    @Test
    void forceRefreshRejectsOfficialRepositoryManifestThatIsNotExactlyFiveHundredProblemsWithoutReplacingCache()
            throws IOException {
        FakeRemote remote = new FakeRemote("https://example.test/question_bank/official");
        remote.publishProblem(1, problemJson("1", "Cached p1 v1"));

        OfficialRepository fixtureRepository = new OfficialRepository(cacheDir, remote.baseUrl, remote);
        fixtureRepository.forceRefresh().join();

        OfficialRepository officialRepository = new OfficialRepository(cacheDir, remote.baseUrl, remote, true);
        int p1RequestsBefore = remote.requestsFor("p1.json");
        remote.publishProblem(1, problemJson("1", "Rejected short official bank"));

        CompletionException error = assertThrows(
                CompletionException.class,
                () -> officialRepository.forceRefresh().join()
        );
        assertTrue(error.getCause().getMessage().contains("totalProblems must be exactly 500"),
                "production official refresh should require the complete 500-problem bank");

        assertEquals(p1RequestsBefore, remote.requestsFor("p1.json"),
                "official count failures should stop at manifest validation before downloading problem bodies");
        assertTrue(officialRepository.getProblems().isEmpty(),
                "production official refresh must not publish an old partial cache after rejecting a short remote bank");
        assertTrue(Files.readString(cacheDir.resolve("p1.json"), StandardCharsets.UTF_8).contains("Cached p1 v1"));
        assertFalse(Files.readString(cacheDir.resolve("p1.json"), StandardCharsets.UTF_8)
                .contains("Rejected short official bank"));
        assertNoTemporaryRepositoryDirs();
    }

