    @Test
    void forceRefreshRejectsIntersectionArraysIISetMembershipReferenceSolutionWithoutReplacingCache()
            throws IOException {
        FakeRemote remote = new FakeRemote("https://example.test/question_bank/official");
        remote.publishCompleteProblemBank();
        remote.seedCompleteProblemBankCache(cacheDir);

        OfficialRepository repository = new OfficialRepository(cacheDir, remote.baseUrl, remote, true);
        repository.refresh().join();

        remote.publishProblem(15, intersectionArraysIIProblemJsonWithInvalidFirstSolution(
                "Remote p15 Set membership reference solution",
                "## Approach\\n\\nInsert the first array into a HashSet, then add each second-array value that appears in the set.\\n\\n"
                        + "## Key Insight\\n\\nThis is intentionally invalid for the official textbook bank because Intersection II must preserve duplicate counts.\\n\\n"
                        + "## Complexity Analysis\\n- Time Complexity: O(m + n)\\n- Space Complexity: O(n)",
                "class Solution { public int[] intersect(int[] nums1, int[] nums2) { java.util.Set<Integer> seen = new java.util.HashSet<>(); for (int num : nums1) { seen.add(num); } java.util.List<Integer> out = new java.util.ArrayList<>(); for (int num : nums2) { if (seen.contains(num)) { out.add(num); } } return out.stream().mapToInt(Integer::intValue).toArray(); } }"));
        remote.publishTranslation("zh_cn", 15, chineseTranslationWithSolutions("杩滅▼棰樼洰", 5));

        CompletionException error = assertThrows(CompletionException.class, () -> repository.forceRefresh().join());
        assertTrue(error.getCause().getMessage().contains("p15.json")
                        && error.getCause().getMessage().contains("Set-only membership"),
                "failure should identify p15 reference solutions that collapse duplicate counts");

        assertEquals(RemoteRepositoryDownloader.OFFICIAL_PROBLEM_COUNT, repository.getProblems().size());
        assertEquals("Complete cached problem 15", repository.getProblems().get(14).getTitle());
        assertTrue(Files.readString(cacheDir.resolve("p15.json"), StandardCharsets.UTF_8)
                .contains("Complete cached problem 15"));
        assertFalse(Files.readString(cacheDir.resolve("p15.json"), StandardCharsets.UTF_8)
                .contains("Remote p15 Set membership reference solution"));
        assertNoTemporaryRepositoryDirs();
    }

