    private void assertRejectedFlattenTreeProblemPreservesCache(
            String remoteTitle, String remoteProblemJson, String expectedMessageFragment) throws IOException {
        FakeRemote remote = new FakeRemote("https://example.test/question_bank/official");
        remote.publishCompleteProblemBank();
        remote.seedCompleteProblemBankCache(cacheDir);

        OfficialRepository repository = new OfficialRepository(cacheDir, remote.baseUrl, remote, true);
        repository.refresh().join();

        remote.publishProblem(100, remoteProblemJson);

        CompletionException error = assertThrows(CompletionException.class, () -> repository.forceRefresh().join());
        String message = error.getCause().getMessage();
        assertTrue(message.contains("Flatten Binary Tree")
                        && message.contains("p100.json")
                        && message.contains(expectedMessageFragment),
                "failure should identify invalid p100 Flatten Binary Tree content before cache replacement; actual: "
                        + message);

        assertEquals(RemoteRepositoryDownloader.OFFICIAL_PROBLEM_COUNT, repository.getProblems().size());
        assertEquals("Complete cached problem 100", repository.getProblems().get(99).getTitle());
        assertTrue(Files.readString(cacheDir.resolve("p100.json"), StandardCharsets.UTF_8)
                .contains("Complete cached problem 100"));
        assertFalse(Files.readString(cacheDir.resolve("p100.json"), StandardCharsets.UTF_8)
                .contains(remoteTitle));
        assertNoTemporaryRepositoryDirs();
    }

