    @Test
    void forceRefreshRejectsOneHundredTwentySeventhReviewedProblemSolutionWithoutKeyInsightWithoutReplacingCache()
            throws IOException {
        FakeRemote remote = new FakeRemote("https://example.test/question_bank/official");
        remote.publishCompleteProblemBank();
        remote.seedCompleteProblemBankCache(cacheDir);

        OfficialRepository repository = new OfficialRepository(cacheDir, remote.baseUrl, remote, true);
        repository.refresh().join();

        remote.publishProblem(127, partitionKProblemJsonWithInvalidFirstSolution(
                "Remote p127 missing reviewed solution section",
                "## Approach\\n\\nReturn true without checking any bucket sums.\\n\\n"
                        + "## Complexity Analysis\\n- Time Complexity: O(1)\\n- Space Complexity: O(1)",
                "class Solution { public boolean canPartitionKSubsets(int[] nums, int k) { return true; } }"));

        CompletionException error = assertThrows(CompletionException.class, () -> repository.forceRefresh().join());
        assertTrue(error.getCause().getMessage().contains("Key Insight")
                        && error.getCause().getMessage().contains("p127.json"),
                "failure should identify the one-hundred-twenty-seventh reviewed problem when its insight section regresses");

        assertEquals(RemoteRepositoryDownloader.OFFICIAL_PROBLEM_COUNT, repository.getProblems().size());
        assertEquals("Complete cached problem 127", repository.getProblems().get(126).getTitle());
        assertTrue(Files.readString(cacheDir.resolve("p127.json"), StandardCharsets.UTF_8)
                .contains("Complete cached problem 127"));
        assertFalse(Files.readString(cacheDir.resolve("p127.json"), StandardCharsets.UTF_8)
                .contains("Remote p127 missing reviewed solution section"));
        assertNoTemporaryRepositoryDirs();
    }

