    @Test
    void forceRefreshRejectsRotateImageReplacementMatrixSolutionWithoutReplacingCache()
            throws IOException {
        assertRejectedRotateImageProblemPreservesCache(
                "Remote p188 allocates replacement matrix",
                rotateImageProblemJsonWithInvalidFirstSolution(
                        "Remote p188 allocates replacement matrix",
                        "## Approach\\n\\nCopy every value into a replacement matrix, then copy it back.\\n\\n"
                                + "## Key Insight\\n\\nThis deliberately violates the in-place teaching contract.\\n\\n"
                                + "## Complexity Analysis\\n- Time Complexity: O(n^2)\\n- Space Complexity: O(n^2)",
                        """
                                class Solution {
                                    public void rotate(int[][] matrix) {
                                        int n = matrix.length;
                                        int[][] copy = new int[n][n];
                                        for (int r = 0; r < n; r++) {
                                            for (int c = 0; c < n; c++) {
                                                copy[c][n - 1 - r] = matrix[r][c];
                                            }
                                        }
                                        for (int r = 0; r < n; r++) {
                                            for (int c = 0; c < n; c++) {
                                                matrix[r][c] = copy[r][c];
                                            }
                                        }
                                    }
                                }
                                """),
                "must not allocate a replacement matrix");
    }

