        assertEquals("Complete cached problem 6", repository.getProblems().get(5).getTitle());
        assertTrue(Files.readString(cacheDir.resolve("p6.json"), StandardCharsets.UTF_8)
                .contains("Complete cached problem 6"));
        assertFalse(Files.readString(cacheDir.resolve("p6.json"), StandardCharsets.UTF_8)
                .contains("Remote p6 non-linear reference solution"));
