    @Test
    void concurrentForceRefreshDoesNotReportSuccessBeforeInFlightUpdateFinishes() throws Exception {
        FakeRemote remote = new FakeRemote("https://example.test/question_bank/official");
        remote.publishProblem(1, problemJson("1", "Remote p1"));
        remote.blockOnFile("p1.json");

        OfficialRepository repository = new OfficialRepository(cacheDir, remote.baseUrl, remote);
        CompletableFuture<Void> first = repository.forceRefresh();
        assertTrue(remote.awaitBlockedFileRequest(), "first refresh should reach the blocked problem download");

        CompletableFuture<Void> second = repository.forceRefresh();
        assertThrows(TimeoutException.class, () -> second.get(300, TimeUnit.MILLISECONDS),
                "a concurrent forceRefresh must wait for the in-flight update instead of reporting early success");

        remote.releaseBlockedFileRequest();
        first.get(5, TimeUnit.SECONDS);
        second.get(5, TimeUnit.SECONDS);

        assertEquals(1, repository.getProblems().size());
        assertEquals("Remote p1", repository.getProblems().getFirst().getTitle());
    }

    @Test
    void syncingFlagTracksInFlightForceRefreshAndClearsAfterSuccess() throws Exception {
        FakeRemote remote = new FakeRemote("https://example.test/question_bank/official");
        remote.publishProblem(1, problemJson("1", "Remote p1"));
        remote.blockOnFile("p1.json");

        OfficialRepository repository = new OfficialRepository(cacheDir, remote.baseUrl, remote);
        CompletableFuture<Void> refresh = repository.forceRefresh();
        assertTrue(remote.awaitBlockedFileRequest(), "refresh should reach the blocked problem download");

        assertTrue(repository.isSyncing(), "repository should report syncing while a forced refresh is in flight");
        assertNull(repository.getLastError(), "starting a refresh should clear the previous error");

        remote.releaseBlockedFileRequest();
        refresh.get(5, TimeUnit.SECONDS);

        assertFalse(repository.isSyncing(), "repository should clear syncing after a successful forced refresh");
        assertNull(repository.getLastError(), "successful refresh should leave no last error");
        assertEquals("Remote p1", repository.getProblems().getFirst().getTitle());
    }

    @Test
    void syncingFlagCoversPostDownloadCacheAndTranslationLoad() throws Exception {
        FakeRemote remote = new FakeRemote("https://example.test/question_bank/official");
        remote.publishProblem(1, problemJson("1", "Remote p1"));

        BlockingTranslationLoader translationLoader = new BlockingTranslationLoader();
        OfficialRepository repository = new OfficialRepository(
                cacheDir, remote.baseUrl, remote, false, translationLoader);

        CompletableFuture<Void> refresh = repository.forceRefresh();
        assertTrue(translationLoader.awaitStarted(),
                "refresh should reach the translation loading phase after installing the downloaded cache");

        try {
            assertEquals("Remote p1", repository.getProblems().getFirst().getTitle(),
                    "problem cache should already be loaded before translations finish");
            assertTrue(repository.isSyncing(),
                    "repository should still report syncing while post-download translations are loading");
            assertThrows(TimeoutException.class, () -> refresh.get(300, TimeUnit.MILLISECONDS),
                    "forceRefresh must not complete before post-download translations are loaded");
        } finally {
            translationLoader.release();
        }

        refresh.get(5, TimeUnit.SECONDS);
        assertFalse(repository.isSyncing(), "repository should clear syncing only after translations finish");
        assertNull(repository.getLastError(), "successful refresh should leave no last error");
    }

    @Test
    void failedForceRefreshClearsSyncingAndRecordsLastError() {
        FakeRemote remote = new FakeRemote("https://example.test/question_bank/official");
        remote.publishProblem(1, problemJson("1", "Remote p1"));
        remote.fail = true;

        OfficialRepository repository = new OfficialRepository(cacheDir, remote.baseUrl, remote);

        CompletionException error = assertThrows(CompletionException.class, () -> repository.forceRefresh().join());
        assertTrue(error.getCause().getMessage().contains("offline"),
                "failure should expose the remote fetch error");

        assertFalse(repository.isSyncing(), "repository must not remain stuck in syncing state after failure");
        assertNotNull(repository.getLastError(), "failed refresh should record a last error for UI/status surfaces");
        assertTrue(repository.getLastError().contains("offline"),
                "last error should contain the remote failure detail");
        assertTrue(repository.getProblems().isEmpty(), "failed initial refresh should not fabricate cached problems");
    }

