    @Test
    void officialRemoteUpdatesRemainExplicitUserActions() throws IOException {
        Path sourceRoot = Path.of(System.getProperty("user.dir"),
                "src", "main", "java", "com", "crabmods", "algocraft");
        String modEntry = Files.readString(sourceRoot.resolve("AlgoCraft.java"), StandardCharsets.UTF_8);
        String screen = Files.readString(sourceRoot.resolve(Path.of(
                "client", "gui", "modern", "ModernAlgorithmScreen.java")), StandardCharsets.UTF_8);
        String repository = Files.readString(sourceRoot.resolve(Path.of(
                "logic", "repo", "OfficialRepository.java")), StandardCharsets.UTF_8);

        assertFalse(Files.exists(sourceRoot.resolve(Path.of("logic", "repo", "OfficialRepositorySync.java"))),
                "official repository updates should not have a background periodic sync service");
        assertFalse(modEntry.contains("OfficialRepositorySync"),
                "the mod lifecycle should not start or stop a background official-repository sync service");
        assertTrue(repository.contains("Normal refresh is offline-safe")
                        && repository.contains("only reads the cached official repo"),
                "normal repository refresh should be cache-only; network updates must be explicit");
        assertTrue(screen.contains("beginOfficialUpdate()")
                        && screen.contains("ProblemManager.forceRefreshOfficial()"),
                "the in-game IDE button should remain the explicit path for updating the official repository");
    }

    @Test
    void replaceDirectoryRestoresCacheWhenInstallMoveFails() throws IOException {
        Path parent = Files.createDirectory(cacheDir.resolve("replace-rollback"));
        Path target = parent.resolve("official");
        Files.createDirectories(target);
        Files.writeString(target.resolve("p1.json"), "cached", StandardCharsets.UTF_8);
        Path staging = Files.createTempDirectory(parent, "official.update-");
        Files.writeString(staging.resolve("p1.json"), "new", StandardCharsets.UTF_8);
        Path normalizedStaging = staging.toAbsolutePath().normalize();

        IOException error = assertThrows(IOException.class,
                () -> RemoteRepositoryDownloader.replaceDirectoryForTest(staging, target, (source, destination) -> {
                    if (source.toAbsolutePath().normalize().equals(normalizedStaging)) {
                        throw new IOException("simulated install move failure");
                    }
                    Files.move(source, destination);
                }));

        assertTrue(error.getMessage().contains("simulated install move failure"));
        assertTrue(Files.exists(target.resolve("p1.json")), "cached repository directory should be restored");
        assertEquals("cached", Files.readString(target.resolve("p1.json"), StandardCharsets.UTF_8));
        assertTrue(temporaryRepositoryDirs(parent, "official.backup-").isEmpty(),
                "successful rollback should remove the backup directory");
    }

    @Test
    void replaceDirectoryRestoresCacheWhenInstallMoveFailsAfterCreatingTarget() throws IOException {
        Path parent = Files.createDirectory(cacheDir.resolve("replace-rollback-after-target-created"));
        Path target = parent.resolve("official");
        Files.createDirectories(target);
        Files.writeString(target.resolve("p1.json"), "cached", StandardCharsets.UTF_8);
        Path staging = Files.createTempDirectory(parent, "official.update-");
        Files.writeString(staging.resolve("p1.json"), "new", StandardCharsets.UTF_8);
        Path normalizedStaging = staging.toAbsolutePath().normalize();

        IOException error = assertThrows(IOException.class,
                () -> RemoteRepositoryDownloader.replaceDirectoryForTest(staging, target, (source, destination) -> {
                    Files.move(source, destination);
                    if (source.toAbsolutePath().normalize().equals(normalizedStaging)) {
                        throw new IOException("simulated install move failure after creating target");
                    }
                }));

        assertTrue(error.getMessage().contains("simulated install move failure after creating target"));
        assertTrue(Files.exists(target.resolve("p1.json")),
                "cached repository directory should be restored even if the failed install left a target behind");
        assertEquals("cached", Files.readString(target.resolve("p1.json"), StandardCharsets.UTF_8));
        assertFalse(Files.readString(target.resolve("p1.json"), StandardCharsets.UTF_8).contains("new"),
                "failed install contents must not survive a reported repository update failure");
        assertTrue(temporaryRepositoryDirs(parent, "official.backup-").isEmpty(),
                "successful rollback should remove the backup directory");
    }

    @Test
    void replaceDirectoryPreservesBackupWhenRollbackMoveAlsoFails() throws IOException {
        Path parent = Files.createDirectory(cacheDir.resolve("replace-backup-preserved"));
        Path target = parent.resolve("official");
        Files.createDirectories(target);
        Files.writeString(target.resolve("p1.json"), "cached", StandardCharsets.UTF_8);
        Path staging = Files.createTempDirectory(parent, "official.update-");
        Files.writeString(staging.resolve("p1.json"), "new", StandardCharsets.UTF_8);
        Path normalizedStaging = staging.toAbsolutePath().normalize();

        IOException error = assertThrows(IOException.class,
                () -> RemoteRepositoryDownloader.replaceDirectoryForTest(staging, target, (source, destination) -> {
                    String sourceName = source.getFileName().toString();
                    if (source.toAbsolutePath().normalize().equals(normalizedStaging)) {
                        throw new IOException("simulated install move failure");
                    }
                    if (sourceName.startsWith("official.backup-")) {
                        throw new IOException("simulated rollback move failure");
                    }
                    Files.move(source, destination);
                }));

        assertTrue(error.getMessage().contains("simulated install move failure"));
        assertEquals(1, error.getSuppressed().length,
                "rollback failure should be attached to the original install failure");
        assertTrue(error.getSuppressed()[0].getMessage().contains("simulated rollback move failure"));
        assertFalse(Files.exists(target), "target may be missing when rollback itself fails");

        List<Path> backups = temporaryRepositoryDirs(parent, "official.backup-");
        assertEquals(1, backups.size(), "failed rollback must preserve the backup instead of deleting cached data");
        assertEquals("cached", Files.readString(backups.getFirst().resolve("p1.json"), StandardCharsets.UTF_8));
    }

    private static List<Path> temporaryRepositoryDirs(Path parent, String prefix) throws IOException {
        try (var stream = Files.list(parent)) {
            return stream
                    .filter(path -> path.getFileName().toString().startsWith(prefix))
                    .toList();
        }
    }

    private void assertNoTemporaryRepositoryDirs() throws IOException {
        Path normalizedCacheDir = cacheDir.toAbsolutePath().normalize();
        Path parent = normalizedCacheDir.getParent();
        String cacheName = normalizedCacheDir.getFileName().toString();

        try (var stream = Files.list(parent)) {
            List<Path> leftovers = stream
                    .filter(path -> {
                        String name = path.getFileName().toString();
                        return name.startsWith(cacheName + ".update-") || name.startsWith(cacheName + ".backup-");
                    })
                    .toList();
            assertTrue(leftovers.isEmpty(), "repository update should not leave staging or backup directories: " + leftovers);
        }
    }

    private static final class BlockingTranslationLoader implements OfficialRepository.TranslationLoader {
        private final CountDownLatch started = new CountDownLatch(1);
        private final CountDownLatch release = new CountDownLatch(1);

        @Override
        public void load(Path cacheDir) {
            started.countDown();
            try {
                if (!release.await(5, TimeUnit.SECONDS)) {
                    throw new CompletionException(new TimeoutException("timed out waiting to release translation load"));
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new CompletionException(e);
            }
        }

        boolean awaitStarted() throws InterruptedException {
            return started.await(5, TimeUnit.SECONDS);
        }

        void release() {
            release.countDown();
        }
    }

    private static void deleteRecursively(Path path) throws IOException {
        if (path == null || !Files.exists(path)) {
            return;
        }
        try (var stream = Files.walk(path)) {
            for (Path entry : stream.sorted(Comparator.reverseOrder()).toList()) {
                Files.deleteIfExists(entry);
            }
        }
    }

