    private static String removeElementStableWritePointerSolutionEntryJson() {
        return """
                    {
                      "name": "Stable Write Pointer Fixture",
                      "description": "## Approach\\n\\nScan read from left to right and copy every value not equal to val into nums[write].\\n\\n## Key Insight\\n\\nThe prefix before write is exactly the kept values already seen, so this route preserves order while filtering in place.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int removeElement(int[] nums, int val) { int write = 0; for (int read = 0; read < nums.length; read++) { if (nums[read] != val) { nums[write] = nums[read]; write++; } } return write; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String removeElementTailSwapSolutionEntryJson() {
        return """
                    {
                      "name": "Swap Removed Values with Tail Fixture",
                      "description": "## Approach\\n\\nWhen nums[index] equals val, overwrite it with nums[length - 1] and shrink the active length.\\n\\n## Key Insight\\n\\nThe remaining order may change, so replacing a removed value with an unchecked tail value keeps all work in place.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int removeElement(int[] nums, int val) { int index = 0; int length = nums.length; while (index < length) { if (nums[index] == val) { nums[index] = nums[length - 1]; length--; } else { index++; } } return length; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String removeElementTwoEndPartitionSolutionEntryJson() {
        return """
                    {
                      "name": "Two-End Partition Fixture",
                      "description": "## Approach\\n\\nMove left to a removed value and right to a kept value, then swap those positions until the regions meet.\\n\\n## Key Insight\\n\\nThis is a partition problem: kept values belong before removed values, and their internal order is irrelevant.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int removeElement(int[] nums, int val) { int left = 0; int right = nums.length - 1; while (left <= right) { while (left <= right && nums[left] != val) { left++; } while (left <= right && nums[right] == val) { right--; } if (left < right) { int temp = nums[left]; nums[left] = nums[right]; nums[right] = temp; left++; right--; } } return right + 1; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String removeElementBoundedCountingSolutionEntryJson() {
        return """
                    {
                      "name": "Bounded Value Counting Fixture",
                      "description": "## Approach\\n\\nCount each value in the fixed 0..50 domain except val, then rewrite the prefix from those counts.\\n\\n## Key Insight\\n\\nSince order may change and the value domain is fixed, a constant-size counting table gives a distinct in-place rewrite route.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n + U)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int removeElement(int[] nums, int val) { int[] count = new int[51]; int kept = 0; for (int number : nums) { if (number != val) { count[number]++; kept++; } } int write = 0; for (int number = 0; number <= 50; number++) { while (count[number] > 0) { nums[write] = number; write++; count[number]--; } } return kept; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String removeElementMarkerCompactSolutionEntryJson() {
        return """
                    {
                      "name": "Marker Compact Comparison Fixture",
                      "description": "## Approach\\n\\nMark removed values with a sentinel outside the input range, then compact non-sentinel values.\\n\\n## Key Insight\\n\\nThis fixture is valid enough for comparison but intentionally is not one of the required official teaching routes.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int removeElement(int[] nums, int val) { int marker = Integer.MIN_VALUE; for (int i = 0; i < nums.length; i++) { if (nums[i] == val) { nums[i] = marker; } } int write = 0; for (int number : nums) { if (number != marker) { nums[write] = number; write++; } } return write; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

