    private static String bestTimeStockRunningMinimumSolutionEntryJson() {
        return """
                    {
                      "name": "Running Minimum Fixture",
                      "description": "## Approach\\n\\nScan prices left to right, keep the lowest earlier price, and update the answer with current price minus that minimum.\\n\\n## Key Insight\\n\\nFor a fixed sell day, the best valid buy day is the cheapest earlier day, so one running minimum preserves the buy-before-sell rule.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int maxProfit(int[] prices) { int minPrice = Integer.MAX_VALUE; int maxProfit = 0; for (int price : prices) { if (price < minPrice) { minPrice = price; } else { maxProfit = Math.max(maxProfit, price - minPrice); } } return maxProfit; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String bestTimeStockSuffixMaximumSolutionEntryJson() {
        return """
                    {
                      "name": "Suffix Maximum Fixture",
                      "description": "## Approach\\n\\nBuild maxFuture so each buy day can be paired with the highest later sell price, then scan buy days for the best profit.\\n\\n## Key Insight\\n\\nLooking to the future sell side makes the time-order condition explicit: day buy may only use maxFuture[buy + 1].\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "class Solution { public int maxProfit(int[] prices) { int n = prices.length; if (n < 2) { return 0; } int[] maxFuture = new int[n]; maxFuture[n - 1] = prices[n - 1]; for (int i = n - 2; i >= 0; i--) { maxFuture[i] = Math.max(prices[i], maxFuture[i + 1]); } int best = 0; for (int buy = 0; buy < n - 1; buy++) { best = Math.max(best, maxFuture[buy + 1] - prices[buy]); } return best; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String bestTimeStockKadaneSolutionEntryJson() {
        return """
                    {
                      "name": "Kadane Daily Difference Fixture",
                      "description": "## Approach\\n\\nConvert adjacent prices into daily gains and run Kadane's algorithm to find the best non-negative contiguous gain interval.\\n\\n## Key Insight\\n\\nOne buy/sell transaction maps to one contiguous segment of daily differences, so a negative running segment should be discarded.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int maxProfit(int[] prices) { int maxProfit = 0; int currentProfit = 0; for (int i = 1; i < prices.length; i++) { int dailyGain = prices[i] - prices[i - 1]; currentProfit = Math.max(0, currentProfit + dailyGain); maxProfit = Math.max(maxProfit, currentProfit); } return maxProfit; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String bestTimeStockBruteForceSolutionEntryJson() {
        return """
                    {
                      "name": "Brute Force Pair Fixture",
                      "description": "## Approach\\n\\nEnumerate every buy < sell pair, compute prices[sell] - prices[buy], and keep the largest non-negative profit.\\n\\n## Key Insight\\n\\nThe direct definition is too slow for large inputs, but it is the clearest baseline for the single-transaction constraint.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int maxProfit(int[] prices) { int best = 0; for (int buy = 0; buy < prices.length; buy++) { for (int sell = buy + 1; sell < prices.length; sell++) { int profit = prices[sell] - prices[buy]; best = Math.max(best, profit); } } return best; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

