    private static String longestRepeatingExactWindowSolutionEntryJson() {
        return """
                    {
                      "name": "Exact Max Count Window Fixture",
                      "description": "## Approach\\n\\nMaintain a sliding window with a 26-entry count table and shrink while window length minus the current max count exceeds k.\\n\\n## Key Insight\\n\\nThe highest-frequency letter is the one kept, so every other character in the window is one replacement.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int characterReplacement(String s, int k) { int[] count = new int[26]; int maxCount = 0; int maxLen = 0; int left = 0; for (int right = 0; right < s.length(); right++) { count[s.charAt(right) - 'A']++; maxCount = Math.max(maxCount, count[s.charAt(right) - 'A']); while (right - left + 1 - maxCount > k) { count[s.charAt(left) - 'A']--; left++; } maxLen = Math.max(maxLen, right - left + 1); } return maxLen; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String longestRepeatingStaleWindowSolutionEntryJson() {
        return """
                    {
                      "name": "Stale Max Count Window Fixture",
                      "description": "## Approach\\n\\nUse the optimized no-shrink sliding window where maxCount may be stale and left advances once when the window is too large.\\n\\n## Key Insight\\n\\nA stale maxCount can only preserve a previously attainable length; it does not make the final maximum too small.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int characterReplacement(String s, int k) { int[] count = new int[26]; int maxCount = 0; int left = 0; int maxLen = 0; for (int right = 0; right < s.length(); right++) { count[s.charAt(right) - 'A']++; maxCount = Math.max(maxCount, count[s.charAt(right) - 'A']); if (right - left + 1 - maxCount > k) { count[s.charAt(left) - 'A']--; left++; } maxLen = right - left + 1; } return maxLen; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String longestRepeatingTargetEnumerationSolutionEntryJson() {
        return """
                    {
                      "name": "Target Character Enumeration Fixture",
                      "description": "## Approach\\n\\nEnumerate each target uppercase letter, then keep a sliding window whose non-target count is at most k.\\n\\n## Key Insight\\n\\nOnce the target character is fixed, every non-target character is exactly one required replacement.\\n\\n## Complexity Analysis\\n- Time Complexity: O(26 * n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int characterReplacement(String s, int k) { int answer = 0; for (char target = 'A'; target <= 'Z'; target++) { int left = 0; int replacementsNeeded = 0; for (int right = 0; right < s.length(); right++) { if (s.charAt(right) != target) { replacementsNeeded++; } while (replacementsNeeded > k) { if (s.charAt(left) != target) { replacementsNeeded--; } left++; } answer = Math.max(answer, right - left + 1); } } return answer; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String longestRepeatingBinarySearchSolutionEntryJson() {
        return """
                    {
                      "name": "Binary Search Feasibility Fixture",
                      "description": "## Approach\\n\\nBinary search the answer length and test each fixed-size window with a frequency table.\\n\\n## Key Insight\\n\\nIf a length is feasible, every shorter length is feasible, so the answer length is monotonic.\\n\\n## Complexity Analysis\\n- Time Complexity: O(26 * n log n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int characterReplacement(String s, int k) { int left = 1; int right = s.length(); int answer = 0; while (left <= right) { int mid = left + (right - left) / 2; if (hasValidWindow(s, k, mid)) { answer = mid; left = mid + 1; } else { right = mid - 1; } } return answer; } private boolean hasValidWindow(String s, int k, int length) { int[] count = new int[26]; for (int right = 0; right < s.length(); right++) { count[s.charAt(right) - 'A']++; if (right >= length) { count[s.charAt(right - length) - 'A']--; } if (right >= length - 1) { int maxCount = 0; for (int value : count) { maxCount = Math.max(maxCount, value); } if (length - maxCount <= k) { return true; } } } return false; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

