    private static String permutationInStringMatchCountSolutionEntryJson() {
        return """
                    {
                      "name": "Match Count Window Fixture",
                      "description": "## Approach\\n\\nTrack how many of the 26 character counts currently match between the target and the fixed window.\\n\\n## Key Insight\\n\\nOnly the entering and leaving characters can change equality, so the full vector comparison can be updated incrementally.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public boolean checkInclusion(String s1, String s2) { if (s1.length() > s2.length()) return false; int[] s1Count = new int[26]; int[] s2Count = new int[26]; for (char c : s1.toCharArray()) { s1Count[c - 'a']++; } int matches = 0; int windowSize = s1.length(); for (int i = 0; i < 26; i++) { if (s1Count[i] == 0) matches++; } for (int i = 0; i < s2.length(); i++) { int idx = s2.charAt(i) - 'a'; s2Count[idx]++; if (s2Count[idx] == s1Count[idx]) matches++; else if (s2Count[idx] == s1Count[idx] + 1) matches--; if (i >= windowSize) { idx = s2.charAt(i - windowSize) - 'a'; s2Count[idx]--; if (s2Count[idx] == s1Count[idx]) matches++; else if (s2Count[idx] == s1Count[idx] - 1) matches--; } if (matches == 26) return true; } return false; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String permutationInStringDeficitCountSolutionEntryJson() {
        return """
                    {
                      "name": "Deficit Count Window Fixture",
                      "description": "## Approach\\n\\nStore how many required characters are still missing, decrease the deficit for entering characters, and restore it for leaving characters.\\n\\n## Key Insight\\n\\nWhen the missing counter reaches zero in a fixed-size window, every required character from s1 has been paid off.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public boolean checkInclusion(String s1, String s2) { if (s1.length() > s2.length()) return false; int[] need = new int[26]; for (int i = 0; i < s1.length(); i++) { need[s1.charAt(i) - 'a']++; } int missing = s1.length(); int windowSize = s1.length(); for (int right = 0; right < s2.length(); right++) { int in = s2.charAt(right) - 'a'; if (need[in] > 0) { missing--; } need[in]--; if (right >= windowSize) { int out = s2.charAt(right - windowSize) - 'a'; need[out]++; if (need[out] > 0) { missing++; } } if (missing == 0) { return true; } } return false; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

