    private static String minimumWindowHashMapFormedSolutionEntryJson() {
        return """
                    {
                      "name": "HashMap Formed Window Fixture",
                      "description": "## Approach\\n\\nTrack required counts in a HashMap, expand the right edge, and shrink while formed equals required.\\n\\n## Key Insight\\n\\nA minimum window is valid only when every distinct requirement has reached its exact needed count, including duplicates.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m + n)\\n- Space Complexity: O(k)",
                      "code": "import java.util.*; class Solution { public String minWindow(String s, String t) { Map<Character, Integer> need = new HashMap<>(); for (char ch : t.toCharArray()) { need.put(ch, need.getOrDefault(ch, 0) + 1); } Map<Character, Integer> window = new HashMap<>(); int required = need.size(); int formed = 0; int bestLength = Integer.MAX_VALUE; int bestStart = 0; int left = 0; for (int right = 0; right < s.length(); right++) { char ch = s.charAt(right); window.put(ch, window.getOrDefault(ch, 0) + 1); if (need.containsKey(ch) && window.get(ch).intValue() == need.get(ch).intValue()) formed++; while (formed == required) { if (right - left + 1 < bestLength) { bestLength = right - left + 1; bestStart = left; } char out = s.charAt(left); window.put(out, window.get(out) - 1); if (need.containsKey(out) && window.get(out) < need.get(out)) formed--; left++; } } return bestLength == Integer.MAX_VALUE ? \\\"\\\" : s.substring(bestStart, bestStart + bestLength); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String minimumWindowDeficitArraySolutionEntryJson() {
        return """
                    {
                      "name": "Deficit Array Window Fixture",
                      "description": "## Approach\\n\\nUse an array of remaining deficits, decrease missing when a useful character enters, and restore it when a needed character leaves.\\n\\n## Key Insight\\n\\nThe missing counter counts required character copies, so duplicate target letters are handled by the same invariant.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m + n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public String minWindow(String s, String t) { int[] need = new int[128]; for (char ch : t.toCharArray()) { need[ch]++; } int missing = t.length(); int bestLength = Integer.MAX_VALUE; int bestStart = 0; int left = 0; for (int right = 0; right < s.length(); right++) { char in = s.charAt(right); if (need[in] > 0) { missing--; } need[in]--; while (missing == 0) { if (right - left + 1 < bestLength) { bestLength = right - left + 1; bestStart = left; } char out = s.charAt(left); need[out]++; if (need[out] > 0) { missing++; } left++; } } return bestLength == Integer.MAX_VALUE ? \\\"\\\" : s.substring(bestStart, bestStart + bestLength); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String minimumWindowFilteredSolutionEntryJson() {
        return """
                    {
                      "name": "Filtered Window Fixture",
                      "description": "## Approach\\n\\nBuild a filtered list of relevant characters with original indices, then run the normal formed-count window over that shorter list.\\n\\n## Key Insight\\n\\nIrrelevant characters cannot satisfy the target, but the filtered entries keep original indices so the returned substring remains exact.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m + n)\\n- Space Complexity: O(m + k)",
                      "code": "import java.util.*; class Solution { public String minWindow(String s, String t) { Map<Character, Integer> need = new HashMap<>(); for (char ch : t.toCharArray()) { need.put(ch, need.getOrDefault(ch, 0) + 1); } List<int[]> filtered = new ArrayList<>(); for (int i = 0; i < s.length(); i++) { char ch = s.charAt(i); if (need.containsKey(ch)) { filtered.add(new int[] {i, ch}); } } Map<Character, Integer> window = new HashMap<>(); int formed = 0; int required = need.size(); int bestLength = Integer.MAX_VALUE; int bestStart = 0; int left = 0; for (int right = 0; right < filtered.size(); right++) { char ch = (char) filtered.get(right)[1]; window.put(ch, window.getOrDefault(ch, 0) + 1); if (window.get(ch).intValue() == need.get(ch).intValue()) formed++; while (formed == required) { int start = filtered.get(left)[0]; int end = filtered.get(right)[0]; if (end - start + 1 < bestLength) { bestLength = end - start + 1; bestStart = start; } char out = (char) filtered.get(left)[1]; window.put(out, window.get(out) - 1); if (window.get(out) < need.get(out)) formed--; left++; } } return bestLength == Integer.MAX_VALUE ? \\\"\\\" : s.substring(bestStart, bestStart + bestLength); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String minimumWindowBinarySearchSolutionEntryJson() {
        return """
                    {
                      "name": "Binary Search Feasibility Fixture",
                      "description": "## Approach\\n\\nBinary search the answer length and call a fixed-window feasibility scan for each candidate length.\\n\\n## Key Insight\\n\\nIf some length works, a longer superwindow can also cover the same target counts, so feasibility by length is monotonic.\\n\\n## Complexity Analysis\\n- Time Complexity: O((m + n) log m)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public String minWindow(String s, String t) { int low = t.length(); int high = s.length(); int bestLength = -1; while (low <= high) { int mid = low + (high - low) / 2; if (findWindowOfLength(s, t, mid) != -1) { bestLength = mid; high = mid - 1; } else { low = mid + 1; } } if (bestLength == -1) return \\\"\\\"; int start = findWindowOfLength(s, t, bestLength); return s.substring(start, start + bestLength); } private int findWindowOfLength(String s, String t, int length) { int[] need = new int[128]; for (char ch : t.toCharArray()) { need[ch]++; } int missing = t.length(); for (int right = 0; right < s.length(); right++) { char in = s.charAt(right); if (need[in] > 0) missing--; need[in]--; if (right >= length) { char out = s.charAt(right - length); need[out]++; if (need[out] > 0) missing++; } if (right >= length - 1 && missing == 0) return right - length + 1; } return -1; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

