    private static String slidingWindowMaximumMonotonicDequeSolutionEntryJson() {
        return """
                    {
                      "name": "Monotonic Deque Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(k)",
                      "description": "## Approach\\n\\nKeep indices in a deque whose values decrease from front to back, expiring old indices and removing dominated tail values before appending the current index.\\n\\n## Key Insight\\n\\nThe deque front is always the current window maximum because smaller older values are dominated by newer larger or equal values.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(k)",
                      "code": "import java.util.*; class Solution { public int[] maxSlidingWindow(int[] nums, int k) { int n = nums.length; int[] result = new int[n - k + 1]; Deque<Integer> deque = new ArrayDeque<>(); for (int right = 0; right < n; right++) { while (!deque.isEmpty() && deque.peekFirst() <= right - k) deque.pollFirst(); while (!deque.isEmpty() && nums[deque.peekLast()] <= nums[right]) deque.pollLast(); deque.offerLast(right); if (right >= k - 1) result[right - k + 1] = nums[deque.peekFirst()]; } return result; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String slidingWindowMaximumLazyHeapSolutionEntryJson() {
        return """
                    {
                      "name": "Lazy Max Heap Fixture",
                      "timeComplexity": "O(n log n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nPush value/index pairs into a max heap and lazily discard stale entries from the top before reporting each full window.\\n\\n## Key Insight\\n\\nA stale entry only matters when it reaches the top, so delayed cleanup keeps the heap route simple.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public int[] maxSlidingWindow(int[] nums, int k) { int n = nums.length; int[] result = new int[n - k + 1]; PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> { if (a[0] != b[0]) return Integer.compare(b[0], a[0]); return Integer.compare(b[1], a[1]); }); for (int right = 0; right < n; right++) { heap.offer(new int[] {nums[right], right}); while (heap.peek()[1] <= right - k) heap.poll(); if (right >= k - 1) result[right - k + 1] = heap.peek()[0]; } return result; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String slidingWindowMaximumBlockDecompositionSolutionEntryJson() {
        return """
                    {
                      "name": "Block Decomposition Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nPrecompute leftMax and rightMax inside blocks of length k, then answer each window by combining the suffix and prefix maxima.\\n\\n## Key Insight\\n\\nEvery window crosses at most one block boundary, so two precomputed values cover the whole range.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "class Solution { public int[] maxSlidingWindow(int[] nums, int k) { int n = nums.length; int[] leftMax = new int[n]; int[] rightMax = new int[n]; for (int i = 0; i < n; i++) { if (i % k == 0) leftMax[i] = nums[i]; else leftMax[i] = Math.max(leftMax[i - 1], nums[i]); int j = n - 1 - i; if (j == n - 1 || (j + 1) % k == 0) rightMax[j] = nums[j]; else rightMax[j] = Math.max(rightMax[j + 1], nums[j]); } int[] result = new int[n - k + 1]; for (int start = 0; start <= n - k; start++) { int end = start + k - 1; result[start] = Math.max(rightMax[start], leftMax[end]); } return result; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String slidingWindowMaximumTreeMapMultisetSolutionEntryJson() {
        return """
                    {
                      "name": "TreeMap Multiset Fixture",
                      "timeComplexity": "O(n log k)",
                      "spaceComplexity": "O(k)",
                      "description": "## Approach\\n\\nMaintain value counts in a TreeMap, insert the entering value, remove one copy of the leaving value, and read lastKey as the current maximum.\\n\\n## Key Insight\\n\\nA counted multiset handles duplicate maxima correctly because removing one occurrence leaves other equal maxima in place.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log k)\\n- Space Complexity: O(k)",
                      "code": "import java.util.*; class Solution { public int[] maxSlidingWindow(int[] nums, int k) { int n = nums.length; int[] result = new int[n - k + 1]; TreeMap<Integer, Integer> counts = new TreeMap<>(); for (int right = 0; right < n; right++) { counts.merge(nums[right], 1, Integer::sum); if (right >= k) removeOne(counts, nums[right - k]); if (right >= k - 1) result[right - k + 1] = counts.lastKey(); } return result; } private void removeOne(TreeMap<Integer, Integer> counts, int value) { int nextCount = counts.get(value) - 1; if (nextCount == 0) counts.remove(value); else counts.put(value, nextCount); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

