    private static String minimumSizeSubarraySumSlidingWindowSolutionEntryJson() {
        return """
                    {
                      "name": "Positive Sliding Window Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nExpand the right pointer to increase the running sum, then shrink from the left while the positive-number window remains valid.\\n\\n## Key Insight\\n\\nPositive values make the window monotonic: adding right only increases the sum and removing left only decreases it.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int minSubArrayLen(int target, int[] nums) { int best = Integer.MAX_VALUE; long sum = 0; int left = 0; for (int right = 0; right < nums.length; right++) { sum += nums[right]; while (sum >= target) { best = Math.min(best, right - left + 1); sum -= nums[left]; left++; } } return best == Integer.MAX_VALUE ? 0 : best; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String minimumSizeSubarraySumPrefixLowerBoundSolutionEntryJson() {
        return """
                    {
                      "name": "Prefix Lower Bound Fixture",
                      "timeComplexity": "O(n log n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nBuild increasing prefix sums, then for each start binary-search the first endpoint whose prefix difference reaches target.\\n\\n## Key Insight\\n\\nPositive values make prefix sums strictly increasing, so every start has a lower-bound search space.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                      "code": "class Solution { public int minSubArrayLen(int target, int[] nums) { int n = nums.length; long[] prefix = new long[n + 1]; for (int i = 0; i < n; i++) { prefix[i + 1] = prefix[i] + nums[i]; } int best = Integer.MAX_VALUE; for (int start = 0; start < n; start++) { long needed = prefix[start] + target; int end = lowerBound(prefix, needed); if (end <= n) best = Math.min(best, end - start); } return best == Integer.MAX_VALUE ? 0 : best; } private int lowerBound(long[] prefix, long target) { int left = 0; int right = prefix.length; while (left < right) { int mid = left + (right - left) / 2; if (prefix[mid] >= target) right = mid; else left = mid + 1; } return left; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String minimumSizeSubarraySumAnswerLengthSolutionEntryJson() {
        return """
                    {
                      "name": "Answer Length Binary Search Fixture",
                      "timeComplexity": "O(n log n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nBinary-search the candidate subarray length and scan fixed-length windows to decide whether that length can reach target.\\n\\n## Key Insight\\n\\nIf one positive-number window length works, longer lengths can also work, so feasibility is monotonic.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int minSubArrayLen(int target, int[] nums) { int left = 1; int right = nums.length; int answer = 0; while (left <= right) { int length = left + (right - left) / 2; if (hasWindowAtLeast(target, nums, length)) { answer = length; right = length - 1; } else { left = length + 1; } } return answer; } private boolean hasWindowAtLeast(int target, int[] nums, int length) { long sum = 0; for (int right = 0; right < nums.length; right++) { sum += nums[right]; if (right >= length) sum -= nums[right - length]; if (right >= length - 1 && sum >= target) return true; } return false; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String minimumSizeSubarraySumQuadraticBaselineSolutionEntryJson() {
        return """
                    {
                      "name": "Quadratic Running Sum Baseline Fixture",
                      "timeComplexity": "O(n^2)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nTry every start index, extend the end index with a running sum, and stop that start as soon as it reaches target.\\n\\n## Key Insight\\n\\nThis slower baseline directly enumerates contiguous subarrays and anchors the correctness discussion before optimization.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int minSubArrayLen(int target, int[] nums) { int best = Integer.MAX_VALUE; for (int start = 0; start < nums.length; start++) { long sum = 0; for (int end = start; end < nums.length; end++) { sum += nums[end]; if (sum >= target) { best = Math.min(best, end - start + 1); break; } } } return best == Integer.MAX_VALUE ? 0 : best; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

