    private static String longestSubstringKDistinctHashMapSolutionEntryJson() {
        return """
                    {
                      "name": "HashMap Count Window Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(k)",
                      "description": "## Approach\\n\\nMaintain counts in a HashMap while expanding right and shrinking left whenever the map has more than k distinct keys.\\n\\n## Key Insight\\n\\nThe HashMap key count is exactly the current distinct-character count, so count.size() <= k is the window invariant.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(k)",
                      "code": "import java.util.*; class Solution { public int lengthOfLongestSubstringKDistinct(String s, int k) { if (k == 0 || s.isEmpty()) return 0; Map<Character, Integer> count = new HashMap<>(); int best = 0; int left = 0; for (int right = 0; right < s.length(); right++) { char ch = s.charAt(right); count.put(ch, count.getOrDefault(ch, 0) + 1); while (count.size() > k) { char outgoing = s.charAt(left); int next = count.get(outgoing) - 1; if (next == 0) count.remove(outgoing); else count.put(outgoing, next); left++; } best = Math.max(best, right - left + 1); } return best; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String longestSubstringKDistinctAsciiArraySolutionEntryJson() {
        return """
                    {
                      "name": "ASCII Count Array Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nUse a fixed ASCII count array and a distinct counter, then shrink while distinct exceeds k.\\n\\n## Key Insight\\n\\nThe array route teaches the same invariant as the HashMap route, specialized to a known character universe.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int lengthOfLongestSubstringKDistinct(String s, int k) { if (k == 0 || s.isEmpty()) return 0; int[] count = new int[128]; int distinct = 0; int best = 0; int left = 0; for (int right = 0; right < s.length(); right++) { char ch = s.charAt(right); if (count[ch] == 0) distinct++; count[ch]++; while (distinct > k) { char outgoing = s.charAt(left); count[outgoing]--; if (count[outgoing] == 0) distinct--; left++; } best = Math.max(best, right - left + 1); } return best; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String longestSubstringKDistinctOrderedEvictionSolutionEntryJson() {
        return """
                    {
                      "name": "Last Seen Ordered Eviction Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(k)",
                      "description": "## Approach\\n\\nRecord last-seen positions in an access-ordered LinkedHashMap and evict the oldest last-seen character when the map grows past k.\\n\\n## Key Insight\\n\\nInstead of shrinking one character at a time, the ordered-eviction route jumps left beyond the character that must leave.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(k)",
                      "code": "import java.util.*; class Solution { public int lengthOfLongestSubstringKDistinct(String s, int k) { if (k == 0 || s.isEmpty()) return 0; LinkedHashMap<Character, Integer> lastSeen = new LinkedHashMap<>(16, 0.75f, true); int left = 0; int best = 0; for (int right = 0; right < s.length(); right++) { char ch = s.charAt(right); lastSeen.put(ch, right); if (lastSeen.size() > k) { Iterator<Map.Entry<Character, Integer>> iterator = lastSeen.entrySet().iterator(); Map.Entry<Character, Integer> oldest = iterator.next(); left = oldest.getValue() + 1; iterator.remove(); } best = Math.max(best, right - left + 1); } return best; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

