    private static String fruitIntoBasketsHashMapSolutionEntryJson() {
        return """
                    {
                      "name": "HashMap Count Window Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nMaintain fruit counts in a HashMap while expanding right and shrinking left whenever the map has more than two keys.\\n\\n## Key Insight\\n\\nThe HashMap key count is exactly the number of basket types currently in use, while counts tell when a type can leave.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "import java.util.*; class Solution { public int totalFruit(int[] fruits) { Map<Integer, Integer> count = new HashMap<>(); int left = 0; int best = 0; for (int right = 0; right < fruits.length; right++) { int fruit = fruits[right]; count.put(fruit, count.getOrDefault(fruit, 0) + 1); while (count.size() > 2) { int outgoing = fruits[left]; int next = count.get(outgoing) - 1; if (next == 0) count.remove(outgoing); else count.put(outgoing, next); left++; } best = Math.max(best, right - left + 1); } return best; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String fruitIntoBasketsBoundedArraySolutionEntryJson() {
        return """
                    {
                      "name": "Bounded Count Array Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nUse the prompt's bounded fruit ids as indexes in a count array, maintain distinct, and shrink while distinct exceeds two.\\n\\n## Key Insight\\n\\nThis teaches the same sliding-window invariant as the HashMap route while making the value-range tradeoff explicit.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "class Solution { public int totalFruit(int[] fruits) { if (fruits.length == 0) return 0; int[] count = new int[fruits.length]; int distinct = 0; int left = 0; int best = 0; for (int right = 0; right < fruits.length; right++) { int fruit = fruits[right]; if (count[fruit] == 0) distinct++; count[fruit]++; while (distinct > 2) { int outgoing = fruits[left]; count[outgoing]--; if (count[outgoing] == 0) distinct--; left++; } best = Math.max(best, right - left + 1); } return best; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String fruitIntoBasketsLastSeenSolutionEntryJson() {
        return """
                    {
                      "name": "Last Seen Eviction Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nRecord the last seen index for each fruit type and evict the type whose last index is farthest left when a third type appears.\\n\\n## Key Insight\\n\\nThe earliest last-seen type cannot remain in any valid window ending at the current tree, so left can jump past it.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "import java.util.*; class Solution { public int totalFruit(int[] fruits) { Map<Integer, Integer> lastSeen = new HashMap<>(); int left = 0; int best = 0; for (int right = 0; right < fruits.length; right++) { lastSeen.put(fruits[right], right); if (lastSeen.size() > 2) { int earliestIndex = fruits.length; int typeToRemove = -1; for (Map.Entry<Integer, Integer> entry : lastSeen.entrySet()) { if (entry.getValue() < earliestIndex) { earliestIndex = entry.getValue(); typeToRemove = entry.getKey(); } } lastSeen.remove(typeToRemove); left = earliestIndex + 1; } best = Math.max(best, right - left + 1); } return best; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String fruitIntoBasketsLastRunSolutionEntryJson() {
        return """
                    {
                      "name": "Last Run Constant Space Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nTrack the two active fruit types, the current window length, and the length of the final run of the newest type.\\n\\n## Key Insight\\n\\nWhen a third type arrives, the only reusable part of the old window is the final run, so the new window is lastRunLength + 1.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int totalFruit(int[] fruits) { int lastType = -1; int secondLastType = -1; int lastRunLength = 0; int currentWindow = 0; int best = 0; for (int fruit : fruits) { if (fruit == lastType || fruit == secondLastType) currentWindow++; else currentWindow = lastRunLength + 1; if (fruit == lastType) lastRunLength++; else { secondLastType = lastType; lastType = fruit; lastRunLength = 1; } best = Math.max(best, currentWindow); } return best; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String fruitIntoBasketsQuadraticBaselineSolutionEntryJson() {
        return """
                    {
                      "name": "Quadratic Distinct Type Baseline Fixture",
                      "timeComplexity": "O(n^2)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nTry every start index, extend right with a set of fruit types, and stop the start when a third type appears.\\n\\n## Key Insight\\n\\nThis baseline follows the prompt literally and anchors why the optimized routes preserve the same answer.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2)\\n- Space Complexity: O(1)",
                      "code": "import java.util.*; class Solution { public int totalFruit(int[] fruits) { int best = 0; for (int start = 0; start < fruits.length; start++) { Set<Integer> types = new HashSet<>(); for (int end = start; end < fruits.length; end++) { types.add(fruits[end]); if (types.size() > 2) break; best = Math.max(best, end - start + 1); } } return best; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

