    private static String validParenthesesBracketMapStackSolutionEntryJson() {
        return """
                    {
                      "name": "Bracket Map Stack Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nPush openers, use a Map from closer to required opener, and compare every closer against the stack top.\\n\\n## Key Insight\\n\\nThe stack stores the most recent unmatched opener, and the map makes bracket type matching explicit.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public boolean isValid(String s) { Deque<Character> stack = new ArrayDeque<>(); Map<Character, Character> pairs = new HashMap<>(); pairs.put(')', '('); pairs.put(']', '['); pairs.put('}', '{'); for (char c : s.toCharArray()) { if (pairs.containsKey(c)) { if (stack.isEmpty() || stack.pop() != pairs.get(c)) return false; } else stack.push(c); } return stack.isEmpty(); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String validParenthesesExpectedCloserStackSolutionEntryJson() {
        return """
                    {
                      "name": "Expected Closer Stack Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nPush the exact closer that each opener requires, then compare every closing bracket against the expected stack top.\\n\\n## Key Insight\\n\\nThe stack can represent future obligations instead of past openers, turning matching into equality.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public boolean isValid(String s) { Deque<Character> stack = new ArrayDeque<>(); for (char c : s.toCharArray()) { if (c == '(') stack.push(')'); else if (c == '[') stack.push(']'); else if (c == '{') stack.push('}'); else if (stack.isEmpty() || stack.pop() != c) return false; } return stack.isEmpty(); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String validParenthesesManualArrayStackSolutionEntryJson() {
        return """
                    {
                      "name": "Manual Array Stack Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nUse a char array plus a top pointer, push openers, and pop/check each closer manually.\\n\\n## Key Insight\\n\\nThis teaches that a stack is a contiguous buffer and an index, not magic library behavior.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "class Solution { public boolean isValid(String s) { char[] stack = new char[s.length()]; int top = -1; for (int i = 0; i < s.length(); i++) { char c = s.charAt(i); if (c == '(' || c == '[' || c == '{') stack[++top] = c; else { if (top < 0) return false; char open = stack[top--]; if ((c == ')' && open != '(') || (c == ']' && open != '[') || (c == '}' && open != '{')) return false; } } return top == -1; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String validParenthesesRecursiveParserSolutionEntryJson() {
        return """
                    {
                      "name": "Recursive Grammar Parser Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nRecursively parse each opener's nested sequence until its required closer appears.\\n\\n## Key Insight\\n\\nBalanced brackets form a grammar, and recursive calls store the pending closing tokens.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "class Solution { private String s; private int index; public boolean isValid(String s) { this.s = s; this.index = 0; return parseUntil('\\\\0') && index == s.length(); } private boolean parseUntil(char expected) { while (index < s.length()) { char c = s.charAt(index); if (c == ')' || c == ']' || c == '}') { if (expected != '\\\\0' && c == expected) { index++; return true; } return false; } char close = matchingClose(c); if (close == '\\\\0') return false; index++; if (!parseUntil(close)) return false; } return expected == '\\\\0'; } private char matchingClose(char c) { if (c == '(') return ')'; if (c == '[') return ']'; if (c == '{') return '}'; return '\\\\0'; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

