    private static String reversePolishStandardOperandStackSolutionEntryJson() {
        return """
                    {
                      "name": "Standard Operand Stack Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nPush numbers and pop right then left operands whenever an operator appears.\\n\\n## Key Insight\\n\\nThe stack stores completed subexpression values, and operand order must be preserved for subtraction and division.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public int evalRPN(String[] tokens) { Deque<Integer> stack = new ArrayDeque<>(); for (String token : tokens) { if (isOperator(token)) { int b = stack.pop(); int a = stack.pop(); stack.push(calculate(a, b, token)); } else { stack.push(Integer.parseInt(token)); } } return stack.pop(); } private boolean isOperator(String token) { return token.equals(\\"+\\") || token.equals(\\"-\\") || token.equals(\\"*\\") || token.equals(\\"/\\"); } private int calculate(int a, int b, String op) { switch (op) { case \\"+\\": return a + b; case \\"-\\": return a - b; case \\"*\\": return a * b; case \\"/\\": return a / b; default: throw new IllegalArgumentException(op); } } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String reversePolishSwitchExpressionSolutionEntryJson() {
        return """
                    {
                      "name": "Switch Expression Stack Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nUse the same operand stack while dispatching the four operators through a switch expression.\\n\\n## Key Insight\\n\\nKeeping operator dispatch in one switch makes the arithmetic table explicit without changing the stack invariant.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public int evalRPN(String[] tokens) { Deque<Integer> stack = new ArrayDeque<>(); Set<String> ops = Set.of(\\"+\\", \\"-\\", \\"*\\", \\"/\\"); for (String token : tokens) { if (ops.contains(token)) { int b = stack.pop(); int a = stack.pop(); int result = switch (token) { case \\"+\\" -> a + b; case \\"-\\" -> a - b; case \\"*\\" -> a * b; case \\"/\\" -> a / b; default -> throw new IllegalArgumentException(token); }; stack.push(result); } else { stack.push(Integer.parseInt(token)); } } return stack.pop(); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String reversePolishManualArrayStackSolutionEntryJson() {
        return """
                    {
                      "name": "Manual Array Stack Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nUse an int array and a top pointer to implement stack push and pop directly.\\n\\n## Key Insight\\n\\nThe array route exposes stack mechanics and keeps the same right-then-left pop order without boxed Integer objects.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "class Solution { public int evalRPN(String[] tokens) { int[] stack = new int[tokens.length]; int top = -1; for (String token : tokens) { if (isOperator(token)) { int b = stack[top--]; int a = stack[top--]; stack[++top] = apply(a, b, token); } else { stack[++top] = Integer.parseInt(token); } } return stack[top]; } private boolean isOperator(String token) { return token.equals(\\"+\\") || token.equals(\\"-\\") || token.equals(\\"*\\") || token.equals(\\"/\\"); } private int apply(int a, int b, String op) { return switch (op) { case \\"+\\" -> a + b; case \\"-\\" -> a - b; case \\"*\\" -> a * b; case \\"/\\" -> a / b; default -> throw new IllegalArgumentException(op); }; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String reversePolishRecursiveRightScanSolutionEntryJson() {
        return """
                    {
                      "name": "Recursive Right Scan Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nRead tokens from right to left and recursively consume each operator's right and left subexpressions.\\n\\n## Key Insight\\n\\nPostfix notation encodes an expression tree, and the recursive right-scan reconstructs that tree directly.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "class Solution { private int index; public int evalRPN(String[] tokens) { index = tokens.length - 1; return eval(tokens); } private int eval(String[] tokens) { String token = tokens[index--]; if (!isOperator(token)) return Integer.parseInt(token); int right = eval(tokens); int left = eval(tokens); return switch (token) { case \\"+\\" -> left + right; case \\"-\\" -> left - right; case \\"*\\" -> left * right; case \\"/\\" -> left / right; default -> throw new IllegalArgumentException(token); }; } private boolean isOperator(String token) { return token.equals(\\"+\\") || token.equals(\\"-\\") || token.equals(\\"*\\") || token.equals(\\"/\\"); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

