    private static String generateParenthesesOutputJson(int n) {
        List<String> result = new java.util.ArrayList<>();
        generateParenthesesExpected(n, 0, 0, new StringBuilder(), result);
        StringBuilder json = new StringBuilder("[");
        for (int i = 0; i < result.size(); i++) {
            if (i > 0) {
                json.append(',');
            }
            json.append('"').append(result.get(i)).append('"');
        }
        json.append(']');
        return json.toString();
    }

    private static void generateParenthesesExpected(
            int n, int open, int close, StringBuilder path, List<String> result) {
        if (path.length() == 2 * n) {
            result.add(path.toString());
            return;
        }
        if (open < n) {
            path.append('(');
            generateParenthesesExpected(n, open + 1, close, path, result);
            path.deleteCharAt(path.length() - 1);
        }
        if (close < open) {
            path.append(')');
            generateParenthesesExpected(n, open, close + 1, path, result);
            path.deleteCharAt(path.length() - 1);
        }
    }

