    private static String generateParenthesesMutableBacktrackingSolutionEntryJson() {
        return """
                    {
                      "name": "Mutable StringBuilder Backtracking Fixture",
                      "timeComplexity": "O(Cn * n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nBuild a mutable prefix with open and close counters.\\n\\n## Key Insight\\n\\nThe prefix remains valid only while close is never greater than open.\\n\\n## Complexity Analysis\\n- Time Complexity: O(Cn * n)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public List<String> generateParenthesis(int n) { List<String> result = new ArrayList<>(); backtrack(n, 0, 0, new StringBuilder(), result); return result; } private void backtrack(int n, int open, int close, StringBuilder path, List<String> result) { if (path.length() == 2 * n) { result.add(path.toString()); return; } if (open < n) { path.append('('); backtrack(n, open + 1, close, path, result); path.deleteCharAt(path.length() - 1); } if (close < open) { path.append(')'); backtrack(n, open, close + 1, path, result); path.deleteCharAt(path.length() - 1); } } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String generateParenthesesImmutableBacktrackingSolutionEntryJson() {
        return """
                    {
                      "name": "Immutable String Backtracking Fixture",
                      "timeComplexity": "O(Cn * n)",
                      "spaceComplexity": "O(Cn * n)",
                      "description": "## Approach\\n\\nPass a new immutable string to each recursive branch.\\n\\n## Key Insight\\n\\nThe same prefix-validity search can be represented without mutating shared state.\\n\\n## Complexity Analysis\\n- Time Complexity: O(Cn * n)\\n- Space Complexity: O(Cn * n)",
                      "code": "import java.util.*; class Solution { public List<String> generateParenthesis(int n) { List<String> result = new ArrayList<>(); generate(n, 0, 0, \\"\\", result); return result; } private void generate(int n, int open, int close, String current, List<String> result) { if (current.length() == 2 * n) { result.add(current); return; } if (open < n) { generate(n, open + 1, close, current + \\"(\\", result); } if (close < open) { generate(n, open, close + 1, current + \\")\\", result); } } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String generateParenthesesIterativeStateStackSolutionEntryJson() {
        return """
                    {
                      "name": "Iterative State Stack Fixture",
                      "timeComplexity": "O(Cn * n)",
                      "spaceComplexity": "O(Cn * n)",
                      "description": "## Approach\\n\\nUse an explicit stack of prefix states instead of recursive calls.\\n\\n## Key Insight\\n\\nBacktracking is graph search over prefix states, so the call stack can be replaced by a data structure.\\n\\n## Complexity Analysis\\n- Time Complexity: O(Cn * n)\\n- Space Complexity: O(Cn * n)",
                      "code": "import java.util.*; class Solution { private static class State { final String value; final int open; final int close; State(String value, int open, int close) { this.value = value; this.open = open; this.close = close; } } public List<String> generateParenthesis(int n) { List<String> result = new ArrayList<>(); Deque<State> stack = new ArrayDeque<>(); stack.push(new State(\\"\\", 0, 0)); while (!stack.isEmpty()) { State state = stack.pop(); if (state.value.length() == 2 * n) { result.add(state.value); continue; } if (state.close < state.open) { stack.push(new State(state.value + \\")\\", state.open, state.close + 1)); } if (state.open < n) { stack.push(new State(state.value + \\"(\\", state.open + 1, state.close)); } } return result; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String generateParenthesesCatalanDpSolutionEntryJson() {
        return """
                    {
                      "name": "Catalan Split Dynamic Programming Fixture",
                      "timeComplexity": "O(Cn * n)",
                      "spaceComplexity": "O(Cn * n)",
                      "description": "## Approach\\n\\nBuild dp[pairs] from smaller left and right valid strings around one matching pair.\\n\\n## Key Insight\\n\\nThe first matching close splits every valid string into two smaller valid strings.\\n\\n## Complexity Analysis\\n- Time Complexity: O(Cn * n)\\n- Space Complexity: O(Cn * n)",
                      "code": "import java.util.*; class Solution { public List<String> generateParenthesis(int n) { List<List<String>> dp = new ArrayList<>(); dp.add(Collections.singletonList(\\"\\")); for (int pairs = 1; pairs <= n; pairs++) { List<String> current = new ArrayList<>(); for (int leftPairs = 0; leftPairs < pairs; leftPairs++) { int rightPairs = pairs - 1 - leftPairs; for (String left : dp.get(leftPairs)) { for (String right : dp.get(rightPairs)) { current.add(\\"(\\" + left + \\")\\" + right); } } } dp.add(current); } return dp.get(n); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String generateParenthesesBitmaskBaselineSolutionEntryJson() {
        return """
                    {
                      "name": "Bitmask Generate and Filter Fixture",
                      "timeComplexity": "O(n * 4^n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nEnumerate bitmasks and filter candidates by prefix balance.\\n\\n## Key Insight\\n\\nThis baseline makes the well-formed condition explicit even though it is not the fastest route.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * 4^n)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public List<String> generateParenthesis(int n) { List<String> result = new ArrayList<>(); int length = 2 * n; int limit = 1 << length; for (int mask = 0; mask < limit; mask++) { if (Integer.bitCount(mask) != n) continue; StringBuilder candidate = new StringBuilder(); int balance = 0; boolean valid = true; for (int bit = length - 1; bit >= 0; bit--) { boolean open = ((mask >> bit) & 1) == 1; if (open) { balance++; candidate.append('('); } else { balance--; candidate.append(')'); } if (balance < 0) { valid = false; break; } } if (valid && balance == 0) result.add(candidate.toString()); } return result; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

