    private static String dailyTemperaturesMonotonicStackSolutionEntryJson() {
        return """
                    {
                      "name": "Monotonic Stack Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nUse a monotonic decreasing stack of unresolved day indices.\\n\\n## Key Insight\\n\\nThe first later temperature that is strictly warmer than the stack top is exactly that older day's answer.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public int[] dailyTemperatures(int[] temperatures) { int n = temperatures.length; int[] result = new int[n]; Deque<Integer> stack = new ArrayDeque<>(); for (int i = 0; i < n; i++) { while (!stack.isEmpty() && temperatures[i] > temperatures[stack.peek()]) { int previousIndex = stack.pop(); result[previousIndex] = i - previousIndex; } stack.push(i); } return result; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String dailyTemperaturesRightToLeftJumpingSolutionEntryJson() {
        return """
                    {
                      "name": "Right-to-Left Answer Jumping Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nScan from right to left and jump by already computed waiting times.\\n\\n## Key Insight\\n\\nIf a later day is not warmer, its answer skips a block that cannot help the current day either.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int[] dailyTemperatures(int[] temperatures) { int n = temperatures.length; int[] result = new int[n]; for (int i = n - 2; i >= 0; i--) { int j = i + 1; while (j < n) { if (temperatures[j] > temperatures[i]) { result[i] = j - i; break; } if (result[j] == 0) { break; } j += result[j]; } } return result; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String dailyTemperaturesBoundedLookupSolutionEntryJson() {
        return """
                    {
                      "name": "Bounded Temperature Value Lookup Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nRemember the next index for each temperature value and scan only warmer values.\\n\\n## Key Insight\\n\\nThe temperature range is bounded to 30 through 100, so a fixed-size table can replace a stack.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "import java.util.*; class Solution { public int[] dailyTemperatures(int[] temperatures) { int n = temperatures.length; int[] answer = new int[n]; int[] nextIndex = new int[101]; Arrays.fill(nextIndex, Integer.MAX_VALUE); for (int i = n - 1; i >= 0; i--) { int nearest = Integer.MAX_VALUE; for (int t = temperatures[i] + 1; t <= 100; t++) { nearest = Math.min(nearest, nextIndex[t]); } if (nearest != Integer.MAX_VALUE) { answer[i] = nearest - i; } nextIndex[temperatures[i]] = i; } return answer; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

