    private static String carFleetSortedFrontierSolutionEntryJson() {
        return """
                    {
                      "name": "Sorted Frontier Time Fixture",
                      "timeComplexity": "O(n log n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nSort cars from closest to target to farthest and compare each arrival time with the slowest fleet ahead.\\n\\n## Key Insight\\n\\nA rear car with time less than or equal to the slowest fleet time ahead must merge, including exactly at the target.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public int carFleet(int target, int[] position, int[] speed) { int n = position.length; int[][] cars = new int[n][2]; for (int i = 0; i < n; i++) { cars[i][0] = position[i]; cars[i][1] = speed[i]; } Arrays.sort(cars, (a, b) -> Integer.compare(b[0], a[0])); int fleets = 0; double slowestFleetTime = 0.0; for (int[] car : cars) { double arrivalTime = (double) (target - car[0]) / car[1]; if (arrivalTime > slowestFleetTime) { fleets++; slowestFleetTime = arrivalTime; } } return fleets; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String carFleetArrivalTimeStackSolutionEntryJson() {
        return """
                    {
                      "name": "Arrival-Time Stack Fixture",
                      "timeComplexity": "O(n log n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nSort by descending position and push only the arrival time of each independent fleet.\\n\\n## Key Insight\\n\\nThe stack top is the fleet directly ahead; equal or smaller time means the current car joins that fleet.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public int carFleet(int target, int[] position, int[] speed) { int n = position.length; double[][] cars = new double[n][2]; for (int i = 0; i < n; i++) { cars[i][0] = position[i]; cars[i][1] = (double) (target - position[i]) / speed[i]; } Arrays.sort(cars, (a, b) -> Double.compare(b[0], a[0])); Deque<Double> fleetTimes = new ArrayDeque<>(); for (double[] car : cars) { double arrivalTime = car[1]; if (fleetTimes.isEmpty() || arrivalTime > fleetTimes.peek()) { fleetTimes.push(arrivalTime); } } return fleetTimes.size(); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String carFleetCoordinateBucketSolutionEntryJson() {
        return """
                    {
                      "name": "Coordinate Bucket Fixture",
                      "timeComplexity": "O(target + n)",
                      "spaceComplexity": "O(target)",
                      "description": "## Approach\\n\\nStore each arrival time at its road coordinate and scan coordinates backward from the target.\\n\\n## Key Insight\\n\\nUnique integer positions allow coordinate buckets to replace sorting at the cost of memory proportional to target.\\n\\n## Complexity Analysis\\n- Time Complexity: O(target + n)\\n- Space Complexity: O(target)",
                      "code": "import java.util.*; class Solution { public int carFleet(int target, int[] position, int[] speed) { double[] timeAtPosition = new double[target]; Arrays.fill(timeAtPosition, -1.0); for (int i = 0; i < position.length; i++) { timeAtPosition[position[i]] = (double) (target - position[i]) / speed[i]; } int fleets = 0; double slowestAhead = 0.0; for (int pos = target - 1; pos >= 0; pos--) { double arrivalTime = timeAtPosition[pos]; if (arrivalTime < 0.0) { continue; } if (arrivalTime > slowestAhead) { fleets++; slowestAhead = arrivalTime; } } return fleets; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String carFleetQuadraticBaselineSolutionEntryJson() {
        return """
                    {
                      "name": "Quadratic Ahead-Time Baseline Fixture",
                      "timeComplexity": "O(n^2)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nSort positions ascending and, for each car, recompute the maximum arrival time among all cars ahead.\\n\\n## Key Insight\\n\\nThis baseline shows the invariant that the optimized scan maintains incrementally.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public int carFleet(int target, int[] position, int[] speed) { int n = position.length; double[][] cars = new double[n][2]; for (int i = 0; i < n; i++) { cars[i][0] = position[i]; cars[i][1] = (double) (target - position[i]) / speed[i]; } Arrays.sort(cars, Comparator.comparingDouble(car -> car[0])); int fleets = 0; for (int i = n - 1; i >= 0; i--) { double maxAheadTime = 0.0; for (int j = i + 1; j < n; j++) { maxAheadTime = Math.max(maxAheadTime, cars[j][1]); } if (cars[i][1] > maxAheadTime) { fleets++; } } return fleets; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

