    private static String asteroidCollisionDequeStackSolutionEntryJson() {
        return """
                    {
                      "name": "Deque Stack Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nUse a Deque as a stack of surviving asteroids and resolve collisions against the top.\\n\\n## Key Insight\\n\\nOnly a positive survivor before a negative current asteroid can collide.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public int[] asteroidCollision(int[] asteroids) { Deque<Integer> survivors = new ArrayDeque<>(); for (int asteroid : asteroids) { boolean alive = true; while (alive && asteroid < 0 && !survivors.isEmpty() && survivors.peek() > 0) { int top = survivors.peek(); if (top < -asteroid) { survivors.pop(); } else if (top == -asteroid) { survivors.pop(); alive = false; } else { alive = false; } } if (alive) { survivors.push(asteroid); } } int[] result = new int[survivors.size()]; for (int i = result.length - 1; i >= 0; i--) { result[i] = survivors.pop(); } return result; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String asteroidCollisionInPlaceStackSolutionEntryJson() {
        return """
                    {
                      "name": "In-place Array Stack Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nReuse the input array as the survivor stack and track its logical size.\\n\\n## Key Insight\\n\\nThe stack invariant needs only the processed prefix, so previous slots can store survivors.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "import java.util.*; class Solution { public int[] asteroidCollision(int[] asteroids) { int size = 0; for (int asteroid : asteroids) { boolean alive = true; while (alive && size > 0 && asteroids[size - 1] > 0 && asteroid < 0) { int top = asteroids[size - 1]; if (top < -asteroid) { size--; } else if (top == -asteroid) { size--; alive = false; } else { alive = false; } } if (alive) { asteroids[size] = asteroid; size++; } } return Arrays.copyOf(asteroids, size); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String asteroidCollisionArrayListSolutionEntryJson() {
        return """
                    {
                      "name": "ArrayList Result Stack Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nUse the end of an ArrayList as the stack top while preserving final output order.\\n\\n## Key Insight\\n\\nThe list tail behaves as a stack, and the list body stays in survivor order.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public int[] asteroidCollision(int[] asteroids) { List<Integer> survivors = new ArrayList<>(); for (int asteroid : asteroids) { boolean alive = true; while (alive && !survivors.isEmpty() && survivors.get(survivors.size() - 1) > 0 && asteroid < 0) { int top = survivors.get(survivors.size() - 1); if (top < -asteroid) { survivors.remove(survivors.size() - 1); } else if (top == -asteroid) { survivors.remove(survivors.size() - 1); alive = false; } else { alive = false; } } if (alive) { survivors.add(asteroid); } } return survivors.stream().mapToInt(value -> value).toArray(); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String asteroidCollisionQuadraticBaselineSolutionEntryJson() {
        return """
                    {
                      "name": "Quadratic Adjacent Pass Fixture",
                      "timeComplexity": "O(n^2)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nRepeatedly scan adjacent opposite-moving pairs and build the next survivor list.\\n\\n## Key Insight\\n\\nThe baseline mirrors physical collisions and shows what the stack compresses.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public int[] asteroidCollision(int[] asteroids) { List<Integer> current = new ArrayList<>(); for (int asteroid : asteroids) { current.add(asteroid); } boolean changed = true; while (changed) { changed = false; List<Integer> next = new ArrayList<>(); int i = 0; while (i < current.size()) { if (i + 1 < current.size() && current.get(i) > 0 && current.get(i + 1) < 0) { int left = current.get(i); int right = current.get(i + 1); if (left + right > 0) { next.add(left); } else if (left + right < 0) { next.add(right); } i += 2; changed = true; } else { next.add(current.get(i)); i++; } } current = next; } return current.stream().mapToInt(value -> value).toArray(); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

