    private static String search2DMatrixFlattenedClosedSolutionEntryJson() {
        return """
                    {
                      "name": "Flattened Closed-Interval Fixture",
                      "timeComplexity": "O(log(m*n))",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nRun closed-interval binary search over the matrix as a virtual sorted array.\\n\\n## Key Insight\\n\\nVirtual index mid maps to matrix[mid / cols][mid % cols].\\n\\n## Complexity Analysis\\n- Time Complexity: O(log(m*n))\\n- Space Complexity: O(1)",
                      "code": "class Solution { public boolean searchMatrix(int[][] matrix, int target) { int rows = matrix.length; int cols = matrix[0].length; int left = 0; int right = rows * cols - 1; while (left <= right) { int mid = left + (right - left) / 2; int value = matrix[mid / cols][mid % cols]; if (value == target) { return true; } if (value < target) { left = mid + 1; } else { right = mid - 1; } } return false; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String search2DMatrixFlattenedLowerBoundSolutionEntryJson() {
        return """
                    {
                      "name": "Flattened Lower Bound Fixture",
                      "timeComplexity": "O(log(m*n))",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nFind the first candidate index whose virtual matrix value is at least target.\\n\\n## Key Insight\\n\\nThe lower-bound loop is unchanged except that each comparison maps a virtual index back to the matrix.\\n\\n## Complexity Analysis\\n- Time Complexity: O(log(m*n))\\n- Space Complexity: O(1)",
                      "code": "class Solution { public boolean searchMatrix(int[][] matrix, int target) { int rows = matrix.length; int cols = matrix[0].length; int left = 0; int right = rows * cols; while (left < right) { int mid = left + (right - left) / 2; int value = matrix[mid / cols][mid % cols]; if (value < target) { left = mid + 1; } else { right = mid; } } return left < rows * cols && matrix[left / cols][left % cols] == target; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String search2DMatrixRowSelectionSolutionEntryJson() {
        return """
                    {
                      "name": "Row Selection Then Column Fixture",
                      "timeComplexity": "O(log m + log n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nBinary search the possible row, then binary search within that row.\\n\\n## Key Insight\\n\\nRow selection works because row starts define sorted row ranges.\\n\\n## Complexity Analysis\\n- Time Complexity: O(log m + log n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public boolean searchMatrix(int[][] matrix, int target) { int rows = matrix.length; int cols = matrix[0].length; int top = 0; int bottom = rows - 1; while (top < bottom) { int mid = top + (bottom - top + 1) / 2; if (matrix[mid][0] <= target) { top = mid; } else { bottom = mid - 1; } } int row = top; int left = 0; int right = cols - 1; while (left <= right) { int mid = left + (right - left) / 2; if (matrix[row][mid] == target) { return true; } if (matrix[row][mid] < target) { left = mid + 1; } else { right = mid - 1; } } return false; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String search2DMatrixRecursiveVirtualSolutionEntryJson() {
        return """
                    {
                      "name": "Recursive Virtual Search Fixture",
                      "timeComplexity": "O(log(m*n))",
                      "spaceComplexity": "O(log(m*n))",
                      "description": "## Approach\\n\\nRecurse over the virtual flattened index range and inspect one middle cell per call.\\n\\n## Key Insight\\n\\nThe recursion keeps the same row-major mapping as iterative flattened binary search.\\n\\n## Complexity Analysis\\n- Time Complexity: O(log(m*n))\\n- Space Complexity: O(log(m*n))",
                      "code": "class Solution { public boolean searchMatrix(int[][] matrix, int target) { int rows = matrix.length; int cols = matrix[0].length; return search(matrix, target, cols, 0, rows * cols - 1); } private boolean search(int[][] matrix, int target, int cols, int left, int right) { if (left > right) { return false; } int mid = left + (right - left) / 2; int value = matrix[mid / cols][mid % cols]; if (value == target) { return true; } if (value < target) { return search(matrix, target, cols, mid + 1, right); } return search(matrix, target, cols, left, mid - 1); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String search2DMatrixStaircaseSolutionEntryJson() {
        return """
                    {
                      "name": "Top-Right Staircase Fixture",
                      "timeComplexity": "O(m+n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nStart from the top-right corner and move left or down.\\n\\n## Key Insight\\n\\nThis staircase route is intentionally non-logarithmic for negative remote tests.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m+n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public boolean searchMatrix(int[][] matrix, int target) { int rows = matrix.length; int cols = matrix[0].length; int row = 0; int col = cols - 1; while (row < rows && col >= 0) { if (matrix[row][col] == target) { return true; } if (matrix[row][col] > target) { col--; } else { row++; } } return false; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String search2DMatrixComparisonSolutionEntryJson() {
        return """
                    {
                      "name": "Matrix Linear Scan Fixture",
                      "timeComplexity": "O(m*n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nScan every cell as a structurally different comparison route for negative remote tests.\\n\\n## Key Insight\\n\\nThis fixture is intentionally not one of the required teaching routes, so omission tests isolate one route at a time.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m*n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public boolean searchMatrix(int[][] matrix, int target) { for (int[] row : matrix) { for (int value : row) { if (value == target) { return true; } } } return false; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

