    private static String kokoEatingBananasHalfOpenSolutionEntryJson() {
        return """
                    {
                      "name": "Half-Open Answer Fixture",
                      "timeComplexity": "O(n log M)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nBinary search the speed range with a half-open lower-bound target.\\n\\n## Key Insight\\n\\nFeasible speeds are monotonic, and integer ceiling division computes hours safely.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log M)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int minEatingSpeed(int[] piles, int h) { int left = 1; int right = 0; for (int pile : piles) { right = Math.max(right, pile); } while (left < right) { int speed = left + (right - left) / 2; if (canFinish(piles, h, speed)) { right = speed; } else { left = speed + 1; } } return left; } private boolean canFinish(int[] piles, int h, int speed) { long hours = 0; for (int pile : piles) { hours += (pile + speed - 1L) / speed; } return hours <= h; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String kokoEatingBananasClosedAnswerSolutionEntryJson() {
        return """
                    {
                      "name": "Closed Answer Fixture",
                      "timeComplexity": "O(n log M)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nUse a closed search interval and keep an answer variable for the best feasible speed.\\n\\n## Key Insight\\n\\nWhen mid works, answer is updated before the search removes mid from the interval.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log M)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int minEatingSpeed(int[] piles, int h) { int left = 1; int right = 0; for (int pile : piles) { right = Math.max(right, pile); } int answer = right; while (left <= right) { int speed = left + (right - left) / 2; if (canFinish(piles, h, speed)) { answer = speed; right = speed - 1; } else { left = speed + 1; } } return answer; } private boolean canFinish(int[] piles, int h, int speed) { long hours = 0; for (int pile : piles) { hours += (pile + speed - 1L) / speed; if (hours > h) { return false; } } return true; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String kokoEatingBananasAverageLowerBoundSolutionEntryJson() {
        return """
                    {
                      "name": "Average Lower Bound Fixture",
                      "timeComplexity": "O(n log M)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nStart from the mathematical lower bound ceil(total / h) and stop feasibility checks early.\\n\\n## Key Insight\\n\\nNo speed below the average lower bound can finish, and early stop avoids unnecessary work.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log M)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int minEatingSpeed(int[] piles, int h) { long total = 0; int right = 0; for (int pile : piles) { total += pile; right = Math.max(right, pile); } int left = (int) Math.max(1, (total + h - 1L) / h); while (left < right) { int speed = left + (right - left) / 2; if (canFinish(piles, h, speed)) { right = speed; } else { left = speed + 1; } } return left; } private boolean canFinish(int[] piles, int h, int speed) { long hours = 0; for (int pile : piles) { hours += (pile + speed - 1L) / speed; if (hours > h) { return false; } } return true; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String kokoEatingBananasRecursiveAnswerSolutionEntryJson() {
        return """
                    {
                      "name": "Recursive Answer Fixture",
                      "timeComplexity": "O(n log M)",
                      "spaceComplexity": "O(log M)",
                      "description": "## Approach\\n\\nRecursively lower-bound search the answer space for the minimum feasible speed.\\n\\n## Key Insight\\n\\nThe base case left >= right isolates the smallest feasible speed.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log M)\\n- Space Complexity: O(log M)",
                      "code": "class Solution { public int minEatingSpeed(int[] piles, int h) { int right = 0; for (int pile : piles) { right = Math.max(right, pile); } return search(piles, h, 1, right); } private int search(int[] piles, int h, int left, int right) { if (left >= right) { return left; } int speed = left + (right - left) / 2; if (canFinish(piles, h, speed)) { return search(piles, h, left, speed); } return search(piles, h, speed + 1, right); } private boolean canFinish(int[] piles, int h, int speed) { long hours = 0; for (int pile : piles) { hours += (pile + speed - 1L) / speed; if (hours > h) { return false; } } return true; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

