    private static String searchRotatedSortedArrayOnePassSolutionEntryJson() {
        return """
                    {
                      "name": "One-Pass Rotated Binary Search Fixture",
                      "timeComplexity": "O(log n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nRun one-pass rotated binary search and keep the sorted half whose value range can contain the target.\\n\\n## Key Insight\\n\\nUnique values guarantee that each interval has at least one sorted half, so a normal range test discards half the candidates.\\n\\n## Complexity Analysis\\n- Time Complexity: O(log n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int search(int[] nums, int target) { int left = 0; int right = nums.length - 1; while (left <= right) { int mid = left + (right - left) / 2; if (nums[mid] == target) { return mid; } if (nums[left] <= nums[mid]) { if (nums[left] <= target && target < nums[mid]) { right = mid - 1; } else { left = mid + 1; } } else { if (nums[mid] < target && target <= nums[right]) { left = mid + 1; } else { right = mid - 1; } } } return -1; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String searchRotatedSortedArrayPivotSolutionEntryJson() {
        return """
                    {
                      "name": "Pivot Then Binary Search Fixture",
                      "timeComplexity": "O(log n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nFind the pivot first, choose the physical sorted half that can contain the target, then run ordinary binary search.\\n\\n## Key Insight\\n\\nOnce the rotation point is known, both sides are standard sorted arrays.\\n\\n## Complexity Analysis\\n- Time Complexity: O(log n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int search(int[] nums, int target) { int n = nums.length; int pivot = findPivot(nums); int left; int right; if (pivot == 0 || target < nums[0]) { left = pivot; right = n - 1; } else { left = 0; right = pivot - 1; } while (left <= right) { int mid = left + (right - left) / 2; if (nums[mid] == target) { return mid; } if (nums[mid] < target) { left = mid + 1; } else { right = mid - 1; } } return -1; } private int findPivot(int[] nums) { int left = 0; int right = nums.length - 1; while (left < right) { int mid = left + (right - left) / 2; if (nums[mid] > nums[right]) { left = mid + 1; } else { right = mid; } } return left; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String searchRotatedSortedArrayVirtualSolutionEntryJson() {
        return """
                    {
                      "name": "Virtual Sorted Index Mapping Fixture",
                      "timeComplexity": "O(log n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nFind the pivot, then binary search virtual sorted indices and map each midpoint back to its real rotated index.\\n\\n## Key Insight\\n\\nThe index mapping turns the rotated array into a virtual sorted array without copying values.\\n\\n## Complexity Analysis\\n- Time Complexity: O(log n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int search(int[] nums, int target) { int n = nums.length; int pivot = findPivot(nums); int left = 0; int right = n - 1; while (left <= right) { int mid = left + (right - left) / 2; int real = (pivot + mid) % n; if (nums[real] == target) { return real; } if (nums[real] < target) { left = mid + 1; } else { right = mid - 1; } } return -1; } private int findPivot(int[] nums) { int left = 0; int right = nums.length - 1; while (left < right) { int mid = left + (right - left) / 2; if (nums[mid] > nums[right]) { left = mid + 1; } else { right = mid; } } return left; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String searchRotatedSortedArrayRecursiveSolutionEntryJson() {
        return """
                    {
                      "name": "Recursive Rotated Binary Search Fixture",
                      "timeComplexity": "O(log n)",
                      "spaceComplexity": "O(log n)",
                      "description": "## Approach\\n\\nUse divide-and-conquer recursion with the same sorted-half tests as one-pass rotated binary search.\\n\\n## Key Insight\\n\\nEach recursive call owns the only remaining interval that can still contain the target.\\n\\n## Complexity Analysis\\n- Time Complexity: O(log n)\\n- Space Complexity: O(log n)",
                      "code": "class Solution { public int search(int[] nums, int target) { return search(nums, target, 0, nums.length - 1); } private int search(int[] nums, int target, int left, int right) { if (left > right) { return -1; } int mid = left + (right - left) / 2; if (nums[mid] == target) { return mid; } if (nums[left] <= nums[mid]) { if (nums[left] <= target && target < nums[mid]) { return search(nums, target, left, mid - 1); } return search(nums, target, mid + 1, right); } if (nums[mid] < target && target <= nums[right]) { return search(nums, target, mid + 1, right); } return search(nums, target, left, mid - 1); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

