    private static String splitArrayLargestSumHalfOpenSolutionEntryJson() {
        return """
                    {
                      "name": "Half-Open Answer Binary Search Fixture",
                      "timeComplexity": "O(n log S)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nBinary search the largest allowed subarray sum and greedily count how many groups are needed for each candidate.\\n\\n## Key Insight\\n\\nFeasibility is monotonic, and non-negative values let an at-most-k feasible split be refined into exactly k groups without increasing the maximum group sum.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log S)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int splitArray(int[] nums, int k) { int left = 0; int right = 0; for (int num : nums) { left = Math.max(left, num); right += num; } while (left < right) { int mid = left + (right - left) / 2; if (canSplit(nums, k, mid)) { right = mid; } else { left = mid + 1; } } return left; } private boolean canSplit(int[] nums, int k, int limit) { int groups = 1; int sum = 0; for (int num : nums) { if (sum + num > limit) { groups++; sum = 0; if (groups > k) { return false; } } sum += num; } return true; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String splitArrayLargestSumClosedAnswerSolutionEntryJson() {
        return """
                    {
                      "name": "Closed Interval Answer Variable Fixture",
                      "timeComplexity": "O(n log S)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nSearch a closed answer interval and keep the best feasible largest sum in an explicit answer variable.\\n\\n## Key Insight\\n\\nThe answer variable records a feasible upper bound while the search continues left for a smaller feasible value.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log S)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int splitArray(int[] nums, int k) { int left = 0; int right = 0; for (int num : nums) { left = Math.max(left, num); right += num; } int answer = right; while (left <= right) { int mid = left + (right - left) / 2; int groups = groupsNeeded(nums, mid); if (groups <= k) { answer = mid; right = mid - 1; } else { left = mid + 1; } } return answer; } private int groupsNeeded(int[] nums, int limit) { int groups = 1; int sum = 0; for (int num : nums) { if (sum + num > limit) { groups++; sum = 0; } sum += num; } return groups; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String splitArrayLargestSumBottomUpDpSolutionEntryJson() {
        return """
                    {
                      "name": "Bottom-Up Partition Dynamic Programming Fixture",
                      "timeComplexity": "O(k n^2)",
                      "spaceComplexity": "O(k n)",
                      "description": "## Approach\\n\\nUse dp[i][parts] for the best largest sum when the first i values are split into parts groups, and enumerate the final cut.\\n\\n## Key Insight\\n\\nThe DP route directly models the exact-k partition requirement and teaches the optimal substructure behind the answer.\\n\\n## Complexity Analysis\\n- Time Complexity: O(k n^2)\\n- Space Complexity: O(k n)",
                      "code": "class Solution { public int splitArray(int[] nums, int k) { int n = nums.length; int[] prefix = new int[n + 1]; for (int i = 0; i < n; i++) { prefix[i + 1] = prefix[i] + nums[i]; } int[][] dp = new int[n + 1][k + 1]; for (int[] row : dp) { Arrays.fill(row, Integer.MAX_VALUE); } dp[0][0] = 0; for (int parts = 1; parts <= k; parts++) { for (int i = parts; i <= n; i++) { for (int cut = parts - 1; cut < i; cut++) { if (dp[cut][parts - 1] == Integer.MAX_VALUE) { continue; } int lastSum = prefix[i] - prefix[cut]; dp[i][parts] = Math.min(dp[i][parts], Math.max(dp[cut][parts - 1], lastSum)); } } } return dp[n][k]; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String splitArrayLargestSumTopDownDpSolutionEntryJson() {
        return """
                    {
                      "name": "Top-Down Memoized Partition DP Fixture",
                      "timeComplexity": "O(k n^2)",
                      "spaceComplexity": "O(k n)",
                      "description": "## Approach\\n\\nLet solve(index, parts) choose the first group and recursively solve the remaining suffix, caching each state.\\n\\n## Key Insight\\n\\nChoosing the first cut makes the recurrence easy to teach, and memoization prevents repeated suffix work.\\n\\n## Complexity Analysis\\n- Time Complexity: O(k n^2)\\n- Space Complexity: O(k n)",
                      "code": "class Solution { private int[] nums; private int[] prefix; private int[][] memo; public int splitArray(int[] nums, int k) { this.nums = nums; int n = nums.length; prefix = new int[n + 1]; for (int i = 0; i < n; i++) { prefix[i + 1] = prefix[i] + nums[i]; } memo = new int[n][k + 1]; for (int[] row : memo) { Arrays.fill(row, -1); } return solve(0, k); } private int solve(int index, int parts) { int n = nums.length; if (parts == 1) { return prefix[n] - prefix[index]; } if (memo[index][parts] != -1) { return memo[index][parts]; } int best = Integer.MAX_VALUE; for (int next = index + 1; next <= n - parts + 1; next++) { int firstSum = prefix[next] - prefix[index]; if (firstSum >= best) { break; } int remaining = solve(next, parts - 1); best = Math.min(best, Math.max(firstSum, remaining)); } memo[index][parts] = best; return best; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

