    private static String reorderListMiddleReverseMergeSolutionEntryJson() {
        return """
                    {
                      "name": "Middle Reverse Merge Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nFind the middle, cut the list, reverse the second half, and merge the two halves by alternating nodes.\\n\\n## Key Insight\\n\\nReversing the second half turns the required tail-to-front order into a normal forward traversal.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public void reorderList(ListNode head) { if (head == null || head.next == null) { return; } ListNode slow = head, fast = head; while (fast.next != null && fast.next.next != null) { slow = slow.next; fast = fast.next.next; } ListNode second = slow.next; slow.next = null; ListNode prev = null; while (second != null) { ListNode next = second.next; second.next = prev; prev = second; second = next; } second = prev; ListNode first = head; while (second != null) { ListNode nextFirst = first.next; ListNode nextSecond = second.next; first.next = second; second.next = nextFirst; first = nextFirst; second = nextSecond; } } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String reorderListDequeSolutionEntryJson() {
        return """
                    {
                      "name": "Deque Front/Back Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nPut nodes into a deque, then alternately take from the back and front to rebuild the target order.\\n\\n## Key Insight\\n\\nA deque exposes the farthest remaining tail node and nearest remaining front node at each step.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "class Solution { public void reorderList(ListNode head) { if (head == null) { return; } Deque<ListNode> deque = new ArrayDeque<>(); ListNode curr = head.next; while (curr != null) { deque.addLast(curr); curr = curr.next; } curr = head; boolean fromBack = true; while (!deque.isEmpty()) { ListNode node = fromBack ? deque.pollLast() : deque.pollFirst(); curr.next = node; curr = node; fromBack = !fromBack; } curr.next = null; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String reorderListRecursiveFrontPointerSolutionEntryJson() {
        return """
                    {
                      "name": "Recursive Front Pointer Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nUse recursion to visit tail-side nodes while a front pointer advances from the head.\\n\\n## Key Insight\\n\\nThe call stack supplies nodes from the tail toward the center, matching them with front-side nodes.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "class Solution { private ListNode front; public void reorderList(ListNode head) { front = head; reorderFromTail(head); } private boolean reorderFromTail(ListNode right) { if (right == null) { return true; } if (!reorderFromTail(right.next)) { return false; } if (front == right || front.next == right) { right.next = null; return false; } ListNode nextFront = front.next; front.next = right; right.next = nextFront; front = nextFront; return true; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String reorderListStackSecondHalfSolutionEntryJson() {
        return """
                    {
                      "name": "Stack of Second-Half Nodes Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nFind the middle, push second-half nodes onto a stack, cut the list, and pop nodes into the first half.\\n\\n## Key Insight\\n\\nOnly the second half needs reverse order, and the stack provides that order directly.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "class Solution { public void reorderList(ListNode head) { if (head == null || head.next == null) { return; } ListNode slow = head, fast = head; while (fast != null && fast.next != null) { slow = slow.next; fast = fast.next.next; } Deque<ListNode> stack = new ArrayDeque<>(); ListNode curr = slow.next; slow.next = null; while (curr != null) { stack.push(curr); curr = curr.next; } ListNode first = head; while (!stack.isEmpty()) { ListNode later = stack.pop(); ListNode next = first.next; first.next = later; later.next = next; first = next; } } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

