    private static String addTwoNumbersIterativeSolutionEntryJson() {
        return """
                    {
                      "name": "Iterative Carry Fixture",
                      "timeComplexity": "O(max(m, n))",
                      "spaceComplexity": "O(max(m, n))",
                      "description": "## Approach\\n\\nWalk both lists from head to tail, append sum modulo ten, and carry sum divided by ten into the next column.\\n\\n## Key Insight\\n\\nReverse digit order means the head is the ones digit, so grade-school addition can proceed directly from the list heads.\\n\\n## Complexity Analysis\\n- Time Complexity: O(max(m, n))\\n- Space Complexity: O(max(m, n))",
                      "code": "class Solution { public ListNode addTwoNumbers(ListNode l1, ListNode l2) { ListNode dummy = new ListNode(0); ListNode curr = dummy; int carry = 0; while (l1 != null || l2 != null || carry != 0) { int sum = carry; if (l1 != null) { sum += l1.val; l1 = l1.next; } if (l2 != null) { sum += l2.val; l2 = l2.next; } carry = sum / 10; curr.next = new ListNode(sum % 10); curr = curr.next; } return dummy.next; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String addTwoNumbersRecursiveSolutionEntryJson() {
        return """
                    {
                      "name": "Recursive Carry Fixture",
                      "timeComplexity": "O(max(m, n))",
                      "spaceComplexity": "O(max(m, n))",
                      "description": "## Approach\\n\\nUse a helper that receives both current nodes and the carry, creates one output digit, and recurses to the next digit.\\n\\n## Key Insight\\n\\nThe base case must wait until both lists are exhausted and no carry remains, otherwise a final carry node would be lost.\\n\\n## Complexity Analysis\\n- Time Complexity: O(max(m, n))\\n- Space Complexity: O(max(m, n))",
                      "code": "class Solution { public ListNode addTwoNumbers(ListNode l1, ListNode l2) { return add(l1, l2, 0); } private ListNode add(ListNode l1, ListNode l2, int carry) { if (l1 == null && l2 == null && carry == 0) { return null; } int sum = carry; if (l1 != null) { sum += l1.val; } if (l2 != null) { sum += l2.val; } ListNode node = new ListNode(sum % 10); node.next = add(l1 == null ? null : l1.next, l2 == null ? null : l2.next, sum / 10); return node; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String addTwoNumbersInPlaceSolutionEntryJson() {
        return """
                    {
                      "name": "In-Place Longer List Fixture",
                      "timeComplexity": "O(max(m, n))",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nMeasure both lists, reuse the longer list as result storage, write each digit back, and append only a final carry node when needed.\\n\\n## Key Insight\\n\\nThe output length is at most one more than the longer input, so the longer list can hold all existing result digits.\\n\\n## Complexity Analysis\\n- Time Complexity: O(max(m, n))\\n- Space Complexity: O(1)",
                      "code": "class Solution { public ListNode addTwoNumbers(ListNode l1, ListNode l2) { if (length(l2) > length(l1)) { ListNode temp = l1; l1 = l2; l2 = temp; } ListNode head = l1; ListNode prev = null; int carry = 0; while (l1 != null || l2 != null) { int sum = carry; if (l1 != null) { sum += l1.val; } if (l2 != null) { sum += l2.val; } l1.val = sum % 10; carry = sum / 10; prev = l1; l1 = l1.next; if (l2 != null) { l2 = l2.next; } } if (carry != 0) { prev.next = new ListNode(carry); } return head; } private int length(ListNode node) { int count = 0; while (node != null) { count++; node = node.next; } return count; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String addTwoNumbersDigitBufferSolutionEntryJson() {
        return """
                    {
                      "name": "Digit Buffer Fixture",
                      "timeComplexity": "O(m + n)",
                      "spaceComplexity": "O(m + n)",
                      "description": "## Approach\\n\\nCopy each input list into a digit buffer, add by index with carry, and then build the result list from the computed digits.\\n\\n## Key Insight\\n\\nBuffering separates pointer traversal from arithmetic, making the digit-column model explicit for teaching and debugging.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m + n)\\n- Space Complexity: O(m + n)",
                      "code": "class Solution { public ListNode addTwoNumbers(ListNode l1, ListNode l2) { List<Integer> a = toDigits(l1); List<Integer> b = toDigits(l2); int max = Math.max(a.size(), b.size()); int carry = 0; ListNode dummy = new ListNode(0); ListNode tail = dummy; for (int i = 0; i < max || carry != 0; i++) { int sum = carry; if (i < a.size()) { sum += a.get(i); } if (i < b.size()) { sum += b.get(i); } carry = sum / 10; tail.next = new ListNode(sum % 10); tail = tail.next; } return dummy.next; } private List<Integer> toDigits(ListNode node) { List<Integer> digits = new ArrayList<>(); while (node != null) { digits.add(node.val); node = node.next; } return digits; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

