    private static String findDuplicateNumberFloydSolutionEntryJson() {
        return """
                    {
                      "name": "Floyd Cycle Detection Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nTreat nums as a functional graph and use Floyd cycle detection to find the cycle entrance.\\n\\n## Key Insight\\n\\nThe duplicate value is the graph's cycle entrance, so the route does not modify nums and uses constant extra space.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int findDuplicate(int[] nums) { int slow = nums[0]; int fast = nums[0]; do { slow = nums[slow]; fast = nums[nums[fast]]; } while (slow != fast); slow = nums[0]; while (slow != fast) { slow = nums[slow]; fast = nums[fast]; } return slow; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String findDuplicateNumberValueRangeBinarySolutionEntryJson() {
        return """
                    {
                      "name": "Value Range Binary Search Fixture",
                      "timeComplexity": "O(n log n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nBinary search over candidate values and count how many entries are less than or equal to mid.\\n\\n## Key Insight\\n\\nA count greater than mid means the pigeonhole violation lies in the lower value range, not an index range.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int findDuplicate(int[] nums) { int left = 1; int right = nums.length - 1; while (left < right) { int mid = left + (right - left) / 2; int count = 0; for (int num : nums) { if (num <= mid) { count++; } } if (count > mid) { right = mid; } else { left = mid + 1; } } return left; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String findDuplicateNumberBitCountSolutionEntryJson() {
        return """
                    {
                      "name": "Bit Count Reconstruction Fixture",
                      "timeComplexity": "O(n log n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nFor every bit, compare expected counts from 1..n with actual counts from nums and set the duplicate bit when actual is larger.\\n\\n## Key Insight\\n\\nExtra copies of the duplicate add extra one-bits exactly at the duplicate's set bit positions.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int findDuplicate(int[] nums) { int n = nums.length - 1; int duplicate = 0; for (int bit = 0; bit < 31; bit++) { int mask = 1 << bit; int expected = 0; int actual = 0; for (int value = 1; value <= n; value++) { if ((value & mask) != 0) { expected++; } } for (int num : nums) { if ((num & mask) != 0) { actual++; } } if (actual > expected) { duplicate |= mask; } } return duplicate; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String findDuplicateNumberHashSetSolutionEntryJson() {
        return """
                    {
                      "name": "HashSet Baseline Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nStore seen values in a HashSet and return the first value that cannot be added.\\n\\n## Key Insight\\n\\nThis baseline follows the direct definition and documents its O(n) extra-space tradeoff instead of satisfying the strict constant-space challenge.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public int findDuplicate(int[] nums) { Set<Integer> seen = new HashSet<>(); for (int num : nums) { if (!seen.add(num)) { return num; } } return -1; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

