    private static String lruCacheManualHashMapListSolutionEntryJson() {
        return """
                    {
                      "name": "Manual HashMap Doubly Linked List Fixture",
                      "timeComplexity": "O(1) average per operation",
                      "spaceComplexity": "O(capacity)",
                      "description": "## Approach\\n\\nUse a HashMap to find nodes and a sentinel doubly linked list to keep recency order.\\n\\n## Key Insight\\n\\nThe map gives O(1) lookup while the list gives O(1) least-recent eviction and O(1) move-to-front.\\n\\n## Complexity Analysis\\n- Time Complexity: O(1) average for get and put\\n- Space Complexity: O(capacity)",
                      "code": "import java.util.*; class LRUCache { static class Node { int key; int value; Node prev; Node next; Node(int key, int value) { this.key = key; this.value = value; } } private final int capacity; private final Map<Integer, Node> nodes = new HashMap<>(); private final Node head = new Node(-1, -1); private final Node tail = new Node(-1, -1); public LRUCache(int capacity) { this.capacity = capacity; head.next = tail; tail.prev = head; } public int get(int key) { Node node = nodes.get(key); if (node == null) return -1; unlink(node); insertAfterHead(node); return node.value; } public void put(int key, int value) { Node node = nodes.get(key); if (node != null) { node.value = value; unlink(node); insertAfterHead(node); return; } Node inserted = new Node(key, value); nodes.put(key, inserted); insertAfterHead(inserted); if (nodes.size() > capacity) { Node leastRecent = tail.prev; unlink(leastRecent); nodes.remove(leastRecent.key); } } private void unlink(Node node) { node.prev.next = node.next; node.next.prev = node.prev; } private void insertAfterHead(Node node) { node.prev = head; node.next = head.next; head.next.prev = node; head.next = node; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String lruCacheLinkedHashMapSolutionEntryJson() {
        return """
                    {
                      "name": "LinkedHashMap Access Order Fixture",
                      "timeComplexity": "O(1) average per operation",
                      "spaceComplexity": "O(capacity)",
                      "description": "## Approach\\n\\nUse LinkedHashMap in access-order mode and let removeEldestEntry evict once size exceeds capacity.\\n\\n## Key Insight\\n\\nLinkedHashMap is Java's built-in version of a hash table joined to a doubly linked access-order list.\\n\\n## Complexity Analysis\\n- Time Complexity: O(1) average for get and put\\n- Space Complexity: O(capacity)",
                      "code": "import java.util.*; class LRUCache extends LinkedHashMap<Integer, Integer> { private final int capacity; public LRUCache(int capacity) { super(capacity, 0.75f, true); this.capacity = capacity; } public int get(int key) { return super.getOrDefault(key, -1); } public void put(int key, int value) { super.put(key, value); } protected boolean removeEldestEntry(Map.Entry<Integer, Integer> eldest) { return size() > capacity; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String lruCacheDirectAddressSolutionEntryJson() {
        return """
                    {
                      "name": "Direct Address Table Fixture",
                      "timeComplexity": "O(1) per operation",
                      "spaceComplexity": "O(U + capacity)",
                      "description": "## Approach\\n\\nUse the bounded key range as a direct address table from key to linked-list node.\\n\\n## Key Insight\\n\\nA fixed key universe can replace hashing while the linked list still provides O(1) recency updates and eviction.\\n\\n## Complexity Analysis\\n- Time Complexity: O(1) for get and put\\n- Space Complexity: O(U + capacity)",
                      "code": "class LRUCache { static final int MAX_KEY = 10000; static class Node { int key; int value; Node prev; Node next; Node(int key, int value) { this.key = key; this.value = value; } } private final int capacity; private int size; private final Node[] table = new Node[MAX_KEY + 1]; private final Node head = new Node(-1, -1); private final Node tail = new Node(-1, -1); public LRUCache(int capacity) { this.capacity = capacity; head.next = tail; tail.prev = head; } public int get(int key) { Node node = table[key]; if (node == null) return -1; unlink(node); insertAfterHead(node); return node.value; } public void put(int key, int value) { Node node = table[key]; if (node != null) { node.value = value; unlink(node); insertAfterHead(node); return; } Node inserted = new Node(key, value); table[key] = inserted; insertAfterHead(inserted); size++; if (size > capacity) { Node leastRecent = tail.prev; unlink(leastRecent); table[leastRecent.key] = null; size--; } } private void unlink(Node node) { node.prev.next = node.next; node.next.prev = node.prev; } private void insertAfterHead(Node node) { node.prev = head; node.next = head.next; head.next.prev = node; head.next = node; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String lruCacheArrayBackedSolutionEntryJson() {
        return """
                    {
                      "name": "Array-Backed Linked List Fixture",
                      "timeComplexity": "O(1) per operation",
                      "spaceComplexity": "O(U)",
                      "description": "## Approach\\n\\nStore values, prev links, next links, and presence bits in arrays indexed by key.\\n\\n## Key Insight\\n\\nThe LRU list invariant is the same as the pointer version, but every pointer becomes an array cell.\\n\\n## Complexity Analysis\\n- Time Complexity: O(1) for get and put\\n- Space Complexity: O(U)",
                      "code": "class LRUCache { static final int MAX_KEY = 10000; static final int HEAD = MAX_KEY + 1; static final int TAIL = MAX_KEY + 2; private final int capacity; private int size; private final int[] values = new int[MAX_KEY + 3]; private final int[] prev = new int[MAX_KEY + 3]; private final int[] next = new int[MAX_KEY + 3]; private final boolean[] present = new boolean[MAX_KEY + 1]; public LRUCache(int capacity) { this.capacity = capacity; next[HEAD] = TAIL; prev[TAIL] = HEAD; } public int get(int key) { if (!present[key]) return -1; unlink(key); insertAfterHead(key); return values[key]; } public void put(int key, int value) { if (present[key]) { values[key] = value; unlink(key); insertAfterHead(key); return; } if (size == capacity) { int leastRecent = prev[TAIL]; unlink(leastRecent); present[leastRecent] = false; size--; } values[key] = value; present[key] = true; insertAfterHead(key); size++; } private void unlink(int key) { int before = prev[key]; int after = next[key]; next[before] = after; prev[after] = before; } private void insertAfterHead(int key) { int first = next[HEAD]; prev[key] = HEAD; next[key] = first; prev[first] = key; next[HEAD] = key; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

