    private static String reverseNodesKGroupKthInPlaceSolutionEntryJson() {
        return """
                    {
                      "name": "Kth In-Place Reversal Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nFind the kth node of each group, save the next group start, reverse pointers inside the group, and reconnect it to the surrounding list.\\n\\n## Key Insight\\n\\nSaving groupNext makes the old group head point directly to the untouched suffix while the group is reversed.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public ListNode reverseKGroup(ListNode head, int k) { ListNode dummy = new ListNode(0, head); ListNode groupPrev = dummy; while (true) { ListNode kth = getKth(groupPrev, k); if (kth == null) break; ListNode groupNext = kth.next; ListNode prev = groupNext; ListNode curr = groupPrev.next; while (curr != groupNext) { ListNode next = curr.next; curr.next = prev; prev = curr; curr = next; } ListNode oldGroupHead = groupPrev.next; groupPrev.next = kth; groupPrev = oldGroupHead; } return dummy.next; } private ListNode getKth(ListNode start, int k) { while (start != null && k > 0) { start = start.next; k--; } return start; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String reverseNodesKGroupHeadInsertionSolutionEntryJson() {
        return """
                    {
                      "name": "Head-Insertion Rotation Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nAfter proving a complete group exists, repeatedly move the node after the group tail to the front of that group.\\n\\n## Key Insight\\n\\nFront insertion reverses one bounded group without using a separate helper list or extra storage.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public ListNode reverseKGroup(ListNode head, int k) { ListNode dummy = new ListNode(0, head); ListNode groupPrev = dummy; while (true) { ListNode kth = groupPrev; for (int i = 0; i < k && kth != null; i++) { kth = kth.next; } if (kth == null) break; ListNode groupTail = groupPrev.next; ListNode curr = groupTail.next; for (int i = 1; i < k; i++) { groupTail.next = curr.next; curr.next = groupPrev.next; groupPrev.next = curr; curr = groupTail.next; } groupPrev = groupTail; } return dummy.next; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String reverseNodesKGroupRecursiveSolutionEntryJson() {
        return """
                    {
                      "name": "Recursive Group Reversal Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n/k)",
                      "description": "## Approach\\n\\nCheck that the current prefix has k nodes, reverse that prefix, and recursively attach the processed suffix.\\n\\n## Key Insight\\n\\nThe original head becomes the reversed group tail, so it is the correct connection point for the recursive result.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n/k)",
                      "code": "class Solution { public ListNode reverseKGroup(ListNode head, int k) { ListNode node = head; for (int i = 0; i < k; i++) { if (node == null) return head; node = node.next; } ListNode reversedHead = reverseFirstK(head, k); head.next = reverseKGroup(node, k); return reversedHead; } private ListNode reverseFirstK(ListNode head, int k) { ListNode prev = null; ListNode curr = head; for (int i = 0; i < k; i++) { ListNode next = curr.next; curr.next = prev; prev = curr; curr = next; } return prev; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String reverseNodesKGroupStackSolutionEntryJson() {
        return """
                    {
                      "name": "Stack per Group Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(k)",
                      "description": "## Approach\\n\\nCollect each complete group in a stack and append popped nodes back to the result list.\\n\\n## Key Insight\\n\\nThe stack makes the reversed group order explicit, trading O(k) extra space for simpler group handling.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(k)",
                      "code": "import java.util.*; class Solution { public ListNode reverseKGroup(ListNode head, int k) { ListNode dummy = new ListNode(0); ListNode tail = dummy; ListNode curr = head; while (curr != null) { Deque<ListNode> stack = new ArrayDeque<>(); ListNode groupStart = curr; int count = 0; while (count < k && curr != null) { stack.push(curr); curr = curr.next; count++; } if (count < k) { tail.next = groupStart; break; } while (!stack.isEmpty()) { tail.next = stack.pop(); tail = tail.next; } tail.next = curr; } return dummy.next; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

