    private static String intersectionTwoLinkedListsPointerSwitchingSolutionEntryJson() {
        return """
                    {
                      "name": "Pointer Switching Equal Distance Fixture",
                      "timeComplexity": "O(m + n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nRun pointer a through list A then list B, and pointer b through list B then list A until they are the same node.\\n\\n## Key Insight\\n\\nAfter switching heads, both pointers travel the same total distance and therefore enter the shared suffix together.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m + n)\\n- Space Complexity: O(1)",
                      "code": "public class Solution { public ListNode getIntersectionNode(ListNode headA, ListNode headB) { ListNode a = headA; ListNode b = headB; while (a != b) { a = (a != null) ? a.next : headB; b = (b != null) ? b.next : headA; } return a; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String intersectionTwoLinkedListsLengthAlignmentSolutionEntryJson() {
        return """
                    {
                      "name": "Length Alignment Fixture",
                      "timeComplexity": "O(m + n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nCount both lengths, advance the longer list by the difference, then move both heads together until node identity matches.\\n\\n## Key Insight\\n\\nEqual remaining distance means the first equal object is the first shared node, regardless of duplicate values.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m + n)\\n- Space Complexity: O(1)",
                      "code": "public class Solution { public ListNode getIntersectionNode(ListNode headA, ListNode headB) { int lenA = length(headA); int lenB = length(headB); while (lenA > lenB) { headA = headA.next; lenA--; } while (lenB > lenA) { headB = headB.next; lenB--; } while (headA != headB) { headA = headA.next; headB = headB.next; } return headA; } private int length(ListNode node) { int count = 0; while (node != null) { count++; node = node.next; } return count; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

