    private static String sortListTopDownMergeSolutionEntryJson() {
        return """
                    {
                      "name": "Top-Down Merge Sort Fixture",
                      "timeComplexity": "O(n log n)",
                      "spaceComplexity": "O(log n)",
                      "description": "## Approach\\n\\nSplit the list with slow and fast pointers, recursively sort both halves, then merge them by rewiring next pointers.\\n\\n## Key Insight\\n\\nCutting the first half with slow.next = null is what makes each recursive call smaller.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log n)\\n- Space Complexity: O(log n)",
                      "code": "class Solution { public ListNode sortList(ListNode head) { if (head == null || head.next == null) return head; ListNode slow = head; ListNode fast = head.next; while (fast != null && fast.next != null) { slow = slow.next; fast = fast.next.next; } ListNode mid = slow.next; slow.next = null; ListNode left = sortList(head); ListNode right = sortList(mid); return merge(left, right); } private ListNode merge(ListNode left, ListNode right) { ListNode dummy = new ListNode(0); ListNode tail = dummy; while (left != null && right != null) { if (left.val <= right.val) { tail.next = left; left = left.next; } else { tail.next = right; right = right.next; } tail = tail.next; } tail.next = (left != null) ? left : right; return dummy.next; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String sortListBottomUpMergeSolutionEntryJson() {
        return """
                    {
                      "name": "Bottom-Up Merge Sort Fixture",
                      "timeComplexity": "O(n log n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nMerge runs of length 1, 2, 4, and so on, using split to cut each neighboring pair and a previous tail to reconnect the merged run.\\n\\n## Key Insight\\n\\nThe iterative form keeps merge sort but removes recursion stack space, which is the follow-up target for this linked-list problem.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public ListNode sortList(ListNode head) { if (head == null || head.next == null) return head; int length = 0; ListNode curr = head; while (curr != null) { length++; curr = curr.next; } ListNode dummy = new ListNode(0, head); for (int size = 1; size < length; size *= 2) { ListNode prev = dummy; curr = dummy.next; while (curr != null) { ListNode left = curr; ListNode right = split(left, size); curr = split(right, size); prev = merge(left, right, prev); } } return dummy.next; } private ListNode split(ListNode head, int size) { for (int i = 1; head != null && i < size; i++) { head = head.next; } if (head == null) return null; ListNode next = head.next; head.next = null; return next; } private ListNode merge(ListNode left, ListNode right, ListNode prev) { while (left != null && right != null) { if (left.val <= right.val) { prev.next = left; left = left.next; } else { prev.next = right; right = right.next; } prev = prev.next; } prev.next = (left != null) ? left : right; while (prev.next != null) { prev = prev.next; } return prev; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String sortListPriorityQueueSolutionEntryJson() {
        return """
                    {
                      "name": "Detached Priority Queue Fixture",
                      "timeComplexity": "O(n log n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nPush every detached node into a priority queue ordered by node value, then poll nodes back into a sorted chain.\\n\\n## Key Insight\\n\\nDetaching old next pointers prevents the rebuilt chain from accidentally keeping an unsorted original suffix.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public ListNode sortList(ListNode head) { PriorityQueue<ListNode> heap = new PriorityQueue<>((a, b) -> Integer.compare(a.val, b.val)); while (head != null) { ListNode next = head.next; head.next = null; heap.offer(head); head = next; } ListNode dummy = new ListNode(0); ListNode tail = dummy; while (!heap.isEmpty()) { tail.next = heap.poll(); tail = tail.next; tail.next = null; } return dummy.next; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

