    private static String rotateListCircleBreakSolutionEntryJson() {
        return """
                    {
                      "name": "Circle Then Break Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nCount length, connect the old tail to the old head, walk to the new tail, and break the circle.\\n\\n## Key Insight\\n\\nRotation is selecting a new head on a circular list, and newTail.next = null prevents a cyclic cache candidate.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public ListNode rotateRight(ListNode head, int k) { if (head == null || head.next == null || k == 0) return head; int length = 1; ListNode tail = head; while (tail.next != null) { length++; tail = tail.next; } k %= length; if (k == 0) return head; tail.next = head; ListNode newTail = head; for (int i = 0; i < length - k - 1; i++) { newTail = newTail.next; } ListNode newHead = newTail.next; newTail.next = null; return newHead; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String rotateListGapTwoPointersSolutionEntryJson() {
        return """
                    {
                      "name": "Gap Two Pointers Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nCount length, reduce k, advance fast by k nodes, then move slow and fast together until fast reaches the old tail.\\n\\n## Key Insight\\n\\nThe gap places slow at the new tail, so slow.next is the new head and the old tail can reconnect to the old head.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public ListNode rotateRight(ListNode head, int k) { if (head == null || head.next == null || k == 0) return head; int length = 0; ListNode curr = head; while (curr != null) { length++; curr = curr.next; } k %= length; if (k == 0) return head; ListNode fast = head; for (int i = 0; i < k; i++) { fast = fast.next; } ListNode slow = head; while (fast.next != null) { slow = slow.next; fast = fast.next; } ListNode newHead = slow.next; slow.next = null; fast.next = head; return newHead; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String rotateListTripleReversalSolutionEntryJson() {
        return """
                    {
                      "name": "Triple Reversal Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nReverse the whole list, cut after k nodes, reverse the prefix and suffix separately, then connect them.\\n\\n## Key Insight\\n\\nThe whole-list reversal groups the moved suffix at the front, and the two smaller reversals restore each group order.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public ListNode rotateRight(ListNode head, int k) { if (head == null || head.next == null || k == 0) return head; int length = 0; ListNode curr = head; while (curr != null) { length++; curr = curr.next; } k %= length; if (k == 0) return head; head = reverse(head); ListNode firstTail = head; for (int i = 1; i < k; i++) { firstTail = firstTail.next; } ListNode secondHead = firstTail.next; firstTail.next = null; ListNode newHead = reverse(head); head.next = reverse(secondHead); return newHead; } private ListNode reverse(ListNode node) { ListNode prev = null; while (node != null) { ListNode next = node.next; node.next = prev; prev = node; node = next; } return prev; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String rotateListArrayIndexSolutionEntryJson() {
        return """
                    {
                      "name": "Array Index Reconnect Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nDetach nodes into an array, compute the rotated start index, and reconnect nodes by cyclic array index.\\n\\n## Key Insight\\n\\nThe array makes modulo arithmetic explicit while detaching old next links prevents cycles and stale suffixes.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public ListNode rotateRight(ListNode head, int k) { if (head == null || head.next == null || k == 0) return head; List<ListNode> nodes = new ArrayList<>(); ListNode curr = head; while (curr != null) { ListNode next = curr.next; curr.next = null; nodes.add(curr); curr = next; } int n = nodes.size(); int rotation = k % n; int start = n - rotation; ListNode dummy = new ListNode(0); ListNode tail = dummy; for (int i = 0; i < n; i++) { ListNode node = nodes.get((start + i) % n); tail.next = node; tail = tail.next; } tail.next = null; return dummy.next; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

