    private static String maximumDepthBottomUpRecursiveSolutionEntryJson() {
        return """
                    {
                      "name": "Bottom-Up Recursive DFS Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(h)",
                      "description": "## Approach\\n\\nReturn zero for an empty subtree, recursively compute left and right depths, then add one for the current node.\\n\\n## Key Insight\\n\\nMaximum depth is the tree-height recurrence, so the answer at a node depends only on the larger child height.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(h)",
                      "code": "class Solution { public int maxDepth(TreeNode root) { if (root == null) return 0; return 1 + Math.max(maxDepth(root.left), maxDepth(root.right)); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String maximumDepthBfsLevelSolutionEntryJson() {
        return """
                    {
                      "name": "BFS Level Counting Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(w)",
                      "description": "## Approach\\n\\nTraverse by queue levels. Process the current queue size as one level, then increment the depth counter.\\n\\n## Key Insight\\n\\nDepth is the number of completed levels, and BFS exposes those levels directly.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(w)",
                      "code": "import java.util.*; class Solution { public int maxDepth(TreeNode root) { if (root == null) return 0; Queue<TreeNode> queue = new ArrayDeque<>(); queue.offer(root); int depth = 0; while (!queue.isEmpty()) { int size = queue.size(); depth++; for (int i = 0; i < size; i++) { TreeNode node = queue.poll(); if (node.left != null) queue.offer(node.left); if (node.right != null) queue.offer(node.right); } } return depth; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String maximumDepthDfsFrameSolutionEntryJson() {
        return """
                    {
                      "name": "Iterative DFS Depth Frames Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(h)",
                      "description": "## Approach\\n\\nPush node-depth frames onto a stack. Every popped frame updates the best depth before pushing non-null children with depth plus one.\\n\\n## Key Insight\\n\\nThe stack stores the recursive depth parameter explicitly, so the maximum frame depth seen is the answer.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(h)",
                      "code": "import java.util.*; class Solution { public int maxDepth(TreeNode root) { if (root == null) return 0; int maxDepth = 0; Deque<Frame> stack = new ArrayDeque<>(); stack.push(new Frame(root, 1)); while (!stack.isEmpty()) { Frame frame = stack.pop(); maxDepth = Math.max(maxDepth, frame.depth); if (frame.node.left != null) { stack.push(new Frame(frame.node.left, frame.depth + 1)); } if (frame.node.right != null) { stack.push(new Frame(frame.node.right, frame.depth + 1)); } } return maxDepth; } private static class Frame { TreeNode node; int depth; Frame(TreeNode node, int depth) { this.node = node; this.depth = depth; } } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

