    private static String diameterGlobalPostorderSolutionEntryJson() {
        return """
                    {
                      "name": "Postorder DFS Global Answer Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(h)",
                      "description": "## Approach\\n\\nReturn subtree heights from postorder DFS and update a global diameter with left plus right height at every node.\\n\\n## Key Insight\\n\\nA path through a node can use both child heights, while the height returned upward can only use one side.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(h)",
                      "code": "class Solution { private int diameter; public int diameterOfBinaryTree(TreeNode root) { diameter = 0; height(root); return diameter; } private int height(TreeNode node) { if (node == null) return 0; int left = height(node.left); int right = height(node.right); diameter = Math.max(diameter, left + right); return 1 + Math.max(left, right); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String diameterInfoReturnSolutionEntryJson() {
        return """
                    {
                      "name": "Postorder DFS Returning Info Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(h)",
                      "description": "## Approach\\n\\nReturn height and diameter together from each subtree, then combine child facts at the parent.\\n\\n## Key Insight\\n\\nThe parent needs both child heights and both child diameters, so an Info object removes mutable global state.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(h)",
                      "code": "class Solution { public int diameterOfBinaryTree(TreeNode root) { return solve(root).diameter; } private Info solve(TreeNode node) { if (node == null) return new Info(0, 0); Info left = solve(node.left); Info right = solve(node.right); int throughNode = left.height + right.height; int diameter = Math.max(throughNode, Math.max(left.diameter, right.diameter)); int height = 1 + Math.max(left.height, right.height); return new Info(height, diameter); } private static class Info { int height; int diameter; Info(int height, int diameter) { this.height = height; this.diameter = diameter; } } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String diameterIterativePostorderSolutionEntryJson() {
        return """
                    {
                      "name": "Iterative Postorder Height Map Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nSimulate postorder traversal with a stack, store completed subtree heights in a map, and update the best diameter when both child heights are available.\\n\\n## Key Insight\\n\\nDiameter depends on completed child heights, so iterative postorder preserves the same dependency order as recursion.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public int diameterOfBinaryTree(TreeNode root) { if (root == null) return 0; Map<TreeNode, Integer> height = new HashMap<>(); Deque<TreeNode> stack = new ArrayDeque<>(); TreeNode current = root; TreeNode lastVisited = null; int best = 0; while (current != null || !stack.isEmpty()) { while (current != null) { stack.push(current); current = current.left; } TreeNode peek = stack.peek(); if (peek.right != null && lastVisited != peek.right) { current = peek.right; } else { int leftHeight = height.getOrDefault(peek.left, 0); int rightHeight = height.getOrDefault(peek.right, 0); best = Math.max(best, leftHeight + rightHeight); height.put(peek, 1 + Math.max(leftHeight, rightHeight)); lastVisited = stack.pop(); } } return best; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String diameterGraphTwoBfsSolutionEntryJson() {
        return """
                    {
                      "name": "Graph Two-BFS Diameter Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nConvert the binary tree to an undirected graph, run BFS from the root to find a farthest node, then run BFS again from that node.\\n\\n## Key Insight\\n\\nTwo farthest-node searches find the diameter of any tree, giving a graph-theory view of the binary-tree problem.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public int diameterOfBinaryTree(TreeNode root) { if (root == null) return 0; Map<TreeNode, List<TreeNode>> graph = new HashMap<>(); buildGraph(root, null, graph); Result first = bfs(root, graph); Result second = bfs(first.node, graph); return second.distance; } private void buildGraph(TreeNode node, TreeNode parent, Map<TreeNode, List<TreeNode>> graph) { if (node == null) return; graph.computeIfAbsent(node, key -> new ArrayList<>()); if (parent != null) { graph.get(node).add(parent); graph.get(parent).add(node); } buildGraph(node.left, node, graph); buildGraph(node.right, node, graph); } private Result bfs(TreeNode start, Map<TreeNode, List<TreeNode>> graph) { Queue<TreeNode> queue = new ArrayDeque<>(); Map<TreeNode, Integer> distance = new HashMap<>(); queue.offer(start); distance.put(start, 0); TreeNode farthest = start; while (!queue.isEmpty()) { TreeNode node = queue.poll(); int currentDistance = distance.get(node); if (currentDistance > distance.get(farthest)) { farthest = node; } for (TreeNode next : graph.get(node)) { if (!distance.containsKey(next)) { distance.put(next, currentDistance + 1); queue.offer(next); } } } return new Result(farthest, distance.get(farthest)); } private static class Result { TreeNode node; int distance; Result(TreeNode node, int distance) { this.node = node; this.distance = distance; } } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

