    private static String lcaBstIterativeSplitSolutionEntryJson() {
        return """
                    {
                      "name": "Iterative BST Split Point Fixture",
                      "timeComplexity": "O(h)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nWalk downward from the root until the target values are no longer both on the same side.\\n\\n## Key Insight\\n\\nThe first BST node whose value lies between p.val and q.val is the lowest common ancestor.\\n\\n## Complexity Analysis\\n- Time Complexity: O(h)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) { int low = Math.min(p.val, q.val); int high = Math.max(p.val, q.val); TreeNode current = root; while (current != null) { if (high < current.val) { current = current.left; } else if (low > current.val) { current = current.right; } else { return current; } } return null; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String lcaBstRecursiveSplitSolutionEntryJson() {
        return """
                    {
                      "name": "Recursive BST Split Point Fixture",
                      "timeComplexity": "O(h)",
                      "spaceComplexity": "O(h)",
                      "description": "## Approach\\n\\nApply the same split-point rule recursively to the only side that can still contain both targets.\\n\\n## Key Insight\\n\\nOnce the two target values stop being on the same side, the current node cannot be skipped.\\n\\n## Complexity Analysis\\n- Time Complexity: O(h)\\n- Space Complexity: O(h)",
                      "code": "class Solution { public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) { int low = Math.min(p.val, q.val); int high = Math.max(p.val, q.val); if (high < root.val) { return lowestCommonAncestor(root.left, p, q); } if (low > root.val) { return lowestCommonAncestor(root.right, p, q); } return root; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String lcaBstPathComparisonSolutionEntryJson() {
        return """
                    {
                      "name": "Root-to-Node Path Comparison Fixture",
                      "timeComplexity": "O(h)",
                      "spaceComplexity": "O(h)",
                      "description": "## Approach\\n\\nBuild the root-to-p path and root-to-q path with BST search, then keep the last shared node.\\n\\n## Key Insight\\n\\nCommon ancestors are exactly the shared prefix of the two root-to-node paths.\\n\\n## Complexity Analysis\\n- Time Complexity: O(h)\\n- Space Complexity: O(h)",
                      "code": "import java.util.*; class Solution { public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) { List<TreeNode> pathToP = pathTo(root, p.val); List<TreeNode> pathToQ = pathTo(root, q.val); TreeNode answer = root; int i = 0; while (i < pathToP.size() && i < pathToQ.size() && pathToP.get(i) == pathToQ.get(i)) { answer = pathToP.get(i); i++; } return answer; } private List<TreeNode> pathTo(TreeNode root, int target) { List<TreeNode> path = new ArrayList<>(); TreeNode current = root; while (current != null) { path.add(current); if (target == current.val) break; current = target < current.val ? current.left : current.right; } return path; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String lcaBstGeneralDfsSolutionEntryJson() {
        return """
                    {
                      "name": "General Binary-Tree DFS Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(h)",
                      "description": "## Approach\\n\\nIgnore the BST ordering and solve the general binary-tree LCA problem with DFS, stopping when the current value matches either target value.\\n\\n## Key Insight\\n\\nThis baseline shows what the BST split-point route optimizes away.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(h)",
                      "code": "class Solution { public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) { if (root == null || root.val == p.val || root.val == q.val) { return root; } TreeNode left = lowestCommonAncestor(root.left, p, q); TreeNode right = lowestCommonAncestor(root.right, p, q); if (left != null && right != null) { return root; } return left != null ? left : right; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

