    private static String levelOrderQueueSizeSolutionEntryJson() {
        return """
                    {
                      "name": "BFS Queue Size Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(w)",
                      "description": "## Approach\\n\\nSnapshot the queue size at the start of each level and process exactly that many nodes into one row.\\n\\n## Key Insight\\n\\nThe size snapshot is the boundary between the current level and children queued for the next level.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(w)",
                      "code": "import java.util.*; class Solution { public List<List<Integer>> levelOrder(TreeNode root) { List<List<Integer>> result = new ArrayList<>(); if (root == null) return result; Queue<TreeNode> queue = new ArrayDeque<>(); queue.offer(root); while (!queue.isEmpty()) { int levelSize = queue.size(); List<Integer> level = new ArrayList<>(); for (int i = 0; i < levelSize; i++) { TreeNode node = queue.poll(); level.add(node.val); if (node.left != null) queue.offer(node.left); if (node.right != null) queue.offer(node.right); } result.add(level); } return result; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String levelOrderRecursiveDfsSolutionEntryJson() {
        return """
                    {
                      "name": "Recursive DFS Level Index Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(h)",
                      "description": "## Approach\\n\\nCarry the current level through DFS and append each value into the row for that level.\\n\\n## Key Insight\\n\\nLevel order is a grouping rule; DFS can satisfy it when every node writes to result[level].\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(h)",
                      "code": "import java.util.*; class Solution { public List<List<Integer>> levelOrder(TreeNode root) { List<List<Integer>> result = new ArrayList<>(); dfs(root, 0, result); return result; } private void dfs(TreeNode node, int level, List<List<Integer>> result) { if (node == null) return; if (level == result.size()) result.add(new ArrayList<>()); result.get(level).add(node.val); dfs(node.left, level + 1, result); dfs(node.right, level + 1, result); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String levelOrderExplicitLevelQueueSolutionEntryJson() {
        return """
                    {
                      "name": "Explicit Level Queue Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(w)",
                      "description": "## Approach\\n\\nStore each queued node together with its level and append values into the matching output row.\\n\\n## Key Insight\\n\\nThe level carried in the queue entry makes row placement explicit.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(w)",
                      "code": "import java.util.*; class Solution { public List<List<Integer>> levelOrder(TreeNode root) { List<List<Integer>> result = new ArrayList<>(); if (root == null) return result; Queue<NodeLevel> queue = new ArrayDeque<>(); queue.offer(new NodeLevel(root, 0)); while (!queue.isEmpty()) { NodeLevel current = queue.poll(); if (result.size() == current.level) result.add(new ArrayList<>()); result.get(current.level).add(current.node.val); if (current.node.left != null) queue.offer(new NodeLevel(current.node.left, current.level + 1)); if (current.node.right != null) queue.offer(new NodeLevel(current.node.right, current.level + 1)); } return result; } private static class NodeLevel { TreeNode node; int level; NodeLevel(TreeNode node, int level) { this.node = node; this.level = level; } } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String levelOrderFrontierListsSolutionEntryJson() {
        return """
                    {
                      "name": "Iterative Frontier Lists Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(w)",
                      "description": "## Approach\\n\\nProcess a list of current-level nodes and build a next-level list from their children.\\n\\n## Key Insight\\n\\nEach level is one frontier, so replacing the current frontier with the next one preserves row boundaries.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(w)",
                      "code": "import java.util.*; class Solution { public List<List<Integer>> levelOrder(TreeNode root) { List<List<Integer>> result = new ArrayList<>(); if (root == null) return result; List<TreeNode> current = new ArrayList<>(); current.add(root); while (!current.isEmpty()) { List<Integer> level = new ArrayList<>(); List<TreeNode> next = new ArrayList<>(); for (TreeNode node : current) { level.add(node.val); if (node.left != null) next.add(node.left); if (node.right != null) next.add(node.right); } result.add(level); current = next; } return result; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

