    private static String goodNodesReturningDfsSolutionEntryJson() {
        return """
                    {
                      "name": "Returning DFS Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(h)",
                      "description": "## Approach\\n\\nReturn the number of good nodes in each subtree while carrying the path maximum.\\n\\n## Key Insight\\n\\nThe current path maximum is the only ancestor state needed to classify a node.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(h)",
                      "code": "class Solution { public int goodNodes(TreeNode root) { return dfs(root, Integer.MIN_VALUE); } private int dfs(TreeNode node, int maxSoFar) { if (node == null) return 0; int count = node.val >= maxSoFar ? 1 : 0; int nextMax = Math.max(maxSoFar, node.val); count += dfs(node.left, nextMax); count += dfs(node.right, nextMax); return count; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String goodNodesMutableCounterSolutionEntryJson() {
        return """
                    {
                      "name": "Mutable Counter DFS Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(h)",
                      "description": "## Approach\\n\\nAccumulate the answer in a field while preorder DFS carries the path maximum.\\n\\n## Key Insight\\n\\nThe same path-maximum invariant can count nodes as a side effect instead of returning counts.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(h)",
                      "code": "class Solution { private int count; public int goodNodes(TreeNode root) { count = 0; visit(root, Integer.MIN_VALUE); return count; } private void visit(TreeNode node, int maxSoFar) { if (node == null) return; if (node.val >= maxSoFar) { count++; } int nextMax = Math.max(maxSoFar, node.val); visit(node.left, nextMax); visit(node.right, nextMax); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String goodNodesBfsFrameSolutionEntryJson() {
        return """
                    {
                      "name": "BFS Frame Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(w)",
                      "description": "## Approach\\n\\nQueue frames containing a node and the maximum value before that node on its path.\\n\\n## Key Insight\\n\\nEach branch needs its own path maximum, so the queue frame carries branch-local state.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(w)",
                      "code": "import java.util.*; class Solution { public int goodNodes(TreeNode root) { if (root == null) return 0; int count = 0; Queue<Frame> queue = new ArrayDeque<>(); queue.offer(new Frame(root, Integer.MIN_VALUE)); while (!queue.isEmpty()) { Frame current = queue.poll(); TreeNode node = current.node; if (node.val >= current.pathMax) { count++; } int nextMax = Math.max(current.pathMax, node.val); if (node.left != null) queue.offer(new Frame(node.left, nextMax)); if (node.right != null) queue.offer(new Frame(node.right, nextMax)); } return count; } private static class Frame { TreeNode node; int pathMax; Frame(TreeNode node, int pathMax) { this.node = node; this.pathMax = pathMax; } } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String goodNodesIterativeDfsStackSolutionEntryJson() {
        return """
                    {
                      "name": "Iterative DFS Parallel Stacks Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(h)",
                      "description": "## Approach\\n\\nUse parallel stacks for nodes and path maximums to emulate recursive DFS without a frame class.\\n\\n## Key Insight\\n\\nThe two stacks preserve the node/path-maximum pairing while keeping this route structurally different from queue frames.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(h)",
                      "code": "import java.util.*; class Solution { public int goodNodes(TreeNode root) { if (root == null) return 0; int count = 0; Deque<TreeNode> nodeStack = new ArrayDeque<>(); Deque<Integer> maxStack = new ArrayDeque<>(); nodeStack.push(root); maxStack.push(Integer.MIN_VALUE); while (!nodeStack.isEmpty()) { TreeNode node = nodeStack.pop(); int pathMax = maxStack.pop(); if (node.val >= pathMax) { count++; } int nextMax = Math.max(pathMax, node.val); if (node.left != null) { nodeStack.push(node.left); maxStack.push(nextMax); } if (node.right != null) { nodeStack.push(node.right); maxStack.push(nextMax); } } return count; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

