    private static String validateBstRangeBoundSolutionEntryJson() {
        return """
                    {
                      "name": "Long Range Bounds Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(h)",
                      "description": "## Approach\\n\\nPass exclusive lower and upper bounds down the tree.\\n\\n## Key Insight\\n\\nAncestor constraints compress into one valid range, and long sentinels protect int boundary values.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(h)",
                      "code": "class Solution { public boolean isValidBST(TreeNode root) { return validate(root, Long.MIN_VALUE, Long.MAX_VALUE); } private boolean validate(TreeNode node, long min, long max) { if (node == null) return true; if (node.val <= min || node.val >= max) return false; return validate(node.left, min, node.val) && validate(node.right, node.val, max); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String validateBstRecursiveInorderSolutionEntryJson() {
        return """
                    {
                      "name": "Recursive Inorder Previous Value Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(h)",
                      "description": "## Approach\\n\\nRecursively traverse left-root-right and compare each value with the previous value.\\n\\n## Key Insight\\n\\nA valid BST must produce a strictly increasing inorder sequence, so duplicates and misplaced descendants fail.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(h)",
                      "code": "class Solution { private Long previous = null; public boolean isValidBST(TreeNode root) { return inorder(root); } private boolean inorder(TreeNode node) { if (node == null) return true; if (!inorder(node.left)) return false; if (previous != null && node.val <= previous) return false; previous = (long) node.val; return inorder(node.right); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String validateBstIterativeInorderStackSolutionEntryJson() {
        return """
                    {
                      "name": "Iterative Inorder Explicit Stack Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(h)",
                      "description": "## Approach\\n\\nSimulate inorder traversal with an explicit stack and compare each visited value to the previous value.\\n\\n## Key Insight\\n\\nThe stack keeps only the active left spine while preserving the same strictly increasing order check.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(h)",
                      "code": "import java.util.*; class Solution { public boolean isValidBST(TreeNode root) { Deque<TreeNode> stack = new ArrayDeque<>(); TreeNode current = root; Long previous = null; while (current != null || !stack.isEmpty()) { while (current != null) { stack.push(current); current = current.left; } current = stack.pop(); if (previous != null && current.val <= previous) { return false; } previous = (long) current.val; current = current.right; } return true; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String validateBstMorrisSolutionEntryJson() {
        return """
                    {
                      "name": "Morris Inorder Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nThread each node's inorder predecessor back to the node so traversal needs no recursion or explicit stack.\\n\\n## Key Insight\\n\\nMorris traversal still checks strictly increasing inorder values and must restore every temporary predecessor link.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public boolean isValidBST(TreeNode root) { TreeNode current = root; Long previous = null; while (current != null) { if (current.left == null) { if (previous != null && current.val <= previous) { return false; } previous = (long) current.val; current = current.right; } else { TreeNode predecessor = current.left; while (predecessor.right != null && predecessor.right != current) { predecessor = predecessor.right; } if (predecessor.right == null) { predecessor.right = current; current = current.left; } else { predecessor.right = null; if (previous != null && current.val <= previous) { return false; } previous = (long) current.val; current = current.right; } } } return true; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

