    private static String pathSumIIDfsBacktrackingSolutionEntryJson() {
        return """
                    {
                      "name": "DFS Backtracking Fixture",
                      "timeComplexity": "O(n * h)",
                      "spaceComplexity": "O(h)",
                      "description": "## Approach\\n\\nUse recursive DFS with one mutable path and copy it when a leaf completes the target.\\n\\n## Key Insight\\n\\nThe copied answer survives later backtracking, while the shared path is restored for sibling branches.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * h)\\n- Space Complexity: O(h)",
                      "code": "import java.util.*; class Solution { public List<List<Integer>> pathSum(TreeNode root, int targetSum) { List<List<Integer>> result = new ArrayList<>(); dfs(root, targetSum, new ArrayList<>(), result); return result; } private void dfs(TreeNode node, int remaining, List<Integer> path, List<List<Integer>> result) { if (node == null) { return; } path.add(node.val); if (node.left == null && node.right == null && remaining == node.val) { result.add(new ArrayList<>(path)); } else { int nextRemaining = remaining - node.val; dfs(node.left, nextRemaining, path, result); dfs(node.right, nextRemaining, path, result); } path.remove(path.size() - 1); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String pathSumIIIterativeDfsSolutionEntryJson() {
        return """
                    {
                      "name": "Iterative DFS Path Copy Fixture",
                      "timeComplexity": "O(n * h)",
                      "spaceComplexity": "O(n * h)",
                      "description": "## Approach\\n\\nUse a stack of frames that carry a node, remaining target, and a copied path.\\n\\n## Key Insight\\n\\nPush the right child before the left child to preserve left-to-right answer order.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * h)\\n- Space Complexity: O(n * h)",
                      "code": "import java.util.*; class Solution { private static final class Frame { final TreeNode node; final int remaining; final List<Integer> path; Frame(TreeNode node, int remaining, List<Integer> path) { this.node = node; this.remaining = remaining; this.path = path; } } public List<List<Integer>> pathSum(TreeNode root, int targetSum) { List<List<Integer>> result = new ArrayList<>(); if (root == null) { return result; } List<Integer> path = new ArrayList<>(); path.add(root.val); Deque<Frame> stack = new ArrayDeque<>(); stack.push(new Frame(root, targetSum - root.val, path)); while (!stack.isEmpty()) { Frame frame = stack.pop(); TreeNode node = frame.node; if (node.left == null && node.right == null && frame.remaining == 0) { result.add(frame.path); continue; } if (node.right != null) { List<Integer> rightPath = new ArrayList<>(frame.path); rightPath.add(node.right.val); stack.push(new Frame(node.right, frame.remaining - node.right.val, rightPath)); } if (node.left != null) { List<Integer> leftPath = new ArrayList<>(frame.path); leftPath.add(node.left.val); stack.push(new Frame(node.left, frame.remaining - node.left.val, leftPath)); } } return result; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String pathSumIIBfsSolutionEntryJson() {
        return """
                    {
                      "name": "BFS Path Tracking Fixture",
                      "timeComplexity": "O(n * h)",
                      "spaceComplexity": "O(n * h)",
                      "description": "## Approach\\n\\nUse a queue whose frames carry the node, running sum, and copied root-to-node path.\\n\\n## Key Insight\\n\\nBreadth-first traversal works because each queued state owns the path that reaches it.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * h)\\n- Space Complexity: O(n * h)",
                      "code": "import java.util.*; class Solution { private static final class Frame { final TreeNode node; final int sum; final List<Integer> path; Frame(TreeNode node, int sum, List<Integer> path) { this.node = node; this.sum = sum; this.path = path; } } public List<List<Integer>> pathSum(TreeNode root, int targetSum) { List<List<Integer>> result = new ArrayList<>(); if (root == null) { return result; } List<Integer> firstPath = new ArrayList<>(); firstPath.add(root.val); Queue<Frame> queue = new ArrayDeque<>(); queue.offer(new Frame(root, root.val, firstPath)); while (!queue.isEmpty()) { Frame frame = queue.poll(); TreeNode node = frame.node; if (node.left == null && node.right == null && frame.sum == targetSum) { result.add(frame.path); } if (node.left != null) { List<Integer> leftPath = new ArrayList<>(frame.path); leftPath.add(node.left.val); queue.offer(new Frame(node.left, frame.sum + node.left.val, leftPath)); } if (node.right != null) { List<Integer> rightPath = new ArrayList<>(frame.path); rightPath.add(node.right.val); queue.offer(new Frame(node.right, frame.sum + node.right.val, rightPath)); } } return result; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String pathSumIIParentMapSolutionEntryJson() {
        return """
                    {
                      "name": "Parent Map Reconstruction Fixture",
                      "timeComplexity": "O(n * h)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nStore parent pointers and root-to-node sums, then reconstruct a path only when a matching leaf is found.\\n\\n## Key Insight\\n\\nThis delays path allocation until a leaf is actually an answer.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * h)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public List<List<Integer>> pathSum(TreeNode root, int targetSum) { List<List<Integer>> result = new ArrayList<>(); if (root == null) { return result; } Map<TreeNode, TreeNode> parent = new HashMap<>(); Map<TreeNode, Integer> sum = new HashMap<>(); Queue<TreeNode> queue = new ArrayDeque<>(); queue.offer(root); parent.put(root, null); sum.put(root, root.val); while (!queue.isEmpty()) { TreeNode node = queue.poll(); int currentSum = sum.get(node); if (node.left == null && node.right == null && currentSum == targetSum) { result.add(reconstruct(node, parent)); } if (node.left != null) { parent.put(node.left, node); sum.put(node.left, currentSum + node.left.val); queue.offer(node.left); } if (node.right != null) { parent.put(node.right, node); sum.put(node.right, currentSum + node.right.val); queue.offer(node.right); } } return result; } private List<Integer> reconstruct(TreeNode node, Map<TreeNode, TreeNode> parent) { LinkedList<Integer> path = new LinkedList<>(); while (node != null) { path.addFirst(node.val); node = parent.get(node); } return path; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

