    private static String pathSumIIIRecursivePrefixSolutionEntryJson() {
        return """
                    {
                      "name": "Prefix Sum HashMap Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nTrack prefix sums for the current DFS branch and count earlier prefixes that differ by targetSum.\\n\\n## Key Insight\\n\\nThe HashMap stores counts because repeated prefix sums can create multiple valid starts for paths ending at one node.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public int pathSum(TreeNode root, int targetSum) { Map<Long, Integer> prefixMap = new HashMap<>(); prefixMap.put(0L, 1); return dfs(root, 0L, targetSum, prefixMap); } private int dfs(TreeNode node, long currentSum, int target, Map<Long, Integer> prefixMap) { if (node == null) { return 0; } currentSum += node.val; int count = prefixMap.getOrDefault(currentSum - target, 0); prefixMap.merge(currentSum, 1, Integer::sum); count += dfs(node.left, currentSum, target, prefixMap); count += dfs(node.right, currentSum, target, prefixMap); prefixMap.merge(currentSum, -1, Integer::sum); return count; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

