    private static String flattenTreeMorrisSolutionEntryJson() {
        return """
                    {
                      "name": "Morris Rewiring Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nWhen a node has a left subtree, splice the original right subtree after the left subtree's rightmost node.\\n\\n## Key Insight\\n\\nPreorder visits the whole left subtree before the original right subtree, so this local splice preserves the final chain.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public void flatten(TreeNode root) { TreeNode curr = root; while (curr != null) { if (curr.left != null) { TreeNode rightmost = curr.left; while (rightmost.right != null) { rightmost = rightmost.right; } rightmost.right = curr.right; curr.right = curr.left; curr.left = null; } curr = curr.right; } } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String flattenTreeReversePostorderSolutionEntryJson() {
        return """
                    {
                      "name": "Reverse Postorder Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(h)",
                      "description": "## Approach\\n\\nVisit right, then left, then root, wiring each root to the previously processed node.\\n\\n## Key Insight\\n\\nReverse preorder processes the final linked list from tail to head, so each next pointer is already known.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(h)",
                      "code": "class Solution { private TreeNode prev = null; public void flatten(TreeNode root) { if (root == null) { return; } flatten(root.right); flatten(root.left); root.right = prev; root.left = null; prev = root; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String flattenTreePreorderStackSolutionEntryJson() {
        return """
                    {
                      "name": "Preorder Stack Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(h)",
                      "description": "## Approach\\n\\nUse a stack to visit nodes in preorder, pushing right before left and rewiring the previous node to the current node.\\n\\n## Key Insight\\n\\nThe traversal order is the target chain order, while the stack remembers postponed subtrees.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(h)",
                      "code": "import java.util.*; class Solution { public void flatten(TreeNode root) { if (root == null) { return; } Deque<TreeNode> stack = new ArrayDeque<>(); stack.push(root); TreeNode previous = null; while (!stack.isEmpty()) { TreeNode node = stack.pop(); if (previous != null) { previous.left = null; previous.right = node; } if (node.right != null) { stack.push(node.right); } if (node.left != null) { stack.push(node.left); } previous = node; } previous.left = null; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String flattenTreeTailRewireSolutionEntryJson() {
        return """
                    {
                      "name": "Tail Rewire Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(h)",
                      "description": "## Approach\\n\\nFlatten both subtrees recursively, return their tails, and splice the flattened left chain before the original right chain.\\n\\n## Key Insight\\n\\nReturning tails lets each root reconnect its three pieces without a global pointer or a later scan.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(h)",
                      "code": "class Solution { public void flatten(TreeNode root) { flattenAndReturnTail(root); } private TreeNode flattenAndReturnTail(TreeNode node) { if (node == null) { return null; } TreeNode leftTail = flattenAndReturnTail(node.left); TreeNode rightTail = flattenAndReturnTail(node.right); if (leftTail != null) { leftTail.right = node.right; node.right = node.left; node.left = null; } if (rightTail != null) { return rightTail; } if (leftTail != null) { return leftTail; } return node; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

