    private static String wordDictionaryArrayTrieSolutionEntryJson() {
        return """
                    {
                      "name": "Array Trie DFS Fixture",
                      "timeComplexity": "O(L) add, O(26^D * L) search",
                      "spaceComplexity": "O(T)",
                      "description": "## Approach\\n\\nUse a 26-entry child array at each Trie node and branch recursively only when the search pattern contains a dot.\\n\\n## Key Insight\\n\\nThe end marker is checked after the whole pattern is consumed, so prefixes do not count as words.\\n\\n## Complexity Analysis\\n- addWord Time Complexity: O(L)\\n- search Time Complexity: O(26^D * L)\\n- Space Complexity: O(T)",
                      "code": "class WordDictionary { private static final class TrieNode { TrieNode[] children = new TrieNode[26]; boolean isEnd = false; } private final TrieNode root; public WordDictionary() { root = new TrieNode(); } public void addWord(String word) { TrieNode node = root; for (char c : word.toCharArray()) { int idx = c - 'a'; if (node.children[idx] == null) { node.children[idx] = new TrieNode(); } node = node.children[idx]; } node.isEnd = true; } public boolean search(String word) { return dfs(word, 0, root); } private boolean dfs(String word, int index, TrieNode node) { if (node == null) { return false; } if (index == word.length()) { return node.isEnd; } char c = word.charAt(index); if (c == '.') { for (TrieNode child : node.children) { if (child != null && dfs(word, index + 1, child)) { return true; } } return false; } return dfs(word, index + 1, node.children[c - 'a']); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String wordDictionaryHashMapTrieSolutionEntryJson() {
        return """
                    {
                      "name": "HashMap Trie DFS Fixture",
                      "timeComplexity": "O(L) add, O(B^D * L) search",
                      "spaceComplexity": "O(T)",
                      "description": "## Approach\\n\\nUse a HashMap of actual child edges at each Trie node, then DFS through map values when a dot is encountered.\\n\\n## Key Insight\\n\\nThe map keeps sparse branches compact while preserving the same complete-word terminal check as the array Trie.\\n\\n## Complexity Analysis\\n- addWord Time Complexity: O(L)\\n- search Time Complexity: O(B^D * L)\\n- Space Complexity: O(T)",
                      "code": "import java.util.*; class WordDictionary { private static final class TrieNode { Map<Character, TrieNode> children = new HashMap<>(); boolean isEnd = false; } private final TrieNode root; public WordDictionary() { root = new TrieNode(); } public void addWord(String word) { TrieNode node = root; for (int i = 0; i < word.length(); i++) { char c = word.charAt(i); node = node.children.computeIfAbsent(c, key -> new TrieNode()); } node.isEnd = true; } public boolean search(String word) { return dfs(word, 0, root); } private boolean dfs(String word, int index, TrieNode node) { if (node == null) { return false; } if (index == word.length()) { return node.isEnd; } char c = word.charAt(index); if (c == '.') { for (TrieNode child : node.children.values()) { if (dfs(word, index + 1, child)) { return true; } } return false; } return dfs(word, index + 1, node.children.get(c)); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String wordDictionaryLengthBucketSolutionEntryJson() {
        return """
                    {
                      "name": "Length Bucket Scan Fixture",
                      "timeComplexity": "O(1) add average, O(C * L) search",
                      "spaceComplexity": "O(N * L)",
                      "description": "## Approach\\n\\nGroup words by length and scan only candidates of the same length, treating dots as single-character wildcards.\\n\\n## Key Insight\\n\\nLength filtering enforces complete-word matching before any character comparisons and is a clear baseline for correctness.\\n\\n## Complexity Analysis\\n- addWord Time Complexity: O(1) average\\n- search Time Complexity: O(C * L)\\n- Space Complexity: O(N * L)",
                      "code": "import java.util.*; class WordDictionary { private final Map<Integer, List<String>> byLength; public WordDictionary() { byLength = new HashMap<>(); } public void addWord(String word) { byLength.computeIfAbsent(word.length(), key -> new ArrayList<>()).add(word); } public boolean search(String word) { List<String> candidates = byLength.get(word.length()); if (candidates == null) { return false; } for (String candidate : candidates) { if (matches(candidate, word)) { return true; } } return false; } private boolean matches(String candidate, String pattern) { for (int i = 0; i < pattern.length(); i++) { char p = pattern.charAt(i); if (p != '.' && p != candidate.charAt(i)) { return false; } } return true; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String wordDictionaryPatternIndexSolutionEntryJson() {
        return """
                    {
                      "name": "Two Dot Pattern Index Fixture",
                      "timeComplexity": "O(L^2) add, O(L) search",
                      "spaceComplexity": "O(N * L^2)",
                      "description": "## Approach\\n\\nPrecompute each added word, every one-dot pattern, and every two-dot pattern in a HashSet, then answer search with a set lookup.\\n\\n## Key Insight\\n\\nThe problem limits searches to at most two dots, so quadratic insertion work buys constant-time membership for all legal query shapes.\\n\\n## Complexity Analysis\\n- addWord Time Complexity: O(L^2)\\n- search Time Complexity: O(L)\\n- Space Complexity: O(N * L^2)",
                      "code": "import java.util.*; class WordDictionary { private final Set<String> patterns; public WordDictionary() { patterns = new HashSet<>(); } public void addWord(String word) { patterns.add(word); char[] chars = word.toCharArray(); for (int i = 0; i < chars.length; i++) { char originalI = chars[i]; chars[i] = '.'; patterns.add(new String(chars)); for (int j = i + 1; j < chars.length; j++) { char originalJ = chars[j]; chars[j] = '.'; patterns.add(new String(chars)); chars[j] = originalJ; } chars[i] = originalI; } } public boolean search(String word) { return patterns.contains(word); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

