    private static String replaceWordsArrayTrieSolutionEntryJson() {
        return """
                    {
                      "name": "Array Trie Shortest Root Fixture",
                      "timeComplexity": "O(D * L + S)",
                      "spaceComplexity": "O(D * L)",
                      "description": "## Approach\\n\\nInsert roots into a fixed-array Trie and stop at the first terminal root while scanning a word.\\n\\n## Key Insight\\n\\nThe first terminal node reached from left to right is the shortest matching root.\\n\\n## Complexity Analysis\\n- Time Complexity: O(D * L + S)\\n- Space Complexity: O(D * L)",
                      "code": "import java.util.*; class Solution { static class TrieNode { TrieNode[] children = new TrieNode[26]; String root; } public String replaceWords(List<String> dictionary, String sentence) { TrieNode trieRoot = new TrieNode(); for (String root : dictionary) { insert(trieRoot, root); } return sentence; } void insert(TrieNode trieRoot, String root) { TrieNode node = trieRoot; for (char c : root.toCharArray()) { int idx = c - 'a'; if (node.children[idx] == null) { node.children[idx] = new TrieNode(); } node = node.children[idx]; } node.root = root; } String find(TrieNode trieRoot, String word) { TrieNode node = trieRoot; for (char c : word.toCharArray()) { int idx = c - 'a'; if (node.children[idx] == null) { return word; } node = node.children[idx]; if (node.root != null) { return node.root; } } return word; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String replaceWordsHashMapTrieSolutionEntryJson() {
        return """
                    {
                      "name": "HashMap Trie Fixture",
                      "timeComplexity": "O(D * L + S)",
                      "spaceComplexity": "O(D * L)",
                      "description": "## Approach\\n\\nStore Trie children in HashMaps and return the first terminal root reached for each sentence word.\\n\\n## Key Insight\\n\\nThe map representation avoids unused child slots while preserving shortest-prefix behavior.\\n\\n## Complexity Analysis\\n- Time Complexity: O(D * L + S)\\n- Space Complexity: O(D * L)",
                      "code": "import java.util.*; class Solution { static class TrieNode { Map<Character, TrieNode> children = new HashMap<>(); String root; } public String replaceWords(List<String> dictionary, String sentence) { TrieNode trieRoot = new TrieNode(); for (String root : dictionary) { TrieNode node = trieRoot; for (char c : root.toCharArray()) { node = node.children.computeIfAbsent(c, key -> new TrieNode()); } node.root = root; } return findRoot(trieRoot, sentence); } String findRoot(TrieNode trieRoot, String word) { TrieNode node = trieRoot; for (char c : word.toCharArray()) { node = node.children.get(c); if (node == null) { return word; } if (node.root != null) { return node.root; } } return word; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

