    private static String mapSumPairsTrieDeltaSolutionEntryJson() {
        return """
                    {
                      "name": "Trie Delta Prefix Sum Fixture",
                      "timeComplexity": "O(L)",
                      "spaceComplexity": "O(T)",
                      "description": "## Approach\\n\\nStore every prefix in a fixed-array Trie and add only the value delta when a key is inserted or overwritten.\\n\\n## Key Insight\\n\\nReinserted keys replace their old value, so each prefix node must receive val minus the previous value.\\n\\n## Complexity Analysis\\n- Time Complexity: O(L) per operation\\n- Space Complexity: O(T)",
                      "code": "import java.util.*; class MapSum { static class TrieNode { TrieNode[] children = new TrieNode[26]; int prefixSum; } private final TrieNode root = new TrieNode(); private final Map<String, Integer> values = new HashMap<>(); public void insert(String key, int val) { int delta = val - values.getOrDefault(key, 0); values.put(key, val); TrieNode node = root; for (char c : key.toCharArray()) { int idx = c - 'a'; if (node.children[idx] == null) { node.children[idx] = new TrieNode(); } node = node.children[idx]; node.prefixSum += delta; } } public int sum(String prefix) { TrieNode node = root; for (char c : prefix.toCharArray()) { int idx = c - 'a'; if (node.children[idx] == null) { return 0; } node = node.children[idx]; } return node.prefixSum; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String mapSumPairsPrefixHashMapSolutionEntryJson() {
        return """
                    {
                      "name": "Prefix Sum HashMap Fixture",
                      "timeComplexity": "O(L)",
                      "spaceComplexity": "O(T)",
                      "description": "## Approach\\n\\nKeep one HashMap for exact key values and another HashMap for cached prefix sums.\\n\\n## Key Insight\\n\\nThe same overwrite delta can be applied to every prefix string without storing explicit Trie nodes.\\n\\n## Complexity Analysis\\n- Time Complexity: O(L) per insert, O(1) per sum\\n- Space Complexity: O(T)",
                      "code": "import java.util.*; class MapSum { private final Map<String, Integer> values = new HashMap<>(); private final Map<String, Integer> prefixSums = new HashMap<>(); public void insert(String key, int val) { int delta = val - values.getOrDefault(key, 0); values.put(key, val); for (int end = 1; end <= key.length(); end++) { String prefix = key.substring(0, end); prefixSums.put(prefix, prefixSums.getOrDefault(prefix, 0) + delta); } } public int sum(String prefix) { return prefixSums.getOrDefault(prefix, 0); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

