    private static String kthLargestStreamMinHeapSolutionEntryJson() {
        return """
                    {
                      "name": "Min Heap Fixture",
                      "timeComplexity": "O(log k)",
                      "spaceComplexity": "O(k)",
                      "description": "## Approach\\n\\nKeep a min heap containing the k largest values seen so far.\\n\\n## Key Insight\\n\\nThe smallest value inside that heap is the kth largest value in the full stream.\\n\\n## Complexity Analysis\\n- Time Complexity: O(log k) per add\\n- Space Complexity: O(k)",
                      "code": "import java.util.*; class KthLargest { private final int k; private final PriorityQueue<Integer> heap = new PriorityQueue<>(); public KthLargest(int k, int[] nums) { this.k = k; for (int num : nums) { add(num); } } public int add(int val) { heap.offer(val); if (heap.size() > k) { heap.poll(); } return heap.peek(); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String kthLargestStreamSortedListSolutionEntryJson() {
        return """
                    {
                      "name": "Sorted ArrayList Binary Search Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nKeep all stream values in a sorted ArrayList and binary-search each insertion point.\\n\\n## Key Insight\\n\\nAfter insertion, the kth largest value is at index size minus k in ascending order.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n) per add\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class KthLargest { private final int k; private final List<Integer> values = new ArrayList<>(); public KthLargest(int k, int[] nums) { this.k = k; for (int num : nums) { insertSorted(num); } } public int add(int val) { insertSorted(val); return values.get(values.size() - k); } private void insertSorted(int val) { int index = Collections.binarySearch(values, val); if (index < 0) { index = -index - 1; } values.add(index, val); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String kthLargestStreamTreeMapSolutionEntryJson() {
        return """
                    {
                      "name": "TreeMap Multiset Fixture",
                      "timeComplexity": "O(u)",
                      "spaceComplexity": "O(u)",
                      "description": "## Approach\\n\\nStore value counts in a TreeMap and scan from largest to smallest after each add.\\n\\n## Key Insight\\n\\nCounts let duplicate values occupy multiple kth-largest positions without storing every copy separately.\\n\\n## Complexity Analysis\\n- Time Complexity: O(u) per add\\n- Space Complexity: O(u)",
                      "code": "import java.util.*; class KthLargest { private final int k; private final TreeMap<Integer, Integer> counts = new TreeMap<>(); public KthLargest(int k, int[] nums) { this.k = k; for (int num : nums) { insert(num); } } public int add(int val) { insert(val); int remaining = k; for (Map.Entry<Integer, Integer> entry : counts.descendingMap().entrySet()) { remaining -= entry.getValue(); if (remaining <= 0) { return entry.getKey(); } } return 0; } private void insert(int val) { counts.put(val, counts.getOrDefault(val, 0) + 1); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String kthLargestStreamQuickselectSolutionEntryJson() {
        return """
                    {
                      "name": "Quickselect on Demand Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nAppend values to a list, copy it on each add, and quickselect index size minus k.\\n\\n## Key Insight\\n\\nKth largest is the same as selecting the n minus k index in ascending order.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n) average per add\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class KthLargest { private final int k; private final List<Integer> values = new ArrayList<>(); public KthLargest(int k, int[] nums) { this.k = k; for (int num : nums) { values.add(num); } } public int add(int val) { values.add(val); int[] copy = new int[values.size()]; for (int i = 0; i < values.size(); i++) { copy[i] = values.get(i); } int target = values.size() - k; return quickselect(copy, target); } private int quickselect(int[] nums, int target) { int left = 0; int right = nums.length - 1; while (left <= right) { int pivotIndex = partition(nums, left, right); if (pivotIndex == target) { return nums[pivotIndex]; } if (pivotIndex < target) { left = pivotIndex + 1; } else { right = pivotIndex - 1; } } return nums[target]; } private int partition(int[] nums, int left, int right) { int pivot = nums[right]; return left; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

