    private static String lastStoneWeightMaxHeapSolutionEntryJson() {
        return """
                    {
                      "name": "Max Heap Fixture",
                      "timeComplexity": "O(n log n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nUse a max heap to repeatedly remove the two heaviest stones and push back the difference.\\n\\n## Key Insight\\n\\nThe problem always asks for the current two heaviest stones, which is exactly the max-heap operation.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public int lastStoneWeight(int[] stones) { PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder()); for (int stone : stones) { heap.offer(stone); } while (heap.size() > 1) { int y = heap.poll(); int x = heap.poll(); if (y != x) { heap.offer(y - x); } } return heap.isEmpty() ? 0 : heap.peek(); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String lastStoneWeightSortSimulationSolutionEntryJson() {
        return """
                    {
                      "name": "Sort Simulation Fixture",
                      "timeComplexity": "O(n^2 log n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nSort the remaining stones on every round, remove the two largest, and append the difference.\\n\\n## Key Insight\\n\\nThis route directly mirrors the statement and makes the equal-stone disappearance rule obvious.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2 log n)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public int lastStoneWeight(int[] stones) { List<Integer> remaining = new ArrayList<>(); for (int stone : stones) { remaining.add(stone); } while (remaining.size() > 1) { Collections.sort(remaining); int y = remaining.remove(remaining.size() - 1); int x = remaining.remove(remaining.size() - 1); if (y != x) { remaining.add(y - x); } } return remaining.isEmpty() ? 0 : remaining.get(0); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String lastStoneWeightCountingBucketSolutionEntryJson() {
        return """
                    {
                      "name": "Counting Bucket Fixture",
                      "timeComplexity": "O(nW)",
                      "spaceComplexity": "O(W)",
                      "description": "## Approach\\n\\nCount every possible stone weight in buckets and repeatedly take the largest available bucket entries.\\n\\n## Key Insight\\n\\nWhen weights are bounded, bucket counts can represent both duplicate cancellation and new difference stones.\\n\\n## Complexity Analysis\\n- Time Complexity: O(nW)\\n- Space Complexity: O(W)",
                      "code": "class Solution { public int lastStoneWeight(int[] stones) { int max = 0; for (int stone : stones) { max = Math.max(max, stone); } int[] buckets = new int[max + 1]; for (int stone : stones) { buckets[stone]++; } int current = max; while (true) { int y = takeLargest(buckets, current); if (y == 0) { return 0; } current = Math.min(current, y); int x = takeLargest(buckets, current); if (x == 0) { return y; } if (x != y) { buckets[y - x]++; current = Math.max(current, y - x); } } } private int takeLargest(int[] buckets, int start) { for (int weight = start; weight > 0; weight--) { if (buckets[weight] > 0) { buckets[weight]--; return weight; } } return 0; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String lastStoneWeightTreeMapSolutionEntryJson() {
        return """
                    {
                      "name": "TreeMap Multiset Fixture",
                      "timeComplexity": "O(n log u)",
                      "spaceComplexity": "O(u)",
                      "description": "## Approach\\n\\nUse a TreeMap as a sorted multiset, remove the largest key twice, and reinsert the difference.\\n\\n## Key Insight\\n\\nTreeMap keeps duplicate counts compact while still giving direct access to the current largest weight.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log u)\\n- Space Complexity: O(u)",
                      "code": "import java.util.*; class Solution { public int lastStoneWeight(int[] stones) { TreeMap<Integer, Integer> counts = new TreeMap<>(); int total = 0; for (int stone : stones) { counts.put(stone, counts.getOrDefault(stone, 0) + 1); total++; } while (total > 1) { int y = removeLargest(counts); int x = removeLargest(counts); total -= 2; if (y != x) { counts.put(y - x, counts.getOrDefault(y - x, 0) + 1); total++; } } return total == 0 ? 0 : counts.lastKey(); } private int removeLargest(TreeMap<Integer, Integer> counts) { int weight = counts.lastKey(); int count = counts.get(weight); if (count == 1) { counts.remove(weight); } else { counts.put(weight, count - 1); } return weight; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

