    private static String designTwitterBoundedMinHeapSolutionEntryJson() {
        return """
                    {
                      "name": "Bounded Min Heap Fixture",
                      "timeComplexity": "O(M log 10)",
                      "spaceComplexity": "O(T + F)",
                      "description": "## Approach\\n\\nScan visible tweet lists and keep only the ten newest candidates in a min heap.\\n\\n## Key Insight\\n\\nThe heap is bounded at ten, so old visible tweets cannot force a full sort.\\n\\n## Complexity Analysis\\n- Time Complexity: O(M log 10)\\n- Space Complexity: O(T + F)",
                      "code": "import java.util.*; class Twitter { private Map<Integer, List<int[]>> tweets = new HashMap<>(); private Map<Integer, Set<Integer>> following = new HashMap<>(); private int timestamp = 0; public Twitter() {} public void postTweet(int userId, int tweetId) { tweets.computeIfAbsent(userId, ignored -> new ArrayList<>()).add(new int[] {timestamp++, tweetId}); } public List<Integer> getNewsFeed(int userId) { PriorityQueue<int[]> minHeap = new PriorityQueue<>(Comparator.comparingInt(a -> a[0])); addVisibleTweets(userId, minHeap); for (int followeeId : following.getOrDefault(userId, Collections.emptySet())) { addVisibleTweets(followeeId, minHeap); } List<int[]> newest = new ArrayList<>(minHeap); newest.sort((a, b) -> Integer.compare(b[0], a[0])); List<Integer> feed = new ArrayList<>(); for (int[] tweet : newest) { feed.add(tweet[1]); } return feed; } private void addVisibleTweets(int userId, PriorityQueue<int[]> minHeap) { for (int[] tweet : tweets.getOrDefault(userId, Collections.emptyList())) { minHeap.offer(tweet); if (minHeap.size() > 10) { minHeap.poll(); } } } public void follow(int followerId, int followeeId) { if (followerId == followeeId) return; following.computeIfAbsent(followerId, ignored -> new HashSet<>()).add(followeeId); } public void unfollow(int followerId, int followeeId) { Set<Integer> followees = following.get(followerId); if (followees != null) followees.remove(followeeId); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String designTwitterKWayMergeSolutionEntryJson() {
        return """
                    {
                      "name": "Per-User Linked Lists k-Way Merge Fixture",
                      "timeComplexity": "O(10 log U)",
                      "spaceComplexity": "O(T + F)",
                      "description": "## Approach\\n\\nStore each user stream as a newest-first linked list and merge list heads with a max heap.\\n\\n## Key Insight\\n\\nEach user list is already sorted, so feed construction is a k-way merge rather than a full scan.\\n\\n## Complexity Analysis\\n- Time Complexity: O(10 log U)\\n- Space Complexity: O(T + F)",
                      "code": "import java.util.*; class Twitter { private static class Tweet { int id; int timestamp; Tweet next; Tweet(int id, int timestamp) { this.id = id; this.timestamp = timestamp; } } private Map<Integer, Tweet> tweetHeads = new HashMap<>(); private Map<Integer, Set<Integer>> following = new HashMap<>(); private int timestamp = 0; public Twitter() {} public void postTweet(int userId, int tweetId) { Tweet tweet = new Tweet(tweetId, timestamp++); tweet.next = tweetHeads.get(userId); tweetHeads.put(userId, tweet); } public List<Integer> getNewsFeed(int userId) { PriorityQueue<Tweet> maxHeap = new PriorityQueue<>((a, b) -> Integer.compare(b.timestamp, a.timestamp)); Tweet ownHead = tweetHeads.get(userId); if (ownHead != null) maxHeap.offer(ownHead); for (int followeeId : following.getOrDefault(userId, Collections.emptySet())) { Tweet followeeHead = tweetHeads.get(followeeId); if (followeeHead != null) maxHeap.offer(followeeHead); } List<Integer> feed = new ArrayList<>(); while (!maxHeap.isEmpty() && feed.size() < 10) { Tweet newest = maxHeap.poll(); feed.add(newest.id); if (newest.next != null) { maxHeap.offer(newest.next); } } return feed; } public void follow(int followerId, int followeeId) { if (followerId == followeeId) return; following.computeIfAbsent(followerId, ignored -> new HashSet<>()).add(followeeId); } public void unfollow(int followerId, int followeeId) { Set<Integer> followees = following.get(followerId); if (followees != null) followees.remove(followeeId); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String designTwitterTimelineScanSolutionEntryJson() {
        return """
                    {
                      "name": "Global Timeline Reverse Scan Fixture",
                      "timeComplexity": "O(T)",
                      "spaceComplexity": "O(T + F)",
                      "description": "## Approach\\n\\nKeep one append-only timeline and scan it backward for visible tweets.\\n\\n## Key Insight\\n\\nThe current follow set decides visibility, while reverse timeline order supplies recency.\\n\\n## Complexity Analysis\\n- Time Complexity: O(T)\\n- Space Complexity: O(T + F)",
                      "code": "import java.util.*; class Twitter { private static class Tweet { int userId; int tweetId; Tweet(int userId, int tweetId) { this.userId = userId; this.tweetId = tweetId; } } private List<Tweet> timeline = new ArrayList<>(); private Map<Integer, Set<Integer>> following = new HashMap<>(); public Twitter() {} public void postTweet(int userId, int tweetId) { timeline.add(new Tweet(userId, tweetId)); } public List<Integer> getNewsFeed(int userId) { Set<Integer> followees = following.getOrDefault(userId, Collections.emptySet()); List<Integer> feed = new ArrayList<>(); for (int i = timeline.size() - 1; i >= 0 && feed.size() < 10; i--) { Tweet tweet = timeline.get(i); if (tweet.userId == userId || followees.contains(tweet.userId)) { feed.add(tweet.tweetId); } } return feed; } public void follow(int followerId, int followeeId) { if (followerId == followeeId) return; following.computeIfAbsent(followerId, ignored -> new HashSet<>()).add(followeeId); } public void unfollow(int followerId, int followeeId) { Set<Integer> followees = following.get(followerId); if (followees != null) followees.remove(followeeId); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String designTwitterFanOutCacheSolutionEntryJson() {
        return """
                    {
                      "name": "Fan-Out Feed Cache Fixture",
                      "timeComplexity": "O(R) for rebuilds and O(10) per feed read",
                      "spaceComplexity": "O(T + F + 10U)",
                      "description": "## Approach\\n\\nPush new tweets into cached feeds and rebuild one feed when follow state changes.\\n\\n## Key Insight\\n\\nThis is the write-time fan-out tradeoff: reads are cheap, but follow changes need a careful rebuild.\\n\\n## Complexity Analysis\\n- Time Complexity: O(R) for rebuilds and O(10) per feed read\\n- Space Complexity: O(T + F + 10U)",
                      "code": "import java.util.*; class Twitter { private static class Tweet { int userId; int tweetId; Tweet(int userId, int tweetId) { this.userId = userId; this.tweetId = tweetId; } } private List<Tweet> timeline = new ArrayList<>(); private Map<Integer, Set<Integer>> following = new HashMap<>(); private Map<Integer, Set<Integer>> followers = new HashMap<>(); private Map<Integer, Deque<Tweet>> feedCache = new HashMap<>(); public Twitter() {} public void postTweet(int userId, int tweetId) { Tweet tweet = new Tweet(userId, tweetId); timeline.add(tweet); pushToCachedFeed(userId, tweet); for (int followerId : followers.getOrDefault(userId, Collections.emptySet())) { pushToCachedFeed(followerId, tweet); } } public List<Integer> getNewsFeed(int userId) { List<Integer> feed = new ArrayList<>(); for (Tweet tweet : feedCache.getOrDefault(userId, new ArrayDeque<>())) { feed.add(tweet.tweetId); if (feed.size() == 10) break; } return feed; } public void follow(int followerId, int followeeId) { if (followerId == followeeId) return; boolean added = following.computeIfAbsent(followerId, ignored -> new HashSet<>()).add(followeeId); if (!added) return; followers.computeIfAbsent(followeeId, ignored -> new HashSet<>()).add(followerId); rebuildFeed(followerId); } public void unfollow(int followerId, int followeeId) { Set<Integer> followees = following.get(followerId); if (followees == null || !followees.remove(followeeId)) return; Set<Integer> followerSet = followers.get(followeeId); if (followerSet != null) followerSet.remove(followerId); rebuildFeed(followerId); } private void pushToCachedFeed(int userId, Tweet tweet) { Deque<Tweet> feed = feedCache.computeIfAbsent(userId, ignored -> new ArrayDeque<>()); feed.addFirst(tweet); while (feed.size() > 10) { feed.removeLast(); } } private void rebuildFeed(int userId) { Deque<Tweet> feed = new ArrayDeque<>(); Set<Integer> followees = following.getOrDefault(userId, Collections.emptySet()); for (int i = timeline.size() - 1; i >= 0 && feed.size() < 10; i--) { Tweet tweet = timeline.get(i); if (tweet.userId == userId || followees.contains(tweet.userId)) { feed.addLast(tweet); } } feedCache.put(userId, feed); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

