    private static String medianDataStreamTreeMapSolutionEntryJson() {
        return """
                    {
                      "name": "TreeMap Ordered Multiset Fixture",
                      "timeComplexity": "O(log u) addNum and O(u) findMedian",
                      "spaceComplexity": "O(u)",
                      "description": "## Approach\\n\\nStore frequencies in a TreeMap and walk ordered counts to the middle rank.\\n\\n## Key Insight\\n\\nDuplicates are preserved as counts, so the median is a rank in an ordered multiset.\\n\\n## Complexity Analysis\\n- Time Complexity: O(log u) addNum and O(u) findMedian\\n- Space Complexity: O(u)",
                      "code": "import java.util.*; class MedianFinder { private TreeMap<Integer, Integer> counts = new TreeMap<>(); private int size = 0; public MedianFinder() {} public void addNum(int num) { counts.put(num, counts.getOrDefault(num, 0) + 1); size++; } public double findMedian() { if (size % 2 == 1) { return kth(size / 2 + 1); } int left = kth(size / 2); int right = kth(size / 2 + 1); return left / 2.0 + right / 2.0; } private int kth(int rank) { int seen = 0; for (Map.Entry<Integer, Integer> entry : counts.entrySet()) { seen += entry.getValue(); if (seen >= rank) { return entry.getKey(); } } throw new IllegalStateException(); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String medianDataStreamFenwickSolutionEntryJson() {
        return """
                    {
                      "name": "Fenwick Tree Bounded Value Fixture",
                      "timeComplexity": "O(log R)",
                      "spaceComplexity": "O(R)",
                      "description": "## Approach\\n\\nMap the fixed value range into Fenwick-tree indices and query the middle rank by prefix counts.\\n\\n## Key Insight\\n\\nA fixed value range turns median lookup into an order-statistics query over frequencies.\\n\\n## Complexity Analysis\\n- Time Complexity: O(log R)\\n- Space Complexity: O(R)",
                      "code": "class MedianFinder { private static final int OFFSET = 100000; private static final int SIZE = 200001; private int[] tree = new int[SIZE + 1]; private int count = 0; public MedianFinder() {} public void addNum(int num) { add(num + OFFSET + 1, 1); count++; } public double findMedian() { if (count % 2 == 1) { return valueAtRank(count / 2 + 1); } int left = valueAtRank(count / 2); int right = valueAtRank(count / 2 + 1); return left / 2.0 + right / 2.0; } private void add(int index, int delta) { while (index <= SIZE) { tree[index] += delta; index += index & -index; } } private int valueAtRank(int rank) { int index = 0; int bit = Integer.highestOneBit(SIZE); while (bit != 0) { int next = index + bit; if (next <= SIZE && tree[next] < rank) { index = next; rank -= tree[next]; } bit >>= 1; } return index + 1 - OFFSET - 1; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

