    private static String smallestRangeMinHeapSolutionEntryJson() {
        return """
                    {
                      "name": "Min Heap with Current Maximum Fixture",
                      "timeComplexity": "O(N log k)",
                      "spaceComplexity": "O(k)",
                      "description": "## Approach\\n\\nPut one candidate from every list in a min heap and track the current maximum.\\n\\n## Key Insight\\n\\nThe heap minimum is the only side that can move inward while preserving one value from every list.\\n\\n## Complexity Analysis\\n- Time Complexity: O(N log k)\\n- Space Complexity: O(k)",
                      "code": "import java.util.*; class Solution { public int[] smallestRange(int[][] nums) { int k = nums.length; PriorityQueue<int[]> minHeap = new PriorityQueue<>(Comparator.comparingInt(a -> a[0])); int currentMax = Integer.MIN_VALUE; for (int listIndex = 0; listIndex < k; listIndex++) { int value = nums[listIndex][0]; minHeap.offer(new int[]{value, listIndex, 0}); currentMax = Math.max(currentMax, value); } int bestLeft = minHeap.peek()[0]; int bestRight = currentMax; while (minHeap.size() == k) { int[] smallest = minHeap.poll(); int currentMin = smallest[0]; if (isBetter(currentMin, currentMax, bestLeft, bestRight)) { bestLeft = currentMin; bestRight = currentMax; } int nextIndex = smallest[2] + 1; int listIndex = smallest[1]; if (nextIndex == nums[listIndex].length) { break; } int nextValue = nums[listIndex][nextIndex]; minHeap.offer(new int[]{nextValue, listIndex, nextIndex}); currentMax = Math.max(currentMax, nextValue); } return new int[]{bestLeft, bestRight}; } private boolean isBetter(int left, int right, int bestLeft, int bestRight) { return right - left < bestRight - bestLeft || (right - left == bestRight - bestLeft && left < bestLeft); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String smallestRangeMergedWindowSolutionEntryJson() {
        return """
                    {
                      "name": "Merged Sorted List with Sliding Window Fixture",
                      "timeComplexity": "O(N log N)",
                      "spaceComplexity": "O(N)",
                      "description": "## Approach\\n\\nFlatten values with their list id, sort them, and shrink a window that covers every list.\\n\\n## Key Insight\\n\\nAfter merging, this is a minimum window that must contain every list color at least once.\\n\\n## Complexity Analysis\\n- Time Complexity: O(N log N)\\n- Space Complexity: O(N)",
                      "code": "import java.util.*; class Solution { public int[] smallestRange(int[][] nums) { int k = nums.length; List<int[]> merged = new ArrayList<>(); for (int listIndex = 0; listIndex < k; listIndex++) { for (int value : nums[listIndex]) { merged.add(new int[]{value, listIndex}); } } merged.sort(Comparator.comparingInt(a -> a[0])); int[] frequency = new int[k]; int covered = 0; int bestLeft = 0; int bestRight = Integer.MAX_VALUE; int left = 0; for (int right = 0; right < merged.size(); right++) { int rightList = merged.get(right)[1]; if (frequency[rightList]++ == 0) { covered++; } while (covered == k) { int rangeLeft = merged.get(left)[0]; int rangeRight = merged.get(right)[0]; if (isBetter(rangeLeft, rangeRight, bestLeft, bestRight)) { bestLeft = rangeLeft; bestRight = rangeRight; } int leftList = merged.get(left)[1]; frequency[leftList]--; if (frequency[leftList] == 0) { covered--; } left++; } } return new int[]{bestLeft, bestRight}; } private boolean isBetter(int left, int right, int bestLeft, int bestRight) { return right - left < bestRight - bestLeft || (right - left == bestRight - bestLeft && left < bestLeft); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String smallestRangeLeftBoundSolutionEntryJson() {
        return """
                    {
                      "name": "Enumerate Left Bound with Binary Search Fixture",
                      "timeComplexity": "O(N * k * log m)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nTry every value as the left endpoint and binary-search the first usable value in each list.\\n\\n## Key Insight\\n\\nFor a fixed left endpoint, picking the first value not below it minimizes the right endpoint.\\n\\n## Complexity Analysis\\n- Time Complexity: O(N * k * log m)\\n- Space Complexity: O(1)",
                      "code": "class Solution { public int[] smallestRange(int[][] nums) { int bestLeft = 0; int bestRight = Integer.MAX_VALUE; for (int[] sourceList : nums) { for (int left : sourceList) { int right = left; boolean valid = true; for (int[] list : nums) { int index = lowerBound(list, left); if (index == list.length) { valid = false; break; } right = Math.max(right, list[index]); } if (valid && isBetter(left, right, bestLeft, bestRight)) { bestLeft = left; bestRight = right; } } } return new int[]{bestLeft, bestRight}; } private int lowerBound(int[] list, int target) { int low = 0; int high = list.length; while (low < high) { int mid = low + (high - low) / 2; if (list[mid] < target) { low = mid + 1; } else { high = mid; } } return low; } private boolean isBetter(int left, int right, int bestLeft, int bestRight) { return right - left < bestRight - bestLeft || (right - left == bestRight - bestLeft && left < bestLeft); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String smallestRangeKPointersSolutionEntryJson() {
        return """
                    {
                      "name": "K Pointers Greedy Scan Fixture",
                      "timeComplexity": "O(N * k)",
                      "spaceComplexity": "O(k)",
                      "description": "## Approach\\n\\nKeep one pointer in every list, scan current values, and advance the list that owns the minimum.\\n\\n## Key Insight\\n\\nThis is the heap greedy movement without the heap optimization, so it makes the correctness idea explicit.\\n\\n## Complexity Analysis\\n- Time Complexity: O(N * k)\\n- Space Complexity: O(k)",
                      "code": "class Solution { public int[] smallestRange(int[][] nums) { int k = nums.length; int[] indices = new int[k]; int bestLeft = 0; int bestRight = Integer.MAX_VALUE; while (true) { int minList = 0; int currentMin = Integer.MAX_VALUE; int currentMax = Integer.MIN_VALUE; for (int i = 0; i < k; i++) { int value = nums[i][indices[i]]; if (value < currentMin) { currentMin = value; minList = i; } currentMax = Math.max(currentMax, value); } if (isBetter(currentMin, currentMax, bestLeft, bestRight)) { bestLeft = currentMin; bestRight = currentMax; } indices[minList]++; if (indices[minList] == nums[minList].length) { break; } } return new int[]{bestLeft, bestRight}; } private boolean isBetter(int left, int right, int bestLeft, int bestRight) { return right - left < bestRight - bestLeft || (right - left == bestRight - bestLeft && left < bestLeft); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

