    private static String topKFrequentWordsFullSortSolutionEntryJson() {
        return """
                    {
                      "name": "HashMap Count and Full Sort Fixture",
                      "timeComplexity": "O(n + u log u)",
                      "spaceComplexity": "O(u)",
                      "description": "## Approach\\n\\nCount every word, sort all unique words by the final answer order, and return the first k.\\n\\n## Key Insight\\n\\nThe comparator must encode descending frequency first and lexicographic order second.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n + u log u)\\n- Space Complexity: O(u)",
                      "code": "import java.util.*; class Solution { public List<String> topKFrequent(String[] words, int k) { Map<String, Integer> frequency = new HashMap<>(); for (String word : words) { frequency.put(word, frequency.getOrDefault(word, 0) + 1); } List<String> unique = new ArrayList<>(frequency.keySet()); unique.sort((a, b) -> { int byCount = Integer.compare(frequency.get(b), frequency.get(a)); if (byCount != 0) { return byCount; } return a.compareTo(b); }); return new ArrayList<>(unique.subList(0, k)); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String topKFrequentWordsMinHeapSolutionEntryJson() {
        return """
                    {
                      "name": "Size K Min Heap Fixture",
                      "timeComplexity": "O(n + u log k)",
                      "spaceComplexity": "O(u + k)",
                      "description": "## Approach\\n\\nKeep a min heap of the current best k words and remove the weakest candidate when the heap grows too large.\\n\\n## Key Insight\\n\\nFor equal frequency, the lexicographically larger word is weaker and should leave the heap first.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n + u log k)\\n- Space Complexity: O(u + k)",
                      "code": "import java.util.*; class Solution { public List<String> topKFrequent(String[] words, int k) { Map<String, Integer> frequency = new HashMap<>(); for (String word : words) { frequency.put(word, frequency.getOrDefault(word, 0) + 1); } PriorityQueue<String> heap = new PriorityQueue<>((a, b) -> { int byCount = Integer.compare(frequency.get(a), frequency.get(b)); if (byCount != 0) { return byCount; } return b.compareTo(a); }); for (String word : frequency.keySet()) { heap.offer(word); if (heap.size() > k) { heap.poll(); } } LinkedList<String> result = new LinkedList<>(); while (!heap.isEmpty()) { result.addFirst(heap.poll()); } return result; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

