    private static String kSmallestPairsRowFrontierSolutionEntryJson() {
        return """
                    {
                      "name": "Row Frontier Min Heap Fixture",
                      "timeComplexity": "O(k log min(m, k))",
                      "spaceComplexity": "O(min(m, k))",
                      "description": "## Approach\\n\\nKeep one heap entry for the next unseen pair in each active row and advance that row after a pair is output.\\n\\n## Key Insight\\n\\nEach row is sorted by sum, so the heap merges sorted row frontiers while long sums prevent overflow.\\n\\n## Complexity Analysis\\n- Time Complexity: O(k log min(m, k))\\n- Space Complexity: O(min(m, k))",
                      "code": "import java.util.*; class Solution { public List<List<Integer>> kSmallestPairs(int[] nums1, int[] nums2, int k) { List<List<Integer>> result = new ArrayList<>(); PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> compare(a, b, nums1, nums2)); int rows = Math.min(nums1.length, k); for (int i = 0; i < rows; i++) { heap.offer(new int[]{i, 0}); } while (!heap.isEmpty() && result.size() < k) { int[] cell = heap.poll(); int i = cell[0]; int j = cell[1]; result.add(Arrays.asList(nums1[i], nums2[j])); if (j + 1 < nums2.length) { heap.offer(new int[]{i, j + 1}); } } return result; } private int compare(int[] a, int[] b, int[] nums1, int[] nums2) { long sumA = (long) nums1[a[0]] + nums2[a[1]]; long sumB = (long) nums1[b[0]] + nums2[b[1]]; int bySum = Long.compare(sumA, sumB); if (bySum != 0) { return bySum; } int byFirst = Integer.compare(nums1[a[0]], nums1[b[0]]); if (byFirst != 0) { return byFirst; } int bySecond = Integer.compare(nums2[a[1]], nums2[b[1]]); if (bySecond != 0) { return bySecond; } int byRow = Integer.compare(a[0], b[0]); if (byRow != 0) { return byRow; } return Integer.compare(a[1], b[1]); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String kSmallestPairsBestFirstGridSolutionEntryJson() {
        return """
                    {
                      "name": "Best-First Grid Expansion Fixture",
                      "timeComplexity": "O(k log k)",
                      "spaceComplexity": "O(k)",
                      "description": "## Approach\\n\\nStart at grid cell (0,0), pop the smallest seen cell, and push its down and right neighbors once.\\n\\n## Key Insight\\n\\nThe sorted arrays make every down or right move monotone, so a visited-set heap frontier emits cells in increasing pair order.\\n\\n## Complexity Analysis\\n- Time Complexity: O(k log k)\\n- Space Complexity: O(k)",
                      "code": "import java.util.*; class Solution { public List<List<Integer>> kSmallestPairs(int[] nums1, int[] nums2, int k) { List<List<Integer>> result = new ArrayList<>(); PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> compare(a, b, nums1, nums2)); Set<Long> seen = new HashSet<>(); offer(heap, seen, 0, 0, nums1.length, nums2.length); while (!heap.isEmpty() && result.size() < k) { int[] cell = heap.poll(); int i = cell[0]; int j = cell[1]; result.add(Arrays.asList(nums1[i], nums2[j])); offer(heap, seen, i + 1, j, nums1.length, nums2.length); offer(heap, seen, i, j + 1, nums1.length, nums2.length); } return result; } private void offer(PriorityQueue<int[]> heap, Set<Long> seen, int i, int j, int m, int n) { if (i >= m || j >= n) { return; } long key = (((long) i) << 32) ^ (j & 0xffffffffL); if (seen.add(key)) { heap.offer(new int[]{i, j}); } } private int compare(int[] a, int[] b, int[] nums1, int[] nums2) { long sumA = (long) nums1[a[0]] + nums2[a[1]]; long sumB = (long) nums1[b[0]] + nums2[b[1]]; int bySum = Long.compare(sumA, sumB); if (bySum != 0) { return bySum; } int byFirst = Integer.compare(nums1[a[0]], nums1[b[0]]); if (byFirst != 0) { return byFirst; } int bySecond = Integer.compare(nums2[a[1]], nums2[b[1]]); if (bySecond != 0) { return bySecond; } int byRow = Integer.compare(a[0], b[0]); if (byRow != 0) { return byRow; } return Integer.compare(a[1], b[1]); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String kSmallestPairsBoundedCandidateSolutionEntryJson() {
        return """
                    {
                      "name": "Bounded Candidate Sort Baseline Fixture",
                      "timeComplexity": "O(k^2 log k)",
                      "spaceComplexity": "O(k^2)",
                      "description": "## Approach\\n\\nGenerate the first-k by first-k candidate rectangle, sort by the required pair order, and return the prefix.\\n\\n## Key Insight\\n\\nNo pair outside that bounded rectangle can be needed before k choices from the same side have appeared.\\n\\n## Complexity Analysis\\n- Time Complexity: O(k^2 log k)\\n- Space Complexity: O(k^2)",
                      "code": "import java.util.*; class Solution { public List<List<Integer>> kSmallestPairs(int[] nums1, int[] nums2, int k) { List<int[]> candidates = new ArrayList<>(); int limit1 = Math.min(nums1.length, k); int limit2 = Math.min(nums2.length, k); for (int i = 0; i < limit1; i++) { for (int j = 0; j < limit2; j++) { candidates.add(new int[]{i, j}); } } candidates.sort((a, b) -> compare(a, b, nums1, nums2)); List<List<Integer>> result = new ArrayList<>(); int limit = Math.min(k, candidates.size()); for (int index = 0; index < limit; index++) { int[] cell = candidates.get(index); result.add(Arrays.asList(nums1[cell[0]], nums2[cell[1]])); } return result; } private int compare(int[] a, int[] b, int[] nums1, int[] nums2) { long sumA = (long) nums1[a[0]] + nums2[a[1]]; long sumB = (long) nums1[b[0]] + nums2[b[1]]; int bySum = Long.compare(sumA, sumB); if (bySum != 0) { return bySum; } int byFirst = Integer.compare(nums1[a[0]], nums1[b[0]]); if (byFirst != 0) { return byFirst; } int bySecond = Integer.compare(nums2[a[1]], nums2[b[1]]); if (bySecond != 0) { return bySecond; } int byRow = Integer.compare(a[0], b[0]); if (byRow != 0) { return byRow; } return Integer.compare(a[1], b[1]); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String kSmallestPairsBinarySearchSolutionEntryJson() {
        return """
                    {
                      "name": "Binary Search Sum Threshold Fixture",
                      "timeComplexity": "O((m+n) log W + k log k)",
                      "spaceComplexity": "O(min(m, k))",
                      "description": "## Approach\\n\\nBinary search the kth sum threshold with two-pointer counting, then run a limited heap merge below that threshold.\\n\\n## Key Insight\\n\\nCounting pairs with sum at most x is monotonic, but the final answer still needs an ordered merge of concrete pairs.\\n\\n## Complexity Analysis\\n- Time Complexity: O((m+n) log W + k log k)\\n- Space Complexity: O(min(m, k))",
                      "code": "import java.util.*; class Solution { public List<List<Integer>> kSmallestPairs(int[] nums1, int[] nums2, int k) { List<List<Integer>> result = new ArrayList<>(); int target = (int) Math.min((long) k, (long) nums1.length * nums2.length); long low = (long) nums1[0] + nums2[0]; long high = (long) nums1[nums1.length - 1] + nums2[nums2.length - 1]; while (low < high) { long mid = low + (high - low) / 2; if (countAtMost(nums1, nums2, mid, target) >= target) { high = mid; } else { low = mid + 1; } } long threshold = low; PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> compare(a, b, nums1, nums2)); for (int i = 0; i < nums1.length && i < target; i++) { if ((long) nums1[i] + nums2[0] > threshold) { break; } heap.offer(new int[]{i, 0}); } while (!heap.isEmpty() && result.size() < target) { int[] cell = heap.poll(); int i = cell[0]; int j = cell[1]; result.add(Arrays.asList(nums1[i], nums2[j])); if (j + 1 < nums2.length && (long) nums1[i] + nums2[j + 1] <= threshold) { heap.offer(new int[]{i, j + 1}); } } return result; } private long countAtMost(int[] nums1, int[] nums2, long limit, int stopAt) { long count = 0; int j = nums2.length - 1; for (int value : nums1) { while (j >= 0 && (long) value + nums2[j] > limit) { j--; } count += j + 1L; if (count >= stopAt) { return count; } } return count; } private int compare(int[] a, int[] b, int[] nums1, int[] nums2) { long sumA = (long) nums1[a[0]] + nums2[a[1]]; long sumB = (long) nums1[b[0]] + nums2[b[1]]; int bySum = Long.compare(sumA, sumB); if (bySum != 0) { return bySum; } int byFirst = Integer.compare(nums1[a[0]], nums1[b[0]]); if (byFirst != 0) { return byFirst; } int bySecond = Integer.compare(nums2[a[1]], nums2[b[1]]); if (bySecond != 0) { return bySecond; } int byRow = Integer.compare(a[0], b[0]); if (byRow != 0) { return byRow; } return Integer.compare(a[1], b[1]); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

