    private static String combinationSumStartIndexSolutionEntryJson() {
        return """
                    {
                      "name": "Sorted Start Index Backtracking Fixture",
                      "timeComplexity": "O(C * L)",
                      "spaceComplexity": "O(L)",
                      "description": "## Approach\\n\\nSort candidates and recurse from a start index while keeping the same index after choosing a reusable value.\\n\\n## Key Insight\\n\\nThe start index prevents duplicate permutations, and sorting lets the loop stop when a candidate is larger than the remaining target.\\n\\n## Complexity Analysis\\n- Time Complexity: O(C * L)\\n- Space Complexity: O(L)",
                      "code": "import java.util.*; class Solution { public List<List<Integer>> combinationSum(int[] candidates, int target) { Arrays.sort(candidates); List<List<Integer>> answer = new ArrayList<>(); backtrack(candidates, target, 0, new ArrayList<>(), answer); return answer; } private void backtrack(int[] candidates, int remain, int start, List<Integer> path, List<List<Integer>> answer) { if (remain == 0) { answer.add(new ArrayList<>(path)); return; } for (int i = start; i < candidates.length; i++) { if (candidates[i] > remain) { break; } path.add(candidates[i]); backtrack(candidates, remain - candidates[i], i, path, answer); path.remove(path.size() - 1); } } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String combinationSumIncludeSkipSolutionEntryJson() {
        return """
                    {
                      "name": "Include or Skip Recursion Fixture",
                      "timeComplexity": "O(C * L)",
                      "spaceComplexity": "O(L + n)",
                      "description": "## Approach\\n\\nAt each candidate index either include the value again or skip it and advance to the next index.\\n\\n## Key Insight\\n\\nThe include branch stays on the same index, which is the direct expression of unlimited reuse.\\n\\n## Complexity Analysis\\n- Time Complexity: O(C * L)\\n- Space Complexity: O(L + n)",
                      "code": "import java.util.*; class Solution { public List<List<Integer>> combinationSum(int[] candidates, int target) { Arrays.sort(candidates); List<List<Integer>> answer = new ArrayList<>(); dfs(candidates, 0, target, new ArrayList<>(), answer); return answer; } private void dfs(int[] candidates, int index, int remain, List<Integer> path, List<List<Integer>> answer) { if (remain == 0) { answer.add(new ArrayList<>(path)); return; } if (index == candidates.length || candidates[index] > remain) { return; } path.add(candidates[index]); dfs(candidates, index, remain - candidates[index], path, answer); path.remove(path.size() - 1); dfs(candidates, index + 1, remain, path, answer); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String combinationSumDpSolutionEntryJson() {
        return """
                    {
                      "name": "Bottom Up Combination DP Fixture",
                      "timeComplexity": "O(n * target * C)",
                      "spaceComplexity": "O(target * C)",
                      "description": "## Approach\\n\\nStore every nondecreasing combination for each sum and extend those lists candidate by candidate.\\n\\n## Key Insight\\n\\nProcessing candidates in sorted outer-loop order allows reuse while preventing the same multiset from appearing in different orders.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * target * C)\\n- Space Complexity: O(target * C)",
                      "code": "import java.util.*; class Solution { public List<List<Integer>> combinationSum(int[] candidates, int target) { Arrays.sort(candidates); List<List<List<Integer>>> dp = new ArrayList<>(); for (int sum = 0; sum <= target; sum++) { dp.add(new ArrayList<>()); } dp.get(0).add(new ArrayList<>()); for (int candidate : candidates) { for (int sum = candidate; sum <= target; sum++) { for (List<Integer> previous : dp.get(sum - candidate)) { if (!previous.isEmpty() && previous.get(previous.size() - 1) > candidate) { continue; } List<Integer> next = new ArrayList<>(previous); next.add(candidate); dp.get(sum).add(next); } } } return dp.get(target); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String combinationSumQueueSolutionEntryJson() {
        return """
                    {
                      "name": "Explicit Queue Search Fixture",
                      "timeComplexity": "O(S * L)",
                      "spaceComplexity": "O(S * L)",
                      "description": "## Approach\\n\\nPut unfinished combinations into a queue with their next allowed index, remaining target, and copied path.\\n\\n## Key Insight\\n\\nThe queue traverses the same state space as recursive backtracking while making the state transition explicit.\\n\\n## Complexity Analysis\\n- Time Complexity: O(S * L)\\n- Space Complexity: O(S * L)",
                      "code": "import java.util.*; class Solution { private static class State { int start; int remain; List<Integer> path; State(int start, int remain, List<Integer> path) { this.start = start; this.remain = remain; this.path = path; } } public List<List<Integer>> combinationSum(int[] candidates, int target) { Arrays.sort(candidates); List<List<Integer>> answer = new ArrayList<>(); Queue<State> queue = new ArrayDeque<>(); queue.offer(new State(0, target, new ArrayList<>())); while (!queue.isEmpty()) { State state = queue.poll(); if (state.remain == 0) { answer.add(state.path); continue; } for (int i = state.start; i < candidates.length; i++) { if (candidates[i] > state.remain) { break; } List<Integer> nextPath = new ArrayList<>(state.path); nextPath.add(candidates[i]); queue.offer(new State(i, state.remain - candidates[i], nextPath)); } } return answer; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

