    private static String permutationsSwapSolutionEntryJson() {
        return """
                    {
                      "name": "In-place Swap Backtracking Fixture",
                      "timeComplexity": "O(n * n!)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nSwap each remaining value into the current start position, recurse, then swap back.\\n\\n## Key Insight\\n\\nThe fixed prefix grows by one each level while the suffix still contains every value that can be placed next.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * n!)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public List<List<Integer>> permute(int[] nums) { List<List<Integer>> answer = new ArrayList<>(); backtrack(nums, 0, answer); return answer; } private void backtrack(int[] nums, int start, List<List<Integer>> answer) { if (start == nums.length) { answer.add(toList(nums)); return; } for (int i = start; i < nums.length; i++) { swap(nums, start, i); backtrack(nums, start + 1, answer); swap(nums, start, i); } } private List<Integer> toList(int[] nums) { List<Integer> list = new ArrayList<>(); for (int value : nums) { list.add(value); } return list; } private void swap(int[] nums, int a, int b) { int temp = nums[a]; nums[a] = nums[b]; nums[b] = temp; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String permutationsUsedArraySolutionEntryJson() {
        return """
                    {
                      "name": "Used Array Backtracking Fixture",
                      "timeComplexity": "O(n * n!)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nBuild a path and use a boolean array to skip values already present in that path.\\n\\n## Key Insight\\n\\nThe used array directly encodes the rule that every input index can appear at most once in a permutation.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * n!)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public List<List<Integer>> permute(int[] nums) { List<List<Integer>> answer = new ArrayList<>(); boolean[] used = new boolean[nums.length]; backtrack(nums, used, new ArrayList<>(), answer); return answer; } private void backtrack(int[] nums, boolean[] used, List<Integer> path, List<List<Integer>> answer) { if (path.size() == nums.length) { answer.add(new ArrayList<>(path)); return; } for (int i = 0; i < nums.length; i++) { if (used[i]) { continue; } used[i] = true; path.add(nums[i]); backtrack(nums, used, path, answer); path.remove(path.size() - 1); used[i] = false; } } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String permutationsIterativeInsertionSolutionEntryJson() {
        return """
                    {
                      "name": "Iterative Insertion Fixture",
                      "timeComplexity": "O(n * n!)",
                      "spaceComplexity": "O(n * n!)",
                      "description": "## Approach\\n\\nInsert each new number into every possible position of every existing partial permutation.\\n\\n## Key Insight\\n\\nA new value has k + 1 insertion positions in each length-k permutation, which shows the factorial growth directly.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * n!)\\n- Space Complexity: O(n * n!)",
                      "code": "import java.util.*; class Solution { public List<List<Integer>> permute(int[] nums) { List<List<Integer>> answer = new ArrayList<>(); answer.add(new ArrayList<>()); for (int num : nums) { List<List<Integer>> nextLevel = new ArrayList<>(); for (List<Integer> permutation : answer) { for (int index = 0; index <= permutation.size(); index++) { List<Integer> copy = new ArrayList<>(permutation); copy.add(index, num); nextLevel.add(copy); } } answer = nextLevel; } return answer; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

