    private static String subsetsIISortSkipSolutionEntryJson() {
        return """
                    {
                      "name": "Sort Skip Same Depth Fixture",
                      "timeComplexity": "O(n * 2^n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nSort nums, record each path, and skip a value when it equals the previous value at the same recursion depth.\\n\\n## Key Insight\\n\\nSkipping only same-depth duplicates prevents duplicate rows while still allowing deeper levels to use multiple copies.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * 2^n)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public List<List<Integer>> subsetsWithDup(int[] nums) { Arrays.sort(nums); List<List<Integer>> answer = new ArrayList<>(); backtrack(nums, 0, new ArrayList<>(), answer); return answer; } private void backtrack(int[] nums, int start, List<Integer> path, List<List<Integer>> answer) { answer.add(new ArrayList<>(path)); for (int i = start; i < nums.length; i++) { if (i > start && nums[i] == nums[i - 1]) { continue; } path.add(nums[i]); backtrack(nums, i + 1, path, answer); path.remove(path.size() - 1); } } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String subsetsIIRunLengthSolutionEntryJson() {
        return """
                    {
                      "name": "Run Length Count Recursion Fixture",
                      "timeComplexity": "O(n * U)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nSort nums and process each run of equal values by choosing zero through all available copies before moving on.\\n\\n## Key Insight\\n\\nA unique subset is determined by the copy count selected from every duplicate run, so duplicate branches disappear.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * U)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public List<List<Integer>> subsetsWithDup(int[] nums) { Arrays.sort(nums); List<List<Integer>> answer = new ArrayList<>(); dfs(nums, 0, new ArrayList<>(), answer); return answer; } private void dfs(int[] nums, int index, List<Integer> path, List<List<Integer>> answer) { if (index == nums.length) { answer.add(new ArrayList<>(path)); return; } int next = index + 1; while (next < nums.length && nums[next] == nums[index]) { next++; } dfs(nums, next, path, answer); int copies = next - index; for (int used = 1; used <= copies; used++) { path.add(nums[index]); dfs(nums, next, path, answer); } for (int used = 1; used <= copies; used++) { path.remove(path.size() - 1); } } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String subsetsIIIterativePreviousLayerSolutionEntryJson() {
        return """
                    {
                      "name": "Iterative Previous Layer Fixture",
                      "timeComplexity": "O(n * U)",
                      "spaceComplexity": "O(n * U)",
                      "description": "## Approach\\n\\nSort nums and extend all subsets for a new value, but only the previous layer for a repeated value.\\n\\n## Key Insight\\n\\nThe previous layer is exactly the set of subsets that may receive the next duplicate without recreating older rows.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * U)\\n- Space Complexity: O(n * U)",
                      "code": "import java.util.*; class Solution { public List<List<Integer>> subsetsWithDup(int[] nums) { Arrays.sort(nums); List<List<Integer>> answer = new ArrayList<>(); answer.add(new ArrayList<>()); int previousStart = 0; for (int i = 0; i < nums.length; i++) { int start = (i > 0 && nums[i] == nums[i - 1]) ? previousStart : 0; int end = answer.size(); for (int j = start; j < end; j++) { List<Integer> next = new ArrayList<>(answer.get(j)); next.add(nums[i]); answer.add(next); } previousStart = end; } return answer; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String subsetsIICanonicalBitMaskSolutionEntryJson() {
        return """
                    {
                      "name": "Canonical Bit Mask Fixture",
                      "timeComplexity": "O(n * 2^n)",
                      "spaceComplexity": "O(n * U)",
                      "description": "## Approach\\n\\nSort nums, enumerate masks, and keep only masks that never select a later duplicate while skipping the previous copy.\\n\\n## Key Insight\\n\\nWithin each equal-value run, selected bits must form a prefix, leaving one canonical mask for each copy count.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * 2^n)\\n- Space Complexity: O(n * U)",
                      "code": "import java.util.*; class Solution { public List<List<Integer>> subsetsWithDup(int[] nums) { Arrays.sort(nums); List<List<Integer>> answer = new ArrayList<>(); int n = nums.length; int totalMasks = 1 << n; for (int mask = 0; mask < totalMasks; mask++) { if (!isCanonical(nums, mask)) { continue; } List<Integer> subset = new ArrayList<>(); for (int i = 0; i < n; i++) { if ((mask & (1 << i)) != 0) { subset.add(nums[i]); } } answer.add(subset); } return answer; } private boolean isCanonical(int[] nums, int mask) { for (int i = 1; i < nums.length; i++) { boolean choseCurrent = (mask & (1 << i)) != 0; boolean chosePrevious = (mask & (1 << (i - 1))) != 0; if (nums[i] == nums[i - 1] && choseCurrent && !chosePrevious) { return false; } } return true; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

