    private static String combinationSumIISortedSkipSolutionEntryJson() {
        return """
                    {
                      "name": "Sorted Same Depth Skip Fixture",
                      "timeComplexity": "O(2^n * n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nSort candidates, then backtrack from a start index and skip equal values at the same depth.\\n\\n## Key Insight\\n\\nAdvancing to i + 1 enforces one use per input position, while same-depth skipping removes duplicate rows.\\n\\n## Complexity Analysis\\n- Time Complexity: O(2^n * n)\\n- Space Complexity: O(n)",
                      "code": "import java.util.*; class Solution { public List<List<Integer>> combinationSum2(int[] candidates, int target) { Arrays.sort(candidates); List<List<Integer>> answer = new ArrayList<>(); backtrack(candidates, target, 0, new ArrayList<>(), answer); return answer; } private void backtrack(int[] candidates, int remain, int start, List<Integer> path, List<List<Integer>> answer) { if (remain == 0) { answer.add(new ArrayList<>(path)); return; } for (int i = start; i < candidates.length; i++) { if (candidates[i] > remain) { break; } if (i > start && candidates[i] == candidates[i - 1]) { continue; } path.add(candidates[i]); backtrack(candidates, remain - candidates[i], i + 1, path, answer); path.remove(path.size() - 1); } } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String combinationSumIIValueCountSolutionEntryJson() {
        return """
                    {
                      "name": "Value Count Choice Fixture",
                      "timeComplexity": "O(U * C)",
                      "spaceComplexity": "O(u + n)",
                      "description": "## Approach\\n\\nCompress candidates into sorted value counts, then choose how many copies of each value to use.\\n\\n## Key Insight\\n\\nA unique answer row is determined by copy counts per value, so duplicate input positions do not create separate branches.\\n\\n## Complexity Analysis\\n- Time Complexity: O(U * C)\\n- Space Complexity: O(u + n)",
                      "code": "import java.util.*; class Solution { public List<List<Integer>> combinationSum2(int[] candidates, int target) { TreeMap<Integer, Integer> counts = new TreeMap<>(); for (int value : candidates) { counts.put(value, counts.getOrDefault(value, 0) + 1); } List<Integer> values = new ArrayList<>(counts.keySet()); List<Integer> frequencies = new ArrayList<>(); for (int value : values) { frequencies.add(counts.get(value)); } List<List<Integer>> answer = new ArrayList<>(); dfs(values, frequencies, 0, target, new ArrayList<>(), answer); return answer; } private void dfs(List<Integer> values, List<Integer> frequencies, int index, int remain, List<Integer> path, List<List<Integer>> answer) { if (remain == 0) { answer.add(new ArrayList<>(path)); return; } if (index == values.size()) { return; } int value = values.get(index); int maxCopies = Math.min(frequencies.get(index), remain / value); for (int used = 0; used <= maxCopies; used++) { for (int copy = 0; copy < used; copy++) { path.add(value); } dfs(values, frequencies, index + 1, remain - used * value, path, answer); for (int copy = 0; copy < used; copy++) { path.remove(path.size() - 1); } } } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String combinationSumIIDescendingDpSolutionEntryJson() {
        return """
                    {
                      "name": "Descending Sum DP Fixture",
                      "timeComplexity": "O(n * target * C)",
                      "spaceComplexity": "O(target * C)",
                      "description": "## Approach\\n\\nSort candidates and maintain a set of combinations for every reachable sum, updating sums in descending order for each candidate.\\n\\n## Key Insight\\n\\nDescending DP iteration is the one-use rule, and sorted list forms let a set collapse duplicate rows.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * target * C)\\n- Space Complexity: O(target * C)",
                      "code": "import java.util.*; class Solution { public List<List<Integer>> combinationSum2(int[] candidates, int target) { Arrays.sort(candidates); List<Set<List<Integer>>> dp = new ArrayList<>(); for (int sum = 0; sum <= target; sum++) { dp.add(new LinkedHashSet<>()); } dp.get(0).add(new ArrayList<>()); for (int candidate : candidates) { for (int sum = target; sum >= candidate; sum--) { List<List<Integer>> previous = new ArrayList<>(dp.get(sum - candidate)); for (List<Integer> combination : previous) { List<Integer> next = new ArrayList<>(combination); next.add(candidate); dp.get(sum).add(next); } } } return new ArrayList<>(dp.get(target)); } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String combinationSumIIExplicitStackSolutionEntryJson() {
        return """
                    {
                      "name": "Explicit Stack DFS Fixture",
                      "timeComplexity": "O(2^n * n)",
                      "spaceComplexity": "O(2^n * n)",
                      "description": "## Approach\\n\\nSort candidates and push DFS states containing start, remain, and path onto an explicit stack.\\n\\n## Key Insight\\n\\nThe stack exposes the same one-use and same-depth duplicate skip rules without relying on recursive calls.\\n\\n## Complexity Analysis\\n- Time Complexity: O(2^n * n)\\n- Space Complexity: O(2^n * n)",
                      "code": "import java.util.*; class Solution { private static class State { final int start; final int remain; final List<Integer> path; State(int start, int remain, List<Integer> path) { this.start = start; this.remain = remain; this.path = path; } } public List<List<Integer>> combinationSum2(int[] candidates, int target) { Arrays.sort(candidates); List<List<Integer>> answer = new ArrayList<>(); Deque<State> stack = new ArrayDeque<>(); stack.push(new State(0, target, new ArrayList<>())); while (!stack.isEmpty()) { State state = stack.pop(); if (state.remain == 0) { answer.add(state.path); continue; } for (int i = candidates.length - 1; i >= state.start; i--) { if (candidates[i] > state.remain) { continue; } if (i > state.start && candidates[i] == candidates[i - 1]) { continue; } List<Integer> next = new ArrayList<>(state.path); next.add(candidates[i]); stack.push(new State(i + 1, state.remain - candidates[i], next)); } } return answer; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

