    private static String wordSearchInPlaceSolutionEntryJson() {
        return """
                    {
                      "name": "In-place Backtracking DFS Fixture",
                      "timeComplexity": "O(m * n * 4^L)",
                      "spaceComplexity": "O(L)",
                      "description": "## Approach\\n\\nStart DFS from each cell, mark the current cell in-place, explore four neighbors, and restore before returning.\\n\\n## Key Insight\\n\\nThe visited state belongs to one path, so backtracking restoration lets later paths reuse the same board cell.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n * 4^L)\\n- Space Complexity: O(L)",
                      "code": "class Solution { public boolean exist(char[][] board, String word) { int rows = board.length; int cols = board[0].length; for (int r = 0; r < rows; r++) { for (int c = 0; c < cols; c++) { if (dfs(board, word, r, c, 0)) { return true; } } } return false; } private boolean dfs(char[][] board, String word, int row, int col, int index) { if (index == word.length()) { return true; } if (row < 0 || row >= board.length || col < 0 || col >= board[0].length) { return false; } if (board[row][col] != word.charAt(index)) { return false; } char original = board[row][col]; board[row][col] = '#'; boolean found = dfs(board, word, row + 1, col, index + 1) || dfs(board, word, row - 1, col, index + 1) || dfs(board, word, row, col + 1, index + 1) || dfs(board, word, row, col - 1, index + 1); board[row][col] = original; return found; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String wordSearchFrequencyPrunedSolutionEntryJson() {
        return """
                    {
                      "name": "Frequency Pruned DFS Fixture",
                      "timeComplexity": "O(m * n * 4^L)",
                      "spaceComplexity": "O(m * n)",
                      "description": "## Approach\\n\\nReject words whose character counts exceed the board counts, optionally reverse toward the rarer end, then backtrack with a visited matrix.\\n\\n## Key Insight\\n\\nFrequency pruning and rare-end search reduce branches without changing the existence of a valid trace.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n * 4^L)\\n- Space Complexity: O(m * n)",
                      "code": "class Solution { public boolean exist(char[][] board, String word) { int rows = board.length; int cols = board[0].length; if (word.length() > rows * cols) { return false; } int[] available = new int[128]; for (int r = 0; r < rows; r++) { for (int c = 0; c < cols; c++) { available[board[r][c]]++; } } char[] chars = word.toCharArray(); int[] needed = new int[128]; for (char ch : chars) { needed[ch]++; if (needed[ch] > available[ch]) { return false; } } if (available[chars[0]] > available[chars[chars.length - 1]]) { reverse(chars); } boolean[][] visited = new boolean[rows][cols]; for (int r = 0; r < rows; r++) { for (int c = 0; c < cols; c++) { if (search(board, chars, r, c, 0, visited)) { return true; } } } return false; } private boolean search(char[][] board, char[] word, int row, int col, int index, boolean[][] visited) { if (index == word.length) { return true; } if (row < 0 || row >= board.length || col < 0 || col >= board[0].length) { return false; } if (visited[row][col] || board[row][col] != word[index]) { return false; } visited[row][col] = true; boolean found = search(board, word, row + 1, col, index + 1, visited) || search(board, word, row - 1, col, index + 1, visited) || search(board, word, row, col + 1, index + 1, visited) || search(board, word, row, col - 1, index + 1, visited); visited[row][col] = false; return found; } private void reverse(char[] chars) { int left = 0; int right = chars.length - 1; while (left < right) { char temp = chars[left]; chars[left++] = chars[right]; chars[right--] = temp; } } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String wordSearchIterativeBitSetSolutionEntryJson() {
        return """
                    {
                      "name": "Iterative BitSet Stack Fixture",
                      "timeComplexity": "O(m * n * 4^L)",
                      "spaceComplexity": "O(m * n * L)",
                      "description": "## Approach\\n\\nPush explicit search states onto a stack, carrying row, column, word index, and a BitSet of cells used by that path.\\n\\n## Key Insight\\n\\nEvery partial path needs its own visited set, which the cloned BitSet makes explicit.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n * 4^L)\\n- Space Complexity: O(m * n * L)",
                      "code": "import java.util.*; class Solution { private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}}; private static class State { final int row; final int col; final int index; final BitSet visited; State(int row, int col, int index, BitSet visited) { this.row = row; this.col = col; this.index = index; this.visited = visited; } } public boolean exist(char[][] board, String word) { int rows = board.length; int cols = board[0].length; Deque<State> stack = new ArrayDeque<>(); for (int r = 0; r < rows; r++) { for (int c = 0; c < cols; c++) { if (board[r][c] == word.charAt(0)) { BitSet visited = new BitSet(rows * cols); visited.set(r * cols + c); stack.push(new State(r, c, 0, visited)); } } } while (!stack.isEmpty()) { State current = stack.pop(); if (current.index == word.length() - 1) { return true; } char next = word.charAt(current.index + 1); for (int[] direction : DIRECTIONS) { int nr = current.row + direction[0]; int nc = current.col + direction[1]; if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) { continue; } int position = nr * cols + nc; if (current.visited.get(position) || board[nr][nc] != next) { continue; } BitSet nextVisited = (BitSet) current.visited.clone(); nextVisited.set(position); stack.push(new State(nr, nc, current.index + 1, nextVisited)); } } return false; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

    private static String wordSearchLayeredLongMaskSolutionEntryJson() {
        return """
                    {
                      "name": "Layered Long Mask Frontier Fixture",
                      "timeComplexity": "O(m * n * 4^L)",
                      "spaceComplexity": "O(m * n * 4^L)",
                      "description": "## Approach\\n\\nCarry a frontier of states for each word index, using one long bit mask to record the cells used by a partial path.\\n\\n## Key Insight\\n\\nThe board has at most 36 cells, so a long mask can represent one path's visited set while the frontier shows the BFS view of the search graph.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n * 4^L)\\n- Space Complexity: O(m * n * 4^L)",
                      "code": "import java.util.*; class Solution { private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}}; private static class State { final int row; final int col; final long mask; State(int row, int col, long mask) { this.row = row; this.col = col; this.mask = mask; } } public boolean exist(char[][] board, String word) { int rows = board.length; int cols = board[0].length; if (word.length() > rows * cols) { return false; } List<State> frontier = new ArrayList<>(); for (int r = 0; r < rows; r++) { for (int c = 0; c < cols; c++) { if (board[r][c] == word.charAt(0)) { int position = r * cols + c; frontier.add(new State(r, c, 1L << position)); } } } if (word.length() == 1) { return !frontier.isEmpty(); } for (int index = 1; index < word.length(); index++) { List<State> nextFrontier = new ArrayList<>(); char target = word.charAt(index); for (State state : frontier) { for (int[] direction : DIRECTIONS) { int nr = state.row + direction[0]; int nc = state.col + direction[1]; if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || board[nr][nc] != target) { continue; } int nextPosition = nr * cols + nc; long bit = 1L << nextPosition; if ((state.mask & bit) != 0) { continue; } nextFrontier.add(new State(nr, nc, state.mask | bit)); } } if (nextFrontier.isEmpty()) { return false; } frontier = nextFrontier; } return true; } }",
                      "language": "java"
                    }
                """.stripTrailing();
    }

