    private static String letterCombinationsRecursiveSuffixSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    private static final String[] MAPPING = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
                    public List<String> letterCombinations(String digits) {
                        if (digits.isEmpty()) {
                            return new ArrayList<>();
                        }
                        return combine(digits, 0);
                    }
                    private List<String> combine(String digits, int index) {
                        if (index == digits.length()) {
                            return new ArrayList<>(Collections.singletonList(""));
                        }
                        List<String> suffixes = combine(digits, index + 1);
                        List<String> result = new ArrayList<>();
                        String letters = MAPPING[digits.charAt(index) - '0'];
                        for (int i = 0; i < letters.length(); i++) {
                            for (String suffix : suffixes) {
                                result.add(letters.charAt(i) + suffix);
                            }
                        }
                        return result;
                    }
                }
                """;
        return """
                    {
                      "name": "Recursive Suffix Cartesian Product Fixture",
                      "timeComplexity": "O(n * 4^n)",
                      "spaceComplexity": "O(n * 4^n)",
                      "description": "## Approach\\n\\nBuild every suffix answer first and prepend each current digit letter.\\n\\n## Key Insight\\n\\nOne complete answer is one current letter plus one valid suffix combination.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * 4^n)\\n- Space Complexity: O(n * 4^n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

    private static String letterCombinationsMixedRadixSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    private static final String[] MAPPING = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
                    public List<String> letterCombinations(String digits) {
                        List<String> answer = new ArrayList<>();
                        if (digits.isEmpty()) {
                            return answer;
                        }
                        int n = digits.length();
                        String[] lettersByIndex = new String[n];
                        int total = 1;
                        for (int i = 0; i < n; i++) {
                            lettersByIndex[i] = MAPPING[digits.charAt(i) - '0'];
                            total *= lettersByIndex[i].length();
                        }
                        int[] indexes = new int[n];
                        for (int count = 0; count < total; count++) {
                            StringBuilder builder = new StringBuilder();
                            for (int i = 0; i < n; i++) {
                                builder.append(lettersByIndex[i].charAt(indexes[i]));
                            }
                            answer.add(builder.toString());
                            for (int pos = n - 1; pos >= 0; pos--) {
                                indexes[pos]++;
                                if (indexes[pos] < lettersByIndex[pos].length()) {
                                    break;
                                }
                                indexes[pos] = 0;
                            }
                        }
                        return answer;
                    }
                }
                """;
        return """
                    {
                      "name": "Mixed-Radix Index Enumeration Fixture",
                      "timeComplexity": "O(n * 4^n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nUse an index vector as a mixed-radix counter across keypad letter sets.\\n\\n## Key Insight\\n\\nThe Cartesian product can be enumerated iteratively by carrying from the rightmost digit choice.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * 4^n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

