    private static String nQueensBitmaskSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public List<List<String>> solveNQueens(int n) {
                        List<List<String>> answer = new ArrayList<>();
                        char[][] board = new char[n][n];
                        for (char[] row : board) { Arrays.fill(row, '.'); }
                        backtrack(0, n, 0, 0, 0, board, answer);
                        return answer;
                    }
                    private void backtrack(int row, int n, int columns, int mainDiagonals, int antiDiagonals, char[][] board, List<List<String>> answer) {
                        if (row == n) { answer.add(snapshot(board)); return; }
                        int available = ((1 << n) - 1) & ~(columns | mainDiagonals | antiDiagonals);
                        while (available != 0) {
                            int bit = available & -available;
                            int col = Integer.numberOfTrailingZeros(bit);
                            board[row][col] = 'Q';
                            backtrack(row + 1, n, columns | bit, (mainDiagonals | bit) << 1, (antiDiagonals | bit) >> 1, board, answer);
                            board[row][col] = '.';
                            available -= bit;
                        }
                    }
                    private List<String> snapshot(char[][] board) {
                        List<String> rows = new ArrayList<>();
                        for (char[] row : board) { rows.add(new String(row)); }
                        return rows;
                    }
                }
                """;
        return """
                    {
                      "name": "Bitmask Backtracking Fixture",
                      "timeComplexity": "O(n!)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nRepresent occupied columns and diagonals with integer masks.\\n\\n## Key Insight\\n\\nAvailable positions are the remaining bits after subtracting all attacked columns.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n!)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

