    private static String sudokuSolverPlainScanSolutionEntryJson() {
        String code = "class Solution { public void solveSudoku(char[][] board) { solve(board); } "
                + "private boolean solve(char[][] board) { for (int row = 0; row < 9; row++) { "
                + "for (int col = 0; col < 9; col++) { if (board[row][col] != '.') { continue; } "
                + "for (char digit = '1'; digit <= '9'; digit++) { if (!isValid(board, row, col, digit)) { continue; } "
                + "board[row][col] = digit; if (solve(board)) { return true; } board[row][col] = '.'; } return false; } } return true; } "
                + "private boolean isValid(char[][] board, int row, int col, char digit) { int boxRow = 3 * (row / 3); int boxCol = 3 * (col / 3); "
                + "for (int i = 0; i < 9; i++) { if (board[row][i] == digit || board[i][col] == digit) { return false; } "
                + "if (board[boxRow + i / 3][boxCol + i % 3] == digit) { return false; } } return true; } }";
        return """
                    {
                      "name": "Plain Board Scan Fixture",
                      "timeComplexity": "O(9^E)",
                      "spaceComplexity": "O(E)",
                      "description": "## Approach\\n\\nScan the board for the first blank and test each digit by row, column, and box scans.\\n\\n## Key Insight\\n\\nThis mirrors the Sudoku rules directly and is the correctness baseline.\\n\\n## Complexity Analysis\\n- Time Complexity: O(9^E)\\n- Space Complexity: O(E)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String sudokuSolverBooleanTableSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public void solveSudoku(char[][] board) { "
                + "boolean[][] rows = new boolean[9][10]; boolean[][] columns = new boolean[9][10]; boolean[][] boxes = new boolean[9][10]; "
                + "List<int[]> emptyCells = new ArrayList<>(); for (int row = 0; row < 9; row++) { for (int col = 0; col < 9; col++) { "
                + "if (board[row][col] == '.') { emptyCells.add(new int[]{row, col}); } else { int digit = board[row][col] - '0'; rows[row][digit] = true; columns[col][digit] = true; boxes[boxIndex(row, col)][digit] = true; } } } "
                + "solve(board, emptyCells, 0, rows, columns, boxes); } "
                + "private boolean solve(char[][] board, List<int[]> emptyCells, int index, boolean[][] rows, boolean[][] columns, boolean[][] boxes) { "
                + "if (index == emptyCells.size()) { return true; } int row = emptyCells.get(index)[0]; int col = emptyCells.get(index)[1]; int box = boxIndex(row, col); "
                + "for (int digit = 1; digit <= 9; digit++) { if (rows[row][digit] || columns[col][digit] || boxes[box][digit]) { continue; } "
                + "board[row][col] = (char) ('0' + digit); rows[row][digit] = true; columns[col][digit] = true; boxes[box][digit] = true; "
                + "if (solve(board, emptyCells, index + 1, rows, columns, boxes)) { return true; } board[row][col] = '.'; rows[row][digit] = false; columns[col][digit] = false; boxes[box][digit] = false; } return false; } "
                + "private int boxIndex(int row, int col) { return (row / 3) * 3 + col / 3; } }";
        return """
                    {
                      "name": "Boolean Constraint Table Fixture",
                      "timeComplexity": "O(9^E)",
                      "spaceComplexity": "O(E)",
                      "description": "## Approach\\n\\nUse boolean tables for row, column, and box occupancy while walking the empty-cell list.\\n\\n## Key Insight\\n\\nCandidate legality becomes constant-time table lookup.\\n\\n## Complexity Analysis\\n- Time Complexity: O(9^E)\\n- Space Complexity: O(E)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String sudokuSolverBitmaskSolutionEntryJson() {
        String code = "import java.util.*; class Solution { private static final int FULL_MASK = (1 << 9) - 1; "
                + "private final int[] rows = new int[9]; private final int[] columns = new int[9]; private final int[] boxes = new int[9]; private final List<int[]> emptyCells = new ArrayList<>(); "
                + "public void solveSudoku(char[][] board) { for (int row = 0; row < 9; row++) { for (int col = 0; col < 9; col++) { if (board[row][col] == '.') { emptyCells.add(new int[]{row, col}); continue; } "
                + "int bit = 1 << (board[row][col] - '1'); rows[row] |= bit; columns[col] |= bit; boxes[boxIndex(row, col)] |= bit; } } solve(board, 0); } "
                + "private boolean solve(char[][] board, int index) { if (index == emptyCells.size()) { return true; } int row = emptyCells.get(index)[0]; int col = emptyCells.get(index)[1]; int box = boxIndex(row, col); "
                + "int candidates = FULL_MASK & ~(rows[row] | columns[col] | boxes[box]); while (candidates != 0) { int bit = candidates & -candidates; int digit = Integer.numberOfTrailingZeros(bit); "
                + "place(board, row, col, box, bit, (char) ('1' + digit)); if (solve(board, index + 1)) { return true; } remove(board, row, col, box, bit); candidates -= bit; } return false; } "
                + "private void place(char[][] board, int row, int col, int box, int bit, char digit) { board[row][col] = digit; rows[row] |= bit; columns[col] |= bit; boxes[box] |= bit; } "
                + "private void remove(char[][] board, int row, int col, int box, int bit) { board[row][col] = '.'; rows[row] ^= bit; columns[col] ^= bit; boxes[box] ^= bit; } "
                + "private int boxIndex(int row, int col) { return (row / 3) * 3 + col / 3; } }";
        return """
                    {
                      "name": "Bitmask Constraint Fixture",
                      "timeComplexity": "O(9^E)",
                      "spaceComplexity": "O(E)",
                      "description": "## Approach\\n\\nRepresent used digits with row, column, and box bit masks.\\n\\n## Key Insight\\n\\nOne integer mask stores and enumerates the remaining candidates.\\n\\n## Complexity Analysis\\n- Time Complexity: O(9^E)\\n- Space Complexity: O(E)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String sudokuSolverMrvSolutionEntryJson() {
        String code = "class Solution { private static final int FULL_MASK = (1 << 9) - 1; private final int[] rows = new int[9]; private final int[] columns = new int[9]; private final int[] boxes = new int[9]; "
                + "public void solveSudoku(char[][] board) { for (int row = 0; row < 9; row++) { for (int col = 0; col < 9; col++) { if (board[row][col] == '.') { continue; } int bit = 1 << (board[row][col] - '1'); rows[row] |= bit; columns[col] |= bit; boxes[boxIndex(row, col)] |= bit; } } solve(board); } "
                + "private boolean solve(char[][] board) { int bestRow = -1; int bestCol = -1; int bestCandidates = 0; int fewest = 10; "
                + "for (int row = 0; row < 9; row++) { for (int col = 0; col < 9; col++) { if (board[row][col] != '.') { continue; } int candidates = FULL_MASK & ~(rows[row] | columns[col] | boxes[boxIndex(row, col)]); int count = Integer.bitCount(candidates); if (count == 0) { return false; } if (count < fewest) { fewest = count; bestRow = row; bestCol = col; bestCandidates = candidates; } } } "
                + "if (bestRow == -1) { return true; } int box = boxIndex(bestRow, bestCol); while (bestCandidates != 0) { int bit = bestCandidates & -bestCandidates; int digit = Integer.numberOfTrailingZeros(bit); board[bestRow][bestCol] = (char) ('1' + digit); rows[bestRow] |= bit; columns[bestCol] |= bit; boxes[box] |= bit; if (solve(board)) { return true; } boxes[box] ^= bit; columns[bestCol] ^= bit; rows[bestRow] ^= bit; board[bestRow][bestCol] = '.'; bestCandidates -= bit; } return false; } "
                + "private int boxIndex(int row, int col) { return (row / 3) * 3 + col / 3; } }";
        return """
                    {
                      "name": "Minimum Remaining Values Fixture",
                      "timeComplexity": "O(9^E)",
                      "spaceComplexity": "O(E)",
                      "description": "## Approach\\n\\nChoose the blank with the fewest mask candidates before branching.\\n\\n## Key Insight\\n\\nThe minimum-remaining-values heuristic reduces wasted search without changing correctness.\\n\\n## Complexity Analysis\\n- Time Complexity: O(9^E)\\n- Space Complexity: O(E)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

