    private static String restoreIpAddressesBacktrackingSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public List<String> restoreIpAddresses(String s) { "
                + "List<String> result = new ArrayList<>(); backtrack(s, 0, new ArrayList<>(), result); return result; } "
                + "private void backtrack(String s, int index, List<String> parts, List<String> result) { "
                + "if (parts.size() == 4) { if (index == s.length()) { result.add(String.join(\".\", parts)); } return; } "
                + "int remainingParts = 4 - parts.size(); int remainingChars = s.length() - index; "
                + "if (remainingChars < remainingParts || remainingChars > remainingParts * 3) { return; } "
                + "for (int length = 1; length <= 3 && index + length <= s.length(); length++) { "
                + "String segment = s.substring(index, index + length); parts.add(segment); "
                + "backtrack(s, index + length, parts, result); parts.remove(parts.size() - 1); } } }";
        return """
                    {
                      "name": "Remaining Length Backtracking Fixture",
                      "timeComplexity": "O(1)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nChoose each IP segment recursively and prune branches whose remaining digit count cannot fill the remaining segments.\\n\\n## Key Insight\\n\\nThe recursion is correct only when exactly four valid segments consume the whole string.\\n\\n## Complexity Analysis\\n- Time Complexity: O(1)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String restoreIpAddressesThreeCutSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public List<String> restoreIpAddresses(String s) { "
                + "List<String> result = new ArrayList<>(); int n = s.length(); "
                + "for (int firstLength = 1; firstLength <= 3; firstLength++) { "
                + "for (int secondLength = 1; secondLength <= 3; secondLength++) { "
                + "for (int thirdLength = 1; thirdLength <= 3; thirdLength++) { "
                + "int fourthLength = n - firstLength - secondLength - thirdLength; if (fourthLength < 1 || fourthLength > 3) { continue; } "
                + "int firstEnd = firstLength; int secondEnd = firstEnd + secondLength; int thirdEnd = secondEnd + thirdLength; "
                + "String first = s.substring(0, firstEnd); String second = s.substring(firstEnd, secondEnd); "
                + "String third = s.substring(secondEnd, thirdEnd); String fourth = s.substring(thirdEnd); "
                + "if (isValidSegment(first) && isValidSegment(second) && isValidSegment(third) && isValidSegment(fourth)) { "
                + "result.add(first + \".\" + second + \".\" + third + \".\" + fourth); } } } } return result; } "
                + "private boolean isValidSegment(String segment) { return true; } }";
        return """
                    {
                      "name": "Fixed Three Cut Enumeration Fixture",
                      "timeComplexity": "O(1)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nEnumerate the first three segment lengths and let the fourth segment be the remaining suffix.\\n\\n## Key Insight\\n\\nThe IP format fixes the search space to a tiny finite set of cut combinations.\\n\\n## Complexity Analysis\\n- Time Complexity: O(1)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String restoreIpAddressesBfsSolutionEntryJson() {
        String code = "import java.util.*; class Solution { private static class State { int index; int parts; String address; "
                + "State(int index, int parts, String address) { this.index = index; this.parts = parts; this.address = address; } } "
                + "public List<String> restoreIpAddresses(String s) { List<String> result = new ArrayList<>(); "
                + "Queue<State> queue = new ArrayDeque<>(); queue.offer(new State(0, 0, \"\")); "
                + "while (!queue.isEmpty()) { State state = queue.poll(); if (state.parts == 4) { "
                + "if (state.index == s.length()) { result.add(state.address); } continue; } "
                + "for (int length = 1; length <= 3 && state.index + length <= s.length(); length++) { "
                + "String segment = s.substring(state.index, state.index + length); String nextAddress = state.address.isEmpty() ? segment : state.address + \".\" + segment; "
                + "queue.offer(new State(state.index + length, state.parts + 1, nextAddress)); } } return result; } }";
        return """
                    {
                      "name": "BFS State Expansion Fixture",
                      "timeComplexity": "O(1)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nUse a queue of partial IP addresses and expand each state by one segment.\\n\\n## Key Insight\\n\\nEach queue edge adds exactly one segment, making the search-state graph explicit.\\n\\n## Complexity Analysis\\n- Time Complexity: O(1)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String restoreIpAddressesDpSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public List<String> restoreIpAddresses(String s) { int n = s.length(); "
                + "List<String>[][] dp = new ArrayList[n + 1][5]; for (int i = 0; i <= n; i++) { for (int parts = 0; parts <= 4; parts++) { dp[i][parts] = new ArrayList<>(); } } "
                + "dp[0][0].add(\"\"); for (int parts = 0; parts < 4; parts++) { for (int index = 0; index <= n; index++) { "
                + "for (int length = 1; length <= 3 && index + length <= n; length++) { String segment = s.substring(index, index + length); "
                + "for (String prefix : dp[index][parts]) { String address = prefix.isEmpty() ? segment : prefix + \".\" + segment; "
                + "dp[index + length][parts + 1].add(address); } } } } return dp[n][4]; } }";
        return """
                    {
                      "name": "Dynamic Programming Reconstruction Fixture",
                      "timeComplexity": "O(1)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nStore partial addresses by consumed index and number of segments, then reconstruct all four-segment addresses.\\n\\n## Key Insight\\n\\nThe DP state is the same invariant as the recursive search: consumed digits and formed segments.\\n\\n## Complexity Analysis\\n- Time Complexity: O(1)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

