    private static String partitionKBucketSymmetrySolutionEntryJson() {
        String code = "import java.util.*; class Solution { public boolean canPartitionKSubsets(int[] nums, int k) { "
                + "int target = 1; int[] buckets = new int[k]; return place(nums, nums.length - 1, buckets, target); } "
                + "private boolean place(int[] nums, int index, int[] buckets, int target) { if (index < 0) { return true; } "
                + "int value = nums[index]; Set<Integer> triedSums = new HashSet<>(); for (int bucket = 0; bucket < buckets.length; bucket++) { "
                + "if (!triedSums.add(buckets[bucket])) { continue; } buckets[bucket] += value; if (place(nums, index - 1, buckets, target)) { return true; } "
                + "buckets[bucket] -= value; if (buckets[bucket] == 0) { break; } } return false; } }";
        return """
                    {
                      "name": "Bucket Symmetry Fixture",
                      "timeComplexity": "O(k^n)",
                      "spaceComplexity": "O(k + n)",
                      "description": "## Approach\\n\\nAssign numbers into bucket sums while skipping buckets with equivalent current sums.\\n\\n## Key Insight\\n\\nUnlabeled equal-sum buckets create symmetric states that should be pruned.\\n\\n## Complexity Analysis\\n- Time Complexity: O(k^n)\\n- Space Complexity: O(k + n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String partitionKTargetSubsetSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public boolean canPartitionKSubsets(int[] nums, int k) { "
                + "int target = 1; boolean[] used = new boolean[nums.length]; return fill(nums, used, k, nums.length - 1, 0, target); } "
                + "private boolean fill(int[] nums, boolean[] used, int bucketsLeft, int start, int currentSum, int target) { "
                + "if (bucketsLeft == 1) { return true; } if (currentSum == target) { return fill(nums, used, bucketsLeft - 1, nums.length - 1, 0, target); } "
                + "int previous = -1; for (int i = start; i >= 0; i--) { if (used[i]) { continue; } used[i] = true; "
                + "if (fill(nums, used, bucketsLeft, i - 1, currentSum + nums[i], target)) { return true; } used[i] = false; "
                + "if (currentSum == 0) { break; } } return false; } }";
        return """
                    {
                      "name": "One Target Subset Fixture",
                      "timeComplexity": "O(k * 2^n * n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nRepeatedly build one subset whose sum reaches the target, using a used array.\\n\\n## Key Insight\\n\\nCompleted buckets are equivalent, so the search can focus on the next target subset.\\n\\n## Complexity Analysis\\n- Time Complexity: O(k * 2^n * n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String partitionKBottomUpBitmaskSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public boolean canPartitionKSubsets(int[] nums, int k) { "
                + "int target = 1; int totalMasks = 1 << nums.length; int[] dp = new int[totalMasks]; Arrays.fill(dp, -1); dp[0] = 0; "
                + "for (int mask = 0; mask < totalMasks; mask++) { if (dp[mask] == -1) { continue; } for (int i = 0; i < nums.length; i++) { "
                + "int nextMask = mask | (1 << i); int nextSum = dp[mask] + nums[i]; dp[nextMask] = nextSum % target; } } "
                + "return dp[totalMasks - 1] == 0; } }";
        return """
                    {
                      "name": "Bottom-Up Bitmask DP Fixture",
                      "timeComplexity": "O(n * 2^n)",
                      "spaceComplexity": "O(2^n)",
                      "description": "## Approach\\n\\nUse a reachable-mask table and store the current bucket remainder for each mask.\\n\\n## Key Insight\\n\\nModulo target zero marks a completed bucket in the state table.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * 2^n)\\n- Space Complexity: O(2^n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String partitionKTopDownMaskSolutionEntryJson() {
        String code = "import java.util.*; class Solution { private int[] nums; private int target; private Map<Integer, Boolean> memo; "
                + "public boolean canPartitionKSubsets(int[] nums, int k) { this.nums = nums; this.target = 1; this.memo = new HashMap<>(); "
                + "return search((1 << nums.length) - 1, 0); } "
                + "private boolean search(int unusedMask, int currentSum) { if (unusedMask == 0) { return currentSum == 0; } "
                + "int remaining = unusedMask; while (remaining != 0) { int bit = remaining & -remaining; int index = Integer.numberOfTrailingZeros(bit); "
                + "int nextSum = currentSum + nums[index]; if (search(unusedMask ^ bit, nextSum % target)) { return true; } remaining -= bit; } "
                + "memo.put(unusedMask, false); return false; } }";
        return """
                    {
                      "name": "Top-Down Remaining Mask Fixture",
                      "timeComplexity": "O(n * 2^n)",
                      "spaceComplexity": "O(2^n)",
                      "description": "## Approach\\n\\nSearch by unused-mask states and memoize failed remaining masks at bucket boundaries.\\n\\n## Key Insight\\n\\nA remaining mask describes the future whenever the current bucket starts empty.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * 2^n)\\n- Space Complexity: O(2^n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

