                + "for (int row = 0; row < grid.length; row++) { for (int col = 0; col < grid[0].length; col++) { "
                + "if (grid[row][col] == 1) { best = Math.max(best, area(grid, row, col)); } } } return best; } "
                + "private int area(int[][] grid, int row, int col) { if (row < 0 || row >= grid.length || col < 0 || col >= grid[0].length || grid[row][col] != 1) { return 0; } "
                + "grid[row][col] = 0; return 1 + area(grid, row + 1, col) + area(grid, row - 1, col) + area(grid, row, col + 1) + area(grid, row, col - 1); } }";
