    private static String wallsAndGatesMultiSourceBfsSolutionEntryJson() {
        String code = "import java.util.*; class Solution { private static final int INF = 2147483647; "
                + "private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}}; "
                + "public void wallsAndGates(int[][] rooms) { int rows = rooms.length; int cols = rooms[0].length; "
                + "Queue<int[]> queue = new ArrayDeque<>(); for (int row = 0; row < rows; row++) { for (int col = 0; col < cols; col++) { "
                + "if (rooms[row][col] == 0) { queue.offer(new int[]{row, col}); } } } "
                + "while (!queue.isEmpty()) { int[] cell = queue.poll(); for (int[] direction : DIRECTIONS) { "
                + "int nextRow = cell[0] + direction[0]; int nextCol = cell[1] + direction[1]; "
                + "if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) { continue; } "
                + "if (rooms[nextRow][nextCol] != INF) { continue; } "
                + "rooms[nextRow][nextCol] = rooms[cell[0]][cell[1]] + 1; queue.offer(new int[]{nextRow, nextCol}); } } } }";
        return """
                    {
                      "name": "Multi-Source BFS from All Gates Fixture",
                      "timeComplexity": "O(m * n)",
                      "spaceComplexity": "O(m * n)",
                      "description": "## Approach\\n\\nPut every gate into one queue, then expand through empty rooms.\\n\\n## Key Insight\\n\\nAll gates are zero-distance sources, so BFS writes the nearest gate distance the first time it reaches an empty room.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n)\\n- Space Complexity: O(m * n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String wallsAndGatesDfsRelaxationSolutionEntryJson() {
        String code = "class Solution { public void wallsAndGates(int[][] rooms) { int rows = rooms.length; int cols = rooms[0].length; "
                + "for (int row = 0; row < rows; row++) { for (int col = 0; col < cols; col++) { "
                + "if (rooms[row][col] == 0) { relax(rooms, row, col, 0); } } } } "
                + "private void relax(int[][] rooms, int row, int col, int distance) { "
                + "if (row < 0 || row >= rooms.length || col < 0 || col >= rooms[0].length) { return; } "
                + "if (rooms[row][col] < distance) { return; } rooms[row][col] = distance; "
                + "relax(rooms, row + 1, col, distance + 1); relax(rooms, row - 1, col, distance + 1); "
                + "relax(rooms, row, col + 1, distance + 1); relax(rooms, row, col - 1, distance + 1); } }";
        return """
                    {
                      "name": "DFS Distance Relaxation Fixture",
                      "timeComplexity": "O(m * n * g)",
                      "spaceComplexity": "O(m * n)",
                      "description": "## Approach\\n\\nRun DFS from each gate and recursively relax a cell only when the current distance improves it.\\n\\n## Key Insight\\n\\nThe pruning condition is the shortest-path invariant: if a cell already has a smaller distance, this path cannot improve any continuation.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n * g) worst case\\n- Space Complexity: O(m * n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String wallsAndGatesDijkstraSolutionEntryJson() {
        String code = "import java.util.*; class Solution { private static final int INF = 2147483647; "
                + "private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}}; "
                + "public void wallsAndGates(int[][] rooms) { int rows = rooms.length; int cols = rooms[0].length; "
                + "PriorityQueue<int[]> heap = new PriorityQueue<>(Comparator.comparingInt(cell -> cell[2])); "
                + "for (int row = 0; row < rows; row++) { for (int col = 0; col < cols; col++) { "
                + "if (rooms[row][col] == 0) { heap.offer(new int[]{row, col, 0}); } } } "
                + "while (!heap.isEmpty()) { int[] cell = heap.poll(); int row = cell[0]; int col = cell[1]; int distance = cell[2]; "
                + "if (distance != rooms[row][col]) { continue; } for (int[] direction : DIRECTIONS) { "
                + "int nextRow = row + direction[0]; int nextCol = col + direction[1]; "
                + "if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) { continue; } "
                + "if (rooms[nextRow][nextCol] != INF) { continue; } int nextDistance = distance + 1; "
                + "rooms[nextRow][nextCol] = nextDistance; heap.offer(new int[]{nextRow, nextCol, nextDistance}); } } } }";
        return """
                    {
                      "name": "Multi-Source Dijkstra Fixture",
                      "timeComplexity": "O(m * n * log(m * n))",
                      "spaceComplexity": "O(m * n)",
                      "description": "## Approach\\n\\nSeed a priority queue with all gates, pop the smallest distance, and relax neighboring empty rooms.\\n\\n## Key Insight\\n\\nDijkstra is the general shortest-path model; here uniform edge weights make BFS the specialized optimal version.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n * log(m * n))\\n- Space Complexity: O(m * n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String wallsAndGatesRepeatedRelaxationSolutionEntryJson() {
        String code = "class Solution { private static final int INF = 2147483647; "
                + "private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}}; "
                + "public void wallsAndGates(int[][] rooms) { int rows = rooms.length; int cols = rooms[0].length; boolean changed = true; "
                + "while (changed) { changed = false; for (int row = 0; row < rows; row++) { for (int col = 0; col < cols; col++) { "
                + "if (rooms[row][col] == -1 || rooms[row][col] == 0) { continue; } int best = rooms[row][col]; "
                + "for (int[] direction : DIRECTIONS) { int nextRow = row + direction[0]; int nextCol = col + direction[1]; "
                + "if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) { continue; } "
                + "if (rooms[nextRow][nextCol] == -1 || rooms[nextRow][nextCol] == INF) { continue; } "
                + "best = Math.min(best, rooms[nextRow][nextCol] + 1); } "
                + "if (best < rooms[row][col]) { rooms[row][col] = best; changed = true; } } } } } }";
        return """
                    {
                      "name": "Repeated Grid Relaxation Fixture",
                      "timeComplexity": "O(m * n * D)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nScan the grid until no empty room can be improved by a finite neighbor distance plus one.\\n\\n## Key Insight\\n\\nThis is Bellman-Ford style relaxation on the grid: local improvements propagate until the fixed point is the shortest distance field.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n * D)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

