    private static String rottingOrangesDijkstraSolutionEntryJson() {
        String code = "import java.util.*; class Solution { private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}}; "
                + "public int orangesRotting(int[][] grid) { int rows = grid.length; int cols = grid[0].length; int fresh = 0; int minutes = 0; "
                + "PriorityQueue<int[]> heap = new PriorityQueue<>(Comparator.comparingInt(cell -> cell[2])); "
                + "for (int row = 0; row < rows; row++) { for (int col = 0; col < cols; col++) { if (grid[row][col] == 2) { heap.offer(new int[]{row, col, 0}); } "
                + "else if (grid[row][col] == 1) { fresh++; } } } while (!heap.isEmpty()) { int[] cell = heap.poll(); int row = cell[0]; int col = cell[1]; "
                + "int time = cell[2]; minutes = Math.max(minutes, time); for (int[] direction : DIRECTIONS) { int nextRow = row + direction[0]; int nextCol = col + direction[1]; "
                + "if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) { continue; } if (grid[nextRow][nextCol] != 1) { continue; } "
                + "int nextTime = time + 1; grid[nextRow][nextCol] = 2; fresh--; heap.offer(new int[]{nextRow, nextCol, nextTime}); } } return fresh == 0 ? minutes : -1; } }";
        return """
                    {
                      "name": "Multi-Source Dijkstra Fixture",
                      "timeComplexity": "O(m * n * log(m * n))",
                      "spaceComplexity": "O(m * n)",
                      "description": "## Approach\\n\\nUse a priority queue seeded with all rotten oranges and assign the next minute when a fresh neighbor is reached.\\n\\n## Key Insight\\n\\nBFS is optimal for uniform minute costs, while Dijkstra is the general shortest-time model for weighted spreading.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n * log(m * n))\\n- Space Complexity: O(m * n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String rottingOrangesMinuteSimulationSolutionEntryJson() {
        String code = "class Solution { private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}}; "
                + "public int orangesRotting(int[][] grid) { int rows = grid.length; int cols = grid[0].length; int fresh = 0; "
                + "for (int[] row : grid) { for (int cell : row) { if (cell == 1) { fresh++; } } } int minutes = 0; "
                + "while (fresh > 0) { boolean changed = false; for (int row = 0; row < rows; row++) { for (int col = 0; col < cols; col++) { "
                + "if (grid[row][col] != 2) { continue; } for (int[] direction : DIRECTIONS) { int nextRow = row + direction[0]; int nextCol = col + direction[1]; "
                + "if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) { continue; } if (grid[nextRow][nextCol] != 1) { continue; } "
                + "grid[nextRow][nextCol] = 3; fresh--; changed = true; } } } if (!changed) { return -1; } "
                + "for (int row = 0; row < rows; row++) { for (int col = 0; col < cols; col++) { if (grid[row][col] == 3) { grid[row][col] = 2; } } } "
                + "minutes++; } return minutes; } }";
        return """
                    {
                      "name": "Minute-by-Minute Simulation Fixture",
                      "timeComplexity": "O(m * n * T)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nScan the whole grid for each simulated minute and use a temporary value for oranges that rot at the end of that minute.\\n\\n## Key Insight\\n\\nTemporary marking prevents chain reactions inside one minute and makes the simultaneous update rule explicit.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n * T)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

