    private static String courseScheduleKahnSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public boolean canFinish(int numCourses, int[][] prerequisites) { "
                + "List<List<Integer>> graph = new ArrayList<>(); for (int course = 0; course < numCourses; course++) { graph.add(new ArrayList<>()); } "
                + "int[] indegree = new int[numCourses]; for (int[] prerequisite : prerequisites) { int course = prerequisite[0]; int before = prerequisite[1]; graph.get(before).add(course); indegree[course]++; } "
                + "Queue<Integer> ready = new ArrayDeque<>(); for (int course = 0; course < numCourses; course++) { if (indegree[course] == 0) { ready.offer(course); } } "
                + "int processed = 0; while (!ready.isEmpty()) { int course = ready.poll(); processed++; for (int next : graph.get(course)) { indegree[next]--; if (indegree[next] == 0) { ready.offer(next); } } } return processed == numCourses; } }";
        return """
                    {
                      "name": "Kahn Topological Sort Fixture",
                      "timeComplexity": "O(V + E)",
                      "spaceComplexity": "O(V + E)",
                      "description": "## Approach\\n\\nProcess indegree-zero courses and remove their outgoing prerequisite edges.\\n\\n## Key Insight\\n\\nA directed acyclic graph always exposes at least one available course, while a cycle never fully unlocks.\\n\\n## Complexity Analysis\\n- Time Complexity: O(V + E)\\n- Space Complexity: O(V + E)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String courseScheduleThreeColorDfsSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public boolean canFinish(int numCourses, int[][] prerequisites) { "
                + "List<List<Integer>> graph = new ArrayList<>(); for (int course = 0; course < numCourses; course++) { graph.add(new ArrayList<>()); } "
                + "for (int[] prerequisite : prerequisites) { graph.get(prerequisite[1]).add(prerequisite[0]); } int[] state = new int[numCourses]; "
                + "for (int course = 0; course < numCourses; course++) { if (!isAcyclic(graph, state, course)) { return false; } } return true; } "
                + "private boolean isAcyclic(List<List<Integer>> graph, int[] state, int course) { if (state[course] == 1) { return false; } if (state[course] == 2) { return true; } "
                + "state[course] = 1; for (int next : graph.get(course)) { if (!isAcyclic(graph, state, next)) { return false; } } state[course] = 2; return true; } }";
        return """
                    {
                      "name": "Three-Color DFS Cycle Detection Fixture",
                      "timeComplexity": "O(V + E)",
                      "spaceComplexity": "O(V + E)",
                      "description": "## Approach\\n\\nUse unvisited, visiting, and finished states during DFS.\\n\\n## Key Insight\\n\\nRe-entering a visiting node means the current recursion path has found a directed cycle.\\n\\n## Complexity Analysis\\n- Time Complexity: O(V + E)\\n- Space Complexity: O(V + E)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String courseScheduleTarjanSolutionEntryJson() {
        String code = "import java.util.*; class Solution { private List<List<Integer>> graph; private int[] index; private int[] low; private boolean[] onStack; private Deque<Integer> stack; private int time; private boolean hasCycle; "
                + "public boolean canFinish(int numCourses, int[][] prerequisites) { graph = new ArrayList<>(); for (int course = 0; course < numCourses; course++) { graph.add(new ArrayList<>()); } "
                + "for (int[] prerequisite : prerequisites) { graph.get(prerequisite[1]).add(prerequisite[0]); } index = new int[numCourses]; low = new int[numCourses]; onStack = new boolean[numCourses]; stack = new ArrayDeque<>(); Arrays.fill(index, -1); "
                + "for (int course = 0; course < numCourses && !hasCycle; course++) { if (index[course] == -1) { strongConnect(course); } } return !hasCycle; } "
                + "private void strongConnect(int node) { index[node] = time; low[node] = time; time++; stack.push(node); onStack[node] = true; for (int next : graph.get(node)) { if (next == node) { hasCycle = true; } "
                + "if (index[next] == -1) { strongConnect(next); low[node] = Math.min(low[node], low[next]); } else if (onStack[next]) { low[node] = Math.min(low[node], index[next]); } } "
                + "if (low[node] == index[node]) { int componentSize = 0; int current; do { current = stack.pop(); onStack[current] = false; componentSize++; } while (current != node); if (componentSize > 1) { hasCycle = true; } } } }";
        return """
                    {
                      "name": "Tarjan Strong Component Detection Fixture",
                      "timeComplexity": "O(V + E)",
                      "spaceComplexity": "O(V + E)",
                      "description": "## Approach\\n\\nUse low-link values to find strongly connected components in one DFS pass.\\n\\n## Key Insight\\n\\nA component with multiple courses is cyclic, and a self-edge must also be treated as a cycle.\\n\\n## Complexity Analysis\\n- Time Complexity: O(V + E)\\n- Space Complexity: O(V + E)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String courseScheduleTwoPassSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public boolean canFinish(int numCourses, int[][] prerequisites) { "
                + "List<List<Integer>> graph = new ArrayList<>(); List<List<Integer>> reverseGraph = new ArrayList<>(); for (int course = 0; course < numCourses; course++) { graph.add(new ArrayList<>()); reverseGraph.add(new ArrayList<>()); } "
                + "boolean hasSelfLoop = false; for (int[] prerequisite : prerequisites) { int course = prerequisite[0]; int before = prerequisite[1]; if (course == before) { hasSelfLoop = true; } graph.get(before).add(course); reverseGraph.get(course).add(before); } "
                + "if (hasSelfLoop) { return false; } boolean[] visited = new boolean[numCourses]; List<Integer> order = new ArrayList<>(); for (int course = 0; course < numCourses; course++) { if (!visited[course]) { fillOrder(graph, visited, order, course); } } "
                + "Arrays.fill(visited, false); for (int i = order.size() - 1; i >= 0; i--) { int course = order.get(i); if (!visited[course]) { int componentSize = markComponent(reverseGraph, visited, course); if (componentSize > 1) { return false; } } } return true; } "
                + "private void fillOrder(List<List<Integer>> graph, boolean[] visited, List<Integer> order, int course) { visited[course] = true; for (int next : graph.get(course)) { if (!visited[next]) { fillOrder(graph, visited, order, next); } } order.add(course); } "
                + "private int markComponent(List<List<Integer>> reverseGraph, boolean[] visited, int course) { visited[course] = true; int size = 1; for (int next : reverseGraph.get(course)) { if (!visited[next]) { size += markComponent(reverseGraph, visited, next); } } return size; } }";
        return """
                    {
                      "name": "Two-Pass Strong Component Detection Fixture",
                      "timeComplexity": "O(V + E)",
                      "spaceComplexity": "O(V + E)",
                      "description": "## Approach\\n\\nUse finish order on the graph and component marking on the reversed graph.\\n\\n## Key Insight\\n\\nThe two-pass component view proves feasibility by ruling out cyclic strongly connected components.\\n\\n## Complexity Analysis\\n- Time Complexity: O(V + E)\\n- Space Complexity: O(V + E)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

