    private static String courseScheduleIIKahnSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public int[] findOrder(int numCourses, int[][] prerequisites) { "
                + "List<List<Integer>> graph = new ArrayList<>(); for (int course = 0; course < numCourses; course++) { graph.add(new ArrayList<>()); } "
                + "int[] indegree = new int[numCourses]; for (int[] prerequisite : prerequisites) { int course = prerequisite[0]; int before = prerequisite[1]; graph.get(before).add(course); indegree[course]++; } "
                + "Queue<Integer> ready = new ArrayDeque<>(); for (int course = 0; course < numCourses; course++) { if (indegree[course] == 0) { ready.offer(course); } } "
                + "int[] order = new int[numCourses]; int index = 0; while (!ready.isEmpty()) { int course = ready.poll(); order[index++] = course; for (int next : graph.get(course)) { indegree[next]--; if (indegree[next] == 0) { ready.offer(next); } } } "
                + "return index == numCourses ? order : new int[0]; } }";
        return """
                    {
                      "name": "Kahn Topological Order Fixture",
                      "timeComplexity": "O(V + E)",
                      "spaceComplexity": "O(V + E)",
                      "description": "## Approach\\n\\nAppend indegree-zero courses and remove their outgoing edges.\\n\\n## Key Insight\\n\\nA cycle prevents the answer length from reaching the number of courses.\\n\\n## Complexity Analysis\\n- Time Complexity: O(V + E)\\n- Space Complexity: O(V + E)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String courseScheduleIIRecursivePostorderSolutionEntryJson() {
        String code = "import java.util.*; class Solution { private List<List<Integer>> graph; private int[] state; private int[] order; private int write; "
                + "public int[] findOrder(int numCourses, int[][] prerequisites) { graph = new ArrayList<>(); for (int course = 0; course < numCourses; course++) { graph.add(new ArrayList<>()); } "
                + "for (int[] prerequisite : prerequisites) { graph.get(prerequisite[1]).add(prerequisite[0]); } state = new int[numCourses]; order = new int[numCourses]; write = numCourses - 1; "
                + "for (int course = 0; course < numCourses; course++) { if (!dfs(course)) { return new int[0]; } } return order; } "
                + "private boolean dfs(int course) { if (state[course] == 1) { return false; } if (state[course] == 2) { return true; } state[course] = 1; "
                + "for (int next : graph.get(course)) { if (!dfs(next)) { return false; } } state[course] = 2; order[write--] = course; return true; } }";
        return """
                    {
                      "name": "Three-Color DFS Postorder Fixture",
                      "timeComplexity": "O(V + E)",
                      "spaceComplexity": "O(V + E)",
                      "description": "## Approach\\n\\nUse recursive three-color DFS and write finished nodes from the end of the order.\\n\\n## Key Insight\\n\\nA visiting node reached again is a cycle, while postorder places prerequisites first.\\n\\n## Complexity Analysis\\n- Time Complexity: O(V + E)\\n- Space Complexity: O(V + E)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String courseScheduleIIDependencyFirstSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public int[] findOrder(int numCourses, int[][] prerequisites) { "
                + "List<List<Integer>> prereqGraph = new ArrayList<>(); for (int course = 0; course < numCourses; course++) { prereqGraph.add(new ArrayList<>()); } "
                + "for (int[] prerequisite : prerequisites) { int course = prerequisite[0]; int before = prerequisite[1]; prereqGraph.get(course).add(before); } "
                + "int[] state = new int[numCourses]; List<Integer> order = new ArrayList<>(); for (int course = 0; course < numCourses; course++) { if (!visit(course, prereqGraph, state, order)) { return new int[0]; } } "
                + "int[] result = new int[numCourses]; for (int i = 0; i < numCourses; i++) { result[i] = order.get(i); } return result; } "
                + "private boolean visit(int course, List<List<Integer>> prereqGraph, int[] state, List<Integer> order) { if (state[course] == 1) { return false; } if (state[course] == 2) { return true; } state[course] = 1; "
                + "for (int before : prereqGraph.get(course)) { if (!visit(before, prereqGraph, state, order)) { return false; } } state[course] = 2; order.add(course); return true; } }";
        return """
                    {
                      "name": "Dependency-First DFS Fixture",
                      "timeComplexity": "O(V + E)",
                      "spaceComplexity": "O(V + E)",
                      "description": "## Approach\\n\\nStore direct prerequisites and append a course only after visiting them.\\n\\n## Key Insight\\n\\nFollowing prerequisites first creates an order that does not need reversal.\\n\\n## Complexity Analysis\\n- Time Complexity: O(V + E)\\n- Space Complexity: O(V + E)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String courseScheduleIIIterativeDfsSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public int[] findOrder(int numCourses, int[][] prerequisites) { "
                + "List<List<Integer>> graph = new ArrayList<>(); for (int course = 0; course < numCourses; course++) { graph.add(new ArrayList<>()); } for (int[] prerequisite : prerequisites) { graph.get(prerequisite[1]).add(prerequisite[0]); } "
                + "int[] state = new int[numCourses]; int[] order = new int[numCourses]; int write = numCourses - 1; for (int start = 0; start < numCourses; start++) { if (state[start] != 0) { continue; } "
                + "Deque<int[]> stack = new ArrayDeque<>(); stack.push(new int[]{start, 0}); while (!stack.isEmpty()) { int[] frame = stack.peek(); int course = frame[0]; if (state[course] == 0) { state[course] = 1; } "
                + "if (frame[1] == graph.get(course).size()) { state[course] = 2; order[write--] = course; stack.pop(); continue; } int next = graph.get(course).get(frame[1]); frame[1]++; "
                + "if (state[next] == 1) { return new int[0]; } if (state[next] == 0) { stack.push(new int[]{next, 0}); } } } return order; } }";
        return """
                    {
                      "name": "Iterative DFS Topological Order Fixture",
                      "timeComplexity": "O(V + E)",
                      "spaceComplexity": "O(V + E)",
                      "description": "## Approach\\n\\nUse explicit stack frames that remember the next outgoing edge to inspect.\\n\\n## Key Insight\\n\\nThe stack preserves DFS entry and finish moments without using recursion.\\n\\n## Complexity Analysis\\n- Time Complexity: O(V + E)\\n- Space Complexity: O(V + E)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

