    private static String graphValidTreeUnionFindSolutionEntryJson() {
        String code = "class Solution { private int[] parent; private int[] rank; public boolean validTree(int n, int[][] edges) { "
                + "if (edges.length != n - 1) { return false; } parent = new int[n]; rank = new int[n]; for (int node = 0; node < n; node++) { parent[node] = node; } "
                + "for (int[] edge : edges) { if (!union(edge[0], edge[1])) { return false; } } return true; } "
                + "private int find(int node) { if (parent[node] != node) { parent[node] = find(parent[node]); } return parent[node]; } "
                + "private boolean union(int a, int b) { int rootA = find(a); int rootB = find(b); if (rootA == rootB) { return false; } "
                + "if (rank[rootA] < rank[rootB]) { int temp = rootA; rootA = rootB; rootB = temp; } parent[rootB] = rootA; if (rank[rootA] == rank[rootB]) { rank[rootA]++; } return true; } }";
        return """
                    {
                      "name": "Union Find With Edge Count Fixture",
                      "timeComplexity": "O(n + E alpha(n))",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nUse Union-Find after rejecting graphs whose edge count is not n - 1.\\n\\n## Key Insight\\n\\nWith n - 1 edges, detecting a repeated component connection rules out cycles and proves the tree condition.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n + E alpha(n))\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String graphValidTreeBfsConnectivitySolutionEntryJson() {
        String code = "import java.util.*; class Solution { public boolean validTree(int n, int[][] edges) { "
                + "if (edges.length != n - 1) { return false; } List<List<Integer>> graph = new ArrayList<>(); for (int node = 0; node < n; node++) { graph.add(new ArrayList<>()); } "
                + "for (int[] edge : edges) { graph.get(edge[0]).add(edge[1]); graph.get(edge[1]).add(edge[0]); } boolean[] seen = new boolean[n]; Queue<Integer> queue = new ArrayDeque<>(); "
                + "queue.offer(0); seen[0] = true; int visited = 0; while (!queue.isEmpty()) { int node = queue.poll(); visited++; for (int next : graph.get(node)) { if (!seen[next]) { seen[next] = true; queue.offer(next); } } } "
                + "return visited == n; } }";
        return """
                    {
                      "name": "BFS Connectivity Plus Edge Count Fixture",
                      "timeComplexity": "O(n + E)",
                      "spaceComplexity": "O(n + E)",
                      "description": "## Approach\\n\\nUse BFS to prove connectivity after checking that the edge count is n - 1.\\n\\n## Key Insight\\n\\nConnectivity plus exactly n - 1 undirected edges excludes all cycles.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n + E)\\n- Space Complexity: O(n + E)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String graphValidTreeDfsParentCycleSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public boolean validTree(int n, int[][] edges) { "
                + "List<List<Integer>> graph = new ArrayList<>(); for (int node = 0; node < n; node++) { graph.add(new ArrayList<>()); } "
                + "for (int[] edge : edges) { graph.get(edge[0]).add(edge[1]); graph.get(edge[1]).add(edge[0]); } boolean[] visited = new boolean[n]; "
                + "if (hasCycle(0, -1, graph, visited)) { return false; } for (boolean wasVisited : visited) { if (!wasVisited) { return false; } } return true; } "
                + "private boolean hasCycle(int node, int parent, List<List<Integer>> graph, boolean[] visited) { visited[node] = true; for (int next : graph.get(node)) { "
                + "if (next == parent) { continue; } if (visited[next]) { return true; } if (hasCycle(next, node, graph, visited)) { return true; } } return false; } }";
        return """
                    {
                      "name": "DFS Parent Cycle Detection Fixture",
                      "timeComplexity": "O(n + E)",
                      "spaceComplexity": "O(n + E)",
                      "description": "## Approach\\n\\nRun DFS with a parent argument, then scan visited nodes for connectivity.\\n\\n## Key Insight\\n\\nA visited non-parent neighbor is a true undirected cycle, while an unvisited node after DFS is a disconnected component.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n + E)\\n- Space Complexity: O(n + E)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String graphValidTreeLeafPeelingSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public boolean validTree(int n, int[][] edges) { "
                + "if (edges.length != n - 1) { return false; } if (n == 1) { return true; } List<List<Integer>> graph = new ArrayList<>(); int[] degree = new int[n]; "
                + "for (int node = 0; node < n; node++) { graph.add(new ArrayList<>()); } for (int[] edge : edges) { graph.get(edge[0]).add(edge[1]); graph.get(edge[1]).add(edge[0]); degree[edge[0]]++; degree[edge[1]]++; } "
                + "Queue<Integer> leaves = new ArrayDeque<>(); for (int node = 0; node < n; node++) { if (degree[node] == 1) { leaves.offer(node); } } int removed = 0; "
                + "while (!leaves.isEmpty()) { int node = leaves.poll(); removed++; for (int next : graph.get(node)) { degree[next]--; if (degree[next] == 1) { leaves.offer(next); } } } return removed == n; } }";
        return """
                    {
                      "name": "Leaf Peeling Fixture",
                      "timeComplexity": "O(n + E)",
                      "spaceComplexity": "O(n + E)",
                      "description": "## Approach\\n\\nRepeatedly remove leaves after checking that the graph has exactly n - 1 edges.\\n\\n## Key Insight\\n\\nA tree peels completely, but a graph with a cycle leaves a core that cannot be removed by leaf trimming.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n + E)\\n- Space Complexity: O(n + E)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

