    private static String wordLadderPairwiseGraphBfsSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public int ladderLength(String beginWord, String endWord, List<String> wordList) { "
                + "List<String> words = new ArrayList<>(); words.add(beginWord); int target = -1; for (String word : wordList) { if (!word.equals(beginWord)) { if (word.equals(endWord)) { target = words.size(); } words.add(word); } } if (target == -1) { return 0; } "
                + "List<List<Integer>> graph = new ArrayList<>(); for (int i = 0; i < words.size(); i++) { graph.add(new ArrayList<>()); } for (int i = 0; i < words.size(); i++) { for (int j = i + 1; j < words.size(); j++) { if (differsByOne(words.get(i), words.get(j))) { graph.get(i).add(j); graph.get(j).add(i); } } } "
                + "int[] distance = new int[words.size()]; Queue<Integer> queue = new ArrayDeque<>(); queue.offer(0); distance[0] = 1; while (!queue.isEmpty()) { int node = queue.poll(); if (node == target) { return distance[node]; } "
                + "for (int next : graph.get(node)) { if (distance[next] == 0) { distance[next] = distance[node] + 1; queue.offer(next); } } } return 0; } "
                + "private boolean differsByOne(String a, String b) { int differences = 0; for (int i = 0; i < a.length(); i++) { if (a.charAt(i) != b.charAt(i)) { differences++; if (differences > 1) { return false; } } } return differences == 1; } }";
        return """
                    {
                      "name": "Pairwise Graph BFS Baseline Fixture",
                      "timeComplexity": "O(N^2 * L)",
                      "spaceComplexity": "O(N^2)",
                      "description": "## Approach\\n\\nBuild the full one-letter-difference graph and then run BFS from beginWord.\\n\\n## Key Insight\\n\\nThis slower baseline exposes the underlying unweighted shortest-path graph directly.\\n\\n## Complexity Analysis\\n- Time Complexity: O(N^2 * L)\\n- Space Complexity: O(N^2)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

