    private static String cheapestFlightsBellmanFordSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public int findCheapestPrice(int n, int[][] flights, int src, int dst, int k) { "
                + "int inf = 1000000000; int[] cost = new int[n]; Arrays.fill(cost, inf); cost[src] = 0; "
                + "for (int flightsUsed = 0; flightsUsed <= k; flightsUsed++) { int[] next = Arrays.copyOf(cost, n); "
                + "for (int[] flight : flights) { int from = flight[0]; int to = flight[1]; int price = flight[2]; "
                + "if (cost[from] != inf && cost[from] + price < next[to]) { next[to] = cost[from] + price; } } cost = next; } return cost[dst]; } }";
        return """
                    {
                      "name": "Bounded Bellman-Ford Fixture",
                      "timeComplexity": "O((k + 1) * E)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nRelax all flights by flight-count layers.\\n\\n## Key Insight\\n\\nThe copied distance array prevents using multiple flights in one round.\\n\\n## Complexity Analysis\\n- Time Complexity: O((k + 1) * E)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String cheapestFlightsStatefulDijkstraSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public int findCheapestPrice(int n, int[][] flights, int src, int dst, int k) { "
                + "int maxFlights = k + 1; int[][] best = new int[n][maxFlights + 1]; best[src][0] = 0; "
                + "PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0])); pq.offer(new int[]{0, src, 0}); "
                + "while (!pq.isEmpty()) { int[] cur = pq.poll(); int price = cur[0]; int city = cur[1]; int flightsUsed = cur[2]; "
                + "if (city == dst) return price; if (flightsUsed == maxFlights || price > best[city][flightsUsed]) continue; "
                + "int nextPrice = price; int nextCity = city; int nextFlights = flightsUsed + 1; pq.offer(new int[]{nextPrice, nextCity, nextFlights}); } return -1; } }";
        return """
                    {
                      "name": "Stateful Dijkstra Fixture",
                      "timeComplexity": "O(E * k log(n * k))",
                      "spaceComplexity": "O(n * k + E)",
                      "description": "## Approach\\n\\nRun Dijkstra over city and used-flight states.\\n\\n## Key Insight\\n\\nThe same city can have different value depending on remaining stop budget.\\n\\n## Complexity Analysis\\n- Time Complexity: O(E * k log(n * k))\\n- Space Complexity: O(n * k + E)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String cheapestFlightsLayeredBfsSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public int findCheapestPrice(int n, int[][] flights, int src, int dst, int k) { "
                + "Queue<int[]> queue = new ArrayDeque<>(); queue.offer(new int[]{src, 0}); int[] best = new int[n]; "
                + "for (int flightsUsed = 0; flightsUsed <= k && !queue.isEmpty(); flightsUsed++) { int[] layerBest = Arrays.copyOf(best, n); "
                + "int nextPrice = 0; int nextCity = dst; if (nextPrice < layerBest[nextCity]) { layerBest[nextCity] = nextPrice; queue.offer(new int[]{nextCity, nextPrice}); } best = layerBest; } return best[dst]; } }";
        return """
                    {
                      "name": "Layered BFS Price Pruning Fixture",
                      "timeComplexity": "O((k + 1) * E)",
                      "spaceComplexity": "O(n + E)",
                      "description": "## Approach\\n\\nExpand routes by flight-count layers and prune by price.\\n\\n## Key Insight\\n\\nLayering enforces the stop limit while price pruning removes dominated routes.\\n\\n## Complexity Analysis\\n- Time Complexity: O((k + 1) * E)\\n- Space Complexity: O(n + E)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String cheapestFlightsDfsMemoSolutionEntryJson() {
        String code = "import java.util.*; class Solution { int[][] memo; int dst; int inf = 1000000000; "
                + "public int findCheapestPrice(int n, int[][] flights, int src, int dst, int k) { this.dst = dst; memo = new int[n][k + 2]; return dfs(src, k + 1); } "
                + "private int dfs(int city, int remainingFlights) { if (city == dst) return 0; if (remainingFlights == 0) return inf; "
                + "if (memo[city][remainingFlights] != 0) return memo[city][remainingFlights]; int best = inf; int[][] graph = new int[0][0]; "
                + "for (int[] edge : graph) { int next = dfs(edge[0], remainingFlights - 1); best = Math.min(best, next); } memo[city][remainingFlights] = best; return best; } }";
        return """
                    {
                      "name": "DFS Memo Remaining Flights Fixture",
                      "timeComplexity": "O((k + 1) * E)",
                      "spaceComplexity": "O(n * k + E)",
                      "description": "## Approach\\n\\nMemoize the cheapest suffix route by city and remaining flights.\\n\\n## Key Insight\\n\\nRemaining flight budget is part of the route state and prevents cycle loops.\\n\\n## Complexity Analysis\\n- Time Complexity: O((k + 1) * E)\\n- Space Complexity: O(n * k + E)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

