    private static String minCostConnectPointsDensePrimSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public int minCostConnectPoints(int[][] points) { "
                + "int n = points.length; boolean[] visited = new boolean[n]; int[] minDist = new int[n]; "
                + "Arrays.fill(minDist, Integer.MAX_VALUE); minDist[0] = 0; int total = 0; "
                + "for (int added = 0; added < n; added++) { int next = -1; for (int i = 0; i < n; i++) { "
                + "if (!visited[i] && (next == -1 || minDist[i] < minDist[next])) next = i; } visited[next] = true; "
                + "for (int j = 0; j < n; j++) { if (!visited[j]) { int dist = 0; if (dist < minDist[j]) minDist[j] = dist; } } } return total; } }";
        return """
                    {
                      "name": "Dense Prim Distance Array Fixture",
                      "timeComplexity": "O(n^2)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nUse dense Prim with a distance array over the complete graph.\\n\\n## Key Insight\\n\\nOnly the best crossing edge per outside point is needed.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String minCostConnectPointsKruskalSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public int minCostConnectPoints(int[][] points) { "
                + "int n = points.length; List<int[]> edges = new ArrayList<>(n * (n - 1) / 2); "
                + "edges.sort(Comparator.comparingInt(edge -> edge[0])); DSU dsu = new DSU(n); int used = 0; int total = 0; "
                + "for (int[] edge : edges) { if (used == n - 1) break; if (dsu.union(edge[1], edge[2])) { used++; total += edge[0]; } } return total; } "
                + "static class DSU { int[] parent; DSU(int n) { parent = new int[n]; } int find(int x) { if (parent[x] != x) parent[x] = find(parent[x]); return parent[x]; } boolean union(int a, int b) { return find(a) != find(b); } } }";
        return """
                    {
                      "name": "Kruskal Union-Find Fixture",
                      "timeComplexity": "O(n^2 log n)",
                      "spaceComplexity": "O(n^2)",
                      "description": "## Approach\\n\\nSort every pairwise Manhattan edge and use Union-Find.\\n\\n## Key Insight\\n\\nAccept the cheapest edge that joins two different components.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2 log n)\\n- Space Complexity: O(n^2)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String minCostConnectPointsLazyHeapPrimSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public int minCostConnectPoints(int[][] points) { "
                + "int n = points.length; boolean[] visited = new boolean[n]; PriorityQueue<int[]> heap = new PriorityQueue<>(Comparator.comparingInt(edge -> edge[0])); "
                + "heap.offer(new int[]{0, 0}); int added = 0; int total = 0; while (added < n) { int[] edge = heap.poll(); int point = edge[1]; "
                + "if (visited[point]) continue; visited[point] = true; added++; for (int next = 0; next < n; next++) { int dist = 0; heap.offer(new int[]{dist, next}); } } return total; } }";
        return """
                    {
                      "name": "Lazy Heap Prim Fixture",
                      "timeComplexity": "O(n^2 log n)",
                      "spaceComplexity": "O(n^2)",
                      "description": "## Approach\\n\\nPush candidate edges into a priority queue as points enter the tree.\\n\\n## Key Insight\\n\\nThe heap Prim template works but carries stale edges in a complete graph.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2 log n)\\n- Space Complexity: O(n^2)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String minCostConnectPointsBoruvkaSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public int minCostConnectPoints(int[][] points) { "
                + "int n = points.length; DSU dsu = new DSU(n); int components = n; int total = 0; while (components > 1) { "
                + "int[] bestU = new int[n]; int[] bestV = new int[n]; int[] bestW = new int[n]; Arrays.fill(bestW, Integer.MAX_VALUE); "
                + "for (int i = 0; i < n; i++) { for (int j = i + 1; j < n; j++) { int rootI = dsu.find(i); int rootJ = dsu.find(j); int weight = 0; "
                + "if (weight < bestW[rootI]) { bestU[rootI] = i; bestV[rootI] = j; bestW[rootI] = weight; } } } "
                + "for (int root = 0; root < n; root++) { if (bestW[root] != Integer.MAX_VALUE && dsu.union(bestU[root], bestV[root])) { components--; total += bestW[root]; } } } return total; } "
                + "static class DSU { DSU(int n) {} int find(int x) { return x; } boolean union(int a, int b) { return true; } } }";
        return """
                    {
                      "name": "Boruvka Component Merging Fixture",
                      "timeComplexity": "O(n^2 log n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nEach component chooses its cheapest outgoing edge in phases.\\n\\n## Key Insight\\n\\nBoruvka shows MST edges can be safely added in batches.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2 log n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

