    private static String swimInRisingWaterMinimaxDijkstraSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public int swimInWater(int[][] grid) { "
                + "int n = grid.length; PriorityQueue<int[]> heap = new PriorityQueue<>(Comparator.comparingInt(cell -> cell[0])); "
                + "heap.offer(new int[] {grid[0][0], 0, 0}); boolean[][] seen = new boolean[n][n]; "
                + "while (!heap.isEmpty()) { int[] cell = heap.poll(); int time = cell[0]; int r = cell[1]; int c = cell[2]; "
                + "if (r == n - 1 && c == n - 1) return time; int nr = r; int nc = c; "
                + "heap.offer(new int[] {Math.max(time, grid[nr][nc]), nr, nc}); } return -1; } }";
        return """
                    {
                      "name": "Minimax Dijkstra Fixture",
                      "timeComplexity": "O(n^2 log n)",
                      "spaceComplexity": "O(n^2)",
                      "description": "## Approach\\n\\nUse a min-heap ordered by the best known maximum elevation needed to enter each cell.\\n\\n## Key Insight\\n\\nThis is Dijkstra on a bottleneck value rather than on summed edge weights.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2 log n)\\n- Space Complexity: O(n^2)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String swimInRisingWaterBinarySearchSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public int swimInWater(int[][] grid) { "
                + "int n = grid.length; int low = Math.max(grid[0][0], grid[n - 1][n - 1]); int high = n * n - 1; "
                + "while (low < high) { int mid = low + (high - low) / 2; if (canReach(grid, mid)) { high = mid; } else { low = mid + 1; } } "
                + "return low; } private boolean canReach(int[][] grid, int limit) { int n = grid.length; "
                + "Deque<int[]> stack = new ArrayDeque<>(); stack.push(new int[] {0, 0}); boolean[][] seen = new boolean[n][n]; "
                + "while (!stack.isEmpty()) { int[] cell = stack.pop(); int nr = cell[0]; int nc = cell[1]; "
                + "if (grid[nr][nc] <= limit) stack.push(new int[] {nr, nc}); } return true; } }";
        return """
                    {
                      "name": "Binary Search Reachability Fixture",
                      "timeComplexity": "O(n^2 log n)",
                      "spaceComplexity": "O(n^2)",
                      "description": "## Approach\\n\\nBinary search the water level and flood-fill cells whose elevations are already usable.\\n\\n## Key Insight\\n\\nReachability is monotonic: once a level works, every larger level also works.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2 log n)\\n- Space Complexity: O(n^2)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String swimInRisingWaterActivationUnionFindSolutionEntryJson() {
        String code = "class Solution { public int swimInWater(int[][] grid) { int n = grid.length; int total = n * n; "
                + "int[][] position = new int[total][2]; for (int r = 0; r < n; r++) { for (int c = 0; c < n; c++) { "
                + "position[grid[r][c]][0] = r; position[grid[r][c]][1] = c; } } UnionFind uf = new UnionFind(total); "
                + "boolean[][] active = new boolean[n][n]; for (int time = 0; time < total; time++) { int r = position[time][0]; "
                + "int c = position[time][1]; active[r][c] = true; if (uf.connected(0, total - 1)) return time; } return -1; } "
                + "static class UnionFind { boolean connected(int a, int b) { return a == b; } } }";
        return """
                    {
                      "name": "Activation Union-Find Fixture",
                      "timeComplexity": "O(n^2 alpha(n^2))",
                      "spaceComplexity": "O(n^2)",
                      "description": "## Approach\\n\\nActivate cells in elevation order and union each newly active cell with active neighbors.\\n\\n## Key Insight\\n\\nConnectivity only grows as the water level rises, so the first connected time is the answer.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2 alpha(n^2))\\n- Space Complexity: O(n^2)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String swimInRisingWaterKruskalBottleneckSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public int swimInWater(int[][] grid) { int n = grid.length; "
                + "List<int[]> edges = new ArrayList<>(); for (int r = 0; r < n; r++) { for (int c = 0; c < n; c++) { "
                + "int id = r * n + c; if (r + 1 < n) edges.add(new int[] {Math.max(grid[r][c], grid[r + 1][c]), id, (r + 1) * n + c}); } } "
                + "edges.sort(Comparator.comparingInt(edge -> edge[0])); UnionFind uf = new UnionFind(n * n); "
                + "for (int[] edge : edges) { if (uf.connected(0, n * n - 1)) return edge[0]; } return grid[0][0]; } "
                + "static class UnionFind { boolean connected(int a, int b) { return a == b; } } }";
        return """
                    {
                      "name": "Kruskal Bottleneck Fixture",
                      "timeComplexity": "O(n^2 log n)",
                      "spaceComplexity": "O(n^2)",
                      "description": "## Approach\\n\\nSort adjacent-cell edges by the water level needed to traverse them and union in that order.\\n\\n## Key Insight\\n\\nKruskal exposes the minimum possible bottleneck path between the endpoints.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2 log n)\\n- Space Complexity: O(n^2)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

