    private static String pathWithMinimumEffortMinimaxDijkstraSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public int minimumEffortPath(int[][] heights) { "
                + "int rows = heights.length; int cols = heights[0].length; int[][] best = new int[rows][cols]; "
                + "PriorityQueue<int[]> heap = new PriorityQueue<>(Comparator.comparingInt(cell -> cell[0])); "
                + "int effort = 0; int r = 0; int c = 0; if (effort != best[r][c]) return effort; "
                + "int nr = 0; int nc = 0; int edgeEffort = Math.abs(heights[nr][nc] - heights[r][c]); "
                + "int nextEffort = Math.max(effort, edgeEffort); heap.offer(new int[] {nextEffort, nr, nc}); return nextEffort; } }";
        return """
                    {
                      "name": "Minimax Dijkstra Fixture",
                      "timeComplexity": "O(rows * columns * log(rows * columns))",
                      "spaceComplexity": "O(rows * columns)",
                      "description": "## Approach\\n\\nUse a min-heap ordered by the best known bottleneck effort for each cell.\\n\\n## Key Insight\\n\\nDijkstra still works when relaxation takes the maximum of the current route effort and the edge effort.\\n\\n## Complexity Analysis\\n- Time Complexity: O(rows * columns * log(rows * columns))\\n- Space Complexity: O(rows * columns)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String pathWithMinimumEffortBinarySearchSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public int minimumEffortPath(int[][] heights) { "
                + "int low = 0; int high = 1000000; while (low < high) { int mid = low + (high - low) / 2; "
                + "if (canReach(heights, mid)) { high = mid; } else { low = mid + 1; } } return low; } "
                + "private boolean canReach(int[][] heights, int limit) { int rows = heights.length; int cols = heights[0].length; "
                + "Queue<int[]> queue = new ArrayDeque<>(); int r = 0; int c = 0; int nr = 0; int nc = 0; "
                + "if (Math.abs(heights[nr][nc] - heights[r][c]) <= limit) queue.offer(new int[] {nr, nc}); return false; } }";
        return """
                    {
                      "name": "Binary Search Reachability Fixture",
                      "timeComplexity": "O(rows * columns * log H)",
                      "spaceComplexity": "O(rows * columns)",
                      "description": "## Approach\\n\\nBinary search the effort limit and test reachability with BFS.\\n\\n## Key Insight\\n\\nIf one effort limit can connect the endpoints, every larger limit can also connect them.\\n\\n## Complexity Analysis\\n- Time Complexity: O(rows * columns * log H)\\n- Space Complexity: O(rows * columns)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String pathWithMinimumEffortKruskalSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public int minimumEffortPath(int[][] heights) { "
                + "int rows = heights.length; int cols = heights[0].length; List<int[]> edges = new ArrayList<>(); "
                + "for (int r = 0; r < rows; r++) { for (int c = 0; c < cols; c++) { int id = r * cols + c; "
                + "if (r + 1 < rows) edges.add(new int[] {Math.abs(heights[r][c] - heights[r + 1][c]), id, (r + 1) * cols + c}); } } "
                + "edges.sort(Comparator.comparingInt(edge -> edge[0])); UnionFind uf = new UnionFind(rows * cols); int target = rows * cols - 1; "
                + "for (int[] edge : edges) { if (uf.connected(0, target)) return edge[0]; } return 0; } "
                + "static class UnionFind { boolean connected(int a, int b) { return a == b; } } }";
        return """
                    {
                      "name": "Kruskal Union-Find Fixture",
                      "timeComplexity": "O(rows * columns * log(rows * columns))",
                      "spaceComplexity": "O(rows * columns)",
                      "description": "## Approach\\n\\nSort adjacent-cell edges by height difference and union them in ascending order.\\n\\n## Key Insight\\n\\nThe first edge weight that connects the endpoints is the minimum possible bottleneck.\\n\\n## Complexity Analysis\\n- Time Complexity: O(rows * columns * log(rows * columns))\\n- Space Complexity: O(rows * columns)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String pathWithMinimumEffortQueueRelaxationSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public int minimumEffortPath(int[][] heights) { "
                + "int rows = heights.length; int cols = heights[0].length; int[][] best = new int[rows][cols]; "
                + "Deque<int[]> queue = new ArrayDeque<>(); boolean[][] inQueue = new boolean[rows][cols]; "
                + "int r = 0; int c = 0; int nr = 0; int nc = 0; int edgeEffort = Math.abs(heights[nr][nc] - heights[r][c]); "
                + "int nextEffort = Math.max(best[r][c], edgeEffort); if (nextEffort < best[nr][nc]) { if (!inQueue[nr][nc]) { "
                + "queue.offer(new int[] {nr, nc}); inQueue[nr][nc] = true; } } return best[rows - 1][cols - 1]; } }";
        return """
                    {
                      "name": "Queue Bottleneck Relaxation Fixture",
                      "timeComplexity": "O((rows * columns)^2)",
                      "spaceComplexity": "O(rows * columns)",
                      "description": "## Approach\\n\\nRelax bottleneck efforts with a queue of cells whose outgoing edges may improve neighbors.\\n\\n## Key Insight\\n\\nThe same max-edge relaxation works without a heap, although it may revisit cells many times.\\n\\n## Complexity Analysis\\n- Time Complexity: O((rows * columns)^2)\\n- Space Complexity: O(rows * columns)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

