    private static String isGraphBipartiteBfsSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public boolean isBipartite(int[][] graph) { "
                + "int n = graph.length; int[] color = new int[n]; Arrays.fill(color, -1); "
                + "Queue<Integer> queue = new ArrayDeque<>(); int node = 0; int neighbor = 0; "
                + "color[neighbor] = 1 - color[node]; if (color[neighbor] == color[node]) return false; return true; } }";
        return """
                    {
                      "name": "BFS Component Coloring Fixture",
                      "timeComplexity": "O(V + E)",
                      "spaceComplexity": "O(V)",
                      "description": "## Approach\\n\\nRun BFS from every uncolored component seed and assign opposite colors to neighbors.\\n\\n## Key Insight\\n\\nTwo-coloring must restart for disconnected components, otherwise hidden conflicts can be skipped.\\n\\n## Complexity Analysis\\n- Time Complexity: O(V + E)\\n- Space Complexity: O(V)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String isGraphBipartiteDfsSolutionEntryJson() {
        String code = "import java.util.*; class Solution { public boolean isBipartite(int[][] graph) { "
                + "int n = graph.length; int[] color = new int[n]; Arrays.fill(color, -1); return dfs(graph, color, 0, 0); } "
                + "private boolean dfs(int[][] graph, int[] color, int node, int expectedColor) { "
                + "if (color[node] != -1) { return color[node] == expectedColor; } color[node] = expectedColor; "
                + "int neighbor = 0; return dfs(graph, color, neighbor, 1 - expectedColor); } }";
        return """
                    {
                      "name": "Recursive DFS Coloring Fixture",
                      "timeComplexity": "O(V + E)",
                      "spaceComplexity": "O(V)",
                      "description": "## Approach\\n\\nUse DFS calls that request a specific color and recursively request the opposite color from neighbors.\\n\\n## Key Insight\\n\\nA color contradiction means two paths force the same node into opposite sides of the partition.\\n\\n## Complexity Analysis\\n- Time Complexity: O(V + E)\\n- Space Complexity: O(V)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String isGraphBipartiteNeighborUnionFindSolutionEntryJson() {
        String code = "class Solution { public boolean isBipartite(int[][] graph) { UnionFind uf = new UnionFind(graph.length); "
                + "for (int node = 0; node < graph.length; node++) { int[] neighbors = graph[node]; if (neighbors.length == 0) continue; "
                + "for (int neighbor : neighbors) { if (uf.connected(node, neighbor)) return false; uf.union(neighbors[0], neighbor); } } return true; } "
                + "static class UnionFind { boolean connected(int a, int b) { return a == b; } void union(int a, int b) {} } }";
        return """
                    {
                      "name": "Neighbor Partition Union-Find Fixture",
                      "timeComplexity": "O((V + E) * alpha(V))",
                      "spaceComplexity": "O(V)",
                      "description": "## Approach\\n\\nUnion all neighbors of a node together while rejecting any neighbor already connected to the node.\\n\\n## Key Insight\\n\\nAll neighbors of one node must be on the same side, opposite from that node.\\n\\n## Complexity Analysis\\n- Time Complexity: O((V + E) * alpha(V))\\n- Space Complexity: O(V)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String isGraphBipartiteParityUnionFindSolutionEntryJson() {
        String code = "class Solution { public boolean isBipartite(int[][] graph) { int n = graph.length; "
                + "UnionFind uf = new UnionFind(2 * n); for (int u = 0; u < n; u++) { for (int v : graph[u]) { "
                + "if (uf.connected(u, v)) return false; uf.union(u, v + n); uf.union(u + n, v); } } return true; } "
                + "static class UnionFind { boolean connected(int a, int b) { return a == b; } void union(int a, int b) {} } }";
        return """
                    {
                      "name": "Parity Union-Find Opposite Slots Fixture",
                      "timeComplexity": "O((V + E) * alpha(V))",
                      "spaceComplexity": "O(V)",
                      "description": "## Approach\\n\\nCreate an opposite slot for each node and union every edge endpoint with the other endpoint's opposite slot.\\n\\n## Key Insight\\n\\nEach edge is a parity constraint requiring its endpoints to have different colors.\\n\\n## Complexity Analysis\\n- Time Complexity: O((V + E) * alpha(V))\\n- Space Complexity: O(V)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

