    private static String minCostClimbingStairsBottomUpTableSolutionEntryJson() {
        String code = "class Solution { public int minCostClimbingStairs(int[] cost) { int n = cost.length; int[] dp = new int[n + 1]; "
                + "dp[0] = 0; dp[1] = 0; for (int step = 2; step <= n; step++) { int fromOneBelow = dp[step - 1] + cost[step - 1]; "
                + "int fromTwoBelow = dp[step - 2] + cost[step - 2]; dp[step] = Math.min(fromOneBelow, fromTwoBelow); } return dp[n]; } }";
        return """
                    {
                      "name": "Bottom-Up DP Table Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nFill a table of minimum costs to reach each virtual position, including the no-cost top.\\n\\n## Key Insight\\n\\nThe top is not a paid stair, so dp[n] is reached by paying the last stair actually stepped on.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String minCostClimbingStairsSpaceOptimizedSolutionEntryJson() {
        String code = "class Solution { public int minCostClimbingStairs(int[] cost) { int twoStepsBack = 0; int oneStepBack = 0; "
                + "for (int step = 2; step <= cost.length; step++) { int current = Math.min(oneStepBack + cost[step - 1], "
                + "twoStepsBack + cost[step - 2]); twoStepsBack = oneStepBack; oneStepBack = current; } return oneStepBack; } }";
        return """
                    {
                      "name": "Space-Optimized Dynamic Programming Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nRoll the two previous virtual-position costs forward instead of storing the whole table.\\n\\n## Key Insight\\n\\nThe recurrence only depends on the previous two positions, so older states can be discarded.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String minCostClimbingStairsMemoizedRecursionSolutionEntryJson() {
        String code = "import java.util.Arrays; class Solution { public int minCostClimbingStairs(int[] cost) { int[] memo = new int[cost.length + 1]; "
                + "Arrays.fill(memo, -1); return minCost(cost, cost.length, memo); } private int minCost(int[] cost, int step, int[] memo) { "
                + "if (step <= 1) return 0; if (memo[step] != -1) return memo[step]; int fromOneBelow = minCost(cost, step - 1, memo) + cost[step - 1]; "
                + "int fromTwoBelow = minCost(cost, step - 2, memo) + cost[step - 2]; memo[step] = Math.min(fromOneBelow, fromTwoBelow); return memo[step]; } }";
        return """
                    {
                      "name": "Top-Down Memoized Recursion Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nRecursively compute the minimum cost to reach each virtual position and cache each step.\\n\\n## Key Insight\\n\\nStarting positions 0 and 1 have zero cost before the first paid stair, so step <= 1 is the base case.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String minCostClimbingStairsInPlaceAccumulationSolutionEntryJson() {
        String code = "class Solution { public int minCostClimbingStairs(int[] cost) { int n = cost.length; "
                + "for (int i = 2; i < n; i++) { cost[i] += Math.min(cost[i - 1], cost[i - 2]); } return Math.min(cost[n - 1], cost[n - 2]); } }";
        return """
                    {
                      "name": "In-Place Cost Accumulation Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nMutate the cost array so each stair stores the cheapest accumulated cost to land there.\\n\\n## Key Insight\\n\\nBecause the top has no cost, the answer is the cheaper accumulated value among the last two stairs.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String minCostClimbingStairsDagShortestPathSolutionEntryJson() {
        String code = "import java.util.Arrays; class Solution { public int minCostClimbingStairs(int[] cost) { int n = cost.length; "
                + "int[] dist = new int[n + 1]; Arrays.fill(dist, Integer.MAX_VALUE / 4); dist[0] = cost[0]; dist[1] = cost[1]; "
                + "for (int step = 0; step < n; step++) { for (int jump = 1; jump <= 2; jump++) { int next = step + jump; if (next > n) continue; "
                + "int nextCost = next == n ? 0 : cost[next]; dist[next] = Math.min(dist[next], dist[step] + nextCost); } } return dist[n]; } }";
        return """
                    {
                      "name": "DAG Shortest Path Relaxation Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nRelax one-step and two-step edges through the staircase DAG until the virtual top is reached.\\n\\n## Key Insight\\n\\nThe DP recurrence is a shortest-path relaxation over positions, with zero cost for entering the top.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

