    private static String longestPalindromicSubstringBruteForceSolutionEntryJson() {
        String code = "class Solution { public String longestPalindrome(String s) { int n = s.length(); "
                + "for (int length = n; length >= 1; length--) { for (int start = 0; start + length <= n; start++) { "
                + "int end = start + length - 1; if (isPalindrome(s, start, end)) { return s.substring(start, end + 1); } } } "
                + "return \\\"\\\"; } private boolean isPalindrome(String s, int left, int right) { while (left < right) { "
                + "if (s.charAt(left) != s.charAt(right)) return false; left++; right--; } return true; } }";
        return """
                    {
                      "name": "Length-Descending Brute Force Fixture",
                      "timeComplexity": "O(n^3)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nTry longer substrings first and validate each candidate with two pointers.\\n\\n## Key Insight\\n\\nDescending length makes the first palindrome optimal, and scanning starts left to right preserves the tie rule.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^3)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String longestPalindromicSubstringCenterExpansionSolutionEntryJson() {
        String code = "class Solution { public String longestPalindrome(String s) { int n = s.length(); int bestStart = 0; int bestLength = 1; "
                + "for (int center = 0; center < n; center++) { int oddLength = expand(s, center, center); "
                + "if (oddLength > bestLength) { bestStart = center - oddLength / 2; bestLength = oddLength; } "
                + "int evenLength = expand(s, center, center + 1); if (evenLength > bestLength) { "
                + "bestStart = center - evenLength / 2 + 1; bestLength = evenLength; } } "
                + "return s.substring(bestStart, bestStart + bestLength); } private int expand(String s, int left, int right) { "
                + "while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) { left--; right++; } "
                + "return right - left - 1; } }";
        return """
                    {
                      "name": "Expand Around Center Fixture",
                      "timeComplexity": "O(n^2)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nExpand every odd and even center, keeping only strictly longer palindromes.\\n\\n## Key Insight\\n\\nA palindrome is determined by its center and radius, so expansion directly checks mirrored characters.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String longestPalindromicSubstringDpTableSolutionEntryJson() {
        String code = "class Solution { public String longestPalindrome(String s) { int n = s.length(); boolean[][] palindrome = new boolean[n][n]; "
                + "int bestStart = 0; int bestLength = 1; for (int length = 1; length <= n; length++) { "
                + "for (int start = 0; start + length <= n; start++) { int end = start + length - 1; "
                + "if (s.charAt(start) == s.charAt(end) && (length <= 2 || palindrome[start + 1][end - 1])) { "
                + "palindrome[start][end] = true; if (length > bestLength) { bestStart = start; bestLength = length; } } } } "
                + "return s.substring(bestStart, bestStart + bestLength); } }";
        return """
                    {
                      "name": "Dynamic Programming Table Fixture",
                      "timeComplexity": "O(n^2)",
                      "spaceComplexity": "O(n^2)",
                      "description": "## Approach\\n\\nFill a palindrome table from short ranges to long ranges.\\n\\n## Key Insight\\n\\nA longer range is a palindrome when its endpoints match and its inner range is a palindrome.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2)\\n- Space Complexity: O(n^2)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String longestPalindromicSubstringManacherSolutionEntryJson() {
        String code = "class Solution { public String longestPalindrome(String s) { int n = s.length(); char[] transformed = new char[n * 2 + 3]; "
                + "transformed[0] = '^'; int index = 1; for (int i = 0; i < n; i++) { transformed[index++] = '#'; transformed[index++] = s.charAt(i); } "
                + "transformed[index++] = '#'; transformed[index] = '$'; int[] radius = new int[transformed.length]; int center = 0; int right = 0; "
                + "int bestCenter = 0; int bestLength = 0; for (int i = 1; i < transformed.length - 1; i++) { int mirror = 2 * center - i; "
                + "if (i < right) { radius[i] = Math.min(right - i, radius[mirror]); } "
                + "while (transformed[i + 1 + radius[i]] == transformed[i - 1 - radius[i]]) { radius[i]++; } "
                + "if (i + radius[i] > right) { center = i; right = i + radius[i]; } if (radius[i] > bestLength) { bestLength = radius[i]; bestCenter = i; } } "
                + "int start = (bestCenter - bestLength) / 2; return s.substring(start, start + bestLength); } }";
        return """
                    {
                      "name": "Manacher Linear-Time Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nUse separators and mirror radii from the rightmost known palindrome.\\n\\n## Key Insight\\n\\nA center inside the right boundary can reuse its mirrored radius and only expand beyond unknown territory.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String longestPalindromicSubstringReverseLcsGuardSolutionEntryJson() {
        String code = "class Solution { public String longestPalindrome(String s) { int n = s.length(); String reversed = new StringBuilder(s).reverse().toString(); "
                + "int[][] dp = new int[n + 1][n + 1]; int bestStart = 0; int bestLength = 1; for (int i = 1; i <= n; i++) { "
                + "for (int j = 1; j <= n; j++) { if (s.charAt(i - 1) != reversed.charAt(j - 1)) continue; "
                + "dp[i][j] = dp[i - 1][j - 1] + 1; int originalStart = n - j; int length = i - originalStart; "
                + "if (originalStart >= 0 && length > bestLength && length <= dp[i][j]) { bestStart = originalStart; bestLength = length; } } } "
                + "return s.substring(bestStart, bestStart + bestLength); } }";
        return """
                    {
                      "name": "Reversed String LCS with Index Guard Fixture",
                      "timeComplexity": "O(n^2)",
                      "spaceComplexity": "O(n^2)",
                      "description": "## Approach\\n\\nFind common substrings between the string and its reverse, then require matching original indices.\\n\\n## Key Insight\\n\\nThe index guard rejects common substrings that are not mirrored in place.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2)\\n- Space Complexity: O(n^2)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

