    private static String palindromicSubstringsBruteForceSolutionEntryJson() {
        String code = "class Solution { public int countSubstrings(String s) { int n = s.length(); int count = 0; "
                + "for (int start = 0; start < n; start++) { for (int end = start; end < n; end++) { "
                + "if (isPalindrome(s, start, end)) { count++; } } } return count; } "
                + "private boolean isPalindrome(String s, int left, int right) { while (left < right) { "
                + "if (s.charAt(left) != s.charAt(right)) { return false; } left++; right--; } return true; } }";
        return """
                    {
                      "name": "Brute Force Substring Validation Fixture",
                      "timeComplexity": "O(n^3)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nEnumerate every substring range and validate it with two pointers.\\n\\n## Key Insight\\n\\nEach start-end range is a separate occurrence, even when the text is repeated.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^3)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String palindromicSubstringsCenterExpansionSolutionEntryJson() {
        String code = "class Solution { public int countSubstrings(String s) { int count = 0; "
                + "for (int center = 0; center < s.length(); center++) { count += countAroundCenter(s, center, center); "
                + "count += countAroundCenter(s, center, center + 1); } return count; } "
                + "private int countAroundCenter(String s, int left, int right) { int palindromes = 0; "
                + "while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) { "
                + "palindromes++; left--; right++; } return palindromes; } }";
        return """
                    {
                      "name": "Expand Around Center Counting Fixture",
                      "timeComplexity": "O(n^2)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nExpand from every odd and even center and count every successful radius.\\n\\n## Key Insight\\n\\nEach palindromic substring is found exactly once from its center.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String palindromicSubstringsDpTableSolutionEntryJson() {
        String code = "class Solution { public int countSubstrings(String s) { int n = s.length(); boolean[][] palindrome = new boolean[n][n]; "
                + "int count = 0; for (int length = 1; length <= n; length++) { for (int start = 0; start + length <= n; start++) { "
                + "int end = start + length - 1; if (s.charAt(start) == s.charAt(end) && (length <= 2 || palindrome[start + 1][end - 1])) { "
                + "palindrome[start][end] = true; count++; } } } return count; } }";
        return """
                    {
                      "name": "Dynamic Programming Palindrome Table Fixture",
                      "timeComplexity": "O(n^2)",
                      "spaceComplexity": "O(n^2)",
                      "description": "## Approach\\n\\nFill a table of palindrome ranges from shorter lengths to longer lengths.\\n\\n## Key Insight\\n\\nA range is palindromic when its endpoints match and the inner range is palindromic.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2)\\n- Space Complexity: O(n^2)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String palindromicSubstringsMemoizedRangeSolutionEntryJson() {
        String code = "class Solution { public int countSubstrings(String s) { int n = s.length(); int[][] memo = new int[n][n]; "
                + "int count = 0; for (int start = 0; start < n; start++) { for (int end = start; end < n; end++) { "
                + "if (isPalindrome(s, start, end, memo)) { count++; } } } return count; } "
                + "private boolean isPalindrome(String s, int left, int right, int[][] memo) { if (left >= right) { return true; } "
                + "if (memo[left][right] != 0) { return memo[left][right] == 1; } "
                + "boolean ok = s.charAt(left) == s.charAt(right) && isPalindrome(s, left + 1, right - 1, memo); "
                + "memo[left][right] = ok ? 1 : -1; return ok; } }";
        return """
                    {
                      "name": "Top-Down Memoized Range Check Fixture",
                      "timeComplexity": "O(n^2)",
                      "spaceComplexity": "O(n^2)",
                      "description": "## Approach\\n\\nEnumerate ranges but cache each recursive palindrome decision.\\n\\n## Key Insight\\n\\nEach left-right range has one truth value that can be reused by outer ranges.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2)\\n- Space Complexity: O(n^2)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String palindromicSubstringsManacherSolutionEntryJson() {
        String code = "class Solution { public int countSubstrings(String s) { int n = s.length(); char[] transformed = new char[n * 2 + 3]; "
                + "int index = 0; transformed[index++] = '^'; for (int i = 0; i < n; i++) { transformed[index++] = '#'; transformed[index++] = s.charAt(i); } "
                + "transformed[index++] = '#'; transformed[index++] = '$'; int[] radius = new int[transformed.length]; int center = 0; int right = 0; "
                + "int count = 0; for (int i = 1; i < index - 1; i++) { int mirror = 2 * center - i; "
                + "if (i < right && mirror >= 0) { radius[i] = Math.min(right - i, radius[mirror]); } "
                + "while (i + 1 + radius[i] < index && i - 1 - radius[i] >= 0 && transformed[i + 1 + radius[i]] == transformed[i - 1 - radius[i]]) { radius[i]++; } "
                + "if (i + radius[i] > right) { center = i; right = i + radius[i]; } count += (radius[i] + 1) / 2; } return count; } }";
        return """
                    {
                      "name": "Manacher Radius Counting Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nUse transformed-string radii and convert each center's radius into original substring counts.\\n\\n## Key Insight\\n\\nA transformed radius contributes half-step palindrome occurrences in the original string.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

