    private static String decodeWaysPrefixDpSolutionEntryJson() {
        String code = "class Solution { public int numDecodings(String s) { int n = s.length(); "
                + "int[] dp = new int[n + 1]; dp[0] = 1; dp[1] = s.charAt(0) == '0' ? 0 : 1; "
                + "for (int i = 2; i <= n; i++) { if (s.charAt(i - 1) != '0') { dp[i] += dp[i - 1]; } "
                + "int twoDigit = Integer.parseInt(s.substring(i - 2, i)); "
                + "if (twoDigit >= 10 && twoDigit <= 26) { dp[i] += dp[i - 2]; } } return dp[n]; } }";
        return """
                    {
                      "name": "Forward Prefix DP Table Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nFill prefix counts from left to right.\\n\\n## Key Insight\\n\\nThe last group of a valid decoding has length one or two.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String decodeWaysSuffixDpSolutionEntryJson() {
        String code = "class Solution { public int numDecodings(String s) { int n = s.length(); "
                + "int[] dp = new int[n + 2]; dp[n] = 1; for (int index = n - 1; index >= 0; index--) { "
                + "if (s.charAt(index) == '0') { dp[index] = 0; continue; } dp[index] = dp[index + 1]; "
                + "if (index + 1 < n && isValidPair(s, index)) { dp[index] += dp[index + 2]; } } return dp[0]; } "
                + "private boolean isValidPair(String s, int index) { char tens = s.charAt(index); "
                + "char ones = s.charAt(index + 1); return tens == '1' || (tens == '2' && ones <= '6'); } }";
        return """
                    {
                      "name": "Backward Suffix DP Table Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nFill suffix counts from right to left.\\n\\n## Key Insight\\n\\nA suffix starting with zero has no valid decoding.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String decodeWaysRollingDpSolutionEntryJson() {
        String code = "class Solution { public int numDecodings(String s) { int n = s.length(); "
                + "int twoBack = 1; int oneBack = s.charAt(0) == '0' ? 0 : 1; "
                + "for (int i = 2; i <= n; i++) { int current = 0; if (s.charAt(i - 1) != '0') { current += oneBack; } "
                + "int twoDigit = (s.charAt(i - 2) - '0') * 10 + (s.charAt(i - 1) - '0'); "
                + "if (twoDigit >= 10 && twoDigit <= 26) { current += twoBack; } "
                + "twoBack = oneBack; oneBack = current; } return oneBack; } }";
        return """
                    {
                      "name": "Rolling Prefix DP Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nKeep only the previous two prefix counts.\\n\\n## Key Insight\\n\\nThe prefix recurrence depends only on two earlier states.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String decodeWaysMemoizedSuffixSolutionEntryJson() {
        String code = "import java.util.Arrays; class Solution { public int numDecodings(String s) { "
                + "int[] memo = new int[s.length()]; Arrays.fill(memo, -1); return waysFrom(s, 0, memo); } "
                + "private int waysFrom(String s, int index, int[] memo) { if (index == s.length()) { return 1; } "
                + "if (s.charAt(index) == '0') { return 0; } if (memo[index] != -1) { return memo[index]; } "
                + "int ways = waysFrom(s, index + 1, memo); if (index + 1 < s.length() && isValidPair(s, index)) { "
                + "ways += waysFrom(s, index + 2, memo); } memo[index] = ways; return ways; } "
                + "private boolean isValidPair(String s, int index) { char tens = s.charAt(index); "
                + "char ones = s.charAt(index + 1); return tens == '1' || (tens == '2' && ones <= '6'); } }";
        return """
                    {
                      "name": "Top-Down Memoized Suffix Recursion Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nRecursively solve each suffix and memoize its answer.\\n\\n## Key Insight\\n\\nThe natural decision tree becomes linear after caching suffix indices.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String decodeWaysDagPathSolutionEntryJson() {
        String code = "import java.util.ArrayList; import java.util.List; class Solution { public int numDecodings(String s) { "
                + "int n = s.length(); List<List<Integer>> edges = new ArrayList<>(); "
                + "for (int i = 0; i <= n; i++) { edges.add(new ArrayList<>()); } "
                + "for (int position = 0; position < n; position++) { if (s.charAt(position) == '0') { continue; } "
                + "edges.get(position).add(position + 1); if (position + 1 < n && isValidPair(s, position)) { "
                + "edges.get(position).add(position + 2); } } int[] ways = new int[n + 1]; ways[0] = 1; "
                + "for (int position = 0; position < n; position++) { for (int next : edges.get(position)) { "
                + "ways[next] += ways[position]; } } return ways[n]; } "
                + "private boolean isValidPair(String s, int index) { char tens = s.charAt(index); "
                + "char ones = s.charAt(index + 1); return tens == '1' || (tens == '2' && ones <= '6'); } }";
        return """
                    {
                      "name": "DAG Path Counting Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nBuild edges between digit positions and count paths through the DAG.\\n\\n## Key Insight\\n\\nEvery valid decoding is exactly one path from position 0 to n.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

