    private static String coinChangeOneDimensionalDpSolutionEntryJson() {
        String code = "import java.util.Arrays; class Solution { public int coinChange(int[] coins, int amount) { "
                + "int unreachable = amount + 1; int[] dp = new int[amount + 1]; Arrays.fill(dp, unreachable); "
                + "dp[0] = 0; for (int value = 1; value <= amount; value++) { for (int coin : coins) { "
                + "if (coin <= value && dp[value - coin] != unreachable) { "
                + "dp[value] = Math.min(dp[value], dp[value - coin] + 1); } } } "
                + "return dp[amount] == unreachable ? -1 : dp[amount]; } }";
        return """
                    {
                      "name": "One-Dimensional Bottom-Up DP Fixture",
                      "timeComplexity": "O(amount * n)",
                      "spaceComplexity": "O(amount)",
                      "description": "## Approach\\n\\nFill a one-dimensional amount table.\\n\\n## Key Insight\\n\\nThe last coin leaves an optimal smaller amount.\\n\\n## Complexity Analysis\\n- Time Complexity: O(amount * n)\\n- Space Complexity: O(amount)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String coinChangeCompleteKnapsackSolutionEntryJson() {
        String code = "import java.util.Arrays; class Solution { public int coinChange(int[] coins, int amount) { "
                + "int n = coins.length; int unreachable = amount + 1; int[][] dp = new int[n + 1][amount + 1]; "
                + "Arrays.fill(dp[0], unreachable); dp[0][0] = 0; for (int i = 1; i <= n; i++) { dp[i][0] = 0; "
                + "int coin = coins[i - 1]; for (int value = 1; value <= amount; value++) { "
                + "dp[i][value] = dp[i - 1][value]; if (coin <= value && dp[i][value - coin] != unreachable) { "
                + "dp[i][value] = Math.min(dp[i][value], dp[i][value - coin] + 1); } } } "
                + "return dp[n][amount] == unreachable ? -1 : dp[n][amount]; } }";
        return """
                    {
                      "name": "Two-Dimensional Complete Knapsack Table Fixture",
                      "timeComplexity": "O(amount * n)",
                      "spaceComplexity": "O(amount * n)",
                      "description": "## Approach\\n\\nUse a full complete-knapsack table over denominations and amounts.\\n\\n## Key Insight\\n\\nTaking a coin stays on the same row because that denomination remains reusable.\\n\\n## Complexity Analysis\\n- Time Complexity: O(amount * n)\\n- Space Complexity: O(amount * n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String coinChangeMemoizedAmountSolutionEntryJson() {
        String code = "import java.util.Arrays; class Solution { private static final int INF = 1000000; "
                + "public int coinChange(int[] coins, int amount) { int[] memo = new int[amount + 1]; "
                + "Arrays.fill(memo, -2); int answer = fewest(coins, amount, memo); return answer >= INF ? -1 : answer; } "
                + "private int fewest(int[] coins, int remaining, int[] memo) { if (remaining == 0) { return 0; } "
                + "if (remaining < 0) { return INF; } if (memo[remaining] != -2) { return memo[remaining]; } "
                + "int best = INF; for (int coin : coins) { best = Math.min(best, fewest(coins, remaining - coin, memo) + 1); } "
                + "memo[remaining] = best; return best; } }";
        return """
                    {
                      "name": "Top-Down Memoized Remaining Amount Fixture",
                      "timeComplexity": "O(amount * n)",
                      "spaceComplexity": "O(amount)",
                      "description": "## Approach\\n\\nRecursively solve remaining amounts and memoize them.\\n\\n## Key Insight\\n\\nThe decision tree has only amount plus one non-negative subproblems after caching.\\n\\n## Complexity Analysis\\n- Time Complexity: O(amount * n)\\n- Space Complexity: O(amount)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String coinChangeBfsSolutionEntryJson() {
        String code = "import java.util.ArrayDeque; import java.util.Queue; class Solution { "
                + "public int coinChange(int[] coins, int amount) { boolean[] visited = new boolean[amount + 1]; "
                + "Queue<Integer> queue = new ArrayDeque<>(); queue.add(0); visited[0] = true; int coinsUsed = 0; "
                + "while (!queue.isEmpty()) { int size = queue.size(); for (int i = 0; i < size; i++) { "
                + "int current = queue.poll(); if (current == amount) { return coinsUsed; } "
                + "for (int coin : coins) { int next = current + coin; if (next <= amount && !visited[next]) { "
                + "visited[next] = true; queue.add(next); } } } coinsUsed++; } return -1; } }";
        return """
                    {
                      "name": "BFS Shortest Path Over Amounts Fixture",
                      "timeComplexity": "O(amount * n)",
                      "spaceComplexity": "O(amount)",
                      "description": "## Approach\\n\\nRun BFS over reachable amounts from zero.\\n\\n## Key Insight\\n\\nEach edge adds exactly one coin, so BFS layers are coin counts.\\n\\n## Complexity Analysis\\n- Time Complexity: O(amount * n)\\n- Space Complexity: O(amount)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String coinChangeBranchAndBoundSolutionEntryJson() {
        String code = "import java.util.Arrays; class Solution { private int best; "
                + "public int coinChange(int[] coins, int amount) { if (amount == 0) { return 0; } "
                + "Arrays.sort(coins); best = amount + 1; search(coins, coins.length - 1, amount, 0); "
                + "return best == amount + 1 ? -1 : best; } "
                + "private void search(int[] coins, int index, int remaining, int used) { if (remaining == 0) { "
                + "best = Math.min(best, used); return; } if (index < 0) { return; } int coin = coins[index]; "
                + "int maxCount = remaining / coin; for (int count = maxCount; count >= 0; count--) { "
                + "int nextUsed = used + count; if (nextUsed >= best) { continue; } "
                + "int nextRemaining = remaining - count * coin; if (nextRemaining == 0) { best = nextUsed; return; } "
                + "search(coins, index - 1, nextRemaining, nextUsed); } } }";
        return """
                    {
                      "name": "Sorted Branch-and-Bound DFS Fixture",
                      "timeComplexity": "O((amount / minCoin)^n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nSearch coin counts from larger denominations to smaller denominations with pruning.\\n\\n## Key Insight\\n\\nLarge coins are a heuristic, not a correctness proof, so the DFS must still backtrack.\\n\\n## Complexity Analysis\\n- Time Complexity: O((amount / minCoin)^n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

