    private static String maximumProductSubarrayRollingStateSolutionEntryJson() {
        String code = "class Solution { public int maxProduct(int[] nums) { int maxEnding = nums[0]; "
                + "int minEnding = nums[0]; int best = nums[0]; for (int index = 1; index < nums.length; index++) { "
                + "int value = nums[index]; if (value < 0) { int temp = maxEnding; maxEnding = minEnding; minEnding = temp; } "
                + "maxEnding = Math.max(value, maxEnding * value); minEnding = Math.min(value, minEnding * value); "
                + "best = Math.max(best, maxEnding); } return best; } }";
        return """
                    {
                      "name": "Rolling Max-Min Product State Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nTrack maximum and minimum products ending at each position.\\n\\n## Key Insight\\n\\nA negative value can swap the usefulness of the current maximum and minimum.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String maximumProductSubarrayDpArraysSolutionEntryJson() {
        String code = "class Solution { public int maxProduct(int[] nums) { int n = nums.length; "
                + "int[] maxEnding = new int[n]; int[] minEnding = new int[n]; maxEnding[0] = nums[0]; "
                + "minEnding[0] = nums[0]; int best = nums[0]; for (int index = 1; index < n; index++) { "
                + "int value = nums[index]; int candidateWithMax = maxEnding[index - 1] * value; "
                + "int candidateWithMin = minEnding[index - 1] * value; "
                + "maxEnding[index] = Math.max(value, Math.max(candidateWithMax, candidateWithMin)); "
                + "minEnding[index] = Math.min(value, Math.min(candidateWithMax, candidateWithMin)); "
                + "best = Math.max(best, maxEnding[index]); } return best; } }";
        return """
                    {
                      "name": "DP Arrays for Ending Products Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nStore maximum and minimum ending products in explicit arrays.\\n\\n## Key Insight\\n\\nThe full table shows why both signs must be kept before compressing space.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String maximumProductSubarrayPrefixSuffixSolutionEntryJson() {
        String code = "class Solution { public int maxProduct(int[] nums) { int n = nums.length; int best = nums[0]; "
                + "int prefix = 1; int suffix = 1; for (int index = 0; index < n; index++) { if (prefix == 0) { prefix = 1; } "
                + "if (suffix == 0) { suffix = 1; } prefix *= nums[index]; suffix *= nums[n - 1 - index]; "
                + "best = Math.max(best, Math.max(prefix, suffix)); } return best; } }";
        return """
                    {
                      "name": "Prefix and Suffix Zero-Reset Scan Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nScan products from both ends and reset after zero.\\n\\n## Key Insight\\n\\nThe two scan directions cover dropping either boundary negative in a zero-free segment.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String maximumProductSubarrayZeroSplitSolutionEntryJson() {
        String code = "class Solution { public int maxProduct(int[] nums) { int n = nums.length; int best = nums[0]; "
                + "int start = 0; while (start < n) { if (nums[start] == 0) { best = Math.max(best, 0); start++; continue; } "
                + "int end = start; long total = 1; int negativeCount = 0; int firstNegative = -1; int lastNegative = -1; "
                + "while (end < n && nums[end] != 0) { total *= nums[end]; best = Math.max(best, nums[end]); "
                + "if (nums[end] < 0) { negativeCount++; if (firstNegative == -1) { firstNegative = end; } lastNegative = end; } end++; } "
                + "if (negativeCount % 2 == 0) { best = Math.max(best, (int) total); } else { long dropPrefix = 1; "
                + "for (int i = firstNegative + 1; i < end; i++) { dropPrefix *= nums[i]; } "
                + "if (firstNegative + 1 < end) { best = Math.max(best, (int) dropPrefix); } long dropSuffix = 1; "
                + "for (int i = start; i < lastNegative; i++) { dropSuffix *= nums[i]; } "
                + "if (start < lastNegative) { best = Math.max(best, (int) dropSuffix); } } start = end; } return best; } }";
        return """
                    {
                      "name": "Zero-Split Negative Boundary Analysis Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nSplit on zero and analyze first and last negative boundaries inside each segment.\\n\\n## Key Insight\\n\\nOdd negative segments become positive only after dropping one negative boundary side.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String maximumProductSubarrayBruteForceSolutionEntryJson() {
        String code = "class Solution { public int maxProduct(int[] nums) { int best = nums[0]; "
                + "for (int start = 0; start < nums.length; start++) { int product = 1; "
                + "for (int end = start; end < nums.length; end++) { product *= nums[end]; "
                + "best = Math.max(best, product); } } return best; } }";
        return """
                    {
                      "name": "Brute Force Rolling Product Baseline Fixture",
                      "timeComplexity": "O(n^2)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nEnumerate every contiguous start-end range with a rolling product.\\n\\n## Key Insight\\n\\nThe baseline proves the exact problem definition before optimized routes are introduced.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

