    private static String wordBreakBottomUpCutDpSolutionEntryJson() {
        String code = "import java.util.HashSet; import java.util.List; import java.util.Set; "
                + "class Solution { public boolean wordBreak(String s, List<String> wordDict) { "
                + "Set<String> words = new HashSet<>(wordDict); int n = s.length(); int maxWordLength = 0; "
                + "for (String word : wordDict) { maxWordLength = Math.max(maxWordLength, word.length()); } "
                + "boolean[] dp = new boolean[n + 1]; dp[0] = true; for (int end = 1; end <= n; end++) { "
                + "for (int start = Math.max(0, end - maxWordLength); start < end; start++) { "
                + "if (dp[start] && words.contains(s.substring(start, end))) { dp[end] = true; break; } } } "
                + "return dp[n]; } }";
        return """
                    {
                      "name": "Bottom-Up Cut DP Fixture",
                      "timeComplexity": "O(n * L^2)",
                      "spaceComplexity": "O(n + W)",
                      "description": "## Approach\\n\\nFill reachable prefix ends from left to right.\\n\\n## Key Insight\\n\\nA new cut is valid only when the previous cut is reachable and the last block is a dictionary word.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * L^2)\\n- Space Complexity: O(n + W)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String wordBreakForwardReachabilitySolutionEntryJson() {
        String code = "import java.util.List; class Solution { public boolean wordBreak(String s, List<String> wordDict) { "
                + "int n = s.length(); boolean[] reachable = new boolean[n + 1]; reachable[0] = true; "
                + "for (int start = 0; start <= n; start++) { if (!reachable[start]) { continue; } "
                + "for (String word : wordDict) { int end = start + word.length(); "
                + "if (end <= n && s.startsWith(word, start)) { reachable[end] = true; } } "
                + "if (reachable[n]) { return true; } } return reachable[n]; } }";
        return """
                    {
                      "name": "Forward Reachability by Words Fixture",
                      "timeComplexity": "O(n * W * L)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nExtend each reachable cut by trying dictionary words.\\n\\n## Key Insight\\n\\nUnreachable cuts never need to expand, and words can be reused from any reachable cut.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * W * L)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String wordBreakTopDownMemoSolutionEntryJson() {
        String code = "import java.util.HashSet; import java.util.List; import java.util.Set; "
                + "class Solution { public boolean wordBreak(String s, List<String> wordDict) { "
                + "Set<String> words = new HashSet<>(wordDict); Boolean[] memo = new Boolean[s.length()]; "
                + "return canBreak(s, 0, words, memo); } "
                + "private boolean canBreak(String s, int index, Set<String> words, Boolean[] memo) { "
                + "if (index == s.length()) { return true; } if (memo[index] != null) { return memo[index]; } "
                + "for (int end = index + 1; end <= s.length(); end++) { "
                + "if (words.contains(s.substring(index, end)) && canBreak(s, end, words, memo)) { "
                + "memo[index] = true; return true; } } memo[index] = false; return false; } }";
        return """
                    {
                      "name": "Top-Down Memoized DFS Fixture",
                      "timeComplexity": "O(n^2 * L)",
                      "spaceComplexity": "O(n + W)",
                      "description": "## Approach\\n\\nRecursively choose the next dictionary word and memoize each suffix start.\\n\\n## Key Insight\\n\\nDifferent prefix choices can lead to the same suffix, so caching suffix starts is essential.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2 * L)\\n- Space Complexity: O(n + W)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String wordBreakBfsSolutionEntryJson() {
        String code = "import java.util.ArrayDeque; import java.util.HashSet; import java.util.List; "
                + "import java.util.Queue; import java.util.Set; class Solution { "
                + "public boolean wordBreak(String s, List<String> wordDict) { Set<String> words = new HashSet<>(wordDict); "
                + "int n = s.length(); boolean[] visited = new boolean[n + 1]; Queue<Integer> queue = new ArrayDeque<>(); "
                + "queue.add(0); visited[0] = true; while (!queue.isEmpty()) { int start = queue.poll(); "
                + "for (int end = start + 1; end <= n; end++) { if (!visited[end] && words.contains(s.substring(start, end))) { "
                + "if (end == n) { return true; } visited[end] = true; queue.add(end); } } } return false; } }";
        return """
                    {
                      "name": "BFS Over Cut Positions Fixture",
                      "timeComplexity": "O(n^3)",
                      "spaceComplexity": "O(n + W)",
                      "description": "## Approach\\n\\nRun BFS over reachable cut indices.\\n\\n## Key Insight\\n\\nThe problem is graph reachability, and visited cuts prevent repeated suffix exploration.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^3)\\n- Space Complexity: O(n + W)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String wordBreakTrieSolutionEntryJson() {
        String code = "import java.util.List; class Solution { public boolean wordBreak(String s, List<String> wordDict) { "
                + "TrieNode root = new TrieNode(); for (String word : wordDict) { insert(root, word); } "
                + "boolean[] reachable = new boolean[s.length() + 1]; reachable[0] = true; "
                + "for (int start = 0; start < s.length(); start++) { if (!reachable[start]) { continue; } "
                + "TrieNode node = root; for (int end = start; end < s.length(); end++) { int idx = s.charAt(end) - 'a'; "
                + "if (node.children[idx] == null) { break; } node = node.children[idx]; "
                + "if (node.word) { reachable[end + 1] = true; } } } return reachable[s.length()]; } "
                + "private void insert(TrieNode root, String word) { TrieNode node = root; for (char ch : word.toCharArray()) { "
                + "int idx = ch - 'a'; if (node.children[idx] == null) { node.children[idx] = new TrieNode(); } "
                + "node = node.children[idx]; } node.word = true; } "
                + "static class TrieNode { TrieNode[] children = new TrieNode[26]; boolean word; } }";
        return """
                    {
                      "name": "Trie-Accelerated Prefix DP Fixture",
                      "timeComplexity": "O(n * L)",
                      "spaceComplexity": "O(n + T)",
                      "description": "## Approach\\n\\nWalk a trie from each reachable start and mark word-ending cuts.\\n\\n## Key Insight\\n\\nThe trie stops immediately when no dictionary word shares the current prefix.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * L)\\n- Space Complexity: O(n + T)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

