    private static String longestIncreasingSubsequenceQuadraticDpSolutionEntryJson() {
        String code = "class Solution { public int lengthOfLIS(int[] nums) { int n = nums.length; "
                + "int[] dp = new int[n]; java.util.Arrays.fill(dp, 1); int best = 1; "
                + "for (int i = 0; i < n; i++) { for (int j = 0; j < i; j++) { "
                + "if (nums[j] < nums[i]) { dp[i] = Math.max(dp[i], dp[j] + 1); } } "
                + "best = Math.max(best, dp[i]); } return best; } }";
        return """
                    {
                      "name": "Quadratic DP Ending at Each Index Fixture",
                      "timeComplexity": "O(n^2)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nStore the best length for subsequences ending at each index.\\n\\n## Key Insight\\n\\nThe answer is the best ending position, and every earlier smaller value can extend into the current value.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String longestIncreasingSubsequencePatienceTailsSolutionEntryJson() {
        String code = "class Solution { public int lengthOfLIS(int[] nums) { int[] tails = new int[nums.length]; "
                + "int size = 0; for (int num : nums) { int lo = 0; int hi = size; while (lo < hi) { "
                + "int mid = lo + (hi - lo) / 2; if (tails[mid] < num) { lo = mid + 1; } else { hi = mid; } } "
                + "tails[lo] = num; if (lo == size) { size++; } } return size; } }";
        return """
                    {
                      "name": "Patience Sorting Tails Fixture",
                      "timeComplexity": "O(n log n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nMaintain minimal tail values for every subsequence length and update them by binary search.\\n\\n## Key Insight\\n\\nReplacing the first tail greater than or equal to the current value preserves strictness and future options.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String longestIncreasingSubsequenceTopDownMemoSolutionEntryJson() {
        String code = "class Solution { public int lengthOfLIS(int[] nums) { "
                + "int[][] memo = new int[nums.length][nums.length + 1]; return dfs(nums, 0, -1, memo); } "
                + "private int dfs(int[] nums, int index, int previous, int[][] memo) { if (index == nums.length) { return 0; } "
                + "int memoColumn = previous + 1; if (memo[index][memoColumn] != 0) { return memo[index][memoColumn]; } "
                + "int skip = dfs(nums, index + 1, previous, memo); int take = 0; "
                + "if (previous == -1 || nums[previous] < nums[index]) { take = 1 + dfs(nums, index + 1, index, memo); } "
                + "memo[index][memoColumn] = Math.max(take, skip); return memo[index][memoColumn]; } }";
        return """
                    {
                      "name": "Top-Down Include-or-Skip Memoization Fixture",
                      "timeComplexity": "O(n^2)",
                      "spaceComplexity": "O(n^2)",
                      "description": "## Approach\\n\\nRecursively choose or skip each index while remembering the previous chosen index.\\n\\n## Key Insight\\n\\nMemoization turns repeated suffix decisions into states keyed by current index and previous index.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2)\\n- Space Complexity: O(n^2)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String longestIncreasingSubsequenceFenwickSolutionEntryJson() {
        String code = "class Solution { public int lengthOfLIS(int[] nums) { int[] values = nums.clone(); "
                + "java.util.Arrays.sort(values); int size = 0; for (int value : values) { "
                + "if (size == 0 || values[size - 1] != value) { values[size++] = value; } } "
                + "Fenwick tree = new Fenwick(size); int best = 0; for (int num : nums) { "
                + "int rank = lowerBound(values, size, num) + 1; int length = tree.query(rank - 1) + 1; "
                + "tree.update(rank, length); best = Math.max(best, length); } return best; } "
                + "private int lowerBound(int[] values, int size, int target) { int lo = 0; int hi = size; "
                + "while (lo < hi) { int mid = lo + (hi - lo) / 2; if (values[mid] < target) { lo = mid + 1; } else { hi = mid; } } return lo; } "
                + "private static class Fenwick { private final int[] tree; Fenwick(int size) { this.tree = new int[size + 1]; } "
                + "void update(int index, int value) { while (index < tree.length) { tree[index] = Math.max(tree[index], value); index += index & -index; } } "
                + "int query(int index) { int best = 0; while (index > 0) { best = Math.max(best, tree[index]); index -= index & -index; } return best; } } }";
        return """
                    {
                      "name": "Fenwick Tree with Coordinate Compression Fixture",
                      "timeComplexity": "O(n log n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nCompress values and use a Fenwick tree for prefix maximum LIS lengths.\\n\\n## Key Insight\\n\\nStrict increasing queries only ranks below the current rank, and the tree stores maximum values.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String longestIncreasingSubsequenceSegmentTreeSolutionEntryJson() {
        String code = "class Solution { public int lengthOfLIS(int[] nums) { int[] values = nums.clone(); "
                + "java.util.Arrays.sort(values); int unique = 0; for (int value : values) { "
                + "if (unique == 0 || values[unique - 1] != value) { values[unique++] = value; } } "
                + "SegmentTree tree = new SegmentTree(unique); int best = 0; for (int num : nums) { "
                + "int rank = lowerBound(values, unique, num); int length = tree.query(0, rank - 1) + 1; "
                + "tree.update(rank, length); best = Math.max(best, length); } return best; } "
                + "private int lowerBound(int[] values, int size, int target) { int lo = 0; int hi = size; "
                + "while (lo < hi) { int mid = lo + (hi - lo) / 2; if (values[mid] < target) { lo = mid + 1; } else { hi = mid; } } return lo; } "
                + "private static class SegmentTree { private final int size; private final int[] tree; SegmentTree(int count) { "
                + "int capacity = 1; while (capacity < count) { capacity <<= 1; } this.size = capacity; this.tree = new int[size * 2]; } "
                + "void update(int index, int value) { int position = index + size; tree[position] = Math.max(tree[position], value); "
                + "position >>= 1; while (position > 0) { tree[position] = Math.max(tree[position << 1], tree[position << 1 | 1]); position >>= 1; } } "
                + "int query(int left, int right) { if (right < left) { return 0; } left += size; right += size; int best = 0; "
                + "while (left <= right) { if ((left & 1) == 1) { best = Math.max(best, tree[left++]); } "
                + "if ((right & 1) == 0) { best = Math.max(best, tree[right--]); } left >>= 1; right >>= 1; } return best; } } }";
        return """
                    {
                      "name": "Segment Tree Range-Max DP Fixture",
                      "timeComplexity": "O(n log n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nCompress values and query a segment tree for the best smaller ending value.\\n\\n## Key Insight\\n\\nLIS by value order is a range maximum DP over all ranks strictly below the current rank.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

