    private static String partitionEqualSubsetSumOneDimensionalSolutionEntryJson() {
        String code = "class Solution { public boolean canPartition(int[] nums) { int total = 0; "
                + "for (int num : nums) { total += num; } if ((total & 1) == 1) { return false; } "
                + "int target = total / 2; boolean[] dp = new boolean[target + 1]; dp[0] = true; "
                + "for (int num : nums) { for (int sum = target; sum >= num; sum--) { "
                + "dp[sum] = dp[sum] || dp[sum - num]; } if (dp[target]) { return true; } } "
                + "return dp[target]; } }";
        return """
                    {
                      "name": "One-Dimensional 0/1 Knapsack DP Fixture",
                      "timeComplexity": "O(n * target)",
                      "spaceComplexity": "O(target)",
                      "description": "## Approach\\n\\nUse a one-dimensional reachable-sum table and update it backward for every number.\\n\\n## Key Insight\\n\\nBackward scanning is what prevents one array element from being reused in the same iteration.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * target)\\n- Space Complexity: O(target)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String partitionEqualSubsetSumTwoDimensionalSolutionEntryJson() {
        String code = "class Solution { public boolean canPartition(int[] nums) { int total = 0; "
                + "for (int num : nums) { total += num; } if (total % 2 != 0) { return false; } "
                + "int target = total / 2; boolean[][] dp = new boolean[nums.length + 1][target + 1]; "
                + "dp[0][0] = true; for (int index = 1; index <= nums.length; index++) { int num = nums[index - 1]; "
                + "for (int sum = 0; sum <= target; sum++) { boolean skip = dp[index - 1][sum]; "
                + "boolean take = sum >= num && dp[index - 1][sum - num]; dp[index][sum] = skip || take; } } "
                + "return dp[nums.length][target]; } }";
        return """
                    {
                      "name": "Two-Dimensional DP Table Fixture",
                      "timeComplexity": "O(n * target)",
                      "spaceComplexity": "O(n * target)",
                      "description": "## Approach\\n\\nFill a prefix-by-sum table where each row decides whether to take or skip the current number.\\n\\n## Key Insight\\n\\nThe full table makes the 0/1 recurrence visible before space compression.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * target)\\n- Space Complexity: O(n * target)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String partitionEqualSubsetSumTopDownMemoSolutionEntryJson() {
        String code = "class Solution { public boolean canPartition(int[] nums) { int total = 0; "
                + "for (int num : nums) { total += num; } if ((total & 1) == 1) { return false; } "
                + "int target = total / 2; Boolean[][] memo = new Boolean[nums.length][target + 1]; "
                + "return canFill(nums, 0, target, memo); } "
                + "private boolean canFill(int[] nums, int index, int remaining, Boolean[][] memo) { "
                + "if (remaining == 0) { return true; } if (index == nums.length || remaining < 0) { return false; } "
                + "if (memo[index][remaining] != null) { return memo[index][remaining]; } "
                + "boolean skip = canFill(nums, index + 1, remaining, memo); "
                + "boolean take = canFill(nums, index + 1, remaining - nums[index], memo); "
                + "memo[index][remaining] = skip || take; return memo[index][remaining]; } }";
        return """
                    {
                      "name": "Top-Down Target Memoization Fixture",
                      "timeComplexity": "O(n * target)",
                      "spaceComplexity": "O(n * target)",
                      "description": "## Approach\\n\\nRecursively choose or skip each number while memoizing the current index and remaining target.\\n\\n## Key Insight\\n\\nThe same remaining target can be reached through many prefixes, so each suffix decision must be cached.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * target)\\n- Space Complexity: O(n * target)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String partitionEqualSubsetSumBitsetShiftSolutionEntryJson() {
        String code = "class Solution { public boolean canPartition(int[] nums) { int total = 0; "
                + "for (int num : nums) { total += num; } if (total % 2 != 0) { return false; } "
                + "int target = total / 2; java.math.BigInteger reachable = java.math.BigInteger.ONE; "
                + "for (int num : nums) { reachable = reachable.or(reachable.shiftLeft(num)); "
                + "if (reachable.testBit(target)) { return true; } } return reachable.testBit(target); } }";
        return """
                    {
                      "name": "BigInteger Bitset Shift DP Fixture",
                      "timeComplexity": "O(n * target / wordSize)",
                      "spaceComplexity": "O(target)",
                      "description": "## Approach\\n\\nRepresent reachable sums as bits and shift the whole bitset for each number.\\n\\n## Key Insight\\n\\nA left shift applies the subset-sum transition to all reachable sums at once.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * target / wordSize)\\n- Space Complexity: O(target)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String partitionEqualSubsetSumReachableSumsSetSolutionEntryJson() {
        String code = "class Solution { public boolean canPartition(int[] nums) { int total = 0; "
                + "for (int num : nums) { total += num; } if ((total & 1) == 1) { return false; } "
                + "int target = total / 2; java.util.Set<Integer> reachable = new java.util.HashSet<>(); "
                + "reachable.add(0); for (int num : nums) { java.util.Set<Integer> next = new java.util.HashSet<>(reachable); "
                + "for (int sum : reachable) { int candidate = sum + num; if (candidate == target) { return true; } "
                + "if (candidate < target) { next.add(candidate); } } reachable = next; } return reachable.contains(target); } }";
        return """
                    {
                      "name": "Reachable Sums Set Expansion Fixture",
                      "timeComplexity": "O(n * target)",
                      "spaceComplexity": "O(target)",
                      "description": "## Approach\\n\\nExpand the set of reachable sums after each number and cap states at the half target.\\n\\n## Key Insight\\n\\nDifferent subsets that make the same sum collapse into one state, bridging brute force and DP.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * target)\\n- Space Complexity: O(target)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

