    private static String uniquePathsTwoDimensionalSolutionEntryJson() {
        String code = "class Solution { public int uniquePaths(int m, int n) { int[][] dp = new int[m][n]; "
                + "for (int row = 0; row < m; row++) { dp[row][0] = 1; } "
                + "for (int col = 0; col < n; col++) { dp[0][col] = 1; } "
                + "for (int row = 1; row < m; row++) { for (int col = 1; col < n; col++) { "
                + "dp[row][col] = dp[row - 1][col] + dp[row][col - 1]; } } "
                + "return dp[m - 1][n - 1]; } }";
        return """
                    {
                      "name": "Two-Dimensional Grid DP Fixture",
                      "timeComplexity": "O(m * n)",
                      "spaceComplexity": "O(m * n)",
                      "description": "## Approach\\n\\nFill a full grid table from the top row and left column.\\n\\n## Key Insight\\n\\nEvery interior cell depends only on paths from above and from the left.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n)\\n- Space Complexity: O(m * n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String uniquePathsOneRowRollingSolutionEntryJson() {
        String code = "class Solution { public int uniquePaths(int m, int n) { int[] dp = new int[n]; "
                + "java.util.Arrays.fill(dp, 1); for (int row = 1; row < m; row++) { "
                + "for (int col = 1; col < n; col++) { dp[col] += dp[col - 1]; } } return dp[n - 1]; } }";
        return """
                    {
                      "name": "One-Row Rolling DP Fixture",
                      "timeComplexity": "O(m * n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nCompress the grid recurrence into one row.\\n\\n## Key Insight\\n\\nThe current cell only needs the old value from above and the updated value from the left.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String uniquePathsTopDownMemoSolutionEntryJson() {
        String code = "class Solution { public int uniquePaths(int m, int n) { int[][] memo = new int[m][n]; "
                + "return paths(0, 0, m, n, memo); } "
                + "private int paths(int row, int col, int m, int n, int[][] memo) { "
                + "if (row == m - 1 || col == n - 1) { return 1; } "
                + "if (memo[row][col] != 0) { return memo[row][col]; } "
                + "memo[row][col] = paths(row + 1, col, m, n, memo) + paths(row, col + 1, m, n, memo); "
                + "return memo[row][col]; } }";
        return """
                    {
                      "name": "Top-Down Memoized Grid Walk Fixture",
                      "timeComplexity": "O(m * n)",
                      "spaceComplexity": "O(m * n)",
                      "description": "## Approach\\n\\nCount paths from each cell to the destination and memoize the grid suffix.\\n\\n## Key Insight\\n\\nLast-row and last-column states have one straight remaining path.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n)\\n- Space Complexity: O(m * n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String uniquePathsCombinatoricsSolutionEntryJson() {
        String code = "class Solution { public int uniquePaths(int m, int n) { int down = m - 1; int right = n - 1; "
                + "int choose = Math.min(down, right); int totalMoves = down + right; long result = 1; "
                + "for (int step = 1; step <= choose; step++) { result = result * (totalMoves - choose + step) / step; } "
                + "return (int) result; } }";
        return """
                    {
                      "name": "Multiplicative Combinatorics Fixture",
                      "timeComplexity": "O(min(m, n))",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nChoose positions for the smaller move group among all right and down moves.\\n\\n## Key Insight\\n\\nA path is a permutation of fixed right and down moves, so the count is a binomial coefficient.\\n\\n## Complexity Analysis\\n- Time Complexity: O(min(m, n))\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String uniquePathsDagPropagationSolutionEntryJson() {
        String code = "class Solution { public int uniquePaths(int m, int n) { int[][] ways = new int[m][n]; "
                + "ways[0][0] = 1; for (int row = 0; row < m; row++) { for (int col = 0; col < n; col++) { "
                + "if (row + 1 < m) { ways[row + 1][col] += ways[row][col]; } "
                + "if (col + 1 < n) { ways[row][col + 1] += ways[row][col]; } } } "
                + "return ways[m - 1][n - 1]; } }";
        return """
                    {
                      "name": "DAG Path Count Propagation Fixture",
                      "timeComplexity": "O(m * n)",
                      "spaceComplexity": "O(m * n)",
                      "description": "## Approach\\n\\nPush each cell's path count to its right and down neighbors in DAG order.\\n\\n## Key Insight\\n\\nThe grid is a directed acyclic graph, so path counts can be propagated forward along edges.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n)\\n- Space Complexity: O(m * n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

