    private static String longestCommonSubsequencePrefixTableSolutionEntryJson() {
        String code = "class Solution { public int longestCommonSubsequence(String text1, String text2) { "
                + "int m = text1.length(); int n = text2.length(); int[][] dp = new int[m + 1][n + 1]; "
                + "for (int i = 1; i <= m; i++) { for (int j = 1; j <= n; j++) { "
                + "if (text1.charAt(i - 1) == text2.charAt(j - 1)) { dp[i][j] = dp[i - 1][j - 1] + 1; } "
                + "else { dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]); } } } return dp[m][n]; } }";
        return """
                    {
                      "name": "Prefix Table DP Fixture",
                      "timeComplexity": "O(m * n)",
                      "spaceComplexity": "O(m * n)",
                      "description": "## Approach\\n\\nFill a prefix table for both strings and extend matching diagonals.\\n\\n## Key Insight\\n\\nThe LCS recurrence is defined by how many characters of each string have already been considered.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n)\\n- Space Complexity: O(m * n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String longestCommonSubsequenceOneRowRollingSolutionEntryJson() {
        String code = "class Solution { public int longestCommonSubsequence(String text1, String text2) { "
                + "int m = text1.length(); int n = text2.length(); int[] dp = new int[n + 1]; "
                + "for (int i = 1; i <= m; i++) { int previousDiagonal = 0; for (int j = 1; j <= n; j++) { "
                + "int oldAbove = dp[j]; if (text1.charAt(i - 1) == text2.charAt(j - 1)) { "
                + "dp[j] = previousDiagonal + 1; } else { dp[j] = Math.max(dp[j], dp[j - 1]); } "
                + "previousDiagonal = oldAbove; } } return dp[n]; } }";
        return """
                    {
                      "name": "One-Row Rolling DP Fixture",
                      "timeComplexity": "O(m * n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nCompress the prefix table into one row while carrying the old diagonal.\\n\\n## Key Insight\\n\\nEach state needs above, left, and diagonal values; one scalar preserves the diagonal before overwrite.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String longestCommonSubsequenceTopDownMemoSolutionEntryJson() {
        String code = "class Solution { public int longestCommonSubsequence(String text1, String text2) { "
                + "int[][] memo = new int[text1.length()][text2.length()]; for (int[] row : memo) { java.util.Arrays.fill(row, -1); } "
                + "return lcs(text1, text2, 0, 0, memo); } "
                + "private int lcs(String text1, String text2, int i, int j, int[][] memo) { "
                + "if (i == text1.length() || j == text2.length()) { return 0; } "
                + "if (memo[i][j] != -1) { return memo[i][j]; } "
                + "if (text1.charAt(i) == text2.charAt(j)) { memo[i][j] = 1 + lcs(text1, text2, i + 1, j + 1, memo); } "
                + "else { memo[i][j] = Math.max(lcs(text1, text2, i + 1, j, memo), lcs(text1, text2, i, j + 1, memo)); } "
                + "return memo[i][j]; } }";
        return """
                    {
                      "name": "Top-Down Memoized Suffix DFS Fixture",
                      "timeComplexity": "O(m * n)",
                      "spaceComplexity": "O(m * n)",
                      "description": "## Approach\\n\\nRecursively solve suffix pairs and memoize each pair of indices.\\n\\n## Key Insight\\n\\nSkipping either current character creates repeated suffix states, so memoization is the core optimization.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n)\\n- Space Complexity: O(m * n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String longestCommonSubsequenceSuffixTableSolutionEntryJson() {
        String code = "class Solution { public int longestCommonSubsequence(String text1, String text2) { "
                + "int m = text1.length(); int n = text2.length(); int[][] dp = new int[m + 1][n + 1]; "
                + "for (int i = m - 1; i >= 0; i--) { for (int j = n - 1; j >= 0; j--) { "
                + "if (text1.charAt(i) == text2.charAt(j)) { dp[i][j] = 1 + dp[i + 1][j + 1]; } "
                + "else { dp[i][j] = Math.max(dp[i + 1][j], dp[i][j + 1]); } } } return dp[0][0]; } }";
        return """
                    {
                      "name": "Suffix Table DP Fixture",
                      "timeComplexity": "O(m * n)",
                      "spaceComplexity": "O(m * n)",
                      "description": "## Approach\\n\\nFill suffix states from the end of both strings toward the front.\\n\\n## Key Insight\\n\\nThis is the bottom-up form of suffix DFS, so `dp[0][0]` is known after shorter suffixes are filled.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n)\\n- Space Complexity: O(m * n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String longestCommonSubsequencePositionLisSolutionEntryJson() {
        String code = "class Solution { public int longestCommonSubsequence(String text1, String text2) { "
                + "java.util.List<Integer>[] positions = new java.util.ArrayList[26]; "
                + "for (int i = 0; i < 26; i++) { positions[i] = new java.util.ArrayList<>(); } "
                + "for (int index = 0; index < text2.length(); index++) { positions[text2.charAt(index) - 'a'].add(index); } "
                + "int[] tails = new int[Math.min(text1.length(), text2.length())]; int size = 0; "
                + "for (int index = 0; index < text1.length(); index++) { java.util.List<Integer> list = positions[text1.charAt(index) - 'a']; "
                + "for (int k = list.size() - 1; k >= 0; k--) { int position = list.get(k); int slot = lowerBound(tails, size, position); "
                + "tails[slot] = position; if (slot == size) { size++; } } } return size; } "
                + "private int lowerBound(int[] values, int size, int target) { int lo = 0; int hi = size; "
                + "while (lo < hi) { int mid = lo + (hi - lo) / 2; if (values[mid] < target) { lo = mid + 1; } else { hi = mid; } } return lo; } }";
        return """
                    {
                      "name": "Match Positions to LIS Fixture",
                      "timeComplexity": "O((m + k) log n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nConvert matching character positions in the second string into an increasing-position subsequence problem.\\n\\n## Key Insight\\n\\nA common subsequence keeps `text2` positions increasing while scanning `text1`; reverse position updates prevent reusing one character twice.\\n\\n## Complexity Analysis\\n- Time Complexity: O((m + k) log n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

