    private static String targetSumOneDimensionalSolutionEntryJson() {
        String code = "class Solution { public int findTargetSumWays(int[] nums, int target) { "
                + "int total = 0; for (int num : nums) { total += num; } "
                + "if (Math.abs(target) > total) { return 0; } int shifted = total + target; "
                + "if ((shifted & 1) != 0) { return 0; } int subsetTarget = shifted / 2; "
                + "int[] ways = new int[subsetTarget + 1]; ways[0] = 1; "
                + "for (int num : nums) { for (int sum = subsetTarget; sum >= num; sum--) { "
                + "ways[sum] += ways[sum - num]; } } return ways[subsetTarget]; } }";
        return """
                    {
                      "name": "One-Dimensional Subset Sum Transform Fixture",
                      "timeComplexity": "O(n * sum)",
                      "spaceComplexity": "O(sum)",
                      "description": "## Approach\\n\\nTransform signed assignments into counting subsets with sum (total + target) / 2.\\n\\n## Key Insight\\n\\nThe parity and reachability checks decide whether the subset target exists, and zero values double counts.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * sum)\\n- Space Complexity: O(sum)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String targetSumTwoDimensionalSolutionEntryJson() {
        String code = "class Solution { public int findTargetSumWays(int[] nums, int target) { "
                + "int total = 0; for (int num : nums) { total += num; } "
                + "if (Math.abs(target) > total) { return 0; } int shifted = total + target; "
                + "if ((shifted & 1) != 0) { return 0; } int subsetTarget = shifted / 2; int n = nums.length; "
                + "int[][] dp = new int[n + 1][subsetTarget + 1]; dp[0][0] = 1; "
                + "for (int i = 1; i <= n; i++) { int num = nums[i - 1]; "
                + "for (int sum = 0; sum <= subsetTarget; sum++) { dp[i][sum] = dp[i - 1][sum]; "
                + "if (sum >= num) { dp[i][sum] += dp[i - 1][sum - num]; } } } "
                + "return dp[n][subsetTarget]; } }";
        return """
                    {
                      "name": "Two-Dimensional Subset Count Table Fixture",
                      "timeComplexity": "O(n * sum)",
                      "spaceComplexity": "O(n * sum)",
                      "description": "## Approach\\n\\nKeep a full 0/1 subset-count table after transforming the signed equation.\\n\\n## Key Insight\\n\\nThe row transition makes the take-or-skip choice explicit and doubles correctly for zeros.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * sum)\\n- Space Complexity: O(n * sum)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String targetSumOffsetSignedSumSolutionEntryJson() {
        String code = "class Solution { public int findTargetSumWays(int[] nums, int target) { "
                + "int total = 0; for (int num : nums) { total += num; } if (Math.abs(target) > total) { return 0; } "
                + "int offset = total; int[] current = new int[2 * total + 1]; current[offset] = 1; "
                + "for (int num : nums) { int[] next = new int[2 * total + 1]; "
                + "for (int sum = -total; sum <= total; sum++) { int count = current[sum + offset]; "
                + "if (count == 0) { continue; } next[sum + num + offset] += count; "
                + "next[sum - num + offset] += count; } current = next; } return current[target + offset]; } }";
        return """
                    {
                      "name": "Offset Signed-Sum DP Fixture",
                      "timeComplexity": "O(n * sum)",
                      "spaceComplexity": "O(sum)",
                      "description": "## Approach\\n\\nTrack counts for every signed sum and use an offset so negative sums fit in arrays.\\n\\n## Key Insight\\n\\nThis directly models plus and minus choices without relying on the subset-sum transformation.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * sum)\\n- Space Complexity: O(sum)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String targetSumTopDownSignedSumSolutionEntryJson() {
        String code = "class Solution { public int findTargetSumWays(int[] nums, int target) { "
                + "java.util.Map<Long, Integer> memo = new java.util.HashMap<>(); return count(nums, 0, 0, target, memo); } "
                + "private int count(int[] nums, int index, int currentSum, int target, java.util.Map<Long, Integer> memo) { "
                + "if (index == nums.length) { return currentSum == target ? 1 : 0; } "
                + "long key = (((long) index) << 32) ^ ((long) currentSum & 0xffffffffL); Integer cached = memo.get(key); "
                + "if (cached != null) { return cached; } int plus = count(nums, index + 1, currentSum + nums[index], target, memo); "
                + "int minus = count(nums, index + 1, currentSum - nums[index], target, memo); int answer = plus + minus; "
                + "memo.put(key, answer); return answer; } }";
        return """
                    {
                      "name": "Top-Down Signed Sum Memoization Fixture",
                      "timeComplexity": "O(n * sum)",
                      "spaceComplexity": "O(n * sum)",
                      "description": "## Approach\\n\\nRecurse over index and signed sum, memoizing each reachable state.\\n\\n## Key Insight\\n\\nThe recursion mirrors expression construction while the memo table removes repeated subtrees.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n * sum)\\n- Space Complexity: O(n * sum)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

    private static String targetSumMeetInTheMiddleSolutionEntryJson() {
        String code = "class Solution { public int findTargetSumWays(int[] nums, int target) { "
                + "int middle = nums.length / 2; java.util.Map<Integer, Integer> leftCounts = new java.util.HashMap<>(); "
                + "java.util.Map<Integer, Integer> rightCounts = new java.util.HashMap<>(); collect(nums, 0, middle, 0, leftCounts); "
                + "collect(nums, middle, nums.length, 0, rightCounts); int answer = 0; "
                + "for (java.util.Map.Entry<Integer, Integer> entry : leftCounts.entrySet()) { int leftSum = entry.getKey(); "
                + "int leftWays = entry.getValue(); answer += leftWays * rightCounts.getOrDefault(target - leftSum, 0); } "
                + "return answer; } private void collect(int[] nums, int index, int end, int sum, java.util.Map<Integer, Integer> counts) { "
                + "if (index == end) { counts.put(sum, counts.getOrDefault(sum, 0) + 1); return; } "
                + "collect(nums, index + 1, end, sum + nums[index], counts); collect(nums, index + 1, end, sum - nums[index], counts); } }";
        return """
                    {
                      "name": "Meet-in-the-Middle Signed Sums Fixture",
                      "timeComplexity": "O(2^(n/2))",
                      "spaceComplexity": "O(2^(n/2))",
                      "description": "## Approach\\n\\nSplit the array, enumerate signed sums per half, and join complementary sums.\\n\\n## Key Insight\\n\\nCounts must be stored because repeated values and zeros can produce the same sum in many ways.\\n\\n## Complexity Analysis\\n- Time Complexity: O(2^(n/2))\\n- Space Complexity: O(2^(n/2))",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code)).stripTrailing();
    }

