    private static String longestIncreasingPathMatrixExplicitStackSolutionEntryJson() {
        String code = """
                class Solution {
                    public int longestIncreasingPath(int[][] matrix) {
                        int m = matrix.length;
                        int n = matrix[0].length;
                        int[][] memo = new int[m][n];
                        int answer = 1;
                        for (int row = 0; row < m; row++) {
                            for (int col = 0; col < n; col++) {
                                answer = Math.max(answer, solve(matrix, memo, row, col));
                            }
                        }
                        return answer;
                    }
                    private int solve(int[][] matrix, int[][] memo, int row, int col) {
                        if (memo[row][col] != 0) { return memo[row][col]; }
                        int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
                        java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                        stack.push(new int[] {row, col, 0});
                        while (!stack.isEmpty()) {
                            int[] state = stack.peek();
                            int r = state[0];
                            int c = state[1];
                            if (memo[r][c] != 0) { stack.pop(); continue; }
                            if (state[2] == 0) {
                                state[2] = 1;
                                for (int[] direction : directions) {
                                    int nextRow = r + direction[0];
                                    int nextCol = c + direction[1];
                                    if (nextRow < 0 || nextRow >= matrix.length || nextCol < 0 || nextCol >= matrix[0].length) { continue; }
                                    if (matrix[nextRow][nextCol] > matrix[r][c] && memo[nextRow][nextCol] == 0) {
                                        stack.push(new int[] {nextRow, nextCol, 0});
                                    }
                                }
                            } else {
                                int best = 1;
                                for (int[] direction : directions) {
                                    int nextRow = r + direction[0];
                                    int nextCol = c + direction[1];
                                    if (nextRow < 0 || nextRow >= matrix.length || nextCol < 0 || nextCol >= matrix[0].length) { continue; }
                                    if (matrix[nextRow][nextCol] > matrix[r][c]) {
                                        best = Math.max(best, 1 + memo[nextRow][nextCol]);
                                    }
                                }
                                memo[r][c] = best;
                                stack.pop();
                            }
                        }
                        return memo[row][col];
                    }
                }
                """;
        return """
                    {
                      "name": "Explicit-Stack Postorder DFS Fixture",
                      "timeComplexity": "O(m * n)",
                      "spaceComplexity": "O(m * n)",
                      "description": "## Approach\\n\\nSimulate postorder DFS with an explicit stack so every larger child is memoized before its parent.\\n\\n## Key Insight\\n\\nThe memoized recurrence is the same as recursive DFS, but the stack makes dependency finishing order visible.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n)\\n- Space Complexity: O(m * n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

