    private static String distinctSubsequencesPrefixTableSolutionEntryJson() {
        String code = """
                class Solution {
                    public int numDistinct(String s, String t) {
                        int m = s.length();
                        int n = t.length();
                        long[][] dp = new long[m + 1][n + 1];
                        for (int i = 0; i <= m; i++) { dp[i][0] = 1; }
                        for (int i = 1; i <= m; i++) {
                            for (int j = 1; j <= n; j++) {
                                dp[i][j] = dp[i - 1][j];
                                if (s.charAt(i - 1) == t.charAt(j - 1)) { dp[i][j] += dp[i - 1][j - 1]; }
                            }
                        }
                        return (int) dp[m][n];
                    }
                }
                """;
        return """
                    {
                      "name": "Prefix Table DP Fixture",
                      "timeComplexity": "O(m * n)",
                      "spaceComplexity": "O(m * n)",
                      "description": "## Approach\\n\\nUse a prefix table that counts ways to form each target prefix from each source prefix.\\n\\n## Key Insight\\n\\nEvery source index either gets skipped or, when characters match, becomes the next target index, which preserves repeated-letter index choices.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n)\\n- Space Complexity: O(m * n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

    private static String distinctSubsequencesOneRowReverseTargetSolutionEntryJson() {
        String code = """
                class Solution {
                    public int numDistinct(String s, String t) {
                        int n = t.length();
                        long[] dp = new long[n + 1];
                        dp[0] = 1;
                        for (int i = 0; i < s.length(); i++) {
                            for (int j = n; j >= 1; j--) {
                                if (s.charAt(i) == t.charAt(j - 1)) { dp[j] += dp[j - 1]; }
                            }
                        }
                        return (int) dp[n];
                    }
                }
                """;
        return """
                    {
                      "name": "One-Row Reverse Target DP Fixture",
                      "timeComplexity": "O(m * n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nCompress the prefix table to one row and scan target positions backward for each source character.\\n\\n## Key Insight\\n\\nBackward target traversal keeps the previous-row value available, so one source index cannot be used twice in a single update round.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

    private static String distinctSubsequencesTopDownTakeOrSkipSolutionEntryJson() {
        String code = """
                class Solution {
                    public int numDistinct(String s, String t) {
                        long[][] memo = new long[s.length()][t.length()];
                        for (long[] row : memo) { java.util.Arrays.fill(row, -1); }
                        return (int) count(s, t, 0, 0, memo);
                    }
                    private long count(String s, String t, int i, int j, long[][] memo) {
                        if (j == t.length()) { return 1; }
                        if (i == s.length()) { return 0; }
                        if (s.length() - i < t.length() - j) { return 0; }
                        if (memo[i][j] != -1) { return memo[i][j]; }
                        long ways = count(s, t, i + 1, j, memo);
                        if (s.charAt(i) == t.charAt(j)) { ways += count(s, t, i + 1, j + 1, memo); }
                        memo[i][j] = ways;
                        return ways;
                    }
                }
                """;
        return """
                    {
                      "name": "Top-Down Take-or-Skip Memoization Fixture",
                      "timeComplexity": "O(m * n)",
                      "spaceComplexity": "O(m * n)",
                      "description": "## Approach\\n\\nRecurse on suffix states where each source index can be skipped or taken when it matches the target.\\n\\n## Key Insight\\n\\nThe take-or-skip tree has many repeated suffix states, and memoization reduces it to one state per pair of source and target positions.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n)\\n- Space Complexity: O(m * n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

    private static String distinctSubsequencesBackwardSuffixSolutionEntryJson() {
        String code = """
                class Solution {
                    public int numDistinct(String s, String t) {
                        int m = s.length();
                        int n = t.length();
                        long[][] suffix = new long[m + 1][n + 1];
                        for (int i = 0; i <= m; i++) { suffix[i][n] = 1; }
                        for (int i = m - 1; i >= 0; i--) {
                            for (int j = n - 1; j >= 0; j--) {
                                suffix[i][j] = suffix[i + 1][j];
                                if (s.charAt(i) == t.charAt(j)) { suffix[i][j] += suffix[i + 1][j + 1]; }
                            }
                        }
                        return (int) suffix[0][0];
                    }
                }
                """;
        return """
                    {
                      "name": "Backward Suffix DP Fixture",
                      "timeComplexity": "O(m * n)",
                      "spaceComplexity": "O(m * n)",
                      "description": "## Approach\\n\\nFill a suffix table from the end of both strings, inheriting skip counts and adding take counts on matches.\\n\\n## Key Insight\\n\\nThe suffix orientation makes the completed-target base case explicit: every remaining source suffix contributes one finished way.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n)\\n- Space Complexity: O(m * n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

    private static String distinctSubsequencesSparseTargetIndexSolutionEntryJson() {
        String code = """
                class Solution {
                    public int numDistinct(String s, String t) {
                        int n = t.length();
                        java.util.List<Integer>[] positions = new java.util.ArrayList[128];
                        for (int i = 0; i < positions.length; i++) { positions[i] = new java.util.ArrayList<>(); }
                        for (int j = 0; j < n; j++) { positions[t.charAt(j)].add(j + 1); }
                        long[] dp = new long[n + 1];
                        dp[0] = 1;
                        for (int i = 0; i < s.length(); i++) {
                            char ch = s.charAt(i);
                            java.util.List<Integer> matches = positions[ch];
                            for (int k = matches.size() - 1; k >= 0; k--) {
                                int j = matches.get(k);
                                dp[j] += dp[j - 1];
                            }
                        }
                        return (int) dp[n];
                    }
                }
                """;
        return """
                    {
                      "name": "Sparse Target-Index DP Fixture",
                      "timeComplexity": "O(m * k)",
                      "spaceComplexity": "O(n + A)",
                      "description": "## Approach\\n\\nBucket target positions by character and update only matching positions while scanning the source string.\\n\\n## Key Insight\\n\\nSparse buckets keep the one-row reverse-update invariant while avoiding target positions that cannot receive new subsequences from the current character.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * k), worst-case O(m * n)\\n- Space Complexity: O(n + A)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

