    private static String editDistanceBackwardSuffixSolutionEntryJson() {
        String code = """
                class Solution {
                    public int minDistance(String word1, String word2) {
                        int m = word1.length();
                        int n = word2.length();
                        int[][] suffix = new int[m + 1][n + 1];
                        for (int i = 0; i <= m; i++) { suffix[i][n] = m - i; }
                        for (int j = 0; j <= n; j++) { suffix[m][j] = n - j; }
                        for (int i = m - 1; i >= 0; i--) {
                            for (int j = n - 1; j >= 0; j--) {
                                if (word1.charAt(i) == word2.charAt(j)) {
                                    suffix[i][j] = suffix[i + 1][j + 1];
                                } else {
                                    int delete = suffix[i + 1][j];
                                    int insert = suffix[i][j + 1];
                                    int replace = suffix[i + 1][j + 1];
                                    suffix[i][j] = 1 + Math.min(replace, Math.min(delete, insert));
                                }
                            }
                        }
                        return suffix[0][0];
                    }
                }
                """;
        return """
                    {
                      "name": "Backward Suffix DP Fixture",
                      "timeComplexity": "O(m * n)",
                      "spaceComplexity": "O(m * n)",
                      "description": "## Approach\\n\\nFill suffix states from the ends of both words, using empty-suffix boundaries for pure insertions and deletions.\\n\\n## Key Insight\\n\\nThis reverses the prefix table and makes the base cases match the top-down suffix recursion directly.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n)\\n- Space Complexity: O(m * n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

    private static String editDistanceEditGraphSolutionEntryJson() {
        String code = """
                class Solution {
                    public int minDistance(String word1, String word2) {
                        int m = word1.length();
                        int n = word2.length();
                        int[][] distance = new int[m + 1][n + 1];
                        for (int[] row : distance) { java.util.Arrays.fill(row, Integer.MAX_VALUE); }
                        java.util.ArrayDeque<int[]> deque = new java.util.ArrayDeque<>();
                        distance[0][0] = 0;
                        deque.addFirst(new int[] {0, 0});
                        while (!deque.isEmpty()) {
                            int[] state = deque.removeFirst();
                            int i = state[0];
                            int j = state[1];
                            int current = distance[i][j];
                            if (i < m && j < n) {
                                int diagonalCost = word1.charAt(i) == word2.charAt(j) ? 0 : 1;
                                relax(distance, deque, i + 1, j + 1, current + diagonalCost, diagonalCost);
                            }
                            if (i < m) { relax(distance, deque, i + 1, j, current + 1, 1); }
                            if (j < n) { relax(distance, deque, i, j + 1, current + 1, 1); }
                        }
                        return distance[m][n];
                    }
                    private void relax(int[][] distance, java.util.ArrayDeque<int[]> deque, int nextI, int nextJ, int nextCost, int edgeCost) {
                        if (nextCost >= distance[nextI][nextJ]) { return; }
                        distance[nextI][nextJ] = nextCost;
                        if (edgeCost == 0) {
                            deque.addFirst(new int[] {nextI, nextJ});
                        } else {
                            deque.addLast(new int[] {nextI, nextJ});
                        }
                    }
                }
                """;
        return """
                    {
                      "name": "Edit Graph 0-1 BFS Fixture",
                      "timeComplexity": "O(m * n)",
                      "spaceComplexity": "O(m * n)",
                      "description": "## Approach\\n\\nModel position pairs as graph nodes and run 0-1 BFS over free matches and unit-cost edits.\\n\\n## Key Insight\\n\\nThe edit table is also a shortest-path grid where matching characters are zero-cost diagonal edges.\\n\\n## Complexity Analysis\\n- Time Complexity: O(m * n)\\n- Space Complexity: O(m * n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

