    private static String maximumSubarrayPrefixMinimumSolutionEntryJson() {
        String code = """
                class Solution {
                    public int maxSubArray(int[] nums) {
                        int prefix = 0;
                        int minPrefix = 0;
                        int best = Integer.MIN_VALUE;
                        for (int num : nums) {
                            prefix += num;
                            best = Math.max(best, prefix - minPrefix);
                            minPrefix = Math.min(minPrefix, prefix);
                        }
                        return best;
                    }
                }
                """;
        return """
                    {
                      "name": "Prefix Sum Minimum Prefix Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nKeep the smallest earlier prefix sum and subtract it from the current prefix.\\n\\n## Key Insight\\n\\nA contiguous subarray sum is exactly the difference of two ordered prefix sums.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

    private static String maximumSubarrayDivideAndConquerSolutionEntryJson() {
        String code = """
                class Solution {
                    public int maxSubArray(int[] nums) {
                        return solve(nums, 0, nums.length - 1);
                    }
                    private int solve(int[] nums, int left, int right) {
                        if (left == right) { return nums[left]; }
                        int mid = left + (right - left) / 2;
                        int leftBest = solve(nums, left, mid);
                        int rightBest = solve(nums, mid + 1, right);
                        int sum = 0;
                        int bestLeftSuffix = Integer.MIN_VALUE;
                        for (int i = mid; i >= left; i--) {
                            sum += nums[i];
                            bestLeftSuffix = Math.max(bestLeftSuffix, sum);
                        }
                        sum = 0;
                        int bestRightPrefix = Integer.MIN_VALUE;
                        for (int i = mid + 1; i <= right; i++) {
                            sum += nums[i];
                            bestRightPrefix = Math.max(bestRightPrefix, sum);
                        }
                        int crossing = bestLeftSuffix + bestRightPrefix;
                        return Math.max(Math.max(leftBest, rightBest), crossing);
                    }
                }
                """;
        return """
                    {
                      "name": "Divide and Conquer Crossing Sum Fixture",
                      "timeComplexity": "O(n log n)",
                      "spaceComplexity": "O(log n)",
                      "description": "## Approach\\n\\nSplit the array and compare left, right, and crossing best subarrays.\\n\\n## Key Insight\\n\\nThe only subarray spanning both halves is a left suffix plus a right prefix.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log n)\\n- Space Complexity: O(log n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

    private static String maximumSubarraySegmentStateSolutionEntryJson() {
        String code = """
                class Solution {
                    public int maxSubArray(int[] nums) {
                        State result = single(nums[0]);
                        for (int i = 1; i < nums.length; i++) {
                            result = merge(result, single(nums[i]));
                        }
                        return result.best;
                    }
                    private State single(int value) {
                        return new State(value, value, value, value);
                    }
                    private State merge(State left, State right) {
                        int total = left.total + right.total;
                        int prefix = Math.max(left.prefix, left.total + right.prefix);
                        int suffix = Math.max(right.suffix, right.total + left.suffix);
                        int best = Math.max(Math.max(left.best, right.best), left.suffix + right.prefix);
                        return new State(total, prefix, suffix, best);
                    }
                    private static class State {
                        final int total;
                        final int prefix;
                        final int suffix;
                        final int best;
                        State(int total, int prefix, int suffix, int best) {
                            this.total = total;
                            this.prefix = prefix;
                            this.suffix = suffix;
                            this.best = best;
                        }
                    }
                }
                """;
        return """
                    {
                      "name": "Segment State Monoid Merge Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nMerge total, prefix, suffix, and best-subarray states from left to right.\\n\\n## Key Insight\\n\\nThis is the segment-tree node formula specialized to one full-array scan.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

