    private static String jumpGameForwardGreedySolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean canJump(int[] nums) {
                        int maxReach = 0;
                        for (int i = 0; i < nums.length; i++) {
                            if (i > maxReach) {
                                return false;
                            }
                            maxReach = Math.max(maxReach, i + nums[i]);
                            if (maxReach >= nums.length - 1) {
                                return true;
                            }
                        }
                        return true;
                    }
                }
                """;
        return """
                    {
                      "name": "Forward Greedy Farthest Reach Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nScan reachable indices while maintaining the farthest boundary.\\n\\n## Key Insight\\n\\nThe exact jump path is irrelevant once the farthest reachable index is known.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

    private static String jumpGameBackwardGoalSolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean canJump(int[] nums) {
                        int goal = nums.length - 1;
                        for (int i = nums.length - 2; i >= 0; i--) {
                            if (i + nums[i] >= goal) {
                                goal = i;
                            }
                        }
                        return goal == 0;
                    }
                }
                """;
        return """
                    {
                      "name": "Backward Greedy Goal Shrink Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nMove the goal left whenever an earlier index can reach it.\\n\\n## Key Insight\\n\\nA good suffix can be expanded leftward one successful predecessor at a time.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

    private static String jumpGameForwardDpSolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean canJump(int[] nums) {
                        boolean[] reachable = new boolean[nums.length];
                        reachable[0] = true;
                        for (int i = 0; i < nums.length; i++) {
                            if (!reachable[i]) {
                                continue;
                            }
                            int farthest = Math.min(nums.length - 1, i + nums[i]);
                            for (int next = i + 1; next <= farthest; next++) {
                                reachable[next] = true;
                            }
                        }
                        return reachable[nums.length - 1];
                    }
                }
                """;
        return """
                    {
                      "name": "Forward Reachability DP Table Fixture",
                      "timeComplexity": "O(n^2)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nMark every index reachable from each already reachable position.\\n\\n## Key Insight\\n\\nThe problem is direct reachability in an acyclic jump graph.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

    private static String jumpGameBackwardGoodDpSolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean canJump(int[] nums) {
                        boolean[] good = new boolean[nums.length];
                        good[nums.length - 1] = true;
                        for (int i = nums.length - 2; i >= 0; i--) {
                            int farthest = Math.min(nums.length - 1, i + nums[i]);
                            for (int next = i + 1; next <= farthest; next++) {
                                if (good[next]) {
                                    good[i] = true;
                                    break;
                                }
                            }
                        }
                        return good[0];
                    }
                }
                """;
        return """
                    {
                      "name": "Backward Good-Index DP Fixture",
                      "timeComplexity": "O(n^2)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nMark an index good if it can jump to an index already known to be good.\\n\\n## Key Insight\\n\\nReachability can be defined from the target backward without recursion.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

    private static String jumpGameBfsFrontierSolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean canJump(int[] nums) {
                        if (nums.length == 1) {
                            return true;
                        }
                        int currentEnd = 0;
                        int farthest = 0;
                        for (int i = 0; i <= currentEnd; i++) {
                            farthest = Math.max(farthest, i + nums[i]);
                            if (farthest >= nums.length - 1) {
                                return true;
                            }
                            if (i == currentEnd) {
                                if (farthest == currentEnd) {
                                    return false;
                                }
                                currentEnd = farthest;
                            }
                        }
                        return false;
                    }
                }
                """;
        return """
                    {
                      "name": "Implicit BFS Frontier Expansion Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nScan each contiguous frontier and compute the next frontier boundary.\\n\\n## Key Insight\\n\\nReachable indices at the same jump depth form an interval, so a queue is unnecessary.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

