    private static String jumpGameIIGreedyLayerSolutionEntryJson() {
        String code = """
                class Solution {
                    public int jump(int[] nums) {
                        if (nums.length <= 1) {
                            return 0;
                        }
                        int jumps = 0;
                        int currentEnd = 0;
                        int farthest = 0;
                        for (int i = 0; i < nums.length - 1; i++) {
                            farthest = Math.max(farthest, i + nums[i]);
                            if (i == currentEnd) {
                                jumps++;
                                currentEnd = farthest;
                                if (currentEnd >= nums.length - 1) {
                                    break;
                                }
                            }
                        }
                        return jumps;
                    }
                }
                """;
        return """
                    {
                      "name": "Greedy BFS Layer Boundaries Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nScan each reachable layer and commit a jump when the layer ends.\\n\\n## Key Insight\\n\\nThe shortest-path BFS layers are contiguous intervals, so two boundaries replace a queue.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

    private static String jumpGameIIForwardDpSolutionEntryJson() {
        String code = """
                class Solution {
                    public int jump(int[] nums) {
                        int n = nums.length;
                        int[] dp = new int[n];
                        java.util.Arrays.fill(dp, 1_000_000);
                        dp[0] = 0;
                        for (int i = 0; i < n; i++) {
                            if (dp[i] == 1_000_000) {
                                continue;
                            }
                            int farthest = Math.min(n - 1, i + nums[i]);
                            for (int next = i + 1; next <= farthest; next++) {
                                dp[next] = Math.min(dp[next], dp[i] + 1);
                            }
                        }
                        return dp[n - 1];
                    }
                }
                """;
        return """
                    {
                      "name": "Forward DP Range Relaxation Fixture",
                      "timeComplexity": "O(n^2)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nRelax every future index reachable from each already reachable index.\\n\\n## Key Insight\\n\\nThis is the direct shortest-path DP on the acyclic jump graph.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

    private static String jumpGameIITopDownSolutionEntryJson() {
        String code = """
                class Solution {
                    public int jump(int[] nums) {
                        int[] memo = new int[nums.length];
                        java.util.Arrays.fill(memo, -1);
                        return solve(nums, 0, memo);
                    }

                    private int solve(int[] nums, int index, int[] memo) {
                        if (index >= nums.length - 1) {
                            return 0;
                        }
                        if (memo[index] != -1) {
                            return memo[index];
                        }
                        int best = 1_000_000;
                        int farthest = Math.min(nums.length - 1, index + nums[index]);
                        for (int next = index + 1; next <= farthest; next++) {
                            best = Math.min(best, 1 + solve(nums, next, memo));
                        }
                        memo[index] = best;
                        return best;
                    }
                }
                """;
        return """
                    {
                      "name": "Top-Down Minimum Jump Memoization Fixture",
                      "timeComplexity": "O(n^2)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nMemoize the minimum jumps needed from each starting index to the target.\\n\\n## Key Insight\\n\\nThe recursive decision tree collapses into one suffix subproblem per index.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

    private static String jumpGameIIBackwardDpSolutionEntryJson() {
        String code = """
                class Solution {
                    public int jump(int[] nums) {
                        int n = nums.length;
                        int[] dp = new int[n];
                        java.util.Arrays.fill(dp, 1_000_000);
                        dp[n - 1] = 0;
                        for (int i = n - 2; i >= 0; i--) {
                            int farthest = Math.min(n - 1, i + nums[i]);
                            int best = 1_000_000;
                            for (int next = i + 1; next <= farthest; next++) {
                                best = Math.min(best, 1 + dp[next]);
                            }
                            dp[i] = best;
                        }
                        return dp[0];
                    }
                }
                """;
        return """
                    {
                      "name": "Backward DP From Target Fixture",
                      "timeComplexity": "O(n^2)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nCompute the minimum remaining jumps from each index while scanning right to left.\\n\\n## Key Insight\\n\\nThe same shortest-path recurrence can be evaluated from the target backward.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n^2)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

    private static String jumpGameIIPriorityQueueSolutionEntryJson() {
        String code = """
                class Solution {
                    public int jump(int[] nums) {
                        int n = nums.length;
                        if (n == 1) {
                            return 0;
                        }
                        int[] dp = new int[n];
                        java.util.PriorityQueue<int[]> active = new java.util.PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
                        active.offer(new int[]{0, nums[0]});
                        for (int i = 1; i < n; i++) {
                            while (!active.isEmpty() && active.peek()[1] < i) {
                                active.poll();
                            }
                            dp[i] = active.peek()[0] + 1;
                            active.offer(new int[]{dp[i], i + nums[i]});
                        }
                        return dp[n - 1];
                    }
                }
                """;
        return """
                    {
                      "name": "Priority Queue Active Range DP Fixture",
                      "timeComplexity": "O(n log n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nKeep earlier reachable intervals in a priority queue ordered by their jump count.\\n\\n## Key Insight\\n\\nThe cheapest still-active interval gives the DP transition for the current index.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

