    private static String gasStationMonotonicQueueSolutionEntryJson() {
        String code = """
                class Solution {
                    public int canCompleteCircuit(int[] gas, int[] cost) {
                        int n = gas.length;
                        long[] prefix = new long[2 * n + 1];
                        for (int i = 0; i < 2 * n; i++) {
                            prefix[i + 1] = prefix[i] + gas[i % n] - cost[i % n];
                        }
                        if (prefix[n] < 0) {
                            return -1;
                        }
                        java.util.Deque<Integer> deque = new java.util.ArrayDeque<>();
                        for (int i = 1; i <= 2 * n; i++) {
                            while (!deque.isEmpty() && prefix[deque.peekLast()] >= prefix[i]) {
                                deque.pollLast();
                            }
                            deque.offerLast(i);
                            int start = i - n;
                            if (start >= 0) {
                                while (!deque.isEmpty() && deque.peekFirst() <= start) {
                                    deque.pollFirst();
                                }
                                if (start < n && !deque.isEmpty() && prefix[deque.peekFirst()] - prefix[start] >= 0) {
                                    return start;
                                }
                            }
                        }
                        return -1;
                    }
                }
                """;
        return """
                    {
                      "name": "Doubled Prefix Monotonic Queue Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nCheck each circular start as a doubled-prefix range minimum maintained by a monotonic queue.\\n\\n## Key Insight\\n\\nA start is valid exactly when the minimum prefix in its next n moves never falls below its starting prefix.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

    private static String gasStationSegmentTreeSolutionEntryJson() {
        String code = """
                class Solution {
                    public int canCompleteCircuit(int[] gas, int[] cost) {
                        int n = gas.length;
                        long[] prefix = new long[2 * n + 1];
                        for (int i = 0; i < 2 * n; i++) {
                            prefix[i + 1] = prefix[i] + gas[i % n] - cost[i % n];
                        }
                        if (prefix[n] < 0) {
                            return -1;
                        }
                        RangeMinTree tree = new RangeMinTree(prefix);
                        for (int start = 0; start < n; start++) {
                            long minBalance = tree.query(start + 1, start + n);
                            if (minBalance - prefix[start] >= 0) {
                                return start;
                            }
                        }
                        return -1;
                    }

                    private static class RangeMinTree {
                        private final int size;
                        private final long[] tree;

                        RangeMinTree(long[] values) {
                            int capacity = 1;
                            while (capacity < values.length) {
                                capacity <<= 1;
                            }
                            size = capacity;
                            tree = new long[size * 2];
                            java.util.Arrays.fill(tree, Long.MAX_VALUE / 4);
                            for (int i = 0; i < values.length; i++) {
                                tree[size + i] = values[i];
                            }
                            for (int i = size - 1; i > 0; i--) {
                                tree[i] = Math.min(tree[i * 2], tree[i * 2 + 1]);
                            }
                        }

                        long query(int left, int right) {
                            left += size;
                            right += size;
                            long answer = Long.MAX_VALUE / 4;
                            while (left <= right) {
                                if ((left & 1) == 1) {
                                    answer = Math.min(answer, tree[left++]);
                                }
                                if ((right & 1) == 0) {
                                    answer = Math.min(answer, tree[right--]);
                                }
                                left >>= 1;
                                right >>= 1;
                            }
                            return answer;
                        }
                    }
                }
                """;
        return """
                    {
                      "name": "Segment Tree Range Minimum Fixture",
                      "timeComplexity": "O(n log n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nBuild a segment tree over doubled prefix sums and query each start window for its minimum balance.\\n\\n## Key Insight\\n\\nGas Station can be stated as a circular range-minimum feasibility check on prefix sums.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

