    private static String handOfStraightsPriorityQueueSolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean isNStraightHand(int[] hand, int groupSize) {
                        if (hand.length % groupSize != 0) {
                            return false;
                        }
                        if (groupSize == 1) {
                            return true;
                        }
                        java.util.Arrays.sort(hand);
                        java.util.PriorityQueue<int[]> groups = new java.util.PriorityQueue<>((a, b) -> {
                            if (a[0] != b[0]) {
                                return Integer.compare(a[0], b[0]);
                            }
                            return Integer.compare(a[1], b[1]);
                        });
                        for (int card : hand) {
                            if (!groups.isEmpty() && groups.peek()[0] + 1 < card) {
                                return false;
                            }
                            if (!groups.isEmpty() && groups.peek()[0] + 1 == card) {
                                int[] group = groups.poll();
                                group[0] = card;
                                group[1]++;
                                if (group[1] < groupSize) {
                                    groups.offer(group);
                                }
                            } else {
                                groups.offer(new int[] {card, 1});
                            }
                        }
                        return groups.isEmpty();
                    }
                }
                """;
        return """
                    {
                      "name": "Priority Queue Unfinished Groups Fixture",
                      "timeComplexity": "O(n log n)",
                      "spaceComplexity": "O(n)",
                      "description": "## Approach\\n\\nExtend the unfinished group with the earliest ending value before starting a new group.\\n\\n## Key Insight\\n\\nThe earliest-ending unfinished group has the first deadline; if the current card passes it, completion is impossible.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

