    private static String mergeTripletsIndependentWitnessSolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean mergeTriplets(int[][] triplets, int[] target) {
                        for (int coordinate = 0; coordinate < 3; coordinate++) {
                            boolean hasWitness = false;
                            for (int[] triplet : triplets) {
                                if (isSafe(triplet, target) && triplet[coordinate] == target[coordinate]) {
                                    hasWitness = true;
                                    break;
                                }
                            }
                            if (!hasWitness) {
                                return false;
                            }
                        }
                        return true;
                    }

                    private boolean isSafe(int[] triplet, int[] target) {
                        return triplet[0] <= target[0]
                                && triplet[1] <= target[1]
                                && triplet[2] <= target[2];
                    }
                }
                """;
        return """
                    {
                      "name": "Independent Coordinate Witness Scan Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nFor each coordinate, scan for a safe triplet that equals the target in that coordinate.\\n\\n## Key Insight\\n\\nThe three coordinates need independent safe witnesses, and because there are only three coordinates, three scans remain linear.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

    private static String mergeTripletsConstructiveWitnessSolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean mergeTriplets(int[][] triplets, int[] target) {
                        int[][] witnesses = new int[3][];
                        for (int[] triplet : triplets) {
                            if (triplet[0] > target[0] || triplet[1] > target[1] || triplet[2] > target[2]) {
                                continue;
                            }
                            for (int coordinate = 0; coordinate < 3; coordinate++) {
                                if (triplet[coordinate] == target[coordinate] && witnesses[coordinate] == null) {
                                    witnesses[coordinate] = triplet;
                                }
                            }
                        }
                        int[] merged = new int[3];
                        for (int coordinate = 0; coordinate < 3; coordinate++) {
                            if (witnesses[coordinate] == null) {
                                return false;
                            }
                            for (int i = 0; i < 3; i++) {
                                merged[i] = Math.max(merged[i], witnesses[coordinate][i]);
                            }
                        }
                        return merged[0] == target[0]
                                && merged[1] == target[1]
                                && merged[2] == target[2];
                    }
                }
                """;
        return """
                    {
                      "name": "Constructive Witness Merge Fixture",
                      "timeComplexity": "O(n)",
                      "spaceComplexity": "O(1)",
                      "description": "## Approach\\n\\nSave one safe witness for each coordinate, merge those witnesses, and compare the constructed triplet to target.\\n\\n## Key Insight\\n\\nIf each coordinate has a safe witness, those at most three witnesses are enough to construct the target.\\n\\n## Complexity Analysis\\n- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                      "code": "%s",
                      "language": "java"
                    }
                """.formatted(escapeJsonString(code.strip())).stripTrailing();
    }

