    private static String partitionLabelsLastOccurrenceSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public List<Integer> partitionLabels(String s) {
                        int[] last = new int[26];
                        for (int i = 0; i < s.length(); i++) {
                            last[s.charAt(i) - 'a'] = i;
                        }
                        List<Integer> result = new ArrayList<>();
                        int start = 0;
                        int end = 0;
                        for (int i = 0; i < s.length(); i++) {
                            end = Math.max(end, last[s.charAt(i) - 'a']);
                            if (i == end) {
                                result.add(end - start + 1);
                                start = end + 1;
                            }
                        }
                        return result;
                    }
                }
                """;
        return partitionLabelsSolutionEntryJson(
                "Last Occurrence Greedy Fixture",
                "O(n)",
                "O(1)",
                "Record each character's last position and close a part when the scan reaches the farthest required end.",
                "A part cannot close before every character it contains has reached its final occurrence.",
                "The string is scanned twice and the alphabet array has fixed size.",
                code);
    }

    private static String partitionLabelsIntervalMergeSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public List<Integer> partitionLabels(String s) {
                        int[] first = new int[26];
                        int[] last = new int[26];
                        Arrays.fill(first, -1);
                        for (int i = 0; i < s.length(); i++) {
                            int c = s.charAt(i) - 'a';
                            if (first[c] == -1) {
                                first[c] = i;
                            }
                            last[c] = i;
                        }
                        List<int[]> intervals = new ArrayList<>();
                        for (int c = 0; c < 26; c++) {
                            if (first[c] != -1) {
                                intervals.add(new int[]{first[c], last[c]});
                            }
                        }
                        intervals.sort((a, b) -> Integer.compare(a[0], b[0]));
                        List<Integer> result = new ArrayList<>();
                        int start = intervals.get(0)[0];
                        int end = intervals.get(0)[1];
                        for (int i = 1; i < intervals.size(); i++) {
                            int[] interval = intervals.get(i);
                            if (interval[0] <= end) {
                                end = Math.max(end, interval[1]);
                            } else {
                                result.add(end - start + 1);
                                start = interval[0];
                                end = interval[1];
                            }
                        }
                        result.add(end - start + 1);
                        return result;
                    }
                }
                """;
        return partitionLabelsSolutionEntryJson(
                "Merge Character Intervals Fixture",
                "O(n + k log k)",
                "O(k)",
                "Build first-to-last intervals for characters and merge overlapping intervals.",
                "Overlapping character intervals must belong to the same final partition.",
                "Building intervals is linear and sorting at most 26 intervals is bounded.",
                code);
    }

    private static String partitionLabelsRemainingFrequencySolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public List<Integer> partitionLabels(String s) {
                        int[] remaining = new int[26];
                        for (int i = 0; i < s.length(); i++) {
                            remaining[s.charAt(i) - 'a']++;
                        }
                        boolean[] active = new boolean[26];
                        int openCharacters = 0;
                        int start = 0;
                        List<Integer> result = new ArrayList<>();
                        for (int i = 0; i < s.length(); i++) {
                            int c = s.charAt(i) - 'a';
                            if (!active[c]) {
                                active[c] = true;
                                openCharacters++;
                            }
                            remaining[c]--;
                            if (remaining[c] == 0) {
                                active[c] = false;
                                openCharacters--;
                            }
                            if (openCharacters == 0) {
                                result.add(i - start + 1);
                                start = i + 1;
                            }
                        }
                        return result;
                    }
                }
                """;
        return partitionLabelsSolutionEntryJson(
                "Remaining Frequency Active Set Fixture",
                "O(n)",
                "O(1)",
                "Track remaining counts and keep the current segment open while any active character appears later.",
                "A segment closes exactly when no character seen in it has future occurrences.",
                "Counting and scanning are linear with fixed alphabet storage.",
                code);
    }

    private static String partitionLabelsClosedSegmentSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public List<Integer> partitionLabels(String s) {
                        int[] first = new int[26];
                        int[] last = new int[26];
                        Arrays.fill(first, -1);
                        for (int i = 0; i < s.length(); i++) {
                            int c = s.charAt(i) - 'a';
                            if (first[c] == -1) {
                                first[c] = i;
                            }
                            last[c] = i;
                        }
                        List<Integer> result = new ArrayList<>();
                        int start = 0;
                        while (start < s.length()) {
                            for (int end = start; end < s.length(); end++) {
                                if (isClosedSegment(first, last, start, end)) {
                                    result.add(end - start + 1);
                                    start = end + 1;
                                    break;
                                }
                            }
                        }
                        return result;
                    }
                    private boolean isClosedSegment(int[] first, int[] last, int start, int end) {
                        for (int c = 0; c < 26; c++) {
                            if (first[c] == -1) {
                                continue;
                            }
                            boolean overlaps = first[c] <= end && last[c] >= start;
                            if (overlaps && (first[c] < start || last[c] > end)) {
                                return false;
                            }
                        }
                        return true;
                    }
                }
                """;
        return partitionLabelsSolutionEntryJson(
                "Brute Force Closed-Segment Fixture",
                "O(26 * n^2)",
                "O(1)",
                "Try candidate segment ends and accept the first segment that fully contains every touched character interval.",
                "A segment is valid only when each character is completely inside or completely outside it.",
                "Each candidate end checks the fixed alphabet, giving a quadratic baseline.",
                code);
    }

    private static String partitionLabelsUnionFindSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public List<Integer> partitionLabels(String s) {
                        int n = s.length();
                        int[] first = new int[26];
                        int[] last = new int[26];
                        Arrays.fill(first, -1);
                        for (int i = 0; i < n; i++) {
                            int c = s.charAt(i) - 'a';
                            if (first[c] == -1) {
                                first[c] = i;
                            }
                            last[c] = i;
                        }
                        DSU dsu = new DSU(n);
                        for (int c = 0; c < 26; c++) {
                            if (first[c] == -1) {
                                continue;
                            }
                            for (int i = first[c] + 1; i <= last[c]; i++) {
                                dsu.union(first[c], i);
                            }
                        }
                        List<Integer> result = new ArrayList<>();
                        int start = 0;
                        int root = dsu.find(0);
                        for (int i = 1; i < n; i++) {
                            int current = dsu.find(i);
                            if (current != root) {
                                result.add(i - start);
                                start = i;
                                root = current;
                            }
                        }
                        result.add(n - start);
                        return result;
                    }
                    private static class DSU {
                        private final int[] parent;
                        DSU(int n) {
                            parent = new int[n];
                            for (int i = 0; i < n; i++) {
                                parent[i] = i;
                            }
                        }
                        int find(int x) {
                            if (parent[x] != x) {
                                parent[x] = find(parent[x]);
                            }
                            return parent[x];
                        }
                        void union(int a, int b) {
                            int rootA = find(a);
                            int rootB = find(b);
                            if (rootA != rootB) {
                                parent[rootB] = rootA;
                            }
                        }
                    }
                }
                """;
        return partitionLabelsSolutionEntryJson(
                "Union-Find Index Components Fixture",
                "O(26 * n 伪(n))",
                "O(n)",
                "Union every index inside each character interval, then output contiguous component lengths.",
                "Character intervals force indices into connected components that become the final partitions.",
                "At most 26 intervals perform linear union work and the DSU stores one parent per index.",
                code);
    }

