    private static String mergeIntervalsSortSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[][] merge(int[][] intervals) {
                        java.util.Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));
                        java.util.List<int[]> result = new java.util.ArrayList<>();
                        for (int[] interval : intervals) {
                            if (result.isEmpty() || result.get(result.size() - 1)[1] < interval[0]) {
                                result.add(new int[] {interval[0], interval[1]});
                            } else {
                                int[] last = result.get(result.size() - 1);
                                last[1] = Math.max(last[1], interval[1]);
                            }
                        }
                        return result.toArray(new int[result.size()][]);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Sort By Start Merge Fixture",
                "O(n log n)",
                "O(n)",
                "Sort intervals by start and merge each interval into the current output tail.",
                "After sorting by start, every interval in the same merged component appears consecutively.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String mergeIntervalsPriorityQueueSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public int[][] merge(int[][] intervals) {
                        PriorityQueue<int[]> minHeap = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
                        for (int[] interval : intervals) {
                            minHeap.offer(new int[] {interval[0], interval[1]});
                        }
                        List<int[]> result = new ArrayList<>();
                        while (!minHeap.isEmpty()) {
                            int[] interval = minHeap.poll();
                            if (result.isEmpty() || result.get(result.size() - 1)[1] < interval[0]) {
                                result.add(interval);
                            } else {
                                int[] last = result.get(result.size() - 1);
                                last[1] = Math.max(last[1], interval[1]);
                            }
                        }
                        return result.toArray(new int[result.size()][]);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Priority Queue Ordered Merge Fixture",
                "O(n log n)",
                "O(n)",
                "Push intervals into a priority queue and poll them in increasing start order.",
                "A heap supplies the same ordered stream as sorting without relying on the original array order.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String mergeIntervalsSeparateStartsEndsSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[][] merge(int[][] intervals) {
                        int n = intervals.length;
                        int[] starts = new int[n];
                        int[] ends = new int[n];
                        for (int i = 0; i < n; i++) {
                            starts[i] = intervals[i][0];
                            ends[i] = intervals[i][1];
                        }
                        java.util.Arrays.sort(starts);
                        java.util.Arrays.sort(ends);
                        java.util.List<int[]> result = new java.util.ArrayList<>();
                        int startIndex = 0;
                        for (int i = 0; i < n; i++) {
                            if (i == n - 1 || starts[i + 1] > ends[i]) {
                                result.add(new int[] {starts[startIndex], ends[i]});
                                startIndex = i + 1;
                            }
                        }
                        return result.toArray(new int[result.size()][]);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Separate Starts And Ends Sweep Fixture",
                "O(n log n)",
                "O(n)",
                "Sort starts and ends independently, then close a merged interval when the next start passes the current end.",
                "For closed intervals, equality still overlaps, so only a strictly greater next start closes the range.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

