    private static String mergeIntervalsGraphSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public int[][] merge(int[][] intervals) {
                        int n = intervals.length;
                        boolean[] visited = new boolean[n];
                        List<int[]> result = new ArrayList<>();
                        for (int i = 0; i < n; i++) {
                            if (visited[i]) {
                                continue;
                            }
                            int start = intervals[i][0];
                            int end = intervals[i][1];
                            Deque<Integer> stack = new ArrayDeque<>();
                            visited[i] = true;
                            stack.push(i);
                            while (!stack.isEmpty()) {
                                int current = stack.pop();
                                start = Math.min(start, intervals[current][0]);
                                end = Math.max(end, intervals[current][1]);
                                for (int next = 0; next < n; next++) {
                                    if (!visited[next] && overlaps(intervals[current], intervals[next])) {
                                        visited[next] = true;
                                        stack.push(next);
                                    }
                                }
                            }
                            result.add(new int[] {start, end});
                        }
                        result.sort((a, b) -> Integer.compare(a[0], b[0]));
                        return result.toArray(new int[result.size()][]);
                    }
                    private boolean overlaps(int[] a, int[] b) {
                        return a[0] <= b[1] && b[0] <= a[1];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Overlap Graph Components Fixture",
                "O(n^2)",
                "O(n)",
                "Treat intervals as graph nodes and DFS each implicit overlap component.",
                "Merging is transitive, so a connected component captures ranges linked through intermediate overlaps.",
                "- Time Complexity: O(n^2)\\n- Space Complexity: O(n)",
                code);
    }

