    private static String meetingRoomsEventDeltaSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public boolean canAttendMeetings(int[][] intervals) {
                        TreeMap<Integer, Integer> events = new TreeMap<>();
                        for (int[] interval : intervals) {
                            events.merge(interval[0], 1, Integer::sum);
                            events.merge(interval[1], -1, Integer::sum);
                        }
                        int active = 0;
                        for (int delta : events.values()) {
                            active += delta;
                            if (active > 1) {
                                return false;
                            }
                        }
                        return true;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Event Delta Sweep Fixture",
                "O(n log n)",
                "O(n)",
                "Add start and end deltas to an ordered timeline and reject any coordinate where active meetings exceed one.",
                "Combining deltas at the same coordinate makes an end and a start at that time compatible.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String meetingRoomsCalendarInsertionSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public boolean canAttendMeetings(int[][] intervals) {
                        TreeMap<Integer, Integer> calendar = new TreeMap<>();
                        for (int[] interval : intervals) {
                            int start = interval[0];
                            int end = interval[1];
                            Map.Entry<Integer, Integer> previous = calendar.floorEntry(start);
                            if (previous != null && previous.getValue() > start) {
                                return false;
                            }
                            Map.Entry<Integer, Integer> next = calendar.ceilingEntry(start);
                            if (next != null && end > next.getKey()) {
                                return false;
                            }
                            calendar.put(start, Math.max(calendar.getOrDefault(start, end), end));
                        }
                        return true;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Ordered Calendar Insertion Fixture",
                "O(n log n)",
                "O(n)",
                "Insert each meeting into an ordered calendar after checking only the predecessor and successor.",
                "By start order, a new meeting can overlap only its nearest previous or next neighbor.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

