    private static String meetingRoomsIIBoundedTimelineSolutionEntryJson() {
        String code = """
                class Solution {
                    public int minMeetingRooms(int[][] intervals) {
                        int maxEnd = 0;
                        for (int[] interval : intervals) {
                            maxEnd = Math.max(maxEnd, interval[1]);
                        }
                        int[] diff = new int[maxEnd + 1];
                        for (int[] interval : intervals) {
                            diff[interval[0]]++;
                            diff[interval[1]]--;
                        }
                        int active = 0;
                        int rooms = 0;
                        for (int time = 0; time <= maxEnd; time++) {
                            active += diff[time];
                            rooms = Math.max(rooms, active);
                        }
                        return rooms;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Bounded Timeline Difference Array Fixture",
                "O(n + U)",
                "O(U)",
                "Use the bounded time coordinate to scan a dense difference array instead of sorting.",
                "When the coordinate range is affordable, the prefix maximum of active meetings gives the room count.",
                "- Time Complexity: O(n + U)\\n- Space Complexity: O(U)",
                code);
    }

