    private static String minimumArrowsBalloonsRightEndpointGreedySolutionEntryJson() {
        String code = """
                class Solution {
                    public int findMinArrowShots(int[][] points) {
                        java.util.Arrays.sort(points, (a, b) -> Integer.compare(a[1], b[1]));
                        int arrows = 1;
                        int arrowPosition = points[0][1];
                        for (int i = 1; i < points.length; i++) {
                            if (points[i][0] > arrowPosition) {
                                arrows++;
                                arrowPosition = points[i][1];
                            }
                        }
                        return arrows;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Right Endpoint Greedy Fixture",
                "O(n log n)",
                "O(1)",
                "Sort balloons by right endpoint and shoot each new arrow at the first uncovered right endpoint.",
                "The earliest possible right endpoint is the safest placement because it keeps future overlap chances maximal.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String minimumArrowsBalloonsStartIntersectionSolutionEntryJson() {
        String code = """
                class Solution {
                    public int findMinArrowShots(int[][] points) {
                        java.util.Arrays.sort(points, (a, b) -> {
                            int byStart = Integer.compare(a[0], b[0]);
                            return byStart != 0 ? byStart : Integer.compare(a[1], b[1]);
                        });
                        int arrows = 1;
                        int currentEnd = points[0][1];
                        for (int i = 1; i < points.length; i++) {
                            if (points[i][0] > currentEnd) {
                                arrows++;
                                currentEnd = points[i][1];
                            } else {
                                currentEnd = Math.min(currentEnd, points[i][1]);
                            }
                        }
                        return arrows;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Start Order Intersection Shrinking Fixture",
                "O(n log n)",
                "O(1)",
                "Sort by start coordinate and keep shrinking the common intersection of the active one-arrow group.",
                "A group is hittable by one arrow exactly while the closed intervals share a non-empty intersection.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String minimumArrowsBalloonsPriorityQueueSolutionEntryJson() {
        String code = """
                class Solution {
                    public int findMinArrowShots(int[][] points) {
                        java.util.Arrays.sort(points, (a, b) -> {
                            int byStart = Integer.compare(a[0], b[0]);
                            return byStart != 0 ? byStart : Integer.compare(a[1], b[1]);
                        });
                        java.util.PriorityQueue<Integer> activeEnds = new java.util.PriorityQueue<>();
                        int arrows = 0;
                        for (int[] point : points) {
                            if (!activeEnds.isEmpty() && activeEnds.peek() < point[0]) {
                                arrows++;
                                activeEnds.clear();
                            }
                            activeEnds.offer(point[1]);
                        }
                        return arrows + (activeEnds.isEmpty() ? 0 : 1);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Priority Queue Active Intersection Fixture",
                "O(n log n)",
                "O(n)",
                "Keep a min-heap of active right endpoints while scanning balloons by start coordinate.",
                "The smallest active right endpoint is a valid shot for the active group until a later start passes it.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String minimumArrowsBalloonsEventSweepSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public int findMinArrowShots(int[][] points) {
                        int[][] events = new int[points.length * 2][3];
                        int index = 0;
                        for (int i = 0; i < points.length; i++) {
                            events[index++] = new int[]{points[i][0], 0, i};
                            events[index++] = new int[]{points[i][1], 1, i};
                        }
                        java.util.Arrays.sort(events, (a, b) -> {
                            int byCoordinate = Integer.compare(a[0], b[0]);
                            return byCoordinate != 0 ? byCoordinate : Integer.compare(a[1], b[1]);
                        });
                        Set<Integer> active = new HashSet<>();
                        int arrows = 0;
                        for (int[] event : events) {
                            if (event[1] == 0) {
                                active.add(event[2]);
                            } else if (active.remove(event[2])) {
                                arrows++;
                                active.clear();
                            }
                        }
                        return arrows;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Explicit Event Sweep Fixture",
                "O(n log n)",
                "O(n)",
                "Create start and end events and shoot at the earliest end event that still belongs to an active balloon.",
                "Processing starts before ends at the same coordinate encodes the closed interval endpoint-sharing rule.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String minimumArrowsBalloonsOrderedArrowSetSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public int findMinArrowShots(int[][] points) {
                        java.util.Arrays.sort(points, (a, b) -> Integer.compare(a[1], b[1]));
                        TreeSet<Integer> arrows = new TreeSet<>();
                        for (int[] point : points) {
                            Integer candidate = arrows.ceiling(point[0]);
                            if (candidate != null && candidate <= point[1]) {
                                continue;
                            }
                            arrows.add(point[1]);
                        }
                        return arrows.size();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Ordered Arrow Set Fixture",
                "O(n log n)",
                "O(n)",
                "Store selected arrow positions in a TreeSet and explicitly query whether one already covers each balloon.",
                "Right-end ordering keeps inserted arrows as early as possible while the ordered set makes stabbing checks visible.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

