    private static String spiralMatrixShrinkingBoundarySolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public List<Integer> spiralOrder(int[][] matrix) {
                        List<Integer> result = new ArrayList<>();
                        int top = 0;
                        int bottom = matrix.length - 1;
                        int left = 0;
                        int right = matrix[0].length - 1;
                        while (top <= bottom && left <= right) {
                            for (int col = left; col <= right; col++) {
                                result.add(matrix[top][col]);
                            }
                            top++;
                            for (int row = top; row <= bottom; row++) {
                                result.add(matrix[row][right]);
                            }
                            right--;
                            if (top <= bottom) {
                                for (int col = right; col >= left; col--) {
                                    result.add(matrix[bottom][col]);
                                }
                                bottom--;
                            }
                            if (left <= right) {
                                for (int row = bottom; row >= top; row--) {
                                    result.add(matrix[row][left]);
                                }
                                left++;
                            }
                        }
                        return result;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Shrinking Boundary Simulation Fixture",
                "O(m * n)",
                "O(1)",
                "Maintain four boundaries and read the current top, right, bottom, and left sides before shrinking them.",
                "A spiral is a sequence of nested rectangles, and each completed side must be removed from later traversal.",
                "- Time Complexity: O(m * n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String spiralMatrixDirectionVectorsVisitedSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public List<Integer> spiralOrder(int[][] matrix) {
                        int rows = matrix.length;
                        int cols = matrix[0].length;
                        boolean[][] visited = new boolean[rows][cols];
                        int[] dr = {0, 1, 0, -1};
                        int[] dc = {1, 0, -1, 0};
                        int row = 0;
                        int col = 0;
                        int dir = 0;
                        List<Integer> result = new ArrayList<>();
                        for (int count = 0; count < rows * cols; count++) {
                            result.add(matrix[row][col]);
                            visited[row][col] = true;
                            int nextRow = row + dr[dir];
                            int nextCol = col + dc[dir];
                            if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols
                                    || visited[nextRow][nextCol]) {
                                dir = (dir + 1) % 4;
                                nextRow = row + dr[dir];
                                nextCol = col + dc[dir];
                            }
                            row = nextRow;
                            col = nextCol;
                        }
                        return result;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Direction Vectors With Visited Matrix Fixture",
                "O(m * n)",
                "O(m * n)",
                "Move with right, down, left, and up direction vectors while marking each consumed cell visited.",
                "The next step decides whether to continue straight or turn right, so a visited matrix replaces boundary math.",
                "- Time Complexity: O(m * n)\\n- Space Complexity: O(m * n)",
                code);
    }

    private static String spiralMatrixRecursivePeelSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public List<Integer> spiralOrder(int[][] matrix) {
                        List<Integer> result = new ArrayList<>();
                        peel(matrix, 0, matrix.length - 1, 0, matrix[0].length - 1, result);
                        return result;
                    }

                    private void peel(int[][] matrix, int top, int bottom, int left, int right,
                            List<Integer> result) {
                        if (top > bottom || left > right) {
                            return;
                        }
                        for (int col = left; col <= right; col++) {
                            result.add(matrix[top][col]);
                        }
                        for (int row = top + 1; row <= bottom; row++) {
                            result.add(matrix[row][right]);
                        }
                        if (top < bottom) {
                            for (int col = right - 1; col >= left; col--) {
                                result.add(matrix[bottom][col]);
                            }
                        }
                        if (left < right) {
                            for (int row = bottom - 1; row > top; row--) {
                                result.add(matrix[row][left]);
                            }
                        }
                        peel(matrix, top + 1, bottom - 1, left + 1, right - 1, result);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Recursive Boundary Peel Fixture",
                "O(m * n)",
                "O(min(m, n))",
                "Append the outer boundary, then recursively solve the smaller inner rectangle.",
                "The outer ring is independent from the remaining subproblem, so recursion directly models nested layers.",
                "- Time Complexity: O(m * n)\\n- Space Complexity: O(min(m, n))",
                code);
    }

    private static String spiralMatrixBoundaryStateMachineSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public List<Integer> spiralOrder(int[][] matrix) {
                        int rows = matrix.length;
                        int cols = matrix[0].length;
                        int top = 0;
                        int bottom = rows - 1;
                        int left = 0;
                        int right = cols - 1;
                        int row = 0;
                        int col = 0;
                        int direction = 0;
                        List<Integer> result = new ArrayList<>();
                        for (int count = 0; count < rows * cols; count++) {
                            result.add(matrix[row][col]);
                            if (direction == 0) {
                                if (col == right) {
                                    top++;
                                    row++;
                                    direction = 1;
                                } else {
                                    col++;
                                }
                            } else if (direction == 1) {
                                if (row == bottom) {
                                    right--;
                                    col--;
                                    direction = 2;
                                } else {
                                    row++;
                                }
                            } else if (direction == 2) {
                                if (col == left) {
                                    bottom--;
                                    row--;
                                    direction = 3;
                                } else {
                                    col--;
                                }
                            } else {
                                if (row == top) {
                                    left++;
                                    col++;
                                    direction = 0;
                                } else {
                                    row--;
                                }
                            }
                        }
                        return result;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Boundary State Machine Without Visited Fixture",
                "O(m * n)",
                "O(1)",
                "Track direction and the active rectangle, turning when the walker reaches the active boundary.",
                "The shrinking rectangle identifies all unvisited cells, so no visited matrix is needed.",
                "- Time Complexity: O(m * n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String spiralMatrixLayerIndexSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public List<Integer> spiralOrder(int[][] matrix) {
                        int rows = matrix.length;
                        int cols = matrix[0].length;
                        int layers = (Math.min(rows, cols) + 1) / 2;
                        List<Integer> result = new ArrayList<>();
                        for (int layer = 0; layer < layers; layer++) {
                            int top = layer;
                            int bottom = rows - 1 - layer;
                            int left = layer;
                            int right = cols - 1 - layer;
                            if (top > bottom || left > right) {
                                continue;
                            }
                            if (top == bottom) {
                                for (int col = left; col <= right; col++) {
                                    result.add(matrix[top][col]);
                                }
                                continue;
                            }
                            if (left == right) {
                                for (int row = top; row <= bottom; row++) {
                                    result.add(matrix[row][left]);
                                }
                                continue;
                            }
                            for (int col = left; col <= right; col++) {
                                result.add(matrix[top][col]);
                            }
                            for (int row = top + 1; row <= bottom; row++) {
                                result.add(matrix[row][right]);
                            }
                            for (int col = right - 1; col >= left; col--) {
                                result.add(matrix[bottom][col]);
                            }
                            for (int row = bottom - 1; row > top; row--) {
                                result.add(matrix[row][left]);
                            }
                        }
                        return result;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Layer Index Perimeter Traversal Fixture",
                "O(m * n)",
                "O(1)",
                "Compute each layer from its index and append that layer's perimeter with degenerate-row checks.",
                "Layer k is exactly the rectangle offset k cells from the border, which makes perimeter geometry explicit.",
                "- Time Complexity: O(m * n)\\n- Space Complexity: O(1)",
                code);
    }

