    private static String happyNumberMemoizedGraphSolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean isHappy(int n) {
                        int[] state = new int[811];
                        return isHappyState(n, state);
                    }

                    private boolean isHappyState(int n, int[] state) {
                        if (n == 1) {
                            return true;
                        }
                        if (n >= state.length) {
                            return isHappyState(next(n), state);
                        }
                        if (state[n] == 1) {
                            return false;
                        }
                        if (state[n] == 2) {
                            return true;
                        }
                        if (state[n] == 3) {
                            return false;
                        }
                        state[n] = 1;
                        boolean happy = isHappyState(next(n), state);
                        state[n] = happy ? 2 : 3;
                        return happy;
                    }

                    private int next(int n) {
                        int sum = 0;
                        while (n > 0) {
                            int digit = n % 10;
                            sum += digit * digit;
                            n /= 10;
                        }
                        return sum;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Memoized Functional Graph Classification Fixture",
                "O(log n)",
                "O(1)",
                "Classify bounded graph states as visiting, happy, or unhappy with memoized recursion.",
                "The transition graph has one outgoing edge per state, so a visiting state means a cycle.",
                "- Time Complexity: O(log n)\\n- Space Complexity: O(1)",
                code);
    }

