    private static String powXNRightToLeftBinarySolutionEntryJson() {
        String code = """
                class Solution {
                    public double myPow(double x, int n) {
                        long exponent = n;
                        if (exponent < 0) {
                            x = 1.0 / x;
                            exponent = -exponent;
                        }

                        double answer = 1.0;
                        while (exponent > 0) {
                            if ((exponent & 1L) == 1L) {
                                answer *= x;
                            }
                            x *= x;
                            exponent >>= 1;
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Right-to-Left Binary Exponentiation Fixture",
                "O(log n)",
                "O(1)",
                "Scan exponent bits from low to high while squaring the base each round.",
                "The exponent's binary representation selects which squared bases contribute to the product.",
                "- Time Complexity: O(log |n|)\\n- Space Complexity: O(1)",
                code);
    }

    private static String powXNRecursiveHalfPowerSolutionEntryJson() {
        String code = """
                class Solution {
                    public double myPow(double x, int n) {
                        long exponent = n;
                        if (exponent < 0) {
                            return 1.0 / power(x, -exponent);
                        }
                        return power(x, exponent);
                    }

                    private double power(double base, long exponent) {
                        if (exponent == 0) {
                            return 1.0;
                        }
                        double half = power(base, exponent / 2);
                        double squared = half * half;
                        return exponent % 2 == 0 ? squared : squared * base;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Recursive Half-Power Fixture",
                "O(log n)",
                "O(log n)",
                "Recursively compute the half exponent, square it, and multiply the base for odd exponents.",
                "Each recursive level halves the remaining exponent and keeps sign handling outside the recurrence.",
                "- Time Complexity: O(log |n|)\\n- Space Complexity: O(log |n|)",
                code);
    }

    private static String powXNBinaryPowersTableSolutionEntryJson() {
        String code = """
                import java.util.ArrayList;
                import java.util.List;

                class Solution {
                    public double myPow(double x, int n) {
                        long exponent = n;
                        boolean negative = exponent < 0;
                        if (negative) {
                            exponent = -exponent;
                        }

                        List<Double> powers = new ArrayList<>();
                        double current = x;
                        for (long value = exponent; value > 0; value >>= 1) {
                            powers.add(current);
                            current *= current;
                        }

                        double answer = 1.0;
                        int bit = 0;
                        while (exponent > 0) {
                            if ((exponent & 1L) == 1L) {
                                answer *= powers.get(bit);
                            }
                            bit++;
                            exponent >>= 1;
                        }
                        return negative ? 1.0 / answer : answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Binary Powers Table Fixture",
                "O(log n)",
                "O(log n)",
                "Precompute powers selected by exponent bits, then multiply only selected table entries.",
                "Separating table generation from answer assembly makes the binary decomposition explicit.",
                "- Time Complexity: O(log |n|)\\n- Space Complexity: O(log |n|)",
                code);
    }

    private static String powXNLeftToRightBinarySolutionEntryJson() {
        String code = """
                class Solution {
                    public double myPow(double x, int n) {
                        long exponent = n;
                        boolean negative = exponent < 0;
                        if (negative) {
                            exponent = -exponent;
                        }
                        if (exponent == 0) {
                            return 1.0;
                        }

                        int highestBit = 63 - Long.numberOfLeadingZeros(exponent);
                        double answer = 1.0;
                        for (int bit = highestBit; bit >= 0; bit--) {
                            answer *= answer;
                            if (((exponent >> bit) & 1L) == 1L) {
                                answer *= x;
                            }
                        }
                        return negative ? 1.0 / answer : answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Left-to-Right Binary Exponentiation Fixture",
                "O(log n)",
                "O(1)",
                "Read exponent bits from the highest set bit to the lowest, squaring the answer at each step.",
                "High-to-low scanning updates the accumulated answer instead of repeatedly updating the base.",
                "- Time Complexity: O(log |n|)\\n- Space Complexity: O(1)",
                code);
    }

    private static String powXNExplicitStackSolutionEntryJson() {
        String code = """
                import java.util.ArrayDeque;
                import java.util.Deque;

                class Solution {
                    public double myPow(double x, int n) {
                        long exponent = n;
                        boolean negative = exponent < 0;
                        if (negative) {
                            exponent = -exponent;
                        }

                        Deque<Long> stack = new ArrayDeque<>();
                        while (exponent > 0) {
                            stack.push(exponent);
                            exponent /= 2;
                        }

                        double current = 1.0;
                        while (!stack.isEmpty()) {
                            long value = stack.pop();
                            current *= current;
                            if ((value & 1L) == 1L) {
                                current *= x;
                            }
                        }
                        return negative ? 1.0 / current : current;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Explicit Stack Divide and Conquer Fixture",
                "O(log n)",
                "O(log n)",
                "Push the halving exponent chain, then pop it to rebuild the divide-and-conquer result.",
                "The explicit stack is the recursive fast-power call stack made visible.",
                "- Time Complexity: O(log |n|)\\n- Space Complexity: O(log |n|)",
                code);
    }

