    private static String detectSquaresOppositeCornerSolutionEntryJson() {
        String code = """
                import java.util.*;

                class DetectSquares {
                    private final Map<Long, Integer> counts = new HashMap<>();
                    private final List<int[]> points = new ArrayList<>();
                    public DetectSquares() {}
                    public void add(int[] point) {
                        counts.merge(key(point[0], point[1]), 1, Integer::sum);
                        points.add(new int[] {point[0], point[1]});
                    }
                    public int count(int[] point) {
                        int px = point[0], py = point[1], answer = 0;
                        for (int[] p : points) {
                            int x = p[0], y = p[1];
                            if (Math.abs(px - x) != Math.abs(py - y)) continue;
                            answer += counts.getOrDefault(key(px, y), 0) * counts.getOrDefault(key(x, py), 0);
                        }
                        return answer;
                    }
                    private long key(int x, int y) { return ((long) x << 32) | y; }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Opposite Corner Hash Map Fixture",
                "O(P)",
                "O(P)",
                "Enumerate each inserted point as a possible opposite corner of the query square.",
                "The query and opposite corner force the other two corners, so duplicate counts multiply directly.",
                "- Time Complexity: O(P)\\n- Space Complexity: O(P)",
                code);
    }

    private static String detectSquaresFixedGridSolutionEntryJson() {
        String code = """
                import java.util.*;

                class DetectSquares {
                    private final int[][] grid = new int[1001][1001];
                    private final List<int[]> points = new ArrayList<>();
                    public DetectSquares() {}
                    public void add(int[] point) {
                        grid[point[0]][point[1]]++;
                        points.add(new int[] {point[0], point[1]});
                    }
                    public int count(int[] point) {
                        int px = point[0], py = point[1], answer = 0;
                        for (int[] p : points) {
                            int x = p[0], y = p[1];
                            answer += grid[px][y] * grid[x][py];
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Fixed Coordinate Grid Fixture",
                "O(P)",
                "O(C^2 + P)",
                "Use a fixed grid for direct coordinate counts and enumerate inserted opposite corners.",
                "The bounded coordinate range permits O(1) lookup for each missing square corner.",
                "- Time Complexity: O(P)\\n- Space Complexity: O(C^2 + P)",
                code);
    }

    private static String detectSquaresColumnEnumerationSolutionEntryJson() {
        String code = """
                import java.util.*;

                class DetectSquares {
                    private final Map<Integer, Map<Integer, Integer>> columns = new HashMap<>();
                    public DetectSquares() {}
                    public void add(int[] point) {
                        columns.computeIfAbsent(point[0], key -> new HashMap<>()).merge(point[1], 1, Integer::sum);
                    }
                    public int count(int[] point) {
                        int x = point[0], y = point[1], answer = 0;
                        Map<Integer, Integer> sameColumn = columns.get(x);
                        for (Map.Entry<Integer, Integer> entry : sameColumn.entrySet()) {
                            int otherY = entry.getKey();
                            int verticalCount = entry.getValue();
                            int side = otherY - y;
                            answer += verticalCount * countAt(x + side, y) * countAt(x + side, otherY);
                            answer += verticalCount * countAt(x - side, y) * countAt(x - side, otherY);
                        }
                        return answer;
                    }
                    private int countAt(int x, int y) { return 0; }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Column Map Enumeration Fixture",
                "O(Kx)",
                "O(U)",
                "Group points by x-coordinate and enumerate the query column.",
                "A vertical side from the query point determines the two possible horizontal directions.",
                "- Time Complexity: O(Kx)\\n- Space Complexity: O(U)",
                code);
    }

    private static String detectSquaresRowEnumerationSolutionEntryJson() {
        String code = """
                import java.util.*;

                class DetectSquares {
                    private final Map<Integer, Map<Integer, Integer>> rows = new HashMap<>();
                    public DetectSquares() {}
                    public void add(int[] point) {
                        rows.computeIfAbsent(point[1], key -> new HashMap<>()).merge(point[0], 1, Integer::sum);
                    }
                    public int count(int[] point) {
                        int x = point[0], y = point[1], answer = 0;
                        Map<Integer, Integer> sameRow = rows.get(y);
                        for (Map.Entry<Integer, Integer> entry : sameRow.entrySet()) {
                            int otherX = entry.getKey();
                            int horizontalCount = entry.getValue();
                            int side = otherX - x;
                            answer += horizontalCount * countAt(x, y + side) * countAt(otherX, y + side);
                            answer += horizontalCount * countAt(x, y - side) * countAt(otherX, y - side);
                        }
                        return answer;
                    }
                    private int countAt(int x, int y) { return 0; }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Row Map Enumeration Fixture",
                "O(Ky)",
                "O(U)",
                "Group points by y-coordinate and enumerate the query row.",
                "The row-indexed version is symmetric with column enumeration and checks above and below.",
                "- Time Complexity: O(Ky)\\n- Space Complexity: O(U)",
                code);
    }

    private static String detectSquaresUniqueOppositeSolutionEntryJson() {
        String code = """
                import java.util.*;

                class DetectSquares {
                    private final Map<Long, Integer> counts = new HashMap<>();
                    private final Set<Long> uniquePoints = new HashSet<>();
                    public DetectSquares() {}
                    public void add(int[] point) {
                        long encoded = key(point[0], point[1]);
                        counts.merge(encoded, 1, Integer::sum);
                        uniquePoints.add(encoded);
                    }
                    public int count(int[] point) {
                        int px = point[0], py = point[1], answer = 0;
                        for (long encoded : uniquePoints) {
                            int x = (int) (encoded >> 32), y = (int) encoded;
                            if (Math.abs(px - x) != Math.abs(py - y)) continue;
                            int diagonalCount = counts.get(encoded);
                            answer += diagonalCount * counts.getOrDefault(key(px, y), 0) * counts.getOrDefault(key(x, py), 0);
                        }
                        return answer;
                    }
                    private long key(int x, int y) { return ((long) x << 32) | y; }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Unique Opposite-Corner Enumeration Fixture",
                "O(U)",
                "O(U)",
                "Enumerate distinct coordinates as opposite corners and multiply by each coordinate count.",
                "This counts duplicate opposite corners explicitly instead of visiting repeated list entries.",
                "- Time Complexity: O(U)\\n- Space Complexity: O(U)",
                code);
    }

