    private static String numberOf1BitsBrianSolutionEntryJson() {
        String code = """
                class Solution {
                    public int hammingWeight(int n) {
                        int count = 0;
                        while (n != 0) {
                            n &= (n - 1);
                            count++;
                        }
                        return count;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Brian Kernighan Lowest-Bit Clearing Fixture",
                "O(k)",
                "O(1)",
                "Repeatedly clear the lowest set bit.",
                "The operation n & (n - 1) removes exactly one set bit from the current pattern.",
                "- Time Complexity: O(k)\\n- Space Complexity: O(1)",
                code);
    }

    private static String numberOf1BitsUnsignedShiftSolutionEntryJson() {
        String code = """
                class Solution {
                    public int hammingWeight(int n) {
                        int count = 0;
                        for (int i = 0; i < 32; i++) {
                            count += n & 1;
                            n >>>= 1;
                        }
                        return count;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Unsigned Right-Shift Scan Fixture",
                "O(32)",
                "O(1)",
                "Read the lowest bit and shift the input with unsigned right shift.",
                "Unsigned shifting is required so negative values do not keep filling high bits with ones.",
                "- Time Complexity: O(32)\\n- Space Complexity: O(1)",
                code);
    }

    private static String numberOf1BitsMovingMaskSolutionEntryJson() {
        String code = """
                class Solution {
                    public int hammingWeight(int n) {
                        int count = 0;
                        int mask = 1;
                        for (int i = 0; i < 32; i++) {
                            if ((n & mask) != 0) {
                                count++;
                            }
                            mask <<= 1;
                        }
                        return count;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Moving Mask Check Fixture",
                "O(32)",
                "O(1)",
                "Move a single-bit mask across all 32 positions.",
                "The input remains unchanged, so every two's-complement position including the sign bit is inspected.",
                "- Time Complexity: O(32)\\n- Space Complexity: O(1)",
                code);
    }

    private static String numberOf1BitsByteLookupSolutionEntryJson() {
        String code = """
                class Solution {
                    private static final int[] BYTE_COUNTS = buildTable();

                    public int hammingWeight(int n) {
                        return BYTE_COUNTS[n & 0xff]
                             + BYTE_COUNTS[(n >>> 8) & 0xff]
                             + BYTE_COUNTS[(n >>> 16) & 0xff]
                             + BYTE_COUNTS[(n >>> 24) & 0xff];
                    }

                    private static int[] buildTable() {
                        int[] counts = new int[256];
                        for (int i = 1; i < counts.length; i++) {
                            counts[i] = counts[i >> 1] + (i & 1);
                        }
                        return counts;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Byte Lookup Table Fixture",
                "O(1)",
                "O(1)",
                "Precompute bit counts for every byte and sum four byte lookups.",
                "A fixed 256-entry table reuses the same small subproblem without depending on library shortcuts.",
                "- Time Complexity: O(1)\\n- Space Complexity: O(1)",
                code);
    }

    private static String numberOf1BitsSwarSolutionEntryJson() {
        String code = """
                class Solution {
                    public int hammingWeight(int n) {
                        n = n - ((n >>> 1) & 0x55555555);
                        n = (n & 0x33333333) + ((n >>> 2) & 0x33333333);
                        n = (n + (n >>> 4)) & 0x0f0f0f0f;
                        n = n + (n >>> 8);
                        n = n + (n >>> 16);
                        return n & 0x3f;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "SWAR Parallel Bit Count Fixture",
                "O(1)",
                "O(1)",
                "Combine packed bit counters with masks and shifts.",
                "SWAR treats one register as many small counters and merges those counters in parallel.",
                "- Time Complexity: O(1)\\n- Space Complexity: O(1)",
                code);
    }

