    private static String countingBitsRightShiftSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] countBits(int n) {
                        int[] ans = new int[n + 1];
                        for (int i = 1; i <= n; i++) {
                            ans[i] = ans[i >> 1] + (i & 1);
                        }
                        return ans;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Right-Shift Lowest-Bit DP Fixture",
                "O(n)",
                "O(n)",
                "Build each answer from the already computed answer for i shifted right by one bit.",
                "The removed lowest bit contributes exactly i & 1, so every state depends on a smaller state.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String countingBitsLastSetBitSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] countBits(int n) {
                        int[] ans = new int[n + 1];
                        for (int i = 1; i <= n; i++) {
                            ans[i] = ans[i & (i - 1)] + 1;
                        }
                        return ans;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Last Set Bit DP Fixture",
                "O(n)",
                "O(n)",
                "Clear the lowest set bit once and reuse the table answer for the remaining value.",
                "The expression i & (i - 1) is smaller than i and removes exactly one set bit.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String countingBitsHighestPowerSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] countBits(int n) {
                        int[] ans = new int[n + 1];
                        int highestPowerOfTwo = 0;
                        for (int i = 1; i <= n; i++) {
                            if ((i & (i - 1)) == 0) {
                                highestPowerOfTwo = i;
                            }
                            ans[i] = ans[i - highestPowerOfTwo] + 1;
                        }
                        return ans;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Highest Power Offset DP Fixture",
                "O(n)",
                "O(n)",
                "Track the highest power of two and reuse the offset inside the current block.",
                "The high bit contributes one count and the suffix repeats an already computed prefix block.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String countingBitsPowerBlockSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] countBits(int n) {
                        int[] ans = new int[n + 1];
                        int offset = 1;
                        while (offset <= n) {
                            for (int i = 0; i < offset && i + offset <= n; i++) {
                                ans[i + offset] = ans[i] + 1;
                            }
                            offset <<= 1;
                        }
                        return ans;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Power-of-Two Block Copy Fixture",
                "O(n)",
                "O(n)",
                "Copy each completed power-of-two block into the next block with one added high bit.",
                "The next block repeats the previous block's bit counts because every value gains the same leading one.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String countingBitsKernighanSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] countBits(int n) {
                        int[] ans = new int[n + 1];
                        for (int i = 1; i <= n; i++) {
                            int x = i;
                            int count = 0;
                            while (x != 0) {
                                x &= (x - 1);
                                count++;
                            }
                            ans[i] = count;
                        }
                        return ans;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Kernighan Per-Number Baseline Fixture",
                "O(n log n)",
                "O(n)",
                "Count each number independently by repeatedly clearing its lowest set bit.",
                "This baseline shows the cost of not reusing table states, making the DP improvement visible.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

