    private static String reverseBitsAccumulatorSolutionEntryJson() {
        String code = """
                class Solution {
                    public int reverseBits(int n) {
                        int result = 0;
                        for (int i = 0; i < 32; i++) {
                            result = (result << 1) | (n & 1);
                            n >>>= 1;
                        }
                        return result;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Bit-by-Bit Shift Accumulator Fixture",
                "O(32)",
                "O(1)",
                "Shift the result left and append the current lowest source bit.",
                "The first source bit read becomes the highest target bit, and unsigned shift exposes negative inputs correctly.",
                "- Time Complexity: O(32)\\n- Space Complexity: O(1)",
                code);
    }

    private static String reverseBitsMaskSwapSolutionEntryJson() {
        String code = """
                class Solution {
                    public int reverseBits(int n) {
                        n = ((n & 0x55555555) << 1) | ((n >>> 1) & 0x55555555);
                        n = ((n & 0x33333333) << 2) | ((n >>> 2) & 0x33333333);
                        n = ((n & 0x0f0f0f0f) << 4) | ((n >>> 4) & 0x0f0f0f0f);
                        n = ((n & 0x00ff00ff) << 8) | ((n >>> 8) & 0x00ff00ff);
                        n = (n << 16) | (n >>> 16);
                        return n;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Mask Swap Divide and Conquer Fixture",
                "O(1)",
                "O(1)",
                "Swap adjacent bit groups with masks from small groups up to half words.",
                "Repeated symmetric exchanges move every bit to its mirrored position without a 32-step loop.",
                "- Time Complexity: O(1)\\n- Space Complexity: O(1)",
                code);
    }

    private static String reverseBitsByteLookupSolutionEntryJson() {
        String code = """
                class Solution {
                    private static final int[] BYTE_REVERSE = buildTable();

                    public int reverseBits(int n) {
                        return (BYTE_REVERSE[n & 0xff] << 24)
                                | (BYTE_REVERSE[(n >>> 8) & 0xff] << 16)
                                | (BYTE_REVERSE[(n >>> 16) & 0xff] << 8)
                                | BYTE_REVERSE[(n >>> 24) & 0xff];
                    }

                    private static int[] buildTable() {
                        int[] table = new int[256];
                        for (int value = 0; value < table.length; value++) {
                            int x = value;
                            int reversed = 0;
                            for (int i = 0; i < 8; i++) {
                                reversed = (reversed << 1) | (x & 1);
                                x >>>= 1;
                            }
                            table[value] = reversed;
                        }
                        return table;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Byte Lookup Table Fixture",
                "O(1)",
                "O(1)",
                "Precompute reverse values for every byte and assemble the four reversed bytes in opposite order.",
                "The same eight-bit reversal subproblem repeats, so a fixed table makes the repeated work explicit.",
                "- Time Complexity: O(1)\\n- Space Complexity: O(1)",
                code);
    }

    private static String reverseBitsOppositeMaskSolutionEntryJson() {
        String code = """
                class Solution {
                    public int reverseBits(int n) {
                        int result = 0;
                        int sourceMask = 1;
                        int targetMask = 1 << 31;
                        for (int i = 0; i < 32; i++) {
                            if ((n & sourceMask) != 0) {
                                result |= targetMask;
                            }
                            sourceMask <<= 1;
                            targetMask >>>= 1;
                        }
                        return result;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Opposite Mask Assembly Fixture",
                "O(32)",
                "O(1)",
                "Scan source bits from low to high while writing target bits from high to low.",
                "This route teaches the exact position mapping from input bit i to output bit 31 - i.",
                "- Time Complexity: O(32)\\n- Space Complexity: O(1)",
                code);
    }

    private static String reverseBitsRecursiveHalfSolutionEntryJson() {
        String code = """
                class Solution {
                    public int reverseBits(int n) {
                        return reverse(n, 32);
                    }

                    private int reverse(int value, int width) {
                        if (width == 1) {
                            return value & 1;
                        }
                        int half = width >>> 1;
                        int mask = (1 << half) - 1;
                        int low = value & mask;
                        int high = value >>> half;
                        return (reverse(low, half) << half) | reverse(high, half);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Recursive Half Reversal Fixture",
                "O(32)",
                "O(1)",
                "Split the current bit range into halves, reverse both halves, and swap their order.",
                "Recursive half reversal is the structural form of divide and conquer used by mask swapping.",
                "- Time Complexity: O(32)\\n- Space Complexity: O(1)",
                code);
    }

