    private static String romanToIntegerLeftToRightSolutionEntryJson() {
        String code = """
                class Solution {
                    public int romanToInt(String s) {
                        int result = 0;
                        for (int i = 0; i < s.length(); i++) {
                            int current = valueOf(s.charAt(i));
                            if (i + 1 < s.length() && current < valueOf(s.charAt(i + 1))) {
                                result -= current;
                            } else {
                                result += current;
                            }
                        }
                        return result;
                    }

                    private int valueOf(char c) {
                        if (c == 'I') return 1;
                        if (c == 'V') return 5;
                        if (c == 'X') return 10;
                        if (c == 'L') return 50;
                        if (c == 'C') return 100;
                        if (c == 'D') return 500;
                        return 1000;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Left-to-Right Lookahead Fixture",
                "O(n)",
                "O(1)",
                "Compare each symbol with the next one and subtract only when the next value is larger.",
                "The immediate larger neighbor captures every valid Roman subtractive form.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String romanToIntegerRightToLeftSolutionEntryJson() {
        String code = """
                class Solution {
                    public int romanToInt(String s) {
                        int result = 0;
                        int previous = 0;
                        for (int i = s.length() - 1; i >= 0; i--) {
                            int current = valueOf(s.charAt(i));
                            if (current < previous) {
                                result -= current;
                            } else {
                                result += current;
                                previous = current;
                            }
                        }
                        return result;
                    }

                    private int valueOf(char c) {
                        if (c == 'I') return 1;
                        if (c == 'V') return 5;
                        if (c == 'X') return 10;
                        if (c == 'L') return 50;
                        if (c == 'C') return 100;
                        if (c == 'D') return 500;
                        return 1000;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Right-to-Left Previous Maximum Fixture",
                "O(n)",
                "O(1)",
                "Scan from the right and subtract any value smaller than the right-side value.",
                "Reading right to left turns the subtractive rule into a stable previous-maximum invariant.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String romanToIntegerPreviousCorrectionSolutionEntryJson() {
        String code = """
                class Solution {
                    public int romanToInt(String s) {
                        int total = 0;
                        int previous = 0;
                        for (int i = 0; i < s.length(); i++) {
                            int current = valueOf(s.charAt(i));
                            total += current;
                            if (previous < current) {
                                total -= 2 * previous;
                            }
                            previous = current;
                        }
                        return total;
                    }

                    private int valueOf(char c) {
                        if (c == 'I') return 1;
                        if (c == 'V') return 5;
                        if (c == 'X') return 10;
                        if (c == 'L') return 50;
                        if (c == 'C') return 100;
                        if (c == 'D') return 500;
                        return 1000;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Previous-Symbol Correction Fixture",
                "O(n)",
                "O(1)",
                "Add every symbol first, then correct a subtractive pair by subtracting twice the previous value.",
                "The correction changes plus previous into minus previous with one local adjustment.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String romanToIntegerExplicitPairsSolutionEntryJson() {
        String code = """
                class Solution {
                    public int romanToInt(String s) {
                        int total = 0;
                        int i = 0;
                        while (i < s.length()) {
                            if (i + 1 < s.length()) {
                                String pair = s.substring(i, i + 2);
                                if (pair.equals("IV")) { total += 4; i += 2; continue; }
                                if (pair.equals("IX")) { total += 9; i += 2; continue; }
                                if (pair.equals("XL")) { total += 40; i += 2; continue; }
                                if (pair.equals("XC")) { total += 90; i += 2; continue; }
                                if (pair.equals("CD")) { total += 400; i += 2; continue; }
                                if (pair.equals("CM")) { total += 900; i += 2; continue; }
                            }
                            total += valueOf(s.charAt(i));
                            i++;
                        }
                        return total;
                    }

                    private int valueOf(char c) {
                        if (c == 'I') return 1;
                        if (c == 'V') return 5;
                        if (c == 'X') return 10;
                        if (c == 'L') return 50;
                        if (c == 'C') return 100;
                        if (c == 'D') return 500;
                        return 1000;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Explicit Subtractive Pair Scan Fixture",
                "O(n)",
                "O(1)",
                "Check the six legal subtractive pairs before falling back to a single-symbol value.",
                "Listing IV, IX, XL, XC, CD, and CM directly exposes the Roman grammar.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

