    private static String integerToRomanPlaceGrammarSolutionEntryJson() {
        String code = """
                class Solution {
                    public String intToRoman(int num) {
                        StringBuilder result = new StringBuilder();
                        appendRepeat(result, 'M', num / 1000);
                        appendDigit(result, (num / 100) % 10, 'C', 'D', 'M');
                        appendDigit(result, (num / 10) % 10, 'X', 'L', 'C');
                        appendDigit(result, num % 10, 'I', 'V', 'X');
                        return result.toString();
                    }

                    private void appendDigit(StringBuilder result, int digit, char one, char five, char ten) {
                        if (digit == 9) {
                            result.append(one).append(ten);
                        } else if (digit >= 5) {
                            result.append(five);
                            appendRepeat(result, one, digit - 5);
                        } else if (digit == 4) {
                            result.append(one).append(five);
                        } else {
                            appendRepeat(result, one, digit);
                        }
                    }

                    private void appendRepeat(StringBuilder result, char symbol, int count) {
                        for (int i = 0; i < count; i++) {
                            result.append(symbol);
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Place-Value Grammar Builder Fixture",
                "O(1)",
                "O(1)",
                "Render each decimal place from its one, five, and ten symbols using the same digit grammar.",
                "The ones, tens, and hundreds places share the same cases for 4, 9, 5 through 8, and 0 through 3.",
                "- Time Complexity: O(1)\\n- Space Complexity: O(1)",
                code);
    }

    private static String integerToRomanAdditiveCompressionSolutionEntryJson() {
        String code = """
                class Solution {
                    public String intToRoman(int num) {
                        StringBuilder additive = new StringBuilder();
                        num = appendChunk(additive, num, 1000, "M");
                        num = appendChunk(additive, num, 500, "D");
                        num = appendChunk(additive, num, 100, "C");
                        num = appendChunk(additive, num, 50, "L");
                        num = appendChunk(additive, num, 10, "X");
                        num = appendChunk(additive, num, 5, "V");
                        appendChunk(additive, num, 1, "I");

                        return additive.toString()
                                .replace("DCCCC", "CM")
                                .replace("CCCC", "CD")
                                .replace("LXXXX", "XC")
                                .replace("XXXX", "XL")
                                .replace("VIIII", "IX")
                                .replace("IIII", "IV");
                    }

                    private int appendChunk(StringBuilder builder, int num, int value, String symbol) {
                        int count = num / value;
                        for (int i = 0; i < count; i++) {
                            builder.append(symbol);
                        }
                        return num % value;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Additive Expansion then Canonical Compression Fixture",
                "O(1)",
                "O(1)",
                "Write a temporary additive Roman spelling and compress the six noncanonical patterns.",
                "Subtractive notation is a canonical compression rule layered over additive Roman notation.",
                "- Time Complexity: O(1)\\n- Space Complexity: O(1)",
                code);
    }

