    private static String longestCommonPrefixHorizontalSolutionEntryJson() {
        String code = """
                class Solution {
                    public String longestCommonPrefix(String[] strs) {
                        String prefix = strs[0];
                        for (int i = 1; i < strs.length; i++) {
                            while (!strs[i].startsWith(prefix)) {
                                prefix = prefix.substring(0, prefix.length() - 1);
                                if (prefix.isEmpty()) {
                                    return "";
                                }
                            }
                        }
                        return prefix;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Horizontal Prefix Shrinking Fixture",
                "O(S)",
                "O(1)",
                "Shrink the current candidate prefix until each next string accepts it.",
                "After each processed string, the candidate is exactly the longest common prefix of that prefix of the array.",
                "- Time Complexity: O(S)\\n- Space Complexity: O(1)",
                code);
    }

    private static String longestCommonPrefixVerticalSolutionEntryJson() {
        String code = """
                class Solution {
                    public String longestCommonPrefix(String[] strs) {
                        String first = strs[0];
                        for (int i = 0; i < first.length(); i++) {
                            char expected = first.charAt(i);
                            for (int j = 1; j < strs.length; j++) {
                                if (i == strs[j].length() || strs[j].charAt(i) != expected) {
                                    return first.substring(0, i);
                                }
                            }
                        }
                        return first;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Vertical Character Scan Fixture",
                "O(S)",
                "O(1)",
                "Scan one character position across every string before moving to the next position.",
                "The first column mismatch proves the exact answer length because all earlier columns already matched.",
                "- Time Complexity: O(S)\\n- Space Complexity: O(1)",
                code);
    }

    private static String longestCommonPrefixDivideSolutionEntryJson() {
        String code = """
                class Solution {
                    public String longestCommonPrefix(String[] strs) {
                        return longestCommonPrefix(strs, 0, strs.length - 1);
                    }

                    private String longestCommonPrefix(String[] strs, int left, int right) {
                        if (left == right) {
                            return strs[left];
                        }
                        int mid = left + (right - left) / 2;
                        String leftPrefix = longestCommonPrefix(strs, left, mid);
                        String rightPrefix = longestCommonPrefix(strs, mid + 1, right);
                        return commonPrefix(leftPrefix, rightPrefix);
                    }

                    private String commonPrefix(String a, String b) {
                        int limit = Math.min(a.length(), b.length());
                        int i = 0;
                        while (i < limit && a.charAt(i) == b.charAt(i)) {
                            i++;
                        }
                        return a.substring(0, i);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Divide and Conquer Merge Fixture",
                "O(S)",
                "O(log n)",
                "Split the array, solve each half, and merge the two resulting prefixes.",
                "The common prefix of the whole array is the common prefix of the two half-prefixes.",
                "- Time Complexity: O(S)\\n- Space Complexity: O(log n)",
                code);
    }

    private static String longestCommonPrefixBinarySolutionEntryJson() {
        String code = """
                class Solution {
                    public String longestCommonPrefix(String[] strs) {
                        int minLength = Integer.MAX_VALUE;
                        for (String word : strs) {
                            minLength = Math.min(minLength, word.length());
                        }

                        int low = 0;
                        int high = minLength;
                        while (low < high) {
                            int mid = low + (high - low + 1) / 2;
                            if (isCommonPrefix(strs, mid)) {
                                low = mid;
                            } else {
                                high = mid - 1;
                            }
                        }
                        return strs[0].substring(0, low);
                    }

                    private boolean isCommonPrefix(String[] strs, int length) {
                        String prefix = strs[0].substring(0, length);
                        for (int i = 1; i < strs.length; i++) {
                            if (!strs[i].startsWith(prefix)) {
                                return false;
                            }
                        }
                        return true;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Binary Search on Prefix Length Fixture",
                "O(S log m)",
                "O(1)",
                "Binary search the answer length and test whether every string shares that prefix.",
                "Prefix validity is monotonic by length: once a length fails, every longer length fails too.",
                "- Time Complexity: O(S log m)\\n- Space Complexity: O(1)",
                code);
    }

    private static String longestCommonPrefixTrieSolutionEntryJson() {
        String code = """
                class Solution {
                    private static class Node {
                        Node[] children = new Node[26];
                        int childCount;
                        boolean terminal;
                    }

                    public String longestCommonPrefix(String[] strs) {
                        Node root = new Node();
                        for (String word : strs) {
                            insert(root, word);
                        }

                        StringBuilder prefix = new StringBuilder();
                        Node node = root;
                        while (node.childCount == 1 && !node.terminal) {
                            for (int i = 0; i < 26; i++) {
                                if (node.children[i] != null) {
                                    prefix.append((char) ('a' + i));
                                    node = node.children[i];
                                    break;
                                }
                            }
                        }
                        return prefix.toString();
                    }

                    private void insert(Node root, String word) {
                        Node node = root;
                        for (int i = 0; i < word.length(); i++) {
                            int index = word.charAt(i) - 'a';
                            if (node.children[index] == null) {
                                node.children[index] = new Node();
                                node.childCount++;
                            }
                            node = node.children[index];
                        }
                        node.terminal = true;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Trie Single-Branch Walk Fixture",
                "O(S)",
                "O(S)",
                "Insert every word into a trie, then follow the only branch until a split or word ending appears.",
                "A shared prefix corresponds to forced trie edges; a branch or terminal node is the exact stopping point.",
                "- Time Complexity: O(S)\\n- Space Complexity: O(S)",
                code);
    }

