    private static String removeDuplicatesSortedListAdjacentSkipSolutionEntryJson() {
        String code = """
                class Solution {
                    public ListNode deleteDuplicates(ListNode head) {
                        ListNode curr = head;
                        while (curr != null && curr.next != null) {
                            if (curr.val == curr.next.val) {
                                curr.next = curr.next.next;
                            } else {
                                curr = curr.next;
                            }
                        }
                        return head;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "In-Place Adjacent Skip Fixture",
                "O(n)",
                "O(1)",
                "Walk through the sorted list and skip the next node whenever it repeats the current value.",
                "All duplicates are adjacent, so the current kept node can delete every equal successor before moving on.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String removeDuplicatesSortedListRunEndRelinkSolutionEntryJson() {
        String code = """
                class Solution {
                    public ListNode deleteDuplicates(ListNode head) {
                        ListNode sentinel = new ListNode(0);
                        ListNode tail = sentinel;
                        ListNode read = head;

                        while (read != null) {
                            tail.next = read;
                            tail = read;
                            int value = read.val;
                            while (read != null && read.val == value) {
                                read = read.next;
                            }
                        }

                        tail.next = null;
                        return sentinel.next;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Run-End Relink with Sentinel Tail Fixture",
                "O(n)",
                "O(1)",
                "Attach one representative from each equal-value run to a sentinel-backed answer tail.",
                "A sorted run contributes exactly one node, and the final tail cut prevents stale duplicate links.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String removeDuplicatesSortedListRecursiveCleanupSolutionEntryJson() {
        String code = """
                class Solution {
                    public ListNode deleteDuplicates(ListNode head) {
                        if (head == null || head.next == null) {
                            return head;
                        }
                        head.next = deleteDuplicates(head.next);
                        return head.val == head.next.val ? head.next : head;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Recursive Suffix Cleanup Fixture",
                "O(n)",
                "O(n)",
                "Recursively deduplicate the suffix, then compare the current head with the cleaned suffix head.",
                "After the recursive call, the only possible duplicate of head is the first node of the cleaned suffix.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String removeDuplicatesSortedListFreshRebuildSolutionEntryJson() {
        String code = """
                class Solution {
                    public ListNode deleteDuplicates(ListNode head) {
                        ListNode dummy = new ListNode(0);
                        ListNode tail = dummy;
                        boolean first = true;
                        int last = 0;
                        ListNode read = head;

                        while (read != null) {
                            if (first || read.val != last) {
                                tail.next = new ListNode(read.val);
                                tail = tail.next;
                                last = read.val;
                                first = false;
                            }
                            read = read.next;
                        }
                        return dummy.next;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Fresh Unique List Rebuild Fixture",
                "O(n)",
                "O(k)",
                "Build a new list and append a node only when the scanned value differs from the last kept value.",
                "Rebuilding separates value filtering from original pointer mutation, while sorted order makes one comparison enough.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(k)",
                code);
    }

    private static String removeDuplicatesSortedListValueCompactionSolutionEntryJson() {
        String code = """
                class Solution {
                    public ListNode deleteDuplicates(ListNode head) {
                        if (head == null) {
                            return null;
                        }

                        ListNode write = head;
                        ListNode read = head.next;
                        int last = head.val;

                        while (read != null) {
                            if (read.val != last) {
                                write = write.next;
                                write.val = read.val;
                                last = read.val;
                            }
                            read = read.next;
                        }

                        write.next = null;
                        return head;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Two-Pointer Value Compaction Fixture",
                "O(n)",
                "O(1)",
                "Use the first nodes as write slots and copy each newly discovered value into the next write slot.",
                "This mirrors array-style compaction and must truncate after the last written node to hide stale duplicates.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

