    private static String removeDuplicatesSortedListIIRecursiveGroupRemovalSolutionEntryJson() {
        String code = """
                class Solution {
                    public ListNode deleteDuplicates(ListNode head) {
                        if (head == null || head.next == null) {
                            return head;
                        }

                        if (head.val == head.next.val) {
                            int value = head.val;
                            while (head != null && head.val == value) {
                                head = head.next;
                            }
                            return deleteDuplicates(head);
                        }

                        head.next = deleteDuplicates(head.next);
                        return head;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Recursive Duplicate Group Removal Fixture",
                "O(n)",
                "O(n)",
                "Recursively remove an entire duplicate group or keep a singleton head and clean its suffix.",
                "The duplicate branch must skip every node with the repeated value before recursing.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String removeDuplicatesSortedListIIFrequencyMapRebuildSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public ListNode deleteDuplicates(ListNode head) {
                        Map<Integer, Integer> counts = new HashMap<>();
                        for (ListNode node = head; node != null; node = node.next) {
                            counts.merge(node.val, 1, Integer::sum);
                        }

                        ListNode dummy = new ListNode(0);
                        ListNode tail = dummy;
                        for (ListNode node = head; node != null; node = node.next) {
                            if (counts.get(node.val) == 1) {
                                tail.next = new ListNode(node.val);
                                tail = tail.next;
                            }
                        }
                        return dummy.next;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Frequency Map Rebuild Fixture",
                "O(n)",
                "O(n)",
                "Count every value first, then rebuild a list containing only values with frequency one.",
                "This directly encodes the global uniqueness rule and avoids subtle in-place predecessor cases.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String removeDuplicatesSortedListIISingletonValueCompactionSolutionEntryJson() {
        String code = """
                class Solution {
                    public ListNode deleteDuplicates(ListNode head) {
                        if (head == null) {
                            return null;
                        }

                        ListNode write = head;
                        boolean wrote = false;
                        ListNode read = head;

                        while (read != null) {
                            int value = read.val;
                            int count = 0;
                            while (read != null && read.val == value) {
                                count++;
                                read = read.next;
                            }
                            if (count == 1) {
                                if (!wrote) {
                                    write = head;
                                    wrote = true;
                                } else {
                                    write = write.next;
                                }
                                write.val = value;
                            }
                        }

                        if (!wrote) {
                            return null;
                        }
                        write.next = null;
                        return head;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Two-Pointer Singleton Value Compaction Fixture",
                "O(n)",
                "O(1)",
                "Reuse early nodes as write slots and copy only singleton run values into the output prefix.",
                "The wrote flag distinguishes no-survivor input from an output list whose first value is copied into head.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

