    private static String countAndSayRunLengthTokenPipelineSolutionEntryJson() {
        String code = """
                import java.util.ArrayList;
                import java.util.List;

                class Solution {
                    public String countAndSay(int n) {
                        List<Run> runs = new ArrayList<>();
                        runs.add(new Run('1', 1));

                        for (int step = 2; step <= n; step++) {
                            List<Character> spoken = new ArrayList<>();
                            for (Run run : runs) {
                                String count = Integer.toString(run.count);
                                for (int i = 0; i < count.length(); i++) {
                                    spoken.add(count.charAt(i));
                                }
                                spoken.add(run.digit);
                            }
                            runs = compress(spoken);
                        }

                        StringBuilder answer = new StringBuilder();
                        for (Run run : runs) {
                            for (int i = 0; i < run.count; i++) {
                                answer.append(run.digit);
                            }
                        }
                        return answer.toString();
                    }

                    private List<Run> compress(List<Character> chars) {
                        List<Run> result = new ArrayList<>();
                        int index = 0;
                        while (index < chars.size()) {
                            char digit = chars.get(index);
                            int count = 0;
                            while (index < chars.size() && chars.get(index) == digit) {
                                index++;
                                count++;
                            }
                            result.add(new Run(digit, count));
                        }
                        return result;
                    }

                    private static class Run {
                        final char digit;
                        final int count;

                        Run(char digit, int count) {
                            this.digit = digit;
                            this.count = count;
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Run-Length Token Pipeline Fixture",
                "O(T_n)",
                "O(L_n)",
                "Keep the current term as run tokens, speak those tokens into characters, then compress again.",
                "Separating token speaking from token compression avoids assuming that a count always has one digit.",
                "- Time Complexity: O(T_n)\\n- Space Complexity: O(L_n)",
                code);
    }

    private static String countAndSayStaticSequenceCacheSolutionEntryJson() {
        String code = """
                class Solution {
                    private static final String[] CACHE = buildCache();

                    public String countAndSay(int n) {
                        return CACHE[n];
                    }

                    private static String[] buildCache() {
                        String[] cache = new String[31];
                        cache[1] = "1";
                        for (int n = 2; n <= 30; n++) {
                            cache[n] = say(cache[n - 1]);
                        }
                        return cache;
                    }

                    private static String say(String term) {
                        StringBuilder next = new StringBuilder();
                        int start = 0;
                        while (start < term.length()) {
                            int end = start + 1;
                            while (end < term.length() && term.charAt(end) == term.charAt(start)) {
                                end++;
                            }
                            next.append(end - start).append(term.charAt(start));
                            start = end;
                        }
                        return next.toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Static Sequence Cache Fixture",
                "O(1)",
                "O(T_30)",
                "Precompute all valid terms under the n <= 30 constraint and answer by indexing a cache.",
                "A fixed problem bound makes cache construction small and turns repeated lookups into direct reads.",
                "- Time Complexity: O(1) per call after O(T_30) initialization\\n- Space Complexity: O(T_30)",
                code);
    }

