    private static String lengthOfLastWordReverseBoundaryScanSolutionEntryJson() {
        String code = """
                class Solution {
                    public int lengthOfLastWord(String s) {
                        int i = s.length() - 1;
                        while (i >= 0 && s.charAt(i) == ' ') {
                            i--;
                        }
                        int end = i;
                        while (i >= 0 && s.charAt(i) != ' ') {
                            i--;
                        }
                        return end - i;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Reverse Boundary Scan Fixture",
                "O(n)",
                "O(1)",
                "Skip trailing spaces from the right, then count the final maximal non-space block.",
                "The last word is the first non-space block reached when scanning left from the string end.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String lengthOfLastWordForwardStateMachineSolutionEntryJson() {
        String code = """
                class Solution {
                    public int lengthOfLastWord(String s) {
                        int current = 0;
                        int last = 0;
                        for (int i = 0; i < s.length(); i++) {
                            if (s.charAt(i) == ' ') {
                                if (current > 0) {
                                    last = current;
                                    current = 0;
                                }
                            } else {
                                current++;
                            }
                        }
                        return current > 0 ? current : last;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Forward Word-Length State Machine Fixture",
                "O(n)",
                "O(1)",
                "Track the active word length and remember the last completed word while scanning left to right.",
                "A trailing-space suffix is handled because the most recent completed word length is stored.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

