    private static String addBinaryReverseAppendSolutionEntryJson() {
        String code = """
                class Solution {
                    public String addBinary(String a, String b) {
                        StringBuilder reversed = new StringBuilder();
                        int i = a.length() - 1;
                        int j = b.length() - 1;
                        int carry = 0;

                        while (i >= 0 || j >= 0 || carry > 0) {
                            int sum = carry;
                            if (i >= 0) {
                                sum += a.charAt(i--) - '0';
                            }
                            if (j >= 0) {
                                sum += b.charAt(j--) - '0';
                            }
                            reversed.append((char) ('0' + (sum & 1)));
                            carry = sum >> 1;
                        }

                        return reversed.reverse().toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Reverse Append Carry Simulation Fixture",
                "O(max(m, n))",
                "O(max(m, n))",
                "Scan both strings from right to left, append each low-to-high result bit, then reverse once.",
                "Missing digits act like zero and the final carry is itself another output column.",
                "- Time Complexity: O(max(m, n))\\n- Space Complexity: O(max(m, n))",
                code);
    }

    private static String addBinaryFixedBufferSolutionEntryJson() {
        String code = """
                class Solution {
                    public String addBinary(String a, String b) {
                        int i = a.length() - 1;
                        int j = b.length() - 1;
                        int carry = 0;
                        char[] buffer = new char[Math.max(a.length(), b.length()) + 1];
                        int write = buffer.length - 1;

                        while (i >= 0 || j >= 0 || carry > 0) {
                            int sum = carry;
                            if (i >= 0) {
                                sum += a.charAt(i--) - '0';
                            }
                            if (j >= 0) {
                                sum += b.charAt(j--) - '0';
                            }
                            buffer[write--] = (char) ('0' + (sum % 2));
                            carry = sum / 2;
                        }

                        return new String(buffer, write + 1, buffer.length - write - 1);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Fixed Buffer from the Back Fixture",
                "O(max(m, n))",
                "O(max(m, n))",
                "Write result bits from the back of a preallocated max length plus one buffer.",
                "The final binary sum can be at most one bit longer than the longer input.",
                "- Time Complexity: O(max(m, n))\\n- Space Complexity: O(max(m, n))",
                code);
    }

    private static String addBinaryDequeFrontAssemblySolutionEntryJson() {
        String code = """
                import java.util.ArrayDeque;

                class Solution {
                    public String addBinary(String a, String b) {
                        ArrayDeque<Character> digits = new ArrayDeque<>();
                        int i = a.length() - 1;
                        int j = b.length() - 1;
                        int carry = 0;

                        while (i >= 0 || j >= 0 || carry != 0) {
                            int sum = carry;
                            if (i >= 0) {
                                sum += a.charAt(i--) - '0';
                            }
                            if (j >= 0) {
                                sum += b.charAt(j--) - '0';
                            }
                            digits.addFirst((char) ('0' + (sum & 1)));
                            carry = sum >> 1;
                        }

                        StringBuilder answer = new StringBuilder(digits.size());
                        while (!digits.isEmpty()) {
                            answer.append(digits.removeFirst());
                        }
                        return answer.toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Deque Front Assembly Fixture",
                "O(max(m, n))",
                "O(max(m, n))",
                "Push each computed result bit to the front of a deque, then drain it in output order.",
                "A deque avoids StringBuilder front-insertion shifts while keeping the front-assembly model.",
                "- Time Complexity: O(max(m, n))\\n- Space Complexity: O(max(m, n))",
                code);
    }

    private static String addBinaryTruthTableCarryStateSolutionEntryJson() {
        String code = """
                class Solution {
                    private static final char[] OUT_BIT = {'0', '1', '1', '0', '1', '0', '0', '1'};
                    private static final int[] NEXT_CARRY = {0, 0, 0, 1, 0, 1, 1, 1};

                    public String addBinary(String a, String b) {
                        StringBuilder reversed = new StringBuilder();
                        int i = a.length() - 1;
                        int j = b.length() - 1;
                        int carry = 0;

                        while (i >= 0 || j >= 0 || carry != 0) {
                            int bitA = i >= 0 ? a.charAt(i--) - '0' : 0;
                            int bitB = j >= 0 ? b.charAt(j--) - '0' : 0;
                            int state = (bitA << 2) | (bitB << 1) | carry;
                            reversed.append(OUT_BIT[state]);
                            carry = NEXT_CARRY[state];
                        }

                        return reversed.reverse().toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Truth Table Carry State Fixture",
                "O(max(m, n))",
                "O(max(m, n))",
                "Encode bitA, bitB, and carry as an eight-state lookup for output bit and next carry.",
                "Binary addition has only eight column states, so the carry transition can be made explicit.",
                "- Time Complexity: O(max(m, n))\\n- Space Complexity: O(max(m, n))",
                code);
    }

    private static String addBinaryStackPopSimulationSolutionEntryJson() {
        String code = """
                import java.util.ArrayDeque;

                class Solution {
                    public String addBinary(String a, String b) {
                        ArrayDeque<Integer> first = new ArrayDeque<>();
                        ArrayDeque<Integer> second = new ArrayDeque<>();
                        for (int i = 0; i < a.length(); i++) {
                            first.push(a.charAt(i) - '0');
                        }
                        for (int i = 0; i < b.length(); i++) {
                            second.push(b.charAt(i) - '0');
                        }

                        StringBuilder reversed = new StringBuilder();
                        int carry = 0;
                        while (!first.isEmpty() || !second.isEmpty() || carry != 0) {
                            int sum = carry;
                            if (!first.isEmpty()) {
                                sum += first.pop();
                            }
                            if (!second.isEmpty()) {
                                sum += second.pop();
                            }
                            reversed.append((char) ('0' + (sum % 2)));
                            carry = sum / 2;
                        }
                        return reversed.reverse().toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Stack Pop Simulation Fixture",
                "O(max(m, n))",
                "O(m + n)",
                "Push both strings into stacks, pop least significant bits first, and simulate carry addition.",
                "The stack representation makes the right-to-left processing order explicit.",
                "- Time Complexity: O(max(m, n))\\n- Space Complexity: O(m + n)",
                code);
    }

