    private static String pascalTriangleIIOneRowBackwardDpSolutionEntryJson() {
        String code = """
                import java.util.List;
                import java.util.ArrayList;

                class Solution {
                    public List<Integer> getRow(int rowIndex) {
                        List<Integer> row = new ArrayList<>();
                        for (int i = 0; i <= rowIndex; i++) {
                            row.add(1);
                            for (int j = i - 1; j > 0; j--) {
                                row.set(j, row.get(j) + row.get(j - 1));
                            }
                        }
                        return row;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "One-Row Backward Dynamic Programming Fixture",
                "O(n^2)",
                "O(n)",
                "Keep one mutable row list and update each new row from right to left.",
                "Backward order preserves the previous row's values until each recurrence has read them.",
                "- Time Complexity: O(n^2)\\n- Space Complexity: O(n)",
                code);
    }

    private static String pascalTriangleIIRollingPreviousRowSolutionEntryJson() {
        String code = """
                import java.util.List;
                import java.util.ArrayList;

                class Solution {
                    public List<Integer> getRow(int rowIndex) {
                        List<Integer> previous = new ArrayList<>();
                        previous.add(1);

                        for (int row = 1; row <= rowIndex; row++) {
                            List<Integer> current = new ArrayList<>();
                            current.add(1);
                            for (int col = 1; col < row; col++) {
                                current.add(previous.get(col - 1) + previous.get(col));
                            }
                            current.add(1);
                            previous = current;
                        }
                        return previous;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Rolling Previous Row Fixture",
                "O(n^2)",
                "O(n)",
                "Construct each row from the previous row while discarding older rows.",
                "Keeping the previous row immutable during construction makes the Pascal recurrence explicit.",
                "- Time Complexity: O(n^2)\\n- Space Complexity: O(n)",
                code);
    }

    private static String pascalTriangleIICoefficientRecurrenceSolutionEntryJson() {
        String code = """
                import java.util.List;
                import java.util.ArrayList;

                class Solution {
                    public List<Integer> getRow(int rowIndex) {
                        List<Integer> row = new ArrayList<>();
                        long value = 1;
                        for (int k = 0; k <= rowIndex; k++) {
                            row.add((int) value);
                            value = value * (rowIndex - k) / (k + 1);
                        }
                        return row;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Combinatorial Coefficient Recurrence Fixture",
                "O(n)",
                "O(n)",
                "Generate binomial coefficients with the recurrence from one coefficient to the next.",
                "Pascal row n equals the coefficients C(n, k), so factorials and quadratic DP are unnecessary.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String pascalTriangleIISymmetricCoefficientFillSolutionEntryJson() {
        String code = """
                import java.util.List;
                import java.util.ArrayList;

                class Solution {
                    public List<Integer> getRow(int rowIndex) {
                        List<Integer> row = new ArrayList<>();
                        for (int i = 0; i <= rowIndex; i++) {
                            row.add(0);
                        }

                        long value = 1;
                        for (int k = 0; k <= rowIndex / 2; k++) {
                            int coefficient = (int) value;
                            row.set(k, coefficient);
                            row.set(rowIndex - k, coefficient);
                            value = value * (rowIndex - k) / (k + 1);
                        }
                        return row;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Symmetric Coefficient Fill Fixture",
                "O(n)",
                "O(n)",
                "Compute coefficients through the middle and write each value into both mirrored positions.",
                "The symmetry C(n, k) equals C(n, n - k) is a structural property of every Pascal row.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String pascalTriangleIIFullTriangleSolutionEntryJson() {
        String code = """
                import java.util.List;
                import java.util.ArrayList;

                class Solution {
                    public List<Integer> getRow(int rowIndex) {
                        List<List<Integer>> triangle = new ArrayList<>();
                        for (int row = 0; row <= rowIndex; row++) {
                            List<Integer> current = new ArrayList<>();
                            for (int col = 0; col <= row; col++) {
                                if (col == 0 || col == row) {
                                    current.add(1);
                                } else {
                                    current.add(triangle.get(row - 1).get(col - 1)
                                            + triangle.get(row - 1).get(col));
                                }
                            }
                            triangle.add(current);
                        }
                        return triangle.get(rowIndex);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Build Full Triangle Fixture",
                "O(n^2)",
                "O(n^2)",
                "Build all rows up to rowIndex from the definition of Pascal's triangle.",
                "This baseline exposes the recurrence directly before optimizing memory or using coefficients.",
                "- Time Complexity: O(n^2)\\n- Space Complexity: O(n^2)",
                code);
    }

