    private static String bestTimeStockIIPositiveAdjacentGainSolutionEntryJson() {
        String code = """
                class Solution {
                    public int maxProfit(int[] prices) {
                        int profit = 0;
                        for (int i = 1; i < prices.length; i++) {
                            if (prices[i] > prices[i - 1]) {
                                profit += prices[i] - prices[i - 1];
                            }
                        }
                        return profit;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Positive Adjacent Gains Greedy Fixture",
                "O(n)",
                "O(1)",
                "Add every positive adjacent price gain during a single scan.",
                "Unlimited transactions let each positive daily rise be collected independently.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String bestTimeStockIIValleyPeakSolutionEntryJson() {
        String code = """
                class Solution {
                    public int maxProfit(int[] prices) {
                        int profit = 0;
                        int i = 0;
                        while (i < prices.length - 1) {
                            while (i < prices.length - 1 && prices[i] >= prices[i + 1]) {
                                i++;
                            }
                            int valley = prices[i];
                            while (i < prices.length - 1 && prices[i] <= prices[i + 1]) {
                                i++;
                            }
                            int peak = prices[i];
                            profit += peak - valley;
                        }
                        return profit;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Valley-Peak Transaction Scan Fixture",
                "O(n)",
                "O(1)",
                "Find each local valley, walk to the next local peak, and add that transaction profit.",
                "The explicit valley and peak boundaries teach the same optimum as adjacent positive gains.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String bestTimeStockIICashHoldStateMachineSolutionEntryJson() {
        String code = """
                class Solution {
                    public int maxProfit(int[] prices) {
                        int cash = 0;
                        int hold = -prices[0];
                        for (int i = 1; i < prices.length; i++) {
                            int prevCash = cash;
                            cash = Math.max(cash, hold + prices[i]);
                            hold = Math.max(hold, prevCash - prices[i]);
                        }
                        return cash;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Cash-Hold State Machine Fixture",
                "O(n)",
                "O(1)",
                "Maintain cash and hold states and update them with buy or sell transitions.",
                "The stock DP state machine generalizes cleanly to fees, cooldowns, and transaction limits.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String bestTimeStockIIExplicitDpTableSolutionEntryJson() {
        String code = """
                class Solution {
                    public int maxProfit(int[] prices) {
                        int n = prices.length;
                        int[] cash = new int[n];
                        int[] hold = new int[n];
                        hold[0] = -prices[0];
                        for (int i = 1; i < n; i++) {
                            cash[i] = Math.max(cash[i - 1], hold[i - 1] + prices[i]);
                            hold[i] = Math.max(hold[i - 1], cash[i - 1] - prices[i]);
                        }
                        return cash[n - 1];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Explicit DP Table Fixture",
                "O(n)",
                "O(n)",
                "Fill cash and hold arrays so every day-by-day transition is visible.",
                "The table form is the teaching baseline before compressing the recurrence to two variables.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String bestTimeStockIISentinelRunCompressionSolutionEntryJson() {
        String code = """
                class Solution {
                    public int maxProfit(int[] prices) {
                        int profit = 0;
                        int buy = prices[0];
                        for (int i = 1; i <= prices.length; i++) {
                            if (i == prices.length || prices[i] < prices[i - 1]) {
                                profit += Math.max(0, prices[i - 1] - buy);
                                if (i < prices.length) {
                                    buy = prices[i];
                                }
                            }
                        }
                        return profit;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Sentinel Run Compression Fixture",
                "O(n)",
                "O(1)",
                "Track one nondecreasing run and close it when a lower next price or the sentinel appears.",
                "The virtual sentinel closes the final transaction without a separate after-loop branch.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

