    private static String excelColumnTitleReverseAppendSolutionEntryJson() {
        String code = """
                class Solution {
                    public String convertToTitle(int columnNumber) {
                        StringBuilder reversed = new StringBuilder();
                        while (columnNumber > 0) {
                            columnNumber--;
                            reversed.append((char) ('A' + columnNumber % 26));
                            columnNumber /= 26;
                        }
                        return reversed.reverse().toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Reverse Append One-Offset Base 26 Fixture",
                "O(log n)",
                "O(log n)",
                "Subtract one, append the current low-order letter, divide by 26, then reverse the builder.",
                "The one-offset correction maps Excel letters A through Z to remainders zero through twenty-five.",
                "- Time Complexity: O(log n)\\n- Space Complexity: O(log n)",
                code);
    }

    private static String excelColumnTitleRecursivePrefixSolutionEntryJson() {
        String code = """
                class Solution {
                    public String convertToTitle(int columnNumber) {
                        if (columnNumber == 0) {
                            return "";
                        }
                        columnNumber--;
                        return convertToTitle(columnNumber / 26) + (char) ('A' + columnNumber % 26);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Recursive Prefix Conversion Fixture",
                "O(log n)",
                "O(log n)",
                "Use recursion so the quotient creates the prefix and the remainder creates the last letter.",
                "The subtraction before quotient and remainder is what makes multiples of twenty-six end in Z.",
                "- Time Complexity: O(log n)\\n- Space Complexity: O(log n)",
                code);
    }

    private static String excelColumnTitleStackReversalSolutionEntryJson() {
        String code = """
                import java.util.ArrayDeque;
                import java.util.Deque;

                class Solution {
                    public String convertToTitle(int columnNumber) {
                        Deque<Character> letters = new ArrayDeque<>();
                        while (columnNumber > 0) {
                            columnNumber--;
                            letters.push((char) ('A' + columnNumber % 26));
                            columnNumber /= 26;
                        }

                        StringBuilder result = new StringBuilder();
                        while (!letters.isEmpty()) {
                            result.append(letters.pop());
                        }
                        return result.toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Stack Reversal Fixture",
                "O(log n)",
                "O(log n)",
                "Push low-order generated letters and pop them to assemble the high-order title.",
                "A stack exposes the reversal caused by extracting base-26 digits from right to left.",
                "- Time Complexity: O(log n)\\n- Space Complexity: O(log n)",
                code);
    }

    private static String excelColumnTitleFixedBackBufferSolutionEntryJson() {
        String code = """
                class Solution {
                    public String convertToTitle(int columnNumber) {
                        char[] buffer = new char[16];
                        int write = buffer.length;
                        while (columnNumber > 0) {
                            columnNumber--;
                            buffer[--write] = (char) ('A' + columnNumber % 26);
                            columnNumber /= 26;
                        }
                        return new String(buffer, write, buffer.length - write);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Fixed Back Buffer Fixture",
                "O(log n)",
                "O(log n)",
                "Write generated letters into a fixed buffer from right to left.",
                "Back filling avoids an explicit reverse while keeping the one-offset digit extraction intact.",
                "- Time Complexity: O(log n)\\n- Space Complexity: O(log n)",
                code);
    }

    private static String excelColumnTitleExactLengthBackFillSolutionEntryJson() {
        String code = """
                class Solution {
                    public String convertToTitle(int columnNumber) {
                        int length = 0;
                        int copy = columnNumber;
                        while (copy > 0) {
                            copy--;
                            copy /= 26;
                            length++;
                        }

                        char[] answer = new char[length];
                        int write = length - 1;
                        while (columnNumber > 0) {
                            columnNumber--;
                            answer[write--] = (char) ('A' + columnNumber % 26);
                            columnNumber /= 26;
                        }
                        return new String(answer);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Exact-Length Back Fill Fixture",
                "O(log n)",
                "O(log n)",
                "Count the required title length first, then fill an exact-size array from the back.",
                "The title length is determined by the same one-offset carry process as the conversion.",
                "- Time Complexity: O(log n)\\n- Space Complexity: O(log n)",
                code);
    }

