    private static String reverseStringTemporaryTwoPointerSolutionEntryJson() {
        String code = """
                class Solution {
                    public void reverseString(char[] s) {
                        int left = 0;
                        int right = s.length - 1;
                        while (left < right) {
                            char temp = s[left];
                            s[left] = s[right];
                            s[right] = temp;
                            left++;
                            right--;
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Temporary Two-Pointer Fixture",
                "O(n)",
                "O(1)",
                "Swap the left and right characters and move both pointers inward.",
                "Each reversal pair is exactly i and n minus one minus i, so one swap fixes two positions.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String reverseStringMirrorIndexLoopSolutionEntryJson() {
        String code = """
                class Solution {
                    public void reverseString(char[] s) {
                        int n = s.length;
                        for (int i = 0; i < n / 2; i++) {
                            int j = n - 1 - i;
                            char temp = s[i];
                            s[i] = s[j];
                            s[j] = temp;
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Mirror Index For Loop Fixture",
                "O(n)",
                "O(1)",
                "Iterate over the first half and swap each index with its mirror position.",
                "Only n divided by two swaps are needed because each swap fixes both ends of a pair.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String reverseStringXorSwapSolutionEntryJson() {
        String code = """
                class Solution {
                    public void reverseString(char[] s) {
                        int left = 0;
                        int right = s.length - 1;
                        while (left < right) {
                            s[left] = (char) (s[left] ^ s[right]);
                            s[right] = (char) (s[left] ^ s[right]);
                            s[left] = (char) (s[left] ^ s[right]);
                            left++;
                            right--;
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "XOR Swap Fixture",
                "O(n)",
                "O(1)",
                "Use outside-in pointers and exchange each pair with three xor operations.",
                "The left index must stay below the right index so the xor swap never targets the same slot.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String reverseStringArithmeticSwapSolutionEntryJson() {
        String code = """
                class Solution {
                    public void reverseString(char[] s) {
                        int left = 0;
                        int right = s.length - 1;
                        while (left < right) {
                            s[left] = (char) (s[left] + s[right]);
                            s[right] = (char) (s[left] - s[right]);
                            s[left] = (char) (s[left] - s[right]);
                            left++;
                            right--;
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Printable ASCII Arithmetic Swap Fixture",
                "O(n)",
                "O(1)",
                "Use addition and subtraction to exchange printable ASCII character values.",
                "The prompt's ASCII constraint keeps the arithmetic swap inside the Java char range.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String reverseStringAdjacentPullBaselineSolutionEntryJson() {
        String code = """
                class Solution {
                    public void reverseString(char[] s) {
                        for (int end = s.length - 1; end > 0; end--) {
                            for (int i = 0; i < end; i++) {
                                char temp = s[i];
                                s[i] = s[i + 1];
                                s[i + 1] = temp;
                            }
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Adjacent Pull Baseline Fixture",
                "O(n^2)",
                "O(1)",
                "Move the first item of each active prefix to the end through adjacent swaps.",
                "This correct in-place baseline shows why direct mirror swaps are the efficient strategy.",
                "- Time Complexity: O(n^2)\\n- Space Complexity: O(1)",
                code);
    }

