    private static String reverseVowelsCollectAndRefillSolutionEntryJson() {
        String code = """
                class Solution {
                    public String reverseVowels(String s) {
                        char[] chars = s.toCharArray();
                        StringBuilder vowels = new StringBuilder();
                        for (char c : chars) {
                            if (isVowel(c)) {
                                vowels.append(c);
                            }
                        }

                        int write = vowels.length() - 1;
                        for (int i = 0; i < chars.length; i++) {
                            if (isVowel(chars[i])) {
                                chars[i] = vowels.charAt(write--);
                            }
                        }
                        return new String(chars);
                    }

                    private boolean isVowel(char c) {
                        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u'
                                || c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U';
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Collect and Refill Fixture",
                "O(n)",
                "O(n)",
                "Collect vowels in order, then refill vowel slots from the collected sequence in reverse.",
                "Separating discovery from placement makes it clear that only the vowel subsequence is reversed.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String reverseVowelsIndexListSolutionEntryJson() {
        String code = """
                import java.util.ArrayList;
                import java.util.List;

                class Solution {
                    public String reverseVowels(String s) {
                        char[] chars = s.toCharArray();
                        List<Integer> positions = new ArrayList<>();
                        for (int i = 0; i < chars.length; i++) {
                            if (isVowel(chars[i])) {
                                positions.add(i);
                            }
                        }

                        int left = 0;
                        int right = positions.size() - 1;
                        while (left < right) {
                            int i = positions.get(left++);
                            int j = positions.get(right--);
                            char temp = chars[i];
                            chars[i] = chars[j];
                            chars[j] = temp;
                        }
                        return new String(chars);
                    }

                    private boolean isVowel(char c) {
                        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u'
                                || c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U';
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Vowel Index List Swap Fixture",
                "O(n)",
                "O(n)",
                "Collect vowel indices and swap the characters stored at mirrored positions in that index list.",
                "The stored index list explicitly identifies the only positions whose characters may change.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String reverseVowelsRecursiveOutsideInSolutionEntryJson() {
        String code = """
                class Solution {
                    public String reverseVowels(String s) {
                        char[] chars = s.toCharArray();
                        reverse(chars, 0, chars.length - 1);
                        return new String(chars);
                    }

                    private void reverse(char[] chars, int left, int right) {
                        if (left >= right) {
                            return;
                        }
                        if (!isVowel(chars[left])) {
                            reverse(chars, left + 1, right);
                            return;
                        }
                        if (!isVowel(chars[right])) {
                            reverse(chars, left, right - 1);
                            return;
                        }
                        char temp = chars[left];
                        chars[left] = chars[right];
                        chars[right] = temp;
                        reverse(chars, left + 1, right - 1);
                    }

                    private boolean isVowel(char c) {
                        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u'
                                || c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U';
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Recursive Outside-In Scan Fixture",
                "O(n)",
                "O(n)",
                "Use recursive boundary movement to skip non-vowels and swap matching outside-in vowels.",
                "The recursive invariant is the same as the loop: everything outside the current range is fixed.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

