    private static String thirdMaximumLongSentinelSolutionEntryJson() {
        String code = """
                class Solution {
                    public int thirdMax(int[] nums) {
                        long first = Long.MIN_VALUE;
                        long second = Long.MIN_VALUE;
                        long third = Long.MIN_VALUE;
                        for (int num : nums) {
                            if (num == first || num == second || num == third) {
                                continue;
                            }
                            if (num > first) {
                                third = second;
                                second = first;
                                first = num;
                            } else if (num > second) {
                                third = second;
                                second = num;
                            } else if (num > third) {
                                third = num;
                            }
                        }
                        return third == Long.MIN_VALUE ? (int) first : (int) third;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Long Sentinel Rank Slots Fixture",
                "O(n)",
                "O(1)",
                "Maintain three long rank slots and insert each new distinct value into its descending position.",
                "Long.MIN_VALUE is outside the int domain, so a real Integer.MIN_VALUE is not mistaken for an empty slot.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String thirdMaximumNullableSlotSolutionEntryJson() {
        String code = """
                class Solution {
                    public int thirdMax(int[] nums) {
                        Integer first = null;
                        Integer second = null;
                        Integer third = null;
                        for (int num : nums) {
                            if ((first != null && num == first)
                                    || (second != null && num == second)
                                    || (third != null && num == third)) {
                                continue;
                            }
                            if (first == null || num > first) {
                                third = second;
                                second = first;
                                first = num;
                            } else if (second == null || num > second) {
                                third = second;
                                second = num;
                            } else if (third == null || num > third) {
                                third = num;
                            }
                        }
                        return third == null ? first : third;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Nullable Integer Rank Slots Fixture",
                "O(n)",
                "O(1)",
                "Use nullable Integer slots to represent missing ranks and shift filled ranks as new values arrive.",
                "Null represents absence directly, avoiding every numeric sentinel collision.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String thirdMaximumTreeSetSolutionEntryJson() {
        String code = """
                import java.util.TreeSet;

                class Solution {
                    public int thirdMax(int[] nums) {
                        TreeSet<Integer> top = new TreeSet<>();
                        for (int num : nums) {
                            top.add(num);
                            if (top.size() > 3) {
                                top.pollFirst();
                            }
                        }
                        return top.size() == 3 ? top.first() : top.last();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "TreeSet Top Three Trim Fixture",
                "O(n log 3)",
                "O(1)",
                "Store distinct values in a TreeSet and trim the smallest value whenever more than three remain.",
                "A trimmed three-value ordered set contains the top three distinct values, with the answer at the front.",
                "- Time Complexity: O(n log 3)\\n- Space Complexity: O(1)",
                code);
    }

    private static String thirdMaximumSortScanSolutionEntryJson() {
        String code = """
                import java.util.Arrays;

                class Solution {
                    public int thirdMax(int[] nums) {
                        Arrays.sort(nums);
                        int distinct = 0;
                        Integer previous = null;
                        for (int i = nums.length - 1; i >= 0; i--) {
                            if (previous != null && nums[i] == previous) {
                                continue;
                            }
                            distinct++;
                            previous = nums[i];
                            if (distinct == 3) {
                                return nums[i];
                            }
                        }
                        return nums[nums.length - 1];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Sort and Scan Distinct Values Fixture",
                "O(n log n)",
                "O(1)",
                "Sort ascending, scan backward, and count only value changes until the third distinct rank appears.",
                "Sorting groups duplicates and turns the distinct-ranking rule into a simple reverse scan.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String thirdMaximumHashSetMinHeapSolutionEntryJson() {
        String code = """
                import java.util.HashSet;
                import java.util.PriorityQueue;
                import java.util.Set;

                class Solution {
                    public int thirdMax(int[] nums) {
                        Set<Integer> seen = new HashSet<>();
                        PriorityQueue<Integer> top = new PriorityQueue<>();
                        for (int num : nums) {
                            if (!seen.add(num)) {
                                continue;
                            }
                            top.offer(num);
                            if (top.size() > 3) {
                                top.poll();
                            }
                        }
                        if (top.size() == 3) {
                            return top.peek();
                        }
                        int maximum = Integer.MIN_VALUE;
                        for (int num : seen) {
                            maximum = Math.max(maximum, num);
                        }
                        return maximum;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "HashSet and Min-Heap Top Three Fixture",
                "O(n log 3)",
                "O(n)",
                "Use a HashSet for global distinctness and a min-heap that retains only the best three candidates.",
                "When exactly three candidates remain, the heap root is the third maximum; otherwise the set maximum is returned.",
                "- Time Complexity: O(n log 3)\\n- Space Complexity: O(n)",
                code);
    }

