    private static String findAllDuplicatesNegativeMarkingSolutionEntryJson() {
        String code = """
                import java.util.ArrayList;
                import java.util.List;

                class Solution {
                    public List<Integer> findDuplicates(int[] nums) {
                        List<Integer> duplicates = new ArrayList<>();
                        for (int value : nums) {
                            int index = Math.abs(value) - 1;
                            if (nums[index] < 0) {
                                duplicates.add(index + 1);
                            } else {
                                nums[index] = -nums[index];
                            }
                        }
                        return duplicates;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Negative Index Marking Fixture",
                "O(n)",
                "O(1)",
                "Use each value as an array index and negate the home slot on the first visit.",
                "The sign bit of nums[x - 1] stores whether x has already been seen without an extra table.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1) excluding the returned list",
                code);
    }

    private static String findAllDuplicatesCyclicMismatchSolutionEntryJson() {
        String code = """
                import java.util.ArrayList;
                import java.util.List;

                class Solution {
                    public List<Integer> findDuplicates(int[] nums) {
                        int i = 0;
                        while (i < nums.length) {
                            int target = nums[i] - 1;
                            if (nums[i] != nums[target]) {
                                swap(nums, i, target);
                            } else {
                                i++;
                            }
                        }
                        List<Integer> duplicates = new ArrayList<>();
                        for (i = 0; i < nums.length; i++) {
                            if (nums[i] != i + 1) {
                                duplicates.add(nums[i]);
                            }
                        }
                        return duplicates;
                    }

                    private void swap(int[] nums, int i, int j) {
                        int temp = nums[i];
                        nums[i] = nums[j];
                        nums[j] = temp;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Cyclic Placement Mismatch Fixture",
                "O(n)",
                "O(1)",
                "Place every value at its home index when possible, then scan mismatched positions.",
                "Duplicates block missing values from occupying their home slots, so mismatches reveal duplicates.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1) excluding the returned list",
                code);
    }

    private static String findAllDuplicatesAddNCountingSolutionEntryJson() {
        String code = """
                import java.util.ArrayList;
                import java.util.List;

                class Solution {
                    public List<Integer> findDuplicates(int[] nums) {
                        int n = nums.length;
                        for (int i = 0; i < n; i++) {
                            int index = (nums[i] - 1) % n;
                            nums[index] += n;
                        }
                        List<Integer> duplicates = new ArrayList<>();
                        for (int i = 0; i < n; i++) {
                            if ((nums[i] - 1) / n == 2) {
                                duplicates.add(i + 1);
                            }
                        }
                        return duplicates;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Add-N In-Place Counting Fixture",
                "O(n)",
                "O(1)",
                "Add n to each value bucket and recover the visit count from the quotient.",
                "Modulo n preserves the original value while multiples of n encode how many times it was seen.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1) excluding the returned list",
                code);
    }

    private static String findAllDuplicatesZeroSentinelSolutionEntryJson() {
        String code = """
                import java.util.ArrayList;
                import java.util.List;

                class Solution {
                    public List<Integer> findDuplicates(int[] nums) {
                        List<Integer> duplicates = new ArrayList<>();
                        int i = 0;
                        while (i < nums.length) {
                            int value = nums[i];
                            if (value == 0 || value == i + 1) {
                                i++;
                                continue;
                            }
                            int target = value - 1;
                            if (nums[target] == value) {
                                duplicates.add(value);
                                nums[i] = 0;
                                i++;
                            } else {
                                swap(nums, i, target);
                            }
                        }
                        return duplicates;
                    }

                    private void swap(int[] nums, int i, int j) {
                        int temp = nums[i];
                        nums[i] = nums[j];
                        nums[j] = temp;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Placement Collision Zero Sentinel Fixture",
                "O(n)",
                "O(1)",
                "Move values to home positions and report a duplicate when a second copy collides with the first.",
                "Zero is outside the valid value range, so it can safely mark a duplicate copy already consumed.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1) excluding the returned list",
                code);
    }

