    private static String canPlaceFlowersMutatingGreedySolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean canPlaceFlowers(int[] flowerbed, int n) {
                        for (int i = 0; i < flowerbed.length && n > 0; i++) {
                            if (flowerbed[i] == 0
                                    && (i == 0 || flowerbed[i - 1] == 0)
                                    && (i == flowerbed.length - 1 || flowerbed[i + 1] == 0)) {
                                flowerbed[i] = 1;
                                n--;
                            }
                        }
                        return n == 0;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Mutating Earliest-Plot Greedy Fixture",
                "O(n)",
                "O(1)",
                "Scan left to right and plant immediately at the earliest empty plot whose neighbors are clear.",
                "The earliest legal placement in a zero run cannot reduce the maximum number of later placements.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String canPlaceFlowersZeroRunSolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean canPlaceFlowers(int[] flowerbed, int n) {
                        int canPlant = 0;
                        int zeros = 1;
                        for (int plot : flowerbed) {
                            if (plot == 0) {
                                zeros++;
                            } else {
                                canPlant += (zeros - 1) / 2;
                                zeros = 0;
                            }
                        }
                        zeros++;
                        canPlant += (zeros - 1) / 2;
                        return canPlant >= n;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Zero-Run Capacity with Virtual Boundaries Fixture",
                "O(n)",
                "O(1)",
                "Count each run of empty plots and compute its capacity using virtual empty boundaries.",
                "The same run formula handles leading, trailing, interior, and all-empty flowerbeds.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String canPlaceFlowersNonMutatingSolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean canPlaceFlowers(int[] flowerbed, int n) {
                        int lastPlanted = -2;
                        for (int i = 0; i < flowerbed.length && n > 0; i++) {
                            if (flowerbed[i] == 1) {
                                lastPlanted = i;
                                continue;
                            }
                            boolean leftClear = i - lastPlanted > 1;
                            boolean rightClear = i == flowerbed.length - 1 || flowerbed[i + 1] == 0;
                            if (leftClear && rightClear) {
                                lastPlanted = i;
                                n--;
                            }
                        }
                        return n <= 0;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Non-Mutating Last-Planted Greedy Fixture",
                "O(n)",
                "O(1)",
                "Track the latest existing or virtual flower instead of modifying the input array.",
                "The left side can be represented by the latest planted index while the original right neighbor is checked directly.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String canPlaceFlowersJumpingSolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean canPlaceFlowers(int[] flowerbed, int n) {
                        int i = 0;
                        while (i < flowerbed.length && n > 0) {
                            if (flowerbed[i] == 1) {
                                i += 2;
                                continue;
                            }
                            boolean leftClear = i == 0 || flowerbed[i - 1] == 0;
                            boolean rightClear = i == flowerbed.length - 1 || flowerbed[i + 1] == 0;
                            if (leftClear && rightClear) {
                                n--;
                                i += 2;
                            } else {
                                i++;
                            }
                        }
                        return n <= 0;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Jumping Greedy Skip Blocked Plots Fixture",
                "O(n)",
                "O(1)",
                "Skip the next plot after seeing an existing flower or after planting a new one.",
                "A flower makes its right neighbor unusable, so jumping exposes the blocking rule directly.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String canPlaceFlowersDynamicProgrammingSolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean canPlaceFlowers(int[] flowerbed, int n) {
                        Integer[][] memo = new Integer[flowerbed.length][2];
                        return maxFlowers(0, false, flowerbed, memo) >= n;
                    }

                    private int maxFlowers(int index, boolean previousOccupied, int[] flowerbed, Integer[][] memo) {
                        if (index == flowerbed.length) {
                            return 0;
                        }
                        int state = previousOccupied ? 1 : 0;
                        if (memo[index][state] != null) {
                            return memo[index][state];
                        }
                        if (flowerbed[index] == 1) {
                            memo[index][state] = maxFlowers(index + 1, true, flowerbed, memo);
                            return memo[index][state];
                        }
                        int best = maxFlowers(index + 1, false, flowerbed, memo);
                        boolean nextClear = index == flowerbed.length - 1 || flowerbed[index + 1] == 0;
                        if (!previousOccupied && nextClear) {
                            best = Math.max(best, 1 + maxFlowers(index + 1, true, flowerbed, memo));
                        }
                        memo[index][state] = best;
                        return best;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Dynamic Programming Capacity Check Fixture",
                "O(n)",
                "O(n)",
                "Memoize the maximum number of flowers from each index and previous-occupied state.",
                "The DP provides a heavier correctness cross-check for the local greedy decisions.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

