    private static String baseballGameListStackSolutionEntryJson() {
        String code = """
                import java.util.ArrayList;
                import java.util.List;

                class Solution {
                    public int calPoints(String[] operations) {
                        List<Integer> stack = new ArrayList<>();
                        for (String op : operations) {
                            int size = stack.size();
                            if (op.equals("+")) {
                                stack.add(stack.get(size - 1) + stack.get(size - 2));
                            } else if (op.equals("D")) {
                                stack.add(2 * stack.get(size - 1));
                            } else if (op.equals("C")) {
                                stack.remove(size - 1);
                            } else {
                                stack.add(Integer.parseInt(op));
                            }
                        }
                        int total = 0;
                        for (int score : stack) {
                            total += score;
                        }
                        return total;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Dynamic List Stack Simulation Fixture",
                "O(n)",
                "O(n)",
                "Use a list-backed stack to store the current valid score record and sum it at the end.",
                "The latest valid scores are exactly the values needed by C, D, and plus operations.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String baseballGameArrayStackSolutionEntryJson() {
        String code = """
                class Solution {
                    public int calPoints(String[] operations) {
                        int[] scores = new int[operations.length];
                        int top = 0;
                        for (String op : operations) {
                            if (op.equals("+")) {
                                scores[top] = scores[top - 1] + scores[top - 2];
                                top++;
                            } else if (op.equals("D")) {
                                scores[top] = 2 * scores[top - 1];
                                top++;
                            } else if (op.equals("C")) {
                                top--;
                            } else {
                                scores[top] = Integer.parseInt(op);
                                top++;
                            }
                        }
                        int total = 0;
                        for (int i = 0; i < top; i++) {
                            total += scores[i];
                        }
                        return total;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Manual Array Stack Fixture",
                "O(n)",
                "O(n)",
                "Use a fixed int array and top pointer as a manual stack for all valid scores.",
                "The operation count bounds the maximum stack size, so array storage is sufficient.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String baseballGameRunningTotalDequeSolutionEntryJson() {
        String code = """
                import java.util.ArrayDeque;
                import java.util.Deque;

                class Solution {
                    public int calPoints(String[] operations) {
                        Deque<Integer> scores = new ArrayDeque<>();
                        int total = 0;
                        for (String op : operations) {
                            int score;
                            if (op.equals("C")) {
                                total -= scores.removeLast();
                            } else if (op.equals("D")) {
                                score = scores.peekLast() * 2;
                                scores.addLast(score);
                                total += score;
                            } else if (op.equals("+")) {
                                int last = scores.removeLast();
                                int previous = scores.peekLast();
                                scores.addLast(last);
                                score = last + previous;
                                scores.addLast(score);
                                total += score;
                            } else {
                                score = Integer.parseInt(op);
                                scores.addLast(score);
                                total += score;
                            }
                        }
                        return total;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Running Total Deque Stack Fixture",
                "O(n)",
                "O(n)",
                "Maintain the total while mutating a deque-backed stack of valid scores.",
                "Undo-style C operations subtract the removed value so no final summation pass is needed.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String baseballGameLinkedNodeSolutionEntryJson() {
        String code = """
                class Solution {
                    private static final class Node {
                        final int score;
                        final Node previous;

                        Node(int score, Node previous) {
                            this.score = score;
                            this.previous = previous;
                        }
                    }

                    public int calPoints(String[] operations) {
                        Node top = null;
                        int total = 0;
                        for (String op : operations) {
                            if (op.equals("C")) {
                                total -= top.score;
                                top = top.previous;
                            } else {
                                int score;
                                if (op.equals("D")) {
                                    score = top.score * 2;
                                } else if (op.equals("+")) {
                                    score = top.score + top.previous.score;
                                } else {
                                    score = Integer.parseInt(op);
                                }
                                top = new Node(score, top);
                                total += score;
                            }
                        }
                        return total;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Linked Node Stack with Aggregate Fixture",
                "O(n)",
                "O(n)",
                "Represent the record as linked stack nodes and maintain the score aggregate beside it.",
                "The plus operation only needs the top node and its previous node, while C rewinds the pointer.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String baseballGameRecursiveSolutionEntryJson() {
        String code = """
                import java.util.ArrayList;
                import java.util.List;

                class Solution {
                    public int calPoints(String[] operations) {
                        List<Integer> record = new ArrayList<>();
                        apply(operations, 0, record);
                        int total = 0;
                        for (int score : record) {
                            total += score;
                        }
                        return total;
                    }

                    private void apply(String[] operations, int index, List<Integer> record) {
                        if (index == operations.length) {
                            return;
                        }
                        String op = operations[index];
                        int size = record.size();
                        if (op.equals("C")) {
                            record.remove(size - 1);
                        } else if (op.equals("D")) {
                            record.add(record.get(size - 1) * 2);
                        } else if (op.equals("+")) {
                            record.add(record.get(size - 1) + record.get(size - 2));
                        } else {
                            record.add(Integer.parseInt(op));
                        }
                        apply(operations, index + 1, record);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Recursive Operation Processor Fixture",
                "O(n)",
                "O(n)",
                "Apply one operation per recursive frame and recurse to the next command index.",
                "The recursion exposes the state transition for each command separately from loop mechanics.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

