    private static String toLowerCaseLookupTableSolutionEntryJson() {
        String code = """
                class Solution {
                    public String toLowerCase(String s) {
                        char[] table = new char[128];
                        for (int i = 0; i < table.length; i++) {
                            table[i] = (char) i;
                        }
                        for (char c = 'A'; c <= 'Z'; c++) {
                            table[c] = (char) ('a' + (c - 'A'));
                        }
                        char[] result = s.toCharArray();
                        for (int i = 0; i < result.length; i++) {
                            result[i] = table[result[i]];
                        }
                        return new String(result);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "ASCII Lookup Table Fixture",
                "O(n)",
                "O(1)",
                "Precompute a 128-entry ASCII table, then replace every character by lookup.",
                "The table isolates classification from transformation and stays constant-size for printable ASCII.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

