    private static String sortArrayByParityTwoPointerSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] sortArrayByParity(int[] nums) {
                        int l = 0, r = nums.length - 1;
                        while (l < r) {
                            if (nums[l] % 2 == 1 && nums[r] % 2 == 0) {
                                int tmp = nums[l];
                                nums[l] = nums[r];
                                nums[r] = tmp;
                            }
                            if (nums[l] % 2 == 0) l++;
                            if (nums[r] % 2 == 1) r--;
                        }
                        return nums;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Two Pointer Swap Fixture",
                "O(n)",
                "O(1)",
                "Swap misplaced odd and even values from the two ends of the array.",
                "Only the parity partition matters, so each swap fixes one wrong value on each side.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String sortArrayByParityWritePartitionSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] sortArrayByParity(int[] nums) {
                        int write = 0;
                        for (int i = 0; i < nums.length; i++) {
                            if (nums[i] % 2 == 0) {
                                int tmp = nums[write];
                                nums[write] = nums[i];
                                nums[i] = tmp;
                                write++;
                            }
                        }
                        return nums;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Single Write Partition Fixture",
                "O(n)",
                "O(1)",
                "Use a write pointer for the next even slot and swap every seen even into that prefix.",
                "The prefix before write is always even, matching the two-bucket partition invariant.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String sortArrayByParityStableTwoPassSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] sortArrayByParity(int[] nums) {
                        int[] result = new int[nums.length];
                        int write = 0;
                        for (int value : nums) {
                            if (value % 2 == 0) {
                                result[write++] = value;
                            }
                        }
                        for (int value : nums) {
                            if (value % 2 != 0) {
                                result[write++] = value;
                            }
                        }
                        return result;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Stable Two-Pass Output Fixture",
                "O(n)",
                "O(n)",
                "Write evens in original order, then odds in original order.",
                "Extra space buys a stable partition even though the problem accepts any valid parity order.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String sortArrayByParityFrontBackSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] sortArrayByParity(int[] nums) {
                        int[] result = new int[nums.length];
                        int left = 0;
                        int right = nums.length - 1;
                        for (int value : nums) {
                            if (value % 2 == 0) {
                                result[left++] = value;
                            } else {
                                result[right--] = value;
                            }
                        }
                        return result;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Single-Pass Front Back Output Fixture",
                "O(n)",
                "O(n)",
                "Write evens from the front and odds from the back of a result array during one scan.",
                "The relaxed output contract permits reversing odd order as long as every odd is after every even.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String sortArrayByParityCountingBucketsSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] sortArrayByParity(int[] nums) {
                        int[] counts = new int[5001];
                        for (int value : nums) {
                            counts[value]++;
                        }
                        int[] result = new int[nums.length];
                        int write = 0;
                        for (int value = 0; value <= 5000; value += 2) {
                            while (counts[value] > 0) {
                                result[write++] = value;
                                counts[value]--;
                            }
                        }
                        for (int value = 1; value <= 5000; value += 2) {
                            while (counts[value] > 0) {
                                result[write++] = value;
                                counts[value]--;
                            }
                        }
                        return result;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Bounded Counting Buckets Fixture",
                "O(n + U)",
                "O(U)",
                "Count every value in the bounded range, then emit even buckets before odd buckets.",
                "The value bound allows deterministic bucket output without swaps or preserving original order.",
                "- Time Complexity: O(n + U)\\n- Space Complexity: O(U)",
                code);
    }

