    private static String uniqueEmailAddressesHashSetSolutionEntryJson() {
        String code = """
                import java.util.HashSet;
                import java.util.Set;

                class Solution {
                    public int numUniqueEmails(String[] emails) {
                        Set<String> seen = new HashSet<>();
                        for (String email : emails) {
                            int at = email.indexOf('@');
                            String local = email.substring(0, at);
                            String domain = email.substring(at + 1);
                            int plus = local.indexOf('+');
                            if (plus >= 0) {
                                local = local.substring(0, plus);
                            }
                            local = local.replace(".", "");
                            seen.add(local + "@" + domain);
                        }
                        return seen.size();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "HashSet Canonical Fixture",
                "O(n * m)",
                "O(n * m)",
                "Normalize each email to a canonical address and insert it into a HashSet.",
                "Only the local name is rewritten; the exact domain remains part of the recipient key.",
                "- Time Complexity: O(n * m)\\n- Space Complexity: O(n * m)",
                code);
    }

    private static String uniqueEmailAddressesManualParserSolutionEntryJson() {
        String code = """
                import java.util.HashSet;
                import java.util.Set;

                class Solution {
                    public int numUniqueEmails(String[] emails) {
                        Set<String> seen = new HashSet<>();
                        for (String email : emails) {
                            StringBuilder normalized = new StringBuilder();
                            boolean ignoringLocalSuffix = false;
                            for (int i = 0; i < email.length(); i++) {
                                char c = email.charAt(i);
                                if (c == '@') {
                                    normalized.append(c);
                                    normalized.append(email.substring(i + 1));
                                    break;
                                }
                                if (c == '+') {
                                    ignoringLocalSuffix = true;
                                } else if (!ignoringLocalSuffix && c != '.') {
                                    normalized.append(c);
                                }
                            }
                            seen.add(normalized.toString());
                        }
                        return seen.size();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Manual Parser Fixture",
                "O(n * m)",
                "O(n * m)",
                "Stream through each email and build the canonical address directly.",
                "The at sign switches from local rewrite mode to verbatim domain-copy mode.",
                "- Time Complexity: O(n * m)\\n- Space Complexity: O(n * m)",
                code);
    }

    private static String uniqueEmailAddressesSortCountSolutionEntryJson() {
        String code = """
                import java.util.Arrays;

                class Solution {
                    public int numUniqueEmails(String[] emails) {
                        String[] normalized = new String[emails.length];
                        for (int i = 0; i < emails.length; i++) {
                            normalized[i] = normalize(emails[i]);
                        }
                        Arrays.sort(normalized);
                        int unique = 0;
                        for (int i = 0; i < normalized.length; i++) {
                            if (i == 0 || !normalized[i].equals(normalized[i - 1])) {
                                unique++;
                            }
                        }
                        return unique;
                    }

                    private String normalize(String email) {
                        int at = email.indexOf('@');
                        StringBuilder local = new StringBuilder();
                        for (int i = 0; i < at && email.charAt(i) != '+'; i++) {
                            char c = email.charAt(i);
                            if (c != '.') {
                                local.append(c);
                            }
                        }
                        return local.append(email.substring(at)).toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Sort Count Fixture",
                "O(n * m + n log n)",
                "O(n * m)",
                "Normalize all emails, sort them, and count adjacent changes.",
                "Ordering can replace hashing because equal canonical recipients become neighbors.",
                "- Time Complexity: O(n * m + n log n)\\n- Space Complexity: O(n * m)",
                code);
    }

    private static String uniqueEmailAddressesDomainBucketsSolutionEntryJson() {
        String code = """
                import java.util.HashMap;
                import java.util.HashSet;
                import java.util.Map;
                import java.util.Set;

                class Solution {
                    public int numUniqueEmails(String[] emails) {
                        Map<String, Set<String>> localsByDomain = new HashMap<>();
                        for (String email : emails) {
                            int at = email.indexOf('@');
                            String domain = email.substring(at + 1);
                            String local = canonicalLocal(email, at);
                            localsByDomain.computeIfAbsent(domain, key -> new HashSet<>()).add(local);
                        }
                        int total = 0;
                        for (Set<String> locals : localsByDomain.values()) {
                            total += locals.size();
                        }
                        return total;
                    }

                    private String canonicalLocal(String email, int at) {
                        StringBuilder local = new StringBuilder();
                        for (int i = 0; i < at; i++) {
                            char c = email.charAt(i);
                            if (c == '+') {
                                break;
                            }
                            if (c != '.') {
                                local.append(c);
                            }
                        }
                        return local.toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Domain Buckets Fixture",
                "O(n * m)",
                "O(n * m)",
                "Group canonical local names under their unchanged domain names.",
                "A recipient is a pair of canonical local name and exact domain, not just a local name.",
                "- Time Complexity: O(n * m)\\n- Space Complexity: O(n * m)",
                code);
    }

    private static String uniqueEmailAddressesTrieSolutionEntryJson() {
        String code = """
                import java.util.HashMap;
                import java.util.Map;

                class Solution {
                    static class Node {
                        Map<Character, Node> children = new HashMap<>();
                        boolean terminal;
                    }

                    public int numUniqueEmails(String[] emails) {
                        Node root = new Node();
                        int unique = 0;
                        for (String email : emails) {
                            String normalized = normalize(email);
                            if (insert(root, normalized)) {
                                unique++;
                            }
                        }
                        return unique;
                    }

                    private boolean insert(Node root, String word) {
                        Node node = root;
                        for (int i = 0; i < word.length(); i++) {
                            char c = word.charAt(i);
                            node = node.children.computeIfAbsent(c, key -> new Node());
                        }
                        if (node.terminal) {
                            return false;
                        }
                        node.terminal = true;
                        return true;
                    }

                    private String normalize(String email) {
                        int at = email.indexOf('@');
                        StringBuilder builder = new StringBuilder();
                        for (int i = 0; i < at; i++) {
                            char c = email.charAt(i);
                            if (c == '+') {
                                break;
                            }
                            if (c != '.') {
                                builder.append(c);
                            }
                        }
                        return builder.append(email.substring(at)).toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Trie Fixture",
                "O(n * m)",
                "O(n * m)",
                "Insert every canonical recipient address into a trie and count new terminal nodes.",
                "The trie compares the whole normalized address while sharing prefixes between recipients.",
                "- Time Complexity: O(n * m)\\n- Space Complexity: O(n * m)",
                code);
    }

