    private static String rangeSumBstInorderSolutionEntryJson() {
        String code = """
                import java.util.ArrayDeque;
                import java.util.Deque;

                class Solution {
                    public int rangeSumBST(TreeNode root, int low, int high) {
                        int sum = 0;
                        Deque<TreeNode> stack = new ArrayDeque<>();
                        TreeNode node = root;
                        while (node != null || !stack.isEmpty()) {
                            while (node != null) {
                                if (node.val >= low) {
                                    stack.push(node);
                                    node = node.left;
                                } else {
                                    node = node.right;
                                }
                            }
                            if (stack.isEmpty()) {
                                break;
                            }
                            node = stack.pop();
                            if (node.val > high) {
                                break;
                            }
                            sum += node.val;
                            node = node.right;
                        }
                        return sum;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Inorder Range Scan Fixture",
                "O(n)",
                "O(h)",
                "Scan the BST in sorted order and stop once the traversal moves beyond high.",
                "The requested range is contiguous in inorder order, so sorted traversal can skip and terminate.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(h)",
                code);
    }

    private static String rangeSumBstMorrisSolutionEntryJson() {
        String code = """
                class Solution {
                    public int rangeSumBST(TreeNode root, int low, int high) {
                        int sum = 0;
                        TreeNode current = root;
                        while (current != null) {
                            if (current.left == null) {
                                if (current.val >= low && current.val <= high) {
                                    sum += current.val;
                                }
                                current = current.right;
                            } else {
                                TreeNode predecessor = current.left;
                                while (predecessor.right != null && predecessor.right != current) {
                                    predecessor = predecessor.right;
                                }
                                if (predecessor.right == null) {
                                    predecessor.right = current;
                                    current = current.left;
                                } else {
                                    predecessor.right = null;
                                    if (current.val >= low && current.val <= high) {
                                        sum += current.val;
                                    }
                                    current = current.right;
                                }
                            }
                        }
                        return sum;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Morris Traversal Fixture",
                "O(n)",
                "O(1)",
                "Use Morris inorder traversal to visit nodes without recursion or a stack.",
                "Temporary predecessor threads provide constant auxiliary space while restoring the tree after each visit.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

