    private static String verifyingAlienDictionaryRecursiveSolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean isAlienSorted(String[] words, String order) {
                        int[] rank = new int[26];
                        for (int i = 0; i < order.length(); i++) {
                            rank[order.charAt(i) - 'a'] = i;
                        }
                        for (int i = 0; i + 1 < words.length; i++) {
                            if (!inOrder(words[i], words[i + 1], 0, rank)) {
                                return false;
                            }
                        }
                        return true;
                    }

                    private boolean inOrder(String left, String right, int index, int[] rank) {
                        if (index == left.length() || index == right.length()) {
                            return left.length() <= right.length();
                        }
                        int a = rank[left.charAt(index) - 'a'];
                        int b = rank[right.charAt(index) - 'a'];
                        if (a != b) {
                            return a < b;
                        }
                        return inOrder(left, right, index + 1, rank);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Recursive Comparator Fixture",
                "O(n * m)",
                "O(m)",
                "Compare adjacent pairs recursively from left to right.",
                "Lexicographic comparison reduces to comparing the current character, then the suffix if tied.",
                "- Time Complexity: O(n * m)\\n- Space Complexity: O(m)",
                code);
    }

    private static String verifyingAlienDictionarySentinelSolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean isAlienSorted(String[] words, String order) {
                        int[] rank = new int[26];
                        for (int i = 0; i < order.length(); i++) {
                            rank[order.charAt(i) - 'a'] = i + 1;
                        }
                        int[] previous = encode(words[0], rank);
                        for (int i = 1; i < words.length; i++) {
                            int[] current = encode(words[i], rank);
                            if (!lessOrEqual(previous, current)) {
                                return false;
                            }
                            previous = current;
                        }
                        return true;
                    }

                    private int[] encode(String word, int[] rank) {
                        int[] encoded = new int[word.length() + 1];
                        for (int i = 0; i < word.length(); i++) {
                            encoded[i] = rank[word.charAt(i) - 'a'];
                        }
                        encoded[word.length()] = 0;
                        return encoded;
                    }

                    private boolean lessOrEqual(int[] left, int[] right) {
                        int limit = Math.min(left.length, right.length);
                        for (int i = 0; i < limit; i++) {
                            if (left[i] != right[i]) {
                                return left[i] < right[i];
                            }
                        }
                        return true;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Sentinel Rank Encoding Fixture",
                "O(n * m)",
                "O(m)",
                "Encode each word as alien ranks plus an end sentinel and compare adjacent sequences.",
                "The sentinel makes the shorter-prefix rule part of ordinary integer sequence comparison.",
                "- Time Complexity: O(n * m)\\n- Space Complexity: O(m)",
                code);
    }

