    private static String nRepeatedElementHashSetSolutionEntryJson() {
        String code = """
                import java.util.HashSet;
                import java.util.Set;

                class Solution {
                    public int repeatedNTimes(int[] nums) {
                        Set<Integer> seen = new HashSet<>();
                        for (int value : nums) {
                            if (!seen.add(value)) {
                                return value;
                            }
                        }
                        return -1;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "HashSet First Repeat Fixture",
                "O(n)",
                "O(n)",
                "Insert values into a hash set and return the first insertion failure.",
                "Only one value repeats, so the first duplicate found by a generic detector is the answer.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String nRepeatedElementDistanceThreeSolutionEntryJson() {
        String code = """
                class Solution {
                    public int repeatedNTimes(int[] nums) {
                        for (int i = 0; i < nums.length; i++) {
                            for (int distance = 1; distance <= 3 && i + distance < nums.length; distance++) {
                                if (nums[i] == nums[i + distance]) {
                                    return nums[i];
                                }
                            }
                        }
                        return -1;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Distance Three Window Fixture",
                "O(n)",
                "O(1)",
                "Check the next three positions from every index.",
                "The repeated value appears n times in 2n slots, forcing two copies within distance three.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String nRepeatedElementCountingSolutionEntryJson() {
        String code = """
                class Solution {
                    public int repeatedNTimes(int[] nums) {
                        int[] count = new int[10001];
                        for (int value : nums) {
                            count[value]++;
                            if (count[value] == 2) {
                                return value;
                            }
                        }
                        return -1;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Bounded Counting Array Fixture",
                "O(n + U)",
                "O(U)",
                "Count values with an array sized to the official value bound.",
                "Because non-answer values appear once, the second hit in any bucket identifies the answer.",
                "- Time Complexity: O(n + U)\\n- Space Complexity: O(U)",
                code);
    }

    private static String nRepeatedElementSortAdjacentSolutionEntryJson() {
        String code = """
                import java.util.Arrays;

                class Solution {
                    public int repeatedNTimes(int[] nums) {
                        int[] sorted = nums.clone();
                        Arrays.sort(sorted);
                        for (int i = 1; i < sorted.length; i++) {
                            if (sorted[i] == sorted[i - 1]) {
                                return sorted[i];
                            }
                        }
                        return -1;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Sort Adjacent Scan Fixture",
                "O(n log n)",
                "O(n)",
                "Sort a copy and scan adjacent equal values.",
                "Sorting groups equal values together, making the only duplicate visible as an adjacent pair.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String nRepeatedElementPairwiseSolutionEntryJson() {
        String code = """
                class Solution {
                    public int repeatedNTimes(int[] nums) {
                        for (int i = 0; i < nums.length; i++) {
                            for (int j = i + 1; j < nums.length; j++) {
                                if (nums[i] == nums[j]) {
                                    return nums[i];
                                }
                            }
                        }
                        return -1;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Pairwise Baseline Fixture",
                "O(n^2)",
                "O(1)",
                "Enumerate every pair of indices until an equal pair is found.",
                "The simplest duplicate definition is a useful baseline before introducing faster data structures.",
                "- Time Complexity: O(n^2)\\n- Space Complexity: O(1)",
                code);
    }

