    private static String countNegativeCellsStaircaseSolutionEntryJson() {
        String code = """
                class Solution {
                    public int countNegatives(int[][] grid) {
                        int rows = grid.length;
                        int cols = grid[0].length;
                        int row = rows - 1;
                        int col = 0;
                        int count = 0;
                        while (row >= 0 && col < cols) {
                            if (grid[row][col] < 0) {
                                count += cols - col;
                                row--;
                            } else {
                                col++;
                            }
                        }
                        return count;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Bottom-Left Staircase Fixture",
                "O(m + n)",
                "O(1)",
                "Walk from the bottom-left corner and count negative row suffixes.",
                "Each step removes either a counted negative suffix or a non-negative position from consideration.",
                "- Time Complexity: O(m + n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String countNegativeCellsCarriedBoundarySolutionEntryJson() {
        String code = """
                class Solution {
                    public int countNegatives(int[][] grid) {
                        int rows = grid.length;
                        int cols = grid[0].length;
                        int firstNegative = cols;
                        int count = 0;
                        for (int row = 0; row < rows; row++) {
                            while (firstNegative > 0 && grid[row][firstNegative - 1] < 0) {
                                firstNegative--;
                            }
                            count += cols - firstNegative;
                        }
                        return count;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Carried Row Boundary Fixture",
                "O(m + n)",
                "O(1)",
                "Carry the first negative column boundary from one row to the next.",
                "Column ordering means the boundary can only move left as rows move downward.",
                "- Time Complexity: O(m + n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String countNegativeCellsRowBinarySolutionEntryJson() {
        String code = """
                class Solution {
                    public int countNegatives(int[][] grid) {
                        int rows = grid.length;
                        int cols = grid[0].length;
                        int count = 0;
                        for (int row = 0; row < rows; row++) {
                            int left = 0;
                            int right = cols;
                            while (left < right) {
                                int mid = left + (right - left) / 2;
                                if (grid[row][mid] < 0) {
                                    right = mid;
                                } else {
                                    left = mid + 1;
                                }
                            }
                            count += cols - left;
                        }
                        return count;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Row Binary Search Fixture",
                "O(m log n)",
                "O(1)",
                "Binary search every row for the first negative cell.",
                "In each descending row, the negative predicate changes from false to true once.",
                "- Time Complexity: O(m log n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String countNegativeCellsColumnBinarySolutionEntryJson() {
        String code = """
                class Solution {
                    public int countNegatives(int[][] grid) {
                        int rows = grid.length;
                        int cols = grid[0].length;
                        int count = 0;
                        for (int col = 0; col < cols; col++) {
                            int low = 0;
                            int high = rows - 1;
                            int first = rows;
                            while (low <= high) {
                                int mid = low + (high - low) / 2;
                                if (grid[mid][col] < 0) {
                                    first = mid;
                                    high = mid - 1;
                                } else {
                                    low = mid + 1;
                                }
                            }
                            count += rows - first;
                        }
                        return count;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Column Binary Search Fixture",
                "O(n log m)",
                "O(1)",
                "Binary search every column for the first negative cell.",
                "Column monotonicity is enough to count the negative suffix in each column.",
                "- Time Complexity: O(n log m)\\n- Space Complexity: O(1)",
                code);
    }

