    private static String shuffleArrayDirectIndexSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] shuffle(int[] nums, int n) {
                        int[] answer = new int[2 * n];
                        for (int i = 0; i < n; i++) {
                            answer[2 * i] = nums[i];
                            answer[2 * i + 1] = nums[i + n];
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Direct Index Mapping Fixture",
                "O(n)",
                "O(n)",
                "Write each first-half and second-half offset directly into its target index.",
                "Offset i from the first half always pairs with offset i from the second half.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String shuffleArrayTwoPointerSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] shuffle(int[] nums, int n) {
                        int[] answer = new int[2 * n];
                        int left = 0;
                        int right = n;
                        int write = 0;

                        while (left < n) {
                            answer[write++] = nums[left++];
                            answer[write++] = nums[right++];
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Two Pointer Half Merge Fixture",
                "O(n)",
                "O(n)",
                "Merge one pointer from each half into the output in alternating order.",
                "The input is two streams with aligned offsets, so advancing both pointers together forms each pair.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String shuffleArrayBitPackingSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] shuffle(int[] nums, int n) {
                        for (int i = 0; i < n; i++) {
                            nums[i] = nums[i] | (nums[i + n] << 10);
                        }

                        int write = 2 * n - 1;
                        for (int i = n - 1; i >= 0; i--) {
                            int y = nums[i] >> 10;
                            int x = nums[i] & 1023;
                            nums[write--] = y;
                            nums[write--] = x;
                        }
                        return nums;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "In-Place Bit Packing Fixture",
                "O(n)",
                "O(1)",
                "Pack each aligned pair into the first half and unpack from right to left.",
                "The value bound leaves enough bits to store both values until their final positions are written.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String shuffleArrayQueueSolutionEntryJson() {
        String code = """
                import java.util.ArrayDeque;
                import java.util.Queue;

                class Solution {
                    public int[] shuffle(int[] nums, int n) {
                        Queue<Integer> firstHalf = new ArrayDeque<>();
                        for (int i = 0; i < n; i++) {
                            firstHalf.add(nums[i]);
                        }

                        int[] answer = new int[2 * n];
                        int write = 0;
                        for (int i = n; i < 2 * n; i++) {
                            answer[write++] = firstHalf.remove();
                            answer[write++] = nums[i];
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Queue First Half Fixture",
                "O(n)",
                "O(n)",
                "Queue the first half, then pair each queued x value with the current second-half y value.",
                "The queue turns the first half into a stream while the second half is scanned in place.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

