    private static String runningSumInPlaceSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] runningSum(int[] nums) {
                        for (int i = 1; i < nums.length; i++) {
                            nums[i] += nums[i - 1];
                        }
                        return nums;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "In-Place Prefix Accumulation Fixture",
                "O(n)",
                "O(1)",
                "Accumulate each prefix sum directly inside the input array.",
                "After the previous index is correct, adding it to the current value produces the current prefix.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String runningSumNewArraySolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] runningSum(int[] nums) {
                        int[] answer = new int[nums.length];
                        int running = 0;
                        for (int i = 0; i < nums.length; i++) {
                            running += nums[i];
                            answer[i] = running;
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "New Array Running Total Fixture",
                "O(n)",
                "O(n)",
                "Maintain a separate running total and write each prefix to a fresh answer array.",
                "Keeping the cumulative state outside the input preserves the original values.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String runningSumRecursiveSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] runningSum(int[] nums) {
                        int[] answer = nums.clone();
                        fill(answer, 1);
                        return answer;
                    }

                    private void fill(int[] answer, int index) {
                        if (index == answer.length) {
                            return;
                        }
                        answer[index] += answer[index - 1];
                        fill(answer, index + 1);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Recursive Prefix Propagation Fixture",
                "O(n)",
                "O(n)",
                "Propagate the prefix recurrence one index at a time through recursion.",
                "The current prefix is the previous prefix plus the current value.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String runningSumHillisSteeleSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] runningSum(int[] nums) {
                        int[] answer = nums.clone();
                        for (int step = 1; step < answer.length; step <<= 1) {
                            int[] previous = answer.clone();
                            for (int i = step; i < answer.length; i++) {
                                answer[i] = previous[i] + previous[i - step];
                            }
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Hillis Steele Prefix Scan Fixture",
                "O(n log n)",
                "O(n)",
                "Double the distance of accumulated ranges in each prefix-scan round.",
                "This is the classic parallel-prefix construction, even though a serial scan is faster here.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

