    private static String kidsWithCandiesMaxScanSolutionEntryJson() {
        String code = """
                import java.util.ArrayList;
                import java.util.List;

                class Solution {
                    public List<Boolean> kidsWithCandies(int[] candies, int extraCandies) {
                        int max = 0;
                        for (int candy : candies) {
                            max = Math.max(max, candy);
                        }

                        List<Boolean> answer = new ArrayList<>();
                        for (int candy : candies) {
                            answer.add(candy + extraCandies >= max);
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Find Max Then Compare Fixture",
                "O(n)",
                "O(1)",
                "Find the current maximum, then compare every kid after adding the extra candies.",
                "Ties count as greatest, so each comparison must use greater-than-or-equal.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String kidsWithCandiesThresholdSolutionEntryJson() {
        String code = """
                import java.util.ArrayList;
                import java.util.List;

                class Solution {
                    public List<Boolean> kidsWithCandies(int[] candies, int extraCandies) {
                        int max = 0;
                        for (int candy : candies) {
                            if (candy > max) {
                                max = candy;
                            }
                        }

                        int threshold = max - extraCandies;
                        List<Boolean> answer = new ArrayList<>();
                        for (int candy : candies) {
                            answer.add(candy >= threshold);
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Required Candy Threshold Fixture",
                "O(n)",
                "O(1)",
                "Convert the maximum comparison into a minimum starting-candy threshold.",
                "Any kid at or above max minus extra candies can tie the current maximum.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String kidsWithCandiesSortCopySolutionEntryJson() {
        String code = """
                import java.util.ArrayList;
                import java.util.Arrays;
                import java.util.List;

                class Solution {
                    public List<Boolean> kidsWithCandies(int[] candies, int extraCandies) {
                        int[] sorted = candies.clone();
                        Arrays.sort(sorted);
                        int max = sorted[sorted.length - 1];

                        List<Boolean> answer = new ArrayList<>();
                        for (int candy : candies) {
                            answer.add(candy + extraCandies >= max);
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Sort Copy Maximum Fixture",
                "O(n log n)",
                "O(n)",
                "Sort a copy to find the maximum while preserving the original answer order.",
                "The largest sorted value is the same benchmark used by the linear scan route.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String kidsWithCandiesCountingBucketSolutionEntryJson() {
        String code = """
                import java.util.ArrayList;
                import java.util.List;

                class Solution {
                    public List<Boolean> kidsWithCandies(int[] candies, int extraCandies) {
                        boolean[] present = new boolean[101];
                        for (int candy : candies) {
                            present[candy] = true;
                        }

                        int max = 100;
                        while (!present[max]) {
                            max--;
                        }

                        List<Boolean> answer = new ArrayList<>();
                        for (int candy : candies) {
                            answer.add(candy + extraCandies >= max);
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Counting Bucket Maximum Fixture",
                "O(n+U)",
                "O(U)",
                "Use a bounded presence bucket to find the largest candy count.",
                "The small value range lets the maximum be recovered by scanning buckets from high to low.",
                "- Time Complexity: O(n+U)\\n- Space Complexity: O(U)",
                code);
    }

