    private static String shuffleStringDirectTargetSolutionEntryJson() {
        String code = """
                class Solution {
                    public String restoreString(String s, int[] indices) {
                        char[] answer = new char[s.length()];
                        for (int i = 0; i < s.length(); i++) {
                            answer[indices[i]] = s.charAt(i);
                        }
                        return new String(answer);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Direct Target Array Fixture",
                "O(n)",
                "O(n)",
                "Write every source character directly into its destination slot.",
                "The value indices[i] is a target position, and the permutation guarantee prevents overwrite conflicts.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String shuffleStringInversePermutationSolutionEntryJson() {
        String code = """
                class Solution {
                    public String restoreString(String s, int[] indices) {
                        int n = s.length();
                        int[] source = new int[n];
                        for (int i = 0; i < n; i++) {
                            source[indices[i]] = i;
                        }

                        StringBuilder answer = new StringBuilder(n);
                        for (int target = 0; target < n; target++) {
                            answer.append(s.charAt(source[target]));
                        }
                        return answer.toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Inverse Permutation Builder Fixture",
                "O(n)",
                "O(n)",
                "Build the inverse map from answer position back to source position.",
                "For each target index, the inverse permutation tells which original character should be read.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String shuffleStringSortByDestinationSolutionEntryJson() {
        String code = """
                import java.util.Arrays;

                class Solution {
                    public String restoreString(String s, int[] indices) {
                        int n = s.length();
                        int[][] pairs = new int[n][2];
                        for (int i = 0; i < n; i++) {
                            pairs[i][0] = indices[i];
                            pairs[i][1] = s.charAt(i);
                        }

                        Arrays.sort(pairs, (a, b) -> Integer.compare(a[0], b[0]));
                        StringBuilder answer = new StringBuilder(n);
                        for (int[] pair : pairs) {
                            answer.append((char) pair[1]);
                        }
                        return answer.toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Sort Pairs by Destination Fixture",
                "O(n log n)",
                "O(n)",
                "Sort character-destination pairs by destination before reading the answer.",
                "The restored string is the original characters ordered by their target positions.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String shuffleStringCycleSwapSolutionEntryJson() {
        String code = """
                class Solution {
                    public String restoreString(String s, int[] indices) {
                        char[] letters = s.toCharArray();
                        int[] destinations = indices.clone();

                        for (int i = 0; i < letters.length; i++) {
                            while (destinations[i] != i) {
                                int target = destinations[i];

                                char tempLetter = letters[i];
                                letters[i] = letters[target];
                                letters[target] = tempLetter;

                                int tempDestination = destinations[i];
                                destinations[i] = destinations[target];
                                destinations[target] = tempDestination;
                            }
                        }
                        return new String(letters);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Cycle Swap on Working Arrays Fixture",
                "O(n)",
                "O(n)",
                "Walk permutation cycles by swapping each character toward its destination.",
                "A permutation decomposes into cycles, and each swap places one current item into its final slot.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

