    private static String richestCustomerWealthDirectRowSumSolutionEntryJson() {
        String code = """
                class Solution {
                    public int maximumWealth(int[][] accounts) {
                        int richest = 0;
                        for (int[] customer : accounts) {
                            int wealth = 0;
                            for (int money : customer) {
                                wealth += money;
                            }
                            richest = Math.max(richest, wealth);
                        }
                        return richest;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Direct Row Sum Maximum Fixture",
                "O(m*n)",
                "O(1)",
                "Sum each customer row and update the maximum after every row.",
                "Only the largest row sum is needed, so each temporary row total can be discarded after comparison.",
                "- Time Complexity: O(m*n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String richestCustomerWealthSeparateArraySolutionEntryJson() {
        String code = """
                class Solution {
                    public int maximumWealth(int[][] accounts) {
                        int[] wealth = new int[accounts.length];
                        for (int customer = 0; customer < accounts.length; customer++) {
                            for (int bank = 0; bank < accounts[customer].length; bank++) {
                                wealth[customer] += accounts[customer][bank];
                            }
                        }

                        int richest = wealth[0];
                        for (int customer = 1; customer < wealth.length; customer++) {
                            if (wealth[customer] > richest) {
                                richest = wealth[customer];
                            }
                        }
                        return richest;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Separate Wealth Array Fixture",
                "O(m*n)",
                "O(m)",
                "Store every customer wealth first, then scan the wealth array for the maximum.",
                "This separates row aggregation from maximum selection and is useful when per-customer wealth is reused.",
                "- Time Complexity: O(m*n)\\n- Space Complexity: O(m)",
                code);
    }

    private static String richestCustomerWealthFlattenedScanSolutionEntryJson() {
        String code = """
                class Solution {
                    public int maximumWealth(int[][] accounts) {
                        int m = accounts.length;
                        int n = accounts[0].length;
                        int richest = 0;
                        int rowSum = 0;

                        for (int index = 0; index < m * n; index++) {
                            int row = index / n;
                            int column = index % n;
                            rowSum += accounts[row][column];
                            if (column == n - 1) {
                                richest = Math.max(richest, rowSum);
                                rowSum = 0;
                            }
                        }
                        return richest;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Flattened Matrix Scan Fixture",
                "O(m*n)",
                "O(1)",
                "Traverse the rectangular matrix with one flat index and update the maximum at row boundaries.",
                "The row and column are recovered with division and modulo, connecting 2D traversal to 1D indexing.",
                "- Time Complexity: O(m*n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String richestCustomerWealthRecursiveSolutionEntryJson() {
        String code = """
                class Solution {
                    public int maximumWealth(int[][] accounts) {
                        return richestFrom(accounts, 0);
                    }

                    private int richestFrom(int[][] accounts, int customer) {
                        if (customer == accounts.length) {
                            return 0;
                        }
                        int current = rowWealth(accounts[customer], 0);
                        int later = richestFrom(accounts, customer + 1);
                        return Math.max(current, later);
                    }

                    private int rowWealth(int[] balances, int bank) {
                        if (bank == balances.length) {
                            return 0;
                        }
                        return balances[bank] + rowWealth(balances, bank + 1);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Recursive Customer Scan Fixture",
                "O(m*n)",
                "O(m+n)",
                "Process one customer row recursively and take the maximum with the best value from later rows.",
                "The richest customer relation decomposes into max(current customer wealth, richest later wealth).",
                "- Time Complexity: O(m*n)\\n- Space Complexity: O(m+n)",
                code);
    }

