    private static String decodeXoredArrayPreviousValueSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] decode(int[] encoded, int first) {
                        int[] arr = new int[encoded.length + 1];
                        arr[0] = first;
                        for (int i = 0; i < encoded.length; i++) {
                            arr[i + 1] = arr[i] ^ encoded[i];
                        }
                        return arr;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Previous Value Recurrence Fixture",
                "O(n)",
                "O(n)",
                "Fill the output from left to right using the previous decoded value.",
                "The XOR equation rearranges to arr[i + 1] = arr[i] ^ encoded[i] once arr[i] is known.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String decodeXoredArrayRollingPrefixSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] decode(int[] encoded, int first) {
                        int[] arr = new int[encoded.length + 1];
                        int prefixXor = 0;
                        for (int i = 0; i < arr.length; i++) {
                            arr[i] = first ^ prefixXor;
                            if (i < encoded.length) {
                                prefixXor ^= encoded[i];
                            }
                        }
                        return arr;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Rolling Prefix XOR Formula Fixture",
                "O(n)",
                "O(n)",
                "Track the running XOR of encoded values before the current decoded position.",
                "Expanding the recurrence gives arr[i] as first XOR the prefix XOR before index i.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String decodeXoredArrayExplicitPrefixSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] decode(int[] encoded, int first) {
                        int n = encoded.length + 1;
                        int[] prefix = new int[n];
                        for (int i = 0; i < encoded.length; i++) {
                            prefix[i + 1] = prefix[i] ^ encoded[i];
                        }

                        int[] arr = new int[n];
                        for (int i = 0; i < n; i++) {
                            arr[i] = first ^ prefix[i];
                        }
                        return arr;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Explicit Prefix XOR Array Fixture",
                "O(n)",
                "O(n)",
                "Store every encoded prefix XOR and then convert prefixes into decoded values.",
                "The explicit prefix array makes the algebraic distance from first visible for each position.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String decodeXoredArrayBackwardSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] decode(int[] encoded, int first) {
                        int last = first;
                        for (int value : encoded) {
                            last ^= value;
                        }

                        int[] arr = new int[encoded.length + 1];
                        arr[arr.length - 1] = last;
                        for (int i = encoded.length - 1; i >= 0; i--) {
                            arr[i] = encoded[i] ^ arr[i + 1];
                        }
                        return arr;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Derive Last Then Walk Backward Fixture",
                "O(n)",
                "O(n)",
                "Derive the last original value, then reconstruct the array from right to left.",
                "The XOR edge can recover the left neighbor when the right neighbor is known.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

