    private static String sortingSentenceSplitPlacementSolutionEntryJson() {
        String code = """
                class Solution {
                    public String sortSentence(String s) {
                        String[] tokens = s.split(" ");
                        String[] ordered = new String[tokens.length];
                        for (String token : tokens) {
                            int position = token.charAt(token.length() - 1) - '1';
                            ordered[position] = token.substring(0, token.length() - 1);
                        }
                        return String.join(" ", ordered);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Split And Place By Index Fixture",
                "O(n)",
                "O(n)",
                "Split the shuffled sentence and place each stripped word at its trailing digit index.",
                "The final digit is a direct one-indexed address for the original word position.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String sortingSentenceSortSolutionEntryJson() {
        String code = """
                import java.util.Arrays;

                class Solution {
                    public String sortSentence(String s) {
                        String[] tokens = s.split(" ");
                        Arrays.sort(tokens, (left, right) -> left.charAt(left.length() - 1)
                                - right.charAt(right.length() - 1));

                        StringBuilder answer = new StringBuilder();
                        for (int i = 0; i < tokens.length; i++) {
                            if (i > 0) {
                                answer.append(' ');
                            }
                            answer.append(tokens[i], 0, tokens[i].length() - 1);
                        }
                        return answer.toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Sort Tokens By Trailing Digit Fixture",
                "O(k log k + n)",
                "O(n)",
                "Sort split tokens by their final digit and then strip digits while joining.",
                "The trailing digit is a sort key that restores the original word order.",
                "- Time Complexity: O(k log k + n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String sortingSentenceManualParserSolutionEntryJson() {
        String code = """
                class Solution {
                    public String sortSentence(String s) {
                        String[] slots = new String[9];
                        int wordCount = 0;
                        int start = 0;

                        for (int i = 0; i <= s.length(); i++) {
                            if (i == s.length() || s.charAt(i) == ' ') {
                                int position = s.charAt(i - 1) - '1';
                                slots[position] = s.substring(start, i - 1);
                                wordCount++;
                                start = i + 1;
                            }
                        }

                        StringBuilder answer = new StringBuilder();
                        for (int i = 0; i < wordCount; i++) {
                            if (i > 0) {
                                answer.append(' ');
                            }
                            answer.append(slots[i]);
                        }
                        return answer.toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Manual Token Parser Fixture",
                "O(n)",
                "O(n)",
                "Scan token boundaries manually and place substrings by their trailing digit.",
                "The single-space format and single trailing digit are enough to parse without split.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String sortingSentenceStreamingBuilderSolutionEntryJson() {
        String code = """
                class Solution {
                    public String sortSentence(String s) {
                        StringBuilder[] slots = new StringBuilder[9];
                        StringBuilder current = new StringBuilder();
                        int wordCount = 0;

                        for (int i = 0; i < s.length(); i++) {
                            char ch = s.charAt(i);
                            if (ch == ' ') {
                                current.setLength(0);
                            } else if (ch >= '1' && ch <= '9') {
                                slots[ch - '1'] = new StringBuilder(current);
                                wordCount++;
                                current.setLength(0);
                            } else {
                                current.append(ch);
                            }
                        }

                        StringBuilder answer = new StringBuilder();
                        for (int i = 0; i < wordCount; i++) {
                            if (i > 0) {
                                answer.append(' ');
                            }
                            answer.append(slots[i]);
                        }
                        return answer.toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Streaming Builder Slots Fixture",
                "O(n)",
                "O(n)",
                "Build each word while scanning characters and copy it into the slot named by the digit.",
                "This route avoids token substring creation while still using the digit as a destination slot.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

