    private static String concatenationArraySinglePassSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] getConcatenation(int[] nums) {
                        int n = nums.length;
                        int[] ans = new int[2 * n];
                        for (int i = 0; i < n; i++) {
                            ans[i] = nums[i];
                            ans[i + n] = nums[i];
                        }
                        return ans;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Single Pass Dual Write Fixture",
                "O(n)",
                "O(n)",
                "Write each input value into both answer positions during one pass over nums.",
                "The duplicate target index is always exactly n positions after the original target index.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String concatenationArrayTwoPassSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] getConcatenation(int[] nums) {
                        int n = nums.length;
                        int[] ans = new int[2 * n];

                        for (int i = 0; i < n; i++) {
                            ans[i] = nums[i];
                        }
                        for (int i = 0; i < n; i++) {
                            ans[i + n] = nums[i];
                        }
                        return ans;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Two Pass Offset Copy Fixture",
                "O(n)",
                "O(n)",
                "Copy the input into the front half first, then copy the same input into the second half.",
                "The answer is two explicit halves with the same contents, separated by offset n.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String concatenationArraySystemArraycopySolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] getConcatenation(int[] nums) {
                        int n = nums.length;
                        int[] ans = new int[2 * n];
                        System.arraycopy(nums, 0, ans, 0, n);
                        System.arraycopy(nums, 0, ans, n, n);
                        return ans;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "System Arraycopy Twice Fixture",
                "O(n)",
                "O(n)",
                "Use the standard library to copy the same contiguous input block into the two answer halves.",
                "This problem is exactly two block-copy operations, so System.arraycopy matches the data movement.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String concatenationArrayModuloFillSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] getConcatenation(int[] nums) {
                        int n = nums.length;
                        int[] ans = new int[2 * n];
                        for (int i = 0; i < ans.length; i++) {
                            ans[i] = nums[i % n];
                        }
                        return ans;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Modulo Output Index Fill Fixture",
                "O(n)",
                "O(n)",
                "Fill the whole output left to right and map each output index back to nums with modulo.",
                "The output is two cycles through nums, and i modulo n selects the matching source index.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

