    private static String maximumWordsSentencesSplitSolutionEntryJson() {
        String code = """
                class Solution {
                    public int mostWordsFound(String[] sentences) {
                        int maxWords = 0;
                        for (String sentence : sentences) {
                            maxWords = Math.max(maxWords, sentence.split(" ").length);
                        }
                        return maxWords;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Split Each Sentence Fixture",
                "O(n*m)",
                "O(m)",
                "Split each valid sentence on spaces and use the resulting token-array length as the word count.",
                "The input contract guarantees that every split token is a word because there are no leading, "
                        + "trailing, or repeated spaces.",
                "- Time Complexity: O(n*m)\\n- Space Complexity: O(m)",
                code);
    }

    private static String maximumWordsSentencesManualSpaceSolutionEntryJson() {
        String code = """
                class Solution {
                    public int mostWordsFound(String[] sentences) {
                        int maxWords = 0;
                        for (String sentence : sentences) {
                            int words = 1;
                            for (int i = 0; i < sentence.length(); i++) {
                                if (sentence.charAt(i) == ' ') {
                                    words++;
                                }
                            }
                            maxWords = Math.max(maxWords, words);
                        }
                        return maxWords;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Manual Space Count Fixture",
                "O(n*m)",
                "O(1)",
                "Start each valid sentence at one word and add one for every space character encountered.",
                "A legal sentence has exactly one separator between adjacent words, so words are spaces plus one.",
                "- Time Complexity: O(n*m)\\n- Space Complexity: O(1)",
                code);
    }

    private static String maximumWordsSentencesIndexOfSolutionEntryJson() {
        String code = """
                class Solution {
                    public int mostWordsFound(String[] sentences) {
                        int maxWords = 0;
                        for (String sentence : sentences) {
                            int words = 1;
                            int start = 0;
                            int next = sentence.indexOf(' ', start);
                            while (next != -1) {
                                words++;
                                start = next + 1;
                                next = sentence.indexOf(' ', start);
                            }
                            maxWords = Math.max(maxWords, words);
                        }
                        return maxWords;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "IndexOf Separator Search Fixture",
                "O(n*m)",
                "O(1)",
                "Jump from one space separator to the next using indexOf and count the separators found.",
                "This route keeps the separator-count model while delegating the character search to the standard "
                        + "library.",
                "- Time Complexity: O(n*m)\\n- Space Complexity: O(1)",
                code);
    }

    private static String maximumWordsSentencesLengthDifferenceSolutionEntryJson() {
        String code = """
                class Solution {
                    public int mostWordsFound(String[] sentences) {
                        int maxWords = 0;
                        for (String sentence : sentences) {
                            int spaces = sentence.length() - sentence.replace(" ", "").length();
                            maxWords = Math.max(maxWords, spaces + 1);
                        }
                        return maxWords;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Length Difference Space Count Fixture",
                "O(n*m)",
                "O(m)",
                "Remove spaces and compare string lengths to find how many separators the sentence contained.",
                "The number of words depends on the separator count rather than the lengths of the words themselves.",
                "- Time Complexity: O(n*m)\\n- Space Complexity: O(m)",
                code);
    }

