    private static String convertTemperatureAffineTableSolutionEntryJson() {
        String code = """
                class Solution {
                    public double[] convertTemperature(double celsius) {
                        double[] scales = {1.0, 1.80};
                        double[] offsets = {273.15, 32.00};
                        double[] answer = new double[2];
                        for (int i = 0; i < 2; i++) {
                            answer[i] = scales[i] * celsius + offsets[i];
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Affine Conversion Table Fixture",
                "O(1)",
                "O(1)",
                "Represent both conversions as scale times Celsius plus an offset and apply them with a small table.",
                "Both conversions share the same affine shape even though their constants differ.",
                "- Time Complexity: O(1)\\n- Space Complexity: O(1)",
                code);
    }

    private static String convertTemperatureConstantsHelpersSolutionEntryJson() {
        String code = """
                class Solution {
                    private static final double KELVIN_OFFSET = 273.15;
                    private static final double FAHRENHEIT_SCALE = 1.80;
                    private static final double FAHRENHEIT_OFFSET = 32.00;

                    public double[] convertTemperature(double celsius) {
                        return new double[]{toKelvin(celsius), toFahrenheit(celsius)};
                    }

                    private double toKelvin(double celsius) {
                        return celsius + KELVIN_OFFSET;
                    }

                    private double toFahrenheit(double celsius) {
                        return celsius * FAHRENHEIT_SCALE + FAHRENHEIT_OFFSET;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Named Constants And Helpers Fixture",
                "O(1)",
                "O(1)",
                "Move conversion constants into named fields and use helpers for each target unit.",
                "Named constants explain the numeric values while helper methods keep the result order visible.",
                "- Time Complexity: O(1)\\n- Space Complexity: O(1)",
                code);
    }

