    private static String findWordsContainingCharacterManualScanSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public List<Integer> findWordsContaining(String[] words, char x) {
                        List<Integer> indices = new ArrayList<>();
                        for (int i = 0; i < words.length; i++) {
                            if (contains(words[i], x)) {
                                indices.add(i);
                            }
                        }
                        return indices;
                    }

                    private boolean contains(String word, char x) {
                        for (int j = 0; j < word.length(); j++) {
                            if (word.charAt(j) == x) {
                                return true;
                            }
                        }
                        return false;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Manual Character Scan Fixture",
                "O(n*m)",
                "O(1)",
                "Scan each word with a helper method and stop after the first matching character.",
                "Once one x is found in a word, the word contributes exactly one index to the result.",
                "- Time Complexity: O(n*m)\\n- Space Complexity: O(1)",
                code);
    }

    private static String findWordsContainingCharacterBitmaskSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public List<Integer> findWordsContaining(String[] words, char x) {
                        List<Integer> indices = new ArrayList<>();
                        int targetMask = 1 << (x - 'a');
                        for (int i = 0; i < words.length; i++) {
                            int mask = 0;
                            for (int j = 0; j < words[i].length(); j++) {
                                mask |= 1 << (words[i].charAt(j) - 'a');
                            }
                            if ((mask & targetMask) != 0) {
                                indices.add(i);
                            }
                        }
                        return indices;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Bitmask Per Word Fixture",
                "O(n*m)",
                "O(1)",
                "Build a fixed 26-bit letter mask for each word and test the bit belonging to x.",
                "Lowercase-letter constraints allow membership to be represented as a constant-size bit check.",
                "- Time Complexity: O(n*m)\\n- Space Complexity: O(1)",
                code);
    }

    private static String findWordsContainingCharacterLabeledLoopSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public List<Integer> findWordsContaining(String[] words, char x) {
                        List<Integer> indices = new ArrayList<>();
                        outer:
                        for (int i = 0; i < words.length; i++) {
                            String word = words[i];
                            for (int j = 0; j < word.length(); j++) {
                                if (word.charAt(j) == x) {
                                    indices.add(i);
                                    continue outer;
                                }
                            }
                        }
                        return indices;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Labeled Loop Early Exit Fixture",
                "O(n*m)",
                "O(1)",
                "Use a labeled loop so the first match in a word jumps directly to the next word.",
                "The labeled continue prevents duplicate indices when x appears multiple times in one word.",
                "- Time Complexity: O(n*m)\\n- Space Complexity: O(1)",
                code);
    }

