    private static String employeesMetTargetSortLowerBoundSolutionEntryJson() {
        String code = """
                import java.util.Arrays;

                class Solution {
                    public int numberOfEmployeesWhoMetTarget(int[] hours, int target) {
                        Arrays.sort(hours);
                        int left = 0;
                        int right = hours.length;
                        while (left < right) {
                            int mid = left + (right - left) / 2;
                            if (hours[mid] >= target) {
                                right = mid;
                            } else {
                                left = mid + 1;
                            }
                        }
                        return hours.length - left;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Sort And Lower Bound Fixture",
                "O(n log n)",
                "O(1)",
                "Sort hours and binary-search for the first value at least target.",
                "After sorting, the qualifying employees form one suffix of the array.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(1)",
                code);
    }

