    private static String countPairsSumLessTargetBruteForceSolutionEntryJson() {
        String code = """
                class Solution {
                    public int countPairs(int[] nums, int target) {
                        int count = 0;
                        for (int i = 0; i < nums.length; i++) {
                            for (int j = i + 1; j < nums.length; j++) {
                                if (nums[i] + nums[j] < target) {
                                    count++;
                                }
                            }
                        }
                        return count;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Brute Force Pairs Fixture",
                "O(n^2)",
                "O(1)",
                "Inspect every index pair i less than j and count sums strictly below target.",
                "This direct route mirrors the statement and keeps the strict inequality visible.",
                "- Time Complexity: O(n^2)\\n- Space Complexity: O(1)",
                code);
    }

    private static String countPairsSumLessTargetTwoPointerSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int countPairs(int[] nums, int target) {
                        Arrays.sort(nums);
                        int left = 0;
                        int right = nums.length - 1;
                        int count = 0;
                        while (left < right) {
                            if (nums[left] + nums[right] < target) {
                                count += right - left;
                                left++;
                            } else {
                                right--;
                            }
                        }
                        return count;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Sort And Two Pointers Fixture",
                "O(n log n)",
                "O(1)",
                "Sort values and count whole valid blocks with a left and right pointer.",
                "When the largest partner works with left, every smaller partner also works.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String countPairsSumLessTargetBinarySearchSolutionEntryJson() {
        String code = """
                import java.util.Arrays;

                class Solution {
                    public int countPairs(int[] nums, int target) {
                        Arrays.sort(nums);
                        int count = 0;
                        for (int i = 0; i < nums.length; i++) {
                            int limit = target - nums[i];
                            int left = i + 1;
                            int right = nums.length;
                            while (left < right) {
                                int mid = left + (right - left) / 2;
                                if (nums[mid] < limit) {
                                    left = mid + 1;
                                } else {
                                    right = mid;
                                }
                            }
                            count += left - i - 1;
                        }
                        return count;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Sort And Binary Search Fixture",
                "O(n log n)",
                "O(1)",
                "For each left index, binary-search the first partner that fails the strict inequality.",
                "For fixed nums[i], valid partners are exactly the values below target minus nums[i].",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String countPairsSumLessTargetFrequencySolutionEntryJson() {
        String code = """
                class Solution {
                    public int countPairs(int[] nums, int target) {
                        int[] frequency = new int[101];
                        for (int value : nums) {
                            frequency[value + 50]++;
                        }

                        int answer = 0;
                        for (int a = 0; a < frequency.length; a++) {
                            if (frequency[a] == 0) {
                                continue;
                            }
                            int valueA = a - 50;
                            for (int b = a; b < frequency.length; b++) {
                                if (frequency[b] == 0) {
                                    continue;
                                }
                                int valueB = b - 50;
                                if (valueA + valueB >= target) {
                                    continue;
                                }
                                if (a == b) {
                                    answer += frequency[a] * (frequency[a] - 1) / 2;
                                } else {
                                    answer += frequency[a] * frequency[b];
                                }
                            }
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Bounded Value Frequency Count Fixture",
                "O(n + U^2)",
                "O(U)",
                "Count occurrences of each value from -50 to 50 and enumerate value pairs.",
                "Grouping by value lets one value-pair calculation stand for many index pairs.",
                "- Time Complexity: O(n + U^2)\\n- Space Complexity: O(U)",
                code);
    }

