    private static String faultyKeyboardDequeDirectionSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public String finalString(String s) {
                        Deque<Character> deque = new ArrayDeque<>();
                        boolean reversed = false;
                        for (int index = 0; index < s.length(); index++) {
                            char c = s.charAt(index);
                            if (c == 'i') {
                                reversed = !reversed;
                            } else if (reversed) {
                                deque.addFirst(c);
                            } else {
                                deque.addLast(c);
                            }
                        }
                        StringBuilder answer = new StringBuilder();
                        if (!reversed) {
                            while (!deque.isEmpty()) {
                                answer.append(deque.removeFirst());
                            }
                        } else {
                            while (!deque.isEmpty()) {
                                answer.append(deque.removeLast());
                            }
                        }
                        return answer.toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Deque Direction Simulation Fixture",
                "O(n)",
                "O(n)",
                "Use a deque and a direction flag so a faulty i toggles orientation instead of moving text.",
                "When orientation flips, future characters should be inserted at the opposite end.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String faultyKeyboardTwoBufferSolutionEntryJson() {
        String code = """
                class Solution {
                    public String finalString(String s) {
                        StringBuilder front = new StringBuilder();
                        StringBuilder back = new StringBuilder();
                        boolean reversed = false;
                        for (int index = 0; index < s.length(); index++) {
                            char c = s.charAt(index);
                            if (c == 'i') {
                                reversed = !reversed;
                            } else if (reversed) {
                                front.append(c);
                            } else {
                                back.append(c);
                            }
                        }
                        if (!reversed) {
                            return front.reverse().append(back).toString();
                        }
                        return back.reverse().append(front).toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Two Buffer Direction Merge Fixture",
                "O(n)",
                "O(n)",
                "Separate characters typed in reversed phases from characters typed in normal phases.",
                "The final direction decides which buffer must be reversed before the two pieces are merged.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String faultyKeyboardRunDequeSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public String finalString(String s) {
                        Deque<String> blocks = new ArrayDeque<>();
                        StringBuilder run = new StringBuilder();
                        boolean reversed = false;
                        for (int index = 0; index < s.length(); index++) {
                            char c = s.charAt(index);
                            if (c == 'i') {
                                flushRun(blocks, run, reversed);
                                reversed = !reversed;
                            } else {
                                run.append(c);
                            }
                        }
                        flushRun(blocks, run, reversed);
                        StringBuilder answer = new StringBuilder();
                        if (!reversed) {
                            for (String block : blocks) {
                                answer.append(block);
                            }
                        } else {
                            Iterator<String> iterator = blocks.descendingIterator();
                            while (iterator.hasNext()) {
                                answer.append(new StringBuilder(iterator.next()).reverse());
                            }
                        }
                        return answer.toString();
                    }

                    private void flushRun(Deque<String> blocks, StringBuilder run, boolean reversed) {
                        if (run.length() == 0) {
                            return;
                        }
                        if (reversed) {
                            blocks.addFirst(run.reverse().toString());
                        } else {
                            blocks.addLast(run.toString());
                        }
                        run.setLength(0);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Run Deque Deferred Reversal Fixture",
                "O(n)",
                "O(n)",
                "Group consecutive non-i characters into runs and place each run according to current direction.",
                "This route teaches the same orientation invariant as the deque solution at a run granularity.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

