    private static String splitBalancedStringsCancellationStackSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int balancedStringSplit(String s) {
                        Deque<Character> stack = new ArrayDeque<>();
                        int pieces = 0;
                        for (int i = 0; i < s.length(); i++) {
                            char c = s.charAt(i);
                            if (stack.isEmpty() || stack.peek() == c) {
                                stack.push(c);
                            } else {
                                stack.pop();
                            }
                            if (stack.isEmpty()) {
                                pieces++;
                            }
                        }
                        return pieces;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Cancellation Stack Fixture",
                "O(n)",
                "O(n)",
                "Use a stack to cancel opposite L/R characters until the current substring becomes empty.",
                "An empty stack is a concrete model for equal numbers of unmatched L and R characters.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

