    private static String decompressRleListArraysFillSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int[] decompressRLElist(int[] nums) {
                        int length = 0;
                        for (int i = 0; i < nums.length; i += 2) {
                            length += nums[i];
                        }
                        int[] ans = new int[length];
                        int index = 0;
                        for (int i = 0; i < nums.length; i += 2) {
                            int freq = nums[i];
                            int value = nums[i + 1];
                            Arrays.fill(ans, index, index + freq, value);
                            index += freq;
                        }
                        return ans;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Arrays Fill By Runs Fixture",
                "O(n + m)",
                "O(m)",
                "Use Arrays.fill to expand each encoded pair as one contiguous output run.",
                "A run-length pair describes a whole segment, so filling the segment directly matches the encoding.",
                "- Time Complexity: O(n + m)\\n- Space Complexity: O(m)",
                code);
    }

    private static String decompressRleListPrefixStartsSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] decompressRLElist(int[] nums) {
                        int pairs = nums.length / 2;
                        int[] starts = new int[pairs + 1];
                        for (int pair = 0; pair < pairs; pair++) {
                            starts[pair + 1] = starts[pair] + nums[2 * pair];
                        }
                        int[] ans = new int[starts[pairs]];
                        for (int pair = 0; pair < pairs; pair++) {
                            int value = nums[2 * pair + 1];
                            for (int index = starts[pair]; index < starts[pair + 1]; index++) {
                                ans[index] = value;
                            }
                        }
                        return ans;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Prefix Run Starts Fixture",
                "O(n + m)",
                "O(n + m)",
                "Build prefix start offsets for every run, then fill each stored output interval.",
                "Prefix starts convert frequencies into concrete output ranges for each encoded pair.",
                "- Time Complexity: O(n + m)\\n- Space Complexity: O(n + m)",
                code);
    }

