    private static String goodPairsBruteForceSolutionEntryJson() {
        String code = """
                class Solution {
                    public int numIdenticalPairs(int[] nums) {
                        int pairs = 0;
                        for (int i = 0; i < nums.length; i++) {
                            for (int j = i + 1; j < nums.length; j++) {
                                if (nums[i] == nums[j]) {
                                    pairs++;
                                }
                            }
                        }
                        return pairs;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Brute Force Pair Enumeration Fixture",
                "O(n^2)",
                "O(1)",
                "Try every pair i < j and count it when the two values match.",
                "This route follows the definition directly and is the simplest correctness baseline.",
                "- Time Complexity: O(n^2)\\n- Space Complexity: O(1)",
                code);
    }

    private static String goodPairsOnlineFrequencySolutionEntryJson() {
        String code = """
                class Solution {
                    public int numIdenticalPairs(int[] nums) {
                        int[] frequency = new int[101];
                        int pairs = 0;
                        for (int value : nums) {
                            pairs += frequency[value];
                            frequency[value]++;
                        }
                        return pairs;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Online Frequency Counting Fixture",
                "O(n)",
                "O(1)",
                "Scan left to right and count pairs by the current index as the right endpoint.",
                "Each previous equal value forms exactly one new pair with the current value.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String goodPairsCombinationCountSolutionEntryJson() {
        String code = """
                class Solution {
                    public int numIdenticalPairs(int[] nums) {
                        int[] frequency = new int[101];
                        for (int value : nums) {
                            frequency[value]++;
                        }

                        int pairs = 0;
                        for (int count : frequency) {
                            pairs += count * (count - 1) / 2;
                        }
                        return pairs;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Combination Count Per Value Fixture",
                "O(n + U)",
                "O(1)",
                "Count every value first, then add count choose two for each equal-value group.",
                "Good pairs depend only on how many indices have each value once the group is known.",
                "- Time Complexity: O(n + U)\\n- Space Complexity: O(1)",
                code);
    }

    private static String goodPairsSortedRunSolutionEntryJson() {
        String code = """
                import java.util.Arrays;

                class Solution {
                    public int numIdenticalPairs(int[] nums) {
                        Arrays.sort(nums);
                        int pairs = 0;
                        int runLength = 1;

                        for (int i = 1; i < nums.length; i++) {
                            if (nums[i] == nums[i - 1]) {
                                runLength++;
                            } else {
                                pairs += runLength * (runLength - 1) / 2;
                                runLength = 1;
                            }
                        }
                        pairs += runLength * (runLength - 1) / 2;
                        return pairs;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Sort And Count Equal Runs Fixture",
                "O(n log n)",
                "O(1)",
                "Sort values so equal numbers are adjacent, then count each equal run.",
                "Sorting reveals frequency groups without using a value-indexed frequency table.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(1)",
                code);
    }

