    private static String parkingSystemArrayRemainingSolutionEntryJson() {
        String code = """
                class ParkingSystem {
                    private final int[] remaining;

                    public ParkingSystem(int big, int medium, int small) {
                        remaining = new int[]{big, medium, small};
                    }

                    public boolean addCar(int carType) {
                        int index = carType - 1;
                        if (remaining[index] == 0) {
                            return false;
                        }
                        remaining[index]--;
                        return true;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Array Remaining Slots Fixture",
                "O(1)",
                "O(1)",
                "Store the remaining capacity for the three car types in an array.",
                "The selected car type maps directly to index carType - 1, and only that counter changes.",
                "- Time Complexity: O(1)\\n- Space Complexity: O(1)",
                code);
    }

    private static String parkingSystemExplicitFieldsSolutionEntryJson() {
        String code = """
                class ParkingSystem {
                    private int big;
                    private int medium;
                    private int small;

                    public ParkingSystem(int big, int medium, int small) {
                        this.big = big;
                        this.medium = medium;
                        this.small = small;
                    }

                    public boolean addCar(int carType) {
                        if (carType == 1) {
                            if (big == 0) return false;
                            big--;
                            return true;
                        }
                        if (carType == 2) {
                            if (medium == 0) return false;
                            medium--;
                            return true;
                        }
                        if (small == 0) return false;
                        small--;
                        return true;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Explicit Fields And Branches Fixture",
                "O(1)",
                "O(1)",
                "Keep big, medium, and small as separate fields and branch on carType.",
                "Named fields make each state transition explicit for a fixed small set of parking types.",
                "- Time Complexity: O(1)\\n- Space Complexity: O(1)",
                code);
    }

    private static String parkingSystemMapBackedSolutionEntryJson() {
        String code = """
                import java.util.HashMap;
                import java.util.Map;

                class ParkingSystem {
                    private final Map<Integer, Integer> remaining = new HashMap<>();

                    public ParkingSystem(int big, int medium, int small) {
                        remaining.put(1, big);
                        remaining.put(2, medium);
                        remaining.put(3, small);
                    }

                    public boolean addCar(int carType) {
                        int slots = remaining.get(carType);
                        if (slots == 0) {
                            return false;
                        }
                        remaining.put(carType, slots - 1);
                        return true;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Map Backed Capacity Fixture",
                "O(1)",
                "O(1)",
                "Use a map from car type to remaining capacity.",
                "The car type becomes a key that selects exactly one mutable state bucket.",
                "- Time Complexity: O(1)\\n- Space Complexity: O(1)",
                code);
    }

