    private static String stringArrayEquivalentCharStreamSolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean arrayStringsAreEqual(String[] word1, String[] word2) {
                        CharStream left = new CharStream(word1);
                        CharStream right = new CharStream(word2);
                        while (left.hasNext() && right.hasNext()) {
                            if (left.next() != right.next()) {
                                return false;
                            }
                        }
                        return !left.hasNext() && !right.hasNext();
                    }

                    private static class CharStream {
                        private final String[] words;
                        private int wordIndex;
                        private int charIndex;

                        CharStream(String[] words) {
                            this.words = words;
                        }

                        boolean hasNext() {
                            return wordIndex < words.length;
                        }

                        char next() {
                            char current = words[wordIndex].charAt(charIndex);
                            charIndex++;
                            if (charIndex == words[wordIndex].length()) {
                                wordIndex++;
                                charIndex = 0;
                            }
                            return current;
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Chunk Character Stream Fixture",
                "O(n)",
                "O(1)",
                "Wrap each chunk array in a stream helper and compare the next character from each stream.",
                "The helper owns chunk-boundary traversal while the main loop reads as stream equality.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String stringArrayEquivalentCharacterQueueSolutionEntryJson() {
        String code = """
                import java.util.ArrayDeque;
                import java.util.Deque;

                class Solution {
                    public boolean arrayStringsAreEqual(String[] word1, String[] word2) {
                        Deque<Character> left = toQueue(word1);
                        Deque<Character> right = toQueue(word2);
                        while (!left.isEmpty() && !right.isEmpty()) {
                            if (left.removeFirst() != right.removeFirst()) {
                                return false;
                            }
                        }
                        return left.isEmpty() && right.isEmpty();
                    }

                    private Deque<Character> toQueue(String[] words) {
                        Deque<Character> queue = new ArrayDeque<>();
                        for (String word : words) {
                            for (int i = 0; i < word.length(); i++) {
                                queue.addLast(word.charAt(i));
                            }
                        }
                        return queue;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Character Queues Fixture",
                "O(n)",
                "O(n)",
                "Expand each represented string into a queue and compare characters from the front.",
                "The queue route models each represented string as an ordered stream before optimizing memory.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

