    private static String prefixCommonArraySharedCounterSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] findThePrefixCommonArray(int[] A, int[] B) {
                        int n = A.length;
                        int[] seen = new int[n + 1];
                        int[] answer = new int[n];
                        int common = 0;
                        for (int i = 0; i < n; i++) {
                            seen[A[i]]++;
                            if (seen[A[i]] == 2) {
                                common++;
                            }
                            seen[B[i]]++;
                            if (seen[B[i]] == 2) {
                                common++;
                            }
                            answer[i] = common;
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Shared Occurrence Counter Fixture",
                "O(n)",
                "O(n)",
                "Use one shared occurrence counter and count values when their counter reaches two.",
                "Each permutation contributes a value once, so reaching two means the value is in both prefixes.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String prefixCommonArrayTwoSeenArraysSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] findThePrefixCommonArray(int[] A, int[] B) {
                        int n = A.length;
                        boolean[] seenA = new boolean[n + 1];
                        boolean[] seenB = new boolean[n + 1];
                        int[] answer = new int[n];
                        int common = 0;
                        for (int i = 0; i < n; i++) {
                            int left = A[i];
                            int right = B[i];
                            seenA[left] = true;
                            seenB[right] = true;
                            if (seenB[left]) {
                                common++;
                            }
                            if (left != right && seenA[right]) {
                                common++;
                            }
                            answer[i] = common;
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Two Seen Arrays Fixture",
                "O(n)",
                "O(n)",
                "Track seen values from A and B separately and only inspect newly added values.",
                "Only A[i] and B[i] can become newly common at step i, with equal values counted once.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String prefixCommonArraySetIntersectionSolutionEntryJson() {
        String code = """
                import java.util.HashSet;
                import java.util.Set;

                class Solution {
                    public int[] findThePrefixCommonArray(int[] A, int[] B) {
                        int n = A.length;
                        int[] answer = new int[n];
                        Set<Integer> seenA = new HashSet<>();
                        Set<Integer> seenB = new HashSet<>();
                        for (int i = 0; i < n; i++) {
                            seenA.add(A[i]);
                            seenB.add(B[i]);
                            int common = 0;
                            for (int value : seenA) {
                                if (seenB.contains(value)) {
                                    common++;
                                }
                            }
                            answer[i] = common;
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Set Intersection Per Prefix Fixture",
                "O(n^2)",
                "O(n)",
                "Maintain both prefix sets and recount their intersection after each index.",
                "This route follows the definition of the answer directly and is a correctness baseline.",
                "- Time Complexity: O(n^2)\\n- Space Complexity: O(n)",
                code);
    }

    private static String prefixCommonArrayFenwickSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] findThePrefixCommonArray(int[] A, int[] B) {
                        int n = A.length;
                        int[] positionInB = new int[n + 1];
                        for (int i = 0; i < n; i++) {
                            positionInB[B[i]] = i;
                        }
                        Fenwick tree = new Fenwick(n);
                        int[] answer = new int[n];
                        for (int i = 0; i < n; i++) {
                            tree.add(positionInB[A[i]], 1);
                            answer[i] = tree.sum(i);
                        }
                        return answer;
                    }

                    private static class Fenwick {
                        private final int[] tree;

                        Fenwick(int n) {
                            tree = new int[n + 1];
                        }

                        void add(int index, int delta) {
                            for (int i = index + 1; i < tree.length; i += i & -i) {
                                tree[i] += delta;
                            }
                        }

                        int sum(int index) {
                            int total = 0;
                            for (int i = index + 1; i > 0; i -= i & -i) {
                                total += tree[i];
                            }
                            return total;
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Fenwick Tree On B Positions Fixture",
                "O(n log n)",
                "O(n)",
                "Map each value to its B position and query how many added A values lie inside B's prefix.",
                "A value from A's prefix is common exactly when its position in B is at most the current index.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

