    private static String consistentStringsBooleanTableSolutionEntryJson() {
        String code = """
                class Solution {
                    public int countConsistentStrings(String allowed, String[] words) {
                        boolean[] allowedTable = new boolean[26];
                        for (int i = 0; i < allowed.length(); i++) {
                            allowedTable[allowed.charAt(i) - 'a'] = true;
                        }

                        int count = 0;
                        for (String word : words) {
                            boolean consistent = true;
                            for (int i = 0; i < word.length(); i++) {
                                if (!allowedTable[word.charAt(i) - 'a']) {
                                    consistent = false;
                                    break;
                                }
                            }
                            if (consistent) {
                                count++;
                            }
                        }
                        return count;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Boolean Allowed Table Fixture",
                "O(A + L)",
                "O(1)",
                "Mark the 26 lowercase letters allowed by the prompt and reject a word at its first unmarked character.",
                "The alphabet size is fixed, so a table lookup is enough to test every character membership.",
                "- Time Complexity: O(A + L)\\n- Space Complexity: O(1)",
                code);
    }

    private static String consistentStringsBitmaskSubsetSolutionEntryJson() {
        String code = """
                class Solution {
                    public int countConsistentStrings(String allowed, String[] words) {
                        int allowedMask = 0;
                        for (int i = 0; i < allowed.length(); i++) {
                            allowedMask |= 1 << (allowed.charAt(i) - 'a');
                        }

                        int count = 0;
                        for (String word : words) {
                            int wordMask = 0;
                            for (int i = 0; i < word.length(); i++) {
                                wordMask |= 1 << (word.charAt(i) - 'a');
                            }
                            if ((wordMask & ~allowedMask) == 0) {
                                count++;
                            }
                        }
                        return count;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Bitmask Subset Fixture",
                "O(A + L)",
                "O(1)",
                "Build a mask for allowed and a mask for each word, then check whether the word has outside bits.",
                "A consistent word has a character set that is a subset of the allowed character set.",
                "- Time Complexity: O(A + L)\\n- Space Complexity: O(1)",
                code);
    }

    private static String consistentStringsHashSetMembershipSolutionEntryJson() {
        String code = """
                import java.util.HashSet;
                import java.util.Set;

                class Solution {
                    public int countConsistentStrings(String allowed, String[] words) {
                        Set<Character> allowedSet = new HashSet<>();
                        for (int i = 0; i < allowed.length(); i++) {
                            allowedSet.add(allowed.charAt(i));
                        }

                        int count = 0;
                        for (String word : words) {
                            boolean consistent = true;
                            for (int i = 0; i < word.length(); i++) {
                                if (!allowedSet.contains(word.charAt(i))) {
                                    consistent = false;
                                    break;
                                }
                            }
                            if (consistent) {
                                count++;
                            }
                        }
                        return count;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "HashSet Membership Fixture",
                "O(A + L)",
                "O(1)",
                "Insert allowed characters into a HashSet and check each word with membership lookups.",
                "This is the general set-model version, with constant extra space because lowercase letters are bounded.",
                "- Time Complexity: O(A + L)\\n- Space Complexity: O(1)",
                code);
    }

