    private static String truncateSentenceSpaceCountCutSolutionEntryJson() {
        String code = """
                class Solution {
                    public String truncateSentence(String s, int k) {
                        int spaces = 0;
                        for (int i = 0; i < s.length(); i++) {
                            if (s.charAt(i) == ' ') {
                                spaces++;
                                if (spaces == k) {
                                    return s.substring(0, i);
                                }
                            }
                        }
                        return s;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Count Spaces And Cut Fixture",
                "O(n)",
                "O(1)",
                "Scan spaces and return the substring before the space that follows the kth word.",
                "Single spaces and no leading spaces make the kth space the exact cut point after k words.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String truncateSentenceSplitJoinSolutionEntryJson() {
        String code = """
                class Solution {
                    public String truncateSentence(String s, int k) {
                        String[] words = s.split(" ");
                        StringBuilder answer = new StringBuilder();
                        for (int i = 0; i < k; i++) {
                            if (i > 0) {
                                answer.append(' ');
                            }
                            answer.append(words[i]);
                        }
                        return answer.toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Split And Join Prefix Fixture",
                "O(n)",
                "O(n)",
                "Split into words and rebuild the first k words with exactly one space between them.",
                "After splitting, truncation is simply taking a prefix of the word array.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String truncateSentenceStreamingCopySolutionEntryJson() {
        String code = """
                class Solution {
                    public String truncateSentence(String s, int k) {
                        StringBuilder answer = new StringBuilder();
                        int completedWords = 0;
                        for (int i = 0; i < s.length(); i++) {
                            char current = s.charAt(i);
                            if (current == ' ') {
                                completedWords++;
                                if (completedWords == k) {
                                    break;
                                }
                            }
                            answer.append(current);
                        }
                        return answer.toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Copy Characters Until K Words Fixture",
                "O(n)",
                "O(n)",
                "Copy characters into a builder and stop before appending the space after the kth completed word.",
                "The streaming scan constructs only the needed prefix without storing every split word.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

