    private static String reversePrefixStringBuilderSolutionEntryJson() {
        String code = """
                class Solution {
                    public String reversePrefix(String word, char ch) {
                        int index = word.indexOf(ch);
                        if (index == -1) {
                            return word;
                        }
                        StringBuilder prefix = new StringBuilder(word.substring(0, index + 1));
                        prefix.reverse();
                        return prefix.append(word.substring(index + 1)).toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "StringBuilder Prefix Reverse Fixture",
                "O(n)",
                "O(n)",
                "Find the first target index, reverse the prefix with StringBuilder, and append the suffix.",
                "Once the first occurrence is known, later target characters do not affect the prefix boundary.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String reversePrefixTwoPointerSolutionEntryJson() {
        String code = """
                class Solution {
                    public String reversePrefix(String word, char ch) {
                        char[] chars = word.toCharArray();
                        int end = -1;
                        for (int i = 0; i < chars.length; i++) {
                            if (chars[i] == ch) {
                                end = i;
                                break;
                            }
                        }
                        if (end == -1) {
                            return word;
                        }
                        int left = 0;
                        int right = end;
                        while (left < right) {
                            char temp = chars[left];
                            chars[left++] = chars[right];
                            chars[right--] = temp;
                        }
                        return new String(chars);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Two Pointer Char Swap Fixture",
                "O(n)",
                "O(n)",
                "Copy the word to a char array and swap characters inside the target prefix with two pointers.",
                "Restricting swaps to the prefix preserves the suffix without extra boundary logic.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String reversePrefixManualBuilderSolutionEntryJson() {
        String code = """
                class Solution {
                    public String reversePrefix(String word, char ch) {
                        int end = -1;
                        for (int i = 0; i < word.length(); i++) {
                            if (word.charAt(i) == ch) {
                                end = i;
                                break;
                            }
                        }
                        if (end == -1) {
                            return word;
                        }
                        StringBuilder answer = new StringBuilder(word.length());
                        for (int i = end; i >= 0; i--) {
                            answer.append(word.charAt(i));
                        }
                        for (int i = end + 1; i < word.length(); i++) {
                            answer.append(word.charAt(i));
                        }
                        return answer.toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Manual Builder By Index Fixture",
                "O(n)",
                "O(n)",
                "Find the first target index and write the reversed prefix followed by the original suffix.",
                "The reversal can be expressed as output order rather than as swaps.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String reversePrefixStackSolutionEntryJson() {
        String code = """
                import java.util.ArrayDeque;
                import java.util.Deque;

                class Solution {
                    public String reversePrefix(String word, char ch) {
                        int end = word.indexOf(ch);
                        if (end == -1) {
                            return word;
                        }
                        Deque<Character> stack = new ArrayDeque<>();
                        for (int i = 0; i <= end; i++) {
                            stack.push(word.charAt(i));
                        }
                        StringBuilder answer = new StringBuilder(word.length());
                        while (!stack.isEmpty()) {
                            answer.append(stack.pop());
                        }
                        answer.append(word.substring(end + 1));
                        return answer.toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Stack Prefix Rebuild Fixture",
                "O(n)",
                "O(n)",
                "Push the prefix through the first target character and pop it to rebuild the reversed prefix.",
                "A stack emits the prefix in last-in first-out order, exactly matching prefix reversal.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

