    private static String mostFrequentFollowingKeyHashMapSolutionEntryJson() {
        String code = """
                import java.util.HashMap;
                import java.util.Map;

                class Solution {
                    public int mostFrequent(int[] nums, int key) {
                        Map<Integer, Integer> counts = new HashMap<>();
                        int bestValue = 0;
                        int bestCount = 0;
                        for (int i = 0; i + 1 < nums.length; i++) {
                            if (nums[i] == key) {
                                int follower = nums[i + 1];
                                int newCount = counts.getOrDefault(follower, 0) + 1;
                                counts.put(follower, newCount);
                                if (newCount > bestCount) {
                                    bestCount = newCount;
                                    bestValue = follower;
                                }
                            }
                        }
                        return bestValue;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "HashMap Counts Fixture",
                "O(n)",
                "O(m)",
                "Count follower values in a HashMap and update the best target as counts grow.",
                "The map form keeps the same logic without depending on the small official value bound.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(m)",
                code);
    }

    private static String mostFrequentFollowingKeySortedRunsSolutionEntryJson() {
        String code = """
                import java.util.ArrayList;
                import java.util.Collections;
                import java.util.List;

                class Solution {
                    public int mostFrequent(int[] nums, int key) {
                        List<Integer> followers = new ArrayList<>();
                        for (int i = 0; i + 1 < nums.length; i++) {
                            if (nums[i] == key) {
                                followers.add(nums[i + 1]);
                            }
                        }
                        Collections.sort(followers);
                        int bestValue = followers.get(0);
                        int bestCount = 0;
                        int index = 0;
                        while (index < followers.size()) {
                            int value = followers.get(index);
                            int start = index;
                            while (index < followers.size() && followers.get(index) == value) {
                                index++;
                            }
                            int runLength = index - start;
                            if (runLength > bestCount) {
                                bestCount = runLength;
                                bestValue = value;
                            }
                        }
                        return bestValue;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Sort Followers And Scan Runs Fixture",
                "O(n log n)",
                "O(n)",
                "Collect followers, sort them, and scan equal-value runs to find the longest run.",
                "Sorting groups equal followers so frequency can be measured as contiguous run length.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String mostFrequentFollowingKeyCandidateEnumerationSolutionEntryJson() {
        String code = """
                import java.util.HashSet;
                import java.util.Set;

                class Solution {
                    public int mostFrequent(int[] nums, int key) {
                        Set<Integer> candidates = new HashSet<>();
                        for (int i = 0; i + 1 < nums.length; i++) {
                            if (nums[i] == key) {
                                candidates.add(nums[i + 1]);
                            }
                        }
                        int bestValue = 0;
                        int bestCount = 0;
                        for (int candidate : candidates) {
                            int currentCount = 0;
                            for (int i = 0; i + 1 < nums.length; i++) {
                                if (nums[i] == key && nums[i + 1] == candidate) {
                                    currentCount++;
                                }
                            }
                            if (currentCount > bestCount) {
                                bestCount = currentCount;
                                bestValue = candidate;
                            }
                        }
                        return bestValue;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Candidate Enumeration Baseline Fixture",
                "O(n * m)",
                "O(m)",
                "Enumerate distinct follower candidates, then count each candidate with a separate scan.",
                "This baseline mirrors the definition directly before collapsing the work into one pass.",
                "- Time Complexity: O(n * m)\\n- Space Complexity: O(m)",
                code);
    }

