    private static String cellsInExcelRangeLinearIndexSolutionEntryJson() {
        String code = """
                import java.util.ArrayList;
                import java.util.List;

                class Solution {
                    public List<String> cellsInRange(String s) {
                        int columnCount = s.charAt(3) - s.charAt(0) + 1;
                        int rowCount = s.charAt(4) - s.charAt(1) + 1;
                        List<String> cells = new ArrayList<>(columnCount * rowCount);
                        for (int index = 0; index < columnCount * rowCount; index++) {
                            char column = (char) (s.charAt(0) + index / rowCount);
                            char row = (char) (s.charAt(1) + index % rowCount);
                            cells.add("" + column + row);
                        }
                        return cells;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Linear Index Mapping Fixture",
                "O(C * R)",
                "O(C * R)",
                "Map one linear index to column and row offsets using quotient and remainder.",
                "Dividing by rowCount advances columns after every row in the current column is emitted.",
                "- Time Complexity: O(C * R)\\n- Space Complexity: O(C * R)",
                code);
    }

