    private static String strongPasswordCheckerIISinglePassSolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean strongPasswordCheckerII(String password) {
                        if (password.length() < 8) {
                            return false;
                        }
                        boolean lower = false;
                        boolean upper = false;
                        boolean digit = false;
                        boolean special = false;
                        String specials = "!@#$%^&*()-+";
                        for (int i = 0; i < password.length(); i++) {
                            char c = password.charAt(i);
                            if (i > 0 && c == password.charAt(i - 1)) {
                                return false;
                            }
                            if (Character.isLowerCase(c)) {
                                lower = true;
                            } else if (Character.isUpperCase(c)) {
                                upper = true;
                            } else if (Character.isDigit(c)) {
                                digit = true;
                            } else if (specials.indexOf(c) >= 0) {
                                special = true;
                            }
                        }
                        return lower && upper && digit && special;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Single Pass Flags Fixture",
                "O(n)",
                "O(1)",
                "Scan once with four boolean flags and reject equal adjacent characters immediately.",
                "One pass can collect category evidence while the previous character is still available.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String strongPasswordCheckerIIHelperSolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean strongPasswordCheckerII(String password) {
                        return password.length() >= 8
                                && !hasAdjacentDuplicate(password)
                                && hasLower(password)
                                && hasUpper(password)
                                && hasDigit(password)
                                && hasSpecial(password);
                    }

                    private boolean hasAdjacentDuplicate(String password) {
                        for (int i = 1; i < password.length(); i++) {
                            if (password.charAt(i) == password.charAt(i - 1)) {
                                return true;
                            }
                        }
                        return false;
                    }

                    private boolean hasLower(String s) { return s.chars().anyMatch(Character::isLowerCase); }
                    private boolean hasUpper(String s) { return s.chars().anyMatch(Character::isUpperCase); }
                    private boolean hasDigit(String s) { return s.chars().anyMatch(Character::isDigit); }
                    private boolean hasSpecial(String s) {
                        String specials = "!@#$%^&*()-+";
                        for (char c : s.toCharArray()) {
                            if (specials.indexOf(c) >= 0) {
                                return true;
                            }
                        }
                        return false;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Separate Rule Helpers Fixture",
                "O(n)",
                "O(1)",
                "Check each prompt rule with a named helper so the validation contract is explicit.",
                "A one-rule-per-helper shape makes weak or missing password rules easy to spot.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String strongPasswordCheckerIIBitmaskSolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean strongPasswordCheckerII(String password) {
                        if (password.length() < 8) {
                            return false;
                        }
                        int mask = 0;
                        for (int i = 0; i < password.length(); i++) {
                            char c = password.charAt(i);
                            if (i > 0 && c == password.charAt(i - 1)) {
                                return false;
                            }
                            mask |= categoryBit(c);
                        }
                        return mask == 0b1111;
                    }

                    private int categoryBit(char c) {
                        if ('a' <= c && c <= 'z') return 1;
                        if ('A' <= c && c <= 'Z') return 2;
                        if ('0' <= c && c <= '9') return 4;
                        return 8;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Category Bitmask Fixture",
                "O(n)",
                "O(1)",
                "Store the four required character categories as bits and combine them during the scan.",
                "The final mask must be binary 1111, meaning all four categories were observed.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String strongPasswordCheckerIIRegexSolutionEntryJson() {
        String code = """
                class Solution {
                    private static final String LOWER_PATTERN = ".*[a-z].*";
                    private static final String UPPER_PATTERN = ".*[A-Z].*";
                    private static final String DIGIT_PATTERN = ".*[0-9].*";
                    private static final String SPECIAL_PATTERN = ".*[!@#$%^&*()\\\\-+].*";

                    public boolean strongPasswordCheckerII(String password) {
                        return password.length() >= 8
                                && password.matches(LOWER_PATTERN)
                                && password.matches(UPPER_PATTERN)
                                && password.matches(DIGIT_PATTERN)
                                && password.matches(SPECIAL_PATTERN)
                                && !hasAdjacentDuplicate(password);
                    }

                    private boolean hasAdjacentDuplicate(String password) {
                        for (int i = 1; i < password.length(); i++) {
                            if (password.charAt(i) == password.charAt(i - 1)) {
                                return true;
                            }
                        }
                        return false;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Regex Categories With Adjacency Scan Fixture",
                "O(n)",
                "O(1)",
                "Use regular expressions for character categories and keep adjacency as an explicit loop.",
                "Existence checks and neighboring-position checks are different jobs, so each gets a fitting tool.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

