    private static String decodeMessageSubstitutionArraySolutionEntryJson() {
        String code = """
                class Solution {
                    public String decodeMessage(String key, String message) {
                        char[] map = new char[26];
                        boolean[] seen = new boolean[26];
                        char next = 'a';
                        for (int i = 0; i < key.length(); i++) {
                            char c = key.charAt(i);
                            if (c == ' ') {
                                continue;
                            }
                            int index = c - 'a';
                            if (!seen[index]) {
                                seen[index] = true;
                                map[index] = next++;
                            }
                        }
                        StringBuilder ans = new StringBuilder(message.length());
                        for (int i = 0; i < message.length(); i++) {
                            char c = message.charAt(i);
                            ans.append(c == ' ' ? ' ' : map[c - 'a']);
                        }
                        return ans.toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Substitution Table Fixture",
                "O(k + m)",
                "O(1)",
                "Build a direct array from encoded lowercase letters to decoded plaintext letters.",
                "The first-appearance order in key is the encoded alphabet, so each message letter becomes a table lookup.",
                "- Time Complexity: O(k + m)\\n- Space Complexity: O(1)",
                code);
    }

    private static String decodeMessageHashMapSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public String decodeMessage(String key, String message) {
                        Map<Character, Character> map = new HashMap<>();
                        char next = 'a';
                        for (int i = 0; i < key.length(); i++) {
                            char c = key.charAt(i);
                            if (c != ' ' && !map.containsKey(c)) {
                                map.put(c, next++);
                            }
                        }
                        StringBuilder ans = new StringBuilder(message.length());
                        for (int i = 0; i < message.length(); i++) {
                            char c = message.charAt(i);
                            ans.append(c == ' ' ? ' ' : map.get(c));
                        }
                        return ans.toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "HashMap Mapping Fixture",
                "O(k + m)",
                "O(1)",
                "Use a HashMap to record first-time encoded letters and their decoded plaintext letters.",
                "containsKey prevents duplicate key letters from consuming another plaintext character.",
                "- Time Complexity: O(k + m)\\n- Space Complexity: O(1)",
                code);
    }

    private static String decodeMessageFirstOccurrenceSolutionEntryJson() {
        String code = """
                class Solution {
                    public String decodeMessage(String key, String message) {
                        boolean[] seen = new boolean[26];
                        StringBuilder order = new StringBuilder(26);
                        for (int i = 0; i < key.length(); i++) {
                            char c = key.charAt(i);
                            if (c == ' ') {
                                continue;
                            }
                            int index = c - 'a';
                            if (!seen[index]) {
                                seen[index] = true;
                                order.append(c);
                            }
                        }
                        StringBuilder decoded = new StringBuilder(message.length());
                        for (int i = 0; i < message.length(); i++) {
                            char c = message.charAt(i);
                            if (c == ' ') {
                                decoded.append(' ');
                            } else {
                                decoded.append((char) ('a' + order.indexOf(String.valueOf(c))));
                            }
                        }
                        return decoded.toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "First Occurrence Alphabet Order Fixture",
                "O(k + 26m)",
                "O(1)",
                "Keep the encoded alphabet string and use each message letter's position to recover plaintext.",
                "A 26-letter alphabet keeps index lookup bounded while showing the cipher table explicitly.",
                "- Time Complexity: O(k + 26m)\\n- Space Complexity: O(1)",
                code);
    }

    private static String decodeMessageAsciiLookupSolutionEntryJson() {
        String code = """
                class Solution {
                    public String decodeMessage(String key, String message) {
                        char[] decoder = new char[128];
                        decoder[' '] = ' ';
                        char next = 'a';
                        for (int i = 0; i < key.length(); i++) {
                            char c = key.charAt(i);
                            if (c != ' ' && decoder[c] == 0) {
                                decoder[c] = next++;
                            }
                        }
                        StringBuilder decoded = new StringBuilder(message.length());
                        for (int i = 0; i < message.length(); i++) {
                            decoded.append(decoder[message.charAt(i)]);
                        }
                        return decoded.toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "ASCII Lookup Including Space Fixture",
                "O(k + m)",
                "O(1)",
                "Map space to itself in the lookup table, then decode every message character through one table.",
                "Treating spaces as table entries removes the branch from the second pass.",
                "- Time Complexity: O(k + m)\\n- Space Complexity: O(1)",
                code);
    }

