    private static String arithmeticTripletsHashSetSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int arithmeticTriplets(int[] nums, int diff) {
                        Set<Integer> values = new HashSet<>();
                        for (int num : nums) {
                            values.add(num);
                        }
                        int count = 0;
                        for (int num : nums) {
                            if (values.contains(num + diff) && values.contains(num + 2 * diff)) {
                                count++;
                            }
                        }
                        return count;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "HashSet Start Lookup Fixture",
                "O(n)",
                "O(n)",
                "Put every value in a set, then count starts whose next two arithmetic values exist.",
                "Strictly increasing input means value presence also guarantees index order.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String arithmeticTripletsBooleanLookupSolutionEntryJson() {
        String code = """
                class Solution {
                    public int arithmeticTriplets(int[] nums, int diff) {
                        boolean[] present = new boolean[201];
                        for (int num : nums) {
                            present[num] = true;
                        }
                        int count = 0;
                        for (int num : nums) {
                            if (num + 2 * diff < present.length
                                    && present[num + diff]
                                    && present[num + 2 * diff]) {
                                count++;
                            }
                        }
                        return count;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Bounded Boolean Presence Table Fixture",
                "O(n)",
                "O(1)",
                "Use the small value range to replace hashing with a fixed boolean presence table.",
                "Array indexing gives direct membership checks for x plus diff and x plus twice diff.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String arithmeticTripletsTwoPointerSolutionEntryJson() {
        String code = """
                class Solution {
                    public int arithmeticTriplets(int[] nums, int diff) {
                        int n = nums.length;
                        int middle = 0;
                        int end = 0;
                        int count = 0;
                        for (int start = 0; start < n; start++) {
                            while (middle < n && nums[middle] - nums[start] < diff) {
                                middle++;
                            }
                            while (end < n && nums[end] - nums[start] < 2 * diff) {
                                end++;
                            }
                            if (middle < n && end < n
                                    && nums[middle] - nums[start] == diff
                                    && nums[end] - nums[start] == 2 * diff) {
                                count++;
                            }
                        }
                        return count;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Monotonic Two Pointers Fixture",
                "O(n)",
                "O(1)",
                "Move middle and end pointers forward to find x plus diff and x plus twice diff for each start.",
                "Sorted strict order makes the target positions monotonic across starts.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String arithmeticTripletsTripleEnumerationSolutionEntryJson() {
        String code = """
                class Solution {
                    public int arithmeticTriplets(int[] nums, int diff) {
                        int count = 0;
                        for (int i = 0; i < nums.length; i++) {
                            for (int j = i + 1; j < nums.length; j++) {
                                for (int k = j + 1; k < nums.length; k++) {
                                    if (nums[j] - nums[i] == diff && nums[k] - nums[j] == diff) {
                                        count++;
                                    }
                                }
                            }
                        }
                        return count;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Triple Enumeration Baseline Fixture",
                "O(n^3)",
                "O(1)",
                "Enumerate i, j, and k exactly as the prompt defines the triplet.",
                "This slow route is a direct correctness baseline for optimized lookup methods.",
                "- Time Complexity: O(n^3)\\n- Space Complexity: O(1)",
                code);
    }

