    private static String numberOfCommonFactorsMinimumEnumerationSolutionEntryJson() {
        String code = """
                class Solution {
                    public int commonFactors(int a, int b) {
                        int limit = Math.min(a, b);
                        int count = 0;
                        for (int factor = 1; factor <= limit; factor++) {
                            if (a % factor == 0 && b % factor == 0) {
                                count++;
                            }
                        }
                        return count;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Minimum Enumeration Fixture",
                "O(min(a,b))",
                "O(1)",
                "Scan every possible factor up to the smaller input and count candidates that divide both values.",
                "The direct definition is a useful correctness baseline before introducing gcd or factor pairs.",
                "- Time Complexity: O(min(a,b))\\n- Space Complexity: O(1)",
                code);
    }

    private static String numberOfCommonFactorsDivisorSetSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int commonFactors(int a, int b) {
                        int smaller = Math.min(a, b);
                        int larger = Math.max(a, b);
                        Set<Integer> divisors = new HashSet<>();
                        for (int factor = 1; factor * factor <= smaller; factor++) {
                            if (smaller % factor == 0) {
                                divisors.add(factor);
                                divisors.add(smaller / factor);
                            }
                        }
                        int count = 0;
                        for (int factor : divisors) {
                            if (larger % factor == 0) {
                                count++;
                            }
                        }
                        return count;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Smaller Divisor Set Fixture",
                "O(sqrt(min(a,b)))",
                "O(sqrt(min(a,b)))",
                "Collect factor pairs of the smaller number in a set, then keep the divisors that also divide the larger value.",
                "The set avoids double-counting the square-root divisor when the smaller number is a perfect square.",
                "- Time Complexity: O(sqrt(min(a,b)))\\n- Space Complexity: O(sqrt(min(a,b)))",
                code);
    }

    private static String numberOfCommonFactorsGcdFactorPairsSolutionEntryJson() {
        String code = """
                class Solution {
                    public int commonFactors(int a, int b) {
                        int g = gcd(a, b);
                        int count = 0;
                        for (int factor = 1; factor * factor <= g; factor++) {
                            if (g % factor == 0) {
                                count++;
                                if (factor != g / factor) {
                                    count++;
                                }
                            }
                        }
                        return count;
                    }

                    private int gcd(int a, int b) {
                        while (b != 0) {
                            int r = a % b;
                            a = b;
                            b = r;
                        }
                        return a;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "GCD Factor Pair Fixture",
                "O(sqrt(gcd(a,b)))",
                "O(1)",
                "Compute gcd(a,b), then count factor pairs of that one compressed number.",
                "Every common factor of a and b is exactly a factor of their gcd.",
                "- Time Complexity: O(sqrt(gcd(a,b)))\\n- Space Complexity: O(1)",
                code);
    }

    private static String numberOfCommonFactorsPrimeFactorFormulaSolutionEntryJson() {
        String code = """
                class Solution {
                    public int commonFactors(int a, int b) {
                        int g = gcd(a, b);
                        int answer = 1;
                        for (int prime = 2; prime * prime <= g; prime++) {
                            if (g % prime != 0) {
                                continue;
                            }
                            int exponent = 0;
                            while (g % prime == 0) {
                                g /= prime;
                                exponent++;
                            }
                            answer *= exponent + 1;
                        }
                        if (g > 1) {
                            answer *= 2;
                        }
                        return answer;
                    }

                    private int gcd(int a, int b) {
                        while (b != 0) {
                            int r = a % b;
                            a = b;
                            b = r;
                        }
                        return a;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Prime Factor Divisor Formula Fixture",
                "O(sqrt(gcd(a,b)))",
                "O(1)",
                "Factorize the gcd and multiply exponent-plus-one terms to get the number of divisors.",
                "The divisor count formula exposes the number-theory structure behind common-factor counting.",
                "- Time Complexity: O(sqrt(gcd(a,b)))\\n- Space Complexity: O(1)",
                code);
    }

