    private static String sortThePeopleMaxHeapSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public String[] sortPeople(String[] names, int[] heights) {
                        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> b[0] - a[0]);
                        for (int i = 0; i < names.length; i++) {
                            heap.offer(new int[]{heights[i], i});
                        }
                        String[] answer = new String[names.length];
                        int index = 0;
                        while (!heap.isEmpty()) {
                            answer[index++] = names[heap.poll()[1]];
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Max Heap Fixture",
                "O(n log n)",
                "O(n)",
                "Push height-index pairs into a max heap and poll the tallest remaining person each time.",
                "The heap stores indices, so duplicate names do not collapse into one entry.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

