    private static String applyOperationsArrayInPlaceCompactSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] applyOperations(int[] nums) {
                        for (int i = 0; i + 1 < nums.length; i++) {
                            if (nums[i] == nums[i + 1]) {
                                nums[i] *= 2;
                                nums[i + 1] = 0;
                            }
                        }
                        int write = 0;
                        for (int num : nums) {
                            if (num != 0) {
                                nums[write++] = num;
                            }
                        }
                        while (write < nums.length) {
                            nums[write++] = 0;
                        }
                        return nums;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Two-Phase In-Place Compact Fixture",
                "O(n)",
                "O(1)",
                "Run the required left-to-right operation in nums, then compact non-zero values with a write pointer.",
                "Keeping merge and compaction as separate phases preserves the sequential update contract.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

