    private static String applyOperationsArrayOnePassMergeOutputSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] applyOperations(int[] nums) {
                        int[] answer = new int[nums.length];
                        int write = 0;
                        int index = 0;
                        while (index < nums.length) {
                            if (index + 1 < nums.length && nums[index] == nums[index + 1]) {
                                if (nums[index] != 0) {
                                    answer[write++] = nums[index] * 2;
                                }
                                index += 2;
                            } else {
                                if (nums[index] != 0) {
                                    answer[write++] = nums[index];
                                }
                                index++;
                            }
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "One Pass Merge Output Fixture",
                "O(n)",
                "O(n)",
                "Scan once and directly emit the compacted result, skipping the right side of each visible merge.",
                "Skipping a zeroed position can only hide zero-zero merges, which do not change the compacted answer.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

