    private static String distinctDifferenceArrayPrefixSuffixSolutionEntryJson() {
        String code = """
                import java.util.HashSet;
                import java.util.Set;

                class Solution {
                    public int[] distinctDifferenceArray(int[] nums) {
                        int n = nums.length;
                        int[] answer = new int[n];
                        int[] suffixDistinct = new int[n + 1];
                        Set<Integer> seen = new HashSet<>();
                        for (int i = n - 1; i >= 0; i--) {
                            seen.add(nums[i]);
                            suffixDistinct[i] = seen.size();
                        }
                        seen.clear();
                        for (int i = 0; i < n; i++) {
                            seen.add(nums[i]);
                            answer[i] = seen.size() - suffixDistinct[i + 1];
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Prefix Suffix Distinct Arrays Fixture",
                "O(n)",
                "O(n)",
                "Precompute suffix distinct counts, then scan the prefix set and subtract suffixDistinct at i + 1.",
                "The suffix for index i starts after nums[i], so the sentinel suffix array removes boundary cases.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String distinctDifferenceArrayRollingFrequencySolutionEntryJson() {
        String code = """
                import java.util.HashMap;
                import java.util.HashSet;
                import java.util.Map;
                import java.util.Set;

                class Solution {
                    public int[] distinctDifferenceArray(int[] nums) {
                        Map<Integer, Integer> suffix = new HashMap<>();
                        for (int num : nums) {
                            suffix.put(num, suffix.getOrDefault(num, 0) + 1);
                        }
                        Set<Integer> prefix = new HashSet<>();
                        int suffixDistinct = suffix.size();
                        int[] answer = new int[nums.length];
                        for (int i = 0; i < nums.length; i++) {
                            prefix.add(nums[i]);
                            int remaining = suffix.get(nums[i]) - 1;
                            if (remaining == 0) {
                                suffix.remove(nums[i]);
                                suffixDistinct--;
                            } else {
                                suffix.put(nums[i], remaining);
                            }
                            answer[i] = prefix.size() - suffixDistinct;
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Rolling Suffix Frequency Fixture",
                "O(n)",
                "O(n)",
                "Maintain a prefix set and a suffix frequency map while moving the cut from left to right.",
                "A suffix value disappears exactly when its remaining frequency reaches zero.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String distinctDifferenceArrayOccurrenceSweepSolutionEntryJson() {
        String code = """
                import java.util.HashMap;
                import java.util.Map;

                class Solution {
                    public int[] distinctDifferenceArray(int[] nums) {
                        int n = nums.length;
                        Map<Integer, Integer> first = new HashMap<>();
                        Map<Integer, Integer> last = new HashMap<>();
                        for (int i = 0; i < n; i++) {
                            first.putIfAbsent(nums[i], i);
                            last.put(nums[i], i);
                        }
                        int[] prefixGain = new int[n];
                        int[] suffixDelta = new int[n + 1];
                        for (int value : first.keySet()) {
                            int firstIndex = first.get(value);
                            int lastIndex = last.get(value);
                            prefixGain[firstIndex]++;
                            if (lastIndex > 0) {
                                suffixDelta[0]++;
                                suffixDelta[lastIndex]--;
                            }
                        }
                        int prefixDistinct = 0;
                        int suffixDistinct = 0;
                        int[] answer = new int[n];
                        for (int i = 0; i < n; i++) {
                            prefixDistinct += prefixGain[i];
                            suffixDistinct += suffixDelta[i];
                            answer[i] = prefixDistinct - suffixDistinct;
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "First Last Occurrence Sweep Fixture",
                "O(n)",
                "O(n)",
                "Record first and last occurrences, then sweep boundary events for prefix and suffix counts.",
                "Distinctness on each side depends only on whether a value has appeared and whether it appears later.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String distinctDifferenceArrayCoordinateCompressionSolutionEntryJson() {
        String code = """
                import java.util.Arrays;

                class Solution {
                    public int[] distinctDifferenceArray(int[] nums) {
                        int[] sorted = nums.clone();
                        Arrays.sort(sorted);
                        int unique = 0;
                        for (int num : sorted) {
                            if (unique == 0 || sorted[unique - 1] != num) {
                                sorted[unique++] = num;
                            }
                        }
                        int[] left = new int[unique];
                        int[] right = new int[unique];
                        for (int num : nums) {
                            right[indexOf(sorted, unique, num)]++;
                        }
                        int leftDistinct = 0;
                        int rightDistinct = unique;
                        int[] answer = new int[nums.length];
                        for (int i = 0; i < nums.length; i++) {
                            int id = indexOf(sorted, unique, nums[i]);
                            if (left[id]++ == 0) {
                                leftDistinct++;
                            }
                            if (--right[id] == 0) {
                                rightDistinct--;
                            }
                            answer[i] = leftDistinct - rightDistinct;
                        }
                        return answer;
                    }

                    private int indexOf(int[] sorted, int unique, int target) {
                        int lo = 0;
                        int hi = unique - 1;
                        while (lo <= hi) {
                            int mid = lo + (hi - lo) / 2;
                            if (sorted[mid] == target) {
                                return mid;
                            }
                            if (sorted[mid] < target) {
                                lo = mid + 1;
                            } else {
                                hi = mid - 1;
                            }
                        }
                        return -1;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Coordinate Compression Counts Fixture",
                "O(n log n)",
                "O(n)",
                "Compress arbitrary integer values to ids, then update left and right count arrays across the cut.",
                "Compression replaces hash-table keys with dense array indexes while preserving equality groups.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

