    private static String countAllOneSubmatricesHeightExpansionSolutionEntryJson() {
        String code = """
                class Solution {
                    public int numSubmat(int[][] mat) {
                        int rows = mat.length;
                        int cols = mat[0].length;
                        int[] height = new int[cols];
                        int answer = 0;
                        for (int r = 0; r < rows; r++) {
                            for (int c = 0; c < cols; c++) {
                                height[c] = mat[r][c] == 0 ? 0 : height[c] + 1;
                            }
                            for (int right = 0; right < cols; right++) {
                                int minHeight = height[right];
                                for (int left = right; left >= 0 && minHeight > 0; left--) {
                                    minHeight = Math.min(minHeight, height[left]);
                                    answer += minHeight;
                                }
                            }
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Bottom Row Height Expansion Fixture",
                "O(m n^2)",
                "O(n)",
                "Use every row as a bottom edge, expand left from each right edge, and add the running minimum height.",
                "The minimum column height is exactly the number of possible top boundaries for fixed horizontal bounds.",
                "- Time Complexity: O(m n^2)\\n- Space Complexity: O(n)",
                code);
    }

    private static String countAllOneSubmatricesMonotonicStackSolutionEntryJson() {
        String code = """
                import java.util.ArrayDeque;
                import java.util.Deque;

                class Solution {
                    public int numSubmat(int[][] mat) {
                        int rows = mat.length;
                        int cols = mat[0].length;
                        int[] height = new int[cols];
                        int answer = 0;
                        for (int r = 0; r < rows; r++) {
                            for (int c = 0; c < cols; c++) {
                                height[c] = mat[r][c] == 0 ? 0 : height[c] + 1;
                            }
                            Deque<int[]> stack = new ArrayDeque<>();
                            int rowCount = 0;
                            for (int c = 0; c < cols; c++) {
                                int width = 1;
                                while (!stack.isEmpty() && stack.peek()[0] >= height[c]) {
                                    int[] top = stack.pop();
                                    rowCount -= top[0] * top[1];
                                    width += top[1];
                                }
                                stack.push(new int[] {height[c], width});
                                rowCount += height[c] * width;
                                answer += rowCount;
                            }
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Monotonic Stack Histogram Fixture",
                "O(m n)",
                "O(n)",
                "Maintain a monotonic stack over each bottom-row histogram and aggregate rectangles ending at each column.",
                "Popping taller groups replaces their contribution with the current limiting height in amortized O(1).",
                "- Time Complexity: O(m n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String countAllOneSubmatricesRowPairCompressionSolutionEntryJson() {
        String code = """
                import java.util.Arrays;

                class Solution {
                    public int numSubmat(int[][] mat) {
                        int rows = mat.length;
                        int cols = mat[0].length;
                        int answer = 0;
                        for (int top = 0; top < rows; top++) {
                            int[] allOne = new int[cols];
                            Arrays.fill(allOne, 1);
                            for (int bottom = top; bottom < rows; bottom++) {
                                int run = 0;
                                for (int c = 0; c < cols; c++) {
                                    allOne[c] &= mat[bottom][c];
                                    if (allOne[c] == 1) {
                                        run++;
                                        answer += run;
                                    } else {
                                        run = 0;
                                    }
                                }
                            }
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Row Pair Column Compression Fixture",
                "O(m^2 n)",
                "O(n)",
                "Fix the top and bottom rows, compress valid all-one columns, then count contiguous one-runs.",
                "A run of length L contributes every possible left and right boundary inside that run.",
                "- Time Complexity: O(m^2 n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String countAllOneSubmatricesWidthDpSolutionEntryJson() {
        String code = """
                class Solution {
                    public int numSubmat(int[][] mat) {
                        int rows = mat.length;
                        int cols = mat[0].length;
                        int[][] width = new int[rows][cols];
                        for (int r = 0; r < rows; r++) {
                            for (int c = 0; c < cols; c++) {
                                if (mat[r][c] == 1) {
                                    width[r][c] = (c == 0 ? 0 : width[r][c - 1]) + 1;
                                }
                            }
                        }
                        int answer = 0;
                        for (int r = 0; r < rows; r++) {
                            for (int c = 0; c < cols; c++) {
                                int minWidth = width[r][c];
                                for (int up = r; up >= 0 && minWidth > 0; up--) {
                                    minWidth = Math.min(minWidth, width[up][c]);
                                    answer += minWidth;
                                }
                            }
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Width DP Upward Scan Fixture",
                "O(m^2 n)",
                "O(m n)",
                "Precompute row widths of consecutive ones, then scan upward from each bottom-right cell.",
                "The narrowest row width in the vertical span equals the number of possible left boundaries.",
                "- Time Complexity: O(m^2 n)\\n- Space Complexity: O(m n)",
                code);
    }

