                class Solution {
                    public ListNode swapPairs(ListNode head) {
                        if (head == null || head.next == null) {
                            return head;
                        }
                        ListNode second = head.next;
                        ListNode rest = second.next;
                        second.next = head;
                        head.next = swapPairs(rest);
                        return second;
                    }
                }
