    private static String swapNodesInPairsStackBufferSolutionEntryJson() {
        String code = """
                import java.util.ArrayDeque;
                import java.util.Deque;

                class Solution {
                    public ListNode swapPairs(ListNode head) {
                        ListNode dummy = new ListNode(0);
                        ListNode tail = dummy;
                        ListNode current = head;
                        while (current != null) {
                            Deque<ListNode> stack = new ArrayDeque<>();
                            int count = 0;
                            while (current != null && count < 2) {
                                ListNode next = current.next;
                                current.next = null;
                                stack.push(current);
                                current = next;
                                count++;
                            }
                            if (count == 1) {
                                tail.next = stack.pop();
                                break;
                            }
                            while (!stack.isEmpty()) {
                                tail.next = stack.pop();
                                tail = tail.next;
                            }
                        }
                        return dummy.next;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Two Node Stack Buffer Fixture",
                "O(n)",
                "O(1)",
                "Read up to two nodes into a stack, detach old next pointers, then append popped nodes to the result.",
                "The stack never holds more than two nodes, so it clarifies group reversal without changing space order.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

