    private static String substringConcatWordsHashMapWindowSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public List<Integer> findSubstring(String s, String[] words) {
                        List<Integer> answer = new ArrayList<>();
                        int wordLength = words[0].length(), wordCount = words.length;
                        Map<String, Integer> target = new HashMap<>();
                        for (String word : words) target.put(word, target.getOrDefault(word, 0) + 1);
                        for (int offset = 0; offset < wordLength; offset++) {
                            Map<String, Integer> window = new HashMap<>();
                            int left = offset, matched = 0;
                            for (int right = offset; right + wordLength <= s.length(); right += wordLength) {
                                String token = s.substring(right, right + wordLength);
                                if (!target.containsKey(token)) { window.clear(); matched = 0; left = right + wordLength; continue; }
                                window.put(token, window.getOrDefault(token, 0) + 1);
                                matched++;
                                while (window.get(token) > target.get(token)) {
                                    String remove = s.substring(left, left + wordLength);
                                    window.put(remove, window.get(remove) - 1);
                                    matched--;
                                    left += wordLength;
                                }
                                if (matched == wordCount) { answer.add(left); String remove = s.substring(left, left + wordLength); window.put(remove, window.get(remove) - 1); matched--; left += wordLength; }
                            }
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Aligned HashMap Count Window Fixture",
                "O(n * w)",
                "O(k * w)",
                "Scan each word-length offset with a HashMap window of token counts.",
                "Once the alignment is fixed, the window moves by whole tokens and shrinks only on overuse.",
                "- Time Complexity: O(n * w)\\n- Space Complexity: O(k * w)",
                code);
    }

    private static String substringConcatWordsRemainingCountsSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public List<Integer> findSubstring(String s, String[] words) {
                        List<Integer> answer = new ArrayList<>();
                        int wordLength = words[0].length(), wordCount = words.length;
                        Map<String, Integer> target = new HashMap<>();
                        for (String word : words) target.put(word, target.getOrDefault(word, 0) + 1);
                        for (int offset = 0; offset < wordLength; offset++) {
                            Map<String, Integer> remaining = new HashMap<>(target);
                            int left = offset, used = 0;
                            for (int right = offset; right + wordLength <= s.length(); right += wordLength) {
                                String token = s.substring(right, right + wordLength);
                                if (!target.containsKey(token)) { remaining = new HashMap<>(target); used = 0; left = right + wordLength; continue; }
                                remaining.put(token, remaining.get(token) - 1);
                                used++;
                                while (remaining.get(token) < 0) {
                                    String remove = s.substring(left, left + wordLength);
                                    remaining.put(remove, remaining.get(remove) + 1);
                                    used--;
                                    left += wordLength;
                                }
                                if (used == wordCount) { answer.add(left); String remove = s.substring(left, left + wordLength); remaining.put(remove, remaining.get(remove) + 1); used--; left += wordLength; }
                            }
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Remaining Count Sliding Window Fixture",
                "O(n * w)",
                "O(k * w)",
                "Track how many copies of each target word remain available inside the current window.",
                "A negative remaining count identifies the token that forced the left side to shrink.",
                "- Time Complexity: O(n * w)\\n- Space Complexity: O(k * w)",
                code);
    }

    private static String substringConcatWordsCompressedIdsSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public List<Integer> findSubstring(String s, String[] words) {
                        List<Integer> answer = new ArrayList<>();
                        int wordLength = words[0].length(), wordCount = words.length;
                        Map<String, Integer> ids = new HashMap<>();
                        int[] required = new int[wordCount];
                        int unique = 0;
                        for (String word : words) { Integer id = ids.get(word); if (id == null) { id = unique++; ids.put(word, id); } required[id]++; }
                        for (int offset = 0; offset < wordLength; offset++) {
                            int[] window = new int[unique];
                            int left = offset, matched = 0;
                            for (int right = offset; right + wordLength <= s.length(); right += wordLength) {
                                Integer id = ids.get(s.substring(right, right + wordLength));
                                if (id == null) { Arrays.fill(window, 0); matched = 0; left = right + wordLength; continue; }
                                window[id]++;
                                matched++;
                                while (window[id] > required[id]) { int removeId = ids.get(s.substring(left, left + wordLength)); window[removeId]--; matched--; left += wordLength; }
                                if (matched == wordCount) { answer.add(left); int removeId = ids.get(s.substring(left, left + wordLength)); window[removeId]--; matched--; left += wordLength; }
                            }
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Compressed Word Id Array Window Fixture",
                "O(n * w)",
                "O(k)",
                "Compress required words to ids and maintain target/window counts in int arrays.",
                "The fixed vocabulary lets the aligned window count duplicates without per-token map updates.",
                "- Time Complexity: O(n * w)\\n- Space Complexity: O(k)",
                code);
    }

    private static String substringConcatWordsPrecomputedTokenIdsSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public List<Integer> findSubstring(String s, String[] words) {
                        List<Integer> answer = new ArrayList<>();
                        int wordLength = words[0].length(), wordCount = words.length;
                        Map<String, Integer> ids = new HashMap<>();
                        int[] required = new int[wordCount];
                        int unique = 0;
                        for (String word : words) { Integer id = ids.get(word); if (id == null) { id = unique++; ids.put(word, id); } required[id]++; }
                        for (int offset = 0; offset < wordLength; offset++) {
                            int tokenCount = (s.length() - offset) / wordLength;
                            int[] tokenIds = new int[tokenCount];
                            for (int i = 0; i < tokenCount; i++) { int start = offset + i * wordLength; Integer id = ids.get(s.substring(start, start + wordLength)); tokenIds[i] = id == null ? -1 : id; }
                            int[] window = new int[unique];
                            int left = 0, matched = 0;
                            for (int right = 0; right < tokenIds.length; right++) {
                                int id = tokenIds[right];
                                if (id == -1) { Arrays.fill(window, 0); left = right + 1; matched = 0; continue; }
                                window[id]++;
                                matched++;
                                while (window[id] > required[id]) { window[tokenIds[left]]--; left++; matched--; }
                                if (matched == wordCount) { answer.add(offset + left * wordLength); window[tokenIds[left]]--; left++; matched--; }
                            }
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Precomputed Token Id Window Fixture",
                "O(n * w)",
                "O(n + k)",
                "Precompute aligned token ids, using -1 for invalid tokens, then slide over integer arrays.",
                "Tokenization is separated from window movement so the same aligned chunk is not sliced twice.",
                "- Time Complexity: O(n * w)\\n- Space Complexity: O(n + k)",
                code);
    }

