    private static String factorialZeroesPreimageBoundaryDifferenceSolutionEntryJson() {
        String code = """
                class Solution {
                    public int preimageSizeFZF(int k) {
                        return (int) (firstAtLeast(k + 1L) - firstAtLeast(k));
                    }

                    private long firstAtLeast(long target) {
                        long left = 0;
                        long right = 5L * (target + 1);
                        while (left < right) {
                            long mid = left + (right - left) / 2;
                            if (trailingZeroes(mid) >= target) {
                                right = mid;
                            } else {
                                left = mid + 1;
                            }
                        }
                        return left;
                    }

                    private long trailingZeroes(long n) {
                        long total = 0;
                        while (n > 0) {
                            n /= 5;
                            total += n;
                        }
                        return total;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Boundary Difference Binary Search Fixture",
                "O(log k log k)",
                "O(1)",
                "Find lower bounds for k and k plus one, then subtract the two positions.",
                "A reachable value occupies one contiguous five-number block, while a skipped value has no width.",
                "- Time Complexity: O(log k log k)\\n- Space Complexity: O(1)",
                code);
    }

    private static String factorialZeroesPreimageLowerBoundExistenceSolutionEntryJson() {
        String code = """
                class Solution {
                    public int preimageSizeFZF(int k) {
                        long left = 0;
                        long right = 5L * (k + 1);
                        while (left < right) {
                            long mid = (left + right) >>> 1;
                            if (countZeroes(mid) >= k) {
                                right = mid;
                            } else {
                                left = mid + 1;
                            }
                        }
                        return countZeroes(left) == k ? 5 : 0;
                    }

                    private long countZeroes(long n) {
                        if (n == 0) {
                            return 0;
                        }
                        return n / 5 + countZeroes(n / 5);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Lower Bound Existence Check Fixture",
                "O(log k log k)",
                "O(1)",
                "Find the first position with at least k zeroes and check whether it exactly hits k.",
                "The lower-bound position decides whether the plateau exists; if it exists, its size is five.",
                "- Time Complexity: O(log k log k)\\n- Space Complexity: O(1)",
                code);
    }

    private static String factorialZeroesPreimageExactBlockSolutionEntryJson() {
        String code = """
                class Solution {
                    public int preimageSizeFZF(int k) {
                        long left = 0;
                        long right = 5L * (k + 1);
                        while (left <= right) {
                            long mid = (left + right) >>> 1;
                            long zeroes = trailingZeroes(mid);
                            if (zeroes == k) {
                                return 5;
                            }
                            if (zeroes < k) {
                                left = mid + 1;
                            } else {
                                right = mid - 1;
                            }
                        }
                        return 0;
                    }

                    private long trailingZeroes(long n) {
                        long total = 0;
                        for (long divisor = 5; divisor <= n; divisor *= 5) {
                            total += n / divisor;
                        }
                        return total;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Exact Block Binary Search Fixture",
                "O(log k log k)",
                "O(1)",
                "Search directly for one x whose trailing-zero count equals k.",
                "One exact hit proves that the whole five-number block exists.",
                "- Time Complexity: O(log k log k)\\n- Space Complexity: O(1)",
                code);
    }

