    private static String maximumSubmatrixAdaptiveCompressionSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public int maxSumSubmatrix(int[][] matrix, int k) {
                        int rows = matrix.length, cols = matrix[0].length;
                        return cols <= rows ? compressColumns(matrix, k) : compressRows(matrix, k);
                    }
                    private int compressColumns(int[][] matrix, int k) {
                        int rows = matrix.length, cols = matrix[0].length, best = Integer.MIN_VALUE;
                        for (int left = 0; left < cols; left++) { int[] rowSums = new int[rows]; for (int right = left; right < cols; right++) { for (int row = 0; row < rows; row++) rowSums[row] += matrix[row][right]; best = Math.max(best, bestSubarrayNoMoreThanK(rowSums, k)); } }
                        return best;
                    }
                    private int compressRows(int[][] matrix, int k) {
                        int rows = matrix.length, cols = matrix[0].length, best = Integer.MIN_VALUE;
                        for (int top = 0; top < rows; top++) { int[] columnSums = new int[cols]; for (int bottom = top; bottom < rows; bottom++) { for (int col = 0; col < cols; col++) columnSums[col] += matrix[bottom][col]; best = Math.max(best, bestSubarrayNoMoreThanK(columnSums, k)); } }
                        return best;
                    }
                    private int bestSubarrayNoMoreThanK(int[] nums, int k) {
                        TreeSet<Integer> prefixes = new TreeSet<>(); prefixes.add(0); int prefix = 0, best = Integer.MIN_VALUE; for (int value : nums) { prefix += value; Integer ceiling = prefixes.ceiling(prefix - k); if (ceiling != null) best = Math.max(best, prefix - ceiling); prefixes.add(prefix); } return best;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Adaptive Dimension Compression Fixture",
                "O(min(r,c)^2 * max(r,c) log max(r,c))",
                "O(max(r,c))",
                "Choose the smaller dimension for the fixed boundary pair, then solve each compressed array with TreeSet prefixes.",
                "The same rectangles are considered, but the number of fixed-boundary pairs is minimized.",
                "- Time Complexity: O(min(r,c)^2 * max(r,c) log max(r,c))\\n- Space Complexity: O(max(r,c))",
                code);
    }

    private static String maximumSubmatrixColumnCompressionSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public int maxSumSubmatrix(int[][] matrix, int k) {
                        int rows = matrix.length, cols = matrix[0].length, best = Integer.MIN_VALUE;
                        for (int left = 0; left < cols; left++) {
                            int[] rowSums = new int[rows];
                            for (int right = left; right < cols; right++) {
                                for (int row = 0; row < rows; row++) rowSums[row] += matrix[row][right];
                                best = Math.max(best, bestSubarrayNoMoreThanK(rowSums, k));
                            }
                        }
                        return best;
                    }
                    private int bestSubarrayNoMoreThanK(int[] nums, int k) {
                        TreeSet<Integer> prefixes = new TreeSet<>(); prefixes.add(0); int prefix = 0, best = Integer.MIN_VALUE; for (int value : nums) { prefix += value; Integer ceiling = prefixes.ceiling(prefix - k); if (ceiling != null) best = Math.max(best, prefix - ceiling); prefixes.add(prefix); } return best;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Column Compression TreeSet Fixture",
                "O(c^2 * r log r)",
                "O(r)",
                "Fix left/right columns and compress row sums into a one-dimensional array.",
                "After fixing columns, each rectangle is exactly one contiguous row interval.",
                "- Time Complexity: O(c^2 * r log r)\\n- Space Complexity: O(r)",
                code);
    }

    private static String maximumSubmatrixRowSortedListSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public int maxSumSubmatrix(int[][] matrix, int k) {
                        int rows = matrix.length, cols = matrix[0].length, best = Integer.MIN_VALUE;
                        for (int top = 0; top < rows; top++) {
                            int[] columnSums = new int[cols];
                            for (int bottom = top; bottom < rows; bottom++) {
                                for (int col = 0; col < cols; col++) columnSums[col] += matrix[bottom][col];
                                best = Math.max(best, bestSubarrayNoMoreThanK(columnSums, k));
                            }
                        }
                        return best;
                    }
                    private int bestSubarrayNoMoreThanK(int[] nums, int k) {
                        List<Integer> prefixes = new ArrayList<>();
                        prefixes.add(0);
                        int prefix = 0, best = Integer.MIN_VALUE;
                        for (int value : nums) {
                            prefix += value;
                            int targetIndex = lowerBound(prefixes, prefix - k);
                            if (targetIndex < prefixes.size()) best = Math.max(best, prefix - prefixes.get(targetIndex));
                            prefixes.add(lowerBound(prefixes, prefix), prefix);
                        }
                        return best;
                    }
                    private int lowerBound(List<Integer> values, int target) {
                        int lo = 0, hi = values.size();
                        while (lo < hi) {
                            int mid = lo + (hi - lo) / 2;
                            if (values.get(mid) < target) lo = mid + 1; else hi = mid;
                        }
                        return lo;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Row Compression Sorted Prefix Fixture",
                "O(r^2 * c^2)",
                "O(c)",
                "Fix top/bottom rows and use a sorted prefix list with explicit lower_bound.",
                "The manual lower_bound shows the ordered-prefix condition without mirroring the TreeSet route.",
                "- Time Complexity: O(r^2 * c^2)\\n- Space Complexity: O(c)",
                code);
    }

    private static String maximumSubmatrixPrefixEnumerationSolutionEntryJson() {
        String code = """
                class Solution {
                    public int maxSumSubmatrix(int[][] matrix, int k) {
                        int rows = matrix.length, cols = matrix[0].length;
                        int[][] prefix = new int[rows + 1][cols + 1];
                        for (int row = 0; row < rows; row++) for (int col = 0; col < cols; col++) prefix[row + 1][col + 1] = matrix[row][col] + prefix[row][col + 1] + prefix[row + 1][col] - prefix[row][col];
                        int best = Integer.MIN_VALUE;
                        for (int top = 0; top < rows; top++) for (int left = 0; left < cols; left++) for (int bottom = top; bottom < rows; bottom++) for (int right = left; right < cols; right++) {
                            int sum = prefix[bottom + 1][right + 1] - prefix[top][right + 1] - prefix[bottom + 1][left] + prefix[top][left];
                            if (sum <= k) best = Math.max(best, sum);
                        }
                        return best;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "2D Prefix Rectangle Enumeration Fixture",
                "O(r^2 * c^2)",
                "O(r * c)",
                "Build a 2D prefix table and enumerate every rectangle boundary.",
                "The rectangle-sum formula is the direct correctness baseline for the optimized routes.",
                "- Time Complexity: O(r^2 * c^2)\\n- Space Complexity: O(r * c)",
                code);
    }

