    private static String permutationSequenceFactorialListSolutionEntryJson() {
        String code = """
                class Solution {
                    public String getPermutation(int n, int k) {
                        int[] factorial = new int[n + 1];
                        factorial[0] = 1;
                        java.util.List<Integer> remaining = new java.util.ArrayList<>();
                        for (int digit = 1; digit <= n; digit++) {
                            factorial[digit] = factorial[digit - 1] * digit;
                            remaining.add(digit);
                        }
                        int index = k - 1;
                        StringBuilder answer = new StringBuilder();
                        for (int len = n; len >= 1; len--) {
                            int block = factorial[len - 1];
                            int pick = index / block;
                            answer.append(remaining.remove(pick));
                            index %= block;
                        }
                        return answer.toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Factorial List Removal Fixture",
                "O(n^2)",
                "O(n)",
                "Use factorial blocks and remove the selected digit from the remaining list.",
                "Zero-based k written in factorial number system directly identifies each list index.",
                "- Time Complexity: O(n^2)\\n- Space Complexity: O(n)",
                code);
    }

    private static String permutationSequenceBooleanScanSolutionEntryJson() {
        String code = """
                class Solution {
                    public String getPermutation(int n, int k) {
                        int[] factorial = new int[n + 1];
                        factorial[0] = 1;
                        for (int i = 1; i <= n; i++) {
                            factorial[i] = factorial[i - 1] * i;
                        }
                        boolean[] used = new boolean[n + 1];
                        int index = k - 1;
                        StringBuilder answer = new StringBuilder();
                        for (int len = n; len >= 1; len--) {
                            int block = factorial[len - 1];
                            int order = index / block + 1;
                            int digit = takeUnused(used, order);
                            answer.append(digit);
                            index %= block;
                        }
                        return answer.toString();
                    }
                    private int takeUnused(boolean[] used, int order) {
                        for (int digit = 1; digit < used.length; digit++) {
                            if (used[digit]) {
                                continue;
                            }
                            order--;
                            if (order == 0) {
                                used[digit] = true;
                                return digit;
                            }
                        }
                        return -1;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Boolean Availability Scan Fixture",
                "O(n^2)",
                "O(n)",
                "Use factorial blocks, then scan a used array to find the ranked unused digit.",
                "The factorial rank is independent of whether remaining digits live in a list or a boolean array.",
                "- Time Complexity: O(n^2)\\n- Space Complexity: O(n)",
                code);
    }

    private static String permutationSequenceFenwickSolutionEntryJson() {
        String code = """
                class Solution {
                    public String getPermutation(int n, int k) {
                        int[] factorial = new int[n + 1];
                        int[] bit = new int[n + 1];
                        factorial[0] = 1;
                        for (int digit = 1; digit <= n; digit++) {
                            factorial[digit] = factorial[digit - 1] * digit;
                            add(bit, digit, 1);
                        }
                        int index = k - 1;
                        StringBuilder answer = new StringBuilder();
                        for (int len = n; len >= 1; len--) {
                            int block = factorial[len - 1];
                            int order = index / block + 1;
                            int digit = findByOrder(bit, order);
                            answer.append(digit);
                            add(bit, digit, -1);
                            index %= block;
                        }
                        return answer.toString();
                    }
                    private void add(int[] bit, int index, int delta) {
                        for (int i = index; i < bit.length; i += i & -i) {
                            bit[i] += delta;
                        }
                    }
                    private int findByOrder(int[] bit, int order) {
                        int index = 0;
                        for (int step = Integer.highestOneBit(bit.length - 1); step != 0; step >>= 1) {
                            int next = index + step;
                            if (next < bit.length && bit[next] < order) {
                                index = next;
                                order -= bit[next];
                            }
                        }
                        return index + 1;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Fenwick Order Statistic Fixture",
                "O(n log n)",
                "O(n)",
                "Use a Fenwick tree to find and remove the ranked unused digit.",
                "The tree turns each factorial-block rank into an order-statistic query.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String permutationSequenceNextPermutationSolutionEntryJson() {
        String code = """
                class Solution {
                    public String getPermutation(int n, int k) {
                        int[] digits = new int[n];
                        for (int i = 0; i < n; i++) {
                            digits[i] = i + 1;
                        }
                        for (int step = 1; step < k; step++) {
                            nextPermutation(digits);
                        }
                        StringBuilder answer = new StringBuilder();
                        for (int digit : digits) {
                            answer.append(digit);
                        }
                        return answer.toString();
                    }
                    private void nextPermutation(int[] digits) {
                        int pivot = digits.length - 2;
                        while (pivot >= 0 && digits[pivot] > digits[pivot + 1]) {
                            pivot--;
                        }
                        if (pivot >= 0) {
                            int larger = digits.length - 1;
                            while (digits[larger] < digits[pivot]) {
                                larger--;
                            }
                            swap(digits, pivot, larger);
                        }
                        reverse(digits, pivot + 1, digits.length - 1);
                    }
                    private void reverse(int[] digits, int left, int right) {
                        while (left < right) {
                            swap(digits, left++, right--);
                        }
                    }
                    private void swap(int[] digits, int i, int j) {
                        int temp = digits[i];
                        digits[i] = digits[j];
                        digits[j] = temp;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Next Permutation Baseline Fixture",
                "O(k * n)",
                "O(n)",
                "Repeatedly advance the sorted digits with the standard next-permutation operation.",
                "The baseline follows lexicographic order literally, while factorial blocks skip the same steps.",
                "- Time Complexity: O(k * n)\\n- Space Complexity: O(n)",
                code);
    }

