    private static String longestSquareStreakHashSetWalkSolutionEntryJson() {
        String code = """
                class Solution {
                    private static final long LIMIT = 1_000_000_000L;
                    public int longestSquareStreak(int[] nums) {
                        java.util.Set<Long> values = new java.util.HashSet<>();
                        for (int num : nums) values.add((long) num);
                        int best = 1;
                        for (long start : values) {
                            long current = start;
                            int length = 0;
                            while (values.contains(current)) {
                                length++;
                                if (current == 1 || current > LIMIT / current) break;
                                current *= current;
                            }
                            best = Math.max(best, length);
                        }
                        return best >= 2 ? best : -1;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Hash Set Forward Walk Fixture",
                "O(n log log V)",
                "O(n)",
                "Put distinct values in a hash set and walk each value forward by repeated squaring.",
                "The walk stops at one or before numeric overflow so duplicates cannot create fake length.",
                "- Time Complexity: O(n log log V)\\n- Space Complexity: O(n)",
                code);
    }

    private static String longestSquareStreakSortedRootDpSolutionEntryJson() {
        String code = """
                class Solution {
                    public int longestSquareStreak(int[] nums) {
                        java.util.TreeSet<Integer> sorted = new java.util.TreeSet<>();
                        for (int num : nums) sorted.add(num);
                        java.util.Map<Integer, Integer> dp = new java.util.HashMap<>();
                        int best = 1;
                        for (int value : sorted) {
                            int length = 1;
                            int root = (int) Math.sqrt(value);
                            if (value != 1 && root * root == value && dp.containsKey(root)) {
                                length = dp.get(root) + 1;
                            }
                            dp.put(value, length);
                            best = Math.max(best, length);
                        }
                        return best >= 2 ? best : -1;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Sorted Root Dynamic Programming Fixture",
                "O(n log n)",
                "O(n)",
                "Sort distinct values and transfer chain length from an existing integer square root.",
                "The square root must be processed before its square, and one cannot extend itself.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String longestSquareStreakChainRootsOnlySolutionEntryJson() {
        String code = """
                class Solution {
                    private static final long LIMIT = 1_000_000_000L;
                    public int longestSquareStreak(int[] nums) {
                        java.util.Set<Integer> values = new java.util.HashSet<>();
                        for (int num : nums) values.add(num);
                        int best = 1;
                        for (int value : values) {
                            if (value == 1 || hasSquareRootInSet(value, values)) continue;
                            long current = value;
                            int length = 0;
                            while (current <= LIMIT && values.contains((int) current)) {
                                length++;
                                if (current > LIMIT / current) break;
                                current *= current;
                            }
                            best = Math.max(best, length);
                        }
                        return best >= 2 ? best : -1;
                    }
                    private boolean hasSquareRootInSet(int value, java.util.Set<Integer> values) {
                        int root = (int) Math.sqrt(value);
                        return root * root == value && values.contains(root);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Chain Roots Only Fixture",
                "O(n log log V)",
                "O(n)",
                "Start walks only from values whose square root is not present in the set.",
                "Skipping internal chain nodes avoids recounting the same square path from the middle.",
                "- Time Complexity: O(n log log V)\\n- Space Complexity: O(n)",
                code);
    }

    private static String longestSquareStreakMemoizedDfsSolutionEntryJson() {
        String code = """
                class Solution {
                    private static final long LIMIT = 1_000_000_000L;
                    private java.util.Set<Long> values;
                    private java.util.Map<Long, Integer> memo;
                    public int longestSquareStreak(int[] nums) {
                        values = new java.util.HashSet<>();
                        for (int num : nums) values.add((long) num);
                        memo = new java.util.HashMap<>();
                        int best = 1;
                        for (long value : values) best = Math.max(best, dfs(value));
                        return best >= 2 ? best : -1;
                    }
                    private int dfs(long value) {
                        if (memo.containsKey(value)) return memo.get(value);
                        int length = 1;
                        if (value != 1 && value <= LIMIT / value) {
                            long next = value * value;
                            if (values.contains(next)) length = 1 + dfs(next);
                        }
                        memo.put(value, length);
                        return length;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Memoized Square DFS Fixture",
                "O(n)",
                "O(n)",
                "Treat each value as a node pointing to its square and memoize the chain length from that node.",
                "Only one can self-loop, so it is treated as a terminal length-one node before following edges.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

