    private static String countSubarraysFixedBoundsLastSeenSolutionEntryJson() {
        String code = """
                class Solution {
                    public long countSubarrays(int[] nums, int minK, int maxK) {
                        long answer = 0L;
                        int lastInvalid = -1;
                        int lastMin = -1;
                        int lastMax = -1;
                        for (int right = 0; right < nums.length; right++) {
                            int value = nums[right];
                            if (value < minK || value > maxK) {
                                lastInvalid = right;
                                lastMin = -1;
                                lastMax = -1;
                                continue;
                            }
                            if (value == minK) lastMin = right;
                            if (value == maxK) lastMax = right;
                            int earliestRequired = Math.min(lastMin, lastMax);
                            if (earliestRequired > lastInvalid) answer += earliestRequired - lastInvalid;
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Last Seen Bounds Fixture",
                "O(n)",
                "O(1)",
                "Track the last invalid index plus the latest positions of minK and maxK.",
                "Every right endpoint contributes starts after lastInvalid and before the earlier required bound.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String countSubarraysFixedBoundsShrinkingWindowSolutionEntryJson() {
        String code = """
                class Solution {
                    public long countSubarrays(int[] nums, int minK, int maxK) {
                        long answer = 0L;
                        int segmentStart = 0;
                        int left = 0;
                        int countMin = 0;
                        int countMax = 0;
                        for (int right = 0; right < nums.length; right++) {
                            int value = nums[right];
                            if (value < minK || value > maxK) {
                                segmentStart = right + 1;
                                left = right + 1;
                                countMin = 0;
                                countMax = 0;
                                continue;
                            }
                            if (value == minK) countMin++;
                            if (value == maxK) countMax++;
                            while (countMin > 0 && countMax > 0) {
                                if (nums[left] == minK) countMin--;
                                if (nums[left] == maxK) countMax--;
                                left++;
                            }
                            answer += left - segmentStart;
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Shrinking Window Counts Fixture",
                "O(n)",
                "O(1)",
                "Maintain counts of both fixed bounds inside the current valid segment and shrink while both exist.",
                "After shrinking, the removed starts are exactly the valid starts for the current right endpoint.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String countSubarraysFixedBoundsInclusionExclusionSolutionEntryJson() {
        String code = """
                class Solution {
                    public long countSubarrays(int[] nums, int minK, int maxK) {
                        long allInside = countRunsInRange(nums, minK, maxK);
                        long missingMin = countRunsInRange(nums, (long) minK + 1L, maxK);
                        long missingMax = countRunsInRange(nums, minK, (long) maxK - 1L);
                        long missingBoth = countRunsInRange(nums, (long) minK + 1L, (long) maxK - 1L);
                        return allInside - missingMin - missingMax + missingBoth;
                    }
                    private long countRunsInRange(int[] nums, long low, long high) {
                        if (low > high) return 0L;
                        long answer = 0L;
                        long runLength = 0L;
                        for (int value : nums) {
                            if (value >= low && value <= high) {
                                runLength++;
                                answer += runLength;
                            } else {
                                runLength = 0L;
                            }
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Segment Inclusion Exclusion Fixture",
                "O(n)",
                "O(1)",
                "Count all in-range subarrays, subtract those missing either boundary, then add back those missing both.",
                "Fixed minimum and maximum can be expressed as range membership minus the two boundary-missing cases.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String countSubarraysFixedBoundsEnumerationBaselineSolutionEntryJson() {
        String code = """
                class Solution {
                    public long countSubarrays(int[] nums, int minK, int maxK) {
                        long answer = 0L;
                        for (int left = 0; left < nums.length; left++) {
                            int minimum = Integer.MAX_VALUE;
                            int maximum = Integer.MIN_VALUE;
                            for (int right = left; right < nums.length; right++) {
                                int value = nums[right];
                                minimum = Math.min(minimum, value);
                                maximum = Math.max(maximum, value);
                                if (minimum < minK || maximum > maxK) break;
                                if (minimum == minK && maximum == maxK) answer++;
                            }
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Enumerate Starts Baseline Fixture",
                "O(n^2)",
                "O(1)",
                "Enumerate each left endpoint and extend right while maintaining the current minimum and maximum.",
                "The baseline mirrors the definition and explains what the linear contribution formulas compress.",
                "- Time Complexity: O(n^2)\\n- Space Complexity: O(1)",
                code);
    }

