    private static String maximalRectangleHistogramStackSolutionEntryJson() {
        String code = """
                class Solution {
                    public int maximalRectangle(char[][] matrix) {
                        if (matrix.length == 0 || matrix[0].length == 0) return 0;
                        int rows = matrix.length;
                        int cols = matrix[0].length;
                        int[] heights = new int[cols];
                        int best = 0;
                        for (int row = 0; row < rows; row++) {
                            for (int col = 0; col < cols; col++) {
                                heights[col] = matrix[row][col] == '1' ? heights[col] + 1 : 0;
                            }
                            best = Math.max(best, largestRectangleArea(heights));
                        }
                        return best;
                    }
                    private int largestRectangleArea(int[] heights) {
                        java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
                        int best = 0;
                        for (int index = 0; index <= heights.length; index++) {
                            int currentHeight = index == heights.length ? 0 : heights[index];
                            while (!stack.isEmpty() && heights[stack.peek()] > currentHeight) {
                                int height = heights[stack.pop()];
                                int left = stack.isEmpty() ? -1 : stack.peek();
                                best = Math.max(best, height * (index - left - 1));
                            }
                            stack.push(index);
                        }
                        return best;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Histogram Monotonic Stack Fixture",
                "O(rows * cols)",
                "O(cols)",
                "Treat each row as the floor of a histogram and solve largest rectangle in histogram with a stack.",
                "Every all-one rectangle ending at a row becomes a histogram rectangle in the accumulated heights.",
                "- Time Complexity: O(rows * cols)\\n- Space Complexity: O(cols)",
                code);
    }

    private static String maximalRectangleBoundaryDpSolutionEntryJson() {
        String code = """
                import java.util.Arrays;
                class Solution {
                    public int maximalRectangle(char[][] matrix) {
                        if (matrix.length == 0 || matrix[0].length == 0) return 0;
                        int rows = matrix.length;
                        int cols = matrix[0].length;
                        int[] height = new int[cols];
                        int[] left = new int[cols];
                        int[] right = new int[cols];
                        Arrays.fill(right, cols);
                        int best = 0;
                        for (int row = 0; row < rows; row++) {
                            int currentLeft = 0;
                            int currentRight = cols;
                            for (int col = 0; col < cols; col++) {
                                if (matrix[row][col] == '1') {
                                    height[col]++;
                                    left[col] = Math.max(left[col], currentLeft);
                                } else {
                                    height[col] = 0;
                                    left[col] = 0;
                                    currentLeft = col + 1;
                                }
                            }
                            for (int col = cols - 1; col >= 0; col--) {
                                if (matrix[row][col] == '1') {
                                    right[col] = Math.min(right[col], currentRight);
                                } else {
                                    right[col] = cols;
                                    currentRight = col;
                                }
                            }
                            for (int col = 0; col < cols; col++) {
                                best = Math.max(best, height[col] * (right[col] - left[col]));
                            }
                        }
                        return best;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Height Left Right Boundary DP Fixture",
                "O(rows * cols)",
                "O(cols)",
                "Maintain each column height plus the tightest left and right valid boundaries for the current row.",
                "Zeros reset the interval boundaries, while ones intersect the interval with previous rows.",
                "- Time Complexity: O(rows * cols)\\n- Space Complexity: O(cols)",
                code);
    }

    private static String maximalRectangleWidthUpwardScanSolutionEntryJson() {
        String code = """
                class Solution {
                    public int maximalRectangle(char[][] matrix) {
                        if (matrix.length == 0 || matrix[0].length == 0) return 0;
                        int rows = matrix.length;
                        int cols = matrix[0].length;
                        int[][] width = new int[rows][cols];
                        int best = 0;
                        for (int row = 0; row < rows; row++) {
                            for (int col = 0; col < cols; col++) {
                                if (matrix[row][col] == '1') {
                                    width[row][col] = (col == 0 ? 0 : width[row][col - 1]) + 1;
                                    int minWidth = width[row][col];
                                    for (int top = row; top >= 0 && width[top][col] > 0; top--) {
                                        minWidth = Math.min(minWidth, width[top][col]);
                                        int height = row - top + 1;
                                        best = Math.max(best, minWidth * height);
                                    }
                                }
                            }
                        }
                        return best;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Width DP Upward Scan Fixture",
                "O(rows^2 * cols)",
                "O(rows * cols)",
                "Precompute consecutive ones ending at each cell and scan upward from each bottom-right corner.",
                "For a fixed bottom-right cell, the limiting width over scanned rows defines each candidate rectangle.",
                "- Time Complexity: O(rows^2 * cols)\\n- Space Complexity: O(rows * cols)",
                code);
    }

    private static String maximalRectangleColumnPairCompressionSolutionEntryJson() {
        String code = """
                import java.util.Arrays;
                class Solution {
                    public int maximalRectangle(char[][] matrix) {
                        if (matrix.length == 0 || matrix[0].length == 0) return 0;
                        int rows = matrix.length;
                        int cols = matrix[0].length;
                        int best = 0;
                        for (int left = 0; left < cols; left++) {
                            boolean[] rowAllOnes = new boolean[rows];
                            Arrays.fill(rowAllOnes, true);
                            for (int right = left; right < cols; right++) {
                                int consecutiveRows = 0;
                                for (int row = 0; row < rows; row++) {
                                    rowAllOnes[row] = rowAllOnes[row] && matrix[row][right] == '1';
                                    if (rowAllOnes[row]) {
                                        consecutiveRows++;
                                        best = Math.max(best, consecutiveRows * (right - left + 1));
                                    } else {
                                        consecutiveRows = 0;
                                    }
                                }
                            }
                        }
                        return best;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Column Pair Compression Fixture",
                "O(cols^2 * rows)",
                "O(rows)",
                "Fix left and right columns, then track which rows remain all ones across that column band.",
                "A rectangle for fixed columns is exactly a consecutive run of rows that remain all ones.",
                "- Time Complexity: O(cols^2 * rows)\\n- Space Complexity: O(rows)",
                code);
    }

