    private static String scrambleStringBottomUpIntervalDpSolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean isScramble(String s1, String s2) {
                        int n = s1.length();
                        boolean[][][] dp = new boolean[n + 1][n][n];
                        for (int i = 0; i < n; i++) {
                            for (int j = 0; j < n; j++) {
                                dp[1][i][j] = s1.charAt(i) == s2.charAt(j);
                            }
                        }
                        for (int len = 2; len <= n; len++) {
                            for (int i = 0; i <= n - len; i++) {
                                for (int j = 0; j <= n - len; j++) {
                                    for (int k = 1; k < len; k++) {
                                        if ((dp[k][i][j] && dp[len - k][i + k][j + k])
                                                || (dp[k][i][j + len - k] && dp[len - k][i + k][j])) {
                                            dp[len][i][j] = true;
                                            break;
                                        }
                                    }
                                }
                            }
                        }
                        return dp[n][0][0];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Bottom-Up 3D Interval DP Fixture",
                "O(n^4)",
                "O(n^3)",
                "Fill scramble states by increasing substring length.",
                "Each split checks the non-swapped and swapped child-pair alignments from the definition.",
                "- Time Complexity: O(n^4)\\n- Space Complexity: O(n^3)",
                code);
    }

    private static String scrambleStringSubstringMemoizationSolutionEntryJson() {
        String code = """
                import java.util.Map;
                import java.util.HashMap;
                class Solution {
                    private Map<String, Boolean> memo = new HashMap<>();
                    public boolean isScramble(String s1, String s2) {
                        memo = new HashMap<>();
                        return solve(s1, s2);
                    }
                    private boolean solve(String s1, String s2) {
                        if (s1.equals(s2)) return true;
                        String key = s1 + "#" + s2;
                        if (memo.containsKey(key)) return memo.get(key);
                        int n = s1.length();
                        int[] count = new int[26];
                        for (int i = 0; i < n; i++) {
                            count[s1.charAt(i) - 'a']++;
                            count[s2.charAt(i) - 'a']--;
                        }
                        for (int value : count) {
                            if (value != 0) return memo.computeIfAbsent(key, ignored -> false);
                        }
                        for (int i = 1; i < n; i++) {
                            if (solve(s1.substring(0, i), s2.substring(0, i))
                                    && solve(s1.substring(i), s2.substring(i))) {
                                memo.put(key, true);
                                return true;
                            }
                            if (solve(s1.substring(0, i), s2.substring(n - i))
                                    && solve(s1.substring(i), s2.substring(0, n - i))) {
                                memo.put(key, true);
                                return true;
                            }
                        }
                        memo.put(key, false);
                        return false;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Substring Memoization Fixture",
                "O(n^4)",
                "O(n^3)",
                "Memoize each pair of current substrings and prune by character counts.",
                "The same substring pair can be reached through several split orders, so caching is essential.",
                "- Time Complexity: O(n^4)\\n- Space Complexity: O(n^3)",
                code);
    }

    private static String scrambleStringIndexPrefixDfsSolutionEntryJson() {
        String code = """
                class Solution {
                    private String a, b;
                    private Boolean[][][] memo;
                    private int[][] prefA, prefB;
                    public boolean isScramble(String s1, String s2) {
                        int n = s1.length();
                        a = s1;
                        b = s2;
                        memo = new Boolean[n][n][n + 1];
                        prefA = buildPrefix(a);
                        prefB = buildPrefix(b);
                        return dfs(0, 0, n);
                    }
                    private boolean dfs(int i, int j, int len) {
                        if (a.regionMatches(i, b, j, len)) return true;
                        if (memo[i][j][len] != null) return memo[i][j][len];
                        if (!sameCounts(i, j, len)) return memo[i][j][len] = false;
                        for (int split = 1; split < len; split++) {
                            if (dfs(i, j, split) && dfs(i + split, j + split, len - split)) {
                                return memo[i][j][len] = true;
                            }
                            if (dfs(i, j + len - split, split) && dfs(i + split, j, len - split)) {
                                return memo[i][j][len] = true;
                            }
                        }
                        return memo[i][j][len] = false;
                    }
                    private int[][] buildPrefix(String s) {
                        int[][] pref = new int[s.length() + 1][26];
                        for (int i = 0; i < s.length(); i++) {
                            System.arraycopy(pref[i], 0, pref[i + 1], 0, 26);
                            pref[i + 1][s.charAt(i) - 'a']++;
                        }
                        return pref;
                    }
                    private boolean sameCounts(int i, int j, int len) {
                        for (int c = 0; c < 26; c++) {
                            if (prefA[i + len][c] - prefA[i][c] != prefB[j + len][c] - prefB[j][c]) {
                                return false;
                            }
                        }
                        return true;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Index Prefix DFS Fixture",
                "O(n^4)",
                "O(n^3)",
                "Memoize by starting indices and length, then use prefix counts to prune impossible interval pairs.",
                "The state is the same as interval DP, but evaluated top-down.",
                "- Time Complexity: O(n^4)\\n- Space Complexity: O(n^3)",
                code);
    }

    private static String scrambleStringPrefixPrunedBottomUpDpSolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean isScramble(String s1, String s2) {
                        int n = s1.length();
                        int[][] prefA = buildPrefix(s1);
                        int[][] prefB = buildPrefix(s2);
                        boolean[][][] dp = new boolean[n + 1][n][n];
                        for (int i = 0; i < n; i++) {
                            for (int j = 0; j < n; j++) {
                                dp[1][i][j] = s1.charAt(i) == s2.charAt(j);
                            }
                        }
                        for (int len = 2; len <= n; len++) {
                            for (int i = 0; i <= n - len; i++) {
                                for (int j = 0; j <= n - len; j++) {
                                    if (!sameCounts(prefA, prefB, i, j, len)) continue;
                                    for (int split = 1; split < len; split++) {
                                        if ((dp[split][i][j] && dp[len - split][i + split][j + split])
                                                || (dp[split][i][j + len - split]
                                                && dp[len - split][i + split][j])) {
                                            dp[len][i][j] = true;
                                            break;
                                        }
                                    }
                                }
                            }
                        }
                        return dp[n][0][0];
                    }
                    private int[][] buildPrefix(String s) {
                        int[][] pref = new int[s.length() + 1][26];
                        for (int i = 0; i < s.length(); i++) {
                            System.arraycopy(pref[i], 0, pref[i + 1], 0, 26);
                            pref[i + 1][s.charAt(i) - 'a']++;
                        }
                        return pref;
                    }
                    private boolean sameCounts(int[][] prefA, int[][] prefB, int i, int j, int len) {
                        for (int c = 0; c < 26; c++) {
                            int left = prefA[i + len][c] - prefA[i][c];
                            int right = prefB[j + len][c] - prefB[j][c];
                            if (left != right) return false;
                        }
                        return true;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Prefix-Pruned Bottom-Up DP Fixture",
                "O(n^4)",
                "O(n^3)",
                "Run bottom-up interval DP but skip split enumeration when prefix counts differ.",
                "Character-count equality is a necessary condition for every scramble interval state.",
                "- Time Complexity: O(n^4)\\n- Space Complexity: O(n^3)",
                code);
    }

