    private static String laserBeamsSecurityRowsPreviousNonemptySolutionEntryJson() {
        String code = """
                class Solution {
                    public int numberOfBeams(String[] bank) {
                        int prev = 0, ans = 0;
                        for (String row : bank) {
                            int cur = 0;
                            for (char ch : row.toCharArray()) if (ch == '1') cur++;
                            if (cur > 0) {
                                ans += prev * cur;
                                prev = cur;
                            }
                        }
                        return ans;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Previous Nonempty Row Fixture",
                "O(rows * cols)",
                "O(1)",
                "Scan rows and keep only the previous non-empty row's device count.",
                "Empty rows are ignored, so the previous non-empty row remains the only pairing state.",
                "- Time Complexity: O(rows * cols)\\n- Space Complexity: O(1)",
                code);
    }

    private static String laserBeamsSecurityRowsCollectedCountsSolutionEntryJson() {
        String code = """
                import java.util.ArrayList;
                import java.util.List;
                class Solution {
                    public int numberOfBeams(String[] bank) {
                        List<Integer> counts = new ArrayList<>();
                        for (String row : bank) {
                            int c = 0;
                            for (int i = 0; i < row.length(); i++) if (row.charAt(i) == '1') c++;
                            if (c != 0) counts.add(c);
                        }
                        int beams = 0;
                        for (int i = 1; i < counts.size(); i++) {
                            beams += counts.get(i - 1) * counts.get(i);
                        }
                        return beams;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Collected Counts Fixture",
                "O(rows * cols)",
                "O(rows)",
                "Collect non-empty row counts before summing adjacent products.",
                "After filtering out empty rows, beams are exactly adjacent products in the count list.",
                "- Time Complexity: O(rows * cols)\\n- Space Complexity: O(rows)",
                code);
    }

    private static String laserBeamsSecurityRowsTwoPointerSolutionEntryJson() {
        String code = """
                class Solution {
                    public int numberOfBeams(String[] bank) {
                        int ans = 0;
                        int row = 0;
                        while (row < bank.length) {
                            int first = count(bank[row]);
                            if (first == 0) {
                                row++;
                                continue;
                            }
                            int next = row + 1;
                            int second = 0;
                            while (next < bank.length && second == 0) {
                                second = count(bank[next]);
                                next++;
                            }
                            if (second == 0) break;
                            ans += first * second;
                            row = next - 1;
                        }
                        return ans;
                    }
                    private int count(String row) {
                        int devices = 0;
                        for (int i = 0; i < row.length(); i++) if (row.charAt(i) == '1') devices++;
                        return devices;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Two Pointer Nonempty Rows Fixture",
                "O(rows * cols)",
                "O(1)",
                "Use one pointer for the current non-empty row and another for the next non-empty row.",
                "The second pointer directly models the next non-empty row below the current row.",
                "- Time Complexity: O(rows * cols)\\n- Space Complexity: O(1)",
                code);
    }

