    private static String recoverBinarySearchTreeRecursiveInorderSolutionEntryJson() {
        String code = """
                class Solution {
                    private TreeNode first, second, prev;
                    public void recoverTree(TreeNode root) {
                        inorder(root);
                        int temp = first.val;
                        first.val = second.val;
                        second.val = temp;
                    }
                    private void inorder(TreeNode node) {
                        if (node == null) return;
                        inorder(node.left);
                        if (prev != null && prev.val > node.val) {
                            if (first == null) first = prev;
                            second = node;
                        }
                        prev = node;
                        inorder(node.right);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Recursive Inorder Inversion Fixture",
                "O(n)",
                "O(h)",
                "Traverse inorder recursively and record the first larger node and the last smaller node.",
                "A swapped BST value pair appears as one or two inversions in the inorder sequence.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(h)",
                code);
    }

    private static String recoverBinarySearchTreeMorrisInorderSolutionEntryJson() {
        String code = """
                class Solution {
                    public void recoverTree(TreeNode root) {
                        TreeNode first = null, second = null, prev = null;
                        TreeNode curr = root;
                        while (curr != null) {
                            if (curr.left == null) {
                                if (prev != null && prev.val > curr.val) {
                                    if (first == null) first = prev;
                                    second = curr;
                                }
                                prev = curr;
                                curr = curr.right;
                            } else {
                                TreeNode pred = curr.left;
                                while (pred.right != null && pred.right != curr) {
                                    pred = pred.right;
                                }
                                if (pred.right == null) {
                                    pred.right = curr;
                                    curr = curr.left;
                                } else {
                                    pred.right = null;
                                    if (prev != null && prev.val > curr.val) {
                                        if (first == null) first = prev;
                                        second = curr;
                                    }
                                    prev = curr;
                                    curr = curr.right;
                                }
                            }
                        }
                        int temp = first.val;
                        first.val = second.val;
                        second.val = temp;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Morris Inorder Fixture",
                "O(n)",
                "O(1)",
                "Use Morris threading to perform inorder traversal without recursion or a stack.",
                "Temporary predecessor threads must be removed after use, leaving only the value swap.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String recoverBinarySearchTreeIterativeStackSolutionEntryJson() {
        String code = """
                class Solution {
                    public void recoverTree(TreeNode root) {
                        java.util.Deque<TreeNode> stack = new java.util.ArrayDeque<>();
                        TreeNode node = root, prev = null, first = null, second = null;
                        while (node != null || !stack.isEmpty()) {
                            while (node != null) {
                                stack.push(node);
                                node = node.left;
                            }
                            node = stack.pop();
                            if (prev != null && prev.val > node.val) {
                                if (first == null) first = prev;
                                second = node;
                            }
                            prev = node;
                            node = node.right;
                        }
                        int tmp = first.val;
                        first.val = second.val;
                        second.val = tmp;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Iterative Stack Inorder Fixture",
                "O(n)",
                "O(h)",
                "Use an explicit stack to simulate inorder traversal and detect inversions.",
                "The same previous/current comparison works regardless of whether traversal is recursive or iterative.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(h)",
                code);
    }

    private static String recoverBinarySearchTreeNodeListSolutionEntryJson() {
        String code = """
                class Solution {
                    public void recoverTree(TreeNode root) {
                        java.util.List<TreeNode> nodes = new java.util.ArrayList<>();
                        inorder(root, nodes);
                        TreeNode first = null, second = null;
                        for (int i = 1; i < nodes.size(); i++) {
                            TreeNode prev = nodes.get(i - 1);
                            TreeNode cur = nodes.get(i);
                            if (prev.val > cur.val) {
                                if (first == null) first = prev;
                                second = cur;
                            }
                        }
                        int temp = first.val;
                        first.val = second.val;
                        second.val = temp;
                    }
                    private void inorder(TreeNode node, java.util.List<TreeNode> nodes) {
                        if (node == null) return;
                        inorder(node.left, nodes);
                        nodes.add(node);
                        inorder(node.right, nodes);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Materialized Inorder Node List Fixture",
                "O(n)",
                "O(n)",
                "Collect inorder nodes into a list before scanning for descending adjacent pairs.",
                "The materialized list makes the inversion pattern explicit before the optimized routes remove it.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

