    private static String wordPatternBijectionTwoMapSolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean wordPattern(String pattern, String s) {
                        String[] words = s.split(" ");
                        if (words.length != pattern.length()) return false;
                        java.util.Map<Character,String> charToWord = new java.util.HashMap<>();
                        java.util.Map<String,Character> wordToChar = new java.util.HashMap<>();
                        for (int i = 0; i < words.length; i++) {
                            char ch = pattern.charAt(i);
                            String word = words[i];
                            if (charToWord.containsKey(ch) && !charToWord.get(ch).equals(word)) return false;
                            if (wordToChar.containsKey(word) && wordToChar.get(word) != ch) return false;
                            charToWord.put(ch, word);
                            wordToChar.put(word, ch);
                        }
                        return true;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Two Directional Maps Fixture",
                "O(n)",
                "O(n)",
                "Keep both character-to-word and word-to-character maps while scanning aligned positions.",
                "The reverse map prevents two different pattern characters from sharing one word.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String wordPatternBijectionMapAndSetSolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean wordPattern(String pattern, String s) {
                        String[] words = s.split(" ");
                        if (words.length != pattern.length()) return false;
                        java.util.Map<Character,String> mapping = new java.util.HashMap<>();
                        java.util.Set<String> usedWords = new java.util.HashSet<>();
                        for (int i = 0; i < pattern.length(); i++) {
                            char ch = pattern.charAt(i);
                            String word = words[i];
                            if (mapping.containsKey(ch)) {
                                if (!mapping.get(ch).equals(word)) return false;
                            } else {
                                if (usedWords.contains(word)) return false;
                                mapping.put(ch, word);
                                usedWords.add(word);
                            }
                        }
                        return true;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Mapping And Used Set Fixture",
                "O(n)",
                "O(n)",
                "Use a forward map for repeated-character consistency and a used-word set for uniqueness.",
                "The set is the reverse uniqueness check without storing the reverse character value.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String wordPatternBijectionFirstPositionsSolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean wordPattern(String pattern, String s) {
                        String[] words = s.split(" ");
                        if (words.length != pattern.length()) return false;
                        java.util.Map<Object,Integer> first = new java.util.HashMap<>();
                        for (int i = 0; i < words.length; i++) {
                            Integer patternFirst = first.putIfAbsent(pattern.charAt(i), i);
                            Integer wordFirst = first.putIfAbsent(words[i], i);
                            if (!java.util.Objects.equals(patternFirst, wordFirst)) return false;
                        }
                        return true;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "First Position Encoding Fixture",
                "O(n)",
                "O(n)",
                "Compare first-occurrence positions for the pattern-character sequence and the word sequence.",
                "A bijection exists exactly when the two aligned sequences share the same first-position signature.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String wordPatternBijectionPairCardinalitySolutionEntryJson() {
        String code = """
                class Solution {
                    public boolean wordPattern(String pattern, String s) {
                        String[] words = s.split(" ");
                        if (words.length != pattern.length()) return false;
                        java.util.Set<Character> chars = new java.util.HashSet<>();
                        java.util.Set<String> seenWords = new java.util.HashSet<>();
                        java.util.Set<String> pairs = new java.util.HashSet<>();
                        for (int i = 0; i < words.length; i++) {
                            char ch = pattern.charAt(i);
                            chars.add(ch);
                            seenWords.add(words[i]);
                            pairs.add(ch + "\\u0001" + words[i]);
                        }
                        return chars.size() == seenWords.size() && chars.size() == pairs.size();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Pair Cardinality Fixture",
                "O(n)",
                "O(n)",
                "Compare the number of unique characters, words, and aligned character-word pairs.",
                "Equal cardinalities rule out both one-to-many and many-to-one mapping failures.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

