    private static String longestBoundedDifferenceWindowMonotonicDequeSolutionEntryJson() {
        String code = """
                class Solution {
                    public int longestBoundedWindow(int[] nums, int limit) {
                        java.util.Deque<Integer> maxDeque = new java.util.ArrayDeque<>();
                        java.util.Deque<Integer> minDeque = new java.util.ArrayDeque<>();
                        int left = 0;
                        int best = 0;
                        for (int right = 0; right < nums.length; right++) {
                            while (!maxDeque.isEmpty() && nums[maxDeque.peekLast()] < nums[right]) maxDeque.pollLast();
                            while (!minDeque.isEmpty() && nums[minDeque.peekLast()] > nums[right]) minDeque.pollLast();
                            maxDeque.addLast(right);
                            minDeque.addLast(right);
                            while ((long) nums[maxDeque.peekFirst()] - nums[minDeque.peekFirst()] > limit) {
                                if (maxDeque.peekFirst() == left) maxDeque.pollFirst();
                                if (minDeque.peekFirst() == left) minDeque.pollFirst();
                                left++;
                            }
                            best = Math.max(best, right - left + 1);
                        }
                        return best;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Monotonic Deques Fixture",
                "O(n)",
                "O(n)",
                "Maintain decreasing and increasing index deques for window maximum and minimum.",
                "The two deque fronts are always the active extremes after stale indexes are removed.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String longestBoundedDifferenceWindowTreeMapSolutionEntryJson() {
        String code = """
                class Solution {
                    public int longestBoundedWindow(int[] nums, int limit) {
                        java.util.TreeMap<Integer,Integer> counts = new java.util.TreeMap<>();
                        int left = 0;
                        int best = 0;
                        for (int right = 0; right < nums.length; right++) {
                            counts.merge(nums[right], 1, Integer::sum);
                            while ((long) counts.lastKey() - counts.firstKey() > limit) {
                                int value = nums[left++];
                                int next = counts.get(value) - 1;
                                if (next == 0) counts.remove(value);
                                else counts.put(value, next);
                            }
                            best = Math.max(best, right - left + 1);
                        }
                        return best;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "TreeMap Multiset Fixture",
                "O(n log n)",
                "O(n)",
                "Use a TreeMap as a counted sorted multiset for the current window values.",
                "The first and last keys directly expose the current minimum and maximum.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String longestBoundedDifferenceWindowLazyHeapSolutionEntryJson() {
        String code = """
                class Solution {
                    public int longestBoundedWindow(int[] nums, int limit) {
                        java.util.PriorityQueue<int[]> maxHeap =
                                new java.util.PriorityQueue<>((a, b) -> Integer.compare(b[0], a[0]));
                        java.util.PriorityQueue<int[]> minHeap =
                                new java.util.PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
                        int left = 0;
                        int best = 0;
                        for (int right = 0; right < nums.length; right++) {
                            maxHeap.offer(new int[]{nums[right], right});
                            minHeap.offer(new int[]{nums[right], right});
                            while (true) {
                                while (maxHeap.peek()[1] < left) maxHeap.poll();
                                while (minHeap.peek()[1] < left) minHeap.poll();
                                long diff = (long) maxHeap.peek()[0] - minHeap.peek()[0];
                                if (diff <= limit) break;
                                if (maxHeap.peek()[1] < minHeap.peek()[1]) left = maxHeap.peek()[1] + 1;
                                else left = minHeap.peek()[1] + 1;
                            }
                            best = Math.max(best, right - left + 1);
                        }
                        return best;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Lazy Dual Heaps Fixture",
                "O(n log n)",
                "O(n)",
                "Keep candidate maximums and minimums in two heaps and lazily discard out-of-window entries.",
                "Heap entries carry indexes, which lets the window skip past the older violating extreme.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String longestBoundedDifferenceWindowSparseTableSolutionEntryJson() {
        String code = """
                class Solution {
                    public int longestBoundedWindow(int[] nums, int limit) {
                        int n = nums.length;
                        int levels = 32 - Integer.numberOfLeadingZeros(n);
                        int[][] maxTable = new int[levels][n];
                        int[][] minTable = new int[levels][n];
                        for (int i = 0; i < n; i++) {
                            maxTable[0][i] = nums[i];
                            minTable[0][i] = nums[i];
                        }
                        for (int level = 1; level < levels; level++) {
                            int span = 1 << level;
                            int half = span >> 1;
                            for (int i = 0; i + span <= n; i++) {
                                maxTable[level][i] = Math.max(maxTable[level - 1][i], maxTable[level - 1][i + half]);
                                minTable[level][i] = Math.min(minTable[level - 1][i], minTable[level - 1][i + half]);
                            }
                        }
                        int low = 1;
                        int high = n;
                        int best = 1;
                        while (low <= high) {
                            int mid = low + (high - low) / 2;
                            if (existsValidWindow(nums, limit, maxTable, minTable, mid)) {
                                best = mid;
                                low = mid + 1;
                            } else {
                                high = mid - 1;
                            }
                        }
                        return best;
                    }

                    private boolean existsValidWindow(int[] nums, int limit, int[][] maxTable, int[][] minTable, int len) {
                        int level = 31 - Integer.numberOfLeadingZeros(len);
                        int span = 1 << level;
                        for (int left = 0; left + len <= nums.length; left++) {
                            int rightStart = left + len - span;
                            int max = Math.max(maxTable[level][left], maxTable[level][rightStart]);
                            int min = Math.min(minTable[level][left], minTable[level][rightStart]);
                            if ((long) max - min <= limit) return true;
                        }
                        return false;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Sparse Table Binary Search Fixture",
                "O(n log n)",
                "O(n log n)",
                "Build range min/max sparse tables and binary search the answer length.",
                "Window length feasibility is monotonic, so fast fixed-window checks support answer search.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n log n)",
                code);
    }

