    private static String palindromePartitioningIIManacherSolutionEntryJson() {
        String code = """
                class Solution {
                    public int minCut(String s) {
                        int n = s.length();
                        int[] odd = oddRadii(s);
                        int[] even = evenRadii(s);
                        int[] cuts = new int[n];
                        for (int i = 0; i < n; i++) cuts[i] = i;
                        for (int center = 0; center < n; center++) {
                            for (int radius = 0; radius < odd[center]; radius++) {
                                int left = center - radius;
                                int right = center + radius;
                                cuts[right] = left == 0 ? 0 : Math.min(cuts[right], cuts[left - 1] + 1);
                            }
                            for (int radius = 1; radius <= even[center]; radius++) {
                                int left = center - radius;
                                int right = center + radius - 1;
                                cuts[right] = left == 0 ? 0 : Math.min(cuts[right], cuts[left - 1] + 1);
                            }
                        }
                        return cuts[n - 1];
                    }

                    private int[] oddRadii(String s) {
                        int n = s.length();
                        int[] radius = new int[n];
                        int left = 0, right = -1;
                        for (int i = 0; i < n; i++) {
                            int k = i > right ? 1 : Math.min(radius[left + right - i], right - i + 1);
                            while (i - k >= 0 && i + k < n && s.charAt(i - k) == s.charAt(i + k)) k++;
                            radius[i] = k;
                            if (i + k - 1 > right) {
                                left = i - k + 1;
                                right = i + k - 1;
                            }
                        }
                        return radius;
                    }

                    private int[] evenRadii(String s) {
                        int n = s.length();
                        int[] radius = new int[n];
                        int left = 0, right = -1;
                        for (int i = 0; i < n; i++) {
                            int k = i > right ? 0 : Math.min(radius[left + right - i + 1], right - i + 1);
                            while (i - k - 1 >= 0 && i + k < n && s.charAt(i - k - 1) == s.charAt(i + k)) k++;
                            radius[i] = k;
                            if (i + k - 1 > right) {
                                left = i - k;
                                right = i + k - 1;
                            }
                        }
                        return radius;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Manacher Radii Cut Relaxation Fixture",
                "O(n^2)",
                "O(n)",
                "Compute odd and even Manacher radii, then relax cuts over represented palindromes.",
                "The radii avoid repeated character comparisons while the DP still accounts for every palindrome interval.",
                "- Time Complexity: O(n^2)\\n- Space Complexity: O(n)",
                code);
    }

