    private static String candyTwoPassSolutionEntryJson() {
        String code = """
                class Solution {
                    public int candy(int[] ratings) {
                        int n = ratings.length;
                        int[] candies = new int[n];
                        java.util.Arrays.fill(candies, 1);
                        for (int i = 1; i < n; i++) {
                            if (ratings[i] > ratings[i - 1]) candies[i] = candies[i - 1] + 1;
                        }
                        for (int i = n - 2; i >= 0; i--) {
                            if (ratings[i] > ratings[i + 1]) candies[i] = Math.max(candies[i], candies[i + 1] + 1);
                        }
                        int total = 0;
                        for (int candy : candies) total += candy;
                        return total;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Two Pass Greedy Fixture",
                "O(n)",
                "O(n)",
                "Run left-to-right and right-to-left passes over the candy array.",
                "Each pass satisfies one neighbor direction and the max satisfies both directions.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String candySlopeCountingSolutionEntryJson() {
        String code = """
                class Solution {
                    public int candy(int[] ratings) {
                        int n = ratings.length;
                        if (n <= 1) return n;
                        int total = 1;
                        int up = 0;
                        int down = 0;
                        int peak = 0;
                        for (int i = 1; i < n; i++) {
                            if (ratings[i] > ratings[i - 1]) {
                                up++;
                                peak = up;
                                down = 0;
                                total += 1 + up;
                            } else if (ratings[i] < ratings[i - 1]) {
                                up = 0;
                                down++;
                                total += 1 + down - (down <= peak ? 1 : 0);
                            } else {
                                up = 0;
                                down = 0;
                                peak = 0;
                                total += 1;
                            }
                        }
                        return total;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Single Pass Slope Counting Fixture",
                "O(n)",
                "O(1)",
                "Count increasing and decreasing slopes and add arithmetic-series candy contributions.",
                "The shared peak is corrected when the descending side grows beyond the previous rise.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String candyRatingOrderSolutionEntryJson() {
        String code = """
                class Solution {
                    public int candy(int[] ratings) {
                        int n = ratings.length;
                        Integer[] order = new Integer[n];
                        for (int i = 0; i < n; i++) order[i] = i;
                        java.util.Arrays.sort(order, (a, b) -> Integer.compare(ratings[a], ratings[b]));
                        int[] candies = new int[n];
                        java.util.Arrays.fill(candies, 1);
                        for (int index : order) {
                            if (index > 0 && ratings[index] > ratings[index - 1]) {
                                candies[index] = Math.max(candies[index], candies[index - 1] + 1);
                            }
                            if (index + 1 < n && ratings[index] > ratings[index + 1]) {
                                candies[index] = Math.max(candies[index], candies[index + 1] + 1);
                            }
                        }
                        int total = 0;
                        for (int candy : candies) total += candy;
                        return total;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Rating Order DP Fixture",
                "O(n log n)",
                "O(n)",
                "Process child indexes in increasing rating order and inherit requirements from lower neighbors.",
                "All constraints point from lower ratings to higher ratings, so sorted processing is valid.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String candyLowerNeighborDfsSolutionEntryJson() {
        String code = """
                class Solution {
                    public int candy(int[] ratings) {
                        int[] memo = new int[ratings.length];
                        int total = 0;
                        for (int i = 0; i < ratings.length; i++) total += candiesFor(i, ratings, memo);
                        return total;
                    }

                    private int candiesFor(int index, int[] ratings, int[] memo) {
                        if (memo[index] != 0) return memo[index];
                        int best = 1;
                        if (index > 0 && ratings[index] > ratings[index - 1]) {
                            best = Math.max(best, candiesFor(index - 1, ratings, memo) + 1);
                        }
                        if (index + 1 < ratings.length && ratings[index] > ratings[index + 1]) {
                            best = Math.max(best, candiesFor(index + 1, ratings, memo) + 1);
                        }
                        memo[index] = best;
                        return best;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Lower Neighbor DFS Memoization Fixture",
                "O(n)",
                "O(n)",
                "Compute each child from its lower-rated neighbors using memoized recursion.",
                "The dependency graph is acyclic because every dependency moves to a strictly lower rating.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

