    private static String wordBreakIIMemoizedSuffixDfsSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public List<String> wordBreak(String s, List<String> wordDict) {
                        Set<String> words = new HashSet<>(wordDict);
                        Map<Integer, List<String>> memo = new HashMap<>();
                        return sentencesFrom(s, 0, words, memo);
                    }
                    private List<String> sentencesFrom(String s, int start, Set<String> words,
                            Map<Integer, List<String>> memo) {
                        if (memo.containsKey(start)) return memo.get(start);
                        List<String> result = new ArrayList<>();
                        if (start == s.length()) result.add("");
                        for (int end = start + 1; end <= s.length(); end++) {
                            String word = s.substring(start, end);
                            if (words.contains(word)) {
                                for (String suffix : sentencesFrom(s, end, words, memo)) {
                                    result.add(suffix.isEmpty() ? word : word + " " + suffix);
                                }
                            }
                        }
                        memo.put(start, result);
                        return result;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Memoized Suffix DFS Fixture",
                "O(n * 2^n)",
                "O(n * 2^n)",
                "Generate every sentence from each suffix start and cache the generated suffix list.",
                "Different prefixes repeatedly ask for the same suffix, so memoizing by start index avoids duplicate work.",
                "- Time Complexity: O(n * 2^n)\\n- Space Complexity: O(n * 2^n)",
                code);
    }

    private static String wordBreakIISuffixFeasibilitySolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public List<String> wordBreak(String s, List<String> wordDict) {
                        Set<String> words = new HashSet<>(wordDict);
                        int n = s.length();
                        int maxWordLength = 0;
                        for (String word : wordDict) maxWordLength = Math.max(maxWordLength, word.length());
                        boolean[] canFinish = new boolean[n + 1];
                        canFinish[n] = true;
                        for (int start = n - 1; start >= 0; start--) {
                            for (int end = start + 1; end <= Math.min(n, start + maxWordLength); end++) {
                                if (canFinish[end] && words.contains(s.substring(start, end))) {
                                    canFinish[start] = true;
                                    break;
                                }
                            }
                        }
                        List<String> answer = new ArrayList<>();
                        backtrack(s, 0, maxWordLength, words, canFinish, new ArrayList<>(), answer);
                        return answer;
                    }
                    private void backtrack(String s, int start, int maxWordLength, Set<String> words,
                            boolean[] canFinish, List<String> path, List<String> answer) {
                        if (start == s.length()) {
                            answer.add(String.join(" ", path));
                            return;
                        }
                        for (int end = start + 1; end <= Math.min(s.length(), start + maxWordLength); end++) {
                            if (!canFinish[end]) continue;
                            String word = s.substring(start, end);
                            if (words.contains(word)) {
                                path.add(word);
                                backtrack(s, end, maxWordLength, words, canFinish, path, answer);
                                path.remove(path.size() - 1);
                            }
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Suffix Feasibility Backtracking Fixture",
                "O(n * 2^n)",
                "O(n * 2^n)",
                "Precompute suffix reachability and use it to prune backtracking branches.",
                "The boolean table removes prefixes that would enter a suffix unable to complete the string.",
                "- Time Complexity: O(n * 2^n)\\n- Space Complexity: O(n * 2^n)",
                code);
    }

    private static String wordBreakIIBottomUpSentenceDpSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public List<String> wordBreak(String s, List<String> wordDict) {
                        Set<String> words = new HashSet<>(wordDict);
                        int n = s.length();
                        int maxWordLength = 0;
                        for (String word : wordDict) maxWordLength = Math.max(maxWordLength, word.length());
                        List<List<String>> dp = new ArrayList<>();
                        for (int i = 0; i <= n; i++) dp.add(new ArrayList<>());
                        dp.get(0).add("");
                        for (int end = 1; end <= n; end++) {
                            for (int start = Math.max(0, end - maxWordLength); start < end; start++) {
                                if (dp.get(start).isEmpty()) continue;
                                String word = s.substring(start, end);
                                if (words.contains(word)) {
                                    for (String prefix : dp.get(start)) {
                                        dp.get(end).add(prefix.isEmpty() ? word : prefix + " " + word);
                                    }
                                }
                            }
                        }
                        return dp.get(n);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Bottom-Up Sentence DP Fixture",
                "O(n * 2^n)",
                "O(n * 2^n)",
                "Store every complete prefix sentence in a bottom-up dynamic programming table.",
                "This shows DP can store generated sentence objects, not only feasibility booleans.",
                "- Time Complexity: O(n * 2^n)\\n- Space Complexity: O(n * 2^n)",
                code);
    }

    private static String wordBreakIITrieGuidedDfsSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    static class TrieNode {
                        TrieNode[] children = new TrieNode[26];
                        String word;
                    }
                    public List<String> wordBreak(String s, List<String> wordDict) {
                        TrieNode root = new TrieNode();
                        for (String word : wordDict) insert(root, word);
                        return dfs(s, 0, root, new HashMap<>());
                    }
                    private void insert(TrieNode root, String word) {
                        TrieNode node = root;
                        for (char ch : word.toCharArray()) {
                            int idx = ch - 'a';
                            if (node.children[idx] == null) node.children[idx] = new TrieNode();
                            node = node.children[idx];
                        }
                        node.word = word;
                    }
                    private List<String> dfs(String s, int start, TrieNode root, Map<Integer, List<String>> memo) {
                        if (memo.containsKey(start)) return memo.get(start);
                        List<String> result = new ArrayList<>();
                        TrieNode node = root;
                        for (int end = start; end < s.length(); end++) {
                            node = node.children[s.charAt(end) - 'a'];
                            if (node == null) break;
                            if (node.word == null) continue;
                            for (String suffix : dfs(s, end + 1, root, memo)) {
                                result.add(suffix.isEmpty() ? node.word : node.word + " " + suffix);
                            }
                        }
                        if (start == s.length()) result.add("");
                        memo.put(start, result);
                        return result;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Trie-Guided Memoized DFS Fixture",
                "O(n * 2^n)",
                "O(n * 2^n)",
                "Walk dictionary prefixes through a trie while memoizing generated suffix sentences.",
                "The trie stops impossible prefix scans early and memoization reuses suffix results.",
                "- Time Complexity: O(n * 2^n)\\n- Space Complexity: O(n * 2^n)",
                code);
    }

    private static String wordBreakIICutGraphSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    static class Edge {
                        int next;
                        String word;
                        Edge(int next, String word) { this.next = next; this.word = word; }
                    }
                    public List<String> wordBreak(String s, List<String> wordDict) {
                        Set<String> words = new HashSet<>(wordDict);
                        int n = s.length();
                        int maxWordLength = 0;
                        for (String word : wordDict) maxWordLength = Math.max(maxWordLength, word.length());
                        List<List<Edge>> graph = new ArrayList<>();
                        for (int i = 0; i <= n; i++) graph.add(new ArrayList<>());
                        boolean[] canFinish = new boolean[n + 1];
                        canFinish[n] = true;
                        for (int start = n - 1; start >= 0; start--) {
                            for (int end = start + 1; end <= Math.min(n, start + maxWordLength); end++) {
                                String word = s.substring(start, end);
                                if (canFinish[end] && words.contains(word)) {
                                    graph.get(start).add(new Edge(end, word));
                                    canFinish[start] = true;
                                }
                            }
                        }
                        List<String> answer = new ArrayList<>();
                        enumerate(graph, 0, n, new ArrayList<>(), answer);
                        return answer;
                    }
                    private void enumerate(List<List<Edge>> graph, int index, int target,
                            List<String> path, List<String> answer) {
                        if (index == target) {
                            answer.add(String.join(" ", path));
                            return;
                        }
                        for (Edge edge : graph.get(index)) {
                            path.add(edge.word);
                            enumerate(graph, edge.next, target, path, answer);
                            path.remove(path.size() - 1);
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Cut Graph Path Enumeration Fixture",
                "O(n * 2^n)",
                "O(n * 2^n)",
                "Build a graph of valid cut positions and enumerate every path from source to sink.",
                "Each complete sentence is exactly one path through the cut graph.",
                "- Time Complexity: O(n * 2^n)\\n- Space Complexity: O(n * 2^n)",
                code);
    }

