    private static String dungeonGameReverse2dSolutionEntryJson() {
        String code = """
                class Solution {
                    public int calculateMinimumHP(int[][] dungeon) {
                        int m = dungeon.length;
                        int n = dungeon[0].length;
                        int inf = 1_000_000_000;
                        int[][] need = new int[m + 1][n + 1];
                        for (int[] row : need) {
                            java.util.Arrays.fill(row, inf);
                        }
                        need[m][n - 1] = 1;
                        need[m - 1][n] = 1;
                        for (int row = m - 1; row >= 0; row--) {
                            for (int col = n - 1; col >= 0; col--) {
                                int next = Math.min(need[row + 1][col], need[row][col + 1]);
                                need[row][col] = Math.max(1, next - dungeon[row][col]);
                            }
                        }
                        return need[0][0];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Reverse Required-Health DP Fixture",
                "O(m * n)",
                "O(m * n)",
                "Work backward and store the minimum health needed before entering each room.",
                "Required health makes every room effect local once the cheaper continuation is known.",
                "- Time Complexity: O(m * n)\\n- Space Complexity: O(m * n)",
                code);
    }

    private static String dungeonGameReverse1dSolutionEntryJson() {
        String code = """
                class Solution {
                    public int calculateMinimumHP(int[][] dungeon) {
                        int m = dungeon.length;
                        int n = dungeon[0].length;
                        int inf = 1_000_000_000;
                        int[] need = new int[n + 1];
                        java.util.Arrays.fill(need, inf);
                        need[n - 1] = 1;
                        for (int row = m - 1; row >= 0; row--) {
                            for (int col = n - 1; col >= 0; col--) {
                                int next = Math.min(need[col], need[col + 1]);
                                need[col] = Math.max(1, next - dungeon[row][col]);
                            }
                            need[n] = inf;
                        }
                        return need[0];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Space-Optimized Reverse DP Fixture",
                "O(m * n)",
                "O(n)",
                "Compress the reverse required-health table to one row.",
                "Right-to-left updates preserve the down and right continuation values at each room.",
                "- Time Complexity: O(m * n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String dungeonGameTopDownSolutionEntryJson() {
        String code = """
                class Solution {
                    public int calculateMinimumHP(int[][] dungeon) {
                        int rows = dungeon.length;
                        int cols = dungeon[0].length;
                        int[][] memo = new int[rows][cols];
                        return need(0, 0, dungeon, memo);
                    }

                    private int need(int row, int col, int[][] dungeon, int[][] memo) {
                        int rows = dungeon.length;
                        int cols = dungeon[0].length;
                        if (row >= rows || col >= cols) {
                            return 1_000_000_000;
                        }
                        if (memo[row][col] != 0) {
                            return memo[row][col];
                        }
                        if (row == rows - 1 && col == cols - 1) {
                            memo[row][col] = Math.max(1, 1 - dungeon[row][col]);
                            return memo[row][col];
                        }
                        int next = Math.min(need(row + 1, col, dungeon, memo), need(row, col + 1, dungeon, memo));
                        memo[row][col] = Math.max(1, next - dungeon[row][col]);
                        return memo[row][col];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Top-Down Required-Health DFS Fixture",
                "O(m * n)",
                "O(m * n)",
                "Memoize the required health before entering each room from a recursive start-state view.",
                "The DFS is the same recurrence as reverse DP with impossible moves treated as infinite demand.",
                "- Time Complexity: O(m * n)\\n- Space Complexity: O(m * n)",
                code);
    }

    private static String dungeonGameBinarySearchSolutionEntryJson() {
        String code = """
                class Solution {
                    public int calculateMinimumHP(int[][] dungeon) {
                        int high = 1;
                        for (int[] row : dungeon) {
                            for (int value : row) {
                                if (value < 0) {
                                    high += -value;
                                }
                            }
                        }
                        int low = 1;
                        while (low < high) {
                            int mid = low + (high - low) / 2;
                            if (canSurvive(dungeon, mid)) {
                                high = mid;
                            } else {
                                low = mid + 1;
                            }
                        }
                        return low;
                    }

                    private boolean canSurvive(int[][] dungeon, int initialHealth) {
                        int rows = dungeon.length;
                        int cols = dungeon[0].length;
                        int[][] best = new int[rows][cols];
                        for (int[] row : best) {
                            java.util.Arrays.fill(row, -1);
                        }
                        int startHealth = initialHealth + dungeon[0][0];
                        if (startHealth <= 0) {
                            return false;
                        }
                        best[0][0] = startHealth;
                        for (int row = 0; row < rows; row++) {
                            for (int col = 0; col < cols; col++) {
                                if (best[row][col] <= 0) {
                                    continue;
                                }
                                if (row + 1 < rows) {
                                    int downHealth = best[row][col] + dungeon[row + 1][col];
                                    if (downHealth > 0) {
                                        best[row + 1][col] = Math.max(best[row + 1][col], downHealth);
                                    }
                                }
                                if (col + 1 < cols) {
                                    int rightHealth = best[row][col] + dungeon[row][col + 1];
                                    if (rightHealth > 0) {
                                        best[row][col + 1] = Math.max(best[row][col + 1], rightHealth);
                                    }
                                }
                            }
                        }
                        return best[rows - 1][cols - 1] > 0;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Binary Search Feasibility DP Fixture",
                "O(m * n * log S)",
                "O(m * n)",
                "Binary search the initial health and use forward DP to test whether that health survives.",
                "Survivability is monotonic, so every working health value proves all larger values also work.",
                "- Time Complexity: O(m * n * log S)\\n- Space Complexity: O(m * n)",
                code);
    }

