    private static String skylineGroupedEventSolutionEntryJson() {
        String code = """
                class Solution {
                    public java.util.List<java.util.List<Integer>> getSkyline(int[][] buildings) {
                        java.util.List<int[]> events = new java.util.ArrayList<>();
                        for (int[] building : buildings) {
                            events.add(new int[]{building[0], -building[2]});
                            events.add(new int[]{building[1], building[2]});
                        }
                        java.util.TreeMap<Integer, Integer> active = new java.util.TreeMap<>();
                        active.put(0, 1);
                        java.util.List<java.util.List<Integer>> answer = new java.util.ArrayList<>();
                        int index = 0;
                        while (index < events.size()) {
                            int x = events.get(index)[0];
                            while (index < events.size() && events.get(index)[0] == x) {
                                int height = events.get(index)[1];
                                if (height < 0) {
                                    active.merge(-height, 1, Integer::sum);
                                }
                                index++;
                            }
                            int currentHeight = active.lastKey();
                            answer.add(java.util.Arrays.asList(x, currentHeight));
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Grouped Event Sweep Fixture",
                "O(n log n)",
                "O(n)",
                "Convert every building edge into an event and process all events that share an x together.",
                "Grouping same-x events before reading the max active height avoids duplicate or contradictory key points.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String skylineLazyHeapSolutionEntryJson() {
        String code = """
                class Solution {
                    public java.util.List<java.util.List<Integer>> getSkyline(int[][] buildings) {
                        java.util.TreeSet<Integer> coordinates = new java.util.TreeSet<>();
                        for (int[] building : buildings) {
                            coordinates.add(building[0]);
                            coordinates.add(building[1]);
                        }
                        java.util.PriorityQueue<int[]> heap = new java.util.PriorityQueue<>((a, b) ->
                                a[0] != b[0] ? Integer.compare(b[0], a[0]) : Integer.compare(b[1], a[1]));
                        java.util.List<java.util.List<Integer>> answer = new java.util.ArrayList<>();
                        int buildingIndex = 0;
                        for (int x : coordinates) {
                            while (buildingIndex < buildings.length && buildings[buildingIndex][0] <= x) {
                                heap.offer(new int[]{buildings[buildingIndex][2], buildings[buildingIndex][1]});
                                buildingIndex++;
                            }
                            while (!heap.isEmpty() && heap.peek()[1] <= x) {
                                heap.poll();
                            }
                            answer.add(java.util.Arrays.asList(x, heap.isEmpty() ? 0 : heap.peek()[0]));
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Lazy Max-Heap Sweep Fixture",
                "O(n log n)",
                "O(n)",
                "Visit sorted coordinates and keep active buildings in a max heap, discarding expired tops lazily.",
                "A building only matters while its right edge is still beyond the current coordinate.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String skylineDivideConquerSolutionEntryJson() {
        String code = """
                class Solution {
                    public java.util.List<java.util.List<Integer>> getSkyline(int[][] buildings) {
                        return divide(buildings, 0, buildings.length - 1);
                    }

                    private java.util.List<java.util.List<Integer>> divide(int[][] buildings, int left, int right) {
                        return merge(new java.util.ArrayList<>(), new java.util.ArrayList<>());
                    }

                    private java.util.List<java.util.List<Integer>> merge(
                            java.util.List<java.util.List<Integer>> left,
                            java.util.List<java.util.List<Integer>> right) {
                        java.util.List<java.util.List<Integer>> merged = new java.util.ArrayList<>();
                        int leftHeight = 0;
                        int rightHeight = 0;
                        int x = 0;
                        append(merged, x, Math.max(leftHeight, rightHeight));
                        return merged;
                    }

                    private void append(java.util.List<java.util.List<Integer>> merged, int x, int height) {
                        merged.add(java.util.Arrays.asList(x, height));
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Divide and Conquer Merge Fixture",
                "O(n log n)",
                "O(n)",
                "Recursively solve halves and merge two skyline contours by tracking the active height from each side.",
                "At every merged x-coordinate, the visible height is the maximum of the left and right skyline heights.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String skylineSegmentTreeSolutionEntryJson() {
        String code = """
                class Solution {
                    private java.util.List<Integer> coords;
                    private int[] tree;

                    public java.util.List<java.util.List<Integer>> getSkyline(int[][] buildings) {
                        java.util.TreeSet<Integer> edges = new java.util.TreeSet<>();
                        for (int[] building : buildings) {
                            edges.add(building[0]);
                            edges.add(building[1]);
                        }
                        coords = new java.util.ArrayList<>(edges);
                        java.util.Map<Integer, Integer> index = new java.util.HashMap<>();
                        for (int i = 0; i < coords.size(); i++) {
                            index.put(coords.get(i), i);
                        }
                        tree = new int[coords.size() * 4];
                        for (int[] building : buildings) {
                            int left = index.get(building[0]);
                            int right = index.get(building[1]) - 1;
                            update(1, 0, coords.size() - 2, left, right, building[2]);
                        }
                        java.util.List<java.util.List<Integer>> answer = new java.util.ArrayList<>();
                        for (int i = 0; i < coords.size() - 1; i++) {
                            int height = query(1, 0, coords.size() - 2, i, 0);
                            answer.add(java.util.Arrays.asList(coords.get(i), height));
                        }
                        return answer;
                    }

                    private void update(int node, int start, int end, int left, int right, int height) {
                        tree[node] = Math.max(tree[node], height);
                    }

                    private int query(int node, int start, int end, int index, int carried) {
                        return Math.max(carried, tree[node]);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Coordinate Compression Segment Tree Fixture",
                "O(n log n)",
                "O(n)",
                "Compress all building edges and write maximum heights over compressed elementary intervals.",
                "Only edge coordinates can change the skyline, so compressed intervals preserve every possible key point.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

