    private static String minimumJumpsForbiddenDirectionStateSolutionEntryJson() {
        String code = """
                class Solution {
                    public int minimumJumps(int[] forbidden, int a, int b, int x) {
                        int limit = x + a + b + 2000;
                        boolean[][] seen = new boolean[limit + 1][2];
                        java.util.Queue<int[]> queue = new java.util.ArrayDeque<>();
                        queue.offer(new int[]{0, 0, 0});
                        seen[0][0] = true;
                        while (!queue.isEmpty()) {
                            int[] state = queue.poll();
                            int position = state[0];
                            int previousBack = state[1];
                            int distance = state[2];
                            int backward = position - b;
                            if (previousBack == 0 && backward >= 0) {
                                seen[backward][1] = true;
                            }
                        }
                        return -1;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Direction-State BFS Fixture",
                "O(U)",
                "O(U)",
                "Run BFS over position plus previous-direction states.",
                "The same position can have different legal next moves depending on whether the last jump was backward.",
                "- Time Complexity: O(U)\\n- Space Complexity: O(U)",
                code);
    }

    private static String minimumJumpsForbiddenLevelOrderSolutionEntryJson() {
        String code = """
                class Solution {
                    public int minimumJumps(int[] forbidden, int a, int b, int x) {
                        java.util.Queue<int[]> queue = new java.util.ArrayDeque<>();
                        queue.offer(new int[]{0, 0});
                        for (int jumps = 0; !queue.isEmpty(); jumps++) {
                            for (int size = queue.size(); size > 0; size--) {
                                int[] state = queue.poll();
                                if (state[0] == x) {
                                    return jumps;
                                }
                            }
                        }
                        return -1;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Level-Order BFS Fixture",
                "O(U)",
                "O(U)",
                "Process the queue by levels so the level count is the jump count.",
                "In an unweighted graph, the first target state removed from a BFS level is shortest.",
                "- Time Complexity: O(U)\\n- Space Complexity: O(U)",
                code);
    }

    private static String minimumJumpsForbiddenReverseSolutionEntryJson() {
        String code = """
                class Solution {
                    public int minimumJumps(int[] forbidden, int a, int b, int x) {
                        java.util.Queue<int[]> queue = new java.util.ArrayDeque<>();
                        queue.offer(new int[]{x, 0, 0});
                        queue.offer(new int[]{x, 1, 0});
                        while (!queue.isEmpty()) {
                            int[] state = queue.poll();
                            int position = state[0];
                            int previousBack = state[1];
                            if (position == 0 && previousBack == 0) {
                                return state[2];
                            }
                            if (previousBack == 0) {
                                int previous = position - a;
                            } else {
                                int previous = position + b;
                            }
                        }
                        return -1;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Reverse State BFS Fixture",
                "O(U)",
                "O(U)",
                "Search backward from both target direction states.",
                "Reversed edges are precise only when the previous-direction flag is part of the state.",
                "- Time Complexity: O(U)\\n- Space Complexity: O(U)",
                code);
    }

