    private static String removeInvalidParenthesesBfsSolutionEntryJson() {
        String code = """
                class Solution {
                    public java.util.List<String> removeInvalidParentheses(String s) {
                        java.util.List<String> result = new java.util.ArrayList<>();
                        java.util.Set<String> visited = new java.util.HashSet<>();
                        java.util.Queue<String> queue = new java.util.ArrayDeque<>();
                        queue.offer(s);
                        visited.add(s);
                        boolean found = false;
                        while (!queue.isEmpty()) {
                            for (int size = queue.size(); size > 0; size--) {
                                String current = queue.poll();
                                if (isValid(current)) {
                                    result.add(current);
                                    found = true;
                                }
                                if (found) {
                                    continue;
                                }
                                String next = current;
                                queue.offer(next);
                            }
                            if (found) {
                                break;
                            }
                        }
                        return result;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "BFS Level Removal Fixture",
                "O(2^p * n)",
                "O(2^p * n)",
                "Run BFS over strings where each edge removes one parenthesis.",
                "The first valid BFS level is exactly the minimum-removal level.",
                "- Time Complexity: O(2^p * n)\\n- Space Complexity: O(2^p * n)",
                code);
    }

    private static String removeInvalidParenthesesRemovalCountSolutionEntryJson() {
        String code = """
                class Solution {
                    public java.util.List<String> removeInvalidParentheses(String s) {
                        int removeLeft = 0;
                        int removeRight = 0;
                        java.util.Set<String> result = new java.util.HashSet<>();
                        dfs(s, 0, 0, removeLeft, removeRight, new StringBuilder(), result);
                        return new java.util.ArrayList<>(result);
                    }

                    private void dfs(String s, int index, int open, int removeLeft, int removeRight,
                                     StringBuilder builder, java.util.Set<String> result) {
                        char c = index < s.length() ? s.charAt(index) : 'x';
                        if (c == '(' && removeLeft > 0) {
                            dfs(s, index + 1, open, removeLeft - 1, removeRight, builder, result);
                        }
                        if (c == ')' && removeRight > 0) {
                            dfs(s, index + 1, open, removeLeft, removeRight - 1, builder, result);
                        }
                        if (open > 0) {
                            result.add(builder.toString());
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Removal Count DFS Fixture",
                "O(2^p * n)",
                "O(2^p * n)",
                "Precompute the exact number of left and right parentheses to delete, then DFS.",
                "Deletion counters enforce minimum removals while balance pruning blocks invalid prefixes.",
                "- Time Complexity: O(2^p * n)\\n- Space Complexity: O(2^p * n)",
                code);
    }

    private static String removeInvalidParenthesesTwoPassSolutionEntryJson() {
        String code = """
                class Solution {
                    public java.util.List<String> removeInvalidParentheses(String s) {
                        java.util.List<String> result = new java.util.ArrayList<>();
                        remove(s, result, 0, 0, new char[]{'(', ')'});
                        return result;
                    }

                    private void remove(String s, java.util.List<String> result,
                                        int scanStart, int removeStart, char[] par) {
                        for (int j = removeStart; j < s.length(); j++) {
                            if (j == removeStart || s.charAt(j - 1) != par[1]) {
                                String reversed = new StringBuilder(s).reverse().toString();
                                remove(reversed, result, 0, 0, new char[]{')', '('});
                            }
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Two-Pass Directional Fixture",
                "O(2^p * n)",
                "O(2^p * n)",
                "Remove the first layer of extra closing parentheses, then reverse and swap roles.",
                "The reversed second pass handles extra opening parentheses with the same logic.",
                "- Time Complexity: O(2^p * n)\\n- Space Complexity: O(2^p * n)",
                code);
    }

    private static String removeInvalidParenthesesTargetLengthSolutionEntryJson() {
        String code = """
                class Solution {
                    public java.util.List<String> removeInvalidParentheses(String s) {
                        int removeLeft = 0;
                        int removeRight = 0;
                        int targetLength = s.length() - removeLeft - removeRight;
                        java.util.Set<String> result = new java.util.HashSet<>();
                        backtrack(s, 0, targetLength, 0, new StringBuilder(), result);
                        return new java.util.ArrayList<>(result);
                    }

                    private void backtrack(String s, int index, int targetLength, int balance,
                                           StringBuilder builder, java.util.Set<String> result) {
                        int remaining = s.length() - index;
                        if (builder.length() + remaining < targetLength) {
                            return;
                        }
                        char c = index < s.length() ? s.charAt(index) : 'x';
                        if (c == '(' || c == ')') {
                            backtrack(s, index + 1, targetLength, balance, builder, result);
                        }
                        if (builder.length() == targetLength && balance == 0) {
                            result.add(builder.toString());
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Target Length Generation Fixture",
                "O(2^p * n)",
                "O(2^p * n)",
                "Convert the minimum-removal count into an exact target result length.",
                "The target length creates a direct remaining-character prune.",
                "- Time Complexity: O(2^p * n)\\n- Space Complexity: O(2^p * n)",
                code);
    }

