    private static String minimumNumberGameSortSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] numberGame(int[] nums) {
                        java.util.Arrays.sort(nums);
                        for (int i = 0; i < nums.length; i += 2) {
                            int alice = nums[i];
                            nums[i] = nums[i + 1];
                            nums[i + 1] = alice;
                        }
                        return nums;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Sort Adjacent Pairs Fixture",
                "O(n log n)",
                "O(1)",
                "Sort the values and swap each adjacent sorted pair before returning the same array.",
                "After sorting, Alice always takes the first item of a pair and Bob takes the second.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String minimumNumberGameHeapSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] numberGame(int[] nums) {
                        java.util.PriorityQueue<Integer> heap = new java.util.PriorityQueue<>();
                        for (int value : nums) {
                            heap.offer(value);
                        }
                        int[] answer = new int[nums.length];
                        for (int i = 0; i < answer.length; i += 2) {
                            int alice = heap.poll();
                            int bob = heap.poll();
                            answer[i] = bob;
                            answer[i + 1] = alice;
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Min Heap Simulation Fixture",
                "O(n log n)",
                "O(n)",
                "Push all numbers into a min heap and pop Alice then Bob for each game round.",
                "The heap mirrors the statement because every pop removes the current minimum.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String minimumNumberGameTreeMapSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] numberGame(int[] nums) {
                        java.util.TreeMap<Integer, Integer> counts = new java.util.TreeMap<>();
                        for (int value : nums) {
                            counts.put(value, counts.getOrDefault(value, 0) + 1);
                        }
                        int[] answer = new int[nums.length];
                        for (int i = 0; i < answer.length; i += 2) {
                            int alice = pollMin(counts);
                            int bob = pollMin(counts);
                            answer[i] = bob;
                            answer[i + 1] = alice;
                        }
                        return answer;
                    }

                    private int pollMin(java.util.TreeMap<Integer, Integer> counts) {
                        java.util.Map.Entry<Integer, Integer> entry = counts.firstEntry();
                        int value = entry.getKey();
                        if (entry.getValue() == 1) {
                            counts.pollFirstEntry();
                        } else {
                            counts.put(value, entry.getValue() - 1);
                        }
                        return value;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "TreeMap Frequency Multiset Fixture",
                "O(n log u)",
                "O(u)",
                "Count values in a TreeMap and remove the smallest multiset entry twice per round.",
                "The ordered frequency map compresses duplicates while preserving minimum removal.",
                "- Time Complexity: O(n log u)\\n- Space Complexity: O(u)",
                code);
    }

    private static String minimumNumberGameSelectionSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] numberGame(int[] nums) {
                        int[] answer = new int[nums.length];
                        for (int i = 0; i < answer.length; i += 2) {
                            int alice = takeMinimum(nums);
                            int bob = takeMinimum(nums);
                            answer[i] = bob;
                            answer[i + 1] = alice;
                        }
                        return answer;
                    }

                    private int takeMinimum(int[] nums) {
                        int best = 0;
                        for (int i = 1; i < nums.length; i++) {
                            if (nums[i] < nums[best]) {
                                best = i;
                            }
                        }
                        int value = nums[best];
                        nums[best] = Integer.MAX_VALUE;
                        return value;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Repeated Selection Baseline Fixture",
                "O(n^2)",
                "O(1)",
                "Scan for the smallest unused value each time the game removes a number.",
                "A sentinel larger than any allowed input marks values already removed.",
                "- Time Complexity: O(n^2)\\n- Space Complexity: O(1)",
                code);
    }

