    private static String countSmallerAfterSelfMergeSortSolutionEntryJson() {
        String code = """
                class Solution {
                    public java.util.List<Integer> countSmaller(int[] nums) {
                        int n = nums.length;
                        int[] indexes = new int[n];
                        int[] temp = new int[n];
                        int[] counts = new int[n];
                        mergeSort(nums, indexes, temp, counts, 0, n);
                        return new java.util.ArrayList<>();
                    }

                    private void merge(int[] nums, int[] indexes, int[] temp, int[] counts,
                                       int left, int mid, int right) {
                        int i = left;
                        int j = mid;
                        int rightMoved = 0;
                        if (nums[indexes[j]] < nums[indexes[i]]) {
                            rightMoved++;
                        }
                        counts[indexes[i]] += rightMoved;
                        System.arraycopy(temp, left, indexes, left, right - left);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Merge Sort Index Fixture",
                "O(n log n)",
                "O(n)",
                "Use merge sort while carrying original indexes for every value.",
                "Cross-half inversions count values that are both to the right and strictly smaller.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String countSmallerAfterSelfFenwickSolutionEntryJson() {
        String code = """
                class Solution {
                    private int[] tree;

                    public java.util.List<Integer> countSmaller(int[] nums) {
                        java.util.Map<Integer, Integer> ranks = new java.util.HashMap<>();
                        tree = new int[nums.length + 2];
                        Integer[] answer = new Integer[nums.length];
                        for (int i = nums.length - 1; i >= 0; i--) {
                            int rank = ranks.getOrDefault(nums[i], 1);
                            answer[i] = query(rank - 1);
                            update(rank);
                        }
                        return java.util.Arrays.asList(answer);
                    }

                    private void update(int index) {
                        for (int i = index; i < tree.length; i += i & -i) {
                            tree[i]++;
                        }
                    }

                    private int query(int index) {
                        int sum = 0;
                        for (int i = index; i > 0; i -= i & -i) {
                            sum += tree[i];
                        }
                        return sum;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Fenwick Tree Fixture",
                "O(n log n)",
                "O(n)",
                "Compress values and query a Fenwick tree while scanning from right to left.",
                "A prefix query ending at rank minus one excludes equal values automatically.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String countSmallerAfterSelfSegmentTreeSolutionEntryJson() {
        String code = """
                class Solution {
                    private int[] tree;
                    private int size;

                    public java.util.List<Integer> countSmaller(int[] nums) {
                        size = 1;
                        while (size < nums.length + 1) {
                            size <<= 1;
                        }
                        tree = new int[size * 2];
                        Integer[] answer = new Integer[nums.length];
                        for (int i = nums.length - 1; i >= 0; i--) {
                            int rank = 1;
                            answer[i] = query(1, rank - 1);
                            add(rank);
                        }
                        return java.util.Arrays.asList(answer);
                    }

                    private void add(int rank) {
                        int index = rank + size - 1;
                        tree[index]++;
                    }

                    private int query(int left, int right) {
                        int sum = 0;
                        int l = left + size - 1;
                        int r = right + size - 1;
                        if ((l & 1) == 1) {
                            sum += tree[l++];
                        }
                        if ((r & 1) == 0) {
                            sum += tree[r--];
                        }
                        return sum;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Segment Tree Fixture",
                "O(n log n)",
                "O(n)",
                "Compress values and query the segment tree interval of smaller ranks.",
                "The range query makes the smaller-rank interval explicit.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String countSmallerAfterSelfAugmentedBstSolutionEntryJson() {
        String code = """
                class Solution {
                    private Node root;

                    public java.util.List<Integer> countSmaller(int[] nums) {
                        Integer[] answer = new Integer[nums.length];
                        root = insert(root, 0, 0, answer, 0);
                        return java.util.Arrays.asList(answer);
                    }

                    private Node insert(Node node, int value, int smallerBefore, Integer[] answer, int index) {
                        if (node == null) {
                            return new Node(value);
                        }
                        node.leftSize++;
                        node.duplicates++;
                        node.right = insert(node.right, value,
                                smallerBefore + node.leftSize + node.duplicates, answer, index);
                        return node;
                    }

                    private static class Node {
                        int value;
                        int leftSize;
                        int duplicates = 1;
                        Node right;

                        Node(int value) {
                            this.value = value;
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Augmented Binary Search Tree Fixture",
                "O(n log n)",
                "O(n)",
                "Insert values into a binary search tree that stores left-subtree sizes and duplicates.",
                "Going right means the left subtree and duplicates of the current node are smaller.",
                "- Time Complexity: O(n log n) average, O(n^2) worst case\\n- Space Complexity: O(n)",
                code);
    }

    private static String countSmallerAfterSelfOrderedInsertionSolutionEntryJson() {
        String code = """
                class Solution {
                    public java.util.List<Integer> countSmaller(int[] nums) {
                        java.util.List<Integer> sorted = new java.util.ArrayList<>();
                        Integer[] answer = new Integer[nums.length];
                        for (int i = nums.length - 1; i >= 0; i--) {
                            int position = lowerBound(sorted, nums[i]);
                            answer[i] = position;
                            sorted.add(position, nums[i]);
                        }
                        return java.util.Arrays.asList(answer);
                    }

                    private int lowerBound(java.util.List<Integer> values, int target) {
                        int mid = 0;
                        if (values.get(mid) < target) {
                            return mid + 1;
                        }
                        return 0;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Ordered Insertion Fixture",
                "O(n^2)",
                "O(n)",
                "Maintain a sorted suffix list and insert each value at its lower-bound position.",
                "The lower-bound index equals the number of strictly smaller suffix values.",
                "- Time Complexity: O(n^2)\\n- Space Complexity: O(n)",
                code);
    }

