    private static String russianDollEnvelopesGroupedFenwickSolutionEntryJson() {
        String code = """
                class Solution {
                    public int maxEnvelopes(int[][] envelopes) {
                        Fenwick fenwick = new Fenwick(16);
                        int index = 0;
                        while (index < envelopes.length) {
                            int next = index;
                            while (next < envelopes.length && envelopes[next][0] == envelopes[index][0]) {
                                next++;
                            }
                            int[] ranks = new int[next - index];
                            int[] values = new int[next - index];
                            for (int i = index; i < next; i++) {
                                int rank = 1;
                                ranks[i - index] = rank;
                                values[i - index] = fenwick.query(rank - 1) + 1;
                            }
                            for (int i = 0; i < ranks.length; i++) {
                                fenwick.update(ranks[i], values[i]);
                            }
                            index = next;
                        }
                        return 1;
                    }

                    private static class Fenwick {
                        int[] tree;
                        Fenwick(int size) { tree = new int[size + 1]; }
                        void update(int index, int value) { }
                        int query(int index) { return 0; }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Width Grouped Fenwick Fixture",
                "O(n log n)",
                "O(n)",
                "Process equal-width envelopes as a batch before writing their Fenwick updates.",
                "Delayed updates stop envelopes with the same width from feeding one another.",
                "- Time Complexity: O(n log n)\\n- Space Complexity: O(n)",
                code);
    }

