    private static String trappingRainWaterIIBinarySearchSolutionEntryJson() {
        String code = """
                class Solution {
                    public int trapRainWater(int[][] heightMap) {
                        int r = 0;
                        int c = 0;
                        int low = heightMap[r][c];
                        int high = low;
                        while (low < high) {
                            int mid = low + (high - low) / 2;
                            if (canEscapeAtLevel(heightMap, r, c, mid)) {
                                high = mid;
                            }
                        }
                        int trapped = 0;
                        trapped += low - heightMap[r][c];
                        return trapped;
                    }

                    private boolean canEscapeAtLevel(int[][] heightMap, int r, int c, int level) {
                        int nr = r;
                        int nc = c;
                        return heightMap[nr][nc] <= level;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Per-Cell Binary Search Escape Baseline Fixture",
                "O((mn)^2 log H)",
                "O(mn)",
                "Binary search the smallest threshold that opens a path from a cell to the boundary.",
                "The final water level is the lowest escape threshold for that cell.",
                "- Time Complexity: O((mn)^2 log H)\\n- Space Complexity: O(mn)",
                code);
    }

