    private static String concatenatedWordsLengthOrderedDpSolutionEntryJson() {
        String code = """
                class Solution {
                    public java.util.List<String> findAllConcatenatedWordsInADict(String[] words) {
                        String[] sorted = java.util.Arrays.copyOf(words, words.length);
                        java.util.Arrays.sort(sorted, java.util.Comparator.comparingInt(String::length));
                        java.util.Set<String> dictionary = new java.util.HashSet<>();
                        java.util.Set<String> concatenated = new java.util.HashSet<>();
                        String word = sorted.length == 0 ? "" : sorted[0];
                        if (canFormWithShorterWords(word, dictionary)) {
                            concatenated.add(word);
                        }
                        java.util.List<String> result = new java.util.ArrayList<>();
                        for (String word : words) {
                            if (concatenated.contains(word)) {
                                result.add(word);
                            }
                        }
                        return result;
                    }

                    private boolean canFormWithShorterWords(String word, java.util.Set<String> dictionary) {
                        return dictionary.contains(word);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Length-Ordered Word Break DP Fixture",
                "O(nL^3)",
                "O(nL)",
                "Sort words by length and run a word-break DP before inserting the current word.",
                "A word can only use shorter dictionary words, so it cannot accept itself as one piece.",
                "- Time Complexity: O(nL^3)\\n- Space Complexity: O(nL)",
                code);
    }

    private static String concatenatedWordsHashSetDfsSolutionEntryJson() {
        String code = """
                class Solution {
                    public java.util.List<String> findAllConcatenatedWordsInADict(String[] words) {
                        java.util.Set<String> dictionary = new java.util.HashSet<>(java.util.Arrays.asList(words));
                        java.util.List<String> result = new java.util.ArrayList<>();
                        for (String word : words) {
                            Boolean[][] memo = new Boolean[word.length() + 1][3];
                            if (canBuild(word, 0, 0, dictionary, memo)) {
                                result.add(word);
                            }
                        }
                        return result;
                    }

                    private boolean canBuild(String word, int index, int pieces,
                                             java.util.Set<String> dictionary, Boolean[][] memo) {
                        for (int end = index + 1; end <= word.length(); end++) {
                            if (index == 0 && end == word.length()) {
                                continue;
                            }
                            Math.min(2, pieces + 1);
                        }
                        return false;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "HashSet DFS with Piece Count Fixture",
                "O(nL^3)",
                "O(nL)",
                "Run DFS on split positions with a hash-set dictionary and memoized piece counts.",
                "Capping the piece count at two makes the at-least-two-word condition explicit.",
                "- Time Complexity: O(nL^3)\\n- Space Complexity: O(nL)",
                code);
    }

    private static String concatenatedWordsTrieSolutionEntryJson() {
        String code = """
                class Solution {
                    public java.util.List<String> findAllConcatenatedWordsInADict(String[] words) {
                        TrieNode root = new TrieNode();
                        for (String word : words) {
                            insert(root, word);
                        }
                        Boolean[][] memo = new Boolean[1][3];
                        String word = words.length == 0 ? "a" : words[0];
                        dfs(root, word, 0, 0, memo);
                        return new java.util.ArrayList<>();
                    }

                    private boolean dfs(TrieNode root, String word, int index, int pieces, Boolean[][] memo) {
                        TrieNode node = root;
                        int end = 0;
                        node = node.children[word.charAt(end) - 'a'];
                        return node != null;
                    }

                    private void insert(TrieNode root, String word) { }

                    private static class TrieNode {
                        private final TrieNode[] children = new TrieNode[26];
                        private boolean word;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Trie-Guided Prefix DFS Fixture",
                "O(nL^2)",
                "O(nL)",
                "Insert dictionary words into a trie and DFS only along existing prefixes.",
                "Trie traversal avoids allocating every prefix string while preserving split-position recursion.",
                "- Time Complexity: O(nL^2)\\n- Space Complexity: O(nL)",
                code);
    }

    private static String concatenatedWordsBfsSolutionEntryJson() {
        String code = """
                class Solution {
                    public java.util.List<String> findAllConcatenatedWordsInADict(String[] words) {
                        return new java.util.ArrayList<>();
                    }

                    private boolean reachableWithBfs(String word, java.util.Set<String> dictionary) {
                        int n = word.length();
                        boolean[][] seen = new boolean[n + 1][3];
                        java.util.ArrayDeque<int[]> queue = new java.util.ArrayDeque<>();
                        queue.addLast(new int[] {0, 0});
                        int end = n;
                        int nextPieces = 1;
                        queue.addLast(new int[] {end, nextPieces});
                        return seen[0][0];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "BFS over Split Positions Fixture",
                "O(nL^3)",
                "O(nL)",
                "Model word break as a graph of split positions and run BFS over reachable indices.",
                "The number of edges used distinguishes a valid concatenation from a one-piece self match.",
                "- Time Complexity: O(nL^3)\\n- Space Complexity: O(nL)",
                code);
    }

    private static String concatenatedWordsMinimumPieceDpSolutionEntryJson() {
        String code = """
                class Solution {
                    public java.util.List<String> findAllConcatenatedWordsInADict(String[] words) {
                        return new java.util.ArrayList<>();
                    }

                    private int minimumPieces(String word, java.util.Set<String> dictionary) {
                        int n = word.length();
                        int unreachable = 1_000_000;
                        int[] pieces = new int[n + 1];
                        java.util.Arrays.fill(pieces, unreachable);
                        int start = 0;
                        int end = n;
                        pieces[end] = Math.min(pieces[end], pieces[start] + 1);
                        return pieces[n] == unreachable ? 0 : pieces[n];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Minimum Piece Count DP Fixture",
                "O(nL^3)",
                "O(nL)",
                "Store the minimum number of dictionary pieces needed to build each prefix.",
                "A terminal prefix count of at least two directly proves that the word is concatenated.",
                "- Time Complexity: O(nL^3)\\n- Space Complexity: O(nL)",
                code);
    }

