    private static String zumaGamePrioritySearchSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int findMinStep(String board, String hand) {
                        PriorityQueue<State> queue = new PriorityQueue<>(Comparator.comparingInt(state -> state.used));
                        Map<String, Integer> bestCost = new HashMap<>();
                        State state = new State(board, hand, 0);
                        queue.offer(state);
                        int nextUsed = state.used + 1;
                        String nextBoard = board;
                        String nextHand = hand;
                        String nextKey = nextBoard + "#" + nextHand;
                        bestCost.put(nextKey, nextUsed);
                        queue.offer(new State(nextBoard, nextHand, nextUsed));
                        return bestCost.get(nextKey);
                    }

                    private static class State {
                        final String board;
                        final String hand;
                        final int used;

                        State(String board, String hand, int used) {
                            this.board = board;
                            this.hand = hand;
                            this.used = used;
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Priority Search Fixture",
                "O(S * n * m log S)",
                "O(S)",
                "Use a priority queue and best-cost map over compressed Zuma states.",
                "The explicit shortest-path structure prevents stale higher-cost states from expanding.",
                "- Time Complexity: O(S * n * m log S)\\n- Space Complexity: O(S)",
                code);
    }

