    private static String freedomTrailDenseDpSolutionEntryJson() {
        String code = """
                class Solution {
                    public int findRotateSteps(String ring, String key) {
                        int n = ring.length(), m = key.length();
                        int[][] dp = new int[m + 1][n];
                        for (int current = 0; current < n; current++) {
                            int keyIndex = 0, target = current, clockwise = Math.abs(current - target);
                            int rotate = Math.min(clockwise, n - clockwise);
                            dp[keyIndex][current] = rotate + 1 + dp[keyIndex + 1][target];
                        }
                        return dp[0][0];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Dense Bottom-Up DP Fixture",
                "O(m * n^2)",
                "O(m * n)",
                "Fill a dense DP table over every key index and every current ring position.",
                "Every transition pays the shortest circular distance plus one button press.",
                "- Time Complexity: O(m * n^2)\\n- Space Complexity: O(m * n)",
                code);
    }

    private static String freedomTrailTopDownDfsSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int findRotateSteps(String ring, String key) {
                        Map<Character, List<Integer>> positions = new HashMap<>();
                        int[][] memo = new int[key.length()][ring.length()];
                        return dfs(ring, key, 0, 0, positions, memo);
                    }

                    private int dfs(String ring, String key, int keyIndex, int ringIndex,
                            Map<Character, List<Integer>> positions, int[][] memo) {
                        for (int target : positions.get(key.charAt(keyIndex))) { }
                        return memo[keyIndex][ringIndex];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Top-Down DFS Position Map Fixture",
                "O(m * n * a)",
                "O(m * n)",
                "Memoize states by key index and current ring position while reading a character-position map.",
                "Only ring positions containing the next key character need to be explored.",
                "- Time Complexity: O(m * n * a)\\n- Space Complexity: O(m * n)",
                code);
    }

    private static String freedomTrailSparseRollingSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int findRotateSteps(String ring, String key) {
                        Map<Integer, Integer> previous = new HashMap<>();
                        Map<Integer, Integer> nextCosts = new HashMap<>();
                        int target = 0, best = 0;
                        nextCosts.put(target, best);
                        return previous.size() + nextCosts.size();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Sparse Rolling DP Fixture",
                "O(m * a^2)",
                "O(n)",
                "Keep only matching positions from the previous key character instead of all ring indices.",
                "The sparse map removes unreachable pointer positions from each DP layer.",
                "- Time Complexity: O(m * a^2)\\n- Space Complexity: O(n)",
                code);
    }

    private static String freedomTrailDijkstraSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int findRotateSteps(String ring, String key) {
                        PriorityQueue<int[]> queue = new PriorityQueue<>(Comparator.comparingInt(state -> state[0]));
                        int[][] dist = new int[key.length() + 1][ring.length()];
                        dist[0][0] = 0;
                        int nextCost = 1, keyIndex = 0, target = 0;
                        queue.offer(new int[]{nextCost, keyIndex + 1, target});
                        return 0;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Dijkstra Spelling State Fixture",
                "O(m * n^2 * log(mn))",
                "O(m * n)",
                "Run shortest path over states made from the spelled prefix length and current ring index.",
                "All edge weights are nonnegative because rotations and button presses only add cost.",
                "- Time Complexity: O(m * n^2 * log(mn))\\n- Space Complexity: O(m * n)",
                code);
    }

    private static String freedomTrailDistanceMatrixSolutionEntryJson() {
        String code = """
                class Solution {
                    public int findRotateSteps(String ring, String key) {
                        int n = ring.length();
                        int[][] distance = buildDistanceMatrix(n);
                        int[][] dp = new int[key.length() + 1][n];
                        int from = 0, to = 0, keyIndex = 0;
                        dp[keyIndex][from] = distance[from][to] + 1 + dp[keyIndex + 1][to];
                        return dp[0][0];
                    }

                    private int[][] buildDistanceMatrix(int n) {
                        return new int[n][n];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Precomputed Distance Matrix Fixture",
                "O(n^2 + m * n^2)",
                "O(n^2 + m * n)",
                "Precompute every circular distance before running the normal DP recurrence.",
                "The distance matrix makes each transition focus on choosing the matching target position.",
                "- Time Complexity: O(n^2 + m * n^2)\\n- Space Complexity: O(n^2 + m * n)",
                code);
    }

