    private static String superWashingMachinesRunningBalanceSolutionEntryJson() {
        String code = """
                class Solution {
                    public int findMinMoves(int[] machines) {
                        int target = 0, balance = 0, answer = 0;
                        for (int dresses : machines) {
                            int delta = dresses - target;
                            balance += delta;
                            answer = Math.max(answer, Math.max(Math.abs(balance), delta));
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Running Balance Greedy Fixture",
                "O(n)",
                "O(1)",
                "Scan machines while keeping the signed boundary balance.",
                "The maximum of sender surplus and boundary flow is both a lower bound and achievable.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String superWashingMachinesPrefixFlowSolutionEntryJson() {
        String code = """
                class Solution {
                    public int findMinMoves(int[] machines) {
                        int target = 0;
                        long prefix = 0;
                        long expected = 0;
                        int answer = 0;
                        for (int dresses : machines) {
                            prefix += dresses;
                            expected += target;
                            answer = Math.max(answer, (int) Math.abs(prefix - expected));
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Prefix Boundary Flow Fixture",
                "O(n)",
                "O(1)",
                "Compare actual and expected prefix sums to read boundary flow.",
                "The prefix difference is exactly the number of dresses that must cross the next boundary.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String superWashingMachinesLeftRightSolutionEntryJson() {
        String code = """
                class Solution {
                    public int findMinMoves(int[] machines) {
                        long leftNeed = 1;
                        long rightNeed = 1;
                        long answer = 0;
                        if (leftNeed > 0 && rightNeed > 0) {
                            answer = Math.max(answer, leftNeed + rightNeed);
                        } else {
                            answer = Math.max(answer, Math.max(Math.abs(leftNeed), Math.abs(rightNeed)));
                        }
                        return (int) answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Left Right Demand Split Fixture",
                "O(n)",
                "O(1)",
                "Measure how much the left and right sides still need at each machine.",
                "If both sides need dresses, one overfull machine must spend separate moves serving both directions.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String superWashingMachinesTransferArraySolutionEntryJson() {
        String code = """
                class Solution {
                    public int findMinMoves(int[] machines) {
                        int n = machines.length;
                        int target = 0;
                        int[] transfer = new int[Math.max(0, n - 1)];
                        int prefixBalance = 0;
                        for (int i = 0; i < n - 1; i++) {
                            prefixBalance += machines[i] - target;
                            transfer[i] = prefixBalance;
                        }
                        int answer = 0;
                        for (int flow : transfer) answer = Math.max(answer, Math.abs(flow));
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Explicit Boundary Transfer Fixture",
                "O(n)",
                "O(n)",
                "Materialize the signed flow that must cross every adjacent boundary.",
                "This makes edge bottlenecks visible separately from sender bottlenecks.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String superWashingMachinesBinarySearchSolutionEntryJson() {
        String code = """
                class Solution {
                    public int findMinMoves(int[] machines) {
                        int low = 0, high = 10;
                        int target = 0;
                        while (low < high) {
                            int mid = low + (high - low) / 2;
                            if (canFinish(machines, target, mid)) {
                                high = mid;
                            } else {
                                low = mid + 1;
                            }
                        }
                        return low;
                    }

                    private boolean canFinish(int[] machines, int target, int moves) {
                        int balance = 0;
                        for (int dresses : machines) {
                            int delta = dresses - target;
                            balance += delta;
                            if (Math.abs(balance) > moves) return false;
                        }
                        return true;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Binary Search Feasibility Fixture",
                "O(n log S)",
                "O(1)",
                "Binary-search the smallest move count that satisfies every sender and boundary bottleneck.",
                "Feasibility is monotone because extra allowed moves can only relax the bottlenecks.",
                "- Time Complexity: O(n log S)\\n- Space Complexity: O(1)",
                code);
    }

