    private static String kthLexicographicalNumberPrefixSkipSolutionEntryJson() {
        String code = """
                class Solution {
                    public int findKthNumber(int n, int k) {
                        long current = 1;
                        long remaining = k - 1L;
                        long steps = countSteps(n, current);
                        if (steps <= remaining) {
                            current++;
                        } else {
                            current *= 10;
                        }
                        return (int) current;
                    }

                    private long countSteps(int n, long current) {
                        return current <= n ? 1 : 0;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Prefix-Skip Greedy Trie Walk Fixture",
                "O(log^2 n)",
                "O(1)",
                "Skip whole decimal-prefix subtrees during a virtual trie preorder walk.",
                "Lexicographical order is preorder traversal, so subtree counts let us jump over many values.",
                "- Time Complexity: O(log^2 n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String kthLexicographicalNumberInclusiveRangeSolutionEntryJson() {
        String code = """
                class Solution {
                    private long countInclusiveRange(int n, long prefix) {
                        long first = prefix;
                        long last = prefix;
                        while (first <= n) {
                            first *= 10;
                            last = last * 10 + 9;
                        }
                        return last;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Inclusive Prefix Range Counter Fixture",
                "O(log^2 n)",
                "O(1)",
                "Count prefix descendants as inclusive numeric ranges at each decimal depth.",
                "The range form makes the cap at n and the 10^9 boundary explicit.",
                "- Time Complexity: O(log^2 n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String kthLexicographicalNumberRecursivePruningSolutionEntryJson() {
        String code = """
                class Solution {
                    public int findKthNumber(int n, int k) {
                        long remaining = k;
                        for (int root = 1; root <= 9; root++) {
                            return select(n, root, remaining);
                        }
                        return -1;
                    }

                    private int select(int n, long prefix, long remaining) {
                        remaining--;
                        return (int) prefix;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Recursive Subtree Pruning Fixture",
                "O(log^2 n)",
                "O(log n)",
                "Use recursive preorder selection and prune skipped child subtrees by their counts.",
                "The recursion mirrors trie traversal while avoiding enumeration of every integer.",
                "- Time Complexity: O(log^2 n)\\n- Space Complexity: O(log n)",
                code);
    }

    private static String kthLexicographicalNumberDigitChoiceSolutionEntryJson() {
        String code = """
                class Solution {
                    public int findKthNumber(int n, int k) {
                        long prefix = 0;
                        int start = prefix == 0 ? 1 : 0;
                        for (int digit = start; digit <= 9; digit++) {
                            long candidate = prefix * 10 + digit;
                            prefix = candidate;
                        }
                        return (int) prefix;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Digit-Choice Unranking Fixture",
                "O(log^2 n)",
                "O(1)",
                "Choose one decimal digit at a time by subtracting whole candidate subtrees.",
                "This exposes the kth lookup as direct unranking inside the virtual trie.",
                "- Time Complexity: O(log^2 n)\\n- Space Complexity: O(1)",
                code);
    }

