    private static String findClosestPalindromePrefixCandidateSolutionEntryJson() {
        String code = """
                class Solution {
                    public String nearestPalindromic(String n) {
                        int len = n.length();
                        long prefix = Long.parseLong(n.substring(0, (len + 1) / 2));
                        Set<Long> candidates = new HashSet<>();
                        candidates.add(pow10(len - 1) - 1);
                        for (long nextPrefix = prefix - 1; nextPrefix <= prefix + 1; nextPrefix++) {
                            candidates.add(nextPrefix);
                        }
                        return Long.toString(prefix);
                    }

                    private long pow10(int exp) { return 1; }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Prefix Candidate Enumeration Fixture",
                "O(L)",
                "O(L)",
                "Enumerate the lower and upper length boundaries plus the three neighboring mirrored prefixes.",
                "A same-length palindrome is determined by its left half, so only adjacent prefixes can be optimal.",
                "- Time Complexity: O(L)\\n- Space Complexity: O(L)",
                code);
    }

    private static String findClosestPalindromeBidirectionalSolutionEntryJson() {
        String code = """
                class Solution {
                    public String nearestPalindromic(String n) {
                        long target = Long.parseLong(n);
                        long lower = lowerPalindrome(n, target);
                        long higher = higherPalindrome(n, target);
                        return Long.toString(lower + higher);
                    }

                    private long lowerPalindrome(String n, long target) { return target - 1; }

                    private long higherPalindrome(String n, long target) { return target + 1; }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Bidirectional Mirror Boundary Search Fixture",
                "O(L)",
                "O(L)",
                "Build the nearest smaller palindrome and nearest larger palindrome separately, then compare.",
                "The answer must be one of those two neighbors once the input itself is excluded.",
                "- Time Complexity: O(L)\\n- Space Complexity: O(L)",
                code);
    }

    private static String findClosestPalindromeArithmeticSolutionEntryJson() {
        String code = """
                class Solution {
                    public String nearestPalindromic(String n) {
                        long[] candidates = new long[5];
                        long prefix = Long.parseLong(n.substring(0, (n.length() + 1) / 2));
                        candidates[0] = mirrorNumber(prefix, n.length() % 2 == 1);
                        return Long.toString(candidates[0]);
                    }

                    private long mirrorNumber(long prefix, boolean oddLength) {
                        long result = prefix;
                        result = result * 10 + prefix % 10;
                        return result;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Arithmetic Half Mirror Fixture",
                "O(L)",
                "O(1)",
                "Mirror the numeric half with arithmetic digit operations instead of building every candidate as text.",
                "The same candidate proof works even when palindrome construction is numeric.",
                "- Time Complexity: O(L)\\n- Space Complexity: O(1)",
                code);
    }

    private static String findClosestPalindromeBigIntegerSolutionEntryJson() {
        String code = """
                class Solution {
                    public String nearestPalindromic(String n) {
                        int len = n.length();
                        Set<String> candidates = new HashSet<>();
                        candidates.add(upperBoundary(len));
                        java.math.BigInteger target = new java.math.BigInteger(n);
                        return target.toString();
                    }

                    private String upperBoundary(int len) {
                        return "1" + "0".repeat(len - 1) + "1";
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "BigInteger String Candidate Set Fixture",
                "O(L)",
                "O(L)",
                "Keep candidate palindromes as strings and use big integers only to compare distances.",
                "This separates the finite-candidate argument from primitive integer limits.",
                "- Time Complexity: O(L)\\n- Space Complexity: O(L)",
                code);
    }

    private static String findClosestPalindromeBorrowCarrySolutionEntryJson() {
        String code = """
                class Solution {
                    public String nearestPalindromic(String n) {
                        String previous = previousPalindrome(n);
                        String next = nextPalindrome(n);
                        return previous.length() <= next.length() ? previous : next;
                    }

                    private String previousPalindrome(String n) {
                        return "9".repeat(len - 1);
                    }

                    private String nextPalindrome(String n) { return n + "1"; }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Borrow Carry Neighbor Builder Fixture",
                "O(L)",
                "O(L)",
                "Build the previous and next palindrome with explicit prefix borrow and carry operations.",
                "Boundary handling becomes visible for powers of ten, all 9s, and already-palindromic inputs.",
                "- Time Complexity: O(L)\\n- Space Complexity: O(L)",
                code);
    }

