    private static String patchingArraySmallestMissingSolutionEntryJson() {
        String code = """
                class Solution {
                    public int minPatches(int[] nums, int n) {
                        long miss = 1;
                        int patches = 0;
                        while (miss <= n) {
                            miss += miss;
                            patches++;
                        }
                        return patches;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Smallest Missing Greedy Fixture",
                "O(m + log n)",
                "O(1)",
                "Track the smallest currently missing value and patch exactly that value when the array cannot help.",
                "Patching the first missing value is the only choice that removes the current gap and maximizes coverage.",
                "- Time Complexity: O(m + log n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String patchingArrayReachIntervalSolutionEntryJson() {
        String code = """
                class Solution {
                    public int minPatches(int[] nums, int n) {
                        long reach = 0;
                        int patches = 0;
                        while (reach < n) {
                            reach += reach + 1;
                            patches++;
                        }
                        return patches;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Reach Interval Greedy Fixture",
                "O(m + log n)",
                "O(1)",
                "Represent the invariant as a covered interval [1, reach] and patch reach + 1 when a gap appears.",
                "The interval formula exposes how the patch expands coverage to 2 * reach + 1.",
                "- Time Complexity: O(m + log n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String patchingArrayConsumeBeforePatchingSolutionEntryJson() {
        String code = """
                class Solution {
                    public int minPatches(int[] nums, int n) {
                        long coverage = 0;
                        int index = 0;
                        int patches = 0;
                        while (coverage < n) {
                            while (index < nums.length && nums[index] <= coverage + 1) {
                                coverage += nums[index++];
                            }
                            coverage += coverage + 1;
                            patches++;
                        }
                        return patches;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Consume Before Patching Fixture",
                "O(m + log n)",
                "O(1)",
                "Consume every usable original number before spending a patch on the next missing value.",
                "Original values are free coverage, so the greedy only patches after no usable input remains.",
                "- Time Complexity: O(m + log n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String patchingArrayGapBoundedSolutionEntryJson() {
        String code = """
                class Solution {
                    public int minPatches(int[] nums, int n) {
                        long coverage = 0;
                        int index = 0;
                        int patches = 0;
                        long nextValue = index < nums.length ? nums[index] : Long.MAX_VALUE;
                        long limit = Math.min((long) n, nextValue - 1);
                        while (coverage < limit) {
                            long patch = coverage + 1;
                            coverage += patch;
                            patches++;
                        }
                        return patches;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Gap-Bounded Patch Filling Fixture",
                "O(m + log n)",
                "O(1)",
                "Fill the gap before the next unusable array value by repeatedly adding coverage + 1.",
                "The next real input value acts as a milestone that bounds how far the current patch run must go.",
                "- Time Complexity: O(m + log n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String patchingArrayRecursiveSolutionEntryJson() {
        String code = """
                class Solution {
                    public int minPatches(int[] nums, int n) {
                        return solve(nums, n, 0, 1L);
                    }

                    private int solve(int[] nums, int n, int index, long miss) {
                        if (miss > n) return 0;
                        return 1 + solve(nums, n, index, miss + miss);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Recursive Coverage Selection Fixture",
                "O(m + log n)",
                "O(m + log n)",
                "Use recursion to make the current index and first missing value explicit.",
                "Each recursive step either consumes a usable input value or patches the first missing sum.",
                "- Time Complexity: O(m + log n)\\n- Space Complexity: O(m + log n)",
                code);
    }

