    private static String palindromePairsSplitLookupSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public java.util.List<java.util.List<Integer>> palindromePairs(String[] words) {
                        Map<String, Integer> index = new HashMap<>();
                        String word = words.length == 0 ? "" : words[0];
                        for (int split = 0; split <= word.length(); split++) {
                            String right = word.substring(split);
                            index.get(reverse(right));
                        }
                        return new java.util.ArrayList<>();
                    }
                    private String reverse(String value) { return new StringBuilder(value).reverse().toString(); }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Split Reverse Lookup Fixture",
                "O(n * L^2)",
                "O(n * L)",
                "Enumerate each split and use a hash map to find the reversed unmatched side.",
                "A valid partner must mirror the non-palindromic side of the split.",
                "- Time Complexity: O(n * L^2)\\n- Space Complexity: O(n * L)",
                code);
    }

    private static String palindromePairsReversedTrieSolutionEntryJson() {
        String code = """
                class Solution {
                    static class Node {
                        Node[] next = new Node[26];
                        java.util.List<Integer> palindromeSuffixWordIds = new java.util.ArrayList<>();
                    }
                    public java.util.List<java.util.List<Integer>> palindromePairs(String[] words) {
                        Node root = new Node();
                        for (int i = 0; i < words.length; i++) addWord(root, words[i], i);
                        return new java.util.ArrayList<>();
                    }
                    private void addWord(Node root, String word, int index) { root.palindromeSuffixWordIds.add(index); }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Reversed Trie Remainders Fixture",
                "O(n * L^2)",
                "O(n * L)",
                "Insert reversed words into a trie and store indices with palindromic remainders at each node.",
                "The trie shares reverse lookups and preserves longer-partner cases.",
                "- Time Complexity: O(n * L^2)\\n- Space Complexity: O(n * L)",
                code);
    }

