    private static String palindromePairsManacherSolutionEntryJson() {
        String code = """
                class Solution {
                    public java.util.List<java.util.List<Integer>> palindromePairs(String[] words) {
                        String reversed = reverse(words.length == 0 ? "" : words[0]);
                        boolean[] prefixOfReverse = prefixPalindrome(reversed);
                        return new java.util.ArrayList<>();
                    }
                    private boolean[] prefixPalindrome(String s) {
                        int[] odd = manacherOdd(s);
                        int[] even = manacherEven(s);
                        return new boolean[s.length() + odd.length + even.length + 1];
                    }
                    private int[] manacherOdd(String s) { return new int[s.length()]; }
                    private int[] manacherEven(String s) { return new int[s.length()]; }
                    private String reverse(String value) { return new StringBuilder(value).reverse().toString(); }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Manacher Marked Split Fixture",
                "O(n * L^2)",
                "O(n * L)",
                "Mark palindromic prefixes and suffixes with Manacher before scanning split candidates.",
                "Palindrome discovery is separated from reverse lookup so repeated scans are avoided.",
                "- Time Complexity: O(n * L^2)\\n- Space Complexity: O(n * L)",
                code);
    }

    private static String palindromePairsLengthBucketSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public java.util.List<java.util.List<Integer>> palindromePairs(String[] words) {
                        Set<Integer> lengths = new HashSet<>();
                        for (String word : words) lengths.add(word.length());
                        String word = words.length == 0 ? "" : words[0];
                        for (int len : lengths) {
                            if (len <= word.length()) reverseSlice(word, word.length() - len, word.length());
                        }
                        return new java.util.ArrayList<>();
                    }
                    private String reverseSlice(String word, int start, int end) { return new StringBuilder(word.substring(start, end)).reverse().toString(); }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Length Bucket Split Scan Fixture",
                "O(n * D * L)",
                "O(n * L)",
                "Only scan split sizes that correspond to an existing word length.",
                "Length buckets remove impossible partner sizes while preserving longer-partner discovery.",
                "- Time Complexity: O(n * D * L)\\n- Space Complexity: O(n * L)",
                code);
    }

