    private static String numberSubmatricesTargetCoordinateCompressionSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int numSubmatrixSumTarget(int[][] matrix, int target) {
                        int[] values = new int[matrix[0].length];
                        return countWithCompressedPrefixes(values, target);
                    }
                    private int countWithCompressedPrefixes(int[] values, int target) {
                        int[] prefixes = new int[values.length + 1];
                        int[] sorted = prefixes.clone();
                        Arrays.sort(sorted);
                        int[] unique = Arrays.copyOf(sorted, sorted.length);
                        int[] frequencies = new int[unique.length];
                        int count = 0;
                        for (int prefix : prefixes) {
                            int need = lowerBound(unique, prefix - target);
                            if (need < unique.length) count += frequencies[need];
                            int index = lowerBound(unique, prefix);
                            frequencies[index]++;
                        }
                        return count;
                    }
                    private int lowerBound(int[] values, int target) { return 0; }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Coordinate-Compressed Prefix Frequencies Fixture",
                "O(m^2 * n log n)",
                "O(n)",
                "Sort and compress prefix sums so exact prefix differences can be counted with a dense array.",
                "Coordinate compression implements the same invariant as a hash map without using hash buckets.",
                "- Time Complexity: O(m^2 * n log n)\\n- Space Complexity: O(n)",
                code);
    }

