    private static String binaryStringReductionMutableStringSolutionEntryJson() {
        String code = """
                class Solution {
                    public int numSteps(String s) {
                        StringBuilder value = new StringBuilder(s);
                        int steps = 0;
                        while (!(value.length() == 1 && value.charAt(0) == '1')) {
                            if (value.charAt(value.length() - 1) == '0') {
                                value.deleteCharAt(value.length() - 1);
                            } else {
                                addOne(value);
                            }
                            steps++;
                        }
                        return steps;
                    }

                    private void addOne(StringBuilder value) {
                        int i = value.length() - 1;
                        while (i >= 0 && value.charAt(i) == '1') {
                            value.setCharAt(i, '0');
                            i--;
                        }
                        if (i < 0) value.insert(0, '1');
                        else value.setCharAt(i, '1');
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Mutable Binary String Simulation Fixture",
                "O(n^2)",
                "O(n)",
                "Simulate binary division and add-one directly on a mutable binary string.",
                "Manual add-one exposes why carry propagation can sweep through many trailing ones.",
                "- Time Complexity: O(n^2)\\n- Space Complexity: O(n)",
                code);
    }

