    private static String arithmeticSubsequencesPerIndexMapSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int numberOfArithmeticSlices(int[] nums) {
                        int n = nums.length;
                        Map<Long, Integer>[] dp = new HashMap[n];
                        int answer = 0;
                        for (int i = 0; i < n; i++) {
                            dp[i] = new HashMap<>();
                            for (int j = 0; j < i; j++) {
                                long diff = (long) nums[i] - (long) nums[j];
                                int extend = dp[j].getOrDefault(diff, 0);
                                int current = dp[i].getOrDefault(diff, 0);
                                answer += extend;
                                dp[i].put(diff, current + extend + 1);
                            }
                        }
                        return answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Per-Index Difference Map DP Fixture",
                "O(n^2)",
                "O(n^2)",
                "Use a per-index endpoint difference table to count weak arithmetic subsequences.",
                "Weak length-two states let each pair both complete previous sequences and create a future state.",
                "- Time Complexity: O(n^2)\\n- Space Complexity: O(n^2)",
                code);
    }

    private static String arithmeticSubsequencesGlobalBucketSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int numberOfArithmeticSlices(int[] nums) {
                        int n = nums.length;
                        Map<Long, List<int[]>> pairsByDiff = new HashMap<>();
                        for (int i = 0; i < n; i++) {
                            for (int j = 0; j < i; j++) {
                                long diff = (long) nums[i] - (long) nums[j];
                                pairsByDiff.computeIfAbsent(diff, key -> new ArrayList<>()).add(new int[] {j, i});
                            }
                        }
                        long answer = 0;
                        for (List<int[]> pairs : pairsByDiff.values()) {
                            long[] weakEndingAt = new long[n];
                            for (int[] pair : pairs) {
                                int j = pair[0], i = pair[1];
                                long completed = weakEndingAt[j];
                                answer += completed;
                                weakEndingAt[i] += completed + 1;
                            }
                        }
                        return (int) answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Global Difference Bucket DP Fixture",
                "O(n^2)",
                "O(n^2)",
                "Group all index pairs by global difference buckets and solve each bucket independently.",
                "For one fixed difference, each pair extends weak sequences ending at its left endpoint.",
                "- Time Complexity: O(n^2)\\n- Space Complexity: O(n^2)",
                code);
    }

    private static String arithmeticSubsequencesCompressedArraysSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int numberOfArithmeticSlices(int[] nums) {
                        int n = nums.length;
                        Map<Long, Integer>[] ids = new HashMap[n];
                        long[][] counts = new long[n][];
                        for (int i = 0; i < n; i++) {
                            ids[i] = new HashMap<>();
                            for (int j = 0; j < i; j++) {
                                long diff = (long) nums[i] - (long) nums[j];
                                ids[i].putIfAbsent(diff, ids[i].size());
                            }
                            counts[i] = new long[ids[i].size()];
                        }
                        long answer = 0;
                        for (int i = 0; i < n; i++) {
                            for (int j = 0; j < i; j++) {
                                long diff = (long) nums[i] - (long) nums[j];
                                Integer previousSlot = ids[j].get(diff);
                                long extend = previousSlot == null ? 0 : counts[j][previousSlot];
                                int slot = ids[i].get(diff);
                                answer += extend;
                                counts[i][slot] += extend + 1;
                            }
                        }
                        return (int) answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Coordinate-Compressed Difference Arrays Fixture",
                "O(n^2)",
                "O(n^2)",
                "Compress incoming differences per endpoint, then run the DP over dense arrays.",
                "The sparse numeric difference domain still has only O(n^2) pair-derived states.",
                "- Time Complexity: O(n^2)\\n- Space Complexity: O(n^2)",
                code);
    }

    private static String arithmeticSubsequencesLastTwoDpSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int numberOfArithmeticSlices(int[] nums) {
                        int n = nums.length;
                        Map<Long, List<Integer>> indicesByValue = new HashMap<>();
                        long[][] dp = new long[n][n];
                        long answer = 0;
                        for (int i = 0; i < n; i++) {
                            for (int j = 0; j < i; j++) {
                                long previousValue = 2L * nums[j] - (long) nums[i];
                                List<Integer> candidates = indicesByValue.get(previousValue);
                                if (candidates != null) {
                                    for (int k : candidates) {
                                        if (k >= j) break;
                                        dp[j][i] += dp[k][j] + 1;
                                    }
                                }
                                answer += dp[j][i];
                            }
                        }
                        return (int) answer;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Last-Two-Index Bottom-Up DP Fixture",
                "O(n^3)",
                "O(n^2)",
                "Use last two selected indices as the DP state and scan predecessor indices.",
                "Each valid predecessor creates one triple and extends longer states ending at the previous pair.",
                "- Time Complexity: O(n^3)\\n- Space Complexity: O(n^2)",
                code);
    }

    private static String arithmeticSubsequencesMemoizedForwardSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int numberOfArithmeticSlices(int[] nums) {
                        Map<Long, List<Integer>> positions = new HashMap<>();
                        Map<String, Integer> memo = new HashMap<>();
                        int answer = 0;
                        int j = 0;
                        long diff = 0L;
                        answer += countAfter(j, diff, nums, positions, memo);
                        return answer;
                    }

                    private int countAfter(int last, long diff, int[] nums, Map<Long, List<Integer>> positions, Map<String, Integer> memo) {
                        long nextValue = (long) nums[last] + diff;
                        List<Integer> nextIndices = positions.get(nextValue);
                        int total = 0;
                        if (nextIndices != null) {
                            for (int next : nextIndices) {
                                total += 1 + countAfter(next, diff, nums, positions, memo);
                            }
                        }
                        return total;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Memoized Forward Pair Extension Fixture",
                "O(n^3)",
                "O(n^2)",
                "Start from each pair and memoize the forward extension tree by last index and difference.",
                "A chosen next index immediately completes one subsequence and may lead to longer continuations.",
                "- Time Complexity: O(n^3)\\n- Space Complexity: O(n^2)",
                code);
    }

