    private static String poorPigsOutcomeTreeSolutionEntryJson() {
        String code = """
                class Solution {
                    public int poorPigs(int buckets, int minutesToDie, int minutesToTest) {
                        int statesPerPig = minutesToTest / minutesToDie + 1;
                        int pigs = 0;
                        while (countOutcomeVectors(pigs, statesPerPig, buckets) < buckets) pigs++;
                        return pigs;
                    }

                    private int countOutcomeVectors(int pigs, int statesPerPig, int limit) {
                        if (pigs == 0) return 1;
                        int total = 0;
                        for (int state = 0; state < statesPerPig && total < limit; state++) {
                            int remainingLimit = limit - total;
                            total += countOutcomeVectors(pigs - 1, statesPerPig, remainingLimit);
                        }
                        return Math.min(total, limit);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Capped Outcome Tree Counting Fixture",
                "O(buckets * log buckets)",
                "O(log buckets)",
                "Count the leaves of the possible observation tree, stopping once enough buckets are covered.",
                "Each leaf is one complete vector of death rounds or survival outcomes.",
                "- Time Complexity: O(buckets * log buckets)\\n- Space Complexity: O(log buckets)",
                code);
    }

