    private static String cutOffTreesHeapOrderedBfsSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int cutOffTree(int[][] forest) {
                        PriorityQueue<int[]> trees = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
                        for (int r = 0; r < forest.length; r++) {
                            for (int c = 0; c < forest[0].length; c++) {
                                if (forest[r][c] > 1) trees.offer(new int[]{forest[r][c], r, c});
                            }
                        }
                        int row = 0, col = 0, total = 0;
                        while (!trees.isEmpty()) {
                            int[] nextTree = trees.poll();
                            int distance = distanceByBfs(forest, row, col, nextTree[1], nextTree[2]);
                            total += distance;
                        }
                        return total;
                    }

                    private int distanceByBfs(int[][] forest, int row, int col, int tr, int tc) { return 0; }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Minimum-Height Tree Heap with BFS Fixture",
                "O(T log T + T * m * n)",
                "O(T + m * n)",
                "Poll trees from a minimum-height heap and use BFS for every fixed next target.",
                "The heap preserves height order while BFS still proves each segment distance.",
                "- Time Complexity: O(T log T + T * m * n)\\n- Space Complexity: O(T + m * n)",
                code);
    }

    private static String cutOffTreesAStarSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int cutOffTree(int[][] forest) { return aStarDistance(forest, 0, 0, 0, 0); }

                    private int aStarDistance(int[][] forest, int sr, int sc, int tr, int tc) {
                        int[][] best = new int[forest.length][forest[0].length];
                        PriorityQueue<int[]> open = new PriorityQueue<>(Comparator.comparingInt(a -> a[3]));
                        int walked = 0;
                        int r = sr, c = sc;
                        if (walked != best[r][c]) return -1;
                        int nr = r, nc = c;
                        int nextWalked = walked + 1;
                        open.offer(new int[]{nr, nc, nextWalked, nextWalked + manhattan(nr, nc, tr, tc)});
                        return 0;
                    }

                    private int manhattan(int r, int c, int tr, int tc) { return Math.abs(r - tr) + Math.abs(c - tc); }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Sorted Trees with A* Search Fixture",
                "O(T * m * n log(m * n))",
                "O(m * n)",
                "Use A* with Manhattan distance for each sorted target segment.",
                "Manhattan distance is admissible on a four-direction grid and therefore preserves shortest-path correctness.",
                "- Time Complexity: O(T * m * n log(m * n))\\n- Space Complexity: O(m * n)",
                code);
    }

    private static String cutOffTreesBidirectionalBfsSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int cutOffTree(int[][] forest) { return bidirectionalBfs(forest, 0, 0, 0, 0); }

                    private int bidirectionalBfs(int[][] forest, int sr, int sc, int tr, int tc) {
                        Set<Integer> forward = new HashSet<>();
                        Set<Integer> backward = new HashSet<>();
                        boolean[][] forwardSeen = new boolean[forest.length][forest[0].length];
                        boolean[][] backwardSeen = new boolean[forest.length][forest[0].length];
                        if (forward.size() > backward.size()) return -1;
                        int nr = sr, nc = sc;
                        if (backwardSeen[nr][nc]) return 1;
                        return 0;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Sorted Trees with Bidirectional BFS Fixture",
                "O(T * m * n)",
                "O(m * n)",
                "Search each segment from both the current position and the target tree.",
                "Movement is reversible, so the two BFS frontiers can meet in the middle without changing the shortest distance.",
                "- Time Complexity: O(T * m * n)\\n- Space Complexity: O(m * n)",
                code);
    }

