    private static String stickersToSpellWordBitmaskDpSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int minStickers(String[] stickers, String target) {
                        int n = target.length();
                        int[] dp = new int[1 << n];
                        for (int mask = 0; mask < (1 << n); mask++) {
                            int nextMask = mask;
                            dp[nextMask] = Math.min(dp[nextMask], dp[mask] + 1);
                        }
                        return dp[0];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Bitmask Dynamic Programming Fixture",
                "O(2^t * s * t)",
                "O(2^t)",
                "Use target positions as a bitmask state and relax the result of applying one sticker.",
                "Equal letters still need separate target positions because one sticker letter covers one occurrence.",
                "- Time Complexity: O(2^t * s * t)\\n- Space Complexity: O(2^t)",
                code);
    }

