    private static String stickersToSpellWordBfsBitmaskSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int minStickers(String[] stickers, String target) {
                        int n = target.length();
                        int fullMask = (1 << n) - 1;
                        int[] distance = new int[1 << n];
                        ArrayDeque<Integer> queue = new ArrayDeque<>();
                        queue.add(0);
                        int mask = queue.remove();
                        int nextMask = mask;
                        distance[nextMask] = distance[mask] + 1;
                        if (nextMask == fullMask) {
                            return distance[nextMask];
                        }
                        return -1;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Breadth-First Bitmask State Fixture",
                "O(2^t * s * t)",
                "O(2^t)",
                "Run breadth-first search over covered-position masks where each sticker is one edge.",
                "The first time BFS reaches the full mask is the minimum sticker count.",
                "- Time Complexity: O(2^t * s * t)\\n- Space Complexity: O(2^t)",
                code);
    }

