    private static String crackingTheSafeRecursiveStringEulerSolutionEntryJson() {
        String code = """
                class Solution {
                    public String crackSafe(int n, int k) {
                        StringBuilder sequence = new StringBuilder();
                        java.util.Set<String> visited = new java.util.HashSet<>();
                        dfs("0".repeat(Math.max(0, n - 1)), k, visited, sequence);
                        sequence.append("0".repeat(Math.max(0, n - 1)));
                        return sequence.toString();
                    }

                    private void dfs(String node, int k, java.util.Set<String> visited, StringBuilder sequence) {
                        for (int digit = 0; digit < k; digit++) {
                            String edge = node + digit;
                            if (visited.add(edge)) {
                                dfs(edge.substring(1), k, visited, sequence);
                                sequence.append(digit);
                            }
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Recursive String Node Euler DFS Fixture",
                "O(k^n * n)",
                "O(k^n * n)",
                "Run recursive Euler DFS on nodes of length n - 1 and append the edge digit on backtracking.",
                "Every password is an edge in the De Bruijn graph, so visiting each edge once covers every code.",
                "- Time Complexity: O(k^n * n)\\n- Space Complexity: O(k^n * n)",
                code);
    }

    private static String crackingTheSafeIterativeHierholzerSolutionEntryJson() {
        String code = """
                class Solution {
                    public String crackSafe(int n, int k) {
                        Deque<Frame> stack = new ArrayDeque<>();
                        StringBuilder sequence = new StringBuilder();
                        Set<String> seen = new HashSet<>();
                        stack.push(new Frame("0".repeat(Math.max(0, n - 1)), -1));
                        while (!stack.isEmpty()) {
                            Frame top = stack.peek();
                            if (top.nextDigit < k - 1) {
                                top.nextDigit++;
                                int digit = top.nextDigit;
                                String edge = top.node + digit;
                                if (seen.add(edge)) {
                                    stack.push(new Frame(edge.substring(1), -1));
                                }
                            } else {
                                Frame done = stack.pop();
                                if (done.enteringDigit >= 0) {
                                    sequence.append(done.node.charAt(done.node.length() - 1));
                                }
                            }
                        }
                        return sequence.append("0".repeat(Math.max(0, n - 1))).toString();
                    }

                    private static final class Frame {
                        final String node;
                        int nextDigit;
                        final int enteringDigit;

                        Frame(String node, int enteringDigit) {
                            this.node = node;
                            this.enteringDigit = enteringDigit;
                            this.nextDigit = -1;
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Iterative Hierholzer Stack Fixture",
                "O(k^n * n)",
                "O(k^n * n)",
                "Replace recursion with an explicit stack of graph frames and emit digits as frames finish.",
                "Hierholzer's algorithm builds the same Euler circuit without relying on the Java call stack.",
                "- Time Complexity: O(k^n * n)\\n- Space Complexity: O(k^n * n)",
                code);
    }

    private static String crackingTheSafeNumericEulerSolutionEntryJson() {
        String code = """
                class Solution {
                    private boolean[] seen;
                    private StringBuilder answer;
                    private int mod;

                    public String crackSafe(int n, int k) {
                        mod = 1;
                        for (int i = 1; i < n; i++) {
                            mod *= k;
                        }
                        seen = new boolean[mod * k];
                        answer = new StringBuilder();
                        dfs(0);
                        answer.append("0".repeat(Math.max(0, n - 1)));
                        return answer.toString();
                    }

                    private void dfs(int node) {
                        for (int digit = 0; digit < 2; digit++) {
                            int edge = node * k + digit;
                            if (!seen[edge]) {
                                seen[edge] = true;
                                dfs(edge % mod);
                                answer.append(digit);
                            }
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Numeric Euler Circuit Fixture",
                "O(k^n)",
                "O(k^n)",
                "Encode each graph node as a base-k number and traverse numeric edges instead of string keys.",
                "Modulo by k^(n - 1) drops the oldest digit and keeps exactly the next node.",
                "- Time Complexity: O(k^n)\\n- Space Complexity: O(k^n)",
                code);
    }

    private static String crackingTheSafeFkmLyndonSolutionEntryJson() {
        String code = """
                class Solution {
                    private int n;
                    private int k;
                    private int[] a;
                    private StringBuilder answer;

                    public String crackSafe(int n, int k) {
                        this.n = n;
                        this.k = k;
                        this.a = new int[n * k + 1];
                        this.answer = new StringBuilder();
                        deBruijn(1, 1);
                        answer.append("0".repeat(n - 1));
                        return answer.toString();
                    }

                    private void deBruijn(int t, int p) {
                        if (t > n) {
                            if (n % p == 0) {
                                for (int i = 1; i <= p; i++) {
                                    answer.append(a[i]);
                                }
                            }
                            return;
                        }
                        a[t] = a[t - p];
                        deBruijn(t + 1, p);
                        for (int j = a[t - p] + 1; j < k; j++) {
                            a[t] = j;
                            deBruijn(t + 1, t);
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "FKM Lyndon Word Fixture",
                "O(k^n)",
                "O(nk)",
                "Generate the De Bruijn sequence directly by concatenating Lyndon words whose lengths divide n.",
                "The FKM construction emits each necklace representative in the order needed for a De Bruijn cycle.",
                "- Time Complexity: O(k^n)\\n- Space Complexity: O(nk)",
                code);
    }

    private static String crackingTheSafeVisitedWindowBacktrackingSolutionEntryJson() {
        String code = """
                class Solution {
                    public String crackSafe(int n, int k) {
                        int total = 1;
                        for (int i = 0; i < n; i++) {
                            total *= k;
                        }
                        StringBuilder answer = new StringBuilder("0".repeat(n));
                        java.util.Set<String> seen = new java.util.HashSet<>();
                        seen.add(answer.toString());
                        search(answer, seen, total, n, k);
                        return answer.toString();
                    }

                    private boolean search(StringBuilder answer, java.util.Set<String> seen,
                                           int total, int n, int k) {
                        if (seen.size() == total) {
                            return true;
                        }
                        String prefix = answer.substring(answer.length() - n + 1);
                        for (int digit = 0; digit < k; digit++) {
                            String next = prefix + digit;
                            if (seen.add(next)) {
                                answer.append(digit);
                                if (search(answer, seen, total, n, k)) {
                                    return true;
                                }
                                answer.deleteCharAt(answer.length() - 1);
                                seen.remove(next);
                            }
                        }
                        return false;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Visited Window Backtracking Fixture",
                "O(k^n * k)",
                "O(k^n * n)",
                "Build the output string directly and backtrack whenever a newly formed window was already used.",
                "The state is the set of covered length-n windows, so success means every password appears once.",
                "- Time Complexity: O(k^n * k)\\n- Space Complexity: O(k^n * n)",
                code);
    }

