    private static String couplesHoldingHandsCompactBfsSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int minSwapsCouples(int[] row) {
                        int couples = row.length / 2;
                        int[][] neighbors = new int[couples][2];
                        int[] degree = new int[couples];
                        ArrayDeque<Integer> queue = new ArrayDeque<>();
                        for (int sofa = 0; sofa < row.length; sofa += 2) {
                            int a = row[sofa] / 2;
                            int b = row[sofa + 1] / 2;
                            neighbors[a][degree[a]++] = b;
                            neighbors[b][degree[b]++] = a;
                        }
                        boolean[] seen = new boolean[couples];
                        int swaps = 0;
                        for (int start = 0; start < couples; start++) {
                            queue.add(start);
                            while (!queue.isEmpty()) {
                                int current = queue.remove();
                                for (int i = 0; i < degree[current]; i++) {
                                    int next = neighbors[current][i];
                                    queue.add(next);
                                }
                            }
                        }
                        return swaps;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Compact BFS over Couple Cycles Fixture",
                "O(n)",
                "O(n)",
                "Use fixed neighbor arrays and a queue to traverse the compact couple graph.",
                "The seating graph has tiny degree, so a compact breadth-first traversal is enough.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

