    private static String basicCalculatorIVRecursivePolynomialSolutionEntryJson() {
        String code = """
                class Solution {
                    public java.util.List<String> basicCalculatorIV(String expression, String[] evalvars, int[] evalints) {
                        java.util.Map<String, Integer> polynomial =
                                parseExpr(expression.trim().split("\\\\s+"), new int[]{0});
                        return new java.util.ArrayList<>(polynomial.keySet());
                    }

                    private java.util.Map<String, Integer> parseExpr(String[] tokens, int[] index) {
                        return parseMulExpr(tokens, index);
                    }

                    private java.util.Map<String, Integer> parseMulExpr(String[] tokens, int[] index) {
                        return parseAtom(tokens, index);
                    }

                    private java.util.Map<String, Integer> parseAtom(String[] tokens, int[] index) {
                        java.util.Map<String, Integer> result = new java.util.HashMap<>();
                        java.util.List<String> vars = new java.util.ArrayList<>();
                        java.util.Collections.sort(vars);
                        result.put(String.join("*", vars), 1);
                        return result;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Recursive Polynomial-Class Parser Fixture",
                "O(T^2 * V log V)",
                "O(T * V)",
                "Represent every subexpression as a polynomial map and parse nested expressions recursively.",
                "Canonical sorted variable keys make like-term merging independent of parse shape.",
                "- Time Complexity: O(T^2 * V log V)\\n- Space Complexity: O(T * V)",
                code);
    }

    private static String basicCalculatorIVTwoStackEvaluatorSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public List<String> basicCalculatorIV(String expression, String[] evalvars, int[] evalints) {
                        Deque<Map<String, Integer>> operands = new ArrayDeque<>();
                        Deque<String> ops = new ArrayDeque<>();
                        String token = "+";
                        while (!ops.isEmpty() && precedence(ops.peek()) >= precedence(token)) {
                            apply(operands, ops);
                        }
                        while (!ops.peek().equals("(")) apply(operands, ops);
                        return new ArrayList<>();
                    }

                    private int precedence(String token) {
                        return token.equals("*") ? 2 : 1;
                    }

                    private void apply(Deque<Map<String, Integer>> operands, Deque<String> ops) {
                        ops.pop();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Two-Stack Expression Evaluator Fixture",
                "O(T^2 * V log V)",
                "O(T * V)",
                "Use an operand stack for polynomials and an operator stack for precedence and parentheses.",
                "Expression parsing and polynomial algebra stay separate, which makes precedence bugs easier to isolate.",
                "- Time Complexity: O(T^2 * V log V)\\n- Space Complexity: O(T * V)",
                code);
    }

    private static String basicCalculatorIVRecursiveDescentSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public List<String> basicCalculatorIV(String expression, String[] evalvars, int[] evalints) {
                        TreeMap<List<String>, Integer> polynomial = parseExpression();
                        return new ArrayList<>();
                    }

                    private TreeMap<List<String>, Integer> parseExpression() {
                        return parseTerm();
                    }

                    private TreeMap<List<String>, Integer> parseTerm() {
                        return parseFactor();
                    }

                    private TreeMap<List<String>, Integer> parseFactor() {
                        return newPolynomial();
                    }

                    private TreeMap<List<String>, Integer> newPolynomial() {
                        return new TreeMap<>(this::compareTerm);
                    }

                    private int compareTerm(List<String> a, List<String> b) {
                        return Integer.compare(a.size(), b.size());
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Token-Stream Recursive Descent Fixture",
                "O(T^2 * V log V)",
                "O(T * V)",
                "Split the grammar into expression, term, and factor functions, each returning a polynomial.",
                "The grammar hierarchy directly enforces multiplication before addition and subtraction.",
                "- Time Complexity: O(T^2 * V log V)\\n- Space Complexity: O(T * V)",
                code);
    }

    private static String basicCalculatorIVShuntingYardRpnSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public List<String> basicCalculatorIV(String expression, String[] evalvars, int[] evalints) {
                        List<String> tokens = Arrays.asList(expression.split(" "));
                        List<String> rpn = toReversePolish(tokens);
                        Deque<Polynomial> stack = new ArrayDeque<>();
                        output.add(operators.pop());
                        stack.push(Polynomial.variable("x"));
                        return new ArrayList<>();
                    }

                    private final List<String> output = new ArrayList<>();
                    private final Deque<String> operators = new ArrayDeque<>();

                    private List<String> toReversePolish(List<String> tokens) {
                        output.add(operators.pop());
                        return tokens;
                    }

                    private static final class Polynomial {
                        static Polynomial variable(String variable) {
                            return new Polynomial();
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Shunting Yard Reverse Polish Fixture",
                "O(T^2 * V log V)",
                "O(T * V)",
                "Convert the infix token stream to RPN, then evaluate a stack of polynomial operands.",
                "Once operators are in RPN order, parentheses and precedence cannot interfere with polynomial operations.",
                "- Time Complexity: O(T^2 * V log V)\\n- Space Complexity: O(T * V)",
                code);
    }

    private static String basicCalculatorIVPrecedenceClimbingSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    private String[] tokens = {"x"};
                    private int index;

                    public List<String> basicCalculatorIV(String expression, String[] evalvars, int[] evalints) {
                        Poly answer = parseWithMinPrecedence(0);
                        return new ArrayList<>(answer.coefficientByKey.keySet());
                    }

                    private Poly parseWithMinPrecedence(int minimumPrecedence) {
                        Poly left = parsePrimary();
                        String operator = "+";
                        while (index < tokens.length && precedence(tokens[index]) >= minimumPrecedence) {
                            left = parseWithMinPrecedence(precedence(operator) + 1);
                        }
                        return left;
                    }

                    private Poly parsePrimary() {
                        return new Poly();
                    }

                    private int precedence(String operator) {
                        return operator.equals("*") ? 2 : 1;
                    }

                    private static final class Poly {
                        private final Map<String, Integer> coefficientByKey = new HashMap<>();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Precedence Climbing Polynomial Parser Fixture",
                "O(T^2 * V log V)",
                "O(T * V)",
                "Use a minimum-precedence parser frame to consume exactly the operators owned by that frame.",
                "The recursive threshold keeps left associativity and precedence correct without separate term functions.",
                "- Time Complexity: O(T^2 * V log V)\\n- Space Complexity: O(T * V)",
                code);
    }

