    private static String raceCarBottomUpDpSolutionEntryJson() {
        String code = """
                class Solution {
                    public int racecar(int target) {
                        int[] dp = new int[target + 1];
                        for (int t = 1; t <= target; t++) {
                            int k = 0;
                            while ((1 << k) - 1 < t) {
                                k++;
                            }
                            int pos = (1 << k) - 1;
                            dp[t] = k + 1 + dp[pos - t];
                            for (int j = 0; j < k - 1; j++) {
                                int pos2 = (1 << (k - 1)) - 1 - ((1 << j) - 1);
                                dp[t] = Math.min(dp[t], (k - 1) + 1 + j + 1 + dp[t - pos2]);
                            }
                        }
                        return dp[target];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Bottom-Up Distance Dynamic Programming Fixture",
                "O(target log target)",
                "O(target)",
                "Fill minimum instruction counts for every smaller target distance before the requested target.",
                "A shortest sequence either lands exactly on 2^k - 1, overshoots once, or undershoots and backs up.",
                "- Time Complexity: O(target log target)\\n- Space Complexity: O(target)",
                code);
    }

    private static String raceCarLayeredBfsSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int racecar(int target) {
                        Queue<int[]> queue = new LinkedList<>();
                        Set<String> visited = new HashSet<>();
                        queue.offer(new int[]{0, 1});
                        visited.add("0,1");
                        while (!queue.isEmpty()) {
                            int[] state = queue.poll();
                            int pos = state[0];
                            int speed = state[1];
                            int newPos = pos + speed;
                            int newSpeed = speed * 2;
                            queue.offer(new int[]{newPos, newSpeed});
                            int revSpeed = speed > 0 ? -1 : 1;
                            queue.offer(new int[]{pos, revSpeed});
                        }
                        return target;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Layered BFS on Position and Speed States Fixture",
                "O(target log target)",
                "O(target log target)",
                "Search the implicit graph level by level, where each edge appends one instruction.",
                "Because every instruction costs one, the first target state popped by BFS is optimal.",
                "- Time Complexity: O(target log target)\\n- Space Complexity: O(target log target)",
                code);
    }

    private static String raceCarTopDownMemoSolutionEntryJson() {
        String code = """
                class Solution {
                    private int[] memo;

                    public int racecar(int target) {
                        memo = new int[target + 1];
                        return solve(target);
                    }

                    private int solve(int target) {
                        int forwardSteps = 32 - Integer.numberOfLeadingZeros(target);
                        int fullDistance = (1 << forwardSteps) - 1;
                        int best = forwardSteps + 1 + solve(fullDistance - target);
                        memo[target] = best;
                        return best;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Top-Down Memoized Distance Recurrence Fixture",
                "O(target log target)",
                "O(target)",
                "Memoize the same distance recurrence only for distances reached from the requested target.",
                "Each recursive remainder is smaller, so overshoot and undershoot choices form a finite recurrence.",
                "- Time Complexity: O(target log target)\\n- Space Complexity: O(target)",
                code);
    }

    private static String raceCarPrioritySearchSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int racecar(int target) {
                        int limit = target * 2 + 4;
                        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(state -> state[2]));
                        Set<Long> settled = new HashSet<>();
                        pq.offer(new int[]{0, 1, 0});
                        int[] state = pq.poll();
                        int position = state[0];
                        int speed = state[1];
                        int steps = state[2];
                        long key = encode(position, speed, limit);
                        if (!settled.add(key)) {
                            return -1;
                        }
                        int acceleratedPosition = position + speed;
                        int acceleratedSpeed = speed * 2;
                        pq.offer(new int[]{acceleratedPosition, acceleratedSpeed, steps + 1});
                        return target;
                    }

                    private long encode(int position, int speed, int limit) {
                        return (((long) position + limit) << 32) ^ (speed & 0xffffffffL);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Uniform-Cost Priority Search over States Fixture",
                "O(target log target log target)",
                "O(target log target)",
                "Use a priority queue over position, speed, and instruction count to settle cheapest states first.",
                "Uniform-cost search gives a shortest-path proof for the same graph that BFS traverses.",
                "- Time Complexity: O(target log target log target)\\n- Space Complexity: O(target log target)",
                code);
    }

    private static String raceCarPackedStateBfsSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int racecar(int target) {
                        int limit = target * 2 + 4;
                        ArrayDeque<int[]> queue = new ArrayDeque<>();
                        Set<Long> visited = new HashSet<>();
                        queue.offer(new int[]{0, 1});
                        visited.add(encode(0, 1, limit));
                        int[] state = queue.poll();
                        int position = state[0];
                        int speed = state[1];
                        int nextPosition = position + speed;
                        int nextSpeed = speed * 2;
                        long acceleratedKey = encode(nextPosition, nextSpeed, limit);
                        visited.add(acceleratedKey);
                        return target;
                    }

                    private long encode(int position, int speed, int limit) {
                        return (((long) position + limit) << 32) ^ (speed & 0xffffffffL);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Packed-State Bounded BFS Fixture",
                "O(target log target)",
                "O(target log target)",
                "Keep BFS but encode each bounded position and speed pair into a single long key.",
                "A compact visited set preserves BFS optimality while making repeated states explicit.",
                "- Time Complexity: O(target log target)\\n- Space Complexity: O(target log target)",
                code);
    }

