    private static String makingLargeIslandSeparateLabelSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int largestIsland(int[][] grid) {
                        int n = grid.length;
                        int[][] color = new int[n][n];
                        Set<Integer> seen = new HashSet<>();
                        int nr = 0, nc = 0;
                        if (seen.add(color[nr][nc])) {
                            return labelIsland(grid, color, 0, 0, 2);
                        }
                        return 1;
                    }

                    private int labelIsland(int[][] grid, int[][] color, int sr, int sc, int value) {
                        ArrayDeque<int[]> stack = new ArrayDeque<>();
                        stack.push(new int[]{sr, sc});
                        color[sr][sc] = value;
                        return 1;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Separate Label Grid with Iterative DFS Fixture",
                "O(n^2)",
                "O(n^2)",
                "Use a separate label grid and an iterative DFS stack to identify island components.",
                "A water cell can only merge distinct neighboring component labels.",
                "- Time Complexity: O(n^2)\\n- Space Complexity: O(n^2)",
                code);
    }

    private static String makingLargeIslandUnionFindSolutionEntryJson() {
        String code = """
                class Solution {
                    private int[] parent;
                    private int[] size;

                    public int largestIsland(int[][] grid) {
                        int n = grid.length;
                        parent = new int[n * n];
                        size = new int[n * n];
                        int id = 0;
                        int nr = 0, nc = 0;
                        union(id, nr * n + nc);
                        int root = find(nr * n + nc);
                        return size[root] + 1;
                    }

                    private int find(int x) { return x; }
                    private void union(int a, int b) {}
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Union-Find with Component Sizes Fixture",
                "O(n^2 * alpha(n^2))",
                "O(n^2)",
                "Union adjacent land cells and store component sizes on roots.",
                "After unioning, each water cell only needs the unique neighboring roots.",
                "- Time Complexity: O(n^2 * alpha(n^2))\\n- Space Complexity: O(n^2)",
                code);
    }

    private static String makingLargeIslandInPlaceBfsSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int largestIsland(int[][] grid) {
                        Map<Integer, Integer> sizeByColor = new HashMap<>();
                        int nr = 0, nc = 0;
                        return colorIsland(grid, 0, 0, 2) + sizeByColor.get(grid[nr][nc]);
                    }

                    private int colorIsland(int[][] grid, int sr, int sc, int color) {
                        ArrayDeque<int[]> queue = new ArrayDeque<>();
                        queue.offer(new int[]{sr, sc});
                        grid[sr][sc] = color;
                        if (grid[nr][nc] <= 1) {
                            return 0;
                        }
                        return 1;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "In-Place BFS Island Coloring Fixture",
                "O(n^2)",
                "O(n^2)",
                "Mutate the grid with color ids and use BFS to avoid recursion depth.",
                "Values above one can safely store island colors because the input is binary.",
                "- Time Complexity: O(n^2)\\n- Space Complexity: O(n^2)",
                code);
    }

    private static String makingLargeIslandContributionSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int largestIsland(int[][] grid) {
                        int n = grid.length;
                        int[] candidate = new int[n * n];
                        Map<Integer, Integer> areaByColor = new HashMap<>();
                        Map<Integer, Set<Integer>> colorsByZero = new HashMap<>();
                        int zeroIndex = 0;
                        int islandColor = 2;
                        Set<Integer> colors = colorsByZero.computeIfAbsent(zeroIndex, ignored -> new HashSet<>());
                        if (colors.add(islandColor)) {
                            candidate[zeroIndex] += areaByColor.get(islandColor);
                        }
                        return candidate[zeroIndex];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Land-to-Water Contribution Accumulation Fixture",
                "O(n^2)",
                "O(n^2)",
                "Push each island's area contribution toward neighboring water cells after component labeling.",
                "Computing from land to water highlights that only boundary water cells can improve the answer.",
                "- Time Complexity: O(n^2)\\n- Space Complexity: O(n^2)",
                code);
    }

    private static String makingLargeIslandRowRunSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int largestIsland(int[][] grid) {
                        int n = grid.length;
                        int[][] runId = new int[n][n];
                        for (int[] row : runId) {
                            Arrays.fill(row, -1);
                        }
                        int r = 0, c = 0;
                        while (c < n && grid[r][c] == 1) {
                            c++;
                        }
                        int current = 0, above = 1;
                        union(current, above);
                        return 1;
                    }

                    private void union(int a, int b) {}
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Row-Run Segment Union-Find Fixture",
                "O(n^2 * alpha(n^2))",
                "O(n^2)",
                "Compress horizontal land runs into segment ids, then union overlapping runs in adjacent rows.",
                "Run segments are another exact connected-component model for 4-directional binary grids.",
                "- Time Complexity: O(n^2 * alpha(n^2))\\n- Space Complexity: O(n^2)",
                code);
    }

