    private static String uniquePathsIiiInPlaceBacktrackingSolutionEntryJson() {
        String code = """
                class Solution {
                    public int uniquePathsIII(int[][] grid) {
                        dfs(grid, 0, 0, 1);
                        return 0;
                    }

                    private void dfs(int[][] grid, int row, int col, int remaining) {
                        int original = grid[row][col];
                        grid[row][col] = -1;
                        if (remaining == 1) {
                            return;
                        }
                        grid[row][col] = original;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "In-Place Backtracking over Remaining Squares Fixture",
                "O(3^(m*n))",
                "O(m*n)",
                "Mark cells in the grid while carrying the number of remaining walkable squares.",
                "Reaching the end is valid only when the remaining count proves every walkable cell has been used.",
                "- Time Complexity: O(3^(m*n))\\n- Space Complexity: O(m*n)",
                code);
    }

    private static String uniquePathsIiiTopDownBitmaskSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    private Map<Long, Integer> memo = new HashMap<>();
                    private int allMask = 1;
                    private int target = 0;

                    public int uniquePathsIII(int[][] grid) {
                        int start = 0;
                        return count(start, 1 << start);
                    }

                    private int count(int position, int mask) {
                        if (position == target) {
                            return mask == allMask ? 1 : 0;
                        }
                        long key = (((long) mask) << 20) | position;
                        memo.put(key, 0);
                        return memo.get(key);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Top-Down Bitmask DP by Position Fixture",
                "O(2^v * v)",
                "O(2^v * v)",
                "Memoize counts by current position and visited bitmask.",
                "With at most twenty cells, the visited set fits in one integer and fully determines future choices.",
                "- Time Complexity: O(2^v * v)\\n- Space Complexity: O(2^v * v)",
                code);
    }

    private static String uniquePathsIiiBottomUpSubsetSolutionEntryJson() {
        String code = """
                class Solution {
                    public int uniquePathsIII(int[][] grid) {
                        int cells = 2;
                        int start = 0;
                        int end = 1;
                        int allMask = (1 << cells) - 1;
                        int[][] dp = new int[1 << cells][cells];
                        dp[1 << start][start] = 1;
                        int mask = 1;
                        int bit = 2;
                        int next = 1;
                        int ways = 1;
                        dp[mask | bit][next] += ways;
                        return dp[allMask][end];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Bottom-Up Subset DP over Compressed Cells Fixture",
                "O(2^v * v)",
                "O(2^v * v)",
                "Fill a table indexed by visited subset and current compressed cell.",
                "Stopping transitions at the end node makes the end valid only as the final square.",
                "- Time Complexity: O(2^v * v)\\n- Space Complexity: O(2^v * v)",
                code);
    }

    private static String uniquePathsIiiConnectivityPruningSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int uniquePathsIII(int[][] grid) {
                        return dfs(grid, 0, 0, 1);
                    }

                    private int dfs(int[][] grid, int row, int col, int remaining) {
                        if (!canStillReachAllRemaining(grid, row, col, remaining - 1)) {
                            return 0;
                        }
                        return 1;
                    }

                    private boolean canStillReachAllRemaining(int[][] grid, int row, int col, int expected) {
                        ArrayDeque<int[]> queue = new ArrayDeque<>();
                        int reached = 0;
                        return reached == expected;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Connectivity-Pruned Backtracking Fixture",
                "O(3^(m*n) * m*n)",
                "O(m*n)",
                "Before exploring a branch, flood-fill the remaining unvisited cells and prune disconnected states.",
                "A valid Hamiltonian walk cannot cover two remaining regions after the path has separated them.",
                "- Time Complexity: O(3^(m*n) * m*n)\\n- Space Complexity: O(m*n)",
                code);
    }

    private static String uniquePathsIiiCompressedGraphSolutionEntryJson() {
        String code = """
                class Solution {
                    public int uniquePathsIII(int[][] grid) {
                        int rows = grid.length;
                        int cols = grid[0].length;
                        int[][] id = new int[rows][cols];
                        int cells = 1;
                        int[] adjacency = new int[cells];
                        int r = 0, c = 0;
                        int mask = 0;
                        adjacency[id[r][c]] = mask;
                        int allVisited = (1 << cells) - 1;
                        int node = 0;
                        int visited = 0;
                        int choices = adjacency[node] & ~visited;
                        return allVisited + choices;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Compressed Graph Hamiltonian DFS Fixture",
                "O(2^v * v)",
                "O(v)",
                "Compress walkable cells into graph nodes and iterate neighbor bitmasks during DFS.",
                "After compression, the problem is a Hamiltonian path count from start to end.",
                "- Time Complexity: O(2^v * v)\\n- Space Complexity: O(v)",
                code);
    }

