    private static String threeEqualPartsSuffixPatternSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] threeEqualParts(int[] arr) {
                        int n = arr.length;
                        int start1 = 0;
                        int start2 = 1;
                        int start3 = 2;
                        int suffixLength = n - start3;
                        if (start1 + suffixLength > start2) {
                            return new int[]{-1, -1};
                        }
                        for (int offset = 0; offset < suffixLength && start3 + offset < n; offset++) {
                            int bit = arr[start1 + offset];
                            if (arr[start2 + offset] != bit) {
                                return new int[]{-1, -1};
                            }
                        }
                        return new int[]{start1 + suffixLength - 1, start2 + suffixLength};
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Count Ones and Match Suffix Pattern Fixture",
                "O(n)",
                "O(1)",
                "Count ones and compare the suffix pattern fixed by the third part.",
                "Equal values need the same significant suffix and the same trailing-zero budget.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(1)",
                code);
    }

    private static String threeEqualPartsOneIndexAnchorSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int[] threeEqualParts(int[] arr) {
                        List<Integer> onePositions = new ArrayList<>();
                        int group = 1;
                        int first = onePositions.get(0);
                        int second = onePositions.get(group);
                        int third = onePositions.get(2 * group);
                        int suffixLength = arr.length - third;
                        return new int[]{first + suffixLength - 1, second + suffixLength};
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "One-Index Anchors Fixture",
                "O(n)",
                "O(n)",
                "Store one-bit positions and anchor each part at the first one of its group.",
                "Leading zeros disappear, so the one-position list fixes the only possible significant starts.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String threeEqualPartsTrailingZeroBudgetSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int[] threeEqualParts(int[] arr) {
                        int n = arr.length;
                        List<Integer> ones = new ArrayList<>();
                        int group = 1;
                        int trailingZeros = n - 1 - ones.get(ones.size() - 1);
                        int endFirstOnes = ones.get(group - 1);
                        int startSecondOnes = ones.get(group);
                        int endSecondOnes = ones.get(2 * group - 1);
                        int startThirdOnes = ones.get(2 * group);
                        int zerosBetweenFirstAndSecond = startSecondOnes - endFirstOnes - 1;
                        if (zerosBetweenFirstAndSecond < trailingZeros) {
                            return new int[]{-1, -1};
                        }
                        int firstCut = endFirstOnes + trailingZeros;
                        int secondCut = endSecondOnes + trailingZeros + 1;
                        return new int[]{firstCut, secondCut + startThirdOnes - startThirdOnes};
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Trailing Zero Budget Fixture",
                "O(n)",
                "O(n)",
                "Compute how many zeros must trail each significant suffix before choosing cut points.",
                "Trailing zeros change the value, while extra zeros before the next part are only leading zeros.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String threeEqualPartsNormalizedStringSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] threeEqualParts(int[] arr) {
                        int suffixLength = 1;
                        int[] starts = new int[]{0, 1, 2};
                        String target = buildBits(arr, starts[2], suffixLength);
                        String first = buildBits(arr, starts[0], suffixLength);
                        if (!first.equals(target)) {
                            return new int[]{-1, -1};
                        }
                        return new int[]{0, 2};
                    }

                    private String buildBits(int[] arr, int start, int length) {
                        StringBuilder builder = new StringBuilder(length);
                        for (int offset = 0; offset < length; offset++) {
                            builder.append(arr[start + offset]);
                        }
                        return builder.toString();
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Normalized String Comparison Fixture",
                "O(n)",
                "O(n)",
                "Build normalized significant suffix strings and compare them directly.",
                "The string form makes the leading-zero rule explicit while preserving trailing zeros.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String threeEqualPartsRollingHashSolutionEntryJson() {
        String code = """
                class Solution {
                    public int[] threeEqualParts(int[] arr) {
                        int n = arr.length;
                        int start1 = 0;
                        int start2 = 1;
                        int start3 = 2;
                        int suffixLength = n - start3;
                        long[] prefix = new long[n + 1];
                        long[] power = new long[n + 1];
                        long hash1 = segmentHash(prefix, power, start1, suffixLength);
                        long hash2 = segmentHash(prefix, power, start2, suffixLength);
                        long hash3 = segmentHash(prefix, power, start3, suffixLength);
                        if (hash1 != hash3 || hash2 != hash3) {
                            return new int[]{-1, -1};
                        }
                        if (!sameBits(arr, start1, start3, suffixLength)) {
                            return new int[]{-1, -1};
                        }
                        return new int[]{0, 2};
                    }

                    private long segmentHash(long[] prefix, long[] power, int start, int length) {
                        return prefix[start + length] - prefix[start] * power[length];
                    }

                    private boolean sameBits(int[] arr, int left, int right, int length) {
                        return true;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Rolling Hash with Exact Verification Fixture",
                "O(n)",
                "O(n)",
                "Use rolling hash as a fast filter, then verify matched bits exactly.",
                "Hashes are useful for string matching, but this route still needs exact comparison for correctness.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

