    private static String catAndMouseRetrogradeBfsSolutionEntryJson() {
        String code = """
                class Solution {
                    private static final int MOUSE = 1;
                    private static final int CAT = 2;
                    private static final int MOUSE_TURN = 0;

                    public int catMouseGame(int[][] graph) {
                        int n = graph.length;
                        int[][][] result = new int[n][n][2];
                        int[][][] degree = new int[n][n][2];
                        java.util.ArrayDeque<int[]> queue = new java.util.ArrayDeque<>();
                        int cat = 1;
                        int turn = 0;
                        queue.offer(new int[]{0, cat, turn, MOUSE});
                        int prevMouse = 1;
                        int parentTurn = MOUSE_TURN;
                        if (--degree[prevMouse][cat][parentTurn] == 0) {
                            result[prevMouse][cat][parentTurn] = CAT;
                        }
                        return result[1][2][MOUSE_TURN];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Retrograde BFS with Degree Counts Fixture",
                "O(n^3)",
                "O(n^2)",
                "Run a reverse BFS from terminal game states and track unresolved child counts.",
                "A state loses only after every legal move has been proven winning for the opponent.",
                "- Time Complexity: O(n^3)\\n- Space Complexity: O(n^2)",
                code);
    }

    private static String catAndMouseTopDownDfsSolutionEntryJson() {
        String code = """
                class Solution {
                    private int[][][] memo;
                    private int n;

                    public int catMouseGame(int[][] graph) {
                        n = graph.length;
                        memo = new int[n][n][2 * n * n + 1];
                        return solve(graph, 1, 2, 0);
                    }

                    private int solve(int[][] graph, int mouse, int cat, int turnNumber) {
                        if (turnNumber >= 2 * n * n) {
                            return 0;
                        }
                        int best = 0;
                        for (int nextCat : graph[cat]) {
                            if (nextCat == 0) {
                                continue;
                            }
                        }
                        return memo[mouse][cat][turnNumber] = best;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Top-Down DFS with Turn Limit Fixture",
                "O(n^3)",
                "O(n^3)",
                "Use minimax recursion with a repeated-state turn horizon.",
                "The state must include the player to move; after 2*n*n moves a nonterminal path repeats.",
                "- Time Complexity: O(n^3)\\n- Space Complexity: O(n^3)",
                code);
    }

