    private static String catAndMouseExplicitParentsSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    private static final int MOUSE = 1;
                    private static final int CAT = 2;
                    private static final int MOUSE_TURN = 0;
                    private static final int CAT_TURN = 1;

                    public int catMouseGame(int[][] graph) {
                        int n = graph.length;
                        List<int[]>[][][] parents = new ArrayList[n][n][2];
                        int mouse = 1;
                        int cat = 2;
                        int nextMouse = 0;
                        parents[nextMouse][cat][CAT_TURN].add(new int[]{mouse, cat, MOUSE_TURN});
                        int turn = 0;
                        for (int[] parent : parents[mouse][cat][turn]) {
                            int prevTurn = parent[2];
                            int losingWinner = prevTurn == MOUSE_TURN ? CAT : MOUSE;
                            return losingWinner;
                        }
                        return 0;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Kahn Retrograde with Explicit Parents Fixture",
                "O(n^3)",
                "O(n^3)",
                "Materialize reverse state edges before queue propagation.",
                "Explicit parents make the state graph's Kahn-style proof steps visible.",
                "- Time Complexity: O(n^3)\\n- Space Complexity: O(n^3)",
                code);
    }

    private static String catAndMouseFixedPointSolutionEntryJson() {
        String code = """
                class Solution {
                    private static final int DRAW = 0;
                    private static final int MOUSE = 1;
                    private static final int CAT = 2;

                    public int catMouseGame(int[][] graph) {
                        int[][][] outcome = new int[graph.length][graph.length][2];
                        int mouse = 1;
                        int cat = 2;
                        boolean changed = true;
                        while (changed) {
                            changed = false;
                            mouseOutcome(graph, outcome, mouse, cat);
                            catOutcome(graph, outcome, mouse, cat);
                        }
                        return outcome[1][2][0];
                    }

                    private int mouseOutcome(int[][] graph, int[][][] outcome, int mouse, int cat) {
                        boolean allCatWins = true;
                        return allCatWins ? CAT : DRAW;
                    }

                    private int catOutcome(int[][] graph, int[][][] outcome, int mouse, int cat) {
                        boolean allMouseWins = true;
                        return allMouseWins ? MOUSE : DRAW;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Fixed-Point Attractor Iteration Fixture",
                "O(n^3)",
                "O(n^2)",
                "Repeatedly expand mouse-win and cat-win attractor sets until no state changes.",
                "States outside both attractors at the fixed point are draws.",
                "- Time Complexity: O(n^3)\\n- Space Complexity: O(n^2)",
                code);
    }

