    private static String malwareSpreadIIBfsSimulationSolutionEntryJson() {
        String code = """
                import java.util.*;

                class Solution {
                    public int minMalwareSpread(int[][] graph, int[] initial) {
                        int removed = initial[0];
                        int count = 0;
                        ArrayDeque<Integer> queue = new ArrayDeque<>();
                        for (int node : initial) {
                            if (node != removed) {
                                queue.offer(node);
                            }
                        }
                        boolean[] seen = new boolean[graph.length];
                        while (!queue.isEmpty()) {
                            int node = queue.poll();
                            for (int next = 0; next < graph.length; next++) {
                                if (next != removed && graph[node][next] == 1 && !seen[next]) {
                                    seen[next] = true;
                                    queue.offer(next);
                                }
                            }
                        }
                        return count;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "BFS Simulation per Removed Node Fixture",
                "O(m * n^2)",
                "O(n)",
                "Simulate each complete node deletion and spread from the remaining infected nodes.",
                "The removed node must be skipped as both a source and a neighbor.",
                "- Time Complexity: O(m * n^2)\\n- Space Complexity: O(n)",
                code);
    }

    private static String malwareSpreadIIDfsSimulationSolutionEntryJson() {
        String code = """
                class Solution {
                    private int[][] graph;
                    private boolean[] seen;
                    private int removed;

                    public int minMalwareSpread(int[][] graph, int[] initial) {
                        this.graph = graph;
                        this.removed = initial[0];
                        this.seen = new boolean[graph.length];
                        dfs(initial[0]);
                        return initial[0];
                    }

                    private void dfs(int node) {
                        if (node == removed || seen[node]) {
                            return;
                        }
                        seen[node] = true;
                        for (int next = 0; next < graph.length; next++) {
                            dfs(next);
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "DFS Simulation per Removed Node Fixture",
                "O(m * n^2)",
                "O(n)",
                "Use recursive reachability after each candidate node deletion.",
                "DFS makes the removed-node guard explicit at traversal entry.",
                "- Time Complexity: O(m * n^2)\\n- Space Complexity: O(n)",
                code);
    }

