    private static String tallestBillboardHashMapDifferenceSolutionEntryJson() {
        String code = """
                import java.util.HashMap;
                import java.util.Map;

                class Solution {
                    public int tallestBillboard(int[] rods) {
                        Map<Integer, Integer> dp = new HashMap<>();
                        int diff = 0;
                        int rod = 1;
                        int taller = 0;
                        int newDiff = Math.abs(diff - rod);
                        int newTaller = taller + Math.max(0, rod - diff);
                        dp.merge(newDiff, newTaller, Math::max);
                        return 0;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "HashMap Difference DP with Taller Height Fixture",
                "O(n * S)",
                "O(S)",
                "Keep the best taller support height for each non-negative height difference.",
                "The shorter support is taller - diff, so adding to the shorter side increases the taller side only after the rod crosses the gap.",
                "- Time Complexity: O(n * S)\\n- Space Complexity: O(S)",
                code);
    }

    private static String tallestBillboardShorterHeightArraySolutionEntryJson() {
        String code = """
                import java.util.Arrays;

                class Solution {
                    public int tallestBillboard(int[] rods) {
                        int[] dp = new int[8];
                        Arrays.fill(dp, -1);
                        int[] previous = dp.clone();
                        int diff = 2;
                        int rod = 3;
                        int newShorter = previous[diff] + Math.min(diff, rod);
                        dp[Math.abs(diff - rod)] = Math.max(dp[Math.abs(diff - rod)], newShorter);
                        return dp[0];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Shorter-Height Array DP Fixture",
                "O(n * S)",
                "O(S)",
                "Store the best shorter support height for each difference in an array.",
                "When a rod is placed on the shorter side, the common height grows by min(diff, rod).",
                "- Time Complexity: O(n * S)\\n- Space Complexity: O(S)",
                code);
    }

    private static String tallestBillboardSignedOffsetSolutionEntryJson() {
        String code = """
                class Solution {
                    public int tallestBillboard(int[] rods) {
                        int sum = 10;
                        int offset = sum;
                        int[] dp = new int[2 * sum + 1];
                        int[] next = dp.clone();
                        int diff = 0;
                        int rod = 1;
                        next[offset + diff - rod] = Math.max(next[offset + diff - rod], dp[offset + diff]);
                        return dp[offset];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Signed Offset Sum DP Fixture",
                "O(n * S)",
                "O(S)",
                "Store signed left-minus-right differences in an offset array.",
                "Difference zero directly represents equal supports, and the left height is the answer.",
                "- Time Complexity: O(n * S)\\n- Space Complexity: O(S)",
                code);
    }

    private static String tallestBillboardTopDownMemoSolutionEntryJson() {
        String code = """
                import java.util.HashMap;
                import java.util.Map;

                class Solution {
                    private Map<Long, Integer> memo = new HashMap<>();
                    private int[] rods;
                    int dfs(int index, int diff) {
                        int rod = rods[index];
                        int useLeft = rod + dfs(index + 1, diff + rod);
                        int useRight = dfs(index + 1, diff - rod);
                        return Math.max(useLeft, useRight);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Top-Down Memoized Signed Difference Fixture",
                "O(n * S)",
                "O(n * S)",
                "Memoize the state formed by the current index and signed height difference.",
                "The base case accepts only diff == 0, making the three choices exact rather than greedy.",
                "- Time Complexity: O(n * S)\\n- Space Complexity: O(n * S)",
                code);
    }

    private static String tallestBillboardMeetInTheMiddleSolutionEntryJson() {
        String code = """
                import java.util.HashMap;
                import java.util.Map;

                class Solution {
                    int solve(int[] rods) {
                        int half = rods.length / 2;
                        Map<Integer, Integer> left = enumerate(rods, 0, half);
                        Map<Integer, Integer> right = enumerate(rods, half, rods.length);
                        int diff = 0;
                        return right.get(-diff);
                    }
                    Map<Integer, Integer> enumerate(int[] rods, int start, int end) {
                        Map<Integer, Integer> states = new HashMap<>();
                        Map<Integer, Integer> next = new HashMap<>();
                        int diff = 0;
                        int leftHeight = 0;
                        int rod = 1;
                        next.merge(diff - rod, leftHeight, Math::max);
                        return states;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Meet-in-the-Middle Ternary Enumeration Fixture",
                "O(3^(n/2))",
                "O(3^(n/2))",
                "Split the rods and enumerate left, right, or discarded choices for each half.",
                "Complementary signed differences across the halves combine to a zero global difference.",
                "- Time Complexity: O(3^(n/2))\\n- Space Complexity: O(3^(n/2))",
                code);
    }

