    private static String bitwiseAndTriplesDensePairScanSolutionEntryJson() {
        String code = """
                class Solution {
                    private static final int LIMIT = 1 << 16;
                    public int countTriplets(int[] nums) {
                        int[] pairCount = new int[LIMIT];
                        int a = 1;
                        int b = 2;
                        int c = 3;
                        int mask = 0;
                        pairCount[a & b]++;
                        if ((mask & c) == 0) { return pairCount[mask]; }
                        return 0;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Dense Pairwise AND Frequency Scan Fixture",
                "O(n^2 + n * 2^16)",
                "O(2^16)",
                "Count every ordered pair AND mask, then scan all masks for each third value.",
                "Once pair masks are counted, a third value only needs masks with no shared set bit.",
                "- Time Complexity: O(n^2 + n * 2^16)\\n- Space Complexity: O(2^16)",
                code);
    }

    private static String bitwiseAndTriplesFrequencyCompressionSolutionEntryJson() {
        String code = """
                import java.util.HashMap;
                import java.util.Map;

                class Solution {
                    void build() {
                        Map<Integer, Integer> valueFrequency = new HashMap<>();
                        Map<Integer, Integer> pairCount = new HashMap<>();
                        for (Map.Entry<Integer, Integer> first : valueFrequency.entrySet()) {
                            for (Map.Entry<Integer, Integer> second : valueFrequency.entrySet()) {
                                int mask = first.getKey() & second.getKey();
                                int orderedPairs = first.getValue() * second.getValue();
                                pairCount.merge(mask, orderedPairs, Integer::sum);
                            }
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Frequency-Compressed Pair Masks Fixture",
                "O(u^2 + n * m)",
                "O(u + m)",
                "Compress duplicate values before constructing ordered pair-mask counts.",
                "The product of frequencies preserves the number of ordered index pairs.",
                "- Time Complexity: O(u^2 + n * m)\\n- Space Complexity: O(u + m)",
                code);
    }

    private static String bitwiseAndTriplesSubmaskEnumerationSolutionEntryJson() {
        String code = """
                class Solution {
                    void query(int[] pairCount, int c) {
                        int complement = 65535 ^ c;
                        int answer = 0;
                        for (int sub = complement;; sub = (sub - 1) & complement) {
                            answer += pairCount[sub];
                            if (sub == 0) { break; }
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Complement Submask Enumeration Fixture",
                "O(n^2 + sum 2^zeroBits)",
                "O(2^16)",
                "Enumerate only the submasks of the third value's 16-bit complement.",
                "A pair mask is valid exactly when all its set bits lie where the third value has zero bits.",
                "- Time Complexity: O(n^2 + sum 2^zeroBits)\\n- Space Complexity: O(2^16)",
                code);
    }

    private static String bitwiseAndTriplesZetaTransformSolutionEntryJson() {
        String code = """
                class Solution {
                    private static final int BITS = 16;
                    void transform(int[] subsetSum) {
                        for (int bit = 0; bit < BITS; bit++) {
                            for (int mask = 0; mask < subsetSum.length; mask++) {
                                if ((mask & (1 << bit)) != 0) {
                                    subsetSum[mask] += subsetSum[mask ^ (1 << bit)];
                                }
                            }
                        }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Subset Zeta Transform Query Table Fixture",
                "O(n^2 + 16 * 2^16 + n)",
                "O(2^16)",
                "Precompute every complement-submask sum with a subset zeta transform.",
                "After the transform, each third value is answered by one lookup on its 16-bit complement.",
                "- Time Complexity: O(n^2 + 16 * 2^16 + n)\\n- Space Complexity: O(2^16)",
                code);
    }

    private static String bitwiseAndTriplesTrieQuerySolutionEntryJson() {
        String code = """
                class Solution {
                    private int query(Node node, int value, int bit) {
                        if (node == null) { return 0; }
                        if (bit < 0) { return node.count; }
                        if ((value & (1 << bit)) != 0) {
                            return query(node.zero, value, bit - 1);
                        }
                        return query(node.zero, value, bit - 1) + query(node.one, value, bit - 1);
                    }
                    private static final class Node {
                        Node zero;
                        Node one;
                        int count;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Bitwise Trie over Pair Masks Fixture",
                "O(n^2 * 16 + n * 16)",
                "O(n^2 * 16)",
                "Insert pair masks into a binary trie and query compatible masks bit by bit.",
                "When the third value has a one bit, the pair mask must take the zero branch at that bit.",
                "- Time Complexity: O(n^2 * 16 + n * 16)\\n- Space Complexity: O(n^2 * 16)",
                code);
    }

