    private static String minimumCostMergeStonesOptimizedTwoDimensionalDpSolutionEntryJson() {
        String code = """
                class Solution {
                    public int mergeStones(int[] stones, int k) {
                        int n = stones.length;
                        int[][] dp = new int[n][n];
                        for (int length = 2; length <= n; length++) {
                            for (int left = 0; left + length <= n; left++) {
                                int right = left + length - 1;
                                for (int split = left; split < right; split += k - 1) {
                                    dp[left][right] = Math.min(dp[left][right], dp[left][split] + dp[split + 1][right]);
                                }
                                if ((length - 1) % (k - 1) == 0) { dp[left][right] += 1; }
                            }
                        }
                        return dp[0][n - 1];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Optimized Two-Dimensional Interval DP Fixture",
                "O(n^3 / k)",
                "O(n^2)",
                "Use one interval value and split only at positions separated by k - 1.",
                "The interval length modulo k - 1 determines whether a final merge can happen.",
                "- Time Complexity: O(n^3 / k)\\n- Space Complexity: O(n^2)",
                code);
    }

    private static String minimumCostMergeStonesExplicitThreeDimensionalDpSolutionEntryJson() {
        String code = """
                class Solution {
                    public int mergeStones(int[] stones, int k) {
                        int n = stones.length;
                        int[][][] dp = new int[n][n][k + 1];
                        for (int length = 2; length <= n; length++) {
                            for (int left = 0; left + length <= n; left++) {
                                int right = left + length - 1;
                                for (int piles = 2; piles <= k; piles++) {
                                    dp[left][right][piles] = 1;
                                }
                                dp[left][right][1] = dp[left][right][k] + 1;
                            }
                        }
                        return dp[0][n - 1][1];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Explicit Three-Dimensional Pile DP Fixture",
                "O(n^3 * k)",
                "O(n^2 * k)",
                "Track the cheapest cost for each interval and exact target pile count.",
                "Only an interval that has exactly k piles may pay its sum and collapse into one pile.",
                "- Time Complexity: O(n^3 * k)\\n- Space Complexity: O(n^2 * k)",
                code);
    }

    private static String minimumCostMergeStonesTopDownExactPileMemoSolutionEntryJson() {
        String code = """
                class Solution {
                    private int k;
                    private int[][][] memo;
                    private int cost(int left, int right, int piles) {
                        int length = right - left + 1;
                        if (length < piles || (length - piles) % (k - 1) != 0) { return 1_000_000; }
                        return memo[left][right][piles];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Top-Down Exact Pile Count Memoization Fixture",
                "O(n^3 * k)",
                "O(n^2 * k)",
                "Memoize the recursive interval state including its exact target pile count.",
                "The subproblem feasibility residue removes impossible target pile counts before splitting.",
                "- Time Complexity: O(n^3 * k)\\n- Space Complexity: O(n^2 * k)",
                code);
    }

    private static String minimumCostMergeStonesImplicitMemoSolutionEntryJson() {
        String code = """
                class Solution {
                    private int k;
                    private int[][] memo;
                    private int solve(int left, int right) {
                        int best = 0;
                        for (int split = left; split < right; split += k - 1) {
                            best += solve(left, split) + solve(split + 1, right);
                        }
                        return memo[left][right] = best;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Memoized Implicit Pile Interval DP Fixture",
                "O(n^3 / k)",
                "O(n^2)",
                "Use a recursive interval solver that stores only the legally minimized pile count.",
                "The remaining pile count is implicit in the interval length modulo k - 1.",
                "- Time Complexity: O(n^3 / k)\\n- Space Complexity: O(n^2)",
                code);
    }

    private static String minimumCostMergeStonesSparseMapDpSolutionEntryJson() {
        String code = """
                import java.util.HashMap;
                import java.util.Map;
                class Solution {
                    public int mergeStones(int[] stones, int k) {
                        int n = stones.length;
                        int[] prefix = new int[n + 1];
                        Map<Integer, Integer>[][] dp = new HashMap[n][n];
                        Map<Integer, Integer> current = new HashMap<>();
                        int piles = 2;
                        int cost = 3;
                        int right = n - 1;
                        int left = 0;
                        Integer kPileCost = 4;
                        current.merge(piles, cost, Math::min);
                        current.merge(1, kPileCost + prefix[right + 1] - prefix[left], Math::min);
                        dp[left][right] = current;
                        return current.get(1);
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Sparse Reachable-Pile Map DP Fixture",
                "O(n^3 * k^2)",
                "O(n^2 * k)",
                "Store a sparse map of reachable pile counts for each interval.",
                "A map makes the temporary pile-count states visible instead of hiding them in residues.",
                "- Time Complexity: O(n^3 * k^2)\\n- Space Complexity: O(n^2 * k)",
                code);
    }

