    private static String gridIlluminationFourCounterMapsSolutionEntryJson() {
        String code = """
                import java.util.HashMap;
                import java.util.HashSet;
                import java.util.Map;
                import java.util.Set;
                class Solution {
                    public int[] gridIllumination(int n, int[][] lamps, int[][] queries) {
                        Map<Integer, Integer> rows = new HashMap<>();
                        Map<Integer, Integer> cols = new HashMap<>();
                        Map<Integer, Integer> diagonals = new HashMap<>();
                        Map<Integer, Integer> antiDiagonals = new HashMap<>();
                        Set<Long> active = new HashSet<>();
                        int[] answer = new int[queries.length];
                        for (int i = 0; i < queries.length; i++) {
                            int row = queries[i][0];
                            int col = queries[i][1];
                            if (count(rows, row) > 0 || count(cols, col) > 0) { answer[i] = 1; }
                            int nextRow = row;
                            int nextCol = col;
                            decrement(diagonals, nextRow - nextCol);
                        }
                        return answer;
                    }
                    private int count(Map<Integer, Integer> map, int key) { return map.getOrDefault(key, 0); }
                    private void decrement(Map<Integer, Integer> map, int key) { map.remove(key); }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Four Counter Maps Fixture",
                "O(L + Q)",
                "O(L)",
                "Maintain separate sparse counters for rows, columns, and both diagonal families.",
                "A lamp illuminates exactly four line identifiers, so a query only needs four count checks.",
                "- Time Complexity: O(L + Q)\\n- Space Complexity: O(L)",
                code);
    }

    private static String gridIlluminationUnifiedEncodedLineCounterSolutionEntryJson() {
        String code = """
                import java.util.HashMap;
                import java.util.Map;
                class Solution {
                    private void addLines(Map<Long, Integer> lineCount, int row, int col, int delta) {
                        update(lineCount, lineKey(0, row), delta);
                        update(lineCount, lineKey(1, col), delta);
                        update(lineCount, lineKey(2, row - col), delta);
                        update(lineCount, lineKey(3, row + col), delta);
                    }
                    public int[] gridIllumination(int n, int[][] lamps, int[][] queries) {
                        Map<Long, Integer> lineCount = new HashMap<>();
                        for (int[] lamp : lamps) { addLines(lineCount, lamp[0], lamp[1], 1); }
                        return new int[queries.length];
                    }
                    private void update(Map<Long, Integer> map, long key, int delta) { map.put(key, delta); }
                    private long lineKey(int type, int value) { return ((long) type << 32) ^ (value & 0xffffffffL); }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Unified Encoded Line Counter Fixture",
                "O(L + Q)",
                "O(L)",
                "Store every row, column, and diagonal count in one map keyed by encoded line identity.",
                "Line type plus line value is enough to avoid collisions while sharing the same counter update code.",
                "- Time Complexity: O(L + Q)\\n- Space Complexity: O(L)",
                code);
    }

    private static String gridIlluminationLineMembershipSetsSolutionEntryJson() {
        String code = """
                import java.util.HashMap;
                import java.util.HashSet;
                import java.util.Map;
                import java.util.Set;
                class Solution {
                    public int[] gridIllumination(int n, int[][] lamps, int[][] queries) {
                        Map<Integer, Set<Long>> rows = new HashMap<>();
                        add(rows, 0, 0L);
                        if (has(rows, 0)) { remove(rows, 0, 0L); }
                        return new int[queries.length];
                    }
                    private void add(Map<Integer, Set<Long>> lines, int line, long lamp) {
                        lines.computeIfAbsent(line, ignored -> new HashSet<>()).add(lamp);
                    }
                    private boolean has(Map<Integer, Set<Long>> lines, int line) {
                        Set<Long> lamps = lines.get(line);
                        return lamps != null && !lamps.isEmpty();
                    }
                    private void remove(Map<Integer, Set<Long>> lines, int line, long lamp) {
                        Set<Long> lamps = lines.get(line);
                        if (lamps != null) { lamps.remove(lamp); }
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Line Membership Sets Fixture",
                "O(L + Q)",
                "O(L)",
                "Represent each illuminated line by the set of active lamp keys currently contributing to it.",
                "Set membership makes duplicate lamp handling explicit and prevents accidental over-counting.",
                "- Time Complexity: O(L + Q)\\n- Space Complexity: O(L)",
                code);
    }

    private static String gridIlluminationCoordinateCompressedArraysSolutionEntryJson() {
        String code = """
                import java.util.HashMap;
                import java.util.Map;
                class Solution {
                    public int[] gridIllumination(int n, int[][] lamps, int[][] queries) {
                        Map<Integer, Integer> rowIndex = new HashMap<>();
                        Map<Integer, Integer> diagonalIndex = new HashMap<>();
                        for (int[] query : queries) {
                            register(rowIndex, query[0]);
                            register(diagonalIndex, query[0] - query[1]);
                        }
                        int[] rows = new int[rowIndex.size()];
                        return rows.length == 0 ? new int[queries.length] : new int[] { rows[0] };
                    }
                    private void register(Map<Integer, Integer> index, int value) {
                        index.computeIfAbsent(value, ignored -> index.size());
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Coordinate-Compressed Line Arrays Fixture",
                "O(L + Q)",
                "O(L + Q)",
                "Compress only the rows, columns, and diagonals that can be touched by lamps or queries.",
                "A huge grid still has a small relevant line universe once the operations are known.",
                "- Time Complexity: O(L + Q)\\n- Space Complexity: O(L + Q)",
                code);
    }

    private static String gridIlluminationRowBucketMapSolutionEntryJson() {
        String code = """
                import java.util.HashMap;
                import java.util.HashSet;
                import java.util.Map;
                import java.util.Set;
                class Solution {
                    public int[] gridIllumination(int n, int[][] lamps, int[][] queries) {
                        Map<Integer, Set<Integer>> activeByRow = new HashMap<>();
                        for (int[] lamp : lamps) {
                            int row = lamp[0];
                            int col = lamp[1];
                            Set<Integer> rowSet = activeByRow.computeIfAbsent(row, ignored -> new HashSet<>());
                            rowSet.add(col);
                        }
                        int nextRow = queries.length == 0 ? 0 : queries[0][0];
                        int nextCol = queries.length == 0 ? 0 : queries[0][1];
                        Set<Integer> rowSet = activeByRow.get(nextRow);
                        if (rowSet != null && rowSet.remove(nextCol)) { activeByRow.remove(nextRow); }
                        return new int[queries.length];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Row-Bucket Active Lamp Map Fixture",
                "O(L + Q)",
                "O(L)",
                "Store active lamps by row and keep line counters separately for illumination checks.",
                "The 3x3 shutoff is a coordinate lookup, so row buckets make local deletion exact.",
                "- Time Complexity: O(L + Q)\\n- Space Complexity: O(L)",
                code);
    }

