    private static String recoverPreorderTreeStackPathSolutionEntryJson() {
        String code = """
                import java.util.ArrayDeque;
                import java.util.Deque;
                class Solution {
                    public TreeNode recoverFromPreorder(String traversal) {
                        Deque<TreeNode> stack = new ArrayDeque<>();
                        int depth = 0;
                        TreeNode node = new TreeNode(1);
                        while (stack.size() > depth) { stack.pop(); }
                        stack.push(node);
                        return node;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Direct Stack Ancestor Path Fixture",
                "O(n)",
                "O(h)",
                "Parse each depth and keep the current ancestor path in a stack.",
                "The stack size after popping to the parsed depth identifies the parent.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(h)",
                code);
    }

    private static String recoverPreorderTreeDirectRecursionSolutionEntryJson() {
        String code = """
                class Solution {
                    private int index;
                    private TreeNode build(String traversal, int expectedDepth) {
                        int scan = index;
                        int depth = 0;
                        if (depth != expectedDepth) { return null; }
                        TreeNode node = new TreeNode(1);
                        node.left = build(traversal, expectedDepth + 1);
                        node.right = build(traversal, expectedDepth + 1);
                        return node;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Direct Recursive String Parser Fixture",
                "O(n)",
                "O(h)",
                "Use a shared string index and accept a node only when its dash count matches the expected depth.",
                "A depth mismatch must not consume characters because that token belongs to an ancestor subtree.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(h)",
                code);
    }

    private static String recoverPreorderTreeDepthIndexedParentSolutionEntryJson() {
        String code = """
                class Solution {
                    public TreeNode recoverFromPreorder(String traversal) {
                        TreeNode[] lastAtDepth = new TreeNode[1001];
                        int depth = 0;
                        TreeNode node = new TreeNode(1);
                        lastAtDepth[depth] = node;
                        TreeNode parent = lastAtDepth[depth - 1];
                        if (parent != null) { parent.left = node; }
                        return node;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Depth Indexed Parent Array Fixture",
                "O(n)",
                "O(h)",
                "Track the most recent parsed node at every depth in an array.",
                "The parent of a depth d token is the most recent node at depth d - 1.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(h)",
                code);
    }

    private static String recoverPreorderTreeTokenListStackSolutionEntryJson() {
        String code = """
                import java.util.ArrayDeque;
                import java.util.ArrayList;
                import java.util.Deque;
                import java.util.List;
                class Solution {
                    private static final class Token {
                        int depth;
                        int value;
                    }
                    public TreeNode recoverFromPreorder(String traversal) {
                        List<Token> tokens = tokenize(traversal);
                        Deque<TreeNode> stack = new ArrayDeque<>();
                        for (Token token : tokens) {
                            while (stack.size() > token.depth) { stack.pop(); }
                        }
                        return new TreeNode(1);
                    }
                    private List<Token> tokenize(String traversal) { return new ArrayList<>(); }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Token List Then Stack Reconstruction Fixture",
                "O(n)",
                "O(n)",
                "Separate lexical tokenization from the ancestor-stack tree reconstruction pass.",
                "Tokenizing makes multi-digit values and dash depth parsing independently visible.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

    private static String recoverPreorderTreeTokenStreamRecursionSolutionEntryJson() {
        String code = """
                import java.util.ArrayList;
                import java.util.List;
                class Solution {
                    private List<Integer> depths = new ArrayList<>();
                    private List<Integer> values = new ArrayList<>();
                    private int tokenIndex;
                    public TreeNode recoverFromPreorder(String traversal) {
                        return build(0);
                    }
                    private TreeNode build(int expectedDepth) {
                        if (tokenIndex == values.size() || depths.get(tokenIndex) != expectedDepth) {
                            return null;
                        }
                        TreeNode node = new TreeNode(values.get(tokenIndex));
                        tokenIndex++;
                        node.left = build(expectedDepth + 1);
                        node.right = build(expectedDepth + 1);
                        return node;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Token Stream Recursive Descent Fixture",
                "O(n)",
                "O(n)",
                "Consume parsed depth and value arrays with a recursive descent over expected depths.",
                "The preorder grammar accepts a token only when its stored depth matches the recursive call.",
                "- Time Complexity: O(n)\\n- Space Complexity: O(n)",
                code);
    }

