    private static String streamOfCharactersLengthBucketSolutionEntryJson() {
        String code = """
                import java.util.HashMap;
                import java.util.HashSet;
                import java.util.Map;
                import java.util.Set;
                class StreamChecker {
                    private final Map<Integer, Set<String>> wordsByLength = new HashMap<>();
                    private String stream = "";
                    public boolean query(char letter) {
                        stream += letter;
                        for (Map.Entry<Integer, Set<String>> entry : wordsByLength.entrySet()) {
                            int length = entry.getKey();
                            if (stream.length() >= length) {
                                String suffix = stream.substring(stream.length() - length);
                                if (entry.getValue().contains(suffix)) { return true; }
                            }
                        }
                        return false;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Length-Bucket Exact Suffix Fixture",
                "O(U * L)",
                "O(WL)",
                "Group words by length and compare only exact suffixes of those lengths.",
                "This route is intentionally direct, making the suffix contract explicit before introducing automata.",
                "- Time Complexity: O(U * L) per query\\n- Space Complexity: O(WL)",
                code);
    }

