    private static String smallestSufficientTeamSixteenPairInput() {
        StringBuilder input = new StringBuilder("req_skills = ");
        appendSkillRange(input, 0, 16);
        input.append(", people = [");
        for (int i = 0; i < 16; i += 2) {
            if (i > 0) {
                input.append(',');
            }
            input.append("[\"s").append(i).append("\",\"s").append(i + 1).append("\"]");
        }
        return input.append(']').toString();
    }

