    private static void appendSkillRange(StringBuilder builder, int startInclusive, int endExclusive) {
        builder.append('[');
        for (int i = startInclusive; i < endExclusive; i++) {
            if (i > startInclusive) {
                builder.append(',');
            }
            builder.append("\"s").append(i).append('"');
        }
        builder.append(']');
    }

