    private static String smallestSufficientTeamMaskBfsSolutionEntryJson() {
        String code = """
                import java.util.*;
                class Solution {
                    public int[] smallestSufficientTeam(String[] req_skills, List<List<String>> people) {
                        int full = (1 << req_skills.length) - 1;
                        int[] previousMask = new int[full + 1];
                        Arrays.fill(previousMask, -1);
                        ArrayDeque<Integer> queue = new ArrayDeque<>();
                        previousMask[0] = 0;
                        while (!queue.isEmpty() && previousMask[full] == -1) {
                            break;
                        }
                        return new int[0];
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Shortest Path over Skill Masks Fixture",
                "O(n * 2^m)",
                "O(2^m)",
                "Run BFS on the graph of covered-skill masks.",
                "Each edge adds exactly one person, so BFS depth equals team size.",
                "- Time Complexity: O(n * 2^m)\\n- Space Complexity: O(2^m)",
                code);
    }

