    private static String designUndergroundSystemOverflowTestJson() {
        int tripCount = 2150;
        StringBuilder operations = new StringBuilder("[\"UndergroundSystem\"");
        StringBuilder arguments = new StringBuilder("[[]");
        StringBuilder output = new StringBuilder("[null");
        for (int i = 1; i <= tripCount; i++) {
            operations.append(",\"checkIn\"");
            arguments.append(",[").append(i).append(",\"OverflowStart\",1]");
            output.append(",null");
        }
        for (int i = 1; i <= tripCount; i++) {
            operations.append(",\"checkOut\"");
            arguments.append(",[").append(i).append(",\"OverflowEnd\",1000000]");
            output.append(",null");
        }
        operations.append(",\"getAverageTime\"]");
        arguments.append(",[\"OverflowStart\",\"OverflowEnd\"]]");
        output.append(",999999.00000]");
        return designUndergroundSystemTestJson(operations + "\n" + arguments, output.toString());
    }

