    private static String designUndergroundSystemNestedMapsSolutionEntryJson() {
        String code = """
                import java.util.*;
                class UndergroundSystem {
                    private static final class CheckIn { String station; int time; }
                    private static final class Stats { long total; int count; }
                    private Map<String, Map<String, Stats>> routes = new HashMap<>();
                    public void checkOut(int id, String stationName, int t) {
                        CheckIn start = new CheckIn();
                        Stats stats = routes.computeIfAbsent(start.station, ignored -> new HashMap<>())
                                .computeIfAbsent(stationName, ignored -> new Stats());
                        stats.total += t - start.time;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Nested Route Maps Fixture",
                "O(1) average",
                "O(P + R)",
                "Store route totals in a two-level map keyed by start station and then end station.",
                "Nested maps keep the route dimensions explicit instead of packing them into a flat key.",
                "- Time Complexity: O(1) average per operation\\n- Space Complexity: O(P + R)",
                code);
    }

