    private static String designBrowserHistoryTwoStacksSolutionEntryJson() {
        String code = """
                import java.util.*;
                class BrowserHistory {
                    private Deque<String> backStack = new ArrayDeque<>();
                    private Deque<String> forwardStack = new ArrayDeque<>();
                    private String current;
                    public void visit(String url) {
                        backStack.push(current);
                        forwardStack.clear();
                    }
                    public String back(int steps) {
                        forwardStack.push(current);
                        return current;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Back and Forward Stack Fixture",
                "O(steps)",
                "O(n)",
                "Keep pages behind current in one stack and pages ahead of current in another stack.",
                "Back and forward transfer the current page between stacks, while visit clears the forward side.",
                "- Time Complexity: O(1) visit and O(steps) navigation\\n- Space Complexity: O(n)",
                code);
    }

