    private static String designCircularDequeMonotonicIndexSolutionEntryJson() {
        String code = """
                class MyCircularDeque {
                    private int[] data;
                    private int capacity;
                    private int head;
                    private int tail;
                    public boolean insertFront(int value) {
                        head--;
                        data[Math.floorMod(head, capacity)] = value;
                        return true;
                    }
                    public boolean isFull() {
                        return tail - head == capacity;
                    }
                }
                """;
        return validParenthesisStringSolutionEntryJson(
                "Monotonic Index Ring Deque Fixture",
                "O(1)",
                "O(k)",
                "Use monotonic head and tail indices, mapping logical positions into the backing ring with floorMod.",
                "The active deque interval is half-open, so the logical size is tail minus head.",
                "- Time Complexity: O(1) per operation\\n- Space Complexity: O(k)",
                code);
    }

