    private static byte[] pngBytes() {
        BufferedImage image = new BufferedImage(256, 144, BufferedImage.TYPE_INT_ARGB);
        for (int y = 0; y < image.getHeight(); y++) {
            for (int x = 0; x < image.getWidth(); x++) {
                int red = (x * 5 + y * 3) & 0xFF;
                int green = (x * 7 + y * 11) & 0xFF;
                int blue = (x * 13 + y * 17) & 0xFF;
                image.setRGB(x, y, 0xFF000000 | (red << 16) | (green << 8) | blue);
            }
        }
        return pngBytes(image);
    }

    private static byte[] solidPngBytes(int width, int height, int argb) {
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        for (int y = 0; y < image.getHeight(); y++) {
            for (int x = 0; x < image.getWidth(); x++) {
                image.setRGB(x, y, argb);
            }
        }
        return pngBytes(image);
    }

    private static byte[] pngBytes(BufferedImage image) {
        try {
            ByteArrayOutputStream output = new ByteArrayOutputStream();
            ImageIO.write(image, "png", output);
            return output.toByteArray();
        } catch (IOException e) {
            throw new AssertionError("Failed to create test PNG", e);
        }
    }

