        void seedCompleteProblemBankCache(Path cacheDir) throws IOException {
            copyTemplateDirectory(completeProblemBankTemplate(), cacheDir);
        }

        private static Path completeProblemBankTemplate() throws IOException {
            synchronized (COMPLETE_BANK_TEMPLATE_LOCK) {
                if (completeProblemBankTemplate != null
                        && Files.isRegularFile(completeProblemBankTemplate.resolve("manifest.json"))) {
                    return completeProblemBankTemplate;
                }

                Path template = Files.createTempDirectory("algocraft-complete-bank-template-");
                FakeRemote remote = new FakeRemote("https://example.test/question_bank/official");
                remote.publishCompleteProblemBank();
                remote.writeResponsesTo(template);
                completeProblemBankTemplate = template;
                return template;
            }
        }

        private void writeResponsesTo(Path targetRoot) throws IOException {
            Files.createDirectories(targetRoot);
            String prefix = baseUrl + "/";
            for (Map.Entry<URI, byte[]> entry : responses.entrySet()) {
                String uri = entry.getKey().toString();
                if (!uri.startsWith(prefix)) {
                    continue;
                }
                Path target = targetRoot.resolve(uri.substring(prefix.length()).replace('/', java.io.File.separatorChar))
                        .normalize();
                if (!target.startsWith(targetRoot.normalize())) {
                    throw new IOException("Refusing to seed file outside template root: " + uri);
                }
                Files.createDirectories(target.getParent());
                Files.write(target, entry.getValue());
            }
        }

        private static void copyTemplateDirectory(Path sourceRoot, Path targetRoot) throws IOException {
            if (Files.exists(targetRoot)) {
                deleteRecursively(targetRoot);
            }
            Files.createDirectories(targetRoot);
            try (var stream = Files.walk(sourceRoot)) {
                for (Path source : stream.sorted(Comparator.naturalOrder()).toList()) {
                    Path relative = sourceRoot.relativize(source);
                    Path target = targetRoot.resolve(relative).normalize();
                    if (!target.startsWith(targetRoot.normalize())) {
                        throw new IOException("Refusing to seed file outside cache root: " + relative);
                    }
                    if (Files.isDirectory(source)) {
                        Files.createDirectories(target);
                    } else {
                        Files.createDirectories(target.getParent());
                        try {
                            Files.createLink(target, source);
                        } catch (IOException | UnsupportedOperationException e) {
                            Files.copy(source, target, java.nio.file.StandardCopyOption.REPLACE_EXISTING);
                        }
                    }
                }
            }
        }

        private void putProblem(int problemNumber, String json) {
            byte[] problemBytes = json.getBytes(StandardCharsets.UTF_8);
            String fileName = "p" + problemNumber + ".json";
            responses.put(URI.create(baseUrl + "/" + fileName), problemBytes);
            ensureDefaultChineseTranslation(problemNumber);
        }

        private static String officialProblemFileJson(int problemNumber) {
            try {
                return Files.readString(
                        Path.of("question_bank", "official", "p" + problemNumber + ".json"),
                        StandardCharsets.UTF_8);
            } catch (IOException e) {
                throw new IllegalStateException("Unable to read official fixture p" + problemNumber + ".json", e);
            }
        }

        void removeProblem(int problemNumber) {
            String fileName = "p" + problemNumber + ".json";
            responses.remove(URI.create(baseUrl + "/" + fileName));
            hashOverrides.remove(fileName);
            String translationSuffix = "/p" + problemNumber + ".json";
            List<String> translationNames = responses.keySet().stream()
                    .map(URI::toString)
                    .filter(uri -> uri.startsWith(baseUrl + "/lang/") && uri.endsWith(translationSuffix))
                    .map(uri -> uri.substring((baseUrl + "/").length()))
                    .toList();
            for (String translationName : translationNames) {
                responses.remove(URI.create(baseUrl + "/" + translationName));
                hashOverrides.remove(translationName);
            }
            publishManifest();
        }

        void publishUnsafeManifestFile(String fileName, String json) {
            responses.put(URI.create(baseUrl + "/" + fileName), json.getBytes(StandardCharsets.UTF_8));
            publishManifest();
        }

        void publishCatalog(String json) {
            responses.put(URI.create(baseUrl + "/catalog.json"), json.getBytes(StandardCharsets.UTF_8));
            publishManifest();
        }

        void removeCatalog() {
            responses.remove(URI.create(baseUrl + "/catalog.json"));
            hashOverrides.remove("catalog.json");
            publishManifest();
        }

        void publishImage(String fileName, byte[] bytes) {
            responses.put(URI.create(baseUrl + "/images/" + fileName), bytes);
            publishManifest();
        }

        void publishOfficialImage(String fileName) {
            try {
                publishImage(fileName, Files.readAllBytes(
                        Path.of("question_bank", "official", "images", fileName)));
            } catch (IOException e) {
                throw new IllegalStateException("Unable to read official fixture image " + fileName, e);
            }
        }

        void removeImage(String fileName) {
            String manifestName = "images/" + fileName;
            responses.remove(URI.create(baseUrl + "/" + manifestName));
            hashOverrides.remove(manifestName);
            publishManifest();
        }

        void publishTranslation(String lang, int problemNumber, String json) {
            String fileName = "lang/" + lang + "/p" + problemNumber + ".json";
            responses.put(URI.create(baseUrl + "/" + fileName), json.getBytes(StandardCharsets.UTF_8));
            publishManifest();
        }

        void removeTranslation(String lang, int problemNumber) {
            String fileName = "lang/" + lang + "/p" + problemNumber + ".json";
            responses.remove(URI.create(baseUrl + "/" + fileName));
            hashOverrides.remove(fileName);
            publishManifest();
        }

        void dropBodyWithoutUpdatingManifest(String fileName) {
            responses.remove(URI.create(baseUrl + "/" + fileName));
            hashOverrides.remove(fileName);
            sizeOverrides.remove(fileName);
        }

        void overrideManifestSize(String fileName, long size) {
            sizeOverrides.put(fileName, size);
            publishManifest();
        }

        void replaceManifestWithBytes(byte[] bytes) {
            responses.put(URI.create(baseUrl + "/manifest.json"), bytes);
        }

        void publishManifestInReverseOrder() {
            reverseManifestOrder = true;
            publishManifest();
        }

        int requestsFor(String fileName) {
            return requestCounts.getOrDefault(fileName, 0);
        }

